
/* snippets/active-filters.liquid */

  .active-filters {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-xs) var(--space-sm);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* A small outlined pill, the same rose border as the Filters and SORT pills */
  .active-filters__pill {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    min-block-size: 2.25rem;
    padding-inline: var(--space-md) var(--space-sm);
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    color: var(--color-text);
    font-size: var(--font-size-small);
    text-decoration: none;
    transition: border-color var(--duration-fast) var(--ease-out);
  }

  .active-filters__pill:hover {
    border-color: var(--color-accent);
  }

  .active-filters__pill svg {
    inline-size: 0.625rem;
    block-size: 0.625rem;
    color: var(--color-accent);
  }

  .active-filters__clear {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    text-underline-offset: 0.2em;
  }

/* snippets/article-card.liquid */

  /*
    Figma cards: --color-card, 1px border, radius 25px, padding ~23px, image 232px tall (radius 19px),
    title ~26px in the heading font, meta at the bottom. Featured: 1818 x 373, padding ~27px, image
    958 x 320 on the left, text column with a ~45px gap.
  */
  .article-card {
    position: relative;
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    block-size: 100%;
    padding: var(--space-lg);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
  }

  .article-card__media {
    position: relative;
    overflow: hidden;
    flex: none;
    block-size: 14.5rem; /* 232px */
    border-radius: var(--radius-sm);
    background-color: var(--color-tint-subtle);
  }

  .article-card__media img,
  .article-card__placeholder {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    transition: scale var(--duration-slow) var(--ease-out);
  }

  /*
    Topic on the image: a small pill in the chosen colour scheme (section setting "Topic badge
    colours"): that scheme's background and accent text. Two classes, so these win over the scheme
    class's own text colour.
  */
  .article-card .article-card__topic {
    position: absolute;
    inset: var(--space-sm) auto auto var(--space-sm);
    padding: 0.15em 0.65em;
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    color: var(--color-accent);
    font-size: var(--font-size-body-sm);
    line-height: 1.4;
  }

  /* No image: the topic pill sits above the title, in the text flow */
  .article-card .article-card__topic--inline {
    position: static;
    align-self: flex-start;
    border: 1px solid color-mix(in srgb, var(--color-accent) 30%, transparent);
  }

  .article-card__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--space-md);
  }

  .article-card__title {
    display: -webkit-box;
    overflow: hidden;
    margin: 0;
    font-size: var(--font-size-h3);
    line-height: 1.3;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  .article-card__link {
    color: inherit;
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out);
  }

  /* Hover / keyboard focus: the title turns to the accent colour (Figma hover frames) */
  .article-card:hover .article-card__link,
  .article-card__link:focus-visible {
    color: var(--color-accent);
  }

  /* The whole card is the link: the title link's ::after covers the card */
  .article-card__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
  }

  /* Author on the left, read time on the right, at the bottom of the card */
  .article-card__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm) var(--space-lg);
    margin-block-start: auto;
    font-size: var(--font-size-caption);
  }

  .article-card__author {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
  }

  .article-card__avatar {
    display: grid;
    flex: none;
    place-items: center;
    overflow: hidden;
    inline-size: 2.25rem; /* 36px */
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-tint);
    color: var(--color-accent);
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
  }

  .article-card__avatar img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .article-card__facts {
    display: inline-flex;
    flex-wrap: wrap;
    gap: var(--space-sm) var(--space-lg);
  }

  .article-card__fact {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    font-size: var(--font-size-small);
  }

  .article-card__fact svg {
    flex: none;
    inline-size: 1.25rem;
    block-size: auto;
    color: var(--color-accent);
  }

  /* Hover / keyboard focus: the card stays put; only the photo zooms and the title turns red (Figma) */
  .article-card__link:focus-visible {
    outline: none;
  }

  .article-card:has(.article-card__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-card:hover .article-card__media img,
    .article-card:has(.article-card__link:focus-visible) .article-card__media img {
      scale: 1.06;
    }
  }

  /* ---------- Featured ---------- */
  .article-card--featured .article-card__pill {
    align-self: flex-start;
    padding: 0.3em 1.4em;
    border: 1px solid color-mix(in srgb, var(--color-accent) 40%, transparent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 15%, var(--color-card));
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
  }

  .article-card--featured .article-card__title {
    font-size: var(--font-size-h2);
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  .article-card__excerpt {
    display: -webkit-box;
    overflow: hidden;
    margin: 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
    line-clamp: 3;
  }

  .article-card--featured .article-card__meta {
    font-size: var(--font-size-body);
  }

  .article-card--featured .article-card__avatar {
    inline-size: 2.5rem; /* 40px */
  }

  /*
    42px red glass circle, white arrow at ↗ (it stays ↗ on hover, as in the Figma). Glass = the hero's
    "Liquid Glass Button" look: a see-through red that frosts what's behind it, with the glass
    shadows (outer drop shadow + a white inner rim). The colours are the button colours of the
    scheme chosen in "Arrow button colours"; two classes so they win over the scheme class.
  */
  .article-card .article-card__arrow {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 2.625rem;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-button) 85%, transparent);
    color: var(--color-button-text);
    box-shadow: var(--shadow-button-glass);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .article-card__arrow svg {
    inline-size: 40%;
    block-size: auto;
    transform: rotate(-45deg);
  }

  /* The badge on a card's image: hidden until hover / keyboard focus, then it pops in */
  .article-card__arrow--badge {
    position: absolute;
    inset: var(--space-sm) var(--space-sm) auto auto;
    opacity: 0;
    scale: 0.6;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      scale var(--duration-base) var(--ease-out);
  }

  .article-card:hover .article-card__arrow--badge,
  .article-card:has(.article-card__link:focus-visible) .article-card__arrow--badge {
    opacity: 1;
    scale: 1;
  }

  /* Wide screens: image left (958 of the 1818px card), text right */
  @media (min-width: 1200px) {
    .article-card--featured {
      display: grid;
      grid-template-columns: minmax(0, 958fr) minmax(0, 750fr);
      gap: var(--space-2xl);
      padding: calc(27 / 16 * 1rem);
    }

    /*
      The image fills the card's full height (at least 320px, the Figma's 958 x 320). A fixed 3:1
      shape left it short on laptops, where the narrower text column wraps onto more lines and makes
      the card taller than the image.
    */
    .article-card--featured .article-card__media {
      block-size: auto;
      min-block-size: 20rem;
    }

    .article-card--featured .article-card__media img,
    .article-card--featured .article-card__placeholder {
      position: absolute;
      inset: 0;
    }

    .article-card--featured .article-card__body {
      padding-block: var(--space-xs);
    }

    /* No image: the text uses the full card */
    .article-card--featured.article-card--no-media {
      display: flex;
    }

    /* Read time and date grouped in the middle, the arrow on the far right (Figma) */
    .article-card--featured .article-card__facts {
      margin-inline-start: auto;
    }
  }

/* snippets/article-product-card.liquid */

  /* Figma 1920: card 356 wide, photo on top (radius 19), white panel with a soft shadow; shorter photo
     and tighter text than the Figma (438 tall), so both cards fit the sidebar more easily */
  /* No overflow: hidden here: it would cut off the Add to cart error message under the pill */
  .article-product-card {
    position: relative;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-background);
    box-shadow: var(--shadow-card);
  }

  .article-product-card__media {
    overflow: hidden;
    aspect-ratio: 16 / 9;
    border-radius: var(--radius-sm) var(--radius-sm) 0 0;
    background-color: var(--color-tint-subtle);
  }

  .article-product-card__media img,
  .article-product-card__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    transition: scale var(--duration-slow) var(--ease-out);
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-product-card:hover .article-product-card__media img {
      scale: 1.05;
    }
  }

  .article-product-card__info {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-2xs);
    padding: var(--space-md);
  }

  .article-product-card__info > * {
    margin: 0;
  }

  .article-product-card__title {
    margin: 0;
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    line-height: 1.35;
  }

  .article-product-card__link {
    color: inherit;
    text-decoration: none;
  }

  /* The title link covers the whole card */
  .article-product-card__link::after {
    content: "";
    position: absolute;
    inset: 0;
  }

  .article-product-card:hover .article-product-card__link {
    color: var(--color-accent);
  }

  .article-product-card__detail {
    margin: 0;
    font-size: var(--font-size-body-sm);
    opacity: 0.8;
  }

  .article-product-card__info .price {
    margin-block-start: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-body);
  }

  /* Top right of the photo, above the stretched title link so it gets its own clicks */
  .article-product-card__add {
    position: absolute;
    inset-block-start: var(--space-sm);
    inset-inline-end: var(--space-sm);
    z-index: 1;
  }

/* snippets/article-product-row.liquid */

  /*
    Figma 1920: row 1116 x 187, radius ~19, 1px pale border; photo 141 x 134 (radius ~10) 33px in;
    text column from x+204 (30px after the photo); price and pill on the right.
    Sizes are Figma px x --px (screen-scale) with rem floors, or tokens.
    The rows sit inside .article-body.rte, so the selectors here use two classes to beat its list,
    image and link rules.
  */

  /* The outer box is the size container: the inner grid changes with the row's own width */
  .article-product-row {
    container-type: inline-size;
  }

  .article-product-row__inner {
    position: relative;
    display: grid;
    grid-template-columns: max(6rem, calc(141 * var(--px, 0.0625rem))) minmax(0, 1fr) auto;
    align-items: center;
    gap: max(var(--space-lg), calc(30 * var(--px, 0.0625rem)));
    padding:
      max(var(--space-md), calc(26 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(31 * var(--px, 0.0625rem)))
      max(var(--space-md), calc(26 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(33 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-background);
  }

  .article-product-row .article-product-row__media {
    overflow: hidden;
    aspect-ratio: 141 / 134;
    border-radius: var(--radius-xs);
    background-color: var(--color-tint-subtle);
  }

  .article-product-row .article-product-row__media img,
  .article-product-row .article-product-row__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    border-radius: 0;
    object-fit: cover;
    transition: scale var(--duration-slow) var(--ease-out);
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-product-row:hover .article-product-row__media img {
      scale: 1.05;
    }
  }

  .article-product-row__info {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    max-inline-size: 32rem; /* 507px: the description wraps to 2 lines as in the Figma */
  }

  .article-product-row .article-product-row__info > * {
    margin: 0;
  }

  .article-product-row__vendor {
    color: var(--color-accent);
    font-size: var(--font-size-body-sm);
    line-height: 1.5;
  }

  .article-product-row__title {
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    line-height: 1.5;
  }

  .article-product-row .article-product-row__link {
    color: inherit;
    text-decoration: none;
  }

  /* The title link covers the whole row */
  .article-product-row__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: var(--radius-sm);
  }

  .article-product-row:hover .article-product-row__link {
    color: var(--color-accent);
  }

  /* Two lines at most, cut with "…" */
  .article-product-row__description {
    display: -webkit-box;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    font-size: var(--font-size-caption);
    line-height: 1.8;
    opacity: 0.85;
  }

  /*
    Price and pill: two fixed-width columns (the same on every row), so the prices start at the same
    place and the pills end at the same place. 11rem fits "From $48.00" or "$54.00 $72.00"; 13rem is
    the Figma pill (205px).
  */
  .article-product-row__buy {
    display: grid;
    grid-template-columns: 11rem 13rem;
    align-items: center;
    column-gap: max(var(--space-lg), calc(32 * var(--px, 0.0625rem)));
  }

  .article-product-row__buy .price {
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
  }

  /* Above the stretched title link, so the pill gets its own clicks */
  .article-product-row__add {
    position: relative;
    z-index: 1;
    justify-self: end;
  }

  /* Narrow rows (no design: our choice): photo + text on top, price and pill on one line below */
  @container (max-width: 50rem) {
    .article-product-row__inner {
      grid-template-columns: max(5.5rem, calc(141 * var(--px, 0.0625rem))) minmax(0, 1fr);
    }

    .article-product-row__buy {
      grid-column: 1 / -1;
      grid-template-columns: minmax(0, 1fr) auto;
    }
  }

  /*
    Very narrow rows (320px phones): the price and the pill share a line only when both fit; else the
    pill goes under the price (it sat on top of a long price)
  */
  @container (max-width: 22rem) {
    .article-product-row__buy {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: var(--space-xs) var(--space-sm);
    }
  }

  /* Phones: a smaller "Add to cart" pill and price. Three classes, so they win over quick-add */
  @media (max-width: 749px) {
    .article-product-row .article-product-row__add .quick-add__button {
      block-size: 2.25rem;
      padding-inline: var(--space-sm);
      font-size: 0.6875rem;
    }

    .article-product-row .article-product-row__buy .price {
      font-size: 0.9375rem;
    }

    /* Phone design: vendor, title and price only (no description), small text */
    .article-product-row .article-product-row__description {
      display: none;
    }

    .article-product-row .article-product-row__vendor {
      font-size: 0.6875rem;
    }

    .article-product-row .article-product-row__title {
      font-size: 0.8125rem;
      line-height: 1.4;
    }

    /*
      Phone design: photo | vendor + title | price at the top right with the pill under it. Only when
      the row is 20rem or wider (375px phones and up); a narrower row keeps price and pill below.
    */
    @container (min-width: 20rem) {
      .article-product-row .article-product-row__inner {
        grid-template-columns: 4.5rem minmax(0, 1fr) fit-content(8rem);
        align-items: stretch;
        gap: var(--space-md);
        padding: var(--space-md);
      }

      .article-product-row .article-product-row__media {
        align-self: start;
      }

      .article-product-row .article-product-row__buy {
        display: flex;
        flex-direction: column;
        grid-column: 3;
        align-items: flex-end;
        justify-content: space-between;
        gap: var(--space-sm);
      }

      /* A long price (sale + old price, "From", unit price) wraps inside its 8rem column */
      .article-product-row .article-product-row__buy .price {
        justify-content: flex-end;
        text-align: end;
      }
    }
  }

/* snippets/author-avatar.liquid */

  .author-avatar {
    display: grid;
    flex: none;
    place-items: center;
    overflow: hidden;
    inline-size: 4rem;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 15%, var(--color-background));
    color: var(--color-accent);
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
  }

  .author-avatar img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

/* snippets/breadcrumb.liquid */

  .breadcrumb ol {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Decoration: the empty alt text after the slash keeps screen readers from reading "›" */
  .breadcrumb li + li::before {
    content: "›";
    content: "›" / "";
    margin-inline-end: var(--space-xs);
    color: var(--color-text);
  }

  .breadcrumb a {
    color: var(--color-text);
    text-decoration: none;
  }

  .breadcrumb a:hover {
    text-decoration: underline;
  }

  .breadcrumb [aria-current] {
    color: var(--breadcrumb-current, var(--color-accent));
  }

/* snippets/cart-item.liquid */

  /*
    Figma cart item card: Glass (Light -45deg 80%), fill #FFFFFF1A, drop shadow 0 4px 10px #B9B9B91A.
    No backdrop blur (Frost 4): only the plain page is behind the card. The fill reads
    --color-surface-raised (white on light schemes, a lighter tone on dark ones).
  */
  .cart-item {
    display: grid;
    grid-template-columns: auto 6.125rem minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--space-md) var(--space-lg);
    padding: var(--space-lg) var(--space-xl) var(--space-lg) var(--space-lg);
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-surface-raised) 10%, transparent);
    box-shadow:
      0 4px 10px 0 #b9b9b91a,
      inset 1px 1px 0 #ffffffcc,
      inset -1px -1px 0 #ffffffbd;
    transition: opacity var(--duration-base) var(--ease-out);
  }

  /*
    The label around the box is the click area: 2px more on each side than the 20px box = 24px
    (WCAG target size). The negative margin keeps the layout the same.
  */
  .cart-item__select {
    display: grid;
    padding: 0.125rem;
    margin: -0.125rem;
    cursor: pointer;
  }

  /*
    Figma checkbox: a soft white rounded square; ticked = the accent colour with a white tick. Drawn by
    hand (appearance: none), so two classes, to beat the global input[type="checkbox"] rule.
  */
  .cart-item__select .cart-item__checkbox {
    display: grid;
    place-content: center;
    inline-size: 1.25rem;
    block-size: 1.25rem;
    margin: 0;
    border: 1px solid color-mix(in srgb, var(--color-text) 15%, var(--color-background));
    border-radius: 0.3rem;
    background-color: var(--color-surface-raised);
    cursor: pointer;
    appearance: none;
  }

  .cart-item__select .cart-item__checkbox::after {
    content: "";
    inline-size: 0.35rem;
    block-size: 0.65rem;
    margin-block-start: -0.15rem;
    border: solid #ffffff;
    border-width: 0 2px 2px 0;
    rotate: 45deg;
    opacity: 0;
  }

  .cart-item__select .cart-item__checkbox:checked {
    border-color: var(--color-accent);
    background-color: var(--color-accent);
  }

  .cart-item__select .cart-item__checkbox:checked::after {
    opacity: 1;
  }

  /*
    Without JavaScript: selecting items ("Remove selected") and - / + do nothing, so they are hidden;
    the number field and the Update button still work.
  */
  .no-js .cart-item__select,
  .no-js .cart-item__step {
    display: none;
  }

  .no-js .cart-item {
    grid-template-columns: 6.125rem minmax(0, 1fr) auto;
  }

  .no-js .cart-item__quantity {
    justify-content: center;
  }

  .cart-item__media {
    display: block;
    aspect-ratio: 98 / 122;
    overflow: hidden;
    border-radius: 0.25rem; /* Figma: almost square */
    background-color: var(--color-tint, #f3ede2);
  }

  .cart-item__media .image,
  .cart-item__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  .cart-item__details {
    display: flex;
    flex-direction: column;
    gap: var(--space-2xs);
    min-inline-size: 0;
  }

  .cart-item__details p {
    margin: 0;
  }

  .cart-item__type {
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Figma: body font, ~20px at 1920px */
  .cart-item__title {
    color: var(--color-text);
    font-size: var(--font-size-body-lg);
    line-height: var(--line-height-heading);
    text-decoration: none;
  }

  .cart-item__title:hover {
    text-decoration: underline;
  }

  .cart-item__options {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2xs) var(--space-md);
    margin: 0;
    padding: 0;
    list-style: none;
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-body-sm);
  }

  .cart-item__option {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
  }

  .cart-item__swatch {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    border-radius: 50%;
    background-color: var(--swatch);
    box-shadow: inset 0 0 0 1px #0000001a;
  }

  .cart-item__note,
  .cart-item__unit {
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-small);
  }

  .cart-item__discount {
    color: var(--color-accent);
    font-size: var(--font-size-small);
  }

  .cart-item__price {
    margin-block-start: var(--space-xs);
    font-size: var(--font-size-body-lg);
    font-weight: var(--font-weight-medium);
  }

  .cart-item__compare {
    margin-inline-start: var(--space-xs);
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-body);
    font-weight: normal;
  }

  .cart-item__actions {
    display: flex;
    align-items: center;
    gap: clamp(var(--space-md), 3vw, 2.5rem);
  }

  /*
    The - 1 + pill (Figma: 160 x 50px, same glass as the card, a little brighter). At least 160px, wider
    when a long number needs it (the field grows with --digits), so the number stays in the centre.
  */
  .cart-item__quantity {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-inline-size: 10rem;
    block-size: 3.125rem;
    padding-inline: var(--space-xs);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-surface-raised) 35%, transparent);
    box-shadow:
      0 4px 10px 0 #b9b9b91a,
      inset 1px 1px 0 #ffffffcc,
      inset -1px -1px 0 #ffffffbd;
  }

  .cart-item__step {
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    color: var(--color-text);
    cursor: pointer;
  }

  /* display: block: an inline SVG sits on the text baseline, which pushed the - and + off centre */
  .cart-item__step svg {
    display: block;
    inline-size: 0.9375rem;
    block-size: auto;
  }

  .cart-item__step:hover:not(:disabled) {
    color: var(--color-accent);
  }

  /*
    Figma: at quantity 1 the minus is light grey = disabled (the bin removes a product, not the minus).
    Above 1 it's dark like the plus.
  */
  .cart-item__step:disabled {
    color: color-mix(in srgb, var(--color-text) 30%, var(--color-background));
    cursor: default;
  }

  /*
    Two classes on purpose: the global form rule in critical.css is `input[type="number"]` (element +
    attribute), which beats a single class, so one class alone would keep its border, background,
    padding, 50px height and 100% width. Every property that rule sets is reset here.
  */
  .cart-item__quantity .cart-item__input {
    /*
      As wide as the number: --digits (from Liquid, updated by the script while typing) x 1ch, at
      least 2 digits, + a little room. Same-width digits (tabular-nums), so 1ch = one digit.
    */
    inline-size: calc(max(var(--digits, 1), 2) * 1ch + 0.75ch);
    font-variant-numeric: tabular-nums;
    min-block-size: 0;
    block-size: 100%;
    line-height: 1; /* the number sits on the same centre line as the - and + */
    padding: 0;
    border: 0;
    border-radius: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-h3);
    text-align: center;
    -moz-appearance: textfield;
    appearance: textfield;
  }

  /* Keyboard focus: a ring around the whole pill instead of the field's own outline */
  .cart-item__quantity .cart-item__input:focus-visible {
    outline: none;
  }

  .cart-item__quantity:has(.cart-item__input:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .cart-item__input::-webkit-inner-spin-button,
  .cart-item__input::-webkit-outer-spin-button {
    margin: 0;
    -webkit-appearance: none;
  }

  /* Round white trash button */
  .cart-item__remove {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 3rem;
    block-size: 3rem;
    border-radius: 50%;
    background-color: var(--color-surface-raised);
    box-shadow: 0 4px 10px 0 #b9b9b933;
    color: var(--color-text);
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
  }

  /* Figma: the bin turns brand red with a white icon on hover */
  .cart-item__remove:hover {
    background-color: var(--color-button);
    color: var(--color-button-text);
  }

  .cart-item__remove svg {
    inline-size: 1rem;
    block-size: auto;
  }

  /* A line being updated dims until the new cart arrives */
  .cart-item.is-loading {
    opacity: 0.5;
    pointer-events: none;
  }

  /*
    Phones (Figma mobile): one row per item: box, small photo, text, a small - 1 + pill and the bin.
    Smaller text (type 8px, title 13px, options 10px, price 13px). The - / + stay 24px (target size).
  */
  @media (max-width: 749px) {
    .cart-item {
      grid-template-columns: auto 2.25rem minmax(0, 1fr) auto;
      gap: var(--space-xs);
      padding: var(--space-sm);
      border-radius: 0.75rem;
    }

    .no-js .cart-item {
      grid-template-columns: 2.25rem minmax(0, 1fr) auto;
    }

    .cart-item__select .cart-item__checkbox {
      inline-size: 1rem;
      block-size: 1rem;
      border-radius: 0.25rem;
    }

    /* 16px box + 4px each side = 24px click area */
    .cart-item__select {
      padding: 0.25rem;
      margin: -0.25rem;
    }

    .cart-item__select .cart-item__checkbox::after {
      inline-size: 0.28rem;
      block-size: 0.5rem;
    }

    .cart-item__details {
      gap: 0.125rem;
    }

    .cart-item__type {
      font-size: 0.5rem;
    }

    .cart-item__title,
    .cart-item__price {
      font-size: 0.8125rem;
    }

    .cart-item__options,
    .cart-item__note,
    .cart-item__unit,
    .cart-item__discount {
      font-size: 0.625rem;
    }

    .cart-item__swatch {
      inline-size: 0.5rem;
      block-size: 0.5rem;
    }

    .cart-item__price {
      margin-block-start: 0.125rem;
    }

    .cart-item__compare {
      font-size: 0.6875rem;
    }

    .cart-item__actions {
      gap: var(--space-xs);
    }

    .cart-item__quantity {
      min-inline-size: 4.75rem;
      block-size: 1.75rem;
      padding-inline: 0.125rem;
    }

    .cart-item__step {
      inline-size: 1.5rem;
      block-size: 1.5rem;
    }

    .cart-item__step svg {
      inline-size: 0.625rem;
    }

    .cart-item__quantity .cart-item__input {
      font-size: 0.8125rem;
    }

    .cart-item__remove {
      inline-size: 1.625rem;
      block-size: 1.625rem;
    }

    .cart-item__remove svg {
      inline-size: 0.625rem;
    }
  }

  /*
    Small phones (below 375px, no design): the text column gets too narrow for a long price
    ("Rs. 3,780,000.00" broke inside the number), so - 1 + and the bin go on a second row under the
    text, at the end.
  */
  @media (max-width: 374px) {
    .cart-item {
      grid-template-columns: auto 2.25rem minmax(0, 1fr);
    }

    .cart-item__actions {
      grid-column: 3;
      justify-content: flex-end;
    }

    .no-js .cart-item {
      grid-template-columns: 2.25rem minmax(0, 1fr);
    }

    .no-js .cart-item__actions {
      grid-column: 2;
    }
  }

  /* Never break inside an amount (the body's overflow-wrap: break-word did); the space between the sale
     price and the old price can still wrap */
  .cart-item__price {
    overflow-wrap: normal;
  }

/* snippets/cart-notification.liquid */

  /*
    The card: the theme's light glass (scheme background, soft shadow and rim), 22rem wide, top right
    under the header. Popover resets: the browser centres a popover with a border and padding.
  */
  .cart-notification {
    position: fixed;
    inset: auto;
    inset-block-start: calc(var(--header-space, 6rem) + var(--space-xs));
    inset-inline-end: var(--page-margin, 1rem);
    z-index: 30;
    display: grid;
    gap: var(--space-md);
    inline-size: min(22rem, calc(100vw - var(--page-margin, 1rem) * 2));
    margin: 0;
    padding: var(--space-lg);
    border: 0;
    border-radius: var(--radius-md);
    background-color: var(--color-background);
    box-shadow: 0 12px 40px 0 #0000001f, var(--glass-rim);
    color: var(--color-text);
  }

  /* hidden = off in every browser (also without popovers, where it shows in place, fixed) */
  .cart-notification[hidden] {
    display: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    .cart-notification:not([hidden]) {
      animation: cart-notification-in 0.3s var(--ease-out);
    }
  }

  @keyframes cart-notification-in {
    from {
      opacity: 0;
      translate: 0 -0.75rem;
    }
  }

  .cart-notification__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  .cart-notification p {
    margin: 0;
  }

  .cart-notification__title {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
  }

  /* The gold tick of the cart button, small */
  .cart-notification__check {
    display: grid;
    place-items: center;
    inline-size: 1.25rem;
    block-size: 1.25rem;
    border-radius: 50%;
    background-color: var(--color-accent);
    color: #ffffff;
  }

  .cart-notification__check svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  /* Two classes: the global button[type] rules would win over one class */
  .cart-notification .cart-notification__close {
    display: grid;
    place-items: center;
    inline-size: 2rem;
    block-size: 2rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    color: var(--color-text);
    cursor: pointer;
  }

  .cart-notification .cart-notification__close:hover {
    background-color: color-mix(in srgb, var(--color-text) 8%, transparent);
  }

  .cart-notification__close svg {
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  .cart-notification__item {
    display: grid;
    grid-template-columns: 4.5rem minmax(0, 1fr);
    align-items: center;
    gap: var(--space-md);
  }

  .cart-notification__media {
    display: block;
    aspect-ratio: 4 / 5;
    overflow: hidden;
    border-radius: 0.5rem;
    background-color: var(--color-tint, #f3ede2);
  }

  .cart-notification__media img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .cart-notification__media img[src="data:,"] {
    visibility: hidden;
  }

  .cart-notification__details {
    display: grid;
    gap: 0.125rem;
    min-inline-size: 0;
  }

  .cart-notification__name {
    overflow: hidden;
    color: var(--color-text);
    font-size: var(--font-size-body);
    line-height: var(--line-height-heading);
    text-decoration: none;
    display: -webkit-box;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  .cart-notification__name:hover {
    text-decoration: underline;
  }

  .cart-notification__variant {
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-small);
  }

  .cart-notification__variant:empty {
    display: none;
  }

  .cart-notification__price {
    font-weight: var(--font-weight-medium);
  }

  /* "In your bag: 2" in the accent colour */
  .cart-notification__in-bag {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
  }

  /* "Bag: 5 items   Rs. 21,300.00" on a hairline */
  .cart-notification__bag:not([hidden]) {
    display: flex;
    justify-content: space-between;
    gap: var(--space-md);
    padding-block-start: var(--space-sm);
    border-block-start: 1px solid color-mix(in srgb, var(--color-text) 12%, transparent);
    font-size: var(--font-size-body-sm);
  }

  .cart-notification__total {
    font-weight: var(--font-weight-medium);
    white-space: nowrap;
  }

  .cart-notification__actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: var(--space-sm);
  }

  .cart-notification__checkout-form {
    display: grid;
    margin: 0;
  }

  /* Both buttons the same size; the checkout pill in the accent colour (as on the cart page) */
  .cart-notification .cart-notification__view,
  .cart-notification .cart-notification__checkout {
    min-block-size: 2.75rem;
    padding-inline: var(--space-sm);
    font-size: var(--font-size-small);
    white-space: nowrap;
  }

  .cart-notification .cart-notification__checkout {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    gap: var(--space-xs);
  }

  .cart-notification__checkout svg {
    inline-size: 1em;
    block-size: auto;
  }

  /* Phones: at the bottom of the screen, full width (thumbs reach the buttons) */
  @media (max-width: 749px) {
    .cart-notification {
      inset-block-start: auto;
      inset-block-end: calc(var(--space-sm) + env(safe-area-inset-bottom));
      inset-inline: var(--page-margin, 1rem);
      inline-size: auto;
      padding: var(--space-md);
    }

    @media (prefers-reduced-motion: no-preference) {
      .cart-notification:not([hidden]) {
        animation-name: cart-notification-up;
      }
    }
  }

  @keyframes cart-notification-up {
    from {
      opacity: 0;
      translate: 0 0.75rem;
    }
  }

/* snippets/category-pills.liquid */

  .collection-pills {
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  .collection-pills__list {
    display: flex;
    margin: 0;
    padding: 0.25rem; /* room for the focus ring and shadow inside the scroll box */
    overflow-x: auto;
    list-style: none;
    scrollbar-width: none;
    scroll-snap-type: x proximity;
  }

  /* The side padding is the gap between a divider and the hover glass (Figma ~10px) */
  .collection-pills__list > li {
    position: relative;
    flex: none;
    padding-inline: var(--space-xs);
    scroll-snap-align: start;
  }

  /* Figma: plain text links with a short divider between them */
  .collection-pills__list > li + li::before {
    content: '';
    position: absolute;
    inset-block: 20%;
    inset-inline-start: 0;
    border-inline-start: 1px solid color-mix(in srgb, var(--color-accent) 15%, transparent);
  }

  /*
    A text link (Figma ~50px tall) that becomes a glass pill on hover; the count is the small
    raised red number ("Fragrance 12"). Three layers, back to front: the hover image, the glass
    (::after), the text. The glass is a pseudo-element rather than the link's own background so
    it can sit over the image and frost it.
  */
  .collection-pill {
    position: relative;
    isolation: isolate;
    display: inline-flex;
    align-items: flex-start;
    gap: 0.2em;
    padding: 0.85rem var(--space-lg);
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
    line-height: 1.2;
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .collection-pill::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: inherit;
    background-color: var(--color-glass);
    box-shadow: var(--shadow-header);
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-out);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  /* Hovered pill on top of its neighbours (and the dividers), so nothing covers its image */
  .collection-pill:hover,
  .collection-pill:focus-visible {
    z-index: 1;
  }

  .collection-pill:hover::after,
  .collection-pill:focus-visible::after {
    opacity: 1;
  }

  /* The page you're on: red text (the Figma frame shows no active style; aria-current tells screen readers) */
  .collection-pill--active {
    color: var(--color-accent);
  }

  .collection-pill__count {
    color: var(--color-accent);
    font-size: 0.65em;
    font-variant-numeric: tabular-nums;
  }

  /*
    The hover image rises from behind the pill and grows (Figma hover frames). Only on
    devices with a mouse and room for it: on phones the pills scroll, which would clip it,
    and display: none also stops the lazy image from downloading there.
  */
  .collection-pill__media {
    display: none;
  }

  @media (hover: hover) and (min-width: 750px) {
    .collection-pills__list {
      flex-wrap: wrap;
      overflow: visible; /* a scroll box would clip the image */
    }

    .collection-pill__media {
      position: absolute;
      inset-block-start: 50%;
      inset-inline-start: 50%;
      z-index: -1;
      display: block;
      /* "Pill image size" = the cut-out's height; a rounded photo is a bit smaller */
      inline-size: calc(var(--pill-image-size, 180px) * 0.6);
      block-size: calc(var(--pill-image-size, 180px) * 0.7);
      border-radius: var(--radius-sm);
      overflow: hidden;
      opacity: 0;
      translate: -50% -40%;
      scale: 0.4;
      transform-origin: 50% 100%;
      pointer-events: none;
      transition:
        opacity var(--duration-base) var(--ease-out),
        translate var(--duration-normal) var(--ease-out),
        scale var(--duration-normal) var(--ease-out);
    }

    /* A cut-out PNG: bigger, no rounded box, the bottle stands behind the glass */
    .collection-pill__media--cutout {
      inline-size: calc(var(--pill-image-size, 180px) * 0.85);
      block-size: var(--pill-image-size, 180px);
      border-radius: 0;
    }

    .collection-pill__media img {
      inline-size: 100%;
      block-size: 100%;
      object-fit: cover;
    }

    .collection-pill__media--cutout img {
      object-fit: contain;
    }

    /* "Pill image animation": the start state differs, the end state (below) is shared */
    .collection-pills--image-scale .collection-pill__media {
      translate: -50% -60%; /* already in place, only grows from its centre */
      transform-origin: 50% 50%;
    }

    .collection-pills--image-fade .collection-pill__media {
      translate: -50% -60%;
      scale: 1;
    }

    .collection-pill:hover .collection-pill__media,
    .collection-pill:focus-visible .collection-pill__media {
      opacity: 1;
      translate: -50% -60%;
      scale: 1;
    }
  }

  /* Reduced motion: the image fades in where it ends up, without rising or growing */
  @media (prefers-reduced-motion: reduce) {
    .collection-pill__media {
      translate: -50% -60%;
      scale: 1;
    }
  }

  /*
    Centred (search page): auto margins on the first and last pill, not justify-content: center. A
    centred row that is wider than the screen loses its start (the first pill could not be scrolled to);
    with auto margins a short row is centred and a long row starts at the edge and scrolls.
  */
  .collection-pills--centred .collection-pills__list > li:first-child {
    margin-inline-start: auto;
  }

  .collection-pills--centred .collection-pills__list > li:last-child {
    margin-inline-end: auto;
  }

/* snippets/explore-button.liquid */

  /*
    At rest: a solid accent pill with white text (a circle, ::before, 250% of the width so its radius
    covers the far corner, fills the pale glass pill). On hover it turns into the pale pill at once
    (circle at scale 0, accent text), then the circle grows from the left edge until it is full again
    and the text goes back to white. Meanwhile the paper plane turns to point straight right, flies off,
    then parks: in from outside the bottom left of the button. The animations end on the rest look, so
    mouse-out changes nothing.

    Two classes (.button.explore-button) on purpose: as a submit button (contact form) the element
    also matches critical.css's button[type="submit"] and button[type="submit"]:hover (element +
    attribute), which beat one class. Their hover forced the solid red background, so the pale state
    never showed and the accent-coloured text vanished on red.
  */
  .button.explore-button {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    gap: 0.75rem;
    min-block-size: 3.5rem;
    padding-inline: 2.25rem;
    border-color: var(--color-accent);
    background-color: color-mix(in srgb, var(--color-accent) 14%, var(--color-background));
    box-shadow: var(--glass-shadow), var(--glass-rim);
    color: #ffffff;
  }

  .explore-button::before {
    content: "";
    position: absolute;
    inset-block-start: 50%;
    inset-inline-start: 0;
    z-index: -1;
    inline-size: 250%;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-accent);
    transform: translate(-50%, -50%) scale(1);
  }

  .button.explore-button:hover,
  .button.explore-button:focus-visible {
    background-color: color-mix(in srgb, var(--color-accent) 14%, var(--color-background));
    box-shadow: var(--glass-shadow), var(--glass-rim);
    animation: explore-button-text 0.8s var(--ease-out) 0.25s backwards;
  }

  /*
    The fill waits 0.25s (the plane's turn, see explore-button-plane-out) and starts as the plane starts
    moving. "backwards" holds the "from" look (pale, no fill) during that wait.
  */
  .explore-button:hover::before,
  .explore-button:focus-visible::before {
    animation: explore-button-fill 0.8s var(--ease-out) 0.25s backwards;
  }

  /* Accent text while the pill is pale, white once the fill has passed under it */
  @keyframes explore-button-text {
    from {
      color: var(--color-accent);
    }
  }

  /* From the pale look (no fill) back to the full fill, growing from the left edge */
  @keyframes explore-button-fill {
    from {
      transform: translate(-50%, -50%) scale(0);
    }
  }

  /* Both planes share one grid cell, so the second rests exactly where the first does */
  .explore-button__icon {
    display: grid;
  }

  .explore-button__icon svg {
    display: block;
    grid-area: 1 / 1;
    inline-size: 1.2em;
    block-size: auto;
  }

  /* The parking plane waits outside the bottom-left of the button (Figma position), clipped by overflow: hidden */
  .explore-button__icon svg + svg {
    transform: translate(-2.1em, 2.5em);
  }

  /*
    Plane 1 (0 - 0.6s): turns 35deg (the icon points up-right, so it now points straight right) in
    0.24s, then flies right until the button's edge has cut it off; no fade. The distance is
    --explore-fly: 4em clears the padding of a normal pill; a wide button (the contact form's
    full-width submit) sets a longer one, or plane 1 would stay visible next to plane 2.
    Plane 2 (0.45 - 0.95s): starts parking just before plane 1 is gone, flies in diagonally, overshoots
    a little and settles. Both end where the rest state puts the other one, so mouse-out is invisible.
  */
  .explore-button:hover .explore-button__icon svg:first-child,
  .explore-button:focus-visible .explore-button__icon svg:first-child {
    animation: explore-button-plane-out 0.6s ease-in forwards;
  }

  .explore-button:hover .explore-button__icon svg + svg,
  .explore-button:focus-visible .explore-button__icon svg + svg {
    animation: explore-button-plane-park 0.5s var(--ease-out) 0.45s forwards;
  }

  @keyframes explore-button-plane-out {
    40% {
      transform: rotate(35deg);
    }

    100% {
      transform: translateX(var(--explore-fly, 4em)) rotate(35deg);
    }
  }

  @keyframes explore-button-plane-park {
    70% {
      transform: translate(0.1em, -0.12em);
    }

    100% {
      transform: none;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .explore-button:hover,
    .explore-button:focus-visible,
    .explore-button:hover::before,
    .explore-button:focus-visible::before,
    .explore-button:hover .explore-button__icon svg,
    .explore-button:focus-visible .explore-button__icon svg {
      animation: none;
    }
  }

/* snippets/faq-contact.liquid */

  /*
    Figma 1920 ("Default-1"): ~90px under the questions; card 1418 x 135 centred, fill #fcfafa (accent
    ~2% on white), radius ~24, soft shadow, padding 32 / 49 / 32 / 55; title heading font semibold
    ~32px; line body ~20px; "WRITE MESSAGE" red pill 258 x 50 with a paper plane; "TRACK ORDER"
    glass pill ~185 x 50. The title uses the heading font's own weight (no extra font file).
  */
  .faq-contact {
    margin-block-start: max(var(--space-2xl), calc(90 * var(--px, 0.0625rem)));
  }

  .faq-contact__card {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-lg) var(--space-xl);
    /* Figma 1418px at 1920; never less than 60rem (full width on phones and tablets) */
    inline-size: min(max(calc(1418 * var(--px, 0.0625rem)), 60rem), 100%);
    min-block-size: max(7rem, calc(135 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    margin-inline: auto;
    padding:
      max(var(--space-lg), calc(32 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(49 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(32 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(55 * var(--px, 0.0625rem)));
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-accent) 2%, var(--color-background));
    box-shadow: 0 4px 24px 0 #0000000d;
  }

  /*
    The glass circle, drawn as a soft glow: accent ~7% in the middle fading to nothing at the edge
    (a flat 3% fill with a backdrop blur shows nothing over a plain card: there's nothing behind it
    to blur). The Figma values, for reference: #7d000008 fill, blur 17.9px, 65 x 65, 4px left of the
    card and 72px below its top.
  */
  .faq-contact__card::before {
    content: "";
    position: absolute;
    inset-block-start: calc(72 * var(--px, 0.0625rem));
    inset-inline-start: calc(-4 * var(--px, 0.0625rem));
    inline-size: max(3rem, calc(65 * var(--px, 0.0625rem)));
    block-size: max(3rem, calc(65 * var(--px, 0.0625rem)));
    border-radius: 50%;
    background: radial-gradient(
      circle,
      color-mix(in srgb, var(--color-accent) 7%, transparent) 0%,
      color-mix(in srgb, var(--color-accent) 3%, transparent) 45%,
      #7d000000 72%
    );
    filter: blur(4px);
    pointer-events: none;
  }

  .faq-contact__copy {
    position: relative;
    flex: 1 1 24rem;
  }

  .faq-contact__heading {
    margin: 0;
    font-size: max(1.5rem, calc(32 * var(--px, 0.0625rem)));
    font-weight: var(--font-heading--weight);
    line-height: 1.2;
  }

  .faq-contact__text {
    margin: max(var(--space-xs), calc(12 * var(--px, 0.0625rem))) 0 0;
    font-size: max(0.9375rem, calc(20 * var(--px, 0.0625rem)));
    line-height: 1.5;
  }

  .faq-contact__actions {
    position: relative;
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-md) max(var(--space-md), calc(32 * var(--px, 0.0625rem)));
  }

  /*
    The buttons follow the screen like the rest of the card (the theme's .button has fixed sizes):
    Figma 50px tall, 35px side padding, ~16.5px lettering at 1920.
  */
  .faq-contact .faq-contact__button,
  .faq-contact .faq-contact__second {
    min-block-size: max(2.75rem, calc(50 * var(--px, 0.0625rem)));
    padding-inline: max(1.25rem, calc(35 * var(--px, 0.0625rem)));
    font-size: max(var(--font-size-caption), calc(16.5 * var(--px, 0.0625rem)));
  }

  .faq-contact__icon {
    display: inline-flex;
  }

  .faq-contact__icon svg {
    inline-size: max(1.125rem, calc(19 * var(--px, 0.0625rem)));
    block-size: auto;
  }

  /* TRACK ORDER: the glass pill (white, the glass shadows, no red border) */
  .faq-contact__second {
    border-color: transparent;
    box-shadow: var(--shadow-header);
  }

  /* Tinted (returns): pale accent fill and border, no glow circle, no shadow */
  .faq-contact--tinted .faq-contact__card {
    border: 1px solid color-mix(in srgb, var(--color-accent) 15%, transparent);
    background-color: color-mix(in srgb, var(--color-accent) 5%, var(--color-background));
    box-shadow: none;
  }

  .faq-contact--tinted .faq-contact__card::before {
    content: none;
  }

  @media (max-width: 749px) {
    .faq-contact {
      margin-block-start: var(--space-xl);
    }

    .faq-contact__card {
      padding: var(--space-md);
    }

    .faq-contact__heading {
      font-size: 1.125rem;
    }

    .faq-contact__text {
      font-size: var(--font-size-caption);
    }

    .faq-contact__actions {
      gap: var(--space-sm);
    }

    .faq-contact .faq-contact__button,
    .faq-contact .faq-contact__second {
      min-block-size: 2.75rem;
      padding-inline: var(--space-md);
    }

    .faq-contact--glass .faq-contact__heading {
      font-size: 0.9375rem;
    }

    .faq-contact--glass .faq-contact__text {
      font-size: 0.75rem;
    }

    .faq-contact--glass .faq-contact__actions {
      justify-content: flex-end;
      inline-size: 100%;
    }

    .faq-contact--glass .faq-contact__actions .faq-contact__button,
    .faq-contact--glass .faq-contact__actions .faq-contact__second {
      min-block-size: 2.25rem;
      padding-inline: var(--space-sm);
      font-size: 0.6875rem;
    }

    /*
      Phones, tinted card (returns): the button takes the full width (easy to tap). The FAQ's glass
      card keeps its two buttons side by side, as in its phone export (Variant10).
    */
    .faq-contact--tinted .faq-contact__actions {
      inline-size: 100%;
    }

    .faq-contact--tinted .faq-contact__actions > * {
      flex: 1 1 100%;
    }
  }

/* snippets/filter-drawer.liquid */

  /* The button and the dialog sit in the toolbar's flow as if the wrapper weren't there */
  .filter-drawer {
    display: contents;
  }

  /* Without JavaScript the drawer can't open, so the button is hidden until the element is defined */
  filter-drawer:not(:defined) .filter-drawer__toggle {
    display: none;
  }

  /* Figma "Filters": a 50px outlined pill (same rose border as SORT), red icon, then the label */
  .filter-drawer__toggle {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--space-xs);
    min-block-size: 3.125rem;
    padding-inline: var(--space-lg);
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    color: var(--color-text);
    font: inherit;
    font-size: var(--font-size-body-sm);
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--ease-out);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .filter-drawer__toggle:hover {
    background-color: var(--color-glass-strong);
  }

  .filter-drawer__toggle svg {
    inline-size: 1.5rem;
    block-size: 1.5rem;
    color: var(--color-accent);
  }

  /*
    The number of applied choices: the small raised red number, like the pill counts. It sits in a
    wrapper span (swapped after each load), so it's lifted with translate rather than flex alignment.
  */
  .filter-drawer__count {
    display: inline-block;
    translate: 0 -0.6em;
    color: var(--color-accent);
    font-size: 0.65em;
    font-variant-numeric: tabular-nums;
  }

  /*
    The panel (Figma 332 x full height, widened to 384px on 2026-11-05 so long filter names and the
    brand search have room): a soft off-white sheet from the left, rounded on the right, 34px side
    padding. The background mixes 2% of the text colour into the scheme background (#faf8f8).
    overflow: hidden: only the body scrolls (a <dialog> scrolls itself by default, which gave two
    scrollbars).
  */
  .filter-drawer__dialog {
    inset-block: 0;
    inset-inline: 0 auto;
    overflow: hidden;
    inline-size: min(24rem, calc(100vw - 3rem));
    max-inline-size: none;
    block-size: 100dvh;
    max-block-size: none;
    margin: 0;
    padding: 0;
    border: 0;
    border-start-end-radius: var(--radius-lg);
    border-end-end-radius: var(--radius-lg);
    background-color: color-mix(in srgb, var(--color-text) 2%, var(--color-background));
    box-shadow: var(--shadow-header);
    color: var(--color-text);
  }

  .filter-drawer__dialog::backdrop {
    background-color: #00000040;
  }

  html:has(.filter-drawer__dialog[open]) {
    overflow: hidden;
  }

  .animations-on .filter-drawer__dialog {
    transition:
      translate var(--duration-base) var(--ease-out),
      display var(--duration-base) allow-discrete,
      overlay var(--duration-base) allow-discrete;
    translate: -100% 0;
  }

  .animations-on .filter-drawer__dialog[open] {
    translate: 0 0;
  }

  @starting-style {
    .animations-on .filter-drawer__dialog[open] {
      translate: -100% 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .animations-on .filter-drawer__dialog {
      transition: none;
    }
  }

  /*
    Head and foot stay put, the groups in between scroll. minmax(0, 1fr), not 1fr: a plain 1fr row is
    never smaller than its content, so the body grew past the screen and the dialog scrolled instead.
  */
  .filter-drawer__form {
    display: grid;
    grid-template-rows: auto minmax(0, 1fr) auto;
    block-size: 100%;
    margin: 0;
  }

  .filter-drawer__head {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    padding: var(--space-lg) var(--space-xl) var(--space-sm);
  }

  .filter-drawer__title {
    flex: 1;
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-h3);
  }

  .filter-drawer__reset {
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    text-decoration: none;
  }

  .filter-drawer__reset:hover {
    text-decoration: underline;
    text-underline-offset: 0.2em;
  }

  /* A 38px white circle with the × */
  .filter-drawer__close {
    display: inline-grid;
    flex: none;
    place-items: center;
    inline-size: 2.375rem;
    block-size: 2.375rem;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background-color: var(--color-background); /* white on the light panel; follows a red or dark scheme */
    box-shadow: var(--shadow-card);
    color: var(--color-text);
    cursor: pointer;
  }

  .filter-drawer__close svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  /*
    The scrolling middle. A thin rose scrollbar instead of the grey system one: scrollbar-width / -color
    for Chrome, Edge and Firefox; the ::-webkit-scrollbar rules for Safari.
  */
  .filter-drawer__body {
    overflow-y: auto;
    padding-inline: var(--space-xl);
    overscroll-behavior: contain;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--color-accent) 30%, transparent) transparent;
  }

  .filter-drawer__body::-webkit-scrollbar {
    inline-size: 0.375rem;
  }

  .filter-drawer__body::-webkit-scrollbar-track {
    background: transparent;
  }

  .filter-drawer__body::-webkit-scrollbar-thumb {
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 30%, transparent);
  }

  /* "Makeup filters": small grey text between two thin rose lines */
  .filter-drawer__divider {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    margin: var(--space-md) 0 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
    white-space: nowrap;
  }

  .filter-drawer__divider::before,
  .filter-drawer__divider::after {
    content: '';
    flex: 1;
    block-size: 1px;
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
  }

  .filter-drawer__foot {
    display: flex;
    justify-content: center;
    padding: var(--space-md) var(--space-xl) var(--space-lg);
  }

  /* Figma: 274 x 50 red pill, white uppercase, soft shadow */
  .filter-drawer__apply {
    inline-size: 100%;
  }

/* snippets/filter-group.liquid */

  .filter-group {
    border-block-end: 1px solid color-mix(in srgb, var(--color-accent) 12%, transparent);
  }

  /* Figma: red uppercase spaced label, + / − on the right, 48px rows */
  .filter-group__summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    min-block-size: 3rem;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    cursor: pointer;
    list-style: none;
  }

  /*
    Keyboard focus ring INSIDE the heading row: an outside ring was cut at the bottom (the open content
    below sits on its own layer while it animates) and, on the first heading, at the top (the drawer's
    scroll area). 8px of side room (negative margin + padding) keeps the text where it was and off the ring.
  */
  .filter-group__summary {
    margin-inline: calc(var(--space-xs) * -1);
    padding-inline: var(--space-xs);
    border-radius: var(--radius-focus, 0.5rem);
  }

  .filter-group__summary:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  .filter-group__summary::-webkit-details-marker {
    display: none;
  }

  .filter-group__plus,
  .filter-group__minus {
    display: inline-grid;
    color: var(--color-text);
  }

  .filter-group__summary svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .filter-group[open] .filter-group__plus,
  .filter-group:not([open]) .filter-group__minus {
    display: none;
  }

  /*
    Smooth open / close (only with the "Enable animations" setting, and not for reduced motion).
    ::details-content is the part of a <details> that hides; interpolate-size lets its height animate
    to and from "auto"; content-visibility (allow-discrete) keeps it visible until the closing slide ends.
    Browsers without ::details-content simply open and close at once.
  */
  /*
    6px of room on the sides of the open content: its overflow is clipped while it animates, which cut off
    focus rings drawn outside a control (checkboxes, price fields, chips). The negative margin keeps the
    controls where they were.
  */
  .filter-group::details-content {
    margin-inline: -0.375rem;
    padding-inline: 0.375rem;
  }

  @media (prefers-reduced-motion: no-preference) {
    .animations-on .filter-group {
      interpolate-size: allow-keywords;
    }

    .animations-on .filter-group::details-content {
      block-size: 0;
      overflow: clip;
      opacity: 0;
      transition:
        block-size var(--duration-base) var(--ease-out),
        opacity var(--duration-base) var(--ease-out),
        content-visibility var(--duration-base) allow-discrete;
    }

    .animations-on .filter-group[open]::details-content {
      block-size: auto;
      opacity: 1;
    }
  }

  .filter-group__fieldset {
    display: grid;
    gap: var(--space-sm);
    margin: 0;
    padding: 0 0 var(--space-lg);
    border: 0;
  }

  /* Brand search: a pill with the magnifier on the right */
  .filter-group__search {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
    padding-inline: var(--space-md);
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
  }

  /*
    Focus ring on the pill's own edge (inset), not outside it: the group's open / close animation clips
    its content (overflow: clip on ::details-content), which cut off an outside ring at the left and right.
  */
  .filter-group__search:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: -2px;
  }

  /* Two classes: critical.css styles input[type="search"] (class + element beats one class) */
  .filter-group__search input[type='search'] {
    flex: 1;
    min-inline-size: 0;
    min-block-size: 2.5rem;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    font-size: var(--font-size-caption);
  }

  .filter-group__search input:focus-visible {
    outline: none;
  }

  /* No browser × in the box (not in the design) */
  .filter-group__search input::-webkit-search-cancel-button {
    -webkit-appearance: none;
    appearance: none;
  }

  .filter-group__search svg {
    flex: none;
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  .filter-group__options {
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .filter-group__item[hidden] {
    display: none;
  }

  /* A row: checkbox, (swatch), label, count on the right. 40px rows (Figma) */
  .filter-option {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    min-block-size: 2.5rem;
    margin: 0;
    font-size: var(--font-size-caption);
    font-weight: 400;
    cursor: pointer;
  }

  .filter-option input {
    flex: none;
    inline-size: 1.0625rem;
    block-size: 1.0625rem;
    margin: 0;
    accent-color: var(--color-accent);
  }

  /* A ring 2px outside the box, so it reads as a ring and not a thicker border (room: see ::details-content) */
  .filter-option input:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .filter-option:has(input:disabled) {
    opacity: 0.45;
    cursor: not-allowed;
  }

  .filter-option__label {
    flex: 1;
    min-inline-size: 0;
  }

  .filter-option__count {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-variant-numeric: tabular-nums;
  }

  /* Star rows (Figma: ~17px gold stars, the rest pale) */
  .filter-option__stars {
    display: flex;
    flex: 1;
    gap: var(--space-2xs);
  }

  .filter-option__star {
    display: inline-grid;
    color: var(--color-rating);
  }

  .filter-option__star--empty {
    color: color-mix(in srgb, var(--color-rating) 20%, var(--color-background));
  }

  .filter-option__star svg {
    inline-size: 1.0625rem;
    block-size: 1.0625rem;
  }

  .filter-option__swatch {
    flex: none;
    inline-size: 1.1875rem;
    block-size: 1.1875rem;
    border: 1px solid color-mix(in srgb, var(--color-text) 12%, transparent);
    border-radius: var(--radius-pill);
    background: var(--swatch);
  }

  /*
    Chips and tiles: the whole chip is the label; the checkbox is hidden but still focusable, so a ticked
    chip is a real checked checkbox for keyboards and screen readers. Selected = red border and tint.
  */
  .filter-group__options--chips {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
  }

  .filter-group__options--tiles {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-xs);
  }

  .filter-option--chips,
  .filter-option--tiles {
    position: relative;
    gap: var(--space-xs);
    padding: var(--space-xs) var(--space-md);
    border: 1px solid color-mix(in srgb, var(--color-accent) 12%, transparent);
    border-radius: var(--radius-xs);
    background-color: color-mix(in srgb, var(--color-text) 3%, var(--color-background));
    transition:
      border-color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
  }

  .filter-option--tiles {
    flex-direction: column;
    justify-content: center;
    min-block-size: 4.875rem; /* 78px, Figma */
    text-align: center;
  }

  .filter-option--chips input,
  .filter-option--tiles input {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    opacity: 0;
    cursor: pointer;
  }

  .filter-option--chips:has(input:checked),
  .filter-option--tiles:has(input:checked) {
    border-color: var(--color-accent);
    background-color: color-mix(in srgb, var(--color-accent) 8%, var(--color-background));
  }

  .filter-option--chips:has(input:focus-visible),
  .filter-option--tiles:has(input:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .filter-option--chips .filter-option__label,
  .filter-option--tiles .filter-option__label {
    flex: none;
  }

  .filter-option--chips .filter-option__count,
  .filter-option--tiles .filter-option__count {
    display: none; /* the Figma chips and tiles show no count; it stays in the DOM for the live update */
  }

  .filter-option__icon {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    object-fit: contain;
  }

  /* Price: a 5px track, red between the two thumbs, then the From / To pills */
  .filter-price {
    display: grid;
    gap: var(--space-md);
  }

  .filter-price__slider {
    position: relative;
    block-size: 1.125rem;
  }

  .filter-price__slider::before {
    content: '';
    position: absolute;
    inset-inline: 0;
    inset-block-start: 50%;
    block-size: 0.3125rem;
    border-radius: var(--radius-pill);
    background: linear-gradient(
      to right,
      color-mix(in srgb, var(--color-accent) 12%, var(--color-background)) var(--from),
      var(--color-accent) var(--from) var(--to),
      color-mix(in srgb, var(--color-accent) 12%, var(--color-background)) var(--to)
    );
    translate: 0 -50%;
  }

  /* Two range inputs on top of each other; only their thumbs take clicks */
  .filter-price__slider input {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    margin: 0;
    background: none;
    pointer-events: none;
    -webkit-appearance: none;
    appearance: none;
  }

  .filter-price__slider input::-webkit-slider-runnable-track {
    background: none;
  }

  .filter-price__slider input::-webkit-slider-thumb {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    border: 2px solid var(--color-background);
    border-radius: var(--radius-pill);
    background: var(--color-accent);
    box-shadow: 0 1px 3px #00000033;
    cursor: pointer;
    pointer-events: auto;
    -webkit-appearance: none;
    appearance: none;
  }

  .filter-price__slider input::-moz-range-thumb {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    border: 2px solid var(--color-background);
    border-radius: var(--radius-pill);
    background: var(--color-accent);
    box-shadow: 0 1px 3px #00000033;
    cursor: pointer;
    pointer-events: auto;
  }

  .filter-price__slider input:focus-visible {
    outline: none;
  }

  .filter-price__slider input:focus-visible::-webkit-slider-thumb {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .filter-price__boxes {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
  }

  .filter-price__box {
    display: flex;
    flex: 1;
    align-items: center;
    gap: var(--space-2xs);
    margin: 0;
    padding-inline: var(--space-sm);
    border: 1px solid color-mix(in srgb, var(--color-accent) 12%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    font-size: var(--font-size-small);
    font-weight: 400;
  }

  .filter-price__box:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  /* Two classes: critical.css styles input[type="number"] */
  .filter-price__box input[type='number'] {
    inline-size: 100%;
    min-block-size: 2rem;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    font-size: var(--font-size-small);
  }

  .filter-price__box input:focus-visible {
    outline: none;
  }

  .filter-price__dash {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

/* snippets/gift-card-recipient.liquid */

  .gift-card-recipient {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  .gift-card-recipient__toggle {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    cursor: pointer;
  }

  /* Two classes: the global input[type="checkbox"] rule in critical.css (1.25rem) must not win */
  .gift-card-recipient .gift-card-recipient__checkbox {
    inline-size: 1.125rem;
    block-size: 1.125rem;
    accent-color: var(--color-accent);
  }

  .gift-card-recipient__fields {
    display: grid;
    gap: var(--space-md);
  }

  /* With JavaScript the fields only show once the box is ticked */
  gift-card-recipient.is-enhanced:not(:has([data-recipient-toggle]:checked)) .gift-card-recipient__fields {
    display: none;
  }

  .gift-card-recipient__field {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
  }

  .gift-card-recipient__field label {
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .gift-card-recipient__hint {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
  }

/* snippets/header-drawer.liquid */

  /*
    Shown only in the header's menu-button layout: header.liquid sets --drawer-display: contents there
    (phones, and tablets per the "Show the menu button below" setting). Elsewhere the full menu is in the pill.
  */
  .header-drawer {
    display: var(--drawer-display, none);
  }

  /*
    No JavaScript: the <noscript> menu (see the markup) takes the button's place in the bar's grid
    (column 3) and opens a panel under the pill, with every level as plain, indented links
  */
  @media (scripting: none) {
    .header-drawer > .header-drawer__toggle {
      display: none;
    }

    .header-drawer noscript {
      display: contents;
    }

    .header-drawer__fallback {
      grid-column: 3;
      grid-row: 1;
    }

    .header-drawer__fallback > summary {
      list-style: none;
      cursor: pointer;
    }

    .header-drawer__fallback > summary::-webkit-details-marker {
      display: none;
    }

    .header-drawer__fallback-panel {
      position: absolute;
      inset-block-start: calc(100% + var(--space-sm));
      inset-inline: 0;
      z-index: 2;
      max-block-size: 70svh;
      overflow-y: auto;
      padding: var(--space-md) var(--space-lg);
      border-radius: var(--radius-lg);
      background-color: var(--color-background);
      box-shadow: var(--shadow-header);
      color: var(--color-text);
    }

    .header-drawer__fallback-panel ul {
      margin: 0;
      padding: 0;
      list-style: none;
    }

    .header-drawer__fallback-panel ul ul {
      padding-inline-start: var(--space-md);
    }

    .header-drawer__fallback-panel a {
      display: block;
      padding-block: var(--space-xs);
      color: inherit;
      text-decoration: none;
    }
  }

  /*
    The drawer (Figma: 267px of a 375px screen, #FAF8F8, soft grey shadow, 25px corners on the left).
    Colours come from the header setting "Menu drawer color scheme" (the color-* class on the dialog):
    - --drawer-surface: the panel, the scheme background with 2% of its text colour (a slightly deeper
      tone, so the round buttons in the plain background colour stand out, like the Figma's white
      buttons on #FAF8F8; on a dark scheme it works the other way round)
    - --drawer-text: the scheme's text colour; hover / current link: the scheme's accent
    The header's sticky wrapper turns off clicks (pointer-events: none) and the dialog would inherit that
    even in the top layer, so turn them back on.
    Two classes (.header .header-drawer__dialog), so the background beats the color-* class's own paint.
  */
  .header .header-drawer__dialog {
    --drawer-text: var(--color-text);
    --drawer-surface: color-mix(in srgb, var(--color-text) 2%, var(--color-background));
    --drawer-shadow: 0 4px 15px #b9b9b940;
    inset-block: 0;
    inset-inline: auto 0;
    /* 85% of the screen (≈ 320px at 375px; wider than the Figma 267px, for the second-level cards), at most 352px */
    inline-size: min(22rem, 85vw);
    min-inline-size: 16rem;
    max-inline-size: none;
    block-size: 100dvh;
    max-block-size: none;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 25px 0 0 25px;
    background-color: var(--drawer-surface);
    box-shadow: var(--drawer-shadow);
    color: var(--drawer-text);
    pointer-events: auto;
  }

  .header-drawer__dialog::backdrop {
    background-color: #00000040;
  }

  /* The page behind doesn't scroll while the drawer is open */
  html:has(.header-drawer__dialog[open]) {
    overflow: hidden;
  }

  /* Slide in from the right (only when the "Enable animations" setting is on) */
  .animations-on .header-drawer__dialog {
    transition:
      translate var(--duration-base) var(--ease-out),
      display var(--duration-base) allow-discrete,
      overlay var(--duration-base) allow-discrete;
    translate: 100% 0;
  }

  .animations-on .header-drawer__dialog[open] {
    translate: 0 0;
  }

  @starting-style {
    .animations-on .header-drawer__dialog[open] {
      translate: 100% 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .animations-on .header-drawer__dialog {
      transition: none;
    }
  }

  /* Head, links (take the rest and scroll if needed), tools at the bottom */
  .header-drawer__panel {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    block-size: 100%;
    padding: var(--space-lg) var(--space-lg) var(--space-xl);
  }

  /* Top row: the logo on the left, the close button on the right */
  .header-drawer__head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  /*
    Its own class, not .header__logo: on a transparent header at rest the bar fades .header__logo out, and that
    rule (many classes long) also hid this copy. The image and text inside keep their .header__logo-* classes.
  */
  .header-drawer__logo {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    min-inline-size: 0;
    color: var(--drawer-text);
    text-decoration: none;
  }

  .header .header-drawer__logo .header__logo-text {
    color: var(--drawer-text);
    font-size: calc(1.75rem * var(--logo-text-scale, 1));
  }

  .header .header-drawer__logo .header__logo-image {
    inline-size: auto;
    max-inline-size: var(--logo-width);
    block-size: 1.625rem;
  }

  /* Close (Figma: a 38px white circle = the scheme's background on the deeper drawer surface) */
  .header-drawer__close {
    display: inline-grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: 2.375rem;
    block-size: 2.375rem;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: var(--color-background);
    color: var(--drawer-text);
    cursor: pointer;
  }

  .header-drawer__close svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    transition: rotate var(--duration-base) var(--ease-out);
  }

  /* The X turns a quarter on hover / keyboard focus, and spins in once when the drawer opens */
  .header-drawer__close:hover,
  .header-drawer__close:focus-visible {
    color: var(--color-accent);
  }

  .header-drawer__close:hover svg,
  .header-drawer__close:focus-visible svg {
    rotate: 90deg;
  }

  @media (prefers-reduced-motion: no-preference) {
    .animations-on .header-drawer__dialog[open] .header-drawer__close svg {
      animation: header-drawer-close-in 0.5s var(--ease-out) 0.1s both;
    }
  }

  @keyframes header-drawer-close-in {
    from {
      rotate: -180deg;
      opacity: 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .header-drawer__close svg {
      transition: none;
    }
  }

  /* The list area; a second-level panel is placed over it (position: relative) */
  .header-drawer__nav {
    position: relative;
    flex: 1;
    min-block-size: 0;
    overflow-y: auto;
  }

  .header-drawer__list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Top-level links (Figma: Satoshi Medium 14.69px / 20px, letter-spacing 12%, uppercase, #1F1F1F, no lines) */
  .header-drawer__link {
    display: flex;
    align-items: center;
    justify-content: space-between;
    inline-size: 100%;
    min-block-size: 3.25rem;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--drawer-text);
    font-family: var(--font-body--family);
    font-size: 0.918rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.25rem;
    letter-spacing: 0.12em;
    text-align: start;
    text-decoration: none;
    text-transform: uppercase;
    cursor: pointer;
  }

  .header-drawer__link:hover,
  .header-drawer__link:focus-visible,
  .header-drawer__link--active {
    color: var(--color-accent);
  }

  /*
    The desktop menu's hand-drawn underline (--nav-underline, set on the header) under the current page's
    link, and on hover / keyboard focus. Same mask technique as .menu__link::after in header-menu.liquid.
  */
  .header-drawer__link {
    position: relative;
  }

  .header-drawer__link::after {
    content: '';
    position: absolute;
    inset-inline-start: 0;
    inset-block-end: 0.35rem;
    inline-size: 4rem;
    aspect-ratio: 97 / 16;
    background-color: currentcolor;
    mask: var(--nav-underline) left center / contain no-repeat;
    pointer-events: none;
    opacity: 0;
    transform: translateY(0.375rem);
    transition:
      opacity var(--duration-base) var(--ease-out),
      transform var(--duration-base) var(--ease-out);
  }

  .header-drawer__link:hover::after,
  .header-drawer__link:focus-visible::after,
  .header-drawer__link--active::after {
    opacity: 1;
    transform: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .header-drawer__link::after {
      transition: none;
    }
  }

  /* The chevron icon points down: turned to point right (next level) or left (Back) */
  .header-drawer__chevron {
    display: inline-flex;
    rotate: -90deg;
  }

  .header-drawer__chevron--back {
    rotate: 90deg;
  }

  .header-drawer__chevron svg {
    inline-size: 0.75rem;
    block-size: auto;
  }

  /*
    Second level: covers the list area and scrolls on its own (Figma: a thin red scrollbar). Slides in from the
    right when it opens (animations on, no reduced motion).
  */
  .header-drawer__sub {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid;
    align-content: start;
    gap: var(--space-2xs);
    overflow-y: auto;
    padding-inline-end: var(--space-md); /* room between the cards and the scrollbar */
    background-color: var(--drawer-surface);
    scrollbar-color: color-mix(in srgb, var(--color-accent) 50%, transparent) transparent;
    scrollbar-width: thin;
  }

  .header-drawer__sub[hidden] {
    display: none;
  }

  .header-drawer__nav:has(.header-drawer__sub:not([hidden])) {
    overflow: hidden;
  }

  @media (prefers-reduced-motion: no-preference) {
    .animations-on .header-drawer__sub:not([hidden]) {
      animation: header-drawer-sub-in var(--duration-base) var(--ease-out);
    }
  }

  @keyframes header-drawer-sub-in {
    from {
      translate: 1.5rem 0;
      opacity: 0;
    }
  }

  /* "< Back" (Figma: small uppercase, wide letter spacing) */
  .header-drawer__back {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    justify-self: start;
    min-block-size: 2.75rem;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--drawer-text);
    font-family: var(--font-body--family);
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.15em;
    text-transform: uppercase;
    cursor: pointer;
  }

  .header-drawer__back:is(:hover, :focus-visible) {
    color: var(--color-accent);
  }

  /*
    The desktop mega panel inside the drawer: no dropdown box (static, no shadow or padding), and the card row
    becomes one column (all cards visible, no slider arrows).
  */
  .header-drawer__sub .menu__panel {
    position: static;
    inline-size: auto;
    gap: var(--space-md);
    padding: 0;
    border-radius: 0;
    background: none;
    box-shadow: none;
    color: var(--drawer-text);
    translate: none;
  }

  /* "Shop by category" on its own line, "Shop all" under it at the end (the drawer is too narrow for one row) */
  .header-drawer__sub .menu__panel-header {
    flex-direction: column;
    align-items: stretch;
    gap: 0;
  }

  .header-drawer__sub .menu__panel-actions {
    display: flex;
    align-items: center;
    justify-content: end;
  }

  .header-drawer__sub .menu__panel-title {
    color: var(--color-accent);
  }

  .header-drawer__sub .menu__panel-all {
    color: color-mix(in srgb, var(--drawer-text) 50%, transparent);
    font-size: 0.75rem;
  }

  .header-drawer__sub .menu__cards {
    grid-auto-flow: row;
    grid-auto-columns: auto;
    gap: var(--space-lg);
    padding-block-end: 1.25rem;
    overflow: visible;
  }

  .header-drawer__sub .menu__card-image-link {
    margin-block-end: 0;
  }

  .header-drawer__sub .menu__card-title {
    font-size: 0.875rem;
  }

  .header-drawer__sub .menu__card-text {
    color: var(--drawer-text);
  }

  .header-drawer__sub .menu__slider-buttons {
    display: none;
  }

  /* Bottom: a hairline, then the round buttons (search, cart) in a row from the start. The account button is in the header bar. */
  .header-drawer__tools {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-md);
    padding-block-start: var(--space-md);
    border-block-start: 1px solid color-mix(in srgb, var(--drawer-text) 10%, transparent);
  }

  .header-drawer__icons {
    display: flex;
    justify-content: flex-start;
    gap: var(--space-md);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Round buttons in the scheme's background colour with the drawer's soft shadow (the cart link also carries .header__icon-button) */
  .header .header-drawer__icon {
    position: relative;
    display: inline-grid;
    place-items: center;
    inline-size: 2.5rem;
    block-size: 2.5rem;
    padding: 0;
    border-radius: 50%;
    background-color: var(--color-background);
    box-shadow: var(--drawer-shadow);
    color: var(--drawer-text);
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .header .header-drawer__icon:is(:hover, :focus-visible) {
    background-color: var(--color-background);
    color: var(--color-accent);
  }

  .header-drawer__icon svg {
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  /* Small phones (320-359px): a slightly wider drawer, tighter sides, no gap between the three parts */
  @media (max-width: 359px) {
    .header .header-drawer__dialog {
      min-inline-size: 18rem;
    }

    .header-drawer__panel {
      gap: 0;
      padding-inline: 1.125rem;
    }
  }

/* snippets/header-menu.liquid */

  .menu {
    display: flex;
    align-items: center;
    gap: var(--space-xl);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Top-level menu links (Figma: Satoshi Medium 16.54px, line-height 100%, letter-spacing 12%, uppercase) */
  .menu__link {
    position: relative;
    display: inline-flex;
    align-items: center;
    min-block-size: 1.5rem;
    color: var(--color-text);
    font-family: var(--font-body--family);
    font-size: 1.0338rem;
    font-weight: var(--font-weight-medium);
    line-height: 1;
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
    text-decoration: none;
    cursor: pointer;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .menu__link:hover,
  .menu__link:focus-visible,
  .menu__link--active,
  .menu__dropdown[open] > .menu__link {
    color: var(--color-accent);
  }

  /*
    Focus ring: a rounded box with room around the word and its brush underline (the global ring sits
    3px from the text box, which cut through the underline and had square corners).
  */
  .menu__link:focus-visible {
    outline-offset: 0.5rem;
    border-radius: var(--radius-focus, 0.5rem);
  }

  /*
    Hand-drawn underline from the Figma, drawn in the current text colour through a CSS mask.
    --nav-underline is set on the header, because this CSS block can't use Liquid (asset_url).
    One size for every link (the SVG's own proportions, 97:16: "contain", never stretched to the word).
    It starts just before the word's first letter and runs on past its end (Figma: "FAQ" with the brush
    stroke from the F). On hover and keyboard focus it fades up into place from a little below; it stays
    on the current page's link and an open dropdown; with reduced motion it simply appears.
  */
  .menu__link::after {
    content: '';
    position: absolute;
    inset-inline-start: 0em;
    inset-block-start: calc(100% + 0.2rem);
    inline-size: 4.5rem;
    aspect-ratio: 97 / 16;
    background-color: currentcolor;
    mask: var(--nav-underline) left center / contain no-repeat;
    pointer-events: none;
    opacity: 0;
    transform: translateY(0.5rem);
    transition:
      opacity var(--duration-base) var(--ease-out),
      transform var(--duration-base) var(--ease-out);
  }

  .menu__link:hover::after,
  .menu__link:focus-visible::after,
  .menu__link--active::after,
  .menu__dropdown[open] > .menu__link::after {
    opacity: 1;
    transform: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .menu__link::after {
      transition: none;
    }
  }

  /* Remove the browser's default triangle on <summary> */
  summary.menu__link {
    list-style: none;
  }

  summary.menu__link::-webkit-details-marker {
    display: none;
  }

  /* The mega panel spans the whole header bar, so the item itself isn't the positioning box */
  .menu__panel {
    position: absolute;
    inset-inline: 0;
    inset-block-start: calc(100% + var(--space-md));
    margin-inline: auto;
    z-index: 10;
    display: grid;
    gap: var(--space-xl);
    padding: var(--space-lg) var(--space-2xl) var(--space-2xl);
    border-radius: var(--radius-md);
    background-color: var(--color-background);
    box-shadow: var(--shadow-panel);
  }

  /* Width options (header setting "Mega menu width"). 'bar' = same width as the header bar (default);
     'screen' breaks out of the bar: centred on it, as wide as the window minus the page margins. */
  .menu--panel-screen .menu__panel {
    inset-inline: 50% auto;
    inline-size: calc(100vw - var(--page-margin) * 2);
    translate: -50% 0;
  }

  .menu__panel-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-lg);
  }

  /* "Shop by category" (Figma: Satoshi Medium 12px / 28px, letter-spacing 2px, uppercase) */
  .menu__panel-title {
    margin: 0;
    font-family: var(--font-body--family);
    font-size: 0.75rem;
    font-weight: var(--font-weight-medium);
    line-height: 1.75rem;
    letter-spacing: 0.125rem;
    text-transform: uppercase;
  }

  /* "Shop all" (Figma: Satoshi Medium 14px, line-height 100%, letter-spacing 21%, uppercase) */
  .menu__panel-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    min-block-size: 1.5rem;
    color: var(--color-text);
    font-family: var(--font-body--family);
    font-size: 0.875rem;
    font-weight: var(--font-weight-medium);
    line-height: 1;
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    text-decoration: none;
  }

  .menu__panel-all:hover {
    color: var(--color-accent);
  }

  .menu__panel-actions {
    display: flex;
    align-items: center;
    gap: var(--space-xl);
  }

  /* Arrow icon from the Figma (assets/icon-arrow.svg, drawn in currentColor); the "previous" one is mirrored */
  .menu__icon {
    display: inline-flex;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  .menu__icon svg {
    inline-size: 0.875rem;
    block-size: auto;
  }

  .menu__icon--back {
    transform: scaleX(-1);
  }

  /*
    Bottom-right corner of the panel, on the same line as the bottom of the cards (the tag row). Absolute,
    so the arrows don't add a row or a gap to the panel. The offsets match the panel's padding
    (--space-2xl), so they line up with the right edge of the last card and the bottom of the content.
  */
  .menu__slider-buttons {
    position: absolute;
    inset-inline-end: var(--space-2xl);
    inset-block-end: var(--space-2xl);
    display: flex;
    align-items: center;
    gap: var(--space-xs);
  }

  /*
    critical.css gives a button that follows another button a 12px top margin (meant for stacked form
    buttons), which dropped the "next" arrow below the "previous" one. That rule uses :where() (zero
    specificity), so this one class is enough to cancel it.
  */
  .menu__slider-buttons .menu__slider-button {
    margin: 0;
  }

  .menu__slider-buttons[hidden] {
    display: none;
  }

  .menu__slider-button {
    display: inline-grid;
    place-items: center;
    inline-size: 2.5rem;
    block-size: 2.5rem;
    padding: 0;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background: none;
    color: var(--color-text);
    cursor: pointer;
    transition: color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out);
  }

  .menu__slider-button:hover:not(:disabled) {
    border-color: var(--color-accent);
    background-color: var(--color-accent);
    color: var(--color-background);
  }

  .menu__slider-button:disabled {
    opacity: 0.35;
    cursor: default;
  }

  /*
    One row of cards, as in the Figma. "Cards per row" (--mega-columns) cards are visible;
    any extra cards continue to the right and the row scrolls (snapping to each card).
  */
  .menu__cards {
    --cards-gap: var(--space-xl);
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: calc((100% - var(--cards-gap) * (var(--mega-columns, 3) - 1)) / var(--mega-columns, 3));
    gap: var(--cards-gap);
    margin: 0;
    padding: 0 0 var(--space-xs);
    list-style: none;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x mandatory;
    scroll-behavior: smooth;
    scrollbar-width: none;
  }

  .menu__cards::-webkit-scrollbar {
    display: none;
  }

  @media (prefers-reduced-motion: reduce) {
    .menu__cards {
      scroll-behavior: auto;
    }
  }

  .menu__card {
    display: grid;
    align-content: start;
    gap: var(--space-sm);
    min-inline-size: 0;
    scroll-snap-align: start;
  }

  .menu__card-image-link {
    display: block;
    margin-block-end: var(--space-sm);
    overflow: hidden;
    border-radius: var(--radius-sm);
  }

  /* Image shape (header setting "Image shape") */
  .menu__card-image {
    aspect-ratio: 7 / 4;
  }

  .menu--ratio-square .menu__card-image {
    aspect-ratio: 1;
  }

  .menu--ratio-portrait .menu__card-image {
    aspect-ratio: 3 / 4;
  }

  /* Image fit (header setting): 'contain' shows the whole image on a soft tint instead of cropping it */
  .menu--images-contain .menu__card-image {
    background-color: var(--color-tint-subtle);
  }

  .menu--images-contain .menu__card-image > img {
    object-fit: contain;
  }

  .menu__card-image img {
    transition: transform var(--duration-base) var(--ease-out);
  }

  .menu__card:hover .menu__card-image img {
    transform: scale(1.04);
    transition-duration: 1500ms;
    }

  /* Category title (Figma: Satoshi Medium 16.54px, line-height 100%, letter-spacing 12%, uppercase, accent).
     --color-accent follows the panel's colour scheme, so it stays readable on red / dark schemes. */
  .menu__card-title {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: var(--space-md);
    justify-self: start;
    min-block-size: 1.5rem;
    padding-block-end: var(--space-xs);
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: 1.0338rem;
    font-weight: var(--font-weight-medium);
    line-height: 1;
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
    text-decoration: none;
  }

  /* Normal: an up-right arrow. Card hover (Figma): the arrow turns to point right and a line draws
     under the title and arrow. Rotating the same arrow 45 degrees turns up-right into right. */
  .menu__card-title svg {
    inline-size: 0.75rem;
    block-size: auto;
    transition: rotate var(--duration-base) var(--ease-out);
  }

  .menu__card-title::after {
    content: '';
    position: absolute;
    inset-inline: 0;
    inset-block-end: 0;
    block-size: 1px;
    background-color: currentcolor;
    scale: 0 1;
    transform-origin: left;
    transition: scale var(--duration-base) var(--ease-out);
  }

  .menu__card:hover .menu__card-title svg,
  .menu__card-title:focus-visible svg {
    rotate: 45deg;
  }

  .menu__card:hover .menu__card-title::after,
  .menu__card-title:focus-visible::after {
    scale: 1 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .menu__icon,
    .menu__card-title svg,
    .menu__card-title::after,
    .menu__card-image img {
      transition: none;
    }
  }

  /* Card description (Figma: Canela Text, our heading font). Wraps naturally and stops after 2 lines. */
  .menu__card-text {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: var(--color-text);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body-sm);
    line-height: var(--line-height-body);
    overflow-wrap: break-word;
    text-wrap: pretty;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  /* 3rd level on the card: small outlined pills under the description */
  .menu__card-subs {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: var(--space-2xs) 0 0;
    padding: 0;
    list-style: none;
  }

  .menu__card-sub {
    display: inline-flex;
    align-items: center;
    min-block-size: 1.75rem;
    padding-inline: var(--space-sm);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-small);
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out);
  }

  .menu__card-sub:hover,
  .menu__card-sub[aria-current='page'] {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

/* snippets/image.liquid */

  .image {
    display: block;
    position: relative;
    overflow: hidden;
    width: 100%;
    height: auto;
  }

  .image > img,
  .image > .image__placeholder {
    display: block;
    width: 100%;
    height: auto;
  }

  /* Fills its parent box (hero backgrounds, fixed-ratio cards). The focal point decides what stays visible. */
  .image--cover,
  .image--cover > img,
  .image--cover > .image__placeholder {
    height: 100%;
  }

  .image--cover > img {
    object-fit: cover;
  }

  .image__placeholder {
    background-color: var(--color-tint-subtle);
    fill: var(--color-tint-border);
  }

/* snippets/localization-form.liquid */

  .localization {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    min-inline-size: 0; /* a flex item: without this it can't get narrower than its text */
    max-inline-size: 100%; /* never wider than its row, so a long name is cut in the pill */
  }

  .localization__picker {
    display: block;
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  .localization__details {
    position: relative;
  }

  /* The pill: same glass as the header's round buttons. Never wider than its row (long names, below). */
  .localization__toggle {
    display: inline-flex;
    max-inline-size: 100%;
    align-items: center;
    gap: var(--space-xs);
    min-block-size: 2.75rem; /* 44px touch target */
    padding-inline: var(--space-md);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    box-shadow: var(--shadow-header);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
    list-style: none;
    cursor: pointer;
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
    /* No backdrop-filter: flat footer panel behind (nothing to blur); a blur showed dark under the header on phones */
  }

  /*
    A long name ("Bosnia & Herzegovina (BAM КМ)") stays on one line in the pill and is cut with …; the
    full name is still in the text, so screen readers read all of it, and the list shows it in full.
  */
  .localization__label {
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Remove the browser's default triangle on <summary> */
  .localization__toggle::-webkit-details-marker {
    display: none;
  }

  .localization__toggle:hover,
  .localization__details[open] > .localization__toggle {
    background-color: var(--color-glass-strong);
    color: var(--color-accent);
  }

  .localization__toggle svg {
    flex-shrink: 0;
    transition: transform var(--duration-fast) var(--ease-out);
  }

  .localization__details[open] > .localization__toggle svg {
    transform: rotate(180deg);
  }

  /* The list opens upwards: the picker sits at the bottom of the page */
  .localization__list {
    position: absolute;
    z-index: 2;
    inset-block-end: calc(100% + var(--space-xs));
    inset-inline-start: 0;
    display: grid;
    gap: 2px;
    /* At least the pill's width and 15rem, but never wider than the screen minus its margins (min() wins) */
    min-inline-size: min(max(100%, 15rem), calc(100vw - var(--page-margin) * 2));
    translate: var(--list-shift, 0) 0; /* set by the script only when the list fits on neither side */
    max-block-size: min(20rem, 60vh);
    overflow-y: auto;
    margin: 0;
    padding: var(--space-xs);
    border-radius: var(--radius-md);
    background-color: var(--color-background);
    color: var(--color-text);
    box-shadow: var(--shadow-panel);
    list-style: none;
  }

  /*
    No space on the opening side (e.g. the language pill at the right on a phone): the script sets
    data-align="end", and the list opens from the pill's other edge. Without JS it opens from the start.
  */
  .localization__list[data-align='end'] {
    inset-inline: auto 0;
  }

  /*
    Two classes on purpose: critical.css styles every button[type='submit'] as the red pill, and its
    selector (one attribute + one element) beats a single class.
  */
  .localization .localization__option {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: var(--space-md);
    inline-size: 100%;
    min-block-size: 2.75rem;
    padding: var(--space-xs) var(--space-md);
    border: 0;
    border-radius: var(--radius-pill);
    background-color: transparent;
    color: inherit;
    box-shadow: none;
    font-size: var(--font-size-small);
    font-weight: 400;
    letter-spacing: normal;
    text-align: start;
    text-transform: none;
  }

  .localization .localization__option:hover {
    background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
    box-shadow: none;
  }

  .localization .localization__option[aria-current='true'] {
    color: var(--color-accent);
    font-weight: var(--font-weight-medium);
  }

  .localization__currency {
    color: color-mix(in srgb, currentColor 70%, transparent);
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    .localization__toggle,
    .localization__toggle svg {
      transition: none;
    }
  }

/* snippets/motion-pause.liquid */

  .motion-pause {
    display: block;
    inline-size: fit-content;
  }

  /* A small round button: the hero's pause button without the blur */
  .motion-pause__button {
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    margin: 0;
    padding: 0;
    border: 1px solid color-mix(in srgb, var(--color-text) 12%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-surface-raised);
    box-shadow: var(--shadow-header);
    color: var(--color-text);
    cursor: pointer;
  }

  .motion-pause__button[hidden] {
    display: none;
  }

  .motion-pause__icon--play,
  .motion-pause__button[aria-pressed='true'] .motion-pause__icon--pause {
    display: none;
  }

  .motion-pause__button[aria-pressed='true'] .motion-pause__icon--play {
    display: block;
  }

  /* Paused: every animation inside the target freezes where it is */
  .is-motion-paused,
  .is-motion-paused *,
  .is-motion-paused *::before,
  .is-motion-paused *::after {
    animation-play-state: paused !important;
  }

/* snippets/newsletter-form.liquid */

  /*
    Figma (footer): a glass pill input (~330 x 50px, 50% white, 1.5px white border) with the red
    SUBSCRIBE pill underneath, 30px apart. The button is the theme's .button (critical.css).
  */
  /*
    Spacing uses margins on our own elements, not flex gap: when the field gets focus, Shopify's bot
    protection injects an empty, invisible <div class="h-captcha"> into the form. Gap is added between
    every flex item, even an empty one, so it pushed the button 30px down. Margins only apply where we
    put them, so the injected div (0px tall) changes nothing.
  */
  .newsletter-form {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    max-inline-size: 20.625rem; /* 330px, Figma input width */
  }

  /*
    Two classes on purpose: critical.css styles input[type='email'] (specificity 0,1,1), which beats a
    single class (0,1,0). Two classes (0,2,0) win, so the hover/focus/error borders are set again below.
  */
  .newsletter-form .newsletter-form__input {
    padding-inline: 1.875rem; /* text starts 30px in, Figma */
    /*
      The edge: the Figma white border gave 1.03:1 on the glass panel, so the field did not show (WCAG
      1.4.11 asks 3:1 for the edge of a field). 55% text: 3.6:1 on the light panel; on a dark scheme the
      text is light, so the edge is near white on the dark panel (as before).
    */
    border: 1.5px solid color-mix(in srgb, var(--color-text) 55%, #ffffff);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong);
    box-shadow: var(--shadow-card);
    font-size: var(--font-size-caption);
    /* No backdrop-filter: flat footer panel behind (nothing to blur); a blur showed dark under the header on phones */
  }

  .newsletter-form .newsletter-form__input:hover {
    border-color: color-mix(in srgb, var(--color-text) 80%, #ffffff);
  }

  .newsletter-form .newsletter-form__input:focus-visible {
    border-color: var(--color-accent);
  }

  .newsletter-form .newsletter-form__input[aria-invalid='true'] {
    border-color: var(--color-error);
  }

  /*
    Our own spacing. Two classes so it beats critical.css's margins between neighbouring fields and
    buttons (the hidden label still counts as the input's neighbour).
  */
  .newsletter-form .newsletter-form__input {
    margin-block-start: 0;
  }

  .newsletter-form .newsletter-form__button {
    margin-block-start: 1.875rem; /* 30px under the field, Figma */
  }

  /* Empty or wrong email: a round "!" and the text under the field (the contact form's look) */
  .newsletter-form__error {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2xs);
    margin: var(--space-xs) 0 0;
    color: var(--color-error);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    line-height: 1.4;
  }

  .newsletter-form__error[hidden] {
    display: none;
  }

  .newsletter-form__error::before {
    content: "!" / "";
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 1.1em;
    block-size: 1.1em;
    margin-block-start: 0.15em;
    border-radius: 50%;
    background-color: var(--color-error);
    color: #ffffff;
    font-size: 0.85em;
    line-height: 1;
  }

  /* Error text, or the success message's <auto-dismiss> wrapper, under the button */
  .newsletter-form__message {
    margin: 0;
  }

  .newsletter-form > .newsletter-form__message,
  .newsletter-form > auto-dismiss {
    margin-block-start: var(--space-md);
  }

  /* The success message takes focus after the reload; it's text, so no focus ring box around it */
  .newsletter-form__message:focus {
    outline: none;
  }

  auto-dismiss {
    display: block;
    transition: opacity var(--duration-base) var(--ease-out);
  }

  auto-dismiss.is-hiding {
    opacity: 0;
  }

  @media (prefers-reduced-motion: reduce) {
    auto-dismiss {
      transition: none;
    }
  }

/* snippets/pagination.liquid */

  /* "Page 1 of 11" on the left, the pill in the middle (the empty third column balances it) */
  .pagination {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    gap: var(--space-md);
    margin-block-start: var(--space-2xl); /* Figma: 78px under the grid, with the results' 24px gap */
  }

  .pagination__status {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-caption);
  }

  /*
    Sizes are about 1.2x the Figma (circles 40 → 48px, current 60 → 72px, bar 50 → 60px), which looked
    too small on screen.

    Figma glass values (on white): the bar fill #f6f2ec at 50%, Frost 100 (= --glass-frost, 35px).
    Border 0.94px #fff4f4 and shadow 0 0 9.39px 5% black exactly as the Figma (developer, 2026-10-30);
    radius 25px, because the Figma's 18.78px looked too square at our 1.2x size. The fill, the pearl
    buttons and the numbers are mixed from the section's colour scheme (a little text colour into the
    background), so on white they match the Figma and on a red or dark scheme they follow it; the
    border is the Figma's fixed pale pink.
    Refraction / Depth / Dispersion need a Chrome-only SVG filter, so they are left out (as in css-variables).
  */
  /* Circles 16px apart, 24px from the ends; prev / next sit 40px from the numbers (see below) */
  .pagination__pill {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    min-block-size: 3.75rem;
    margin: 0;
    padding: 0 var(--space-lg);
    border: 0.94px solid #fff4f4;
    border-radius: var(--radius-md); /* 25px */
    background-color: color-mix(in srgb, color-mix(in srgb, var(--color-text) 5%, var(--color-background)) 50%, transparent);
    box-shadow: 0 0 9.39px 0 #0000000d;
    list-style: none;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  /* More room between the arrows and the page numbers, so the numbers read as one group */
  .pagination__end--previous {
    margin-inline-end: var(--space-lg);
  }

  .pagination__end--next {
    margin-inline-start: var(--space-lg);
  }

  .pagination__arrow,
  .pagination__page,
  .pagination__gap {
    display: inline-grid;
    place-items: center;
    inline-size: 3rem;
    block-size: 3rem;
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
    font-variant-numeric: tabular-nums;
    text-decoration: none;
  }

  /*
    Previous / next and the page numbers: soft raised pearl buttons (my reference image). Back to front:
    - the fill: a little darker at the top-left fading to the scheme background at the bottom-right
      (on white: #eeeeee → #f8f8f8 → white)
    - a bright white rim on the top-left edge (the light), a softer white glow inside the bottom-right
    - a faint shadow outside, so the button lifts off the bar
    The current page (accent circle) has its own look.
  */
  .pagination__arrow,
  .pagination__page {
    background-image: linear-gradient(
      135deg,
      color-mix(in srgb, var(--color-text) 7%, var(--color-background)) 0%,
      color-mix(in srgb, var(--color-text) 3%, var(--color-background)) 55%,
      var(--color-background) 100%
    );
    box-shadow:
      inset 1.5px 1.5px 1px #ffffff,
      inset -2px -2px 4px #ffffffb3,
      0 3px 10px 0 #00000014;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .pagination__arrow svg {
    inline-size: 0.5625rem;
    block-size: 0.875rem;
  }

  .pagination__arrow--disabled {
    opacity: 0.4;
  }

  a.pagination__page:hover,
  a.pagination__arrow:hover {
    color: var(--color-accent);
  }

  /*
    The current page: a 72px circle in the scheme's accent (red on light schemes, white on red, gold on dark)
    with a thin ring, 6px taller than the bar on each side (Figma)
  */
  .pagination__page--current {
    inline-size: 4.5rem;
    block-size: 4.5rem;
    margin-block: -0.375rem;
    border: 1px solid color-mix(in srgb, var(--color-text) 8%, var(--color-background));
    background-color: var(--color-accent);
    background-image: none;
    box-shadow: none;
    color: var(--color-background);
  }

  /* Phones: previous, the current page, next; "Page 3 of 11" goes under the pill */
  @media (max-width: 749px) {
    .pagination {
      grid-template-columns: 1fr;
      justify-items: center;
    }

    .pagination__status {
      grid-row: 2;
    }

    .pagination__part:not(:has(.pagination__page--current)) {
      display: none;
    }
  }

/* snippets/pair-card.liquid */

  /*
    Figma: cards ~254 wide, images 254 x 318 (4:5), radius ~16; a 40px white circle with an accent tick
    at the top right (empty white circle when unticked); title heading font ~22px; price ~22px medium.
    Unticked cards fade to ~45%. Phones (Variant97): cards ~98 wide, radius ~10, a 16px circle, title
    ~13px, price ~12px.
    Only the photo fades: a faded title and price failed contrast (2.81:1, Lighthouse)
  */
  .pair-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    min-inline-size: 0;
  }

  .pair-card .pair-card__image {
    opacity: 0.45;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  /* Hover or keyboard focus brings an unticked card up a little, so it reads as clickable */
  .pair-card:is(:hover, :focus-within) .pair-card__image {
    opacity: 0.75;
  }

  /* Ticked: full strength (same weight as the hover rule, and after it, so it wins) */
  .pair-card:has(.pair-card__input:checked) .pair-card__image {
    opacity: 1;
  }

  .pair-card__media {
    position: relative;
    overflow: hidden;
    aspect-ratio: 4 / 5;
    margin-block-end: var(--space-sm);
    border-radius: var(--pair-card-radius, max(0.75rem, calc(16 * var(--px, 0.0625rem))));
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 5%, var(--color-background)));
  }

  /*
    The checkbox itself: invisible, still in the Tab order (its focus ring shows on the tick). Two
    classes: the global input[type="checkbox"] rule (element + attribute) outweighs one class.
  */
  .pair-card .pair-card__input {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: 0;
    opacity: 0;
    pointer-events: none;
  }

  /* The whole image is the checkbox's label: a click anywhere on it ticks / unticks the card */
  .pair-card__toggle {
    position: relative;
    display: block;
    margin: 0;
    inline-size: 100%;
    block-size: 100%;
    cursor: pointer;
  }

  .pair-card__input:disabled + .pair-card__toggle {
    cursor: not-allowed;
  }

  .pair-card__image {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .pair-card__placeholder {
    fill: color-mix(in srgb, var(--color-text) 30%, transparent);
  }

  .pair-card__tick {
    position: absolute;
    inset-block-start: var(--pair-tick-inset, max(0.5rem, calc(10 * var(--px, 0.0625rem))));
    inset-inline-end: var(--pair-tick-inset, max(0.5rem, calc(10 * var(--px, 0.0625rem))));
    display: grid;
    place-items: center;
    inline-size: var(--pair-tick-size, max(2.5rem, calc(40 * var(--px, 0.0625rem))));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-background);
    box-shadow: 0 2px 8px #0000001f;
    color: transparent;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .pair-card__tick svg {
    inline-size: 45%;
    block-size: auto;
  }

  .pair-card__input:checked + .pair-card__toggle .pair-card__tick {
    color: var(--color-accent);
  }

  .pair-card__input:focus-visible + .pair-card__toggle .pair-card__tick {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .pair-card__title {
    color: inherit;
    font-family: var(--font-heading--family);
    font-size: var(--pair-card-text, var(--font-size-body-lg));
    line-height: 1.3;
    text-decoration: none;
  }

  .pair-card__title:hover {
    text-decoration: underline;
    text-underline-offset: 0.2em;
  }

  .pair-card__price,
  .pair-card__note {
    margin: 0;
  }

  .pair-card__price {
    font-size: var(--pair-card-text, var(--font-size-body-lg));
    font-weight: var(--font-weight-medium);
  }

  .pair-card__note {
    font-size: var(--font-size-small);
  }

  .pair-card__note[hidden] {
    display: none;
  }

  /* Phones (Variant97): small cards, 3 in a row */
  @media (max-width: 749px) {
    .pair-card {
      --pair-card-radius: 0.625rem;
      --pair-card-text: 0.8125rem;
      --pair-tick-size: 1.25rem;
      --pair-tick-inset: 0.375rem;
    }

    .pair-card__media {
      margin-block-end: var(--space-xs);
    }

    .pair-card__title {
      line-height: 1.25;
    }

    .pair-card__note {
      font-size: 0.75rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .pair-card,
    .pair-card__tick {
      transition: none;
    }
  }

/* snippets/pickup-line.liquid */

  .product-pickup__line {
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm);
    font-size: var(--font-size-body-sm);
  }

  .product-pickup__icon {
    display: inline-flex;
    flex: none;
    margin-block-start: 0.1em;
