/* snippets/policy-page-styles.liquid */

  /* The page column: the "Widest" width of the other pages, under the header */
  .shopify-policy__container {
    --policy-title-column: max(14rem, calc(418 / 1920 * 100vw));

    box-sizing: border-box;
    inline-size: min(calc(100vw - clamp(4rem, 8vw, 10rem)), calc(100% - var(--page-margin) * 2));
    max-inline-size: none;
    margin: 0 auto;
    padding-block: var(--space-xl) var(--space-3xl, 6rem);
  }

  /* The title, as the policy section's heading (Figma ~64px, a 3px rule under it) */
  .shopify-policy__title {
    padding-block-end: var(--space-xl);
    border-block-end: 3px solid var(--color-card-border);
    text-align: start;
  }

  .shopify-policy__title h1 {
    margin: 0;
    /* As the policy section's heading (64 Figma px at 1920, at least 36px) */
    font-size: max(2.25rem, calc(64 / 1920 * 100vw));
    font-weight: 400;
    line-height: 1.1;
  }

  /* The text: Shopify wraps it in .rte > div; the div steps out so its children are the grid items */
  .shopify-policy__body {
    margin-block-start: var(--space-xl);
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .shopify-policy__body .rte {
    counter-reset: policy-item;
    display: grid;
    grid-template-columns: var(--policy-title-column) minmax(0, 1fr);
    align-items: start;
  }

  .shopify-policy__body .rte > div {
    display: contents;
  }

  .shopify-policy__body .rte :is(p, ul, ol, h3, table, h4, h5, h6) {
    grid-column: 1 / -1;
    margin: 0;
  }

  .shopify-policy__body .rte :is(p, ul, ol) + :is(p, ul, ol) {
    margin-block-start: var(--space-sm);
  }

  /* Each H2: a numbered row title ("01 Returns"), with the row line above it */
  .shopify-policy__body .rte h2 {
    counter-increment: policy-item;
    grid-column: 1;
    display: flex;
    gap: var(--space-md);
    margin: 0;
    padding: var(--space-xl) var(--space-lg) 0 0;
    border-block-start: 1px solid var(--color-card-border);
    font-size: clamp(1.25rem, 1.1rem + 0.45vw, 1.625rem);
    font-weight: 400;
    line-height: 1.35;
  }

  .shopify-policy__body .rte h2::before {
    content: counter(policy-item, decimal-leading-zero);
    flex-shrink: 0;
    color: var(--color-accent);
    font-size: 0.85em;
    line-height: 1.6;
  }

  /* The text after an H2 (until the next one) sits in the text column; the first piece draws the line */
  .shopify-policy__body .rte h2 ~ :is(p, ul, ol, h3) {
    grid-column: 2;
  }

  .shopify-policy__body .rte h2 + :is(p, ul, ol, h3) {
    padding-block-start: var(--space-xl);
    border-block-start: 1px solid var(--color-card-border);
  }

  .shopify-policy__body .rte h2 ~ :is(p, ul, ol):has(+ h2) {
    padding-block-end: var(--space-xl);
  }

  .shopify-policy__body .rte h3 {
    margin-block-start: var(--space-md);
    font-size: var(--font-size-body-lg);
    font-weight: 400;
  }

  /* An H4–H6: an accent group label; the numbering restarts */
  .shopify-policy__body .rte :is(h4, h5, h6) {
    counter-reset: policy-item;
    margin-block-start: var(--space-2xl);
    margin-block-end: var(--space-md);
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .shopify-policy__body .rte a,
  .shopify-policy__body .rte em {
    color: var(--color-accent);
  }

  .shopify-policy__body .rte em {
    font-style: normal;
  }

  /* A table: the register (accent header labels, heading-font first column, accent last column) */
  .shopify-policy__body .rte table {
    inline-size: 100%;
    border-collapse: collapse;
  }

  .shopify-policy__body .rte th {
    padding: 0 var(--space-md) var(--space-md) 0;
    border-block-end: 1px solid var(--color-card-border);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-align: start;
    text-transform: uppercase;
  }

  .shopify-policy__body .rte td {
    padding: var(--space-lg) var(--space-md) var(--space-lg) 0;
    border-block-end: 1px solid var(--color-card-border);
    vertical-align: top;
  }

  .shopify-policy__body .rte td:first-child {
    font-family: var(--font-heading--family);
    font-size: clamp(1.125rem, 1rem + 0.45vw, 1.5rem);
  }

  .shopify-policy__body .rte td:last-child {
    color: var(--color-accent);
  }

  /* Phones (the policy phone PNGs): one column (the number + title, then the text); the table scrolls sideways */
  @media (max-width: 749px) {
    .shopify-policy__container {
      inline-size: calc(100% - var(--page-margin) * 2);
    }

    .shopify-policy__title {
      padding-block-end: var(--space-lg);
    }

    .shopify-policy__title h1 {
      font-size: 1.75rem;
      line-height: 1.3;
    }

    .shopify-policy__body {
      margin-block-start: var(--space-lg);
      font-size: 0.8125rem;
      line-height: 1.65;
    }

    .shopify-policy__body .rte h2 {
      gap: var(--space-sm);
      font-size: 1.0625rem;
    }

    .shopify-policy__body .rte {
      grid-template-columns: minmax(0, 1fr);
    }

    .shopify-policy__body .rte h2,
    .shopify-policy__body .rte h2 ~ :is(p, ul, ol, h3) {
      grid-column: 1;
    }

    .shopify-policy__body .rte h2 {
      padding-inline-end: 0;
    }

    .shopify-policy__body .rte h2 + :is(p, ul, ol, h3) {
      padding-block-start: var(--space-sm);
      border-block-start: 0;
    }

    .shopify-policy__body .rte table {
      display: block;
      overflow-x: auto;
    }
  }

/* snippets/price.liquid */

  /* Figma card: the price in the accent red, medium weight */
  .price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0 var(--space-xs);
  }

  .price__current {
    color: var(--color-accent);
    font-weight: var(--font-weight-medium);
  }

  /* The old price: smaller, softer, struck through */
  .price__compare {
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: 0.85em;
  }

  /* Savings pill (Figma PDP "13% OFF"): small uppercase label on a soft accent tint */
  .price__savings {
    align-self: center;
    padding: 0.25em 0.75em;
    border-radius: var(--radius-pill);
    background-color: var(--color-tint);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    line-height: 1.4;
    text-transform: uppercase;
  }

  /* Unit price on its own line, small */
  .price__unit {
    flex-basis: 100%;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-caption);
  }

  /* Sold out: the price stays readable but steps back (the card shows a "Sold out" badge) */
  .price--sold-out .price__current {
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

/* snippets/product-block-heading.liquid */

  .product-block-heading {
    margin: 0 0 var(--space-md);
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    line-height: 1.3;
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

/* snippets/product-card.liquid */

  /*
    Figma card: a white glass tile, small rounded corners (19px), soft shadow; image on top, then the
    title + subtitle on the left and the red price on the right.
  */
  .product-card {
    position: relative; /* the title link's ::after stretches over the whole card */
    display: flex;
    flex-direction: column;
    overflow: hidden;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-glass-strong);
    box-shadow: var(--shadow-card);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  /* Keyboard focus: the ring goes around the whole card, not just the title text */
  .product-card:has(.product-card__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .product-card__link:focus-visible {
    outline: none;
  }

  .product-card__media {
    position: relative;
    overflow: hidden;
  }

  .product-card__media--portrait {
    aspect-ratio: 4 / 5;
  }

  .product-card__media--square {
    aspect-ratio: 1;
  }

  .product-card__media--landscape {
    aspect-ratio: 4 / 3;
  }

  .product-card__media .image > img {
    transition:
      transform var(--duration-slow) var(--ease-out),
      opacity var(--duration-base) var(--ease-out);
  }

  /* Hover: a slow, gentle zoom; with a second image, that one fades in on top */
  .product-card:hover .product-card__media .image > img {
    transform: scale(1.04);
  }

  .product-card__secondary {
    position: absolute;
    inset: 0;
  }

  .product-card__secondary > img {
    opacity: 0;
  }

  .product-card--has-secondary:hover .product-card__secondary > img {
    opacity: 1;
  }

  @media (prefers-reduced-motion: reduce) {
    .product-card__media .image > img {
      transition: none;
    }

    .product-card:hover .product-card__media .image > img {
      transform: none;
    }
  }

  .product-card__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    background-color: var(--color-tint-subtle);
    fill: var(--color-tint-border);
  }

  /*
    Badges top-left of the image. Figma: a cream rounded rectangle with red text ("New").
    Colours come from the colour scheme chosen in Theme settings > Product cards: the scheme class
    (color-scheme-N) paints the scheme's background; the text uses the scheme's accent.
  */
  .product-card__badges {
    position: absolute;
    inset-block-start: var(--space-sm);
    inset-inline-start: var(--space-sm);
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2xs);
    pointer-events: none;
  }

  .product-card__badge {
    padding: 0.3em 0.75em;
    border-radius: 0.75em;
    font-size: var(--font-size-caption);
    line-height: 1.3;
  }

  /*
    Two classes on purpose: the scheme class sets color: var(--color-text) with one class, and which
    stylesheet loads last isn't guaranteed. Two classes always win, so the text is the scheme's accent.
  */
  .product-card .product-card__badge {
    color: var(--color-accent);
  }

  /* A badge entry with its own colours (Content > Metaobjects > Badges); three classes beat the rule above */
  .product-card .product-card__badge.product-card__badge--own-colors {
    background-color: var(--badge-bg);
    color: var(--badge-fg);
  }

  /* Title + subtitle left, price right; the price drops below on a narrow card */
  .product-card__info {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-xs) var(--space-md);
    padding: var(--space-md);
  }

  .product-card__text {
    flex: 1 1 10rem;
    min-inline-size: 0;
  }

  .product-card__title {
    margin: 0;
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    line-height: 1.35;
    text-wrap: pretty;
  }

  .product-card__link {
    color: var(--color-text);
    text-decoration: none;
  }

  /* The stretched link: an invisible box over the whole card, so a click anywhere opens the product */
  .product-card__link::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
  }

  .product-card__subtitle {
    margin: var(--space-2xs) 0 0;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-caption);
  }

  .product-card .price {
    font-size: var(--font-size-body-sm);
  }

  /*
    ---------- Tile style (Figma collection page) ----------
    A white tile with a 4px frame; the photo fills it and the white info strip sits over the photo's
    bottom edge. The tile fills the box its parent gives it (block-size: 100%).
    Layers: isolation makes the tile its own stacking context, so the photo can sit at z-index -1
    (under the strip) while the stretched title link (z-index 1) still covers the whole tile, and the
    cart button (z-index 2) sits above that.
    container-type: size lets short tiles drop the description (container query below).
  */
  .product-card--tile {
    isolation: isolate;
    justify-content: flex-end;
    block-size: 100%;
    padding: 0.25rem;
    border: 0;
    background-color: #ffffff;
    box-shadow: 0 5px 25px 0 #0000000d; /* Figma collection-card shadow */
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    container-type: size;
  }

  .product-card__media--fill {
    position: absolute;
    inset: 0.25rem;
    z-index: -1;
    border-radius: calc(var(--radius-sm) - 0.25rem);
  }

  .product-card__media--fill > .image {
    block-size: 100%;
  }

  /* Badges a little further in, like the Figma ("Trending" sits ~24px from the corner) */
  .product-card--tile .product-card__badges {
    inset-block-start: var(--space-lg);
    inset-inline-start: var(--space-lg);
  }

  /*
    The details strip is glass over the photo (Figma Glass: Light -45deg 80%, Frost 157.25; drop shadow
    0 0 14.77px #000000 5%).
    - Light -45deg = the light comes from the top LEFT: a bright 1px rim on the top and left edges (80%
      white) and a weaker one bottom-right.
    - Frost: the theme maps Frost 100 to a 35px blur, so 157.25 = 35px x 1.5725 = 55px.
    - The fill is the theme's strong glass (50% white), so the text stays readable on any photo.
    Figma's Refraction, Depth, Dispersion and Splay bend light through the glass; CSS has no equivalent,
    so the blur, rim and shadow carry the effect.
  */
  .product-card--tile .product-card__panel {
    border-radius: calc(var(--radius-sm) - 0.25rem);
    background-color: var(--color-glass-strong);
    box-shadow:
      0 0 14.77px 0 #0000000d,
      inset 1px 1px 0 #ffffffcc,
      inset -1px -1px 0 #ffffff80;
    -webkit-backdrop-filter: blur(55px);
    backdrop-filter: blur(55px);
  }

  /* Strip: title + subtitle left, price right and vertically centred (Figma: ~103px tall at 1920px) */
  .product-card--tile .product-card__info {
    flex-wrap: nowrap;
    align-items: center;
    padding: var(--space-md) var(--space-lg);
  }

  /*
    The glass blur (backdrop-filter) makes the strip the box that absolutely positioned children measure
    from, so the title link's click area (::after, inset: 0) would only cover the strip. The tile is a
    size container, so 100cqh = the tile's full height: the click area hangs from the strip's bottom
    edge and reaches the top of the tile again (-0.25rem = the tile's white frame).
  */
  .product-card--tile .product-card__link::after {
    inset: auto -0.25rem -0.25rem;
    block-size: 100cqh;
  }

  .product-card--tile .product-card__title {
    font-size: var(--font-size-body);
    font-weight: 400;
  }

  /*
    Price on the right edge. The price lines are stacked in a column, right-aligned: as a wrapping row,
    the unit price line (flex-basis 100%) made the box as wide as both lines side by side, so the price
    started mid-card and squeezed the title.
  */
  .product-card--tile .price {
    flex: 0 1 auto;
    flex-direction: column;
    align-items: flex-end;
    margin-inline-start: auto;
    font-size: var(--font-size-body-lg);
    text-align: end;
  }

  .product-card--tile .price__unit {
    flex-basis: auto;
  }

  .product-card--tile .price__current {
    font-weight: 700;
  }

  /*
    Details panel: folded away (0fr) until the tile is hovered or something inside has keyboard focus,
    then it grows to its natural height (1fr) and the strip slides up over the photo. visibility keeps
    the folded content away from screen readers and the Tab key; tabbing onto the title link opens the
    panel first (focus-within), so the cart button is visible before it gets focus.
  */
  .product-card__details {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows var(--duration-base) var(--ease-out);
  }

  .product-card__details-inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    min-block-size: 0;
    overflow: hidden;
    padding-inline: var(--space-lg);
    visibility: hidden;
    transition: visibility 0s linear var(--duration-base);
  }

  .product-card--tile:focus-within .product-card__details {
    grid-template-rows: 1fr;
  }

  .product-card--tile:focus-within .product-card__details-inner {
    visibility: visible;
    transition-delay: 0s;
  }

  /* Hover only where there is a real pointer: on touch screens a tap goes straight to the product */
  @media (hover: hover) {
    .product-card--tile:hover .product-card__details {
      grid-template-rows: 1fr;
    }

    .product-card--tile:hover .product-card__details-inner {
      visibility: visible;
      transition-delay: 0s;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .product-card__details {
      transition: none;
    }
  }

  /* "4.9 ★  213 reviews": number + gold star, then the count in a soft pill */
  .product-card__rating {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
  }

  .product-card__star {
    color: #c8a24b;
  }

  .product-card__reviews {
    padding: 0.15em 0.6em;
    border-radius: var(--radius-pill);
    background-color: var(--color-tint-subtle);
    font-weight: 400;
  }

  .product-card__description {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-caption);
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  .product-card__actions {
    position: relative;
    z-index: 2; /* above the stretched title link */
    display: flex;
    flex-wrap: wrap; /* a long cart button text puts "View details" on the next line */
    align-items: center;
    gap: var(--space-sm);
    padding-block-end: var(--space-md);
  }

  /*
    The glass cart button needs something behind it to show; on the white strip it gets a soft tint
    instead (three classes beat quick-add's own two-class rule).
  */
  .product-card__actions .quick-add:where(:not(.quick-add--pill)) .quick-add__button {
    background-color: var(--color-tint);
  }

  /* "View details": a label in the Figma pill style; the whole tile is the link */
  .product-card__more {
    display: inline-flex;
    align-items: center;
    block-size: 2.5rem;
    padding-inline: var(--space-lg);
    border-radius: var(--radius-pill);
    background-color: var(--color-accent);
    color: var(--color-background);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    text-transform: uppercase;
    text-decoration: none;
  }

  .product-card__more svg {
    display: none;
    inline-size: 1rem;
    block-size: 1rem;
  }

  /* Tiles: the subtitle is always one line ("…"), so the strip keeps the same height */
  .product-card--tile .product-card__subtitle {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* Short tiles (e.g. 1280px screens, the shortest bento tiles): no description, so the panel fits */
  @container (max-height: 24rem) {
    .product-card__description {
      display: none;
    }
  }

  /*
    Very short tiles (the bento's 1-column tiles on 1200-1440px screens are ~190-220px tall): a compact
    strip, one line each for title and price, no subtitle, so the photo still shows (~1/3 strip, as in the
    Figma at 1920px).
  */
  @container (max-height: 16rem) {
    .product-card--tile .product-card__info {
      padding: var(--space-xs) var(--space-md);
    }

    .product-card--tile .product-card__title {
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .product-card--tile .product-card__subtitle {
      display: none;
    }

    .product-card--tile .price {
      font-size: var(--font-size-body);
    }

    .product-card--tile .price__unit {
      display: none;
    }
  }

  /*
    Narrow tiles, measured on the tile itself (a size container), so it works wherever the card sits.
    - Up to 24rem (phones, small bento tiles): "View details" becomes a round arrow button; the label
      wrapped onto two lines here.
    - Up to 20rem (the 1-column bento tiles on small laptops): the price goes under the title instead of
      beside it, so the title gets the full width and words never break letter by letter.
  */
  @container (max-width: 24rem) {
    .product-card__more {
      justify-content: center;
      inline-size: 2.75rem;
      block-size: 2.75rem;
      padding: 0;
    }

    .product-card__more-label {
      display: none;
    }

    .product-card__more svg {
      display: block;
    }
  }

  @container (max-width: 20rem) {
    .product-card--tile .product-card__info {
      flex-wrap: wrap;
      align-items: flex-start;
      row-gap: var(--space-2xs);
    }

    .product-card--tile .product-card__text {
      flex: 1 1 100%;
    }

    .product-card--tile .price {
      flex-direction: row;
      align-items: baseline;
      gap: var(--space-xs);
      margin-inline-start: 0;
      font-size: var(--font-size-body);
      text-align: start;
    }
  }

  /*
    Phones (one tile per row): a slimmer strip, so the photo keeps most of the tile. Title up to 2 lines,
    price at body size; the text column gets the room and never breaks mid-word.
  */
  @media (max-width: 749px) {
    .product-card--tile .product-card__info {
      gap: var(--space-sm);
      padding: var(--space-sm) var(--space-md);
    }

    .product-card--tile .product-card__text {
      flex: 1 1 auto;
    }

    .product-card--tile .product-card__title {
      display: -webkit-box;
      overflow: hidden;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: 2;
      line-clamp: 2;
    }

    .product-card--tile .price {
      flex: none;
      font-size: var(--font-size-body);
    }
  }
  /*
    ---------- Full style (phone design of the collection page) ----------
    Photo on top, everything under it. The controls (options, cart, BUY, Notify me) sit above the
    stretched title link (z-index 2), so they get the clicks; the rest of the card opens the product.
  */
  .product-card__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--space-xs);
    padding: var(--space-sm) var(--space-sm) var(--space-md);
  }

  .product-card__meta {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-2xs) var(--space-xs);
  }

  .product-card__category {
    overflow: hidden;
    flex: 1 1 0;
    min-inline-size: 0;
    margin: 0;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .product-card__score {
    flex: none;
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-caption);
    white-space: nowrap;
  }

  .product-card__pricing {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-xs);
  }

  .product-card--full .price {
    color: var(--color-accent);
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
  }

  .product-card__save {
    padding: 0.2em 0.7em;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 10%, var(--color-background));
    color: var(--color-accent);
    font-size: var(--font-size-caption);
  }

  .product-card__save[hidden],
  .product-card__buy-now[hidden],
  .product-card__notify[hidden] {
    display: none;
  }

  .product-card__options {
    position: relative;
    z-index: 2;
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    border: 0;
    list-style: none;
  }

  /* Size pills: the chosen one dark (design), a sold-out one struck through */
  .product-card__option {
    display: inline-block;
    overflow: hidden;
    max-inline-size: 100%;
    padding: 0.3em 0.7em;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
    border: 1px solid color-mix(in srgb, var(--color-text) 30%, transparent);
    border-radius: var(--radius-pill);
    font-size: var(--font-size-caption);
    cursor: pointer;
  }

  :checked + .product-card__option {
    border-color: var(--color-text);
    background-color: var(--color-text);
    color: var(--color-background);
  }

  :focus-visible + .product-card__option {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  /* 65%: grey text needs at least a 62% mix for 4.5:1 (55% gave 3.74:1); the value can still be picked (Notify me) */
  .product-card__option--sold-out {
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    text-decoration: line-through;
  }

  /* Colour dots (the option has swatches): a ring shows the chosen one */
  .product-card__option--swatch {
    overflow: hidden;
    inline-size: 1.5rem;
    min-block-size: 0;
    block-size: 1.5rem;
    padding: 0;
    border: 2px solid var(--color-background);
    background-color: var(--swatch-color, var(--color-tint));
    box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-text) 25%, transparent);
  }

  :checked + .product-card__option--swatch {
    border-color: var(--color-background);
    background-color: var(--swatch-color, var(--color-tint));
    box-shadow: 0 0 0 2px var(--color-text);
  }

  .product-card__option--swatch img {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* A sold-out dot: faded (a line can't cross a dot) */
  .product-card__option--sold-out.product-card__option--swatch {
    opacity: 0.45;
  }

  /*
    ---------- Full card: photo slider (design 2026-11-25) ----------
    The track scrolls sideways with snap points (swipe on touch). It sits above the title link's
    stretched box (z-index 2), so a swipe moves the photos; each slide is itself a link to the product.
    Arrows (hover) and dots are mouse / touch helpers; badges and the cart pill sit above the track.
  */
  /* "Original" shape with a slider: every slide takes the first photo's shape (the others: their ratio class) */
  .product-card__media--original.product-card__media--slider {
    aspect-ratio: var(--card-media-ratio, 0.8);
  }

  .product-card__gallery {
    position: absolute;
    inset: 0;
    z-index: 2;
    display: block;
  }

  .product-card__slides {
    display: flex;
    block-size: 100%;
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x mandatory;
    scrollbar-width: none;
  }

  .product-card__slides::-webkit-scrollbar {
    display: none;
  }

  .product-card__slide {
    display: block;
    flex: 0 0 100%;
    scroll-snap-align: start;
  }

  .product-card__slide .image {
    block-size: 100%;
  }

  .product-card--full .product-card__badges {
    z-index: 3;
    flex-direction: column;
    align-items: flex-start;
  }

  .product-card__badge[hidden] {
    display: none;
  }

  /* Dots (design): white, the shown photo a longer pill */
  .product-card__dots {
    position: absolute;
    inset-block-end: var(--space-sm);
    inset-inline: 0;
    z-index: 1;
    display: flex;
    justify-content: center;
    gap: 0.3rem;
    pointer-events: none;
  }

  .product-card__dot {
    inline-size: 0.375rem;
    block-size: 0.375rem;
    border-radius: var(--radius-pill);
    background-color: #ffffffa6;
    box-shadow: 0 0 2px #00000040;
    cursor: pointer;
    pointer-events: auto;
    transition: inline-size var(--duration-fast) var(--ease-out);
  }

  .product-card__dot.is-active {
    inline-size: 1.25rem;
    background-color: #ffffff;
  }

  /* Arrows: only with a mouse, shown while the card is hovered */
  .product-card__arrow {
    position: absolute;
    inset-block-start: 50%;
    z-index: 1;
    display: none;
    place-items: center;
    inline-size: 2rem;
    block-size: 2rem;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-background) 88%, transparent);
    box-shadow: var(--shadow-button);
    color: var(--color-text);
    cursor: pointer;
    opacity: 0;
    translate: 0 -50%;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  .product-card__arrow svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .product-card__arrow--prev {
    inset-inline-start: var(--space-xs);
  }

  .product-card__arrow--next {
    inset-inline-end: var(--space-xs);
  }

  /* The theme's chevron points down: next turns to point to the end side, prev to the start side */
  .product-card__arrow--next svg {
    rotate: -90deg;
  }

  .product-card__arrow--prev svg {
    rotate: 90deg;
  }

  .product-card__arrow--next:dir(rtl) svg {
    rotate: 90deg;
  }

  .product-card__arrow--prev:dir(rtl) svg {
    rotate: -90deg;
  }

  @media (hover: hover) and (pointer: fine) {
    .product-card__arrow {
      display: grid;
    }

    .product-card:hover .product-card__arrow {
      opacity: 1;
    }
  }

  .product-card__arrow:hover {
    color: var(--color-accent);
  }

  /* Sold out (design): the photo fades */
  .product-card--sold-out .product-card__media :is(.image, .product-card__slides) {
    opacity: 0.6;
  }

  /*
    ---------- Full card: buy row ----------
    The card is a size container, so the layout follows the card's own width (any column count):
    - small (under 15rem, 2 per row on phones): price, options, then the cart circle (left) + BUY (right)
    - medium (15rem and wider, touch screens): price, then options (left) + cart circle + BUY (right)
    - large (15rem and wider with a mouse): options, then price + BUY in one row; the cart button is the
      "ADD TO CART" pill that appears over the bottom of the photo on hover (design)
  */
  .product-card--full {
    container: product-card / inline-size;
  }

  .product-card__buy {
    position: relative;
    z-index: 2;
    margin-block-start: auto;
    padding-block-start: var(--space-xs);
  }

  .product-card__buy-now {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-xs);
  }

  /*
    Cart circle and BUY as one pair, both 44px tall. Two classes: the global .button rule loads after
    this file and beat the one-class rule (height, padding)
  */
  .product-card .product-card__buy-link,
  .product-card .product-card__notify {
    gap: 0.4em;
    min-block-size: 2.75rem;
    padding-block: 0;
    padding-inline: 1.1rem;
    font-size: var(--font-size-caption);
  }

  .product-card__notify {
    inline-size: 100%;
    letter-spacing: 0.04em;
    white-space: nowrap;
  }

  .product-card__buy-link :is(svg, img),
  .product-card__notify svg {
    flex: none;
    inline-size: 1.1em;
    block-size: 1.1em;
  }

  /* The BUY cart icon is drawn small in its box: 1.25rem (20px), the same as the cart circle's icon */
  .product-card .product-card__buy-link svg {
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  .product-card__buy-link img {
    object-fit: contain;
  }

  /*
    BUY keeps its width (flex: none) and wraps only between words: "anywhere" broke "BUY" into B / U / Y
    (and BU / Y at 390px) when the row was short
  */
  .product-card__buy-link {
    flex: none;
    text-align: center;
  }

  .product-card__buy-label {
    overflow-wrap: normal;
  }

  /* The cart button in its round look ("round" style): the text visually hidden, a 44px circle */
  .product-card .product-card__quick-add--icon .quick-add__button {
    flex: none;
    inline-size: var(--quick-add-size, 2.75rem);
    min-inline-size: 0;
    block-size: var(--quick-add-size, 2.75rem);
    padding: 0;
    gap: 0;
  }

  .product-card__quick-add--icon .quick-add__label {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* The cart icon: 45% of the 44px circle (~20px; quick-add's own share is 35%) */
  .product-card .product-card__quick-add:not(.product-card__cart-text) .quick-add__cart {
    inline-size: calc(var(--quick-add-size, 50px) * 0.45);
    block-size: calc(var(--quick-add-size, 50px) * 0.45);
  }

  /* A very narrow card (320px phones, 2 per row: a 105px row): BUY without its icon, a smaller circle */
  @container product-card (max-width: 9.5rem) {
    .product-card .product-card__buy-link {
      padding-inline: 0.75rem;
    }

    .product-card .product-card__buy-link :is(svg, img) {
      display: none;
    }

    /* 40px (quick-add writes its own 44px size inline, so the size is set on the button itself) */
    .product-card .product-card__quick-add--icon .quick-add__button {
      inline-size: 2.5rem;
      block-size: 2.5rem;
    }

    .product-card__buy-now {
      gap: 0.375rem;
    }
  }

  /* Medium: options on the left of the cart + BUY row */
  @container product-card (min-width: 15rem) {
    .product-card--full .product-card__body {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      grid-template-areas:
        'meta meta'
        'title title'
        'price price'
        'options buy';
      align-items: center;
    }

    .product-card--full .product-card__meta {
      grid-area: meta;
    }

    .product-card--full .product-card__title {
      grid-area: title;
    }

    .product-card--full .product-card__pricing {
      grid-area: price;
    }

    .product-card--full .product-card__options {
      grid-area: options;
    }

    .product-card--full .product-card__buy {
      grid-area: buy;
      align-self: end;
      padding-block-start: 0;
    }

    /* No options: the buttons take the whole row, BUY still on the right */
    .product-card--full .product-card__body:not(:has(.product-card__options)) {
      grid-template-areas:
        'meta meta'
        'title title'
        'price price'
        'buy buy';
    }
  }

  /*
    Large, with a mouse: options, then price + BUY in one row. The cart button leaves the row and sits
    over the bottom of the photo (its bottom = the photo's height, from --card-media-h x the card width,
    less 2rem, clear of the dots), shown while the card is hovered, while it has keyboard focus and while it adds
  */
  @media (hover: hover) and (pointer: fine) {
    @container product-card (min-width: 15rem) {
      .product-card--full .product-card__body {
        grid-template-areas:
          'meta meta'
          'title title'
          'options options'
          'price buy';
      }

      .product-card--full .product-card__body:not(:has(.product-card__options)) {
        grid-template-areas:
          'meta meta'
          'title title'
          'price buy';
      }

      .product-card--full .product-card__buy {
        position: static;
      }

      .product-card--full :is(.product-card__buy-link, .product-card__notify) {
        position: relative;
        z-index: 2;
      }

      /*
        Anchored by its bottom edge: the photo's bottom less 2rem (dots 12px up + 6px tall + a 14px gap),
        then translated up by its own height, so a taller pill never covers the dots
      */
      .product-card--full .product-card__quick-add {
        position: absolute;
        inset-block-start: calc(var(--card-media-h, 1.25) * 100cqi - 2rem);
        inset-inline: 0;
        z-index: 4;
        display: flex;
        justify-content: center;
        pointer-events: none;
        opacity: 0;
        translate: 0 calc(-100% + 0.5rem);
        transition:
          opacity var(--duration-fast) var(--ease-out),
          translate var(--duration-fast) var(--ease-out);
      }

      .product-card--full:hover .product-card__quick-add,
      .product-card--full .product-card__quick-add:focus-within,
      .product-card--full .product-card__quick-add:is(.is-adding, .is-added, .is-resetting, .is-error) {
        opacity: 1;
        translate: 0 -100%;
      }

      .product-card--full:hover .product-card__quick-add .quick-add__button,
      .product-card--full .product-card__quick-add:focus-within .quick-add__button {
        pointer-events: auto;
      }

      /* The design's red pill with the cart icon and "ADD TO CART" (also for the "round" style) */
      .product-card--full .product-card__quick-add .quick-add__button {
        inline-size: auto;
        block-size: auto;
        min-block-size: 2.75rem;
        padding-inline: 1.25rem;
        gap: var(--space-xs);
        background-color: var(--color-button);
        box-shadow: var(--shadow-button);
        color: var(--color-button-text);
        font-size: var(--font-size-caption);
      }

      .product-card--full .product-card__quick-add .quick-add__button:hover {
        background-color: color-mix(in srgb, var(--color-button) 88%, #000000);
        color: var(--color-button-text);
      }

      .product-card--full .product-card__quick-add--icon .quick-add__label {
        position: static;
        inline-size: auto;
        block-size: auto;
        clip-path: none;
      }

      @media (prefers-reduced-motion: reduce) {
        .product-card--full .product-card__quick-add {
          translate: 0 -100%;
          transition: none;
        }
      }
    }
  }

  /*
    Cart button with text (Theme settings > Product cards > Cart button style): two pills, side by side
    when they fit, else one under the other at full width. Both 44px tall at least (touch target).
  */
  .product-card__buy-now--text {
    flex-wrap: wrap;
  }

  .product-card__buy-now--text > * {
    flex: 1 1 auto;
    min-inline-size: 0;
  }

  .product-card__buy-now--text .product-card__buy-link {
    min-block-size: 2.75rem;
  }

  /* Three classes: beat quick-add's pill rule (two classes) and the theme's button[type="submit"] */
  .product-card .product-card__cart-text .quick-add__button {
    inline-size: 100%;
    max-inline-size: 100%;
    block-size: auto;
    min-block-size: 2.75rem;
    padding-inline: 1em;
    font-size: var(--font-size-caption);
    line-height: 1.2;
    text-align: center;
    white-space: normal;
    overflow-wrap: anywhere;
  }

  /* The tile panel: the pill as wide as its text */
  .product-card__actions .product-card__cart-text .quick-add__button {
    inline-size: auto;
  }

/* snippets/product-lightbox.liquid */

  /*
    Figma 1920 ("Product details 14"): white, full screen. Counter pill x 50 y 44 (140 x 60, 1px pale
    border, ~28px); close 60px circle top right; the image x 458–1416 (958 square, radius ~24) from y 36
    to 995; the thumbnails x 1436–1870 in 3 columns (125 / 168 / 106, ~16px gaps, middle column 28px
    higher than the left, the right 61px lower), the current one with a 2px accent outline.
    Change from Figma (our choice): the image area also takes Figma's empty left column, so the image
    grows to the screen height. Full screen: the image alone, whole, the counter and close turn to glass.
  */
  .product-lightbox__dialog {
    inline-size: 100%;
    max-inline-size: none;
    block-size: 100%;
    max-block-size: none;
    margin: 0;
    padding: 0;
    border: 0;
    background-color: var(--color-background);
    color: var(--color-text);
  }

  .product-lightbox__dialog::backdrop {
    background-color: var(--color-background);
  }

  /* The page behind doesn't scroll while the viewer is open */
  html:has(.product-lightbox__dialog[open]) {
    overflow: hidden;
  }

  .product-lightbox__inner {
    position: relative;
    display: grid;
    /* The image area (from the left edge to the thumbnails) and the thumbnails (Figma 504px of 1920) */
    grid-template-columns: minmax(0, 1fr) minmax(0, 26.25%);
    align-items: center;
    padding-inline-start: max(var(--space-md), calc(50 * var(--px, 0.0625rem)));
    block-size: 100%;
    padding-block: var(--lightbox-padding);
  }

  /*
    The image's height limit, from the screen height: a percentage height inside these grids has nothing
    definite to measure against, so it would be ignored and the image would overflow
  */
  .product-lightbox {
    --lightbox-padding: max(var(--space-md), calc(36 * var(--px, 0.0625rem)));
    --lightbox-image-max: calc(100svh - var(--lightbox-padding) * 2);
  }

  .product-lightbox__counter {
    position: absolute;
    z-index: 2;
    inset-block-start: max(var(--space-md), calc(44 * var(--px, 0.0625rem)));
    inset-inline-start: max(var(--space-md), calc(50 * var(--px, 0.0625rem)));
    margin: 0;
    padding: 0.45em 1.1em;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    font-size: var(--font-size-body); /* smaller than Figma's 28px (our choice) */
    line-height: 1.2;
    font-variant-numeric: tabular-nums;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .product-lightbox__close,
  .product-lightbox__arrow {
    display: grid;
    place-items: center;
    inline-size: 2.75rem; /* 44px: smaller than Figma's 60px (our choice), still a full touch target */
    aspect-ratio: 1;
    min-block-size: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: var(--color-background);
    box-shadow: var(--shadow-glass-edge);
    color: var(--color-text);
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .product-lightbox__close {
    position: absolute;
    z-index: 2;
    inset-block-start: max(var(--space-md), calc(44 * var(--px, 0.0625rem)));
    inset-inline-end: max(var(--space-md), calc(50 * var(--px, 0.0625rem)));
  }

  .product-lightbox__close:hover,
  .product-lightbox__arrow:hover {
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
  }

  .product-lightbox__icon {
    display: inline-flex;
  }

  .product-lightbox__icon svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  /* The image area: everything left of the thumbnails, as tall as the screen allows */
  .product-lightbox__stage {
    position: relative;
    grid-column: 1;
    display: grid;
    place-items: center;
    block-size: 100%;
    min-block-size: 0;
  }

  .product-lightbox__slide {
    display: grid;
    place-items: center;
    inline-size: 100%;
    block-size: 100%;
    min-block-size: 0;
  }

  .product-lightbox__slide[hidden] {
    display: none;
  }

  /* The image keeps its shape, as large as fits; the rounded corners sit on the image itself */
  /*
    The button is as big as the image, so the hint sits on the photo. Its width comes from the image's
    shape: as tall as the screen allows (height limit x ratio), never wider than the image area. This
    also lets a smaller photo grow (auto sizing never draws an image larger than its own pixels).
  */
  .product-lightbox__zoom {
    position: relative;
    display: block;
    inline-size: min(100%, calc(var(--lightbox-image-max) * var(--media-ratio, 1)));
    min-block-size: 0;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: none;
    box-shadow: none;
    cursor: zoom-in;
    touch-action: pan-y; /* sideways finger moves are left to the script (swipe = next / previous) */
  }

  .product-lightbox__zoom:focus-visible {
    outline: none;
  }

  .product-lightbox__zoom:focus-visible .product-lightbox__image {
    outline: 2px solid var(--color-accent);
    outline-offset: 4px;
  }

  /* Full screen: the image fills the screen, so the ring goes inside it */
  .product-lightbox.is-full .product-lightbox__zoom:focus-visible .product-lightbox__image {
    outline-offset: -6px;
  }

  .product-lightbox__image {
    display: block;
    inline-size: 100%;
    block-size: auto;
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    user-select: none;
    -webkit-user-drag: none;
  }

  .product-lightbox__media {
    inline-size: min(100%, calc(var(--lightbox-image-max) * var(--media-ratio, 1.7778)));
    max-block-size: var(--lightbox-image-max);
    aspect-ratio: var(--media-ratio, 1.7778);
    overflow: hidden;
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
  }

  .product-lightbox__media .product-media {
    border-radius: inherit;
  }

  /* "CLICK TO VIEW FULL SCREEN" at the bottom of the image */
  .product-lightbox__hint {
    position: absolute;
    inset-block-end: max(var(--space-md), calc(20 * var(--px, 0.0625rem)));
    inset-inline: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-sm);
    color: #ffffff;
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-shadow: 0 1px 6px #00000059;
    text-transform: uppercase;
    pointer-events: none;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  /* One hint per kind of screen: mouse "Click…", touch "Tap…" */
  .product-lightbox__hint-text--touch {
    display: none;
  }

  @media (hover: none) {
    .product-lightbox__hint-text--mouse {
      display: none;
    }

    .product-lightbox__hint-text--touch {
      display: inline;
    }
  }

  /* Previous / next: glass circles on the image's sides; shown on hover or keyboard focus (always on touch) */
  .product-lightbox__arrow {
    position: absolute;
    z-index: 1;
    inset-block-start: 50%;
    translate: 0 -50%;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  .product-lightbox__arrow--prev {
    inset-inline-start: var(--space-md);
  }

  .product-lightbox__arrow--next {
    inset-inline-end: var(--space-md);
  }

  .product-lightbox__stage:hover .product-lightbox__arrow,
  .product-lightbox__arrow:focus-visible {
    opacity: 1;
  }

  @media (hover: none) {
    .product-lightbox__arrow {
      opacity: 1;
    }
  }

  /* One medium: no thumbnails, the image takes the whole width */
  .product-lightbox__inner--single {
    grid-template-columns: minmax(0, 1fr);
    padding-inline-end: max(var(--space-md), calc(50 * var(--px, 0.0625rem)));
  }

  /*
    Thumbnails: 3 columns of their own shapes, the middle one higher, the right one lower. Many media:
    the list scrolls inside the screen height (the image stays in view)
  */
  .product-lightbox__thumbs {
    grid-column: 2;
    display: grid;
    max-block-size: var(--lightbox-image-max);
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-width: thin;
    padding-block: 4px;
    grid-template-columns: 125fr 168fr 106fr;
    align-items: start;
    gap: max(var(--space-sm), calc(16 * var(--px, 0.0625rem)));
    padding-inline: max(var(--space-md), calc(20 * var(--px, 0.0625rem))) max(var(--space-md), calc(50 * var(--px, 0.0625rem)));
  }

  .product-lightbox__thumb-column {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-sm), calc(16 * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  .product-lightbox__thumb-column--1 {
    margin-block-start: calc(28 * var(--px, 0.0625rem));
  }

  .product-lightbox__thumb-column--3 {
    margin-block-start: calc(61 * var(--px, 0.0625rem));
  }

  .product-lightbox__thumb {
    display: block;
    overflow: hidden;
    inline-size: 100%;
    min-block-size: 0;
    aspect-ratio: var(--media-ratio, 1);
    padding: 0;
    border: 2px solid transparent;
    border-radius: max(0.5rem, calc(10 * var(--px, 0.0625rem)));
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 5%, var(--color-background)));
    box-shadow: none;
    cursor: pointer;
    transition: border-color var(--duration-fast) var(--ease-out);
  }

  .product-lightbox__thumb[aria-current="true"] {
    border-color: var(--color-accent);
  }

  .product-lightbox__thumb:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .product-lightbox__thumb-image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /*
    Full screen: the image alone over the whole screen, whole (contain: never cropped), on the background
    colour. Thumbnails, arrows and hint step aside; the counter and close turn to frosted glass.
  */
  .product-lightbox.is-full .product-lightbox__zoom {
    position: fixed;
    z-index: 1;
    inset: 0;
    inline-size: auto;
    background-color: var(--color-background);
    cursor: zoom-out;
  }

  .product-lightbox.is-full .product-lightbox__image {
    inline-size: 100%;
    block-size: 100%;
    max-inline-size: none;
    max-block-size: none;
    object-fit: contain;
    border-radius: 0;
  }

  .product-lightbox.is-full .product-lightbox__hint,
  .product-lightbox.is-full .product-lightbox__arrow,
  .product-lightbox.is-full .product-lightbox__thumbs {
    visibility: hidden;
    opacity: 0;
  }

  .product-lightbox.is-full .product-lightbox__counter,
  .product-lightbox.is-full .product-lightbox__close {
    border-color: transparent;
    background-color: color-mix(in srgb, var(--color-background) 55%, transparent);
    -webkit-backdrop-filter: blur(12px);
    backdrop-filter: blur(12px);
  }

  /* A short fade-in of the full-screen image */
  @media (prefers-reduced-motion: no-preference) {
    .product-lightbox.is-full .product-lightbox__image {
      animation: product-lightbox-in var(--duration-normal) var(--ease-out);
    }
  }

  @keyframes product-lightbox-in {
    from {
      opacity: 0;
      scale: 0.97;
    }
  }

  /*
    Tablets and phones (Figma Variant89–104): counter and close on top, the image below at full width,
    the thumbnails underneath.
  */
  @media (max-width: 989px) {
    /* Phones: the image shares the height with the counter row and the thumbnails */
    .product-lightbox {
      --lightbox-image-max: 55svh;
    }

    /*
      Rows: counter + close / the image (a fixed height, so it never covers the thumbnails) / the
      thumbnails in the space left (they scroll when there are many)
    */
    .product-lightbox__inner {
      grid-template-columns: minmax(0, 1fr);
      grid-template-rows: auto var(--lightbox-image-max) minmax(0, 1fr);
      align-items: start;
      gap: var(--space-lg);
      padding: var(--space-md) var(--space-sm);
    }

    .product-lightbox__counter,
    .product-lightbox__close {
      position: static;
      grid-row: 1;
    }

    /* Column 1 too (with no column, the grid made a 2nd column for it and moved everything left) */
    .product-lightbox__counter {
      grid-column: 1;
      justify-self: start;
      padding: 0.4em 1em;
    }

    .product-lightbox__close {
      grid-column: 1;
      justify-self: end;
      inline-size: 2.75rem;
    }

    .product-lightbox__stage {
      grid-column: 1;
      grid-row: 2;
    }

    .product-lightbox__thumbs {
      grid-column: 1;
      grid-row: 3;
      justify-self: center;
      inline-size: min(100%, 20rem);
      max-block-size: 100%;
      padding: 4px;
    }

    .product-lightbox__inner--single {
      padding-inline-end: var(--space-sm);
    }

    .product-lightbox__thumb-column--1 {
      margin-block-start: 1.25rem;
    }

    .product-lightbox__thumb-column--3 {
      margin-block-start: 2.5rem;
    }

    /* The counter and close stay above the full-screen photo */
    .product-lightbox.is-full .product-lightbox__counter,
    .product-lightbox.is-full .product-lightbox__close {
      position: fixed;
      z-index: 2;
      inset-block-start: var(--space-md);
    }

    .product-lightbox.is-full .product-lightbox__counter {
      inset-inline-start: var(--space-sm);
    }

    .product-lightbox.is-full .product-lightbox__close {
      inset-inline-end: var(--space-sm);
    }
  }

/* snippets/product-media.liquid */

  .product-media {
    position: relative;
    block-size: 100%;
    overflow: hidden;
    border-radius: var(--radius-lg);
    background-color: var(--color-tint);
  }

  .product-media .image,
  .product-media :is(video, iframe, model-viewer) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    border: 0;
  }

  /*
    3D: Shopify's control script wraps <model-viewer> in its own div, which has no size of its own: it
    and the model were 0 x 0 (empty tile, the play button cut off in the corner). It fills the box
  */
  .product-media .shopify-model-viewer-ui {
    position: absolute;
    inset: 0;
  }

  /*
    Shopify's zoom / full screen column sits bottom right; in a small gallery tile it reached up to the
    gallery's "open viewer" button (top right). Bottom left instead (the image is not mirrored in RTL)
  */
  .product-media .shopify-model-viewer-ui .shopify-model-viewer-ui__controls-area {
    right: auto;
    left: 10px;
  }

  .product-media .image > img,
  .product-media video {
    block-size: 100%;
    object-fit: cover;
  }

/* snippets/product-row-card.liquid */

  /*
    Glass row (Figma Glass: Light 45deg 80%), like the search popup's product cards. No backdrop blur:
    only the plain page is behind the row (the blur also gave a dark band under the header on phones).
  */
  .product-row-card {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    padding: 0.625rem;
    padding-inline-end: var(--space-md);
    border-radius: 1rem;
    background-color: var(--color-glass-strong);
    box-shadow:
      0 4px 15px #b9b9b926,
      inset -1px 1px 0 #ffffffcc,
      inset 1px -1px 0 #ffffff80;
  }

  .product-row-card__link {
    display: flex;
    flex: 1;
    align-items: center;
    gap: 0.875rem;
    min-inline-size: 0;
    border-radius: 0.625rem; /* rounded focus ring */
    color: var(--color-text);
    text-decoration: none;
  }

  .product-row-card__media {
    flex: none;
    inline-size: 5.25rem;
    block-size: 5.25rem;
    overflow: hidden;
    border-radius: 0.625rem;
  }

  .product-row-card__media :is(img, svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .product-row-card__text {
    display: grid;
    gap: 0.1875rem;
    min-inline-size: 0;
  }

  .product-row-card__category {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: 0.2em;
    text-transform: uppercase;
  }

  .product-row-card__title {
    overflow: hidden;
    margin: 0;
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-sm);
    font-weight: 400;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .product-row-card__link:hover .product-row-card__title {
    text-decoration: underline;
  }

  /* Dark bold price (the price snippet uses the accent colour on the big product cards) */
  .product-row-card__price .price__current {
    color: var(--color-text);
    font-weight: 700;
  }

  .product-row-card__add {
    flex: none;
  }

/* snippets/product-sticky-bar.liquid */

  /*
    Figma 1920: x 375–1545 (1170 x 94), 24px above the bottom, a white glass card (radius ~24, soft
    shadow); image 70px (radius ~10); type in the heading font accent ~18px; title heading font ~26px;
    "15ML . QTY 1" grey caps ~14px wide spacing; price ~28px medium; Add to cart (outline glass) and
    Buy now (red), both 50px pills.
    Hidden: below the screen edge and see-through; shown (.is-visible): slides up.
  */
  .product-sticky-bar {
    position: fixed;
    z-index: 40;
    inset-block-end: max(var(--space-sm), calc(24 * var(--px, 0.0625rem)));
    inset-inline: 0;
    display: flex;
    justify-content: center;
    padding-inline: var(--page-margin);
    container-type: inline-size; /* the bar's layout follows its own width (see @container below) */
    pointer-events: none; /* the empty sides of the row let clicks through to the page */
    opacity: 0;
    translate: 0 calc(100% + 2rem);
    visibility: hidden;
    transition:
      translate var(--duration-normal) var(--ease-out),
      opacity var(--duration-normal) var(--ease-out),
      visibility 0s linear var(--duration-normal);
  }

  .product-sticky-bar.is-visible {
    opacity: 1;
    translate: 0 0;
    visibility: visible;
    transition:
      translate var(--duration-normal) var(--ease-out),
      opacity var(--duration-normal) var(--ease-out),
      visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    .product-sticky-bar,
    .product-sticky-bar.is-visible {
      translate: 0 0;
      transition: opacity var(--duration-fast) linear, visibility 0s;
    }
  }

  .product-sticky-bar__inner {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto auto;
    align-items: center;
    gap: var(--space-sm) max(var(--space-md), calc(40 * var(--px, 0.0625rem)));
    inline-size: min(100%, max(56rem, calc(1170 * var(--px, 0.0625rem))));
    padding: max(var(--space-sm), calc(12 * var(--px, 0.0625rem)));
    padding-inline-end: max(var(--space-md), calc(24 * var(--px, 0.0625rem)));
    border: 1px solid color-mix(in srgb, var(--color-background) 60%, transparent);
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-background) 82%, transparent);
    box-shadow: 0 10px 40px #0000001f;
    color: var(--color-text);
    pointer-events: auto;
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
  }

  /*
    Minimise: a round glass button with a ⌄ inside the bar, after Buy now, as tall as the buttons (50px).
    Hover / focus: accent ring and the chevron nudges down (it shows where the bar goes).
  */
  .product-sticky-bar .product-sticky-bar__minimize {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 3.125rem;
    block-size: 3.125rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-card-border);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-background) 70%, transparent);
    box-shadow: var(--shadow-glass-edge);
    color: var(--color-text);
    cursor: pointer;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .product-sticky-bar__minimize > span {
    display: inline-flex;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  .product-sticky-bar__minimize svg {
    inline-size: 0.875rem;
    block-size: auto;
  }

  .product-sticky-bar .product-sticky-bar__minimize:hover,
  .product-sticky-bar .product-sticky-bar__minimize:focus-visible {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-sticky-bar__minimize:hover > span {
      translate: 0 2px;
    }

    /* Minimised: the round cart pops in; opened again: the bar rises back */
    .product-sticky-bar.is-minimized .product-sticky-bar__mini {
      animation: sticky-bar-pop 0.45s var(--ease-out);
    }

    .product-sticky-bar.is-expanding .product-sticky-bar__inner {
      animation: sticky-bar-rise 0.35s var(--ease-out);
    }

    /*
      Minimise (the script closes the bar like a lens onto the minimise button): everything but that
      button fades, so the last thing left is the round button
    */
    .product-sticky-bar.is-minimizing :is(.product-sticky-bar__product, .product-sticky-bar__price, .product-sticky-bar__buttons > :not(.product-sticky-bar__minimize)) {
      opacity: 0;
      transition: opacity 0.2s ease-out;
    }

    /* Landed in the corner: two rings pulse out of the round cart and its icon wiggles */
    .product-sticky-bar.is-landed .product-sticky-bar__mini::after {
      content: "";
      position: absolute;
      inset: 0;
      border: 2px solid var(--color-button);
      border-radius: 50%;
      pointer-events: none;
      animation: sticky-bar-ripple 0.9s ease-out 2;
    }

    .product-sticky-bar.is-landed .product-sticky-bar__mini svg {
      animation: sticky-bar-wiggle 0.6s ease-in-out 0.1s;
    }
  }

  @keyframes sticky-bar-ripple {
    from {
      opacity: 0.7;
      scale: 1;
    }

    to {
      opacity: 0;
      scale: 1.9;
    }
  }

  @keyframes sticky-bar-wiggle {
    25% {
      rotate: -14deg;
    }

    50% {
      rotate: 10deg;
    }

    75% {
      rotate: -5deg;
    }
  }

  /* The round cart rises from below the screen edge with a small bounce */
  @keyframes sticky-bar-pop {
    0% {
      opacity: 0;
      translate: 0 calc(100% + 2rem);
    }

    70% {
      opacity: 1;
      translate: 0 -0.375rem;
    }

    100% {
      translate: 0 0;
    }
  }

  @keyframes sticky-bar-rise {
    from {
      opacity: 0;
      translate: 0 1rem;
    }
  }

  /* Minimised: only a round cart button in the bottom right corner; a click opens the bar again */
  .product-sticky-bar .product-sticky-bar__mini {
    position: relative;
    display: none;
    place-items: center;
    inline-size: 3.5rem;
    block-size: 3.5rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: var(--color-button);
    box-shadow: 0 6px 24px #00000033;
    color: var(--color-button-text);
    cursor: pointer;
    pointer-events: auto;
  }

  .product-sticky-bar__mini svg {
    inline-size: 1.375rem;
    block-size: 1.375rem;
  }

  .product-sticky-bar.is-minimized {
    justify-content: flex-end;
  }

  .product-sticky-bar.is-minimized .product-sticky-bar__inner {
    display: none;
  }

  .product-sticky-bar.is-minimized .product-sticky-bar__mini {
    display: grid;
  }

  .product-sticky-bar__product {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    min-inline-size: 0;
  }

  .product-sticky-bar__media {
    flex: none;
    overflow: hidden;
    inline-size: max(3.5rem, calc(70 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: max(0.5rem, calc(10 * var(--px, 0.0625rem)));
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 5%, var(--color-background)));
