  .product-sticky-bar__image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .product-sticky-bar__text {
    min-inline-size: 0;
  }

  .product-sticky-bar__text p {
    margin: 0;
  }

  .product-sticky-bar__type {
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body);
    line-height: 1.2;
  }

  .product-sticky-bar__title {
    overflow: hidden;
    font-family: var(--font-heading--family);
    font-size: var(--font-size-h3);
    line-height: 1.25;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .product-sticky-bar__meta {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background)); /* 60% = 4.35:1 on white */
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-sticky-bar__price {
    margin: 0;
    font-size: var(--font-size-h3);
    font-weight: var(--font-weight-medium);
    white-space: nowrap;
  }

  .product-sticky-bar__buttons {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
  }

  /*
    margin 0: the global form rule spaces a button that follows another button (button + button), which
    pushed Buy now 12px down. nowrap: a squeezed button grew to two lines (62px) instead of 50px.
  */
  .product-sticky-bar__buttons > .button {
    margin: 0;
    padding-inline: max(var(--space-md), calc(26 * var(--px, 0.0625rem)));
    white-space: nowrap;
  }

  /* While Buy buttons adds: the label dims a little and a small spinning ring takes the place of the icon */
  .product-sticky-bar__add.is-adding {
    cursor: progress;
  }

  .product-sticky-bar__add.is-adding .product-sticky-bar__icon {
    display: none;
  }

  .product-sticky-bar__add.is-adding [data-sticky-add-label] {
    opacity: 0.7;
  }

  .product-sticky-bar__add.is-adding::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    border: 2px solid color-mix(in srgb, currentcolor 25%, transparent);
    border-block-start-color: currentcolor;
    border-radius: 50%;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-sticky-bar__add.is-adding::before {
      animation: sticky-bar-spin 0.7s linear infinite;
    }
  }

  @keyframes sticky-bar-spin {
    to {
      rotate: 1turn;
    }
  }

  /* The icons sit on the middle of the label line (block svg: no space under it for text descenders) */
  .product-sticky-bar__icon {
    display: inline-flex;
    align-items: center;
  }

  .product-sticky-bar__icon svg {
    display: block;
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  /* Outline glass Add to cart: restated because the global button[type] rules outweigh one class */
  .product-sticky-bar .product-sticky-bar__add {
    border-color: var(--color-secondary-button-border);
    background-color: var(--color-secondary-button);
    color: var(--color-secondary-button-text);
    box-shadow: var(--shadow-glass-edge);
  }

  .product-sticky-bar .product-sticky-bar__add:hover:not(:disabled) {
    background-color: color-mix(in srgb, var(--color-secondary-button-text) 8%, var(--color-secondary-button));
  }

  .product-sticky-bar button:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }

  /*
    When the bar is narrower than ~60rem (laptops with large text, tablets): two rows, the product and
    price on top, the two buttons side by side below. Measured on the bar itself (container query), so it
    works at any screen width and text size.
  */
  @container (max-width: 60rem) {
    .product-sticky-bar__inner {
      grid-template-columns: minmax(0, 1fr) auto;
      gap: var(--space-sm) var(--space-md);
    }

    .product-sticky-bar__price {
      grid-column: 2;
      grid-row: 1;
    }

    .product-sticky-bar__buttons {
      grid-column: 1 / -1;
    }

    .product-sticky-bar__buttons > .button {
      flex: 1;
    }
  }

  /* Phones (Variant96-1): smaller title and price */
  @container (max-width: 40rem) {
    .product-sticky-bar__inner {
      padding: var(--space-sm);
    }

    .product-sticky-bar__title {
      font-size: var(--font-size-body-lg);
    }

    .product-sticky-bar__price {
      font-size: var(--font-size-body-lg);
    }

    /*
      Phones: the two buttons share the row with the minimise button (Figma Variant96-1); smaller text so
      the labels stay on one line and nothing goes past the screen edge
    */
    .product-sticky-bar__buttons > .button {
      flex: 1 1 0;
      min-inline-size: 0;
      gap: 0.25rem;
      padding-inline: 0.5rem;
      font-size: 0.6875rem;
      letter-spacing: 0.05em;
    }

    .product-sticky-bar__icon svg {
      inline-size: 1rem;
      block-size: 1rem;
    }
  }

/* snippets/quick-add.liquid */

  quick-add {
    display: block;
  }

  /*
    Overlay behind the round button (overlay: N): the glass button is white at 25%, so on a light photo
    it disappears. A soft dark circle, twice the button's size, fades out from its middle. The rest of
    the photo stays untouched. z-index -1 puts the circle behind the button but above the photo: the
    caller's position + z-index make the button its own stacking layer. :where() keeps this fallback
    position at zero specificity, so the caller's position: absolute always wins. The circle shows and
    hides with the button (same element).
  */
  :where(.quick-add--overlay) {
    position: relative;
  }

  .quick-add--overlay::before {
    content: "";
    position: absolute;
    inset: -50%;
    z-index: -1;
    border-radius: 50%;
    background: radial-gradient(
      closest-side,
      color-mix(in srgb, #000000 var(--quick-add-overlay, 0%), transparent),
      transparent
    );
    pointer-events: none;
  }

  .quick-add__form {
    margin: 0;
  }

  /*
    Figma "Liquid Glass Button": 50px circle, white at 25%, soft grey glow, white 17.5px cart.
    Scoped under .quick-add so it outranks the theme's general button[type="submit"] style.
  */
  .quick-add .quick-add__button {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: var(--quick-add-size, 50px);
    block-size: var(--quick-add-size, 50px);
    min-block-size: 0;
    margin: 0;
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    box-shadow: var(--glass-shadow), var(--glass-rim);
    color: var(--quick-add-color, #ffffff);
    cursor: pointer;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .quick-add .quick-add__button:hover {
    background-color: #ffffff59;
    box-shadow: var(--glass-shadow), var(--glass-rim); /* the theme's button:hover removes shadows */
  }

  .quick-add__button:focus-visible {
    outline: 2px solid #ffffff;
    outline-offset: 2px;
  }

  /*
    Pill (Figma article sidebar "🛒 ADD TO CART"): a white pill with the soft glass shadow, accent
    label and cart. Same two-class weight as the circle above, written after it, so it wins.
  */
  .quick-add--pill .quick-add__button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    inline-size: auto;
    padding-inline: var(--space-lg);
    background-color: var(--color-background);
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-decoration: none;
    text-transform: uppercase;
    white-space: nowrap;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .quick-add--pill .quick-add__button:hover {
    background-color: var(--color-accent);
    box-shadow: var(--shadow-header);
    color: var(--color-background);
  }

  .quick-add--pill .quick-add__button:focus-visible {
    outline-color: var(--color-accent);
  }

  .quick-add--pill .quick-add__button:disabled {
    background-color: var(--color-background);
    color: var(--color-text);
    cursor: default;
    opacity: 0.55;
  }

  /*
    The pill's cart stays in place while adding: the circle's drive-off distance is worked out from the
    circle's size and would run over the label. It tilts, then the gold tick pops in.
  */
  .quick-add--pill .quick-add__line {
    display: none;
  }

  quick-add.quick-add--pill.is-adding .quick-add__icon--tilt {
    animation: none;
  }

  /* The cart: both poses stacked; the tick sits on its top right */
  /* Cart icon: 17.5px in the 50px Figma button = 35% of the button */
  .quick-add__cart {
    position: relative;
    display: grid;
    inline-size: calc(var(--quick-add-size, 50px) * 0.35);
    block-size: calc(var(--quick-add-size, 50px) * 0.35);
  }

  .quick-add__icon {
    grid-area: 1 / 1;
    display: grid;
    place-items: center;
  }

  /*
    The three poses come from Figma with different canvas sizes (upright 19x19, tilted 21x21,
    slightly tilted 22x20) but the cart drawing is the same size in each. Each SVG is therefore drawn
    at its real size relative to the upright one (19 units = the icon box), centred in the same spot,
    so the cart keeps its scale when the poses swap instead of jumping.
  */
  .quick-add__icon svg {
    inline-size: 100%;
    block-size: 100%;
  }

  .quick-add__icon--tilt svg {
    inline-size: calc(100% * 21 / 19);
    block-size: calc(100% * 21 / 19);
  }

  .quick-add__icon--tilt {
    opacity: 0;
  }

  /*
    Custom icon (icon_image): the uploaded image at the icon size, its own colours. No icon (pill,
    show_icon: false): the box takes no room at rest and shows only while adding and added, before the
    text. Both: a spinner while adding, then the tick.
  */
  .quick-add__icon--custom img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: contain;
  }

  .quick-add__spinner {
    grid-area: 1 / 1;
    box-sizing: border-box;
    inline-size: 100%;
    block-size: 100%;
    border: 2px solid currentcolor;
    border-inline-end-color: transparent;
    border-radius: 50%;
    opacity: 0;
  }

  quick-add.is-adding .quick-add__icon--custom {
    opacity: 0;
  }

  quick-add.is-adding .quick-add__spinner {
    opacity: 1;
    animation: quick-add-spin 0.8s linear infinite;
  }

  .quick-add__cart--none {
    display: none;
  }

  quick-add:is(.is-adding, .is-added, .is-resetting) .quick-add__cart--none {
    display: grid;
  }

  /* No icon: the tick takes the spinner's place (there is no icon to sit on) */
  .quick-add__cart--none .quick-add__tick {
    position: static;
    grid-area: 1 / 1;
    inline-size: 100%;
    block-size: 100%;
  }

  @keyframes quick-add-spin {
    to { rotate: 1turn; }
  }

  /*
    Speed lines (Figma, in the 50px button): two 7px lines, 1px thick.
    Line 1: 30px from the top, 22px from the left. Line 2: 32px from the top, 19px from the left.
  */
  .quick-add__line {
    position: absolute;
    display: block;
    inline-size: 14%;
    block-size: max(1px, calc(var(--quick-add-size, 50px) * 0.02));
    border-radius: var(--radius-pill);
    background-color: currentcolor;
    opacity: 0;
  }

  /* Positions as % of the button (Figma px / 50), so they stay right at every button size */
  .quick-add__line--1 {
    inset-block-start: 60%;
    inset-inline-start: 44%;
  }

  .quick-add__line--2 {
    inset-block-start: 64%;
    inset-inline-start: 38%;
  }

  /* Gold circle with a white tick */
  .quick-add__tick {
    position: absolute;
    inset-block-start: -45%;
    inset-inline-end: -50%;
    display: grid;
    place-items: center;
    inline-size: 80%;
    block-size: 80%;
    border-radius: var(--radius-pill);
    background-color: #c8a24b;
    color: #ffffff;
    opacity: 0;
    scale: 0;
  }

  .quick-add__tick svg {
    inline-size: 65%;
    block-size: 65%;
  }

  /* Adding: tilt, speed lines, drive off right, roll back in from the left (1s) */
  quick-add.is-adding .quick-add__icon--upright {
    opacity: 0;
  }

  quick-add.is-adding .quick-add__icon--tilt {
    opacity: 1;
    animation: quick-add-drive 1s var(--ease-out) both;
  }

  quick-add.is-adding .quick-add__line {
    animation: quick-add-lines 1s linear both;
  }

  /*
    Added (Figma states 4 -> 5): the tick pops in while the cart is still tilted, then the tilted cart
    cross-fades into the upright one, which stays.
  */
  quick-add.is-added .quick-add__icon--tilt {
    animation: quick-add-tilt-out 0.6s var(--ease-out) both;
  }

  quick-add.is-added .quick-add__icon--upright {
    animation: quick-add-upright-in 0.6s var(--ease-out) both;
  }

  quick-add.is-added .quick-add__tick {
    animation: quick-add-tick 0.45s cubic-bezier(0.34, 1.56, 0.64, 1) both;
  }

  /* Back to the normal button when the "Added" card closes: the tick shrinks away (the cart stays) */
  quick-add.is-resetting .quick-add__tick {
    animation: quick-add-tick 0.3s ease-in reverse both;
  }

  quick-add.is-error .quick-add__button {
    animation: quick-add-shake 0.4s ease both;
  }

  /*
    Error message near the button: the reason a product can't be added (e.g. Shopify's "You can't add
    more ... to the cart." when the bag already holds all the stock). A small dark pill for 4 seconds. It is a popover (top layer, never cut off by a card): fixed position,
    the script writes --message-top / --message-left from the button's place (above it, else below,
    kept inside the screen). The resets undo the browser's popover box (centred, border, padding).
  */
  .quick-add__message {
    position: fixed;
    inset: auto;
    top: var(--message-top, 0);
    left: var(--message-left, 0);
    inline-size: max-content;
    max-inline-size: min(15rem, calc(100vw - 1rem));
    margin: 0;
    padding: 0.5rem 0.75rem;
    border: 0;
    border-radius: var(--radius-sm);
    background-color: #1f1f1fe6;
    color: #ffffff;
    font-size: var(--font-size-small);
    line-height: 1.4;
    text-align: start;
    pointer-events: none;
  }

  quick-add {
    position: relative;
  }

  /* hidden = off in every browser; browsers without popovers (Safari < 17) show it in place, fixed */
  .quick-add__message[hidden] {
    display: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    .quick-add__message:not([hidden]) {
      animation: quick-add-message 0.2s var(--ease-out);
    }
  }

  @keyframes quick-add-message {
    from {
      opacity: 0;
      translate: 0 0.25rem;
    }
  }

  /* One cross-fade from the tilted to the upright cart, after the tick has popped in */
  @keyframes quick-add-tilt-out {
    0%, 35% { opacity: 1; }
    100% { opacity: 0; }
  }

  @keyframes quick-add-upright-in {
    0%, 35% { opacity: 0; }
    100% { opacity: 1; }
  }

  /* Figma state 2: the tilted cart edges a few px right while the lines appear, then drives off */
  @keyframes quick-add-drive {
    0% { translate: 0 0; }
    20% { translate: calc(var(--quick-add-size, 50px) * 0.1) 0; }
    48% { translate: calc(var(--quick-add-size, 50px) * 0.9) 0; }
    48.01% { translate: calc(var(--quick-add-size, 50px) * -0.9) 0; }
    85%,
    100% { translate: 0 0; }
  }

  /* Speed lines only while the cart drives OFF (they'd cross the cart while it rolls back in) */
  @keyframes quick-add-lines {
    0% { opacity: 0; translate: calc(var(--quick-add-size, 50px) * 0.1) 0; }
    12% { opacity: 1; translate: 0 0; }
    38% { opacity: 1; translate: calc(var(--quick-add-size, 50px) * -0.06) 0; }
    48%, 100% { opacity: 0; translate: calc(var(--quick-add-size, 50px) * -0.06) 0; }
  }

  @keyframes quick-add-tick {
    from { opacity: 0; scale: 0; }
    to { opacity: 1; scale: 1; }
  }

  @keyframes quick-add-shake {
    0%, 100% { translate: 0 0; }
    25% { translate: -4px 0; }
    75% { translate: 4px 0; }
  }

  @media (prefers-reduced-motion: reduce) {
    quick-add.is-adding .quick-add__icon--upright {
      opacity: 1;
    }

    quick-add.is-adding :is(.quick-add__icon--tilt, .quick-add__line) {
      opacity: 0;
      animation: none;
    }

    quick-add.is-added .quick-add__icon--tilt {
      opacity: 0;
      animation: none;
    }

    quick-add.is-added .quick-add__icon--upright {
      opacity: 1;
      animation: none;
    }

    quick-add.is-added .quick-add__tick {
      animation: none;
      opacity: 1;
      scale: 1;
    }

    quick-add.is-resetting .quick-add__tick {
      animation: none;
    }

    quick-add.is-error .quick-add__button {
      animation: none;
    }

    /* The spinner stands still: the open ring still says "busy" */
    quick-add.is-adding .quick-add__spinner {
      animation: none;
    }
  }

/* snippets/screen-scale.liquid */

  .section--fill-screen {
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-block-size: 100svh;
  }

  /* The page's first section shares the screen with the header (20px gap + 77px pill = 6.0625rem) */
  #MainContent > .shopify-section:first-child .section--fill-screen {
    min-block-size: calc(100svh - 6.0625rem);
  }

  /*
    A top announcement bar sits in flow above everything and pushes the first section down, so take its
    height off too (same as the hero, see hero.liquid). The rule falls away when the bar is closed
    ([hidden]) or is the right-side band; .is-closing drops it as the bar collapses, so the section grows
    back in step. --announcement-size is set on :root by the announcement bar section (default 36px).
  */
  body:has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .section--fill-screen {
    min-block-size: calc(100svh - 6.0625rem - var(--announcement-size, 2.25rem));
  }

  /* "Right side" is a bar above the header below 990px (the band only exists from 990px), so it counts too */
  @media (max-width: 989px) {
    body:has(.announcement-bar--right:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .section--fill-screen {
      min-block-size: calc(100svh - 6.0625rem - var(--announcement-size, 2.25rem));
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    #MainContent > .shopify-section:first-child .section--fill-screen {
      transition: min-block-size var(--duration-base, 300ms) var(--ease-out);
    }
  }

  /*
    --px (one Figma pixel on this screen) sizes the cards, badges, icons and fields. Text and spacing
    are NOT tied to it (that made the text far bigger than normal on big screens): text uses the
    theme's normal sizes x --text-boost (the section's Text size setting, e.g. 1.1 = 10% bigger), and
    spacing stays normal, so extra room on a big screen stays as space.
  */
  .section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
    --text-boost: 1.1;

    --font-size-display: calc(clamp(3rem, 2.235rem + 3.14vw, 6rem) * var(--text-boost));
    --font-size-h1: calc(clamp(2.25rem, 1.868rem + 1.57vw, 3.75rem) * var(--text-boost));
    --font-size-h2: calc(clamp(1.75rem, 1.559rem + 0.784vw, 2.5rem) * var(--text-boost));
    --font-size-h3: calc(clamp(1.375rem, 1.311rem + 0.261vw, 1.625rem) * var(--text-boost));
    --font-size-body-lg: calc(clamp(1.125rem, 1.061rem + 0.261vw, 1.375rem) * var(--text-boost));
    --font-size-body: calc(clamp(1rem, 0.9363rem + 0.261vw, 1.25rem) * var(--text-boost));
    --font-size-body-sm: calc(clamp(0.9375rem, 0.8897rem + 0.196vw, 1.125rem) * var(--text-boost));
    --font-size-caption: calc(clamp(0.875rem, 0.8431rem + 0.131vw, 1rem) * var(--text-boost));
    --font-size-small: calc(clamp(0.8125rem, 0.7966rem + 0.0654vw, 0.875rem) * var(--text-boost));
    --font-size-label: calc(clamp(0.875rem, 0.8113rem + 0.261vw, 1.125rem) * var(--text-boost));
  }

  /*
    Outside a scaled section --px isn't set, so components fall back to 1px per Figma pixel
    (written as 0.0625rem): e.g. calc(66 * var(--px, 0.0625rem)) is 66px at the browser's
    default font size.
  */

/* snippets/search-popup.liquid */

  /* The custom element adds no box of its own: the search button stays a direct item of the header's row */
  .search-popup {
    display: contents;
  }

  /*
    The script hides groups with the hidden attribute. The browser's own [hidden] { display: none } is the
    weakest rule there is, so any class that sets display (e.g. the grid on .search-popup__start) would
    win and keep the group on screen. Two classes' worth of specificity puts hidden back in charge.
  */
  .search-popup [hidden] {
    display: none;
  }

  /*
    The popup (Figma: 1363px wide like the header pill, radius 50px, cream). showModal() puts the dialog in
    the browser's "top layer", above everything, so the sticky header's z-index and blur don't affect it.
    It drops in just under the pill, plus a small gap. The pill's real bottom edge changes (a top
    announcement bar above it, the smaller pill after scrolling, phones), so the script measures it on
    open and sets --search-popup-header. Without the script value: the desktop 20px gap + 77px pill.
  */
  .search-popup__dialog {
    --search-popup-top: calc(var(--search-popup-header, 1.25rem + 4.8125rem) + var(--space-sm));

    /*
      Shared sizes: the field's height, the close button and the room it needs. The close button lines up
      with the field and the results column keeps clear of it, both calculated from these.
    */
    --search-field-size: 3.125rem; /* 50px, Figma */
    --search-close-size: 2.375rem; /* 38px, Figma */
    --search-close-inset: var(--space-lg); /* from the panel's right edge */
    --search-close-gap: 0.75rem; /* between the field and the button */
    --search-panel-inline: var(--space-xl); /* the panel's side padding */

    /*
      Glass for the text panels of the product cards and the result rows (see "Glass" further down):
      the fill and the edges, used by .search-card__text and .search-link__text.
      The inner shadow (the frosted look of the Figma panels): one soft grey glow inside all four edges.
      No offset, so it is even on every side; 6% black keeps it light.
    */
    --search-glass-fill: #ffffff33;
    --search-glass-rim:
      inset -1px 1px 0 #ffffffcc,
      inset 1px -1px 0 #ffffff80,
      inset 0 0 0.75rem #0000000f;

    /*
      The header's wrapper sets pointer-events: none (so the page under the see-through strip stays
      clickable), and the dialog would inherit it even in the top layer. Turn clicks back on.
    */
    pointer-events: auto;
    inline-size: min(85.25rem, 100% - 2 * var(--space-md));
    max-inline-size: none;
    max-block-size: calc(100dvh - var(--search-popup-top) - var(--space-md));
    margin-block: var(--search-popup-top) auto;
    margin-inline: auto;
    padding: 0;
    border: 0;
    border-radius: var(--radius-lg);
    box-shadow: var(--glass-shadow);
    /*
      Up and down only. overflow-y: auto alone turns overflow-x into auto too, so a too-wide row would add a
      sideways bar; the result grids below already stop that, hidden is the safety net.
    */
    overflow-x: hidden;
    overflow-y: auto;
    overscroll-behavior: contain; /* scrolling the results doesn't scroll the page behind */
  }

  /*
    Scrollbar: a thin pill in the highlight colour instead of the grey system bar (like the filter drawer).
    Chrome, Edge and Safari: the ::-webkit-scrollbar rules. The 14px bar has a 4px clear border, so the
    visible thumb is 6px wide and sits 4px in from the edge. The track's margin keeps it out of the 50px
    round corners, which would otherwise cut its ends off.
    Chrome ignores these rules as soon as scrollbar-width / scrollbar-color are set, so those two are only
    for browsers without ::-webkit-scrollbar (Firefox: a thin bar, no track margin there).
  */
  .search-popup__dialog::-webkit-scrollbar {
    inline-size: 0.875rem;
  }

  .search-popup__dialog::-webkit-scrollbar-track {
    margin-block: 2.5rem;
    background: transparent;
  }

  .search-popup__dialog::-webkit-scrollbar-thumb {
    border: 0.25rem solid transparent;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 55%, transparent);
    background-clip: padding-box;
  }

  .search-popup__dialog::-webkit-scrollbar-thumb:hover {
    background-color: var(--color-accent);
  }

  @supports not selector(::-webkit-scrollbar) {
    .search-popup__dialog {
      scrollbar-width: thin;
      scrollbar-color: color-mix(in srgb, var(--color-accent) 55%, transparent) transparent;
    }
  }

  .search-popup__dialog::backdrop {
    background-color: #1f1f1f33;
  }

  /*
    Focus ring: the theme's usual ring (2px in the scheme's accent, critical.css). Inside the popup
    --color-accent is the gold highlight, too light for a ring on cream (WCAG asks 3:1), so the ring takes
    the scheme's own accent instead (--search-focus, brand red), like everywhere else on the site.
  */
  .search-popup__dialog :focus-visible {
    outline-color: var(--search-focus, var(--color-text));
  }

  .animations-on .search-popup__dialog[open] {
    animation: search-popup-in var(--duration-base) var(--ease-out);
  }

  @keyframes search-popup-in {
    from {
      opacity: 0;
      translate: 0 -0.75rem;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .animations-on .search-popup__dialog[open] {
      animation: none;
    }
  }

  /*
    The panel fills the whole dialog, so a click whose target is the <dialog> itself can only be a click
    on the dimmed backdrop outside it: that's how the script knows to close.
    A one-cell grid: the column and the close button share the cell (both in row 1, column 1), so the
    button can be position: sticky (it stays on screen while long results scroll) without taking room
    above the field. It stays after the form in the HTML, so focus still goes to the field first.
  */
  .search-popup__panel {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    padding-block: 2.5rem 3.5rem;
    padding-inline: var(--search-panel-inline);
  }

  .search-popup__inner,
  .search-popup__close {
    grid-area: 1 / 1;
  }

  /* The content column (Figma: 931px, the width of the field) */
  /*
    Room for the close button: from the panel's right edge it needs inset + button + gap; the panel's
    side padding already gives part of that, so the column keeps the rest free. The same room is kept on
    the left so the column stays centred. Without it, below ~1120px the button sat on the search field.
  */
  .search-popup__inner {
    --search-close-room: calc(
      var(--search-close-inset) + var(--search-close-size) + var(--search-close-gap) - var(--search-panel-inline)
    );

    inline-size: 100%;
    max-inline-size: min(58.1875rem, 100% - 2 * var(--search-close-room));
    margin-inline: auto;
  }

  .search-popup__form {
    position: relative;
  }

  /* Two classes, to beat the global input[type="search"] rule (element + attribute = higher specificity) */
  /* display: block: no inline text line around the field, so the form is exactly as tall as the field */
  .search-popup__form .search-popup__input {
    display: block;
    min-block-size: var(--search-field-size);
    padding-inline: var(--space-xl) 3.5rem; /* room for the magnifier on the right */
    border: 1px solid var(--color-accent);
    border-radius: var(--radius-pill);
    background-color: transparent;
    font-size: var(--font-size-body-sm);
  }

  /*
    Focused (Figma: the caret in the field, still the gold border): no dark ring, the border thickens and a
    soft glow appears instead. Gold on cream is under 3:1, on the M9 contrast list with the other golds.
  */
  .search-popup__form .search-popup__input:hover,
  .search-popup__form .search-popup__input:focus-visible {
    border-color: var(--color-accent);
  }

  .search-popup__form .search-popup__input:focus-visible {
    outline: none;
    box-shadow:
      inset 0 0 0 1px var(--color-accent),
      0 0 0 3px color-mix(in srgb, var(--color-accent) 25%, transparent);
  }

  .search-popup__form .search-popup__input::placeholder {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  /* The browser's own "x" in search fields: we already have the close button */
  .search-popup__input::-webkit-search-cancel-button {
    display: none;
  }

  /*
    The magnifier. Two classes, and every property the global button[type="submit"] rule sets is reset:
    that rule (element + attribute) beats one class and would draw the red pill button here.
  */
  .search-popup__form .search-popup__submit {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: 0.3125rem;
    translate: 0 -50%;
    display: grid;
    place-items: center;
    /* A 40px circle centred in the 50px field, so its focus ring is a full circle too */
    inline-size: 2.5rem;
    block-size: 2.5rem;
    min-block-size: 0;
    /*
      The global "space between form controls" rule (critical.css: a control after a control gets a 12px
      top margin) hits this button, because it comes right after the hidden options[prefix] input. That
      margin pushed the circle 12px below the centre.
    */
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background: none;
    box-shadow: none;
    color: var(--color-accent);
    cursor: pointer;
  }

  /* The global rule's :hover is stronger again (it adds a pseudo-class), so the hover needs its own reset */
  .search-popup__form .search-popup__submit:hover {
    background: none;
    color: var(--color-text);
  }

  .search-popup__submit svg {
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  /* The thin line under the field, as wide as the field */
  .search-popup__rule {
    inline-size: 100%;
    margin-block: 1.5rem 1.25rem;
    margin-inline: 0;
    border: 0;
    border-block-start: 1px solid var(--color-tint-border);
  }

  /*
    minmax(0, 1fr), not the default auto column: a grid column grows to its widest unbreakable content,
    and the titles are nowrap. With auto, a long article title widened the whole column past the panel
    (the sideways scrollbar). A 0 minimum keeps every column inside the panel, and the title ends in "…".
  */
  .search-popup__start,
  .search-popup__matches {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-xl);
  }

  .search-popup__heading {
    margin-block: 0 var(--space-md);
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: var(--font-size-body-lg);
    line-height: 1.2;
  }

  .search-popup__chips,
  .search-popup__products,
  .search-popup__links {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .search-popup__chips {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm) var(--space-md);
  }

  /* Recent searches and suggestions: soft beige pills. Trending: solid highlight colour, white text. */
  .search-popup__chip {
    display: inline-flex;
    align-items: center;
    min-block-size: 1.75rem;
    padding-block: 0.125rem;
    padding-inline: var(--space-md);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 22%, var(--color-background));
    box-shadow: 0 2px 6px #0000000d;
    color: var(--color-text);
    font-size: var(--font-size-caption);
    text-decoration: none;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .search-popup__chip:hover {
    background-color: color-mix(in srgb, var(--color-accent) 38%, var(--color-background));
  }

  .search-popup__chip--trending {
    min-block-size: 2.0625rem;
    background-color: var(--color-accent);
    color: #ffffff;
  }

  .search-popup__chip--trending:hover {
    background-color: color-mix(in srgb, var(--color-accent) 85%, #1f1f1f);
  }

  /* In suggestions, Shopify marks the part already typed ("<mark>rose</mark> petal"): a little bolder, not yellow */
  .search-popup__chip mark {
    background: none;
    color: inherit;
    font-weight: var(--font-weight-medium);
  }

  /*
    auto-fill (not auto-fit): the empty columns stay, so 1 or 2 results keep the width of a full row's
    card (about one third) instead of one card stretching over the whole 931px column. At most 3 per row
    (the 16rem minimum); 2 on tablets, 1 on phones.
  */
  .search-popup__products {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(16rem, 100%), 1fr));
    gap: var(--space-md) 1.25rem;
  }

  /* Grid items: min-inline-size 0, so a long nowrap title can't make its column wider than 1fr */
  .search-popup__products > *,
  .search-popup__link-groups > * {
    min-inline-size: 0;
  }

  /*
    Glass for the text panels of the product cards and the result rows (Figma Glass: fill #FFFFFF33,
    Light 45deg 80%, Frost 100). Light 45deg = the light comes from the top right, so a bright 1px rim on
    the top and right edges (80% white) and a weaker one bottom-left. Frost 100 (a backdrop blur) is left
    out: the panel behind is solid cream, so a blur shows nothing and only costs paint time.
    Refraction / Depth / Dispersion / Splay bend the background along the rim (an SVG filter that only
    Chrome supports) and are left out, as on every other glass element.
    The two values (--search-glass-fill, --search-glass-rim) are set on .search-popup__dialog at the top.
  */

  /* Product card (snippets/search-product-card.liquid; Figma 297 x 82: photo + glass panel) */
  /* The radius matches the photo and panel, so the focus ring (an outline follows border-radius) is rounded too */
  .search-card {
    display: flex;
    gap: 0.6875rem;
    border-radius: 0.5rem;
    color: var(--color-text);
    text-decoration: none;
  }

  .search-card__media {
    flex: none;
    inline-size: 5.125rem;
    block-size: 5.125rem;
    overflow: hidden;
    border-radius: 0.5rem;
    box-shadow: 0 4px 10px #0000001f;
  }

  .search-card__media :is(img, svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .search-card__text {
    display: flex;
    flex: 1;
    flex-direction: column;
    justify-content: center;
    gap: 0.125rem;
    min-inline-size: 0; /* lets a long title shorten with "…" instead of widening the card */
    padding-block: var(--space-xs);
    padding-inline: var(--space-md);
    border-radius: 0.5rem;
    background-color: var(--search-glass-fill);
    box-shadow: var(--search-glass-rim);
  }

  .search-card__category {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: 0.2em;
    text-transform: uppercase;
  }

  .search-card__title {
    overflow: hidden;
    font-size: var(--font-size-caption);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .search-card:hover .search-card__title {
    text-decoration: underline;
  }

  .search-card__price {
    font-size: var(--font-size-caption);
  }

  /* Figma: the price in dark bold here, not the accent colour the price snippet uses on product cards */
  .search-card__price .price__current {
    color: var(--color-text);
    font-weight: 700;
  }

  /* Collections, pages and articles: one column each, side by side, sharing the full width */
  .search-popup__link-groups {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(14rem, 100%), 1fr));
    gap: var(--space-lg) 1.25rem;
  }

  .search-popup__links {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-sm);
  }

  /* Result row (snippets/search-link-card.liquid): the product card's look, a size smaller */
  .search-link {
    display: flex;
    gap: 0.6875rem;
    border-radius: 0.5rem; /* rounded focus ring, like the product card */
    color: var(--color-text);
    text-decoration: none;
  }

  /* The picture, or the title's first letter on a soft highlight tile (pages have no picture) */
  .search-link__media {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 3.5rem;
    block-size: 3.5rem;
    overflow: hidden;
    border-radius: 0.5rem;
    background-color: color-mix(in srgb, var(--color-accent) 22%, var(--color-background));
    box-shadow: 0 4px 10px #0000001f;
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body-lg);
  }

  .search-link__media img {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .search-link__text {
    display: flex;
    flex: 1;
    flex-direction: column;
    justify-content: center;
    gap: 0.125rem;
    min-inline-size: 0;
    padding-inline: var(--space-md);
    border-radius: 0.5rem;
    background-color: var(--search-glass-fill);
    box-shadow: var(--search-glass-rim);
  }

  .search-link__title {
    overflow: hidden;
    font-size: var(--font-size-caption);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .search-link:hover .search-link__title {
    text-decoration: underline;
  }

  .search-link__meta {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
  }

  .search-popup__empty {
    margin: 0;
  }

  .search-popup__all {
    justify-self: start;
  }

  .search-popup__results[aria-busy='true'] {
    opacity: 0.6;
  }

  /*
    Close (Figma quick view: 38px round button, top right).
    In the panel's grid cell it starts at the top of the content, the same line as the field; the top
    margin centres it on the field's height. The negative end margin moves it from the panel's padding
    out to --search-close-inset from the edge.
    Sticky: once the results scroll, it stays --space-md under the top of the popup, so there is always a
    way out on touch screens (no Escape key). z-index keeps it above the scrolling cards.
  */
  .search-popup__close {
    position: sticky;
    inset-block-start: var(--space-md);
    z-index: 1;
    justify-self: end;
    align-self: start;
    display: grid;
    place-items: center;
    inline-size: var(--search-close-size);
    block-size: var(--search-close-size);
    margin-block-start: calc((var(--search-field-size) - var(--search-close-size)) / 2);
    margin-inline-end: calc(var(--search-close-inset) - var(--search-panel-inline));
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    /* Solid (mixed with the background, not see-through): it stays on top of scrolling cards */
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
    color: var(--color-text);
    cursor: pointer;
  }

  .search-popup__close:hover {
    background-color: color-mix(in srgb, var(--color-text) 12%, var(--color-background));
  }

  .search-popup__close svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  /* Small screens: the close button sits above the field instead of over it */
  @media (max-width: 749px) {
    .search-popup__dialog {
      --search-panel-inline: var(--space-md);
      --search-close-inset: var(--space-md);
    }

    .search-popup__panel {
      padding-block-start: 4rem;
    }

    /* The button is above the field here, so the column can use the full width again */
    .search-popup__inner {
      max-inline-size: none;
    }

    /* Pulled up from the field's line (4rem padding) to --space-md under the popup's top edge */
    .search-popup__close {
      margin-block-start: calc(var(--space-md) - 4rem);
    }
  }

/* snippets/share-links.liquid */

  .share-links__list {
    display: flex;
    align-items: center;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* isolation: isolate keeps the hover circle (z-index: -1) inside the button, under the icon */
  .share-links .share-links__item {
    position: relative;
    isolation: isolate;
    display: grid;
    place-items: center;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: inherit;
    cursor: pointer;
    transition: color var(--duration-normal) var(--ease-out);
  }

  /* Hover / keyboard focus, as on the footer's social icons: a circle grows from the centre */
  .share-links__item::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background-color: var(--share-hover-fill);
    transform: scale(0);
    transition: transform var(--duration-normal) var(--ease-out);
  }

  .share-links__item:hover::before,
  .share-links__item:focus-visible::before {
    transform: scale(1);
  }

  /* Reduced motion: the fill and colour change at once, no growing */
  @media (prefers-reduced-motion: reduce) {
    .share-links .share-links__item,
    .share-links__item::before {
      transition: none;
    }
  }

  .share-links__item svg {
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  /* Pill (the hero's hover state): one outlined glass pill, white icons, 50px tall */
  .share-links--pill .share-links__list {
    gap: var(--space-xs);
    block-size: 3.125rem;
    padding-inline: var(--space-md);
    border: 1px solid #ffffff;
    border-radius: var(--radius-pill);
    background-color: #ffffff1a;
    color: #ffffff;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .share-links--pill .share-links__item {
    --share-hover-fill: #ffffff33;
    inline-size: 2.25rem;
    aspect-ratio: 1;
    border-radius: 50%;
  }

  /* Round (sidebar, share row): 50px round glass buttons, accent icons */
  .share-links--round .share-links__list {
    flex-wrap: wrap;
    gap: var(--space-md);
    color: var(--color-accent);
  }

  .share-links--round .share-links__item {
    --share-hover-fill: var(--color-accent);
    inline-size: 3.125rem;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-background);
    box-shadow: var(--shadow-header);
  }

  .share-links--round .share-links__item:hover,
  .share-links--round .share-links__item:focus-visible {
    color: var(--color-background);
  }

/* snippets/social-icons.liquid */

  /* Figma: 50px circles, 23px apart (buttons start every 73px) */
  .social-icons {
    display: flex;
    flex-wrap: wrap;
    gap: 1.4375rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Same round "Liquid Glass" button as the header icons, in the white of the Figma footer */
  .social-icons__link {
    position: relative; /* the ::before fill is positioned against the button */
    isolation: isolate; /* keeps the fill's z-index: -1 inside the button, behind the icon */
    display: grid;
    place-items: center;
    inline-size: 3.125rem;
    block-size: 3.125rem;
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong);
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
    transition: color var(--duration-normal) var(--ease-out);
    /* No backdrop-filter: the icons sit on the footer's flat panel (nothing to blur), and on phones a
       blur under the floating header showed dark while the icons scrolled under it */
  }

  /*
    Hover (not in the Figma, our choice): an accent circle grows from the centre of the button
    (scale 0 -> 1) and the icon turns white. Only transform animates, which the browser can do on the
    GPU, so it stays smooth. Keyboard focus gets the same effect.
  */
  .social-icons__link::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background-color: var(--color-accent);
    transform: scale(0);
    transition: transform var(--duration-normal) var(--ease-out);
  }

  .social-icons__link:hover,
  .social-icons__link:focus-visible {
    color: var(--color-button-text);
  }

  .social-icons__link:hover::before,
  .social-icons__link:focus-visible::before {
    transform: scale(1);
  }

  /* Reduced motion: the fill and colour change at once, no growing */
  @media (prefers-reduced-motion: reduce) {
    .social-icons__link,
    .social-icons__link::before {
      transition: none;
    }
  }

  .social-icons__link svg {
    display: block;
  }

/* snippets/status-dot.liquid */

  .status-dot {
    position: relative;
    flex: none;
    inline-size: 0.375rem;
    block-size: 0.375rem;
    border-radius: 50%;
    background-color: var(--color-accent);
  }

  @media (prefers-reduced-motion: no-preference) {
    .status-dot::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: 50%;
      background-color: var(--color-accent);
      animation: status-dot-pulse 2s var(--ease-out) infinite;
    }
  }

  @keyframes status-dot-pulse {
    from {
      opacity: 0.6;
      transform: scale(1);
    }

    to {
      opacity: 0;
      transform: scale(4);
    }
  }

/* snippets/trending-article.liquid */

  /*
    Figma row: 1185 x 114, padding ~28px, 24px apart. Columns: number (~70px) | title + meta |
    pill | views (~150px) | 42px button. Figma px x --px follow the screen in a scaled section
    (snippets/screen-scale.liquid) and are exact px elsewhere.
  */
  .trending-article {
    position: relative;
    display: grid;
    grid-template-columns:
      max(3rem, calc(72 * var(--px, 0.0625rem))) minmax(0, 1fr) auto
      max(6rem, calc(150 * var(--px, 0.0625rem))) auto;
    grid-template-areas: "number text tag views arrow";
    align-items: center;
    column-gap: var(--space-lg);
    min-block-size: calc(114 * var(--px, 0.0625rem));
    padding: var(--space-md) max(var(--space-md), calc(33 * var(--px, 0.0625rem))) var(--space-md) max(var(--space-md), calc(28 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
    transition:
      transform var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  /* "01"–"05": the row's place in the list (counter set on the <ol>), very pale, decorative */
  .trending-article__number {
    grid-area: number;
    align-self: end;
    color: var(--color-tint);
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: max(2.5rem, calc(52 * var(--px, 0.0625rem)));
    font-variant-numeric: oldstyle-nums;
    line-height: 1;
  }

  .trending-article__number::before {
    counter-increment: trending-row;
    content: counter(trending-row, decimal-leading-zero);
  }

  .trending-article__text {
    grid-area: text;
  }

  .trending-article__title {
    margin: 0;
    font-size: var(--font-size-body-lg); /* 24px in the heading font */
    line-height: 1.3;
  }

  .trending-article__link {
    color: inherit;
    text-decoration: none;
  }

  /* The whole row is the link: the title link's ::after covers the row (position: relative) */
  .trending-article__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
  }

  /* "Author • Topic • 8 min" */
  .trending-article__meta {
    margin: var(--space-xs) 0 0;
    font-size: var(--font-size-body-sm);
  }

  .trending-article__meta > * + *::before {
    content: "•";
    margin-inline: 0.4em;
  }

  /* Topic pill: pale accent fill, accent border and text (like "Featured story") */
  .trending-article__tag {
    grid-area: tag;
    justify-self: end;
    padding: 0.25em 0.75em;
    border: 1px solid color-mix(in srgb, var(--color-accent) 40%, transparent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 15%, var(--color-card));
    color: var(--color-accent);
    font-size: var(--font-size-body);
    line-height: 1.3;
    white-space: nowrap;
  }

  /* The Figma grey (developer's choice, under 4.5:1): one variable, so M9 can darken it */
  .trending-article__views {
    grid-area: views;
    color: var(--trending-muted, color-mix(in srgb, var(--color-text) 65%, var(--color-background)));
    font-size: var(--font-size-small);
    white-space: nowrap;
  }

  /* 42px red circle, white arrow turned to ↗; it turns to → on hover */
  .trending-article__arrow {
    grid-area: arrow;
    display: grid;
    place-items: center;
    inline-size: max(2.25rem, calc(42 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-button);
    color: var(--color-button-text);
    box-shadow: var(--shadow-card);
  }

  .trending-article__arrow svg {
    inline-size: 40%;
    block-size: auto;
    transform: rotate(-45deg);
    transition: transform var(--duration-base) var(--ease-out);
  }

  .trending-article:has(.trending-article__link) {
    cursor: pointer;
  }

  .trending-article:has(.trending-article__link):hover,
  .trending-article:has(.trending-article__link:focus-visible) {
    box-shadow: var(--shadow-card-rose);
  }

  .trending-article:hover .trending-article__arrow svg,
  .trending-article:has(.trending-article__link:focus-visible) .trending-article__arrow svg {
    transform: rotate(0deg);
  }

  /* The keyboard focus ring goes round the whole row, not just the title */
  .trending-article__link:focus-visible {
    outline: none;
  }

  .trending-article:has(.trending-article__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  @media (prefers-reduced-motion: no-preference) {
    .trending-article:has(.trending-article__link):hover,
    .trending-article:has(.trending-article__link:focus-visible) {
      transform: translateY(-0.25rem);
    }
  }

  .trending-article--placeholder {
    opacity: 0.6;
  }

  /*
    Phones (design/inbox/blog-list/Variant14): a compact row. Number | title + meta | pill | arrow, with
    the views text under the arrow. The section removes the views row when no row has views.
  */
  @media (max-width: 749px) {
    .trending-article {
      grid-template-columns: 1.75rem minmax(0, 1fr) auto auto;
      grid-template-areas:
        "number text tag arrow"
        "number text tag views";
      column-gap: var(--space-xs);
      row-gap: 0.25rem;
      min-block-size: 0;
      padding: 0.625rem var(--space-sm);
    }

    .trending-article__number {
      align-self: center;
      font-size: 1.75rem;
    }

    .trending-article__title {
      font-size: 0.8125rem;
    }

    .trending-article__meta {
      margin-block-start: 0.25rem;
      font-size: 0.6875rem;
    }

    .trending-article__tag {
      align-self: center;
      font-size: 0.6875rem;
    }

    .trending-article__arrow {
      align-self: end;
      justify-self: center;
      inline-size: 1.5rem;
    }

    .trending-article__views {
      align-self: start;
      justify-self: center;
      font-size: 0.625rem;
    }
  }

/* snippets/trending-list.liquid */

  /* The rows change layout by the list's own width (container query), not by the screen width:
     the list can be a narrow sheet on a wide screen. */
  .trending-list {
    container-type: inline-size;
    display: flex;
    flex-direction: column;
    gap: clamp(2rem, 1rem + 3vw, 5rem);
  }

  .trending-list__header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-md);
  }

  .trending-list__heading {
    margin: 0;
    font-size: var(--font-size-display);
  }

  /* "Trending *Now*": the italic word in the accent colour (gold in the Dark scheme), not slanted */
  .trending-list__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* Custom sizes: the typed size at 1920px, shrinking in a straight line to the phone size */
  .trending-list__heading--custom {
    font-size: clamp(
      var(--fs-min),
      calc(var(--fs-min) + (100vw - 390px) * var(--fs-diff) / 1530),
      var(--fs-max)
    );
  }

  .trending-list__rows--custom {
    --title-size: clamp(
      var(--fs-min),
      calc(var(--fs-min) + (100vw - 390px) * var(--fs-diff) / 1530),
      var(--fs-max)
    );
  }

  /*
    Optional background image behind the list (Trending sheet / Trending products panel): it sits
    under the content (z-index -1 inside the panel's own stacking context) at the chosen opacity,
    over the panel's background colour.
  */
  .trending-bg {
    position: absolute;
    inset: 0;
    z-index: -1;
    opacity: var(--trending-bg-opacity, 0.3);
    pointer-events: none;
  }

  .trending-bg img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .trending-list__view-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
  }

  .trending-list__arrow svg {
    inline-size: 1em;
    block-size: auto;
  }

  .trending-list__rows {
    display: flex;
    flex-direction: column;
    gap: clamp(1.5rem, 1rem + 1.5vw, 3rem);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /*
    One row (wide list, Figma desktop): number · thumbnail · category over title · badge · price.
    The meta wrapper "disappears" (display: contents), so the category and the badge are grid items.
  */
  .trending-list__row {
    position: relative;
    display: grid;
    grid-template-columns: auto clamp(5rem, 4rem + 3vw, 7.5rem) minmax(0, 1fr) auto auto;
    grid-template-rows: auto auto;
    align-items: center;
    column-gap: clamp(1rem, 0.5rem + 1.5vw, 2.25rem);
  }

  .trending-list__number,
  .trending-list__thumb,
  .trending-list__badge,
  .trending-list__price {
    grid-row: 1 / span 2;
  }

  .trending-list__meta {
    display: contents;
  }

  .trending-list__category {
    grid-column: 3;
    grid-row: 1;
    align-self: end;
  }

  .trending-list__title {
    grid-column: 3;
    grid-row: 2;
    align-self: start;
  }

  /* No category (product without a type): the title takes both rows, centred like the rest of the row */
  .trending-list__row:not(:has(.trending-list__category)) .trending-list__title {
    grid-row: 1 / span 2;
    align-self: center;
  }

  .trending-list__badge {
    grid-column: 4;
    white-space: nowrap;
  }

  .trending-list__price {
    grid-column: 5;
  }

  /*
    Figma badge ("Hot", "New"): a pill with a faint accent fill, a thin accent edge and light accent text.
    Two classes, so it beats the one-class colour scheme class that product-badge adds (that scheme can be
    the same colour as the sheet, so the pill didn't show). A Badge entry with its own colours keeps them.
  */
  .trending-list__badge .product-card__badge {
    display: inline-block;
    padding: 0.25em 0.8em;
    border: 1px solid color-mix(in srgb, var(--color-accent) 55%, transparent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
    color: color-mix(in srgb, var(--color-accent) 75%, var(--color-text));
    font-size: var(--font-size-caption);
    line-height: 1.3;
  }

  /* Own colours: a thin edge in its text colour, so the pill shows also when its fill = the sheet colour */
  .trending-list__badge .product-card__badge--own-colors {
    border-color: color-mix(in srgb, var(--badge-fg) 45%, transparent);
    background-color: var(--badge-bg);
    color: var(--badge-fg);
  }

  .trending-list__badge:empty {
    display: none;
  }

  .trending-list__number {
    min-inline-size: 2ch;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-family: var(--font-heading--family);
    font-size: var(--font-size-h2);
    line-height: 1;
  }

  .trending-list__thumb {
    aspect-ratio: 3 / 2;
    overflow: hidden;
    background-color: var(--color-tint);
  }

  .trending-list__thumb > :is(img, svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .trending-list__category {
    margin: 0 0 var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .trending-list__title {
    margin: 0;
    font-size: var(--title-size, var(--font-size-h3));
    font-weight: var(--font-heading--weight);
  }

  /* The title's link covers the whole row: one click target, one tab stop per product */
  .trending-list__link {
    color: inherit;
    text-decoration: none;
  }

  .trending-list__link::after {
    content: "";
    position: absolute;
    inset: 0;
  }

  @media (hover: hover) {
    .trending-list__row:hover .trending-list__title {
      text-decoration: underline;
      text-decoration-thickness: 1px;
      text-underline-offset: 0.2em;
    }
  }

  /* Theme editor only: no products in the collection */
  .trending-list__note {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-small);
    font-style: italic;
  }

  .trending-list__link:focus-visible {
    outline: none;
  }

  .trending-list__row:has(.trending-list__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 0.5rem;
  }

  /* Figma: the price in white, bold, body font (the theme's price is accent-coloured elsewhere) */
  .trending-list__price .price__current {
    white-space: nowrap;
    color: var(--color-text);
    font-size: var(--font-size-body-lg);
    font-weight: 600;
  }

  .trending-list__price .price {
    justify-content: flex-end;
  }

  /*
    Narrow list (less than 40rem wide: phones, tablets, the sheet on small laptops), Figma mobile:
    number and photo on the left; category and badge on one line (the badge goes under the category
    when the line is too short), then the title, then the price. Sizes follow the list's width (cqi).
  */
  @container (max-width: 40rem) {
    .trending-list__row {
      grid-template-columns: auto clamp(3.5rem, 18cqi, 5rem) minmax(0, 1fr);
      grid-template-rows: none;
      gap: 0.25rem clamp(0.75rem, 4cqi, 1.25rem);
    }

    .trending-list__number,
    .trending-list__thumb {
      grid-row: 1 / span 3;
    }

    .trending-list__number {
      font-size: clamp(1.125rem, 7cqi, var(--font-size-h2));
    }

    .trending-list__meta {
      display: flex;
      flex-wrap: wrap;
      align-items: center;
      justify-content: space-between;
      gap: 0.25rem var(--space-xs);
      grid-column: 3;
    }

    .trending-list__title,
    .trending-list__price {
      grid-column: 3;
      grid-row: auto;
    }

    .trending-list__category {
      margin: 0;
    }

    /* Figma mobile: the badge at the right end of the category line (also when it wraps to its own line) */
    .trending-list__badge {
      margin-inline-start: auto;
    }

    .trending-list__badge .product-card__badge {
      padding: 0.15em 0.6em;
      font-size: 0.6875rem;
    }

    .trending-list__heading {
      font-size: min(var(--font-size-display), 16cqi);
    }

    .trending-list__heading--custom {
      font-size: min(clamp(var(--fs-min), calc(var(--fs-min) + (100vw - 390px) * var(--fs-diff) / 1530), var(--fs-max)), 16cqi);
    }

    .trending-list__title {
      font-size: min(var(--title-size, var(--font-size-h3)), max(0.9375rem, 6.5cqi));
    }

    .trending-list__price .price {
      justify-content: flex-start;
    }

    .trending-list__price .price__current {
      font-size: clamp(0.875rem, 6.5cqi, var(--font-size-body-lg));
    }
  }

  @media (max-width: 749px) {
    .trending-list__row--no-phone {
      display: none;
    }
  }

/* blocks/_banner-content.liquid */

  .banner-content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--banner-content-gap, 24px);
    max-inline-size: var(--banner-content-width, 760px);
  }

  .banner-content:not(:has(*)) {
    display: none;
  }

/* blocks/_blog-stat-card.liquid */

  /*
    Figma card: 354 x 195, padding ~36px, value ~52px (heading font, accent), 56px white icon circle at
    the top right, 2-line text 18px. Figma px x --px follow the screen in a scaled section
    (snippets/screen-scale.liquid) and are exact px elsewhere. Phones (Figma 375px): ~152px wide,
    value ~22px, icon circle ~28px, small text.
  */
  .blog-stat-card {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-content: start;
    column-gap: var(--space-md);
    min-block-size: calc(195 * var(--px, 0.0625rem));
    padding: max(var(--space-md), calc(30 * var(--px, 0.0625rem))) max(var(--space-md), calc(36 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
    box-shadow: var(--shadow-card-rose);
  }

  .blog-stat-card__value {
    grid-column: 1;
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: max(2.25rem, calc(52 * var(--px, 0.0625rem)));
    font-variant-numeric: oldstyle-nums;
    line-height: 1.1;
  }

  /* No value: the icon still sits in the top-right corner */
  .blog-stat-card__icon {
    grid-column: 2;
    grid-row: 1;
    display: grid;
    place-items: center;
    inline-size: max(2.75rem, calc(56 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-surface-raised);
    box-shadow: var(--shadow-card);
    color: var(--color-accent);
  }

  .blog-stat-card__icon svg {
    inline-size: 45%;
    block-size: auto;
  }

  .blog-stat-card__text {
    grid-column: 1 / -1;
    max-inline-size: 16em;
    margin: var(--space-lg) 0 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  .blog-stat-card--empty .blog-stat-card__text {
    margin: 0;
    font-style: italic;
  }

  /*
    Sizes by the width of the section's collage (container "blog-hero-cards"), not the screen: the
    stacked layout runs up to 1439px, so the card width decides. Below 50rem (tablets, 1440px
    desktop): medium. Below 36rem (phones, cards ~150px): the phone design.
  */
  @container blog-hero-cards (width < 50rem) {
    .blog-stat-card {
      padding: var(--space-md) var(--space-lg);
    }

    .blog-stat-card__value {
      font-size: 1.875rem;
    }

    .blog-stat-card__icon {
      inline-size: 2.25rem;
    }

    .blog-stat-card__text {
      margin-block-start: var(--space-md);
      font-size: var(--font-size-small);
      line-height: 1.5;
    }
  }

  @container blog-hero-cards (width < 36rem) {
    .blog-stat-card {
      column-gap: var(--space-xs);
      padding: var(--space-md) var(--space-sm) var(--space-md) var(--space-md);
      border-radius: var(--radius-sm);
    }

    .blog-stat-card__value {
      font-size: 1.375rem;
    }

    .blog-stat-card__icon {
      inline-size: 1.75rem;
    }

    .blog-stat-card__text {
      margin-block-start: var(--space-sm);
      font-size: 0.75rem;
      line-height: 1.45;
    }
  }

/* blocks/_chapter.liquid */

  /*
    Figma 1920 (Default-14): content x 308, max ~1070 wide; label y 248; heading 76px bold, 2 lines
    (y 285–415); text 24px / 38px (y 445–630); rule y 686 (1px, accent ~60%, ~940 long); stat y 735:
    value 36px bold + label (label style). Sizes: Figma px x --px with rem floors, or tokens.
    The section sets --chapter-text (white) and --chapter-accent (the label colour setting).
  */
  .chapter {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    min-block-size: 100svh;
    /* The same space above (clear of the header pill) and below, so the words sit in the screen's middle */
    padding-block: max(6.5rem, calc(130 * var(--px)));
    padding-inline: var(--chapter-indent) var(--page-margin);
  }

  /* The photo or video fills the chapter (or, moved by the script, the section's sticky layer) */
  .chapter__media {
    position: absolute;
    inset: 0;
    z-index: -1;
    overflow: hidden;
    background-color: #1f1f1f;
  }

  /*
    The dark overlay keeps the white words readable: clear at the top, darkest (70%) just under the
    middle where the words are, 50% at the bottom (the developer's values). The section's Overlay
    setting scales it (100% = as designed).
  */
  .chapter__media::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, #00000000 0%, #000000b3 43.71%, #00000080 100%);
    opacity: var(--chapter-overlay, 1);
  }

  .chapter__media .image,
  .chapter__video {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .chapter__content {
    max-inline-size: max(20rem, calc(1070 * var(--px)));
    color: var(--chapter-text);
  }

  .chapter__label {
    margin: 0 0 max(var(--space-md), calc(30 * var(--px)));
    color: var(--chapter-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .chapter__heading {
    margin: 0;
    max-inline-size: 18ch;
    color: inherit;
    font-family: var(--font-heading--family);
    font-size: max(1.75rem, calc(76 * var(--px)));
    font-weight: 700;
    line-height: 1;
    text-wrap: balance;
  }

  .chapter__text {
    margin-block-start: max(var(--space-lg), calc(45 * var(--px)));
    font-size: var(--font-size-body-lg);
    line-height: 1.6;
  }

  .chapter__text > * {
    margin: 0;
  }

  .chapter__text > * + * {
    margin-block-start: var(--space-md);
  }

  /* The rule above the stat: the accent at ~60% */
  .chapter__stat {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-xs) var(--space-sm);
    max-inline-size: max(16rem, calc(940 * var(--px)));
    margin: max(var(--space-xl), calc(70 * var(--px))) 0 0;
    padding-block-start: max(var(--space-lg), calc(30 * var(--px)));
    border-block-start: 1px solid color-mix(in srgb, var(--chapter-accent) 60%, transparent);
  }

  .chapter__stat-value {
    font-family: var(--font-body--family);
    font-size: max(1.5rem, calc(36 * var(--px)));
    font-weight: 700;
    line-height: 1;
  }

  .chapter__stat-label {
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /*
    With the story script running (data-ready) and motion allowed, a chapter's words fade up when
    its top reaches 70% down the screen (is-active), like Default-1 (the photo first, then the
    words). No JS, animations off or reduced motion: always visible.
  */
  @media (prefers-reduced-motion: no-preference) {
    .animations-on about-chapters[data-ready] .chapter__content {
      opacity: 0;
      translate: 0 2rem;
      transition:
        opacity var(--duration-slow) var(--ease-out),
        translate var(--duration-slow) var(--ease-out);
    }

    .animations-on about-chapters[data-ready] .chapter.is-active .chapter__content {
      opacity: 1;
      translate: 0 0;
    }
  }

  /* Theme editor only: a Chapter block with no content */
  .about-chapters__chapter-note {
    position: relative;
    margin: 0;
    padding: var(--space-xl) var(--page-margin);
    color: #ffffff;
    font-style: italic;
    text-align: center;
  }

  /*
    Phones (Variant45-1 to Variant48, 375px): label ~9px, heading ~26px, text ~12px / 1.6, stat
    value ~16px and label ~9px, no rule above the stat. Fixed rem sizes: the scaled section
    multiplies the text tokens by Text size. The words start ~80px in (--chapter-indent, set by
    the section), clear of the 01–04 nav. Less space above and below, so a 667px tall phone still
    shows a long chapter in one screen.
  */
  @media (max-width: 749px) {
    .chapter {
      padding-block: 6.5rem 3rem; /* the top stays clear of the header pill */
    }

    .chapter__label {
      margin-block-end: 0.625rem;
      font-size: 0.5625rem;
      letter-spacing: 0.1em;
    }

    .chapter__heading {
      font-size: 1.625rem;
      line-height: 1.2;
    }

    .chapter__text {
      margin-block-start: 0.875rem;
      font-size: 0.75rem;
      line-height: 1.6;
    }

    .chapter__text > * + * {
      margin-block-start: var(--space-sm);
    }

    .chapter__stat {
      gap: var(--space-xs);
      margin-block-start: var(--space-xl);
      border-block-start: 0;
      padding-block-start: 0;
    }

    .chapter__stat-value {
      font-size: 1rem;
    }

    .chapter__stat-label {
      font-size: 0.5625rem;
      letter-spacing: 0.1em;
    }
  }

/* blocks/_contact-channel.liquid */

  /*
    Figma card: 408 x 468px. Made roomier on purpose (developer, 2026-10-30): bigger badge, title and
    text, more padding, at least 520 Figma px tall. Sizes in Figma px x --px follow the screen in a
    scaled section (snippets/screen-scale.liquid) and are exact px elsewhere.
    Column layout, so the bottom link can be pushed to the bottom of the card (margin-block-start:
    auto) and all links line up when the texts have different lengths.
  */
  .contact-channel {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    padding: var(--space-xl) var(--space-2xl) var(--space-2xl);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
  }

  /* 80px circle, 40px icon (Figma 66 / 34, enlarged). The pale fill is the scheme's border colour */
  .contact-channel__badge {
    display: grid;
    place-items: center;
    inline-size: max(4.125rem, calc(80 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-border);
    color: var(--color-accent);
  }

  .contact-channel__badge svg {
    inline-size: max(2.125rem, calc(40 * var(--px, 0.0625rem)));
    block-size: auto;
  }

  .contact-channel__label {
    margin: var(--space-lg) 0 0; /* 20px under the badge */
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
  }

  /* The Figma title is in the body font (not the serif headings); 26px (Figma 22, enlarged) */
  .contact-channel__title {
    margin: var(--space-2xs) 0 0;
    font-family: var(--font-body--family);
    font-style: var(--font-body--style);
    font-weight: var(--font-weight-medium);
    font-size: var(--font-size-h3);
    line-height: var(--line-height-body);
  }

  .contact-channel__value {
    margin: var(--space-xs) 0 0;
    font-size: var(--font-size-body-lg);
  }

  /* A long email address may break anywhere; a phone number stays on one line */
  .contact-channel__value--email {
    overflow-wrap: anywhere;
  }

  .contact-channel__value--phone,
  .contact-channel__value--whatsapp {
    white-space: nowrap;
  }

  .contact-channel__value a {
    color: var(--color-accent);
    text-decoration: none;
  }

  .contact-channel__value a:hover {
    text-decoration: underline;
  }

  .contact-channel__text {
    margin-block-start: var(--space-sm);
    font-size: var(--font-size-body-lg);
    line-height: var(--line-height-body);
  }

  .contact-channel__status {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
    margin: var(--space-lg) 0 0;
    padding-inline-start: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
  }

  /* Pushed to the bottom of the card; at least 32px under the text */
  .contact-channel__footer {
    margin: auto 0 0;
    padding-block-start: var(--space-xl);
  }

  /*
    "SEND EMAIL →": the underline runs under the text AND the arrow (Figma), so it's a 1px background
    line rather than text-decoration (which skips the icon). 2px on hover, and the arrow moves right.
  */
  .contact-channel__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    padding-block-end: var(--space-xs);
    background: linear-gradient(currentcolor, currentcolor) left bottom / 100% 1px no-repeat;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-decoration: none;
    text-transform: uppercase;
  }

  .contact-channel__link:hover {
    background-size: 100% 2px;
  }

  .contact-channel__link svg {
    flex: none;
    inline-size: max(1.125rem, calc(20 * var(--px, 0.0625rem)));
    block-size: auto;
    transition: transform var(--duration-fast) var(--ease-out);
  }

  @media (prefers-reduced-motion: no-preference) {
    .contact-channel__link:hover svg {
      transform: translateX(0.25rem);
    }
  }

  /* RTL: the arrow points the other way */
  .contact-channel__link:dir(rtl) svg {
    scale: -1 1;
  }

  /* 4 per row (from 1440px): at least 520 Figma px tall */
  @media (min-width: 1440px) {
    .contact-channel {
      min-block-size: calc(520 * var(--px, 0.0625rem));
    }
  }

  /* Tablets, small laptops and the first 4-per-row widths: less padding */
  @media (min-width: 750px) and (max-width: 1599px) {
    .contact-channel {
      padding: var(--space-lg) var(--space-xl) var(--space-xl);
    }
  }

  /* Phones (phone design): compact cards, small text */
  @media (max-width: 749px) {
    .contact-channel {
      padding: var(--space-sm) var(--space-sm) var(--space-md);
      border-radius: var(--radius-sm);
    }

    .contact-channel__badge {
      inline-size: 2rem;
    }

    .contact-channel__badge svg {
      inline-size: 1rem;
    }

    .contact-channel__label {
      margin-block-start: var(--space-sm);
      font-size: 0.625rem;
    }

    .contact-channel__title {
      font-size: var(--font-size-body);
    }

    .contact-channel__value,
    .contact-channel__text,
    .contact-channel__status {
      font-size: 0.75rem;
    }

    .contact-channel__status {
      gap: var(--space-sm);
      margin-block-start: var(--space-sm);
    }

    .contact-channel__footer {
      padding-block-start: var(--space-md);
    }

    .contact-channel__link {
      gap: var(--space-xs);
      font-size: 0.625rem;
    }

    .contact-channel__link svg {
      inline-size: 0.75rem;
    }
  }

  .contact-channel--empty {
    justify-content: center;
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    font-style: italic;
    text-align: center;
  }

/* blocks/_discipline.liquid */

  /*
    Figma 1920 (card x 872–1868): number x 954, name x 1012 (heading font ~64px), count right
    (label); rows ~106px tall with a 1px rule under each. Open: photo 318 x 268 (radius ~10), the
    text ~54px to its right. Sizes are Figma px x --px (screen-scale) with rem floors, or tokens.
  */
  .discipline {
    counter-increment: discipline;
    border-block-end: 1px solid var(--color-border);
  }

  .discipline__summary {
    display: grid;
    grid-template-columns: max(2rem, calc(58 * var(--px))) minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--space-sm);
    padding-block: max(var(--space-sm), calc(18 * var(--px)));
    cursor: pointer;
    list-style: none;
  }

  /* No browser triangle */
  .discipline__summary::-webkit-details-marker {
    display: none;
  }

  .discipline__number::before {
    content: counter(discipline, decimal-leading-zero);
  }

  .discipline__number,
  .discipline__count {
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .discipline__number {
    color: var(--color-accent);
  }

  .discipline__title {
    font-family: var(--font-heading--family);
    font-size: max(2rem, calc(64 * var(--px)));
    font-weight: var(--font-heading--weight);
    line-height: 1.2;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .discipline[open] .discipline__title {
    color: var(--color-accent);
  }

  @media (hover: hover) {
    .discipline__summary:hover .discipline__title {
      color: var(--color-accent);
    }
  }

  .discipline__panel {
    display: grid;
    grid-template-columns: minmax(0, 318fr) minmax(0, 450fr);
    align-items: start;
    gap: max(var(--space-lg), calc(54 * var(--px)));
    padding-block: max(var(--space-sm), calc(16 * var(--px))) max(var(--space-md), calc(24 * var(--px)));
  }

  /* No photo on the store: the text takes the whole row */
  .discipline__panel--no-media {
    grid-template-columns: minmax(0, 1fr);
  }

  /* Theme editor only: a Discipline block with no content */
  .about-hero__discipline-note {
    margin: 0;
    padding-block: var(--space-sm);
    border-block-end: 1px solid var(--color-border);
    font-size: var(--font-size-small);
    font-style: italic;
    opacity: 0.75;
  }

  /*
    Opening and closing glide (only with motion allowed). ::details-content is the part of a
    <details> under its summary: its height goes 0 → auto, which interpolate-size lets the browser
    animate; content-visibility waits (allow-discrete) so the closing row stays visible while it
    shrinks. The panel fades at the same time. Browsers without these features open at once.
  */
  @media (prefers-reduced-motion: no-preference) {
    @supports selector(::details-content) {
      .discipline {
        interpolate-size: allow-keywords;
      }

      .discipline::details-content {
        block-size: 0;
        overflow: clip;
        transition:
          block-size var(--duration-slow) var(--ease-out),
          content-visibility var(--duration-slow) allow-discrete;
      }

      .discipline[open]::details-content {
        block-size: auto;
      }

      .discipline__panel {
        opacity: 0;
        transition: opacity var(--duration-slow) var(--ease-out);
      }

      .discipline[open] .discipline__panel {
        opacity: 1;
      }
    }
  }

  .discipline__media {
    overflow: hidden;
    aspect-ratio: 318 / 268;
    border-radius: var(--radius-xs);
    background-color: var(--color-tint-subtle);
  }

  .discipline__media img,
  .discipline__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .discipline__body {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: max(var(--space-md), calc(40 * var(--px)));
    padding-block-start: max(var(--space-sm), calc(30 * var(--px)));
  }

  .discipline__text {
    font-size: var(--font-size-body-lg);
    line-height: 1.6;
  }

  .discipline__text > * {
    margin: 0;
  }

  .discipline__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
    text-decoration: none;
  }

  /* The → icon turned to ↗; it lifts a little more on hover */
  .discipline__link-arrow svg {
    display: block;
    inline-size: 1em;
    block-size: auto;
    rotate: -45deg;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .discipline__link:hover .discipline__link-arrow svg {
      translate: 0.15em -0.15em;
    }
  }

  /*
    Phones (mobile export Variant45, 375px): a smaller name so it never runs into the count, the
    count on the open row only, and the photo kept beside the text (~135px : the rest). Fixed rem
    sizes: the scaled section multiplies the text tokens by Text size. Number ~8px, count ~9px.
  */
  @media (max-width: 749px) {
    .discipline__summary {
      gap: var(--space-xs);
    }

    .discipline__number {
      font-size: 0.5rem;
    }

    .discipline__count {
      font-size: 0.5625rem;
      letter-spacing: 0.1em;
    }

    .discipline__title {
      font-size: 1.75rem;
      overflow-wrap: anywhere;
    }

    .discipline:not([open]) .discipline__count {
      display: none;
    }

    .discipline__panel {
      grid-template-columns: minmax(0, 135fr) minmax(0, 155fr);
      gap: var(--space-md);
    }

    .discipline__body {
      gap: var(--space-md);
      padding-block-start: var(--space-sm);
    }

    .discipline__text,
    .discipline__link {
      font-size: 0.75rem;
    }
  }

/* blocks/_faq-question.liquid */

  /*
    Figma 1920 (Default-1): rows 712 x 68, one every 95px (gap ~27); "01" body ~20px accent and the
    question body ~22px; the left edge is a thin pale accent "(" (a 2px border, rounded by the
    section's "Question corner radius" setting, --faq-row-radius, default 19px). Open / active: fill
    accent ~5%, radius on the right too, accent edge, accent question.
  */
  /* Only real questions are numbered (not the editor's note row for an incomplete one) */
  .faq-question:not(.faq-question--empty) {
    counter-increment: faq-question;
  }

  /* Shared by the <summary> (no JS) and the script's <button> */
  .faq-question__row {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    inline-size: 100%;
    min-block-size: max(3.25rem, calc(68 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    margin: 0;
    padding: var(--space-sm) var(--space-lg) var(--space-sm) max(var(--space-md), calc(22 * var(--px, 0.0625rem)));
    border: 0;
    border-inline-start: 2px solid color-mix(in srgb, var(--color-accent) 30%, transparent);
    /* Full pill radius always: without a fill only the left "(" edge shows; with the hover or active fill the right end is round too */
    border-radius: var(--faq-row-radius, 19px);
    background: none;
    color: var(--color-text);
    font-family: var(--font-body--family);
    font-size: max(1.0625rem, calc(22 * var(--px, 0.0625rem)));
    font-weight: inherit;
    line-height: 1.35;
    text-align: start;
    list-style: none;
    cursor: pointer;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out),
      border-color var(--duration-fast) var(--ease-out);
  }

  .faq-question__row::-webkit-details-marker {
    display: none;
  }

  .faq-question__number::before {
    content: counter(faq-question, decimal-leading-zero);
  }

  .faq-question__number {
    flex-shrink: 0;
    color: var(--color-accent);
    font-size: 0.9em;
    font-variant-numeric: tabular-nums;
  }

  .faq-question__row:hover {
    background-color: color-mix(in srgb, var(--color-accent) 3%, transparent);
  }

  .faq-question__details[open] > .faq-question__row,
  .faq-question.is-active > .faq-question__row {
    border-inline-start-color: var(--color-accent);
    background-color: color-mix(in srgb, var(--color-accent) 5%, transparent);
    color: var(--color-accent);
  }

  .faq-question__answer {
    padding: var(--space-md) var(--space-lg) var(--space-lg) calc(var(--space-lg) + 2.5ch);
    line-height: 1.6;
  }

  .faq-question__answer > div > * {
    margin: 0;
  }

  .faq-question__answer > div > * + * {
    margin-block-start: var(--space-sm);
  }

  /* With the script the answer lives in the answer card and the button is the row */
  .faq[data-ready] .faq-question__details {
    display: none;
  }

  .faq-question--empty {
    margin: 0;
    padding: var(--space-sm) var(--space-lg);
    border-inline-start: 2px dashed color-mix(in srgb, var(--color-accent) 30%, transparent);
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    font-style: italic;
  }

  /* Phones (faq-mobile): small rows */
  @media (max-width: 749px) {
    .faq-question__row {
      gap: var(--space-sm);
      min-block-size: 2.25rem;
      padding: var(--space-2xs) var(--space-md) var(--space-2xs) var(--space-sm);
      font-size: 0.8125rem;
    }
  }

/* blocks/_faq-topic.liquid */

  /*
    Figma 1920 ("Default"): card 322 x 268, radius ~24, 1px pale border, soft shadow, padding ~25;
    icon 48px circle (1px pale accent ring); number heading font thin ~90px, accent 20%, top right,
    cut by the card's top edge; title heading font ~28px; line body ~16px; "4 ANSWERS" accent
    label; 42px red arrow circle (↗). Hover (card 05): a pale circle with an accent →, more shadow.
    Panel ("Default-1"): left column 712 (head + questions), right answer card 793 x ~433.
  */

  /* The block's wrappers don't take part in the layout: the card and the panel are the grid items */
  .faq-topic {
    display: contents;
  }

  .faq-topic__card {
    counter-increment: faq-topic;
    position: relative;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-block-size: max(14rem, calc(268 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    padding: max(var(--space-md), calc(25 * var(--px, 0.0625rem))) max(var(--space-md), calc(27 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-accent) 1%, var(--color-background));
    box-shadow: var(--shadow-card);
    color: var(--color-text);
    text-decoration: none;
  }

  /* "01", "02"…: cut by the card's top edge (it starts above it) */
  .faq-topic__number::before {
    content: counter(faq-topic, decimal-leading-zero);
  }

  .faq-topic__number {
    position: absolute;
    inset-block-start: -0.32em;
    inset-inline-end: max(0.25rem, calc(8 * var(--px, 0.0625rem)));
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-family: var(--font-heading--family);
    font-size: max(3.5rem, calc(90 * var(--px, 0.0625rem)));
    font-weight: var(--font-heading--weight);
    line-height: 1;
    pointer-events: none;
  }

  .faq-topic__icon {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: max(2.5rem, calc(48 * var(--px, 0.0625rem)));
    block-size: max(2.5rem, calc(48 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    border: 1px solid color-mix(in srgb, var(--color-accent) 15%, transparent);
    border-radius: 50%;
    background-color: var(--color-background);
    color: var(--color-accent);
  }

  .faq-topic__icon svg,
  .faq-topic__icon img {
    inline-size: max(1.125rem, calc(20 * var(--px, 0.0625rem)));
    block-size: max(1.125rem, calc(20 * var(--px, 0.0625rem)));
  }

  /* Custom icon: the whole image shows in the box, in its own colours */
  .faq-topic__icon img {
    display: block;
    object-fit: contain;
  }

  .faq-topic__title {
    margin-block-start: max(var(--space-lg), calc(38 * var(--px, 0.0625rem)));
    font-family: var(--font-heading--family);
    font-size: max(1.375rem, calc(28 * var(--px, 0.0625rem)));
    line-height: 1.2;
  }

  .faq-topic__text {
    margin-block-start: max(var(--space-sm), calc(18 * var(--px, 0.0625rem)));
    font-size: var(--font-size-caption);
    line-height: 1.45;
  }

  .faq-topic__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
    margin-block-start: auto;
    padding-block-start: var(--space-lg);
  }

  .faq-topic__count {
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    letter-spacing: 0.15em;
    text-transform: uppercase;
  }

  /* The arrow: a red circle with ↗ (the solid → icon turned); hover: a pale circle with → */
  .faq-topic__arrow {
    --arrow-size: max(2.25rem, calc(42 * var(--px, 0.0625rem)));

    display: grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: var(--arrow-size);
    block-size: var(--arrow-size);
    box-sizing: border-box;
    border: 1px solid var(--color-button);
    border-radius: 50%;
    background-color: var(--color-button);
    box-shadow: var(--shadow-button);
    color: var(--color-button-text);
    transition:
      background-color var(--duration-base) var(--ease-out),
      border-color var(--duration-base) var(--ease-out),
      color var(--duration-base) var(--ease-out),
      transform var(--duration-normal) var(--ease-out);
  }

  .faq-topic__arrow svg {
    inline-size: max(1rem, calc(18 * var(--px, 0.0625rem)));
    block-size: auto;
    transform: rotate(-45deg);
  }

  /*
    Hover animation (Default card 05): the circle rolls to the right like a wheel. Turning 45deg
    (clockwise) turns the ↗ inside it into →, while it moves 0.2 x its width to the right (~8px for
    42px; a true roll would be 0.39 x, which looked too far). Both happen in one transform, so the
    roll and the arrow's turn stay in sync. The card itself doesn't change.
    Reduced motion: only the colours change (↗ becomes → at once).
  */
  @media (prefers-reduced-motion: no-preference) {
    .faq-topic__card:hover .faq-topic__arrow,
    .faq-topic__card:focus-visible .faq-topic__arrow {
      transform: translateX(calc(var(--arrow-size) * 0.2)) rotate(45deg);
    }
  }

  .faq-topic__card:hover .faq-topic__arrow,
  .faq-topic__card:focus-visible .faq-topic__arrow {
    border-color: var(--color-accent);
    background-color: color-mix(in srgb, var(--color-accent) 10%, var(--color-background));
    color: var(--color-accent);
  }

  @media (prefers-reduced-motion: reduce) {
    .faq-topic__card:hover .faq-topic__arrow svg,
    .faq-topic__card:focus-visible .faq-topic__arrow svg {
      transform: none;
    }
  }

  @media (max-width: 749px) {
    .faq-topic__arrow {
      --arrow-size: 1.5rem;
    }
  }

  /* ---------- The panel ---------- */
  .faq-topic__panel {
    grid-column: 1 / -1;
    display: grid;
    grid-template-columns: minmax(0, 712fr) minmax(0, 793fr);
    grid-template-areas:
      "head card"
      "list card";
    align-items: start;
    column-gap: max(var(--space-2xl), calc(144 * var(--px, 0.0625rem)));
    margin-block-start: var(--space-2xl);
    padding-inline: max(0rem, calc(85 * var(--px, 0.0625rem)));
    scroll-margin-block-start: 8rem;
  }

  .faq-topic__head {
    grid-area: head;
    display: flex;
    align-items: flex-start;
    gap: var(--space-sm);
    margin-block-end: max(var(--space-xl), calc(52 * var(--px, 0.0625rem)));
  }

  .faq-topic__head .faq-topic__icon {
    margin-block-start: 0.6rem;
  }

  .faq-topic__heading {
    margin: 0;
    font-size: max(1.375rem, calc(28 * var(--px, 0.0625rem)));
    font-weight: 400;
    line-height: 1.2;
  }

  .faq-topic__line {
    margin: var(--space-xs) 0 0;
    font-size: var(--font-size-caption);
  }

  .faq-topic__list {
    grid-area: list;
    counter-reset: faq-question;
    display: flex;
    flex-direction: column;
    gap: max(var(--space-md), calc(27 * var(--px, 0.0625rem)));
  }

  /* Theme editor only: a topic with no complete question */
  .faq-topic__note {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    font-style: italic;
  }

  /* ---------- The answer card (only with the script) ---------- */
  .faq-answer,
  .faq[data-ready] .faq-topic--empty .faq-answer {
    display: none;
  }

  .faq[data-ready] .faq-answer {
    grid-area: card;
    position: sticky;
    inset-block-start: 8rem;
    display: block;
    overflow: hidden;
    margin-block-start: max(var(--space-md), calc(25 * var(--px, 0.0625rem)));
    padding: max(var(--space-xl), calc(55 * var(--px, 0.0625rem)));
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-accent) 1%, var(--color-background));
    box-shadow: 0 20px 60px 0 #0000000f;
  }

  .faq-answer__number {
    position: absolute;
    inset-block-start: -0.32em;
    inset-inline-end: max(var(--space-md), calc(25 * var(--px, 0.0625rem)));
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-family: var(--font-heading--family);
    font-size: max(3.5rem, calc(90 * var(--px, 0.0625rem)));
    font-weight: var(--font-heading--weight);
    line-height: 1;
  }

  .faq-answer__label {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    letter-spacing: 0.15em;
    text-transform: uppercase;
  }

  .faq-answer__question {
    margin: max(var(--space-md), calc(28 * var(--px, 0.0625rem))) 0 0;
    font-size: max(1.5rem, calc(36 * var(--px, 0.0625rem)));
    font-weight: 400;
    line-height: 1.2;
  }

  .faq-answer__question:focus {
    outline: none;
  }

  .faq-answer__rule {
    display: block;
    inline-size: max(2.5rem, calc(52 * var(--px, 0.0625rem)));
    block-size: 2px;
    margin-block-start: var(--space-sm);
    background-color: var(--color-text);
  }

  .faq-answer__text {
    margin-block-start: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
    font-size: max(1rem, calc(22 * var(--px, 0.0625rem)));
    line-height: 1.6;
  }

  .faq-answer__text > * {
    margin: 0;
  }

  .faq-answer__text > * + * {
    margin-block-start: var(--space-sm);
  }

  .faq-answer__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-md);
    margin-block-start: max(var(--space-xl), calc(55 * var(--px, 0.0625rem)));
    padding-block-start: max(var(--space-lg), calc(32 * var(--px, 0.0625rem)));
    border-block-start: 1px solid var(--color-card-border);
  }

  .faq-answer__footer[hidden] {
    display: none;
  }

  .faq-answer__ask {
    margin: 0;
    font-size: var(--font-size-body-sm);
  }

  /*
    Figma ~40px tall at 1920; they follow the screen like the card. Two classes: the theme's .button
    rule loads after this file and beats one class.
  */
  .faq-answer .faq-answer__yes,
  .faq-answer .faq-answer__human {
    min-block-size: max(2.5rem, calc(40 * var(--px, 0.0625rem)));
    padding-inline: max(1.25rem, calc(25 * var(--px, 0.0625rem)));
    font-size: max(var(--font-size-caption), calc(16 * var(--px, 0.0625rem)));
  }

  /* YES: the glass pill (white, the glass shadows, no red border) */
  .faq-answer .faq-answer__yes {
    border-color: transparent;
    box-shadow: var(--shadow-header);
  }

  .faq-answer__thanks {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-body-sm);
  }

  .faq-answer__thanks:empty {
    display: none;
  }

  .faq-answer__thanks:not(:empty) {
    margin-block-start: max(var(--space-xl), calc(55 * var(--px, 0.0625rem)));
    padding-block-start: max(var(--space-lg), calc(32 * var(--px, 0.0625rem)));
    border-block-start: 1px solid var(--color-card-border);
  }

  /* Tablets and phones (Variant10): one column: questions, then the answer card */
  @media (max-width: 1099px) {
    .faq-topic__panel {
      grid-template-columns: minmax(0, 1fr);
      grid-template-areas:
        "head"
        "list"
        "card";
      padding-inline: 0;
    }

    .faq[data-ready] .faq-answer {
      position: relative;
      inset-block-start: auto;
      margin-block-start: var(--space-xl);
      padding: var(--space-lg);
    }
  }

  @media (max-width: 749px) {
    .faq-topic__card {
      min-block-size: 0;
      padding: var(--space-sm);
    }

    .faq-topic__number {
      font-size: 2.75rem;
    }

    .faq-topic__icon {
      inline-size: 1.75rem;
      block-size: 1.75rem;
    }

    .faq-topic__icon svg,
    .faq-topic__icon img {
      inline-size: 0.875rem;
      block-size: 0.875rem;
    }

    .faq-topic__title {
      margin-block-start: var(--space-md);
      font-size: 1rem;
    }

    .faq-topic__text {
      margin-block-start: var(--space-xs);
      font-size: 0.75rem;
    }

    .faq-topic__count {
      font-size: 0.5625rem;
    }

    .faq-topic__arrow {
      inline-size: 1.5rem;
      block-size: 1.5rem;
    }

    .faq-topic__arrow svg {
      inline-size: 0.625rem;
    }

    /* Variant10: no topic header on phones once the pills name the topic */
    .faq[data-ready] .faq-topic__head {
      display: none;
    }

    .faq[data-ready] .faq-topic__panel {
      margin-block-start: var(--space-lg);
    }

    /* faq-mobile: a compact answer card, full width */
    .faq[data-ready] .faq-answer {
      margin-block-start: var(--space-lg);
      padding: var(--space-lg) var(--space-md);
    }

    .faq-answer__number {
      font-size: 2.5rem;
    }

    .faq-answer__label {
      font-size: 0.6875rem;
    }

    .faq-answer__question {
      margin-block-start: var(--space-sm);
      font-size: 1.125rem;
    }

    .faq-answer__text {
      margin-block-start: var(--space-sm);
      font-size: 0.8125rem;
    }

    .faq-answer__footer {
      gap: var(--space-sm);
      margin-block-start: var(--space-md);
      padding-block-start: var(--space-md);
    }

    .faq-answer__ask {
      font-size: 0.75rem;
    }

    .faq-answer .faq-answer__yes,
    .faq-answer .faq-answer__human {
      min-block-size: 2.25rem;
      padding-inline: 0.75rem;
      font-size: 0.75rem;
    }

    .faq-answer__thanks:not(:empty) {
      margin-block-start: var(--space-md);
      padding-block-start: var(--space-md);
    }
  }

/* blocks/_hero-content.liquid */

  /*
    Layer 10: decorations with Layer 1-9 sit behind the text, 11-20 in front of it.
    The gap is the section's "Gap" setting (Content spacing = Fixed gap); the other spacings spread the blocks.
  */
  .hero-content {
    position: relative;
    z-index: 10;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--hero-content-gap, 24px);
  }

/* blocks/_hero-decoration.liquid */

  /*
    Placed by its centre (translate -50%) and tilted with rotate; the animations use transform, which
    the browser adds on top of translate/rotate, so an animated decoration keeps its place and tilt.
    Opacity sits on the inner art, so "twinkle" can fade it without losing the chosen opacity.
  */
  .hero-decoration {
    position: absolute;
    inset-inline-start: var(--deco-x);
    inset-block-start: var(--deco-y);
    z-index: var(--deco-layer, 5);
    inline-size: calc(var(--deco-size) * var(--hero-px, 1px)); /* design px x the hero's scale */
    translate: -50% -50%;
    rotate: var(--deco-rotate);
    pointer-events: none;
  }

  .hero-decoration__art {
    display: block;
    inline-size: 100%;
    block-size: auto;
    opacity: var(--deco-opacity, 1);
  }

  .hero-decoration__art :is(svg) {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  /* Sketch = a box in the chosen colour, cut to the drawing's lines */
  .hero-decoration__mask {
    background-color: currentcolor;
    mask: var(--deco-mask) center / contain no-repeat;
  }

  .hero-decoration--muted {
    color: color-mix(in srgb, var(--color-text) 55%, var(--color-background));
  }

  .hero-decoration--accent {
    color: var(--color-accent);
  }

  .hero-decoration--white {
    color: #ffffff;
  }

  /* Stronger than Muted (a 55% mix that looks dull on cream) */
  .hero-decoration--black {
    color: #000000;
  }

  .hero-decoration--grey {
    color: #716c68;
  }

  /* Animations (only with "Enable animations" on: the .motion-on class on <html>, also in the theme editor: a loop never hides content) */
  @keyframes deco-breathe {
    0%, 100% { transform: scale(1); }
    50% { transform: scale(1.08); }
  }

  @keyframes deco-float {
    0%, 100% { transform: translateY(0); }
    50% { transform: translateY(-8px); }
  }

  @keyframes deco-sway {
    0%, 100% { transform: rotate(-5deg); }
    50% { transform: rotate(5deg); }
  }

  @keyframes deco-twinkle {
    0%, 100% { transform: scale(1); opacity: 1; }
    50% { transform: scale(0.6); opacity: 0.35; }
  }

  @keyframes deco-spin {
    to { transform: rotate(360deg); }
  }

  /* Rock: from its normal angle up to 20deg and back (sway goes -5 to 5 round the middle instead) */
  @keyframes deco-rock {
    0%, 100% { transform: rotate(0deg); }
    50% { transform: rotate(20deg); }
  }

  /*
    Flash (made for the star): pops in, stays visible while it turns half a circle, then shrinks away
    still turning, stays hidden for a moment and starts again. Hidden at the very start and end, so
    the loop restarts without a jump.
  */
  @keyframes deco-flash {
    0% { transform: scale(0.3) rotate(0deg); opacity: 0; }
    15% { transform: scale(1) rotate(30deg); opacity: 1; }
    65% { transform: scale(1) rotate(180deg); opacity: 1; }
    80%, 100% { transform: scale(0.3) rotate(240deg); opacity: 0; }
  }

  .motion-on .hero-decoration:not(.hero-decoration--anim-none) {
    animation-duration: var(--deco-speed, 6s);
    animation-delay: var(--deco-delay, 0s);
    animation-iteration-count: infinite;
    animation-timing-function: ease-in-out;
  }

  .motion-on .hero-decoration--anim-breathe { animation-name: deco-breathe; }
  .motion-on .hero-decoration--anim-float { animation-name: deco-float; }
  .motion-on .hero-decoration--anim-sway { animation-name: deco-sway; }
  .motion-on .hero-decoration--anim-twinkle { animation-name: deco-twinkle; }
  .motion-on .hero-decoration--anim-rock { animation-name: deco-rock; }
  .motion-on .hero-decoration--anim-flash { animation-name: deco-flash; }

  .motion-on .hero-decoration--anim-spin {
    animation-name: deco-spin;
    animation-timing-function: linear;
  }

  @media (prefers-reduced-motion: reduce) {
    .hero-decoration {
      animation: none !important;
    }
  }

/* blocks/_hero-decorations.liquid */

  .hero-decorations {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }

  /* Smaller screens: the text fills the width, so scattered decorations would sit on it */
  @media (max-width: 989px) {
    .hero-decorations {
      display: none;
    }
  }

/* blocks/_hero-product.liquid */

  /*
    Positioned by its centre: left/top put the centre point, translate(-50%, -50%) pulls the image back
    by half its own size. Percentages are of the product area, so the layout scales with the screen.
  */
  .hero-product {
    position: absolute;
    inset-inline-start: var(--hero-product-x);
    inset-block-start: var(--hero-product-y);
    inline-size: var(--hero-product-width);
    translate: -50% -50%;
    rotate: var(--hero-product-rotate);
  }

  /* Cut-out photos (transparent PNG / WebP): no box, a soft shadow under the product itself */
  .hero-product .image {
    overflow: visible;
    background: none;
  }

  .hero-product .image > img {
    filter: drop-shadow(0 12px 18px #00000033);
  }

  /*
    Name tag (Figma: "Fragrance" / "Makeup": white script letters with a thick dark-red outline, like a
    sticker, and a thin white arrow pointing up-right, sitting to the LEFT of the product at its middle).
    Position: the label's right edge sits on the Label position point and it is centred on it vertically,
    so the defaults (-4% / 50%) place it just left of the product, halfway down.
    Hidden until the product is the active one (class is-active, set by <hero-showcase>).
  */
  .hero-product__label {
    position: absolute;
    inset-inline-start: var(--hero-label-x);
    inset-block-start: var(--hero-label-y);
    z-index: 2;
    display: flex;
    align-items: center;
    gap: 0.2em;
    translate: -100% -50%;
    rotate: calc(var(--hero-product-rotate) * -1);
    font-family: var(--font-accent--family);
    font-style: var(--font-accent--style);
    font-weight: var(--font-accent--weight);
    font-size: max(1.75rem, calc(64 * var(--hero-px, 1px)));
    line-height: 1;
    white-space: nowrap;
    opacity: 0;
    scale: 0.85;
    transform-origin: right center;
    pointer-events: none;
    transition:
      opacity var(--duration-base) var(--ease-out),
      scale var(--duration-base) var(--ease-out);
  }

  /*
    The sticker outline: a thick stroke in the accent colour, painted BEHIND the white letters
    (paint-order: stroke fill), so the letters stay full width and only the outside is red.
    The text-shadow ring is a fallback for browsers without stroke paint-order.
  */
  .hero-product__label-text {
    color: #ffffff;
    -webkit-text-stroke: 0.16em var(--color-accent);
    paint-order: stroke fill;
    text-shadow: 0 0.08em 0.25em #00000040;
  }

  @supports not (paint-order: stroke fill) {
    .hero-product__label-text {
      -webkit-text-stroke: 0;
      text-shadow:
        0.05em 0 0 var(--color-accent),
        -0.05em 0 0 var(--color-accent),
        0 0.05em 0 var(--color-accent),
        0 -0.05em 0 var(--color-accent),
        0.04em 0.04em 0 var(--color-accent),
        -0.04em 0.04em 0 var(--color-accent),
        0.04em -0.04em 0 var(--color-accent),
        -0.04em -0.04em 0 var(--color-accent);
    }
  }

  /* Thin white arrow (the theme's arrow icon turned to point up-right), slightly above the middle */
  .hero-product__label-arrow {
    display: inline-flex;
    align-self: flex-start;
    margin-block-start: 0.1em;
    color: #ffffff;
    filter: drop-shadow(0 1px 2px #00000059);
  }

  .hero-product__label-arrow svg {
    inline-size: 0.42em;
    block-size: auto;
    rotate: -45deg;
  }

  /*
    The active product's name label must sit over the content's text (it reaches left, into the text
    column). The product's rotate/translate make it its own stacking layer, so the label's z-index
    can't escape it: the active product itself is lifted above the content layer (.hero__inner, z-index 1).
  */
  .hero-product.is-active {
    z-index: 2;
  }

  .hero-product.is-active .hero-product__label {
    opacity: 1;
    scale: 1;
  }

  /* The active product lifts slightly */
  .hero-product .image > img {
    transition: transform var(--duration-base) var(--ease-out);
  }

  .hero-product.is-active .image > img {
    transform: scale(1.04);
  }

  @media (prefers-reduced-motion: reduce) {
    .hero-product__label,
    .hero-product .image > img {
      transition: none;
    }
  }

  .hero-product__empty {
    display: grid;
    place-items: center;
    aspect-ratio: 1;
    padding: var(--space-xs);
    border: 2px dashed var(--color-accent);
    border-radius: var(--radius-sm);
    background-color: #ffffffb3;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    text-align: center;
  }

/* blocks/_hero-products.liquid */

  /* Fills the hero's product area (sized by .hero__products in the section); children are positioned in % */
  .hero-products {
    position: relative;
    inline-size: 100%;
    block-size: 100%;
  }

/* blocks/_highlight-card.liquid */

  /*
    Glass card over the photo: a light, see-through fill that blurs what is behind it, a thin bright
    edge and a soft shadow. The text uses the section's (light) text colour.
  */
  .highlight-card {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    min-inline-size: clamp(15rem, 14vw, 17rem); /* grows for a long value; the cards in a column get the same width */
    max-inline-size: 100%;
    padding: var(--space-md) var(--space-lg);
    border: 1px solid #ffffff59;
    border-radius: var(--highlight-card-radius, var(--radius-lg));
    background-color: #ffffff2e;
    box-shadow: 0 0.75rem 2rem #00000026, var(--glass-rim);
    color: var(--color-text);
    text-decoration: none;
    -webkit-backdrop-filter: blur(var(--glass-frost)) saturate(1.2);
    backdrop-filter: blur(var(--glass-frost)) saturate(1.2);
    transition:
      background-color var(--duration-fast) var(--ease-out),
      translate var(--duration-fast) var(--ease-out);
  }

  a.highlight-card:hover {
    background-color: #ffffff47;
    translate: 0 -2px;
  }

  .highlight-card__icon {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 3rem;
    block-size: 3rem;
    border: 1px solid #ffffff59;
    border-radius: var(--radius-pill);
    background-color: #ffffff26;
  }

  .highlight-card__icon svg,
  .highlight-card__icon img {
    inline-size: 1.375rem;
    block-size: 1.375rem;
    object-fit: contain;
  }

  .highlight-card__text {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    min-inline-size: 0;
  }

  .highlight-card__label {
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    opacity: 0.85;
  }

  .highlight-card__value {
    font-size: var(--font-size-h3);
    line-height: 1.2;
  }

  /* Large screens: the value stays on one line (the card grows); smaller screens let a long value wrap */
  @media (min-width: 1200px) {
    .highlight-card__value {
      white-space: nowrap;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    a.highlight-card:hover {
      translate: none;
    }
  }

/* blocks/_highlight-cards.liquid */

  .highlight-cards {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
  }

  .highlight-cards:not(:has(.highlight-card, .countdown:not([hidden]))) {
    display: none;
  }

  /*
    Slide-in: the column itself only triggers (it stays visible); its cards start moved and
    transparent, then glide to their place when the column gets is-visible. Each card waits
    (its position - 1) x the stagger, so they arrive one after another.
    The selectors repeat [data-animate] with :not(.is-visible) to outrank the theme's generic
    "hide until visible" rule in critical.css, which would otherwise hide the whole column.
  */
  .highlight-cards[data-animate='slide-top'] { --slide-from: 0, -3rem; }
  .highlight-cards[data-animate='slide-bottom'] { --slide-from: 0, 3rem; }
  .highlight-cards[data-animate='slide-left'] { --slide-from: -4rem, 0; }
  .highlight-cards[data-animate='slide-right'] { --slide-from: 4rem, 0; }

  .highlight-cards > :nth-child(2) { --card-index: 1; }
  .highlight-cards > :nth-child(3) { --card-index: 2; }
  .highlight-cards > :nth-child(4) { --card-index: 3; }
  .highlight-cards > :nth-child(5) { --card-index: 4; }
  .highlight-cards > :nth-child(n + 6) { --card-index: 5; }

  @media (prefers-reduced-motion: no-preference) {
    .js.animations-on .highlight-cards[data-animate],
    .js.animations-on .highlight-cards[data-animate]:not(.is-visible) {
      opacity: 1;
      transform: none;
      transition: none;
    }

    .js.animations-on .highlight-cards[data-animate] :is(.highlight-card, .countdown) {
      transition:
        opacity var(--slide-duration) var(--ease-out),
        transform var(--slide-duration) var(--ease-out),
        background-color var(--duration-fast) var(--ease-out),
        translate var(--duration-fast) var(--ease-out);
      transition-delay: calc(var(--card-index, 0) * var(--slide-stagger)), calc(var(--card-index, 0) * var(--slide-stagger)), 0s, 0s;
    }

    .js.animations-on .highlight-cards[data-animate]:not(.is-visible) :is(.highlight-card, .countdown) {
      opacity: 0;
      transform: translate(var(--slide-from));
    }
  }

/* blocks/_icon-feature.liquid */

  .icon-feature {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-xs);
    text-align: center;
  }

  .icon-feature--empty {
    justify-content: center;
    padding: var(--space-md);
    border: 1px dashed var(--color-border);
  }

  /*
    Figma: a white circle with a soft shadow, the icon in the Icon color (empty = the scheme's
    "Links and highlights" color). The circle is the scheme's --color-surface-raised: white on a
    light background, a light mix of the text color on a dark one (snippets/css-variables.liquid).
    Sizes: phones 48px (Figma mobile), tablets 64px, desktop 72 -> 84px.
  */
  .icon-feature__badge {
    display: grid;
    place-items: center;
    inline-size: 3rem;
    aspect-ratio: 1;
    margin-block-end: var(--space-xs);
    border-radius: var(--radius-pill);
    background-color: var(--color-surface-raised, #ffffff);
    box-shadow: 0 0.5rem 1.5rem #0000000f;
    color: var(--icon-feature-color, var(--color-accent));
  }

  .icon-feature__badge svg,
  .icon-feature__badge img {
    inline-size: 1.25rem;
    block-size: 1.25rem;
    object-fit: contain;
  }

  /* Phones (Figma mobile): small title and text, so 2 columns fit at 390px */
  .icon-feature__title {
    margin: 0;
    font-size: 1rem;
  }

  .icon-feature__title a {
    color: inherit;
    text-decoration: none;
  }

  /* The link covers the full feature */
  .icon-feature__title a::after {
    content: '';
    position: absolute;
    inset: 0;
  }

  .icon-feature__title a:hover {
    text-decoration: underline;
    text-decoration-thickness: 1px;
  }

  .icon-feature__text {
    max-inline-size: 22rem;
    font-size: var(--font-size-small);
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
  }

  .icon-feature__text > * {
    margin: 0;
  }

  /*
    The text stays above the covering link: visitors can select and copy it, and links in the text
    still work. The badge, the title and the space around them are the click area.
  */
  .icon-feature__text {
    position: relative;
    z-index: 1;
  }

  /* Keyboard focus: the ring goes around the full feature (the click area), not only the title */
  @supports selector(:has(*)) {
    .icon-feature:has(.icon-feature__title a:focus-visible) {
      outline: 2px solid var(--color-accent);
      outline-offset: var(--space-xs);
      border-radius: var(--radius-focus);
    }

    .icon-feature__title a:focus-visible {
      outline: none;
    }
  }

  @media (min-width: 750px) {
    .icon-feature {
      gap: var(--space-sm);
    }

    .icon-feature__badge {
      inline-size: 4rem;
      margin-block-end: var(--space-sm);
    }

    .icon-feature__badge svg,
    .icon-feature__badge img {
      inline-size: 1.5rem;
      block-size: 1.5rem;
    }

    .icon-feature__title {
      font-size: 1.25rem;
    }

    .icon-feature__text {
      font-size: var(--font-size-body-sm);
    }
  }

  @media (min-width: 1200px) {
    .icon-feature__badge {
      inline-size: clamp(4.5rem, 3.5rem + 0.85vw, 5.25rem);
    }

    .icon-feature__badge svg,
    .icon-feature__badge img {
      inline-size: 1.75rem;
      block-size: 1.75rem;
    }

    .icon-feature__title {
      font-size: var(--font-size-h3);
    }

    .icon-feature__text {
      font-size: var(--font-size-body);
    }
  }

/* blocks/_location-card.liquid */

  /*
    Figma card: 492 x 210, badge 56px at 31px from the left, text 21px after it. Made roomier on
    purpose (developer, 2026-10-30): 68px badge, bigger title and text, more padding. Figma px x --px
    follow the screen in a scaled section (snippets/screen-scale.liquid).
  */
  .location-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: start;
    column-gap: var(--space-lg);
    padding: var(--space-xl) var(--space-xl);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-card);
  }

  .location-card__badge {
    display: grid;
    place-items: center;
    inline-size: max(3.5rem, calc(68 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-border);
    color: var(--color-accent);
    font-size: var(--font-size-h3);
    text-transform: uppercase;
  }


  .location-card__title {
    margin: 0;
    font-family: var(--font-body--family);
    font-style: var(--font-body--style);
    font-weight: var(--font-weight-medium);
    font-size: var(--font-size-h3);
    line-height: var(--line-height-body);
  }

  /*
    Whole card clickable: the place name stays the real link (screen readers read it as the link
    name), and its ::after covers the card (the card is position: relative). No underline; the hand
    cursor and the lift show it's clickable.
  */
  .location-card__link {
    color: inherit;
    text-decoration: none;
  }

  .location-card__link::after {
    content: "";
    position: absolute;
    inset: 0;
    border-radius: inherit;
  }

  .location-card--link {
    position: relative;
    cursor: pointer;
    transition:
      transform var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  /* The keyboard focus ring goes round the whole card, not just the name */
  .location-card__link:focus-visible {
    outline: none;
  }

  .location-card--link:has(.location-card__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .location-card--link:hover,
  .location-card--link:has(.location-card__link:focus-visible) {
    box-shadow: var(--shadow-card-rose);
  }

  @media (prefers-reduced-motion: no-preference) {
    .location-card--link:hover,
    .location-card--link:has(.location-card__link:focus-visible) {
      transform: translateY(-0.25rem);
    }
  }


  .location-card__address {
    margin: var(--space-sm) 0 0;
    font-size: var(--font-size-body-lg);
    line-height: var(--line-height-body);
  }

  .location-card__hours {
    margin: var(--space-xs) 0 0;
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
  }

  /*
    The badge beside the place, the address and the hours under both (phone design), so the text uses
    the card's full width (in the narrow desktop column the text had ~200px beside the badge).
  */
  .location-card {
    align-items: center;
    row-gap: 0;
  }

  .location-card__body {
    display: contents;
  }

  .location-card__address,
  .location-card__hours,
  .location-card:not(:has(.location-card__badge)) .location-card__title {
    grid-column: 1 / -1;
  }

  /* Below 1440px (2 cards per row): smaller badge, text and padding */
  @media (max-width: 1439px) {
    .location-card {
      column-gap: var(--space-sm);
      padding: var(--space-md);
    }

    .location-card__badge {
      inline-size: 3rem;
      font-size: var(--font-size-body);
    }

    .location-card__title {
      font-size: var(--font-size-body-lg);
      line-height: 1.3;
    }

    .location-card__address,
    .location-card__hours {
      font-size: var(--font-size-body);
    }
  }

  /* Phones: compact cards, small text (phone design) */
  @media (max-width: 749px) {
    .location-card {
      padding: var(--space-sm);
      border-radius: var(--radius-xs);
    }

    .location-card__badge {
      inline-size: 1.75rem;
      font-size: 0.625rem;
    }

    .location-card__title {
      font-size: 0.8125rem;
    }

    .location-card__address,
    .location-card__hours {
      font-size: 0.75rem;
      line-height: 1.5;
    }

    .location-card__address {
      margin-block-start: var(--space-xs);
    }

    .location-card__hours {
      margin-block-start: var(--space-2xs);
    }
  }

  .location-card--empty {
    display: block;
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 65%, transparent);
    font-style: italic;
    text-align: center;
  }

/* blocks/_location-list.liquid */

  /* Figma: 546 x 715 white panel, cards 492 wide, 27px in from the sides, ~16px apart */
  .location-list {
    --location-gap: var(--space-md);
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--location-gap);
    padding: var(--space-lg);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-background);
  }

  .location-list > * {
    flex: 1 1 100%;
    min-inline-size: 0;
  }

  @media (min-width: 375px) and (max-width: 1439px) {
    .location-list > * {
      flex: 0 0 calc((100% - var(--location-gap)) / 2);
    }
  }

  @media (max-width: 749px) {
    .location-list {
      --location-gap: var(--space-xs);
      padding: var(--space-xs);
      border-radius: var(--radius-sm);
    }
  }

  .location-list__note {
    margin: 0;
    padding: var(--space-md);
    font-style: italic;
    text-align: center;
  }

/* blocks/_map-pin.liquid */

  /*
    The point (--pin-x, --pin-y) is the centre of the 28px dot; the label hangs ~12px under it,
    centred (Figma: 132 x 82 dark glass boxes).
  */
  .map-pin {
    position: absolute;
    left: var(--pin-x);
    top: var(--pin-y);
    --pin-dot: max(1rem, calc(28 * var(--px, 0.0625rem)));
    /* The point is the dot's centre */
    transform: translate(-50%, calc(var(--pin-dot) / -2));
  }

  .map-pin[hidden] {
    display: none;
  }

  .map-pin__inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-sm);
  }

  /* Red dot with a darker ring and a soft glow (the map behind is always dark) */
  .map-pin__dot {
    inline-size: var(--pin-dot);
    aspect-ratio: 1;
    border: 1px solid var(--color-accent);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 75%, transparent);
    box-shadow: 0 0 0.75rem color-mix(in srgb, var(--color-accent) 70%, transparent);
  }

  /* Dark glass: white text is used on purpose (the map image is dark on every colour scheme) */
  .map-pin__label {
    display: grid;
    justify-items: center;
    min-inline-size: calc(132 * var(--px, 0.0625rem)); /* 132px */
    margin: 0;
    padding: var(--space-sm) var(--space-lg);
    border: 1px solid #ffffff40;
    border-radius: var(--radius-xs);
    background-color: #ffffff1a;
    color: #ffffff;
    font-size: var(--font-size-body);
    line-height: 1.4;
    text-align: center;
    white-space: nowrap;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .map-pin__type {
    color: #ffffffb3;
  }

  /*
    Phones and tablets (phone design): smaller labels, so neighbouring cities (London, Dubai) overlap
    less. On phones the map is taller (Map shape on phones), so the cities are further apart.
  */
  @media (max-width: 1199px) {
    .map-pin {
      --pin-dot: 0.75rem;
    }

    .map-pin__inner {
      gap: var(--space-2xs);
    }

    .map-pin__label {
      min-inline-size: 0;
      padding: var(--space-2xs) var(--space-sm);
      font-size: 0.75rem;
    }
  }

/* blocks/_milestone.liquid */

  /*
    Figma 1920 (Default-3): rail x 237 (2px accent), markers 22px (2px accent ring, background
    fill); content from x 301, ~520 wide; pill label ~13px bold uppercase, accent on accent ~10%,
    padding ~6 x 13; title ~24px medium; text ~19px / 29px; stat value ~24px accent + label ~17px;
    year ~200px body font medium, accent ~20%, centred in the right part; ~291px per milestone.
    The section sets --px, --rail-x (the rail, from the content box's left) and --content-x.
    --milestone-pad-top: the space above the content; the marker sits at its end.
  */
  .milestone {
    --marker-size: max(1.125rem, calc(22 * var(--px)));
    --milestone-pad-top: max(var(--space-xl), calc(40 * var(--px)));

    position: relative;
    display: grid;
    grid-template-columns: var(--content-x) minmax(0, 560fr) minmax(0, 1000fr);
    align-items: start;
    padding-block: var(--milestone-pad-top) max(var(--space-2xl), calc(70 * var(--px)));
  }

  /* The rail piece without the section's script (the whole rail shows filled) */
  .milestone::before {
    content: "";
    position: absolute;
    inset-block: 0;
    inset-inline-start: calc(var(--rail-x) - 1px);
    inline-size: 2px;
    background-color: var(--color-accent);
  }

  .milestone__marker {
    position: absolute;
    z-index: 1;
    inset-block-start: calc(var(--milestone-pad-top) + 0.05rem);
    inset-inline-start: calc(var(--rail-x) - var(--marker-size) / 2);
    box-sizing: border-box;
    inline-size: var(--marker-size);
    block-size: var(--marker-size);
    border: 2px solid var(--color-accent);
    border-radius: 50%;
    background-color: var(--color-background);
    box-shadow: 0 0 10px 0 color-mix(in srgb, var(--color-accent) 47%, transparent);
  }

  .milestone__content {
    grid-column: 2;
    max-inline-size: max(18rem, calc(540 * var(--px)));
  }

  .milestone__pill {
    display: inline-block;
    margin: 0;
    padding: 0.3rem 0.8rem;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 10%, transparent);
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: 700;
    letter-spacing: 0.15em;
    line-height: 1.3;
    text-transform: uppercase;
  }

  .milestone__title {
    margin: max(var(--space-md), calc(22 * var(--px))) 0 0;
    font-family: var(--font-body--family);
    font-size: max(1.25rem, calc(24 * var(--px)));
    font-weight: var(--font-weight-medium);
    line-height: 1.3;
  }

  /* The title can be first (no pill) */
  .milestone__content > .milestone__title:first-child {
    margin-block-start: 0;
  }

  .milestone__text {
    margin-block-start: max(var(--space-sm), calc(18 * var(--px)));
    font-size: var(--font-size-body);
    line-height: 1.55;
  }

  .milestone__text > * {
    margin: 0;
  }

  .milestone__stat {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-xs) var(--space-sm);
    margin: max(var(--space-md), calc(22 * var(--px))) 0 0;
  }

  .milestone__stat-value {
    color: var(--color-accent);
    font-size: max(1.25rem, calc(24 * var(--px)));
    line-height: 1;
  }

  .milestone__stat-label {
    font-size: var(--font-size-body-sm);
  }

  .milestone__year {
    grid-column: 3;
    justify-self: center;
    margin: calc(max(var(--space-sm), calc(15 * var(--px))) * -1) 0 0;
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-family: var(--font-body--family);
    font-size: max(4rem, calc(200 * var(--px)));
    font-weight: var(--font-weight-medium);
    line-height: 1;
    letter-spacing: -0.01em;
  }

  /* Editor only: an empty milestone */
  .about-timeline__item-note {
    margin: 0;
    padding-block: var(--space-md);
    padding-inline-start: var(--content-x);
    font-style: italic;
    opacity: 0.7;
  }

  /*
    With the section's script (data-ready): the section draws one rail for the whole list, so the
    milestones' own pieces go; milestones not reached yet are faded, their markers paler and
    without the glow, their years paler (Default-4).
  */
  .about-timeline[data-ready] .milestone::before {
    content: none;
  }

  .about-timeline[data-ready] .milestone:not(.is-reached) .milestone__content {
    opacity: 0.5;
  }

  .about-timeline[data-ready] .milestone:not(.is-reached) .milestone__marker {
    border-color: color-mix(in srgb, var(--color-accent) 35%, var(--color-background));
    box-shadow: 0 0 10px 0 color-mix(in srgb, var(--color-accent) 0%, transparent);
  }

  .about-timeline[data-ready] .milestone:not(.is-reached) .milestone__year {
    color: color-mix(in srgb, var(--color-accent) 6%, transparent);
  }

  @media (prefers-reduced-motion: no-preference) {
    .about-timeline[data-ready] .milestone__content,
    .about-timeline[data-ready] .milestone__marker,
    .about-timeline[data-ready] .milestone__year {
      transition:
        opacity var(--duration-slow) var(--ease-out),
        color var(--duration-slow) var(--ease-out),
        border-color var(--duration-slow) var(--ease-out),
        box-shadow var(--duration-slow) var(--ease-out);
    }
  }

  /*
    Tablets (750–1199px): the phone layout (Variant45-3) a little bigger: the content next to the
    rail, the year centred in the space at the right and in the middle of its milestone's height.
  */
  @media (max-width: 1199px) {
    .milestone {
      --marker-size: 0.875rem;
      --milestone-pad-top: var(--space-md);

      grid-template-columns: var(--content-x) minmax(0, 24rem) minmax(0, 1fr);
      column-gap: var(--space-md);
      padding-block-end: var(--space-xl);
    }

    .milestone__marker {
      inset-block-start: calc(var(--milestone-pad-top) + 0.25rem);
    }

    .milestone__content {
      max-inline-size: none;
    }

    .milestone__pill {
      padding: 0.25rem 0.625rem;
      font-size: 0.6875rem;
    }

    .milestone__title {
      margin-block-start: var(--space-sm);
      font-size: 1.125rem;
    }

    .milestone__text {
      margin-block-start: var(--space-xs);
      font-size: 0.875rem;
      line-height: 1.5;
    }

    .milestone__stat {
      margin-block-start: var(--space-sm);
    }

    .milestone__stat-value {
      font-size: 1rem;
    }

    .milestone__stat-label {
      font-size: 0.75rem;
    }

    .milestone__year {
      align-self: center;
      margin: 0;
      font-size: min(6rem, 10vw);
    }
  }

  /*
    Phones (Variant45-3 at 375px): marker 12px; content ~175px wide; pill 9px, title 14px, text
    12px, stat 13px + 9px; the year ~52px flush right (it shrinks with the screen, so a 320px phone
    keeps room for the text).
  */
  @media (max-width: 749px) {
    .milestone {
      --marker-size: 0.75rem;

      grid-template-columns: var(--content-x) minmax(0, 1fr) auto;
      column-gap: var(--space-sm);
      padding-block-end: 1.75rem;
    }

    .milestone__marker {
      inset-block-start: calc(var(--milestone-pad-top) + 0.125rem);
    }

    .milestone__pill {
      padding: 0.1875rem 0.5rem;
      font-size: 0.5625rem;
    }

    .milestone__title {
      font-size: 0.875rem;
    }

    .milestone__text {
      font-size: 0.75rem;
    }

    .milestone__stat-value {
      font-size: 0.8125rem;
    }

    .milestone__stat-label {
      font-size: 0.5625rem;
    }

    .milestone__year {
      justify-self: end;
      font-size: min(3.25rem, 13.9vw);
    }
  }

/* blocks/_offer.liquid */

  /*
    Figma: white ticket, soft shadow, ~6px radius, 16px padding; bank accent caps ~15px with wide
    spacing; offer ~15px; detail grey ~14px; a 1px dotted line with notches (the card colour shows
    through); code caps letter-spaced; COPY accent caps.
  */
  .offer {
    position: relative;
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    block-size: 100%;
    border-radius: 0.375rem;
    background-color: var(--color-background);
    box-shadow: 0 2px 10px #0000001a;
    rotate: var(--offer-tilt, 0deg); /* set per ticket by Bank offers */
    transition: rotate var(--duration-fast) var(--ease-out);
  }

  /* Straightens up under the pointer, like a ticket picked up */
  .offer:hover,
  .offer:focus-within {
    z-index: 1;
    rotate: 0deg;
  }

  .offer__top {
    flex: 1;
    padding: var(--space-sm) var(--space-sm) var(--space-sm) var(--space-md);
  }

  .offer__bank {
    margin: 0 0 var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .offer__text {
    margin: 0;
    font-size: var(--font-size-caption);
  }

  .offer__detail {
    margin: 0.15em 0 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background)); /* 60% gave 4.35:1 on white */
    font-size: var(--font-size-small);
  }

  /* The tear line, with a notch cut from each edge (radial gradients in a mask) */
  .offer__bottom {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-xs);
    padding: var(--space-sm) var(--space-sm) var(--space-sm) var(--space-md);
    border-block-start: 1px dashed color-mix(in srgb, var(--color-text) 30%, transparent);
  }

  /* The notches: two half-hidden circles in the card colour, centred on the tear line */
  .offer__bottom::before,
  .offer__bottom::after {
    content: "";
    position: absolute;
    inset-block-start: calc(-0.375rem - 0.5px);
    inline-size: 0.75rem;
    block-size: 0.75rem;
    border-radius: 50%;
    /* The card colour is see-through: lay it over the page background, as the card itself shows it */
    background: linear-gradient(var(--color-card), var(--color-card)) var(--color-background);
  }

  .offer__bottom::before {
    inset-inline-start: -0.375rem;
  }

  .offer__bottom::after {
    inset-inline-end: -0.375rem;
  }

  /* A ticket with only a code: no tear line above it (nothing to tear off), it fills the ticket */
  .offer__bottom:first-child {
    flex: 1;
    border-block-start: 0;
  }

  .offer__bottom:first-child::before,
  .offer__bottom:first-child::after {
    content: none;
  }

  .offer__code {
    overflow: hidden;
    font-size: var(--font-size-caption);
    letter-spacing: var(--letter-spacing-label);
    text-overflow: ellipsis;
    text-transform: uppercase;
    white-space: nowrap;
  }

  .offer__copy {
    flex: none;
    min-block-size: 1.5rem;
    padding: 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    cursor: pointer;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  .offer__copy:hover {
    text-decoration: underline;
  }

  .offer:hover .offer__copy,
  .offer:focus-within .offer__copy,
  .offer__copy.is-copied {
    opacity: 1;
  }

  @media (hover: none) {
    .offer__copy {
      opacity: 1;
    }
  }

  /* COPY needs the script: without JavaScript the code stays readable, the button goes */
  @media (scripting: none) {
    .offer__copy {
      display: none;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .offer {
      transition: none;
    }
  }

/* blocks/_pillar.liquid */

  /*
    Figma 1920 (Default-2): label y 265 (accent label, "01 · MISSION"); heading ~66px regular, 2
    lines, ~770 wide (y 330–460); text 24px / 38px (y 515–615); checklist from y 712, rows 58px
    apart: tick 16px at x 55, text at x 102 (body-lg). Sizes: Figma px x --px (set by the
    section) with rem floors.
  */
  .pillar {
    counter-increment: pillar;
    max-inline-size: max(20rem, calc(810 * var(--px)));
  }

  .pillar__label {
    margin: 0 0 max(var(--space-lg), calc(52 * var(--px)));
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* "01 · " before the label (only "01" when the label is empty) */
  .pillar__label::before {
    content: counter(pillar, decimal-leading-zero);
  }

  .pillar__label-text::before {
    content: " · ";
  }

  .pillar__heading {
    margin: 0;
    font-family: var(--font-heading--family);
    font-size: max(2rem, calc(66 * var(--px)));
    font-weight: var(--font-heading--weight);
    line-height: 1.1;
    text-wrap: balance;
  }

  .pillar__text {
    margin-block-start: max(var(--space-lg), calc(50 * var(--px)));
    font-size: var(--font-size-body-lg);
    line-height: 1.6;
  }

  .pillar__text > * {
    margin: 0;
  }

  .pillar__text > * + * {
    margin-block-start: var(--space-md);
  }

  .pillar__checklist {
    display: grid;
    gap: max(var(--space-md), calc(26 * var(--px)));
    margin: max(var(--space-xl), calc(90 * var(--px))) 0 0;
    padding: 0;
    list-style: none;
    font-size: var(--font-size-body-lg);
    line-height: 1.4;
  }

  .pillar__point {
    display: flex;
    align-items: baseline;
    gap: max(var(--space-md), calc(33 * var(--px)));
  }

  .pillar__check {
    flex: none;
    color: var(--color-accent);
  }

  .pillar__check svg {
    display: block;
    inline-size: max(0.875rem, calc(16 * var(--px)));
    block-size: auto;
  }

  /* Editor only: an empty Pillar */
  .pillar__note {
    margin: 0;
    font-style: italic;
    opacity: 0.7;
  }

  /*
    Phones (Variant45-2 at 375px): label ~10px, heading 26px, text 13px with tall lines (~24px),
    checklist 12px, rows 30px apart. Fixed rem values: the screen-scale tokens are clamped and
    multiplied by Text size, which made the phone text too big.
  */
  @media (max-width: 749px) {
    .pillar__label {
      margin-block-end: var(--space-md);
      font-size: 0.625rem;
    }

    .pillar__heading {
      font-size: 1.625rem;
    }

    .pillar__text {
      margin-block-start: var(--space-md);
      font-size: 0.8125rem;
      line-height: 1.8;
    }

    .pillar__checklist {
      gap: 0.75rem;
      margin-block-start: var(--space-lg);
      font-size: 0.75rem;
    }

    .pillar__point {
      gap: var(--space-md);
    }

    .pillar__check svg {
      inline-size: 0.75rem;
    }
  }

/* blocks/_product-feature.liquid */

  .product-feature {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-sm);
  }

  .product-feature__icon {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: max(2.5rem, calc(44 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    color: var(--color-accent);
  }

  /* The pale accent circle behind the icon's lower right (Figma) */
  .product-feature__icon::before {
    content: "";
    position: absolute;
    z-index: 0;
    inset-block-end: 0;
    inset-inline-end: -0.25rem;
    inline-size: 55%;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 12%, transparent);
  }

  .product-feature__icon > * {
    position: relative;
    z-index: 1;
  }

  .product-feature__image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: contain;
  }

  .product-feature__icon svg {
    inline-size: 55%;
    block-size: auto;
  }

  .product-feature__label {
    font-size: var(--font-size-body-sm);
  }

/* blocks/_return-step.liquid */

  /*
    Figma 1920: circles 73 x 73 (1px accent ring, white, "01" body ~20px accent) every 410px; a 1px
    pale line from 8px after the circle to the next one (319 wide, at the circle's middle); title
    heading font ~30px ~58px under the circle; text ~20 / 35, 318 wide; label accent caps ~16px.
    Phones: a vertical timeline (circle left, the line running down to the next circle).
  */
  .return-step {
    counter-increment: return-step;
    position: relative;
    display: flex;
    flex-direction: column;
  }

  .return-step__marker {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: var(--step-marker, max(3.25rem, calc(73 * var(--px))));
    aspect-ratio: 1;
    box-sizing: border-box;
    border: 1px solid var(--color-accent);
    border-radius: 50%;
    background-color: var(--color-background);
    color: var(--color-accent);
    font-size: var(--font-size-body);
    font-variant-numeric: tabular-nums;
  }

  .return-step__marker::before {
    content: counter(return-step, decimal-leading-zero);
  }

  .return-step__body {
    max-inline-size: max(16rem, calc(320 * var(--px)));
  }

  .return-step__title {
    margin: max(var(--space-lg), calc(40 * var(--px))) 0 0;
    font-size: max(1.375rem, calc(30 * var(--px)));
    font-weight: 400;
    line-height: 1.25;
  }

  .return-step__text {
    margin-block-start: max(var(--space-sm), calc(16 * var(--px)));
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .return-step__text > * {
    margin: 0;
  }

  .returns-steps__note {
    margin: 0;
    font-style: italic;
    opacity: 0.7;
  }

  .return-step__label {
    margin: max(var(--space-md), calc(21 * var(--px))) 0 0;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Phones: a vertical timeline */
  @media (max-width: 749px) {
    .return-step {
      display: grid;
      grid-template-columns: 3rem minmax(0, 1fr);
      column-gap: var(--space-md);
      padding-block-end: var(--space-xl);
    }

    .return-step__marker {
      inline-size: 3rem;
      font-size: var(--font-size-caption);
    }

    .return-step__body {
      max-inline-size: none;
    }

    .return-step__title {
      margin-block-start: var(--space-sm);
      font-size: 1.25rem;
    }

    .return-step__text {
      font-size: var(--font-size-body-sm);
      line-height: 1.7;
    }
  }

/* blocks/_social-card.liquid */

  /*
    Figma card: 262 x 267, white, padding 28px top / 37px left. Made roomier on purpose (developer,
    2026-10-30): 300 x 310 Figma px, 64px badge, bigger text. Figma px x --px follow the screen in a
    scaled section (snippets/screen-scale.liquid).
  */
  .social-card {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    min-block-size: max(16.6875rem, calc(310 * var(--px, 0.0625rem)));
    padding: var(--space-xl) var(--space-xl);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-background);
    box-shadow: var(--shadow-card);
    color: var(--color-text);
    text-decoration: none;
    transition:
      transform var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  /* 64px white circle with a soft shadow, 30px logo (Figma 50 / 24, enlarged) */
  .social-card__badge {
    display: grid;
    place-items: center;
    inline-size: max(3.125rem, calc(64 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: #ffffff;
    box-shadow: var(--shadow-card);
    color: var(--color-accent);
  }

  .social-card__badge svg {
    inline-size: max(1.5rem, calc(30 * var(--px, 0.0625rem)));
    block-size: auto;
  }

  /* Brand logos keep their own colours (Instagram gradient, YouTube red…) */
  .social-card__badge--brand {
    color: inherit;
  }

  /*
    Arrow in the corner: a solid right arrow (assets/icon-arrow-solid.svg, drawn centred in its
    16px box, so it turns around its own middle and stays a straight line). At rest it's turned
    -45deg to point up-right (↗); on hover it turns back to point right (→) while the card lifts
    (Figma hover state). It takes the scheme's accent colour (currentColor).
  */
  .social-card__arrow {
    position: absolute;
    inset-block-start: var(--space-lg);
    inset-inline-end: var(--space-lg);
    color: var(--color-accent);
  }

  .social-card__arrow svg {
    display: block;
    inline-size: max(1rem, calc(18 * var(--px, 0.0625rem)));
    block-size: auto;
    transform: rotate(-45deg);
    transition: transform var(--duration-base) var(--ease-out);
  }

  /* The whole card is the link, so the whole card shows the hand cursor */
  .social-card--link {
    cursor: pointer;
  }

  .social-card--link:hover .social-card__arrow svg,
  .social-card--link:focus-visible .social-card__arrow svg {
    transform: rotate(0deg);
  }

  .social-card__name {
    margin: var(--space-lg) 0 0;
    font-family: var(--font-body--family);
    font-style: var(--font-body--style);
    font-weight: var(--font-weight-medium);
    font-size: var(--font-size-h3);
    line-height: var(--line-height-body);
  }

  .social-card__handle {
    margin-block-start: var(--space-sm);
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
    overflow-wrap: anywhere;
  }

  .social-card__followers {
    margin-block-start: var(--space-2xs);
    font-size: var(--font-size-body-lg);
  }

  /* Hover: the card lifts with a soft rose shadow (no movement with reduced motion, shadow only) */
  .social-card--link:hover,
  .social-card--link:focus-visible {
    box-shadow: var(--shadow-card-rose);
  }

  @media (prefers-reduced-motion: no-preference) {
    .social-card--link:hover,
    .social-card--link:focus-visible {
      transform: translateY(-0.5rem);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .social-card__arrow svg {
      transition: none;
    }
  }

  /* All cards in a row are the same height (the flex row stretches the item, the card fills it) */
  .social-card-item {
    display: flex;
  }

  .social-card {
    flex: 1;
    min-inline-size: 0;
  }

  /* Below the wide grid (3 small cards per row): no Figma minimum height */
  @media (max-width: 1439px) {
    .social-card {
      min-block-size: 0;
    }
  }

  /* Phones (phone design): compact cards, small text */
  @media (max-width: 749px) {
    .social-card {
      padding: var(--space-sm);
      border-radius: var(--radius-xs);
    }

    .social-card__badge {
      inline-size: 1.75rem;
    }

    .social-card__badge svg {
      inline-size: 0.875rem;
    }

    .social-card__arrow {
      inset-block-start: var(--space-xs);
      inset-inline-end: var(--space-xs);
    }

    .social-card__arrow svg {
      inline-size: 0.625rem;
    }

    .social-card__name {
      margin-block-start: var(--space-sm);
      font-size: 0.8125rem;
    }

    .social-card__handle,
    .social-card__followers {
      font-size: 0.6875rem;
    }

    .social-card__handle {
      margin-block-start: var(--space-2xs);
    }
  }

/* blocks/_social-list.liquid */

  .social-list {
    container-type: inline-size;
  }

  /*
    Flex rows with a centred last row: with equal cards and equal gaps, two cards in a row of three
    sit exactly under the two gaps above them (Figma 3 + 2), for any number of cards.
  */
  .social-list__grid {
    --social-columns: 1;
    --social-gap: var(--space-sm);
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--social-gap);
  }

  .social-list__grid > * {
    flex: 0 0 calc((100% - (var(--social-columns) - 1) * var(--social-gap)) / var(--social-columns));
    min-inline-size: 0;
  }

  @media (min-width: 375px) {
    .social-list__grid {
      --social-columns: 3;
    }
  }

  @media (min-width: 750px) {
    .social-list__grid {
      --social-gap: var(--space-lg);
    }
  }

  /* Wide: 300 Figma px cards (Figma 262, enlarged), the gaps take the rest (first and third card at the edges) */
  @container (min-width: 62rem) {
    .social-list__grid {
      --social-card-w: max(16.375rem, calc(300 * var(--px, 0.0625rem)));
      column-gap: calc((100% - 3 * var(--social-card-w)) / 2);
      row-gap: var(--space-2xl); /* 42px */
    }

    .social-list__grid > * {
      flex-basis: var(--social-card-w);
    }
  }

  /* Reveal one after the other in each group of five */
  .social-list__grid > :nth-child(5n + 2) { --animate-delay: 100ms; }
  .social-list__grid > :nth-child(5n + 3) { --animate-delay: 200ms; }
  .social-list__grid > :nth-child(5n + 4) { --animate-delay: 300ms; }
  .social-list__grid > :nth-child(5n + 5) { --animate-delay: 400ms; }

  .social-list__note {
    flex-basis: 100%;
    margin: 0;
    padding: var(--space-md);
    border: 1px dashed var(--color-border);
    font-style: italic;
    text-align: center;
  }

/* blocks/_stat-figure.liquid */

  /*
    Figma 1920 (Default-10): card 371x371, #fdfcfb (the card colour on white), 1px pale border,
    radius ~24; centred: value heading font ~70px accent, letter-spaced ~0.1em; rule 30x2 accent
    ~45px under it; title heading font semibold ~34px, ~55px under the rule; text body ~17px,
    ~20px under the title.
  */
  .stat-figure {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    aspect-ratio: 1;
    padding: max(var(--space-lg), calc(32 * var(--px)));
    /*
      Figma: border #f0cbcb4f (= --color-card-border), shadow 0 0 10px #0000000d, fill #f6f2ec33.
      Glass (Light -45°, 80%; Frost 0): like the theme's --glass-rim, a thin white inner edge lit
      from the top left (80% = #ffffffcc) and a weaker one bottom right; -45° is ~0.71px on each
      axis. Frost 0 = no blur. Refraction / dispersion are left out, as elsewhere in the theme (an
      SVG filter, Chrome only).
    */
    border: 1px solid var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px)));
    background-color: #f6f2ec33;
    box-shadow:
      0 0 10px 0 #0000000d,
      inset 0.71px 0.71px 0 #ffffffcc,
      inset -0.71px -0.71px 0 #ffffffad;
    text-align: center;
  }

  .stat-figure__value {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: max(2.5rem, calc(70 * var(--px)));
    line-height: 1;
    letter-spacing: 0.1em;
    /* Letter spacing also adds space after the last character: take it back, so the number is centred */
    margin-inline-end: -0.1em;
    white-space: nowrap;
    /* Every digit as wide as the others, so the number doesn't wobble while it counts */
    font-variant-numeric: tabular-nums;
  }

  .stat-figure__rule {
    display: block;
    inline-size: max(1.5rem, calc(30 * var(--px)));
    block-size: 2px;
    margin-block-start: max(var(--space-lg), calc(45 * var(--px)));
    background-color: var(--color-accent);
  }

  .stat-figure__title {
    margin: max(var(--space-xl), calc(55 * var(--px))) 0 0;
    font-size: max(1.375rem, calc(34 * var(--px)));
    font-weight: 600;
    line-height: 1.15;
  }

  .stat-figure__text {
    margin: max(var(--space-sm), calc(20 * var(--px))) 0 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.4;
  }

  /* Editor only: a card with no number, title or text (it shows nothing on the store) */
  .about-numbers__note {
    margin: 0;
    padding: var(--space-md);
    border: 1px dashed var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px)));
    font-style: italic;
    text-align: center;
  }

  /*
    Phones and tablets (zig-zag, 2 per row). The card stays square but can grow taller when the
    text needs more room (aspect-ratio keeps an automatic minimum height). Container units let the
    number shrink on a narrow card, so a long number (31,400) stays inside it.
  */
  @media (max-width: 1199px) {
    .stat-figure {
      container-type: inline-size;
      padding: var(--space-md) var(--space-sm);
    }

    .stat-figure__value {
      font-size: min(2.25rem, 20cqi);
      letter-spacing: 0.15em;
      margin-inline-end: -0.15em;
    }

    .stat-figure__rule {
      inline-size: 1.25rem;
      margin-block-start: var(--space-md);
    }

    .stat-figure__title {
      margin-block-start: var(--space-md);
      font-size: 1.125rem;
    }

    .stat-figure__text {
      margin-block-start: var(--space-xs);
      font-size: 0.8125rem;
    }
  }

  /*
    Phones (Variant46-3, cards ~148px): thin wide number ~28px with 0.2em letter spacing, title
    13px. The design's text is 9–10px; it is 11px here, the smallest size that is easy to read.
  */
  @media (max-width: 749px) {
    .stat-figure {
      padding: 0.75rem 0.5rem;
      border-radius: 0.75rem;
    }

    .stat-figure__value {
      font-size: min(1.75rem, 22cqi);
      letter-spacing: 0.2em;
      margin-inline-end: -0.2em;
    }

    .stat-figure__rule {
      inline-size: 0.75rem;
      block-size: 1px;
      margin-block-start: 0.625rem;
    }

    .stat-figure__title {
      margin-block-start: 0.75rem;
      font-size: 0.8125rem;
    }

    .stat-figure__text {
      margin-block-start: 0.375rem;
      font-size: 0.6875rem;
      line-height: 1.3;
    }
  }

/* blocks/_team-member.liquid */

  /*
    Figma 1920 (Default-8): photo 393x393, radius ~16; the role word ~48px uppercase, accent outline
    and a faint white fill, centred on the photo's top edge; name heading font ~36px; role accent
    label ~18px letter-spaced, ~20px under the name.
    Hover (image.png): a dark panel (~#1f1f1f, radius ~16) 12px around the photo and the quote; name
    ~30px and role (white) on the photo's bottom over a dark fade; 3 round buttons (~40px) stacked
    in the photo's top right; quote body ~17px white; the role word ~1.1em higher, with a faded copy
    above it. The panel uses the scheme's text colour (dark on light schemes).

    --open is 0 (rest) or 1 (open): every part reads it, so the open state is set in one place
    (hover on mouse devices, or the button's .is-open) and transitions still run.
  */
  .team-member {
    --open: 0;
    --member-pad: max(0.625rem, calc(12 * var(--px)));
    --member-panel: var(--color-text);
    --member-on-panel: var(--color-background);
    --word-size: max(1.5rem, calc(48 * var(--px)));

    position: relative;
    isolation: isolate;
    display: flex;
    flex-direction: column;
    /* The role word's size reads the card's width (cqi) */
    container-type: inline-size;
  }

  @media (hover: hover) {
    .team-member:hover {
      --open: 1;
    }
  }

  .team-member.is-open {
    --open: 1;
  }

  /* The dark panel, drawn around the photo and the text below it (only once the script runs, see the quote) */
  .team-member::before {
    content: "";
    position: absolute;
    z-index: -1;
    inset: calc(var(--member-pad) * -1);
    border-radius: calc(var(--radius-sm) - 3px + var(--member-pad));
    background-color: var(--member-panel);
    box-shadow: 0 1.25rem 2.5rem -1rem color-mix(in srgb, var(--member-panel) 45%, transparent);
    opacity: 0;
  }

  about-team-list:defined .team-member::before {
    opacity: var(--open);
  }

  /*
    The outline role word, over the photo's top edge. Its letters are ::before (CSS content, so
    contrast checkers skip the decoration); the echo's ::before / ::after are the faded copies that
    rise above it. A long word gets smaller to fit the card (--word-em from Liquid, 96cqi = the card
    less a small margin); an older browser without container units keeps the first font-size and
    the … cuts it.
  */
  .team-member__word {
    position: absolute;
    z-index: 2;
    inset-block-start: 0;
    inset-inline: 0;
    color: #ffffff66;
    font-family: var(--font-body--family);
    font-size: var(--word-size);
    font-size: min(var(--word-size), calc(96cqi / var(--word-em, 8)));
    font-weight: 700;
    line-height: 1;
    text-align: center;
    text-transform: uppercase;
    white-space: nowrap;
    -webkit-text-stroke: 1px var(--color-accent);
    transform: translateY(calc(-55% - (var(--member-pad) + 0.6em) * var(--open)));
    pointer-events: none;
  }

  .team-member__word::before,
  .team-member__word-echo::before,
  .team-member__word-echo::after {
    content: attr(data-word);
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .team-member__word-echo {
    position: absolute;
    inset: 0;
  }

  /* Two faded copies (open): ::before just above the word, ::after above that, fainter */
  .team-member__word-echo::before,
  .team-member__word-echo::after {
    position: absolute;
    inset: 0;
    color: #ffffff99;
    -webkit-text-stroke: 1px color-mix(in srgb, var(--color-text) 14%, transparent);
    opacity: var(--open);
    transform: translateY(calc(-0.8em * var(--open)));
  }

  .team-member__word-echo::after {
    -webkit-text-stroke-color: color-mix(in srgb, var(--color-text) 8%, transparent);
    transform: translateY(calc(-1.6em * var(--open)));
  }

  .team-member__media {
    position: relative;
    overflow: hidden;
    aspect-ratio: 1;
    border-radius: calc(var(--radius-sm) - 3px);
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
  }

  .team-member__media .image,
  .team-member__media img,
  .team-member__media svg {
    inline-size: 100%;
    block-size: 100%;
  }

  /* Name + role on the photo (open): over a dark fade at the bottom */
  .team-member__overlay {
    position: absolute;
    inset: auto 0 0;
    padding: 4rem var(--space-md) var(--space-md);
    background: linear-gradient(to bottom, #00000000, #000000a6);
    color: #ffffff;
    opacity: var(--open);
    transform: translateY(calc((1 - var(--open)) * 0.75rem));
  }

  .team-member__overlay-name {
    margin: 0;
    font-family: var(--font-heading--family);
    font-size: max(1.375rem, calc(30 * var(--px)));
    line-height: 1.2;
  }

  .team-member__overlay-role {
    margin: var(--space-xs) 0 0;
    font-size: var(--font-size-caption);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .team-member__social {
    position: absolute;
    z-index: 2;
    inset-block-start: var(--space-sm);
    inset-inline-end: var(--space-sm);
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    margin: 0;
    padding: 0;
    list-style: none;
    opacity: var(--open);
    transform: translateX(calc((1 - var(--open)) * 0.5rem));
    /* Hidden buttons can't be tapped (the card's button takes the tap); keyboard focus still reaches them */
    pointer-events: none;
  }

  .team-member.is-open .team-member__social {
    pointer-events: auto;
  }

  /* Keyboard focus on a social button shows the buttons only (the card's button keeps its own state) */
  .team-member__social:focus-within {
    opacity: 1;
    transform: none;
    pointer-events: auto;
  }

  @media (hover: hover) {
    .team-member:hover .team-member__social {
      pointer-events: auto;
    }
  }

  /* No backdrop blur (it repainted on every scroll frame): an almost solid white circle */
  .team-member__social-link {
    display: grid;
    place-items: center;
    inline-size: max(2.75rem, calc(52 * var(--px)));
    block-size: max(2.75rem, calc(52 * var(--px)));
    border-radius: 50%;
    background-color: #ffffffd9;
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
  }

  @media (hover: hover) {
    .team-member__social-link:hover {
      background-color: #ffffff;
    }
  }

  .team-member__social-link svg {
    inline-size: max(1.375rem, calc(24 * var(--px)));
    block-size: max(1.375rem, calc(24 * var(--px)));
  }

  /* The card's button: transparent, over the whole panel (the social buttons sit above it) */
  .team-member__toggle {
    position: absolute;
    z-index: 1;
    inset: calc(var(--member-pad) * -1);
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: calc(var(--radius-sm) - 3px + var(--member-pad));
    background: none;
    color: inherit;
    cursor: pointer;
  }

  .team-member__toggle[hidden] {
    display: none;
  }

  /*
    Without JS (and before the script is defined) the quote shows under the caption, in the text
    colour. Once defined, the caption (rest) and the quote (open) share one cell, so the card's
    height doesn't jump on hover.
  */
  .team-member__below {
    display: grid;
    gap: var(--space-sm);
    margin-block-start: max(var(--space-md), calc(20 * var(--px)));
  }

  about-team-list:defined .team-member__caption,
  about-team-list:defined .team-member__quote {
    grid-area: 1 / 1;
  }

  about-team-list:defined .team-member__caption {
    opacity: calc(1 - var(--open));
  }

  .team-member__name {
    margin: 0;
    font-size: max(1.5rem, calc(36 * var(--px)));
    font-weight: 400;
    line-height: 1.2;
  }

  .team-member__role {
    margin: max(var(--space-sm), calc(16 * var(--px))) 0 0;
    color: var(--color-accent);
    font-size: var(--font-size-label);
    letter-spacing: var(--letter-spacing-label);
    line-height: 1.3;
    text-transform: uppercase;
  }

  .team-member__quote {
    margin: 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  about-team-list:defined .team-member__quote {
    color: var(--member-on-panel);
    opacity: var(--open);
  }

  .team-member__quote p {
    margin: 0;
  }

  @media (prefers-reduced-motion: no-preference) {
    .team-member::before,
    .team-member__word,
    .team-member__word-echo::before,
    .team-member__word-echo::after,
    .team-member__overlay,
    .team-member__social,
    .team-member__caption,
    .team-member__quote {
      transition:
        opacity var(--duration-slow) var(--ease-out),
        transform var(--duration-slow) var(--ease-out);
    }
  }

  /* Phones and tablets ("leaders"): smaller words, smaller panel padding */
  @media (max-width: 1199px) {
    .team-member {
      --word-size: clamp(1.125rem, 4.5vw, 2.25rem);
    }

    .team-member__name {
      font-size: clamp(1rem, 3.2vw, 1.75rem);
    }

    .team-member__role {
      margin-block-start: var(--space-xs);
      font-size: clamp(0.5625rem, 1.6vw, 0.875rem);
      letter-spacing: 0.12em;
    }

    .team-member__quote {
      font-size: var(--font-size-caption);
    }
  }

  /*
    Phones: the card is ~160px wide, so a quote in the caption's cell would leave a tall empty space
    under every card. The quote takes the caption's place only while the card is open (the button),
    and the dark panel follows the button only (a narrow window with a mouse would otherwise show
    the dark caption on the dark panel).
  */
  @media (max-width: 749px) {
    about-team-list:defined .team-member::before {
      opacity: 0;
    }

    about-team-list:defined .team-member.is-open::before {
      opacity: 1;
    }

    about-team-list:defined .team-member__caption {
      opacity: 1;
    }

    about-team-list:defined .team-member__quote {
      display: none;
      grid-area: auto;
      opacity: 1;
    }

    about-team-list:defined .team-member.is-open .team-member__quote {
      display: block;
    }

    /* Open: the caption leaves the flow but stays for screen readers (the name on the photo is aria-hidden) */
    about-team-list:defined .team-member.is-open:has(.team-member__quote) .team-member__caption {
      position: absolute;
      inline-size: 1px;
      block-size: 1px;
      overflow: hidden;
      clip-path: inset(50%);
      white-space: nowrap;
    }

    /* The photo is ~160px tall, so smaller buttons keep all three on it */
    .team-member__social {
      inset-block-start: var(--space-xs);
      inset-inline-end: var(--space-xs);
      gap: var(--space-xs);
    }

    .team-member__social-link {
      inline-size: 2rem;
      block-size: 2rem;
    }

    .team-member__social-link svg {
      inline-size: 1rem;
      block-size: 1rem;
    }
  }

/* blocks/_trending-sheet.liquid */

  /* The sheet: a solid panel in the section's background colour (dark in the Dark scheme) */
  .banner-sheet {
    position: relative;
    isolation: isolate;
    display: flex;
    flex-direction: column;
    /*
      Figma: the heading sits just under the sticky header and the rows run down to the bottom.
      So the content starts at the top (no centring: that left an empty band above it on tall screens)
      and the list stretches to fill the rest of the sheet (see below).
    */
    justify-content: flex-start;
    padding: clamp(7rem, 3rem + 7vw, 11rem) clamp(var(--page-margin), 3vw, 4rem) clamp(2rem, 1rem + 2vw, 4rem);
    background-color: var(--color-background);
    color: var(--color-text);

    /* Scrollbar (when the list is taller than the screen): thin, gold thumb on a faint track */
    scrollbar-width: thin;
    scrollbar-color: var(--color-accent) color-mix(in srgb, var(--color-text) 10%, transparent);
  }

  /*
    The list fills the sheet's height: heading at the top, then the rows spread evenly down to the
    bottom (space-between). Gaps follow the screen height (svh); when the rows don't fit, the gaps
    shrink to their minimum and the sheet scrolls from the top, so row 01 is always reachable.
  */
  .banner-sheet .trending-list {
    flex: 1;
    gap: clamp(1.5rem, 5svh, 4.5rem);
  }

  .banner-sheet .trending-list > animate-on-scroll {
    display: flex;
    flex: 1;
    flex-direction: column;
  }

  .banner-sheet .trending-list__rows {
    flex: 1;
    justify-content: space-between;
    gap: clamp(0.75rem, 2svh, 2rem);
  }

  /*
    Phones (Figma mobile): the rows stay together under the heading with an even gap (no spread to the
    bottom), and the heading is closer to the list; the space left under the list stays empty.
  */
  @media (max-width: 749px) {
    .banner-sheet .trending-list {
      gap: 1.25rem;
    }

    .banner-sheet .trending-list__rows {
      justify-content: flex-start;
      gap: 1.5rem;
    }
  }

  .banner-sheet::-webkit-scrollbar {
    inline-size: 6px;
  }

  .banner-sheet::-webkit-scrollbar-track {
    background: color-mix(in srgb, var(--color-text) 10%, transparent);
  }

  .banner-sheet::-webkit-scrollbar-thumb {
    border-radius: var(--radius-pill);
    background: var(--color-accent);
  }

/* blocks/_value-card.liquid */

  /*
    Figma 1920 (Default-9): card #fcfafa, 1px pale border, radius ~24, soft shadow, padding ~32;
    icon 50px circle, accent ~10% fill, accent icon 24px; number heading font thin ~90px, accent
    ~20%, top right (its top in line with the icon); title heading font semibold ~36px accent,
    ~24px under the icon; text body ~18px / 29px, ~30px under the title; photo 471x225, radius ~24,
    ~20px under the text, at the card's bottom.
    Phones (Variant49 / 50, 375px): padding ~16–20, icon ~26px, number ~26px, title ~17px, text
    ~10–11px; the featured card's photo ~120x195 beside the text (text column : photo ~ 1 : 0.7).
  */
  .value-card {
    counter-increment: value-card;
    display: flex;
    flex-direction: column;
    gap: max(var(--space-md), calc(20 * var(--px)));
    block-size: 100%;
    box-sizing: border-box;
    padding: max(var(--space-lg), calc(32 * var(--px)));
    border: 1px solid var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px)));
    background-color: color-mix(in srgb, var(--color-accent) 2%, var(--color-background));
    box-shadow: 0 2px 10px 0 #0000001a;
  }

  /* Figma: title ~24px under the icon row, text ~30px under the title */
  .value-card__body {
    display: flex;
    flex-direction: column;
  }

  .value-card__top {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-md);
  }

  .value-card__icon {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: max(2.75rem, calc(50 * var(--px)));
    block-size: max(2.75rem, calc(50 * var(--px)));
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 10%, transparent);
    color: var(--color-accent);
  }

  .value-card__icon svg {
    inline-size: max(1.25rem, calc(24 * var(--px)));
    block-size: max(1.25rem, calc(24 * var(--px)));
  }

  /* "01", "02"…: the section's counter (one per card) */
  .value-card__number::before {
    content: counter(value-card, decimal-leading-zero);
  }

  /*
    line-height 1 and no negative margin: a tighter box let the digits rise above it, through the
    card's top padding (they touched the card's edge).
  */
  .value-card__number {
    margin: 0;
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-family: var(--font-heading--family);
    font-size: max(3rem, calc(90 * var(--px)));
    font-weight: 200;
    line-height: 1;
  }

  .value-card__title {
    margin: max(var(--space-md), calc(24 * var(--px))) 0 0;
    color: var(--color-accent);
    font-size: max(1.5rem, calc(36 * var(--px)));
    font-weight: 600;
    line-height: 1.1;
  }

  .value-card__text {
    margin-block-start: max(var(--space-lg), calc(30 * var(--px)));
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  .value-card__text > * {
    margin: 0;
  }

  .value-card__text > * + * {
    margin-block-start: max(var(--space-md), calc(24 * var(--px)));
  }

  /*
    The photo fills what is left of the card and never makes it taller: the img is taken out of the
    flow (absolute), so the two-row card is as tall as its two rows (~326px each), not the photo.
  */
  .value-card__media {
    position: relative;
    overflow: hidden;
    flex: 1 1 0;
    min-block-size: max(10rem, calc(225 * var(--px)));
    border-radius: max(1rem, calc(24 * var(--px)));
  }

  .value-card__media .image {
    position: absolute;
    inset: 0;
  }

  .value-card__media .image,
  .value-card__media img {
    inline-size: 100%;
    block-size: 100%;
  }

  /*
    Phones and tablets: smaller type. The featured first card (the section adds --feature) puts its
    photo beside the text, as tall as the text (the img is absolute, so the row height comes from
    the text); the other cards keep the photo under their text.
  */
  @media (max-width: 1199px) {
    .value-card {
      gap: var(--space-sm);
      padding: var(--space-md);
    }

    .value-card__icon {
      inline-size: 2.25rem;
      block-size: 2.25rem;
    }

    .value-card__icon svg {
      inline-size: 1.125rem;
      block-size: 1.125rem;
    }

    .value-card__number {
      font-size: 2.25rem;
    }

    .value-card__title {
      margin-block-start: var(--space-sm);
      font-size: clamp(1.125rem, 3.5vw, 1.75rem);
    }

    .value-card__text {
      margin-block-start: var(--space-sm);
      font-size: clamp(0.75rem, 2vw, 1rem);
    }

    .value-card__media {
      flex: none;
      min-block-size: 0;
      aspect-ratio: 16 / 10;
    }

    /* The icon row stays full width (the number at the card's corner); the photo sits beside the title and text */
    .about-values__list--feature > .value-card--media:first-child {
      display: grid;
      grid-template-columns: minmax(0, 1fr) minmax(0, 0.7fr);
      grid-template-rows: auto auto 1fr;
      grid-template-areas:
        "top top"
        "title media"
        "text media";
      gap: 0 var(--space-md);
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__body {
      display: contents;
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__top {
      grid-area: top;
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__title {
      grid-area: title;
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__text {
      grid-area: text;
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__media {
      grid-area: media;
      min-block-size: 10rem;
      margin-block-start: var(--space-sm);
      aspect-ratio: auto;
    }
  }

  /* Phones (Variant49 / 50): compact cards, 2 per row (the section) */
  @media (max-width: 749px) {
    .value-card {
      gap: var(--space-sm);
      padding: 1rem;
      border-radius: 1.25rem;
    }

    .value-card__icon {
      inline-size: 1.625rem;
      block-size: 1.625rem;
    }

    .value-card__icon svg {
      inline-size: 0.875rem;
      block-size: 0.875rem;
    }

    .value-card__number {
      font-size: 1.75rem;
    }

    .value-card__title {
      margin-block-start: 0.75rem;
      font-size: 1.0625rem;
      line-height: 1.2;
    }

    .value-card__text {
      margin-block-start: 0.75rem;
      font-size: 0.6875rem;
      line-height: 1.65;
    }

    .value-card__text > * + * {
      margin-block-start: 0.75rem;
    }

    .value-card__media {
      border-radius: 0.875rem;
    }

    .about-values__list--feature > .value-card--media:first-child {
      column-gap: 0.75rem;
    }

    .about-values__list--feature > .value-card--media:first-child .value-card__media {
      min-block-size: 8rem;
      margin-block-start: 0.75rem;
      border-radius: 1.25rem;
    }
  }

/* blocks/button.liquid */

  /*
    The pill / outline / text looks come from .button, .button--secondary and .button--text in
    critical.css. This block only adds its own bits: its width, its alignment and the optional arrow.

    fit-content: the button keeps its natural width instead of stretching across a section's column.
    Alignment uses auto margins, which work the same in a section (grid) and in a Group column (flex):
    an auto margin takes up all the free space on that side. In a Group row, the Group's own
    alignment places the buttons, so leave the button on "left" there.
  */
  /*
    margin-block: 0 cancels critical.css's "button after a button gets 12px on top" (meant for stacked
    form buttons): in a Group row it would drop the second button 12px lower. Spacing between blocks
    comes from the Group's Gap setting instead.
  */
  .button-block {
    inline-size: fit-content;
    margin-block: 0;
  }

  .button-block--center {
    margin-inline: auto;
  }

  .button-block--right {
    margin-inline-start: auto;
  }

  .button-block__icon {
    display: inline-flex;
  }

  .button-block__icon svg {
    inline-size: 1em;
    block-size: auto;
  }

  /* No link yet: still shown in the editor, but clearly not clickable */
  .button-block[aria-disabled='true'] {
    opacity: 0.5;
    cursor: not-allowed;
  }

/* blocks/buy-buttons.liquid */

  .buy-buttons__form {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  /* The product page: more air between the option groups, the purchase options and the buttons */
  .buy-buttons--inline .buy-buttons__form {
    gap: max(var(--space-lg), calc(28 * var(--px, 0.0625rem)));
  }

  .buy-buttons__label {
    display: block;
    margin-block-end: var(--space-xs);
    padding: 0;
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* The chosen swatch's name next to the option name ("COLOR  Rose") */
  .buy-buttons__chosen {
    margin-inline-start: var(--space-sm);
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-weight: 400;
    letter-spacing: normal;
    text-transform: none;
  }

  /*
    Without JavaScript the select is the picker and the pills stay hidden (they need the script). With
    JavaScript the pills show from the first paint (scripting media query), so the card does not move when
    the script runs
  */
  .buy-buttons__options {
    display: none;
  }

  @media (scripting: enabled) {
    .buy-buttons__options {
      display: flex;
      flex-direction: column;
      gap: var(--space-md);
    }

    .buy-buttons__select {
      display: none;
    }

    /* Two classes: the base rule (display: none) comes later in this file */
    .buy-buttons .buy-buttons__step {
      display: grid;
    }

    /*
      Until the script has run (slow connection), the pills and − / + can't change the hidden select: they
      don't react, so Add to cart always sends the variant the pills show
    */
    buy-buttons:not(:defined) :is(.buy-buttons__pills, .buy-buttons__step) {
      pointer-events: none;
    }
  }

  .buy-buttons__option {
    margin: 0;
    padding: 0;
    border: 0;
  }

  .buy-buttons__pills {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
  }

  /* The radio itself is invisible but still focusable and clickable through its label */
  .buy-buttons__pill-input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
  }

  /* Figma PDP: outlined grey pill; the chosen one filled with the accent colour */
  /*
    margin 0 on the labels that follow their radio (pill, swatch, purchase card): the global form rule
    (input + label: margin-block-start) would push each one 12px down
  */
  .buy-buttons__pill {
    margin: 0;
    padding: 0.55em 1.25em;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    cursor: pointer;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  /* The pill's own grey (70% mix) already passes 4.5:1; an extra fade made "(+$X)" fail (3.43:1) */
  .buy-buttons__pill-extra {
    margin-inline-start: 0.35em;
  }

  /* "Show images for options": the variant's image in a small circle before the name */
  .buy-buttons__pill--image {
    display: inline-flex;
    align-items: center;
    gap: 0.5em;
    padding-block: 0.25em;
    padding-inline-start: 0.25em;
  }

  .buy-buttons__pill-image {
    flex: none;
    inline-size: 2rem;
    block-size: 2rem;
    border-radius: 50%;
    object-fit: cover;
  }

  /*
    A value that can't be bought with the other chosen values: dimmed (default), or also crossed out
    ("Unavailable values" setting). It can still be chosen: the button then says Sold out / Unavailable.
    Pills: no opacity (it faded the text to 1.97:1 and a chosen pill's white on accent to 2.81:1, and a
    pill that can be chosen is not exempt from contrast): a dashed, paler border and a light tint
    instead; the text keeps the pill's own grey (passes 4.5:1). Swatches have no text: they still fade.
  */
  .buy-buttons__pill-input[data-state] + .buy-buttons__pill {
    border-style: dashed;
    border-color: color-mix(in srgb, var(--color-border) 60%, transparent);
    background-color: color-mix(in srgb, var(--color-text) 5%, transparent);
  }

  .buy-buttons__pill-input[data-state] + .buy-buttons__swatch {
    opacity: 0.45;
  }

  .buy-buttons--cross .buy-buttons__pill-input[data-state] + .buy-buttons__pill {
    text-decoration: line-through;
  }

  .buy-buttons--cross .buy-buttons__pill-input[data-state] + .buy-buttons__swatch::after {
    content: "";
    position: absolute;
    inset: 50% -10%;
    block-size: 1px;
    background-color: var(--color-text);
    transform: rotate(-45deg);
  }

  .buy-buttons__pill-input:checked + .buy-buttons__pill {
    border-color: var(--color-accent);
    background-color: var(--color-accent);
    color: var(--color-button-text);
  }

  .buy-buttons__pill-input:focus-visible + .buy-buttons__pill,
  .buy-buttons__pill-input:focus-visible + .buy-buttons__swatch {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  /* Figma Variant64: ~34px circles, a ring around the chosen one */
  .buy-buttons__pills--swatches {
    gap: var(--space-sm);
  }

  .buy-buttons__swatch {
    position: relative;
    display: block;
    margin: 0;
    overflow: hidden;
    inline-size: max(2rem, calc(34 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    border: 1px solid color-mix(in srgb, var(--color-text) 15%, transparent);
    border-radius: 50%;
    background-color: var(--swatch-color, var(--color-background));
    cursor: pointer;
  }

  .buy-buttons__swatch-image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .buy-buttons__pill-input:checked + .buy-buttons__swatch {
    box-shadow:
      0 0 0 2px var(--color-card, var(--color-background)),
      0 0 0 3px var(--color-accent);
  }

  .buy-buttons__select select {
    inline-size: 100%;
  }

  /*
    Purchase options (Figma PDP): two cards ~700px wide, cream with a pale border, radius ~12; the
    chosen one has a 1px accent border. A round mark at the left: empty ring, or an accent circle with
    a white tick when chosen.
  */
  .buy-buttons__plans {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    max-inline-size: 43.75rem;
    margin: 0;
    padding: 0;
    border: 0;
  }

  /* A plan card the chosen variant has no plan for (the class's display would beat [hidden]) */
  .buy-buttons__plan[hidden] {
    display: none;
  }

  .buy-buttons__plan {
    border: 1px solid var(--color-card-border);
    border-radius: max(0.75rem, calc(12 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-background) 60%, transparent);
    transition: border-color var(--duration-fast) var(--ease-out);
  }

  .buy-buttons__plan:has(.buy-buttons__plan-input:checked) {
    border-color: var(--color-accent);
  }

  .buy-buttons__plan:has(.buy-buttons__plan-input:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .buy-buttons__plan-input {
    position: absolute;
    opacity: 0;
    pointer-events: none;
  }

  .buy-buttons__plan-head {
    display: grid;
    margin: 0;
    grid-template-columns: auto auto 1fr auto;
    align-items: center;
    gap: var(--space-xs) var(--space-md);
    padding: var(--space-lg) max(var(--space-lg), calc(34 * var(--px, 0.0625rem)));
    cursor: pointer;
  }

  .buy-buttons__plan-mark {
    display: grid;
    place-items: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    border: 1px solid color-mix(in srgb, var(--color-text) 25%, transparent);
    border-radius: 50%;
    color: transparent;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      border-color var(--duration-fast) var(--ease-out);
  }

  .buy-buttons__plan-mark svg {
    inline-size: 0.75rem;
    block-size: auto;
  }

  .buy-buttons__plan-input:checked + .buy-buttons__plan-head .buy-buttons__plan-mark {
    border-color: var(--color-accent);
    background-color: var(--color-accent);
    color: var(--color-button-text);
  }

  .buy-buttons__plan-title {
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* "RECOMMENDED": a pale accent pill */
  .buy-buttons__plan-tag {
    justify-self: start;
    padding: 0.3em 0.9em;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .buy-buttons__plan-price {
    grid-column: 4;
    grid-row: 1;
    font-size: var(--font-size-h3); /* Figma ~24px */
    font-weight: var(--font-weight-medium);
  }

  /* "No commitment • Standard price" under the title */
  .buy-buttons__plan-note {
    grid-column: 2 / 4;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  .buy-buttons__plan-body {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    padding: 0 max(var(--space-lg), calc(34 * var(--px, 0.0625rem))) var(--space-lg);
    padding-inline-start: calc(max(var(--space-lg), calc(34 * var(--px, 0.0625rem))) + 1.5rem + var(--space-md));
  }

  .buy-buttons__plan-label {
    font-size: var(--font-size-label);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

  .buy-buttons__plan-select {
    max-inline-size: 28rem;
    border-radius: var(--radius-pill);
  }

  .buy-buttons__plan-perks {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    margin: var(--space-sm) 0 0;
    padding: 0;
    list-style: none;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

  /* A small accent tick before each perk */
  .buy-buttons__plan-perks li {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
  }

  .buy-buttons__plan-perks li::before {
    content: "✓";
    color: var(--color-accent);
  }

  .buy-buttons__row {
    display: flex;
    gap: var(--space-sm);
  }

  /* Figma PDP: stepper at the left, Add to cart and Buy now side by side; they wrap on narrow cards */
  /*
    Top-aligned: with a subscription Shopify adds its legal text ("This item is a recurring purchase...")
    under Buy now; it must stay visible, and the other buttons stay level with Buy now.
  */
  .buy-buttons--inline .buy-buttons__row {
    flex-wrap: wrap;
    align-items: flex-start;
    gap: var(--space-md) max(var(--space-md), calc(40 * var(--px, 0.0625rem)));
  }

  /*
    Quantity: a pill with − and + around the number, the same height and roundness as Add to cart.
    Without JavaScript the − / + are hidden and the number field works on its own.
  */
  .buy-buttons__quantity {
    display: flex;
    align-items: center;
    min-block-size: 3.125rem;
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-surface-raised);
  }

  /* In a row: a pale accent edge (the tint of the "Recommended" pill), softer than Add to cart */
  .buy-buttons--inline .buy-buttons__quantity {
    border-color: color-mix(in srgb, var(--color-accent) 35%, transparent);
    box-shadow: var(--shadow-glass-edge);
  }

  .buy-buttons__step {
    display: none;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 100%;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background: none;
    color: var(--color-text);
    line-height: 1;
    cursor: pointer;
  }

  /* − / + are SVG icons (a text "+" sat lower than "−": the font draws them at different heights) */
  .buy-buttons__step svg {
    display: block;
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .buy-buttons__step:hover {
    color: var(--color-accent);
  }

  /* .buy-buttons in front: the global input[type] rule (element + attribute) beats one class */
  .buy-buttons .buy-buttons__quantity-input {
    inline-size: 3rem;
    min-block-size: 0;
    padding: 0;
    border: 0;
    background: none;
    font-weight: var(--font-weight-medium);
    text-align: center;
    appearance: textfield; /* hides the browser's tiny up/down arrows */
  }

  .buy-buttons__quantity-input::-webkit-inner-spin-button,
  .buy-buttons__quantity-input::-webkit-outer-spin-button {
    margin: 0;
    appearance: none;
  }

  .buy-buttons__quantity-input:focus-visible {
    outline: none;
  }

  .buy-buttons__quantity:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  /* Shop Pay Installments: Shopify's own banner, in our text colour */
  .buy-buttons__installments:empty {
    display: none;
  }

  .buy-buttons__installments shopify-payment-terms {
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-small);
  }

  /*
    Accelerated checkout (Shopify's own buttons). Branded ones (Shop Pay, Apple Pay...) take their size
    and corner radius from Shopify's CSS variables; the plain "Buy it now" is styled like our buttons:
    a dark pill under Add to cart, or (product page, "inline") the red pill with the buy icon.
  */
  .buy-buttons__payment {
    --shopify-accelerated-checkout-button-block-size: 3.125rem;
    --shopify-accelerated-checkout-button-border-radius: 3.125rem;
  }

  .buy-buttons__payment .shopify-payment-button__button--unbranded {
    min-block-size: 3.125rem;
    padding: 0 var(--space-lg);
    border-radius: var(--radius-pill);
    background-color: var(--color-text);
    color: var(--color-background);
    font-family: inherit;
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .buy-buttons__payment .shopify-payment-button__button--unbranded:hover:not([disabled]) {
    background-color: color-mix(in srgb, var(--color-text) 85%, var(--color-background));
  }

  .buy-buttons__payment .shopify-payment-button__more-options {
    margin-block-start: var(--space-xs);
    color: inherit;
    font-size: var(--font-size-small);
  }

  /* In a row: each button as wide as its label (never on two lines), the free space shared out; the row
     breaks only when the labels do not fit side by side */
  .buy-buttons--inline .buy-buttons__payment {
    flex: 1 1 auto;
  }

  .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    background-color: var(--color-button);
    color: var(--color-button-text);
    box-shadow: var(--shadow-button);
    font-size: var(--font-size-caption);
    letter-spacing: var(--letter-spacing-nav);
  }

  .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded:hover:not([disabled]) {
    background-color: color-mix(in srgb, var(--color-button) 88%, #000000);
  }

  /* The buy icon, drawn in the text colour through a mask (Shopify's button has no room for an <svg>) */
  .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded::before {
    content: "";
    inline-size: 1.5rem;
    block-size: 1.5rem;
    background-color: currentcolor;
    -webkit-mask: var(--icon-buy) center / contain no-repeat;
    mask: var(--icon-buy) center / contain no-repeat;
  }

  .buy-buttons__submit {
    flex: 1;
  }

  .buy-buttons--inline .buy-buttons__submit,
  .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
    flex: 1 1 auto;
    white-space: nowrap;
  }

  /*
    "Outline glass" Add to cart (Figma PDP: a white glass pill, accent text). Restates .button--secondary
    because the global button[type="submit"] rule (element + attribute) beats that one class.
  */
  .buy-buttons .buy-buttons__submit.button--secondary {
    border-color: var(--color-secondary-button-border);
    background-color: var(--color-secondary-button);
    color: var(--color-secondary-button-text);
    box-shadow: var(--shadow-glass-edge);
  }

  .buy-buttons .buy-buttons__submit.button--secondary:hover:not(:disabled) {
    background-color: color-mix(in srgb, var(--color-secondary-button-text) 8%, var(--color-secondary-button));
  }

  /* The icons sit on the middle of the label line (block svg: no space under it for text descenders) */
  .buy-buttons__submit-icon {
    display: inline-flex;
    align-items: center;
  }

  .buy-buttons__submit-icon svg {
    display: block;
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  /*
    While it adds: the button keeps its colour, the label dims a little and a small spinning ring takes
    the place of the cart icon (the sticky bar draws the same on its own button). Then the product photo flies to the
    header cart (script) and the label says "Added" for 2s
  */
  .buy-buttons__submit.is-adding {
    cursor: progress;
  }

  .buy-buttons__submit.is-adding .buy-buttons__submit-icon {
    display: none;
  }

  .buy-buttons__submit.is-adding [data-submit-label] {
    opacity: 0.7;
  }

  .buy-buttons__submit.is-adding::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    border: 2px solid color-mix(in srgb, currentcolor 25%, transparent);
    border-block-start-color: currentcolor;
    border-radius: 50%;
  }

  @media (prefers-reduced-motion: no-preference) {
    .buy-buttons__submit.is-adding::before {
      animation: buy-buttons-spin 0.7s linear infinite;
    }
  }

  @keyframes buy-buttons-spin {
    to {
      rotate: 1turn;
    }
  }

  /* The flying photo (made by the script, on <body>); the header draws the cart icon's bump when it lands */
  /*
    A light glass bubble: a thin accent ring, a small light gap round the photo and a soft glow in the
    accent colour (it follows the colour scheme, so it suits red and dark schemes too)
  */
  .cart-flight {
    position: fixed;
    z-index: 1000;
    inline-size: 3.5rem;
    block-size: 3.5rem;
    padding: 3px;
    border: 1.5px solid color-mix(in srgb, var(--color-accent) 55%, transparent);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-surface-raised, #ffffff) 85%, transparent);
    box-shadow:
      0 10px 28px color-mix(in srgb, var(--color-accent) 30%, transparent),
      inset 0 1px 0 #ffffffcc;
    pointer-events: none;
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
  }

  .cart-flight img {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    border-radius: 50%;
    object-fit: cover;
  }

  .buy-buttons__message {
    margin: 0;
    color: var(--color-error);
    font-size: var(--font-size-small);
  }

  /* Quantity rules and volume pricing (B2B): small grey text under the buttons */
  .buy-buttons__rules:empty,
  .buy-buttons__rules:not(:has(.buy-buttons__rule:not([hidden]))),
  .buy-buttons__rule[hidden] {
    display: none;
  }

  .buy-buttons__rule {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-small);
  }

  .buy-buttons__rule-line {
    display: flex;
    flex-wrap: wrap;
    gap: 0 var(--space-md);
    margin: 0;
  }

  .buy-buttons__rule-title {
    margin: var(--space-xs) 0 0;
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .buy-buttons__breaks {
    display: grid;
    grid-template-columns: max-content max-content;
    gap: 0.25rem var(--space-lg);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .buy-buttons__breaks li {
    display: contents;
  }

  .buy-buttons__submit:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }

  @media (max-width: 749px) {
    .buy-buttons__plan-head,
    .buy-buttons__plan-body {
      padding-inline: var(--space-md);
    }

    .buy-buttons__plan-head {
      grid-template-columns: auto 1fr auto;
    }

    .buy-buttons__plan-tag {
      grid-column: 2;
    }

    .buy-buttons__plan-price {
      grid-column: 3;
    }

    .buy-buttons__plan-note {
      grid-column: 2 / -1;
    }

    /*
      Phones (user, 2026-11-25; the Figma Variant96 put all three in one row, which made them small and
      close together): quantity and Add to cart share the first row, Buy now gets its own full-width row
      below. The labels keep a readable size
    */
    .buy-buttons--inline .buy-buttons__row {
      gap: var(--space-sm);
    }

    .buy-buttons--inline .buy-buttons__payment {
      flex-basis: 100%;
    }

    /* 32px − / + (above the WCAG 2.2 minimum of 24px) */
    .buy-buttons--inline .buy-buttons__step {
      inline-size: 2rem;
    }

    /* Room for 3 digits (a B2B rule can start at 6 and go up in steps) */
    .buy-buttons.buy-buttons--inline .buy-buttons__quantity-input {
      inline-size: 3ch;
    }

    .buy-buttons--inline .buy-buttons__submit,
    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
      gap: var(--space-xs);
      padding-inline: var(--space-md);
      font-size: 0.75rem;
      letter-spacing: 0.08em;
    }

    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
      inline-size: 100%;
    }

    .buy-buttons--inline .buy-buttons__submit-icon svg,
    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded::before {
      inline-size: 1.125rem;
      block-size: 1.125rem;
    }
  }
  /*
    Small laptops (990–1449px): the info card is narrow, so less padding and gap keep quantity, Add to cart
    and Buy now on one line
  */
  @media (min-width: 990px) and (max-width: 1449px) {
    .buy-buttons--inline .buy-buttons__row {
      column-gap: var(--space-sm);
    }

    .buy-buttons--inline .buy-buttons__submit,
    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
      padding-inline: var(--space-md);
    }
  }

  /* 990–1199px: the narrowest info card. Also a narrower stepper and less letter spacing */
  @media (min-width: 990px) and (max-width: 1199px) {
    .buy-buttons--inline .buy-buttons__step {
      inline-size: 2rem;
    }

    .buy-buttons.buy-buttons--inline .buy-buttons__quantity-input {
      inline-size: 2.25rem;
    }

    .buy-buttons--inline .buy-buttons__submit,
    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded {
      padding-inline: var(--space-sm);
      letter-spacing: 0.06em;
    }
  }

  /*
    The first laptop widths (990–1079px, the narrowest info card): no icons in the two buttons, so the row
    still fits (phones now give Buy now its own row, so they keep the icons)
  */
  /* Small phones (under 390px): Add to cart without its icon and with less padding, so it still fits
     beside the quantity (at 320px it went to a row of its own) */
  @media (max-width: 389px) {
    .buy-buttons--inline .buy-buttons__submit-icon {
      display: none;
    }

    .buy-buttons--inline .buy-buttons__submit {
      padding-inline: var(--space-sm);
    }
  }

  @media (min-width: 990px) and (max-width: 1079px) {
    .buy-buttons--inline .buy-buttons__submit-icon,
    .buy-buttons--inline .buy-buttons__payment .shopify-payment-button__button--unbranded::before {
      display: none;
    }
  }

/* blocks/countdown.liquid */

  countdown-timer {
    display: block;
  }

  /* hidden (set by the script at the end) must win over the display values in this file */
  countdown-timer[hidden],
  .countdown .countdown__row[hidden],
  .countdown .countdown__pause[hidden] {
    display: none;
  }

  /*
    Sizes from the Figma: phones (375px) tiles ~52 x 36px, numbers ~22px, labels ~10px; desktop
    (1920px) tiles ~110 x 78px, numbers ~46px, labels ~18px. Fluid between the two.
    The colours follow the section's scheme (currentColor), so the tiles also work on a light scheme.
  */
  .countdown {
    --countdown-tile: clamp(3.25rem, 2.37rem + 3.75vw, 6.875rem);
    --countdown-number: clamp(1.375rem, 1.01rem + 1.55vw, 2.875rem);
    --countdown-label: clamp(0.6875rem, 0.55rem + 0.45vw, 1.125rem);
    --countdown-gap: clamp(0.375rem, 0.15rem + 0.9vw, 1.25rem);
  }

  /* Alignment: "Alignment" from 1200px, "Alignment on phones and tablets" below 1200px */
  /* The row: the tiles, then the pause button */
  .countdown__row {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: var(--countdown-justify, flex-start);
    gap: var(--countdown-gap);
  }

  .countdown__units {
    display: flex;
    align-items: flex-start;
    gap: var(--countdown-gap);
  }

  /*
    Pause button: a round glass button like the tiles, centred on the tile height (tile width x 0.7),
    at least 2.25rem (a big enough tap target).
  */
  .countdown .countdown__pause {
    --countdown-pause: max(2.25rem, calc(var(--countdown-tile) * 0.45));
    display: grid;
    place-items: center;
    flex: none;
    inline-size: var(--countdown-pause);
    block-size: var(--countdown-pause);
    margin: calc((var(--countdown-tile) * 0.7 - var(--countdown-pause)) / 2) 0 0;
    padding: 0;
    border: 1px solid color-mix(in srgb, currentcolor 25%, transparent);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-background) 45%, transparent);
    color: inherit;
    cursor: pointer;
  }

  .countdown__pause svg {
    inline-size: 40%;
    block-size: auto;
  }

  .countdown__pause-icon--play,
  .countdown__pause[aria-pressed='true'] .countdown__pause-icon--pause {
    display: none;
  }

  .countdown__pause[aria-pressed='true'] .countdown__pause-icon--play {
    display: block;
  }

  .countdown__message,
  .countdown__editor-note {
    text-align: var(--countdown-text-align, start);
  }

  @media (min-width: 1200px) {
    .countdown--center { --countdown-justify: center; --countdown-text-align: center; }
    .countdown--end { --countdown-justify: flex-end; --countdown-text-align: end; }
  }

  @media (max-width: 1199px) {
    .countdown--mobile-center { --countdown-justify: center; --countdown-text-align: center; }
    .countdown--mobile-end { --countdown-justify: flex-end; --countdown-text-align: end; }
  }

  .countdown__unit {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: clamp(0.5rem, 0.35rem + 0.5vw, 1rem);
  }

  /*
    Glass tile (Figma): a dark see-through fill (the scheme's background, so a light scheme gets light
    tiles), a thin light edge and a blur of the photo behind it.
    tabular-nums: every digit is the same width, so the tiles don't twitch while the numbers change.
  */
  .countdown__value {
    display: grid;
    place-items: center;
    min-inline-size: var(--countdown-tile);
    aspect-ratio: 10 / 7;
    padding-inline: 0.25em;
    border: 1px solid color-mix(in srgb, currentcolor 25%, transparent);
    border-radius: clamp(0.375rem, 0.25rem + 0.4vw, 0.625rem);
    background-color: color-mix(in srgb, var(--color-background) 45%, transparent);
    box-shadow: inset 0 1px 0 color-mix(in srgb, currentcolor 18%, transparent);
    -webkit-backdrop-filter: blur(0.5rem);
    backdrop-filter: blur(0.5rem);
    font-family: var(--font-body--family);
    font-size: var(--countdown-number);
    font-variant-numeric: tabular-nums;
    font-weight: 500;
    line-height: 1;
  }

  .countdown__label {
    font-size: var(--countdown-label);
    font-weight: 500;
    line-height: 1.2;
  }

  /* The colon sits on the middle of the tile (half the tile height), not of tile + label */
  .countdown__colon {
    display: grid;
    place-items: center;
    block-size: calc(var(--countdown-tile) * 0.7);
    font-size: calc(var(--countdown-number) * 0.7);
    font-weight: 600;
    line-height: 1;
  }

  .countdown__message {
    margin: 0;
    font-size: var(--font-size-body-lg);
  }

  /* Editor only: the time is over and the store hides the countdown */
  .countdown--preview-hidden .countdown__units {
    opacity: 0.35;
  }

  .countdown__editor-note {
    margin: var(--space-xs) 0 0;
    font-size: var(--font-size-small);
    opacity: 0.8;
  }

/* blocks/custom-liquid.liquid */

  /* Pasted embeds (iframes, videos) never push past the column */
  .custom-liquid {
    inline-size: 100%;
    max-inline-size: 100%;
  }

  .custom-liquid :is(iframe, video, img) {
    max-inline-size: 100%;
  }

/* blocks/group.liquid */

  /*
    No overflow: hidden here (Skeleton had it): it would cut off the focus ring of buttons and links
    inside the group, which keyboard users rely on.
  */
  .group {
    display: flex;
    gap: var(--group-gap);
    inline-size: 100%;
    padding: var(--group-padding);
  }

  /* Column: Alignment moves items across (left / centre / right) */
  .group--vertical {
    flex-direction: column;
    align-items: var(--group-align);
  }

  /* Row: Alignment moves the row along (or spreads it), Vertical alignment lines items up */
  .group--horizontal {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: var(--group-align);
    align-items: var(--group-valign);
  }

/* blocks/heading.liquid */

  /*
    The heading look comes from these classes, not from the tag: critical.css sizes h1-h4 by tag, and a
    class (0,1,0) beats a tag (0,0,1), so <h2 class="heading--display"> is display-sized.
    A <p> tag gets the heading font from .heading as well.
  */
  .heading {
    margin: 0;
    font-family: var(--font-heading--family);
    font-weight: var(--font-heading--weight);
    font-style: var(--font-heading--style);
    line-height: var(--line-height-heading);
    text-align: var(--heading-align, start);
    text-wrap: balance; /* even line lengths for multi-line headings */
  }

  /* Indent in em (scales with the heading's own size), e.g. the hero's "It is time to" starting further in */
  .heading {
    margin-inline-start: calc(var(--heading-indent, 0) * 1em);
  }

  .heading--align-left {
    --heading-align: start;
  }

  .heading--align-center {
    --heading-align: center;
  }

  .heading--align-right {
    --heading-align: end;
  }

  /* Sizes = the theme's type tokens (exact Figma size at 1920, fluid down to phones) */
  .heading--display-xl {
    font-size: var(--font-size-display-xl);
    line-height: 1.05;
  }

  .heading--display {
    font-size: var(--font-size-display);
    line-height: 1.05;
  }

  .heading--h1 {
    font-size: var(--font-size-h1);
  }

  .heading--h2 {
    font-size: var(--font-size-h2);
  }

  .heading--h3 {
    font-size: var(--font-size-h3);
  }

  .heading--h4 {
    font-size: var(--font-size-body-lg);
  }

  /* Custom px size (snippets/fluid-font-size.liquid): after the size rules, so it wins */
  .heading--custom-size {
    font-size: clamp(
      var(--fs-min),
      calc(var(--fs-min) + (100vw - 390px) * var(--fs-diff) / 1530),
      var(--fs-max)
    );
  }

  /* Colour */
  .heading--accent {
    color: var(--color-accent);
  }

  /* Faded: the Figma's big background letters (e.g. "PAR"). Decorative only: too faint to read as text */
  .heading--faded {
    color: var(--color-tint);
  }

  /* Font: the accent font for decorative lines (Figma hero: "It is time to", "Unveil Your") */
  .heading--accent-font {
    font-family: var(--font-accent--family);
    font-style: var(--font-accent--style);
    font-weight: var(--font-accent--weight);
  }

  /* Body font: a sans-serif heading in medium weight (Figma hero: "Premium Skincare, Fragrance & Makeup") */
  .heading--body-font {
    font-family: var(--font-body--family);
    font-style: normal;
    font-weight: var(--font-weight-medium);
  }

  /* Italic words (made italic in the editor): accent colour, the red brush, or just italic */
  .heading--italic-accent em {
    color: var(--color-accent);
  }

  /*
    Brush (Figma: "glow" in white script on a red brush stroke). The word gets the accent font in the
    button text colour; ::before is the brush, a box painted in the accent colour and cut to the
    shape of brush-glow.svg with a CSS mask, behind the text (z-index -1 inside the word's own
    stacking context, made by isolation: isolate).
  */
  .heading--italic-brush em {
    position: relative;
    isolation: isolate;
    display: inline-block;
    padding: 0.05em 0.4em 0.15em;
    color: var(--color-button-text);
    font-family: var(--font-accent--family);
    font-style: var(--font-accent--style);
    font-weight: var(--font-accent--weight);
  }

  .heading--italic-brush em::before {
    content: '';
    position: absolute;
    inset: -0.1em -0.15em;
    z-index: -1;
    background-color: var(--color-accent);
    mask: var(--brush-glow) center / 100% 100% no-repeat;
  }

/* blocks/image.liquid */

  /* Width: a share of the space the block sits in; Alignment places a narrower image */
  .image-block {
    inline-size: var(--image-block-width, 100%);
    overflow: hidden; /* rounds the image's corners along with the box */
    border-radius: var(--image-block-radius, 0);
  }

  .image-block--align-center {
    margin-inline: auto;
  }

  .image-block--align-right {
    margin-inline-start: auto;
  }

  /* Shapes: the box gets the ratio, the image fills it (image--cover) */
  .image-block--square {
    aspect-ratio: 1;
  }

  .image-block--portrait {
    aspect-ratio: 4 / 5;
  }

  .image-block--landscape {
    aspect-ratio: 4 / 3;
  }

  .image-block--wide {
    aspect-ratio: 16 / 9;
  }

  /* Corner radius = the Figma's radius tokens */
  .image-block--radius-sm {
    --image-block-radius: var(--radius-sm);
  }

  .image-block--radius-md {
    --image-block-radius: var(--radius-md);
  }

  .image-block--radius-lg {
    --image-block-radius: var(--radius-lg);
  }

  /* A linked image: a gentle zoom on hover, and the focus ring drawn inside the rounded box */
  .image-block a.image {
    outline-offset: -3px;
  }

  .image-block a.image img {
    transition: transform var(--duration-slow) var(--ease-out);
  }

  .image-block a.image:hover img {
    transform: scale(1.03);
  }

  @media (prefers-reduced-motion: reduce) {
    .image-block a.image img {
      transition: none;
    }
  }

/* blocks/product-description.liquid */

  .product-description {
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
    font-size: var(--font-size-body-lg);
  }

  .product-description--small {
    font-size: var(--font-size-body-sm);
  }

  .product-description--body {
    font-size: var(--font-size-body);
  }

  /* Read more: the full text replaces the short one; the button goes away */
  .product-description:has(.product-description__more[open]) .product-description__short,
  .product-description__more[open] > .product-description__toggle {
    display: none;
  }

  .product-description__toggle {
    display: inline-block;
    margin-block-start: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 0.25em;
    text-transform: uppercase;
    cursor: pointer;
    list-style: none;
  }

  .product-description__toggle::-webkit-details-marker {
    display: none;
  }

/* blocks/product-eyebrow.liquid */

  /*
    Figma: "Skincare" heading font ~34px accent; a white "Trending" pill beside it; "SHARE" accent caps
    ~15px with a filled share arrow (assets/icon-share-solid.svg, the text colour) and an underline, at the right.
  */
  .product-eyebrow {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm) var(--space-md);
  }

  .product-eyebrow__start {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-sm) var(--space-md);
  }

  .product-eyebrow__label {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: max(1.5rem, calc(34 * var(--px, 0.0625rem)));
    line-height: 1.1;
  }

  /*
    The badge (snippets/product-badge.liquid gives a .product-card__badge). The product card's paint
    rules need a .product-card parent, so the pill is painted here too. Two classes beat the scheme
    class (color-scheme-N), so the text is the scheme's accent, as on the cards.
  */
  .product-eyebrow__badge .product-card__badge {
    display: inline-block;
    position: static;
    padding: 0.3em 0.75em;
    border-radius: 0.75em;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    line-height: 1.3;
  }

  /* A Badge entry with its own colours (Content > Metaobjects > Badges): a thin edge in its text colour */
  .product-eyebrow__badge .product-card__badge--own-colors {
    background-color: var(--badge-bg);
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--badge-fg) 25%, transparent);
    color: var(--badge-fg);
  }

  .product-eyebrow__share {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    min-block-size: 2.75rem;
    padding: 0;
    border: 0;
    background: none;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: underline;
    text-decoration-thickness: 1.5px;
    text-underline-offset: 0.5em;
    text-transform: uppercase;
    cursor: pointer;
  }

  .product-eyebrow__share-icon {
    display: inline-flex;
  }

  .product-eyebrow__share-icon svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

/* blocks/product-features.liquid */

  /* Figma: 4 badges spread across the card (~160px apart), icon above, label under */
  .product-features__list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(7rem, 1fr));
    gap: var(--space-md);
  }

  /* Editor only: the note when no feature has a label */
  .product-features__empty {
    margin: 0 0 var(--space-sm);
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
  }

/* blocks/product-offers.liquid */

  /*
    Figma: 4 tickets ~186px wide, overlapping a few px and slightly tilted, each its own angle. The
    tickets are the list's direct children (the blocks have no wrapper: "tag": null) and an empty
    offer outputs nothing, so :nth-child counts only the tickets that show.
  */
  /* The container is the block, not the list: a container query only styles the container's children */
  .product-offers {
    container-type: inline-size;
  }

  .product-offers__list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-sm);
  }

  @container (min-width: 40rem) {
    .product-offers__list {
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: var(--space-sm) 0;
    }

    /* Each ticket overlaps the one at its left; the first of each row of 4 has none at its left */
    .product-offers__list > :not(:nth-child(4n + 1)) {
      margin-inline-start: -0.25rem;
    }
  }

  .product-offers__list > :nth-child(4n + 1) {
    --offer-tilt: -1deg;
  }

  .product-offers__list > :nth-child(4n + 2) {
    --offer-tilt: 0.6deg;
  }

  .product-offers__list > :nth-child(4n + 3) {
    --offer-tilt: -0.4deg;
  }

  .product-offers__list > :nth-child(4n + 4) {
    --offer-tilt: 0.8deg;
  }

  .product-offers__empty {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
  }

/* blocks/product-panel.liquid */

  /* Figma: cream (the card colour on white), 1px pale border, radius ~24, padding ~55 */
  .product-panel {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-md), calc(var(--panel-gap) * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  .product-panel--card {
    padding: max(var(--space-lg), calc(55 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: var(--color-card);
  }

  @media (max-width: 749px) {
    .product-panel--card {
      padding: var(--space-lg) var(--space-md);
    }
  }

/* blocks/product-payment.liquid */

  /* Figma: grey line ~16px; icons ~38 x 24 in a row, ~6px apart */
  .product-payment__text {
    margin: 0 0 var(--space-md);
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-body-sm);
  }

  .product-payment__list {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .product-payment__icon {
    display: block;
    inline-size: 2.4rem;
    block-size: auto;
  }

/* blocks/product-pickup.liquid */

  .product-pickup__list {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* The line itself (icon, ready time, the link) is styled in snippets/pickup-line.liquid */

  /*
    The side panel (user's choice A, 2026-11-25): slides in from the end side like the phone menu drawer,
    full height, rounded on its inner side. Colours from the product section's scheme (inherited).
  */
  .product-pickup__drawer {
    inset-block: 0;
    inset-inline: auto 0;
    inline-size: min(26rem, 90vw);
    max-inline-size: none;
    block-size: 100dvh;
    max-block-size: none;
    margin: 0;
    padding: 0;
    border: 0;
    border-start-start-radius: 25px;
    border-end-start-radius: 25px;
    background-color: var(--color-background);
    box-shadow: 0 4px 15px #b9b9b940;
    color: var(--color-text);
  }

  .product-pickup__drawer::backdrop {
    background-color: #00000040;
  }

  html:has(.product-pickup__drawer[open]) {
    overflow: hidden;
  }

  .animations-on .product-pickup__drawer {
    transition:
      translate var(--duration-base) var(--ease-out),
      display var(--duration-base) allow-discrete,
      overlay var(--duration-base) allow-discrete;
    translate: 100% 0;
  }

  .animations-on .product-pickup__drawer:dir(rtl) {
    translate: -100% 0;
  }

  .animations-on .product-pickup__drawer[open] {
    translate: 0 0;
  }

  @starting-style {
    .animations-on .product-pickup__drawer[open] {
      translate: 100% 0;
    }

    .animations-on .product-pickup__drawer[open]:dir(rtl) {
      translate: -100% 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .animations-on .product-pickup__drawer {
      transition: none;
    }
  }

  /* Head (title + close), then the list, which scrolls when there are many stores */
  .product-pickup__drawer-panel {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    block-size: 100%;
    padding: var(--space-lg);
  }

  .product-pickup__drawer-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  .product-pickup__drawer-title {
    margin: 0;
    font-size: var(--font-size-h3);
  }

  .product-pickup__close {
    display: inline-grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: 2.375rem;
    block-size: 2.375rem;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
    color: inherit;
    cursor: pointer;
  }

  .product-pickup__close:is(:hover, :focus-visible) {
    color: var(--color-accent);
  }

  .product-pickup__close svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  .product-pickup__body {
    flex: 1;
    min-block-size: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
  }

  /* Nothing to show (no delivery note, no pickup line for the chosen variant): no heading either */
  .product-pickup:not(:has(.product-pickup__line:not([hidden]))) {
    display: none;
  }

/* blocks/product-price.liquid */

  .product-price {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
  }

  /* Large (Figma PDP): a big, dark price in the body font; the old price and pill sit beside it */
  .product-price--large .price {
    gap: 0 var(--space-sm);
  }

  .product-price--large .price__current {
    color: var(--color-text);
    font-size: var(--font-size-h1);
    font-weight: 600;
    line-height: 1.1;
  }

  .product-price--large .price__compare {
    font-size: var(--font-size-h3);
  }

  /* The price at the left, the rating at the right (Figma PDP) */
  .product-price__row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-xs) var(--space-lg);
  }

  .product-price__rating {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
    font-size: var(--font-size-caption);
  }

  /* Five stars filled up to the rating (e.g. 4.9 of 5 = 98%), the rest pale */
  .product-price__stars {
    background: linear-gradient(
      90deg,
      var(--color-rating) var(--rating-percent, 100%),
      color-mix(in srgb, var(--color-text) 15%, transparent) var(--rating-percent, 100%)
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 1.15em;
    letter-spacing: 0.1em;
  }

  .product-price__reviews {
    color: var(--color-accent);
    font-size: var(--font-size-small);
  }

  /* "Shipping calculated at checkout": small uppercase label, softer colour */
  .product-price__note {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-price__note a {
    color: inherit;
  }

  /* The chosen options match no variant ("Unavailable"): the last price stays, faded */
  .product-price.is-unavailable [data-price-current] {
    opacity: 0.4;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-price [data-price-current] {
      transition: opacity var(--duration-fast) var(--ease-out);
    }
  }

/* blocks/product-stock.liquid */

  /* Figma: accent caps ~15px with a dot; a 1px line ~45px; grey caps count */
  .product-stock__line {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    margin: 0;
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-stock__line[hidden],
  .product-stock__line--none {
    display: none;
  }

  .product-stock__label {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    color: var(--stock-color, var(--color-accent));
    font-weight: var(--font-weight-medium);
  }

  .product-stock__line--low .product-stock__label {
    color: var(--stock-low-color, var(--stock-color, var(--color-accent)));
  }

  .product-stock__label::before {
    content: "";
    inline-size: 0.375rem;
    block-size: 0.375rem;
    border-radius: 50%;
    background-color: currentcolor;
  }

  .product-stock__line--out .product-stock__label {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background)); /* 60% = 4.35:1 on white */
  }

  .product-stock__rule {
    inline-size: 2.75rem;
    block-size: 1px;
    background-color: color-mix(in srgb, var(--color-text) 25%, transparent);
  }

  .product-stock__count {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

/* blocks/product-title.liquid */

  .product-title {
    margin: 0;
  }

  /*
    "Product page" size (Figma PDP: the title ~46px at 1920): between Heading 1 (60px) and Heading 2
    (40px); 32px on phones, growing with the screen like the other heading sizes
  */
  .product-title--product {
    font-size: clamp(2rem, 1.733rem + 1.098vw, 2.875rem);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-title__link {
    color: inherit;
    text-decoration: none;
  }

  .product-title__link:hover {
    text-decoration: underline;
    text-decoration-thickness: 1px;
  }

/* blocks/product-videos.liquid */

  /* Figma: 4 circles ~96px, ~26px apart, a small white play disc in the middle */
  .product-videos__list {
    display: flex;
    flex-wrap: wrap;
    gap: max(var(--space-md), calc(26 * var(--px, 0.0625rem)));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .product-videos__thumb {
    position: relative;
    display: grid;
    place-items: center;
    overflow: hidden;
    inline-size: max(4.5rem, calc(96 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    min-block-size: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 6%, var(--color-background)));
    box-shadow: none;
    cursor: pointer;
  }

  .product-videos__thumb:hover {
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 6%, var(--color-background)));
  }

  .product-videos__thumb:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .product-videos__image {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    transition: scale var(--duration-normal) var(--ease-out);
  }

  .product-videos__thumb:hover .product-videos__image {
    scale: 1.06;
  }

  /* The white play disc: 40px (bigger than Figma's ~24px, our choice, so it reads as a video) */
  .product-videos__play {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: 2.5rem;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: #ffffff;
    color: var(--color-text);
  }

  .product-videos__play svg {
    inline-size: 1.25rem;
    block-size: 1.25rem;
    margin-inline-start: 0.15rem; /* a triangle looks centred a touch right of the middle */
  }

  /* The player: the video as large as fits, on a dark see-through backdrop */
  /*
    margin: auto centres the dialog on the screen: that's how the browser centres a modal <dialog>, and the
    theme's reset (margin: 0 on everything) had taken it away, leaving the player in the top-left corner
  */
  .product-videos__dialog {
    margin: auto;
    max-inline-size: min(90vw, 60rem);
    max-block-size: 90svh;
    padding: 0;
    border: 0;
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background: #000000;
    overflow: hidden;
  }

  .product-videos__dialog::backdrop {
    background-color: #000000b3;
  }

  html:has(.product-videos__dialog[open]) {
    overflow: hidden;
  }

  /*
    The player takes the video's shape (--video-ratio, set from the thumbnail) before the video has loaded,
    as large as fits: 90% of the screen width, 90% of its height, at most 960px wide
  */
  .product-videos__player {
    inline-size: min(90vw, 60rem, calc(90svh * var(--video-ratio, 1.7778)));
    aspect-ratio: var(--video-ratio, 1.7778);
  }

  .product-videos__video,
  .product-videos__frame {
    display: block;
    border: 0;
    inline-size: 100%;
    block-size: 100%;
    object-fit: contain;
  }

  .product-videos__close {
    position: absolute;
    z-index: 1;
    inset-block-start: var(--space-sm);
    inset-inline-end: var(--space-sm);
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    min-block-size: 0;
    aspect-ratio: 1;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-background) 80%, transparent);
    box-shadow: none;
    color: var(--color-text);
  }

  .product-videos__close:hover {
    background-color: var(--color-background);
  }

  .product-videos__close svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  /* Editor placeholders: grey drawings in the circles, not clickable */
  .product-videos--placeholder .product-videos__thumb {
    cursor: default;
  }

  .product-videos__placeholder {
    fill: color-mix(in srgb, var(--color-text) 35%, transparent);
  }

  .product-videos__empty {
    margin: var(--space-sm) 0 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-small);
  }

  @media (prefers-reduced-motion: reduce) {
    .product-videos__image {
      transition: none;
    }
  }

/* blocks/text.liquid */

  .text {
    max-inline-size: var(--text-max-width, none);
    text-align: var(--text-align, start);
  }

  /*
    Alignment also moves the box itself: a narrow centred paragraph should sit in the middle of its
    container, not only have its lines centred inside a box stuck on the left.
  */
  .text--align-left {
    --text-align: start;
  }

  .text--align-center {
    --text-align: center;
    margin-inline: auto;
  }

  .text--align-right {
    --text-align: end;
    margin-inline-start: auto;
  }

  /* Rich text wraps its content in <p>: no extra space above the first or below the last paragraph */
  .text > :first-child {
    margin-block-start: 0;
  }

  .text > :last-child {
    margin-block-end: 0;
  }

  /* Type styles = the M1 tokens (Figma sizes at 1920, fluid down to phones) */
  .text--body-lg {
    font-size: var(--font-size-body-lg);
  }

  .text--body {
    font-size: var(--font-size-body);
  }

  .text--small {
    font-size: var(--font-size-body-sm);
  }

  .text--caption {
    font-size: var(--font-size-caption);
  }

  /* Eyebrow: the Figma's small uppercase label in the accent colour (same look as .eyebrow in critical.css) */
  .text--eyebrow {
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-heading);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* The Figma eyebrow has a short gold rule in front of the label (like .eyebrow in critical.css) */
  .text--eyebrow {
    display: flex;
    align-items: center;
    gap: var(--space-md);
  }

  .text--eyebrow::before {
    content: "";
    flex: none;
    inline-size: 66px;
    block-size: 2px;
    background-color: currentcolor;
  }

  .text--eyebrow > * {
    margin: 0;
  }

  /* A flex row ignores text-align, so the alignment setting moves the rule + label as a whole */
  .text--eyebrow.text--align-center {
    justify-content: center;
  }

  .text--eyebrow.text--align-right {
    justify-content: flex-end;
  }

  /*
    Custom size: replaces the style's size (this rule comes after the style rules, so it wins).
    The same fluid formula as the tokens: the phone size at 390px wide, growing in a straight line
    to the typed size at 1920px wide (1530px further), never below or above those two.
    --fs-diff is the difference without "px", because CSS can multiply a length by a plain number
    but not a length by a length.
  */
  .text--custom-size {
    font-size: clamp(
      var(--fs-min),
      calc(var(--fs-min) + (100vw - 390px) * var(--fs-diff) / 1530),
      var(--fs-max)
    );
  }

  /* Font: the Figma sets some paragraphs in the serif heading font (e.g. card and newsletter text) */
  .text--heading-font {
    font-family: var(--font-heading--family);
  }

  /*
    Colour. "Muted" mixes the scheme's text into its background (the softer grey of the Figma's footer
    and card text) and stays at about 6:1 contrast on the light schemes.
  */
  .text--muted {
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

  .text--accent {
    color: var(--color-accent);
  }

  /* "Hide on phones": e.g. a long paragraph the mobile design leaves out (it stays on tablets and desktop) */
  @media (max-width: 749px) {
    .text--hide-phones {
      display: none;
    }
  }

/* sections/404.liquid */

  /*
    No Figma frame: built from the M5 pages (collection banner / search hero): centred, the eyebrow
    with rules, a heading-font h1 with an accent word, a pill search field (the search page's),
    .button + .button--secondary, pills like the category pills. The "404" is decorative (the
    FAQ numbers' style: heading font, accent 15%).
  */
  .not-found {
    /* One Figma pixel: the screen width only, never more than 1px (Scale with the screen off) */
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /* Scale with the screen on: the width and the height, as in the screen-scale snippet */
  .not-found.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .not-found__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    text-align: center;
  }

  .not-found__code {
    margin: 0;
    color: color-mix(in srgb, var(--color-accent) 15%, transparent);
    font-family: var(--font-heading--family);
    font-size: clamp(7rem, 4rem + 14vw, 17rem);
    font-weight: var(--font-heading--weight);
    line-height: 0.85;
    letter-spacing: -0.02em;
  }

  .not-found__code::before {
    content: attr(data-code);
  }

  .not-found__eyebrow {
    margin-block-start: var(--space-lg);
  }

  .not-found__heading {
    max-inline-size: 18em;
    margin: var(--space-lg) auto 0;
    /* --text-boost = the Text size setting (only with Scale with the screen) */
    font-size: calc(max(2rem, calc(64 * var(--px))) * var(--text-boost, 1));
    font-weight: 400;
    line-height: 1.1;
  }

  .not-found__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .not-found__text {
    max-inline-size: 36rem;
    margin: var(--space-lg) auto 0;
    font-size: var(--font-size-body);
    line-height: 1.7;
  }

  .not-found__text > * {
    margin: 0;
  }

  /* The search field: one pill with the button inside (as on the search page) */
  /* A fixed-height pill; the round button sits in its middle (6px all round), without a shadow */
  .not-found__search {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    block-size: 3.5rem;
    box-sizing: border-box;
    max-inline-size: 36rem;
    margin: var(--space-xl) auto 0;
    padding: 0.375rem 0.375rem 0.375rem var(--space-lg);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-card);
    box-shadow: var(--shadow-card);
  }

  .not-found__search:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .not-found .not-found__search-input {
    flex: 1;
    align-self: stretch;
    min-inline-size: 0;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-body);
  }

  .not-found .not-found__search-input:focus-visible {
    outline: none;
  }

  .not-found__search-input::-webkit-search-cancel-button {
    -webkit-appearance: none;
  }

  .not-found .not-found__search-submit {
    display: inline-grid;
    flex: none;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background-color: var(--color-button);
    box-shadow: none;
    color: var(--color-button-text);
  }

  .not-found__search-submit svg {
    inline-size: 1.1rem;
    block-size: 1.1rem;
  }

  .not-found__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-sm) var(--space-md);
    margin-block-start: var(--space-xl);
  }

  .not-found__links {
    margin-block-start: var(--space-2xl);
  }

  .not-found__links-heading {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-small);
    font-weight: 400;
    line-height: 1.5;
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .not-found__links-list {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-xs) var(--space-sm);
    margin: var(--space-md) 0 0;
    padding: 0;
    list-style: none;
  }

  .not-found__link {
    display: inline-flex;
    align-items: center;
    min-block-size: 2.75rem;
    padding: 0 var(--space-md);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-caption);
    text-decoration: none;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  @media (hover: hover) {
    .not-found__link:hover {
      border-color: color-mix(in srgb, var(--color-accent) 35%, transparent);
      color: var(--color-accent);
    }
  }

  /* Phones: full-width buttons, easy to tap */
  @media (max-width: 749px) {
    .not-found__actions > .button {
      flex: 1 1 100%;
    }
  }

/* sections/about-chapters.liquid */

  /*
    Figma 1920: full bleed, each chapter one screen; dark overlay over the photo (~45%); content
    x 308; side nav x 55, items 43px apart (y 450–580): a 30px rule + "02" in the text colour,
    the active one a 66px rule + number in the accent. Sizes: Figma px x --px with rem floors.
  */
  .about-chapters {
    /* One Figma pixel; with "Scale with the screen" off it follows the width only, never more than 1px */
    --px: min(calc(100vw / 1920), 0.0625rem);
    /* Empty Label color = the theme's accent (the setting writes its own value inline) */
    --chapter-accent: var(--color-accent);
    --chapter-indent: max(4.75rem, calc(308 * var(--px)));

    display: grid;
    background-color: #1f1f1f; /* behind the photos while they load */
  }

  .about-chapters.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  /* The layers share one cell; the sticky ones stay one screen tall at the top */
  .about-chapters > * {
    grid-area: 1 / 1;
  }

  .about-chapters__media,
  .about-chapters__nav,
  .about-chapters__controls {
    position: sticky;
    inset-block-start: 0;
    align-self: start;
    block-size: 100svh;
  }

  .about-chapters__media {
    overflow: hidden;
  }

  /*
    The chapters' photos once the script moved them here (.chapter__media, styled in the block:
    absolute, filling the box, with the overlay): stacked, only the active one visible
  */
  .about-chapters__media .chapter__media {
    z-index: auto;
    opacity: 0;
  }

  .about-chapters__media .chapter__media.is-active {
    opacity: 1;
  }

  .about-chapters__list {
    position: relative;
    z-index: 1;
  }

  /* The nav sits on the left, over the chapters; only its links take clicks */
  .about-chapters__nav {
    z-index: 2;
    display: flex;
    align-items: center;
    justify-self: start;
    padding-inline-start: max(1rem, calc(55 * var(--px)));
    pointer-events: none;
  }

  /* display: flex above would beat the hidden attribute (no JS, or a single chapter) */
  .about-chapters__nav[hidden] {
    display: none;
  }

  .about-chapters__nav-list {
    display: grid;
    gap: max(0.75rem, calc(22 * var(--px)));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .about-chapters__link {
    display: flex;
    align-items: center;
    gap: max(0.75rem, calc(17 * var(--px)));
    color: var(--chapter-text);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    pointer-events: auto;
  }

  .about-chapters__rule {
    inline-size: max(1.25rem, calc(30 * var(--px)));
    block-size: 1px;
    background-color: currentcolor;
  }

  .about-chapters__link[aria-current] {
    color: var(--chapter-accent);
  }

  .about-chapters__link[aria-current] .about-chapters__rule {
    inline-size: max(2.5rem, calc(66 * var(--px)));
    block-size: 2px;
  }

  /*
    Pause / play for the videos: the About hero's round button, at the bottom right of the screen.
    The layer lets clicks through; only the button takes them.
  */
  .about-chapters__controls {
    z-index: 2;
    display: flex;
    align-items: flex-end;
    justify-self: end;
    padding: var(--space-lg) var(--page-margin);
    pointer-events: none;
  }

  .about-chapters__pause {
    display: grid;
    place-items: center;
    inline-size: 2.25rem;
    block-size: 2.25rem;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
    cursor: pointer;
    pointer-events: auto;
  }

  .about-chapters__pause[hidden] {
    display: none;
  }

  .about-chapters__pause-icon--play,
  .about-chapters__pause[aria-pressed='true'] .about-chapters__pause-icon--pause {
    display: none;
  }

  .about-chapters__pause[aria-pressed='true'] .about-chapters__pause-icon--play {
    display: block;
  }

  /* Theme editor only: no chapter with content */
  .about-chapters__editor {
    padding: var(--space-2xl) var(--page-margin);
    color: #ffffff;
    text-align: center;
  }

  .about-chapters__empty {
    margin: 0;
  }

  /* The photo cross-fade and the nav rule's growth, only with motion allowed */
  @media (prefers-reduced-motion: no-preference) {
    .about-chapters__media .chapter__media {
      transition: opacity 900ms var(--ease-out);
    }

    .about-chapters__rule {
      transition: inline-size var(--duration-fast) var(--ease-out);
    }
  }

  /*
    Phones (Variant45-1 to Variant48, 375px): the words start ~80px in, the nav closer to the edge
    with ~8px numbers and shorter rules, so it never touches the words
  */
  @media (max-width: 749px) {
    .about-chapters {
      --chapter-indent: 5rem;
    }

    .about-chapters__nav {
      padding-inline-start: 1.125rem;
    }

    .about-chapters__nav-list {
      gap: var(--space-sm);
    }

    .about-chapters__link {
      gap: var(--space-xs);
      font-size: 0.5rem;
      letter-spacing: 0.1em;
    }

    .about-chapters__rule {
      inline-size: 0.875rem;
    }

    .about-chapters__link[aria-current] .about-chapters__rule {
      inline-size: 1.75rem;
    }
  }

/* sections/about-hero.liquid */

  /*
    Figma 1920 (export "Property 1=Default", 1:1): breadcrumb y 150; left column x 48–810, card
    x 872–1868 (996 wide, y 190–970, radius ~30, soft shadow). "Our story" ~64px italic at x 150;
    "Made Slowly," ~125px (cap ~85px); "worn daily" ~125px indented ~57px, brush under "daily";
    intro ~24px / 38px; button 250 x 58; text link label + 1px underline.
    Sizes are Figma px x --px (screen-scale) with rem floors, or tokens.
  */
  /*
    --px = one Figma pixel. With "Scale with the screen" off it follows the width only, never more
    than 1px (without this value every size fell back to the 1920px size on phones).
  */
  .about-hero {
    --px: min(calc(100vw / 1920), 0.0625rem);

    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .about-hero.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .about-hero__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .about-hero__breadcrumb {
    margin-block-end: max(var(--space-lg), calc(32 * var(--px)));
  }

  /* Phones and tablets: the story, then the card. Two columns from 1200px (only with the card) */
  .about-hero__grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr); /* never wider than the screen (the one-row buttons shrink) */
    gap: var(--space-2xl);
    align-items: center;
  }

  @media (min-width: 1200px) {
    .about-hero__grid--split {
      grid-template-columns: minmax(0, 762fr) minmax(0, 996fr);
      column-gap: calc(62 * var(--px));
    }
  }

  /* ---------- Lettering (relative: it holds the pause button) ---------- */
  .about-hero__lettering {
    position: relative;
    margin-block-end: max(var(--space-xl), calc(90 * var(--px)));
  }

  .about-hero__script {
    margin: 0 0 calc(-0.15em) max(var(--space-xl), calc(100 * var(--px)));
    font-family: var(--font-heading--family);
    font-size: max(1.75rem, calc(64 * var(--px)));
    font-style: italic;
    line-height: 1.1;
  }

  .about-hero__heading {
    margin: 0;
    /* 125px at 1920, times the "Heading size" setting (--heading-scale, e.g. 0.8 = 80%) */
    font-size: calc(max(2.75rem, calc(125 * var(--px))) * var(--heading-scale, 1));
    line-height: 1.05;
    letter-spacing: -0.01em;
  }

  .about-hero__line {
    display: block;
  }

  /* Pause / play for the changing line: a small round glass button at the lettering's bottom right */
  .about-hero__pause {
    position: absolute;
    inset-block-end: 0.5rem;
    inset-inline-end: 0;
    display: grid;
    place-items: center;
    inline-size: 2.25rem;
    block-size: 2.25rem;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
    cursor: pointer;
  }

  .about-hero__pause[hidden] {
    display: none;
  }

  .about-hero__pause-icon--play,
  .about-hero__pause[aria-pressed='true'] .about-hero__pause-icon--pause {
    display: none;
  }

  .about-hero__pause[aria-pressed='true'] .about-hero__pause-icon--play {
    display: block;
  }

  .about-hero__line--indent {
    padding-inline-start: max(var(--space-lg), calc(57 * var(--px)));
  }

  /* "Made *Slowly,*": the italic word in the accent colour, kept italic as in the Figma */
  .about-hero__heading em {
    color: var(--color-accent);
  }

  /*
    "worn **daily**": a Bold word gets the brush under it (and stays the heading's weight). <u> is
    still read, for headings typed before the setting had Bold/Italic buttons.
  */
  .about-hero__heading strong,
  .about-hero__heading u {
    position: relative;
    font-weight: inherit;
    text-decoration: none;
  }

  .about-hero__heading strong::after,
  .about-hero__heading u::after {
    content: "";
    position: absolute;
    inset-inline: -8% -2%;
    inset-block-end: -0.12em;
    block-size: 0.18em;
    background-color: var(--color-accent);
    -webkit-mask: var(--brush-underline) center / 100% 100% no-repeat;
    mask: var(--brush-underline) center / 100% 100% no-repeat;
    pointer-events: none;
  }

  /*
    ---------- Line 2 changing on a timer (Figma prototype: "worn daily" → "read openly" →
    "refilled always") ----------
    The versions share one grid cell (the line keeps the width of the longest: no jumps). Before
    the script runs (and without JS) only the first shows. With the script (data-ready): the
    leaving version rises out and fades, the next rises in from below.
  */
  .about-hero__rotator {
    position: relative; /* holds the gliding brush */
    display: inline-grid;
  }

  /* Each version stays on one line (make the heading smaller with "Heading size" if one is too long) */
  .about-hero__phrase,
  .about-hero__brush-holder {
    grid-area: 1 / 1;
    white-space: nowrap;
  }

  /* Only the copy draws the brush: invisible text, visible brush, never moving */
  .about-hero__phrase strong::after,
  .about-hero__phrase u::after {
    content: none;
  }

  .about-hero__brush-holder {
    visibility: hidden;
  }

  .about-hero__brush-holder strong::after,
  .about-hero__brush-holder u::after {
    visibility: visible;
  }

  /*
    With the script (data-ready) the copy's brush steps aside for one brush that the script places
    under the current version's Bold word (--brush-x, --brush-y, --brush-w, in px inside the
    line), so it slides and stretches to the new word while the words change.
  */
  .about-hero__brush {
    display: none;
  }

  .about-hero__rotator[data-ready] .about-hero__brush-holder strong::after,
  .about-hero__rotator[data-ready] .about-hero__brush-holder u::after {
    visibility: hidden;
  }

  .about-hero__rotator[data-ready] .about-hero__brush {
    position: absolute;
    inset-block-start: calc(var(--brush-y, 0px) - 0.06em);
    inset-inline-start: var(--brush-x, 0px);
    display: block;
    inline-size: var(--brush-w, 0px);
    block-size: 0.18em;
    background-color: var(--color-accent);
    -webkit-mask: var(--brush-underline) center / 100% 100% no-repeat;
    mask: var(--brush-underline) center / 100% 100% no-repeat;
    pointer-events: none;
    transition:
      inset-inline-start 800ms var(--ease-out) 150ms,
      inline-size 800ms var(--ease-out) 150ms,
      inset-block-start 800ms var(--ease-out) 150ms,
      opacity 300ms ease;
  }

  .about-hero__rotator[data-ready] .about-hero__brush.is-hidden {
    opacity: 0;
  }

  .about-hero__phrase:not(:first-child) {
    visibility: hidden;
  }

  .about-hero__rotator[data-ready] .about-hero__phrase {
    visibility: visible;
    opacity: 0;
    translate: 0 0.3em;
  }

  .about-hero__rotator[data-ready] .about-hero__phrase.is-leaving {
    translate: 0 -0.25em;
    transition:
      opacity 350ms ease-in,
      translate 450ms ease-in;
  }

  .about-hero__rotator[data-ready] .about-hero__phrase.is-active {
    opacity: 1;
    translate: 0 0;
    transition:
      opacity 700ms var(--ease-out) 200ms,
      translate 900ms var(--ease-out) 200ms;
  }

  /* ---------- Intro and actions ---------- */
  .about-hero__text {
    max-inline-size: 48rem; /* ~760px */
    font-size: var(--font-size-body-lg);
    line-height: 1.6;
  }

  .about-hero__text > * {
    margin: 0;
  }

  .about-hero__text > * + * {
    margin-block-start: var(--space-md);
  }

  .about-hero__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-lg) max(var(--space-xl), calc(85 * var(--px)));
    margin-block-start: max(var(--space-xl), calc(80 * var(--px)));
  }

  /* "BOOK CONSULTATION →": accent label with an underline */
  .about-hero__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    padding-block-end: var(--space-xs);
    border-block-end: 1px solid currentcolor;
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
  }

  .about-hero__link-arrow svg {
    display: block;
    inline-size: 1.1em;
    block-size: auto;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .about-hero__link:hover .about-hero__link-arrow svg {
      translate: 0.25em 0;
    }
  }

  /* ---------- Disciplines card ---------- */
  .about-hero__card {
    padding:
      max(var(--space-xl), calc(53 * var(--px)))
      max(var(--space-lg), calc(93 * var(--px)))
      max(var(--space-xl), calc(50 * var(--px)))
      max(var(--space-lg), calc(82 * var(--px)));
    border-radius: max(var(--radius-md), calc(30 * var(--px)));
    background-color: var(--color-background);
    box-shadow: var(--shadow-card);
  }

  .about-hero__card-label {
    margin: 0 0 max(var(--space-md), calc(40 * var(--px)));
    font-family: var(--font-body--family);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    line-height: var(--line-height-heading);
    text-transform: uppercase;
  }

  .about-hero__disciplines {
    counter-reset: discipline;
  }

  /* Theme editor only: no Discipline row with content */
  .about-hero__note {
    margin: 0;
    font-size: var(--font-size-small);
    font-style: italic;
    opacity: 0.75;
  }

  /*
    Phones (mobile export Variant45, 375px). Fixed rem sizes, not the text tokens: in a scaled
    section the tokens are multiplied by Text size, and the design wants small text here.
    - "Our story" ~70px in, above "Slowly"; line 2 indented ~50px. The heading is ~44px at 375px
      with the saved Heading size 85% (52px x 0.85); the vw cap and the smaller indent keep the
      longest line 2 ("refilled always", nowrap) inside a 320px screen at Heading size 100%.
    - The pause button goes to the top right, beside "Our story", away from the long line 2.
    - Both buttons on one row with 11px labels; the button keeps a 44px tap height.
  */
  @media (max-width: 749px) {
    .about-hero__script {
      margin-inline-start: min(4.375rem, 18vw);
      font-size: 1.75rem;
    }

    .about-hero__heading {
      font-size: calc(min(3.25rem, 13.5vw) * var(--heading-scale, 1));
    }

    .about-hero__line--indent {
      padding-inline-start: min(3.125rem, 10vw);
    }

    .about-hero__pause {
      inset-block: 0 auto;
    }

    .about-hero__text {
      font-size: 0.875rem;
    }

    .about-hero__actions {
      flex-wrap: nowrap;
      justify-content: space-between;
      gap: var(--space-sm);
    }

    .about-hero__actions .about-hero__button {
      flex-shrink: 1;
      min-inline-size: 0;
      min-block-size: 2.75rem;
      padding-inline: clamp(0.75rem, 4.5vw, 1.25rem);
      font-size: 0.6875rem;
      letter-spacing: 0.1em;
      white-space: nowrap;
    }

    .about-hero__link {
      flex-shrink: 1;
      gap: 0.375rem;
      min-inline-size: 0;
      min-block-size: 1.5rem;
      font-size: 0.6875rem;
      letter-spacing: 0.1em;
      white-space: nowrap;
    }

    .about-hero__card-label {
      font-size: 0.6875rem;
      letter-spacing: 0.1em;
    }
  }

  /* Small phones (320px): a little smaller labels and spacing, so both buttons still share one row */
  @media (max-width: 374px) {
    .about-hero__actions .about-hero__button,
    .about-hero__link {
      font-size: min(0.6875rem, 3.1vw);
      letter-spacing: 0.05em;
    }

    .about-hero__card-label {
      letter-spacing: 0.06em;
    }
  }

/* sections/about-numbers.liquid */

  /*
    Figma 1920 (Default-10): eyebrow y 148, heading ~66px y 205–265 ("*Proof,* not promises.",
    accent upright); 4 cards 371x371 at x 183 / 598 / 1015 / 1430 (gap ~45, row ~1618 wide);
    card tops staggered y 330 / 437 / 357 / 408 (0 / 107 / 27 / 78 below the first).
    Phones (Variant46-3, 375 wide): heading ~26px, cards ~148x150, 26px apart, the right column
    30px lower.
  */

  /* --px = one Figma pixel. Scale off: it follows the width only, never more than 1px */
  .about-numbers {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /* Two classes: beats the shared .section--screen-scale rule whatever the bundle order */
  .about-numbers.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .about-numbers__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .about-numbers__header {
    margin-block-end: max(var(--space-xl), calc(65 * var(--px)));
    text-align: center;
  }

  .about-numbers__heading {
    margin: max(var(--space-lg), calc(40 * var(--px))) 0 0;
    font-size: max(2rem, calc(66 * var(--px)));
    line-height: 1.15;
  }

  .about-numbers__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /*
    Flex, not grid: a row that isn't full (1–3 cards, or 5–7) is centred. --columns (from Liquid) =
    the number of cards, at most 4; the row is never wider than that many cards.
  */
  .about-numbers__list {
    --numbers-columns: var(--columns, 4);
    --numbers-card: calc(371 * var(--px));
    --numbers-gap: max(var(--space-lg), calc(45 * var(--px)));

    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: center;
    gap: var(--numbers-gap);
    max-inline-size: calc(
      var(--numbers-columns) * var(--numbers-card) + (var(--numbers-columns) - 1) * var(--numbers-gap)
    );
    margin-inline: auto;
  }

  .about-numbers__list > * {
    flex: 0 0 calc((100% - (var(--numbers-columns) - 1) * var(--numbers-gap)) / var(--numbers-columns));
    min-inline-size: 0;
  }

  /* Staggered heights from 1200px (the cards are the direct children: the block has no wrapper) */
  @media (min-width: 1200px) {
    .about-numbers__list--stagger > :nth-child(4n + 2) {
      margin-block-start: calc(107 * var(--px));
    }

    .about-numbers__list--stagger > :nth-child(4n + 3) {
      margin-block-start: calc(27 * var(--px));
    }

    .about-numbers__list--stagger > :nth-child(4n + 4) {
      margin-block-start: calc(78 * var(--px));
    }

    /* The cards fade up one after another */
    .about-numbers__list > :nth-child(4n + 2) {
      --animate-delay: 100ms;
    }

    .about-numbers__list > :nth-child(4n + 3) {
      --animate-delay: 200ms;
    }

    .about-numbers__list > :nth-child(4n + 4) {
      --animate-delay: 300ms;
    }
  }

  .about-numbers__empty {
    margin: 0;
    text-align: center;
  }

  /*
    Phones and tablets: 2 per row in a zig-zag. The right column moves down with a relative offset
    (not a margin), so each column keeps its own even gap, as in the phone design; the list gets the
    same space at the bottom so the last card doesn't run into the padding.
  */
  @media (max-width: 1199px) {
    .about-numbers__list {
      --numbers-columns: min(var(--columns, 2), 2);
      --numbers-card: 13.5rem;
      --numbers-gap: 2rem;
    }

    .about-numbers__list--stagger {
      --numbers-drop: 2.5rem;

      padding-block-end: var(--numbers-drop);
    }

    .about-numbers__list--stagger > :nth-child(even) {
      position: relative;
      inset-block-start: var(--numbers-drop);
    }

    .about-numbers__list > :nth-child(even) {
      --animate-delay: 100ms;
    }
  }

  @media (max-width: 749px) {
    .about-numbers__list {
      --numbers-card: 9.25rem;
      --numbers-gap: 1.625rem;
    }

    .about-numbers__list--stagger {
      --numbers-drop: 1.875rem;
    }

    .about-numbers__header {
      margin-block-end: 1.75rem;
    }

    .about-numbers__heading {
      margin-block-start: var(--space-sm);
      font-size: 1.625rem;
    }
  }

/* sections/about-pillars.liquid */

  /*
    Figma 1920 (Default-2): text column x 55–815; progress y 197 (3 bars: active 66px accent,
    others ~30px accent 20%, then "01 / 03"); photos from y 155 to the screen's bottom, columns
    x 1068 (396 wide) and x 1488 (387 wide), gap 24, square corners, a white fade over the last
    ~200px; the right column starts higher. Sizes: Figma px x --px with rem floors, or tokens.
  */
  .about-pillars {
    /* One Figma pixel; with "Scale with the screen" also limited by the screen height */
    --px: min(calc(100vw / 1920), 0.0625rem);
    --progress: 0;
    --drift-distance: 35%;

    display: block;
    counter-reset: pillar;
    background-color: var(--color-background);
  }

  .about-pillars.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .about-pillars__inner {
    display: grid;
    gap: var(--space-2xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* Two columns only with photos (no empty photo column) */
  @media (min-width: 990px) {
    .about-pillars__inner--photos {
      grid-template-columns: minmax(0, 1013fr) minmax(0, 807fr);
      column-gap: var(--space-xl);
    }
  }

  .about-pillars__story {
    padding-block: max(6.5rem, calc(185 * var(--px))) var(--space-2xl);
  }

  /* ---------- Progress (only while the panel is pinned: it means nothing on stacked slides) ---------- */
  .about-pillars__progress {
    display: flex;
    align-items: center;
    gap: max(var(--space-md), calc(17 * var(--px)));
    margin-block-end: max(var(--space-xl), calc(60 * var(--px)));
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
  }

  .about-pillars:not([data-ready]) .about-pillars__progress {
    display: none;
  }

  .about-pillars__bar {
    inline-size: max(1.25rem, calc(30 * var(--px)));
    block-size: 2px;
    background-color: color-mix(in srgb, var(--color-accent) 20%, transparent);
  }

  .about-pillars__bar.is-active {
    inline-size: max(2.5rem, calc(66 * var(--px)));
    background-color: var(--color-accent);
  }

  .about-pillars__count {
    margin-inline-start: max(var(--space-md), calc(15 * var(--px)));
    white-space: nowrap;
  }

  .about-pillars__slides > * + * {
    margin-block-start: var(--space-3xl);
  }

  .about-pillars__empty {
    margin: 0;
    font-style: italic;
  }

  /* ---------- Photos ---------- */
  .about-pillars__photos {
    display: grid;
    grid-template-columns: minmax(0, 396fr) minmax(0, 387fr);
    align-items: start;
    position: relative;
    gap: max(var(--space-md), calc(24 * var(--px)));
    overflow: hidden;
  }

  /*
    The fade across the bottom of the screen (Figma "image 680": full width, 195px tall, from
    y 836 to the frame's bottom, over the photos and the text side alike): clear at the top left,
    the background at the bottom right. It uses the scheme's background, so it's white on the
    white scheme and still blends into any other scheme.
  */
  .about-pillars__panel {
    position: relative;
  }

  .about-pillars__panel::after {
    content: "";
    position: absolute;
    inset: auto 0 0;
    z-index: 1;
    block-size: max(7rem, calc(195 * var(--px))); /* 195px at 1920 */
    /*
      In a wide, short band the slanted gradient is already partly white along its top edge on the
      right, which drew a hard line (like a box). This mask fades the band in from its top, so it
      has no edge and melts into the photos like an overlay.
    */
    -webkit-mask-image: linear-gradient(to bottom, #00000000, #000000 70%);
    mask-image: linear-gradient(to bottom, #00000000, #000000 70%);
    background: linear-gradient(
      163.39deg,
      color-mix(in srgb, var(--color-background) 0%, transparent) 11.49%,
      var(--color-background) 96.29%
    );
    pointer-events: none;
  }

  .about-pillars__column {
    display: grid;
    gap: inherit;
  }

  .about-pillars__photo,
  .about-pillars__photo img {
    display: block;
    inline-size: 100%;
  }

  .about-pillars__photo--placeholder {
    aspect-ratio: 4 / 5;
    background-color: var(--color-tint-subtle);
  }

  .about-pillars__photo--placeholder svg {
    inline-size: 100%;
    block-size: 100%;
    fill: var(--color-tint-border);
  }

  /*
    ---------- Pinned (data-ready: the script runs and the content fits one screen) ----------
    The section is one screen tall per slide; its panel sticks to the top for the whole way, so the
    visitor scrolls "through" it. Slides lie on top of each other, the current one shows.
  */
  .about-pillars[data-ready] {
    block-size: calc(var(--slides) * 100svh);
  }

  .about-pillars[data-ready] .about-pillars__panel {
    position: sticky;
    inset-block-start: 0;
    block-size: 100svh;
    overflow: hidden;
  }

  @media (min-width: 990px) {
    .about-pillars[data-ready] .about-pillars__inner {
      block-size: 100%;
    }

    .about-pillars[data-ready] .about-pillars__photos {
      align-self: stretch;
      margin-block-start: max(6rem, calc(155 * var(--px)));
    }

    /* The left column moves up, the right one (starting higher) moves down */
    .about-pillars[data-ready] .about-pillars__column--1 {
      translate: 0 calc(var(--progress) * var(--drift-distance) * -1);
    }

    .about-pillars[data-ready] .about-pillars__column--2 {
      translate: 0 calc((var(--progress) - 1) * var(--drift-distance));
    }
  }

  /* The slides are the Pillar blocks themselves ("tag": null: no Shopify wrapper), stacked in one cell */
  .about-pillars[data-ready] .about-pillars__slides {
    display: grid;
  }

  .about-pillars[data-ready] .about-pillars__slides > * {
    grid-area: 1 / 1;
    margin: 0;
  }

  /*
    The slide change, line by line (label, heading, text, checklist):
    - waiting slides: invisible, already placed where they will come from (--enter-from: below when
      scrolling down, above when scrolling back; the script sets it), no transition, so they jump
      there unseen;
    - the leaving slide (is-leaving): fades out quickly, moving the other way;
    - the new slide (is-active): its lines rise into place one after another, starting once the old
      one has mostly gone, so the two texts never overlap in a muddle.
    --motion: 0 for visitors who reduce motion: then it's a plain, quick fade.
  */
  .about-pillars {
    --enter-from: 2rem;
    --motion: 1;
  }

  .about-pillars[data-ready] .pillar {
    pointer-events: none;
  }

  .about-pillars[data-ready] .pillar.is-active {
    pointer-events: auto;
  }

  .about-pillars[data-ready] .pillar > * {
    opacity: 0;
    translate: 0 calc(var(--enter-from) * var(--motion));
  }

  .about-pillars[data-ready] .pillar.is-leaving > * {
    translate: 0 calc(var(--enter-from) * var(--motion) * -0.5);
    transition:
      opacity 280ms ease-in,
      translate 380ms ease-in;
  }

  .about-pillars[data-ready] .pillar.is-active > * {
    opacity: 1;
    translate: 0 0;
    transition:
      opacity 600ms var(--ease-out) calc(220ms + var(--line, 0) * 90ms),
      translate 900ms var(--ease-out) calc(220ms + var(--line, 0) * 90ms);
  }

  .about-pillars[data-ready] .pillar > :nth-child(2) {
    --line: 1;
  }

  .about-pillars[data-ready] .pillar > :nth-child(3) {
    --line: 2;
  }

  .about-pillars[data-ready] .pillar > :nth-child(n + 4) {
    --line: 3;
  }

  @media (prefers-reduced-motion: reduce) {
    .about-pillars {
      --motion: 0;
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .about-pillars__bar {
      transition:
        inline-size var(--duration-slow) var(--ease-out),
        background-color var(--duration-slow) var(--ease-out);
    }

    /* One step per slide (no drift): the columns glide to their new place */
    .about-pillars[data-ready]:not([data-drift-on]) .about-pillars__column {
      transition: translate 1s var(--ease-out);
    }
  }

  /*
    ---------- Phones and tablets (Variant45-2, 46-1, 47-1) ----------
    The text, then the photos as two rows sliding sideways while the slide changes: row 1 starts
    7.5rem in from the screen edge on the first slide and moves left; row 2 starts cut off at the
    left and ends 7.5rem in on the last slide (--row-indent, --row-travel: 6rem per step of three
    slides). The rows reach the screen edges (negative page margins).
  */
  @media (max-width: 989px) {
    .about-pillars {
      --row-indent: 7.5rem;
      --row-travel: 12rem;
      --dir: 1;
    }

    /* translate is physical: mirror the moves on right-to-left pages */
    .about-pillars:dir(rtl) {
      --dir: -1;
    }

    .about-pillars[data-ready] .about-pillars__panel {
      display: flex;
      flex-direction: column;
    }

    .about-pillars__inner {
      gap: var(--space-lg);
    }

    .about-pillars__story {
      padding-block: 6rem 0;
    }

    .about-pillars__photos {
      grid-template-columns: none;
      margin-inline: calc(var(--page-margin) * -1);
    }

    .about-pillars__column {
      display: flex;
      inline-size: max-content;
    }

    .about-pillars__photo,
    .about-pillars__photo img {
      inline-size: auto;
      block-size: 7.25rem;
    }

    .about-pillars__photo img {
      aspect-ratio: auto;
      object-fit: cover;
    }

    .about-pillars__photo--placeholder {
      aspect-ratio: 1;
    }

    .about-pillars[data-ready] .about-pillars__column--1 {
      translate: calc((var(--row-indent) - var(--progress) * var(--row-travel)) * var(--dir)) 0;
    }

    .about-pillars[data-ready] .about-pillars__column--2 {
      translate: calc((var(--row-indent) - (1 - var(--progress)) * var(--row-travel)) * var(--dir)) 0;
    }
  }

  /* Phones (Variant45-2): small progress text */
  @media (max-width: 749px) {
    .about-pillars__progress {
      gap: var(--space-sm);
      margin-block-end: var(--space-lg);
      font-size: 0.625rem;
    }
  }

/* sections/about-team.liquid */

  /*
    Figma 1920 (Default-8): eyebrow y 148, heading ~66px y 205–265 (brush under "OroSkin"), intro
    ~19px / 29px centred, max ~880, y 310–360; arrows ~90x110 at x 380 y 285 and x 1600 y 325;
    3 cards x 279 / 795 / 1311, 393 wide, gap 123, photos from y 487; "OUR EXPERTS" ~150px at
    x 10–110, reading bottom to top, pale fill and a pale accent outline.
    Phones and tablets ("leaders", answer 12): 2 columns, the odd last card centred below.
  */
  .about-team {
    --px: min(calc(100vw / 1920), 0.0625rem);

    position: relative;
    overflow: hidden;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .about-team.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  /* The vertical word: the wrapper slides in (data-animate), the word inside is turned */
  .about-team__side {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: max(0.25rem, calc(10 * var(--px)));
    pointer-events: none;
  }

  .about-team__side-word {
    color: color-mix(in srgb, var(--color-accent) 7%, var(--color-background));
    font-family: var(--font-body--family);
    font-size: max(4.5rem, calc(150 * var(--px)));
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.02em;
    text-transform: uppercase;
    white-space: nowrap;
    writing-mode: vertical-rl;
    -webkit-text-stroke: 1px color-mix(in srgb, var(--color-accent) 22%, transparent);
    transform: rotate(180deg);
  }

  .about-team__side-word::before {
    content: attr(data-word);
  }

  .about-team__inner {
    position: relative;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .about-team__header {
    position: relative;
    margin-block-end: max(var(--space-2xl), calc(110 * var(--px)));
    text-align: center;
  }

  .about-team__heading {
    margin: max(var(--space-lg), calc(40 * var(--px))) 0 0;
    font-size: max(2rem, calc(66 * var(--px)));
    line-height: 1.15;
  }

  .about-team__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* Bold = the hand-drawn brush under the word (as in the hero), in the heading's weight */
  .about-team__heading strong {
    position: relative;
    font-weight: inherit;
  }

  .about-team__heading strong::after {
    content: "";
    position: absolute;
    /* Figma: the brush is ~220x35 under a ~230px word at 66px, so about half the font size tall */
    inset-inline: -10% -3%;
    inset-block-end: -0.42em;
    block-size: 0.45em;
    background-color: var(--color-accent);
    -webkit-mask: var(--brush-underline) center / 100% 100% no-repeat;
    mask: var(--brush-underline) center / 100% 100% no-repeat;
    pointer-events: none;
  }

  .about-team__text {
    max-inline-size: max(30rem, calc(880 * var(--px)));
    margin: max(var(--space-lg), calc(40 * var(--px))) auto 0;
    font-size: var(--font-size-body);
    line-height: 1.55;
  }

  .about-team__text > * {
    margin: 0;
  }

  .about-team__arrow {
    position: absolute;
    color: var(--color-text);
    pointer-events: none;
  }

  .about-team__arrow svg {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  .about-team__arrow--left {
    inset-block-start: max(7rem, calc(137 * var(--px)));
    inset-inline-start: calc(245 * var(--px));
    inline-size: max(3.5rem, calc(86 * var(--px)));
  }

  .about-team__arrow--right {
    inset-block-start: max(9rem, calc(177 * var(--px)));
    inset-inline-end: calc(82 * var(--px));
    inline-size: max(4rem, calc(103 * var(--px)));
  }

  /*
    Breathing: both arrows grow a little and shrink back, slowly and together. They start with the
    page (same stylesheet, same clock), so they stay in sync. A looping movement that never hides
    content: .motion-on ("Enable animations", also in the theme editor) and motion allowed.
  */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .about-team__arrow svg {
      animation: about-team-breathe 4s ease-in-out infinite;
    }
  }

  @keyframes about-team-breathe {
    0%,
    100% {
      transform: scale(0.92);
    }

    50% {
      transform: scale(1.08);
    }
  }

  /* The cards are the list's direct children (the blocks have no Shopify wrapper) */
  .about-team__list {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 393fr));
    gap: max(var(--space-2xl), calc(80 * var(--px))) max(var(--space-2xl), calc(123 * var(--px)));
    max-inline-size: calc(1425 * var(--px));
    margin-inline: auto;
  }

  /* The cards fade up one after another, by column */
  .about-team__list > :nth-child(3n + 2) {
    --animate-delay: 100ms;
  }

  .about-team__list > :nth-child(3n + 3) {
    --animate-delay: 200ms;
  }

  .about-team__empty,
  .about-team__note {
    margin: 0;
    font-style: italic;
    text-align: center;
  }

  .about-team__empty {
    margin-block-start: var(--space-lg);
  }

  @media (max-width: 1199px) {
    .about-team__list {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: var(--space-2xl) var(--space-md);
      max-inline-size: 48rem;
    }

    /* The odd last card: centred under the others, one column wide */
    .about-team__list > :last-child:nth-child(odd) {
      grid-column: 1 / -1;
      justify-self: center;
      inline-size: calc(50% - var(--space-md) / 2);
    }

    .about-team__list > :nth-child(n) {
      --animate-delay: 0ms;
    }

    .about-team__list > :nth-child(2n) {
      --animate-delay: 100ms;
    }

    .about-team__arrow {
      display: none;
    }
  }

  /* Phones ("leaders"): heading ~26px, the side word ~45px letters, partly off the left edge, from ~110px down */
  @media (max-width: 749px) {
    .about-team__side {
      inset-block-start: 6.875rem;
      inset-inline-start: -0.5rem;
    }

    .about-team__side-word {
      font-size: 4rem;
    }

    /*
      The slide-in starts 1.5rem to the left (not the theme's 4rem): from the edge, 4rem put the whole
      word off the screen, so the scroll observer never saw it and it never slid in.
    */
    @media (prefers-reduced-motion: no-preference) {
      .js.animations-on .about-team__side[data-animate]:not(.is-visible) {
        transform: translateX(-1.5rem);
      }
    }

    .about-team__header {
      margin-block-end: var(--space-2xl);
    }

    .about-team__heading {
      margin-block-start: var(--space-md);
      font-size: 1.625rem;
    }

    .about-team__text {
      margin-block-start: var(--space-lg);
      font-size: var(--font-size-body-sm);
    }
  }

/* sections/about-timeline.liquid */

  /*
    Figma 1920 (Default-3): eyebrow y 155 (centred, rules both sides), heading ~66px y 210–275
    ("*Seven years*, slowly.": the accent words upright); first milestone ~85px under the heading.
    --rail-x / --content-x: the rail at x 237 and the content at x 301 (from the page's x 48).
  */
  .about-timeline {
    /* One Figma pixel; with "Scale with the screen" also limited by the screen height */
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .about-timeline.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .about-timeline__inner {
    --rail-x: max(1.25rem, calc(189 * var(--px)));
    --content-x: max(3.5rem, calc(253 * var(--px)));

    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .about-timeline__header {
    margin-block-end: max(var(--space-xl), calc(45 * var(--px)));
    text-align: center;
  }

  .about-timeline__heading {
    margin: max(var(--space-lg), calc(40 * var(--px))) 0 0;
    font-size: max(2rem, calc(66 * var(--px)));
    line-height: 1.1;
  }

  /* Italic words: the accent colour, upright (as in the Figma) */
  .about-timeline__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /*
    Without the script, each milestone draws its own rail piece (::before, from its top to its
    end). The last one stops a little under its marker (Default-4). The milestones are the list's
    children ("tag": null); "1 of .milestone" skips an editor note after the last one.
  */
  .about-timeline__list > .milestone:nth-last-child(1 of .milestone)::before {
    inset-block-end: auto;
    block-size: calc(var(--milestone-pad-top) + 4.5rem);
  }

  /*
    With the script (data-ready), one rail for the whole list replaces the milestones' own pieces:
    a pale track and the accent fill, like a progress bar. The script sets --rail-top /
    --rail-length (px, from just above the first marker to just past the last one) and --fill-px,
    easing it so the fill glides instead of jumping with the wheel. When the visitor stops scrolling
    partway through (is-waiting), a light sweeps down the fill three times as a hint to scroll on;
    scrolling hides it at once. It never loops for long (WCAG 2.2.2).
    --rail-lead: how far the rail starts above the first marker (px: the script reads it).
  */
  .about-timeline__list {
    --rail-lead: 0px;

    position: relative;
  }

  .about-timeline__rail {
    display: none;
  }

  .about-timeline[data-ready] .about-timeline__rail {
    position: absolute;
    z-index: 0;
    display: block;
    inset-block-start: var(--rail-top, 0px);
    inset-inline-start: calc(var(--rail-x) - 1px);
    inline-size: 2px;
    block-size: var(--rail-length, 0px);
    background-color: color-mix(in srgb, var(--color-accent) 15%, transparent);
    pointer-events: none;
  }

  /* The fill covers the whole rail and is cut to --fill-px (so the sweep isn't stretched) */
  .about-timeline__fill {
    position: absolute;
    inset: 0;
    overflow: hidden;
    background-color: var(--color-accent);
    clip-path: inset(0 0 calc(100% - var(--fill-px, 0px)) 0);
  }

  .about-timeline__fill::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: linear-gradient(
      to bottom,
      #ffffff00 0,
      color-mix(in srgb, var(--color-background) 70%, transparent) 4rem,
      #ffffff00 8rem
    );
    background-size: 100% 16rem;
    opacity: 0;
  }

  /* Three sweeps, fading in and out, then it rests (restarts the next time the visitor pauses) */
  .about-timeline__list.is-waiting .about-timeline__fill::after {
    animation:
      about-timeline-sweep 1.2s linear 3,
      about-timeline-sweep-fade 3.6s ease-in-out forwards;
  }

  @keyframes about-timeline-sweep {
    to {
      background-position: 0 16rem;
    }
  }

  @keyframes about-timeline-sweep-fade {
    15%,
    80% {
      opacity: 1;
    }

    to {
      opacity: 0;
    }
  }

  .about-timeline__empty {
    margin: 0 0 var(--space-lg);
    font-style: italic;
    text-align: center;
  }

  /*
    Phones and tablets (Variant45-3 at 375px, tablets the same layout a little bigger): the rail
    near the left edge, the content next to it, the year at the right. The rail starts ~20px above
    the first marker (Variant45-3).
  */
  @media (max-width: 1199px) {
    .about-timeline__inner {
      --rail-x: 0.5rem;
      --content-x: 2.5rem;
    }

    .about-timeline__list {
      --rail-lead: 20px;
    }

    .about-timeline__header {
      margin-block-end: var(--space-2xl);
    }

    .about-timeline__heading {
      margin-block-start: var(--space-md);
      font-size: 2.25rem;
    }
  }

  @media (max-width: 749px) {
    .about-timeline__inner {
      --rail-x: 0.375rem;
      --content-x: 1.875rem;
    }

    .about-timeline__header {
      margin-block-end: var(--space-xl);
    }

    .about-timeline__heading {
      font-size: 1.625rem;
    }
  }

/* sections/about-values.liquid */

  /*
    Figma 1920 (Default-9): eyebrow y 148, heading ~66px y 205–265 ("Our Core *Values*", accent
    upright); cards from y 306: 3 columns 538 wide (x 103 / 691 / 1279, gap ~50), 2 rows ~326
    tall with a ~48 gap; card 01 spans both rows.
  */
  .about-values {
    --px: min(calc(100vw / 1920), 0.0625rem);

    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .about-values.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .about-values__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .about-values__header {
    margin-block-end: max(var(--space-xl), calc(40 * var(--px)));
    text-align: center;
  }

  /* Only a hidden h2: no space under an empty header */
  .about-values__header:not(:has(:not(.visually-hidden))) {
    margin-block-end: 0;
  }

  .about-values__heading {
    margin: max(var(--space-lg), calc(40 * var(--px))) 0 0;
    font-size: max(2rem, calc(66 * var(--px)));
    line-height: 1.15;
  }

  .about-values__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* The cards are the list's direct children (the blocks have no Shopify wrapper) */
  .about-values__list {
    counter-reset: value-card;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    grid-auto-rows: minmax(max(16rem, calc(326 * var(--px))), auto);
    gap: max(var(--space-xl), calc(48 * var(--px))) max(var(--space-xl), calc(50 * var(--px)));
  }

  /* Two rows tall only with a photo to fill it and at least 2 more cards beside it */
  .about-values__list--feature > .value-card--media:first-child:nth-last-child(n + 3) {
    grid-row: span 2;
  }

  /* The cards fade up one after another, by column */
  .about-values__list > :nth-child(3n + 2) {
    --animate-delay: 100ms;
  }

  .about-values__list > :nth-child(3n + 3) {
    --animate-delay: 200ms;
  }

  .about-values__empty,
  .about-values__note {
    margin: 0;
    font-style: italic;
    text-align: center;
  }

  /* Phones and tablets (Variant49 / 50): 2 columns; the featured card full width */
  @media (max-width: 1199px) {
    .about-values__list {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      grid-auto-rows: auto;
      gap: var(--space-md);
    }

    .about-values__list--feature > :first-child {
      grid-column: 1 / -1;
    }

    /*
      A lone card in the last row: centred, one column wide. With the featured card, the others
      start at child 2, so the lone one is an even child; without it, an odd child.
    */
    .about-values__list--feature > :last-child:nth-child(even):not(:first-child),
    .about-values__list:not(.about-values__list--feature) > :last-child:nth-child(odd) {
      grid-column: 1 / -1;
      justify-self: center;
      inline-size: calc(50% - var(--space-md) / 2);
    }

    /* Delays by column: column 2 = the odd children after the featured card, else the even ones */
    .about-values__list > :nth-child(n) {
      --animate-delay: 0ms;
    }

    .about-values__list--feature > :nth-child(odd):not(:first-child),
    .about-values__list:not(.about-values__list--feature) > :nth-child(even) {
      --animate-delay: 100ms;
    }
  }

  @media (max-width: 749px) {
    .about-values__list {
      gap: 0.75rem;
    }

    .about-values__list--feature > :last-child:nth-child(even):not(:first-child),
    .about-values__list:not(.about-values__list--feature) > :last-child:nth-child(odd) {
      inline-size: calc(50% - 0.375rem);
    }

    .about-values__heading {
      margin-block-start: var(--space-md);
    }
  }

/* sections/announcement-bar.liquid */

  /*
    The Header group wraps each of its sections in .shopify-section-group-header-group. Only the header's
    wrapper is sticky (header.liquid); this one stays in the page flow, so the bar scrolls away.
  */
  .announcement-bar {
    display: block;
    background-color: var(--color-background);
    color: var(--color-text);
  }

  .announcement-bar[hidden] {
    display: none;
  }

  /*
    Close: the script fixes the bar's height, then animates it (and the opacity) to zero, so the bar
    collapses instead of vanishing. block-size + opacity are set inline by the script; this only supplies
    the easing. The full-height hero grows back in step (see hero.liquid). Instant with reduced motion.
  */
  .announcement-bar.is-closing {
    overflow: hidden;
  }

  @media (prefers-reduced-motion: no-preference) {
    .announcement-bar {
      transition:
        block-size var(--duration-base, 300ms) var(--ease-out),
        opacity var(--duration-base, 300ms) var(--ease-out);
    }
  }

  .announcement-bar__inner {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    min-block-size: var(--announcement-size, 2.25rem);
    padding-inline: var(--page-margin);
    font-size: var(--announcement-text, var(--font-size-small));
    font-weight: var(--font-weight-medium);
    line-height: 1.3;
  }

  /*
    Horizontal bar: the message area fills the row by default, and Text alignment places the text inside it.
    (Slideshow instead lets the arrows hug the text — see below.) The pause and close buttons are taken out
    of the flow and pinned to the two ends, so neither shifts the text. Whenever either button is present,
    both ends reserve the same room, so the message stays centred with one button or two.
    These rules are written for every bar (not only --top): "Right side" is a bar above the header below
    990px too, and the band's own rules (min-width: 990px, further down) override them.
  */
  .announcement-bar__messages {
    flex: 1;
  }

  .announcement-bar .announcement-bar__inner:is(:has(.announcement-bar__close), :has(.announcement-bar__pause)) {
    padding-inline: calc(var(--page-margin) + 1.5rem + var(--space-sm));
  }

  .announcement-bar--font-heading .announcement-bar__inner {
    font-family: var(--font-heading--family);
  }

  /* Arrows follow the text size */
  .announcement-bar__arrow {
    inline-size: 1.15em;
    block-size: 1.15em;
  }

  .announcement-bar--uppercase .announcement-bar__inner {
    letter-spacing: 0.2em;
    text-transform: uppercase;
  }

  .announcement-bar__message {
    margin: 0;
  }

  /*
    Text alignment: moves the slideshow's arrows + message group along the bar (left / right above the
    header, top / bottom in the band). The text itself is placed by auto margins (see the message line).
  */
  .announcement-bar--align-start .announcement-bar__inner {
    justify-content: flex-start;
  }

  .announcement-bar--align-end .announcement-bar__inner {
    justify-content: flex-end;
  }

  .announcement-bar__link-label {
    margin-inline-start: 0.5em;
  }

  .announcement-bar__link {
    color: inherit;
    text-decoration: underline;
    text-underline-offset: 0.35em;
  }

  .announcement-bar__link:hover {
    text-decoration-thickness: 2px;
  }

  /* Slideshow: every message in the same grid cell, so the bar keeps the tallest one's size (no jumps) */
  .announcement-bar--slideshow .announcement-bar__messages {
    display: grid;
    min-inline-size: 0;
    /* Don't stretch: the box shrinks to the message so the arrows sit right beside the text, centred as a group */
    flex: 0 1 auto;
    grid-template-columns: minmax(0, 1fr); /* each line is at most the box's width, so a long one can scroll */
  }

  .announcement-bar--slideshow .announcement-bar__message {
    grid-area: 1 / 1;
  }

  .announcement-bar--slideshow .announcement-bar__message:not(.is-active) {
    visibility: hidden;
    opacity: 0;
  }

  /* The fade between messages; with reduced motion the text just changes (autoplay still runs) */
  @media (prefers-reduced-motion: no-preference) {
    .animations-on .announcement-bar--slideshow .announcement-bar__message {
      transition:
        opacity var(--duration-base) var(--ease-out),
        visibility var(--duration-base);
    }
  }

  /* Without JavaScript the arrows can't change the message: hidden (the first message shows) */
  .no-js .announcement-bar__prev,
  .no-js .announcement-bar__next {
    display: none;
  }

  /* Small round buttons: arrows, pause / play, close (24px targets, WCAG 2.5.8) */
  .announcement-bar__button {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background-color: transparent;
    color: inherit;
    cursor: pointer;
  }

  .announcement-bar__button:hover {
    background-color: color-mix(in srgb, var(--color-text) 15%, transparent);
  }

  .announcement-bar__button[hidden] {
    display: none;
  }

  .announcement-bar__close {
    position: absolute;
    inset-inline-end: var(--page-margin);
  }

  /*
    Bar above the header (Top, and Right side below 990px): pause/play is pinned to the start end and close
    to the other, both out of the flow, and centred vertically so they sit right whatever the bar's height.
  */
  .announcement-bar .announcement-bar__pause {
    position: absolute;
    inset-inline-start: var(--page-margin);
  }

  .announcement-bar .announcement-bar__close,
  .announcement-bar .announcement-bar__pause {
    inset-block: 0;
    margin-block: auto;
  }

  /* Play icon only while paused, pause icon only while playing (driven by .is-paused on the host element) */
  .announcement-bar:not(.is-paused) .announcement-bar__icon--play,
  .announcement-bar.is-paused .announcement-bar__icon--pause {
    display: none;
  }

  /*
    Marquee. The script adds is-moving when the strip may move: not in the theme editor, and the visitor
    hasn't asked for reduced motion. (The theme's "Enable animations" setting doesn't matter: choosing
    Marquee is the merchant's own choice.)
    - Not moving: the strip is hidden and the real line shows (one line, scrolls, follows Text alignment).
    - Moving: the strip shows and the real line is visually hidden (screen readers still read it). When the
      keyboard reaches the real line, it swaps in for the strip, so the focus ring can be seen.
    The track slides by one half, then starts over; the halves are the same, so no seam shows.
  */
  .announcement-bar__viewport {
    display: none;
    overflow: hidden;
    min-inline-size: 0;
    flex: 1;
    padding-block: 0.3em; /* room for the link underline (offset 0.35em), which overflow: hidden would cut off */
  }

  .announcement-bar--marquee.is-moving:not(:has(.announcement-bar__marquee-line:focus-within)) .announcement-bar__viewport {
    display: block;
  }

  .announcement-bar--marquee.is-moving:not(:has(.announcement-bar__marquee-line:focus-within)) .announcement-bar__messages {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    padding: 0;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
    border: 0;
  }

  /* Real line: a dot between messages, with room on both sides */
  .announcement-bar__marquee-line .announcement-bar__separator {
    padding-inline: 1em;
  }

  .announcement-bar__track,
  .announcement-bar__half {
    display: flex;
    align-items: center;
    inline-size: max-content;
  }

  .announcement-bar__item,
  .announcement-bar__separator {
    flex-shrink: 0;
    padding-inline-end: 2em;
    white-space: nowrap;
  }

  /* Letter spacing: Automatic = from Text style (uppercase is spaced, wider in the band). The class is doubled so a
     chosen value also beats the band's uppercase rule further down. */
  .announcement-bar.announcement-bar.announcement-bar--spacing-normal .announcement-bar__inner {
    letter-spacing: 0;
  }

  .announcement-bar.announcement-bar.announcement-bar--spacing-wide .announcement-bar__inner {
    letter-spacing: 0.1em;
  }

  .announcement-bar.announcement-bar.announcement-bar--spacing-extra .announcement-bar__inner {
    letter-spacing: 0.3em;
  }

  /*
    Horizontal bar on phones (below 750px): the text follows the screen width instead of the fixed Text size,
    and the letter spacing shrinks with it, so a short message stays on one line. Text size is the upper
    limit: min() takes the smaller of the setting and 3.4% of the screen width (11px on a 320px phone,
    ~13px at 375px), never below 11px. A message that still doesn't fit stays on one line and scrolls
    sideways, as on every screen size (Static and Slideshow); Marquee keeps any length on one line by moving.
    Letter spacing Automatic only: a spacing the merchant picked by hand is kept.
  */
  @media (max-width: 749px) {
    .announcement-bar__inner {
      font-size: max(0.6875rem, min(var(--announcement-text, 0.875rem), 3.4vw));
      padding-block: var(--space-2xs);
    }

    /* Phones: tighter icon room so the message keeps more width */
    .announcement-bar .announcement-bar__inner:is(:has(.announcement-bar__close), :has(.announcement-bar__pause)) {
      padding-inline: calc(var(--space-xs) + 1.5rem);
    }

    .announcement-bar .announcement-bar__close {
      inset-inline-end: var(--space-2xs);
    }

    .announcement-bar .announcement-bar__pause {
      inset-inline-start: var(--space-2xs);
    }

    .announcement-bar--uppercase.announcement-bar--spacing-auto .announcement-bar__inner {
      letter-spacing: 0.08em;
    }
  }

  /*
    Static and Slideshow, every screen size: a long message stays on ONE line and its line scrolls sideways
    (swipe, trackpad, Shift + mouse wheel, or the arrow keys once focused) instead of wrapping. Each message
    line (.announcement-bar__scroller) is the scroll box and its text span grows past it (max-content).
    When it fits, the text follows the Text alignment setting via the auto margins; when it is too long the
    margins collapse to 0, so it reads from its start. The scrollbar is hidden; a soft fade marks whichever
    side still has text off screen. The script toggles has-overflow-start / -end on the line, so once you
    reach an end that end is fully shown. A little block padding leaves room for the focus ring.
    Slideshow: the arrows hug a short message; a long one fills the room between them and scrolls.
    The right-side band scrolls the same way, but up and down (its text runs top to bottom).
  */
  /*
    Room for the focus ring: a scroll box clips everything outside its padding (top and bottom too), and the
    ring needs 6px (4px offset + 2px line). 8px of padding gives it room; the negative margin takes the
    extra back, so the bar keeps its height.
  */
  .announcement-bar__scroller {
    overflow-x: auto;
    padding-block: 0.5rem;
    margin-block: -0.25rem;
    scrollbar-width: none; /* Firefox: hide the bar; the fades are the cue */
  }

  .announcement-bar__scroller::-webkit-scrollbar {
    display: none; /* Chrome / Safari */
  }

  .announcement-bar__scroller.has-overflow-start.has-overflow-end {
    -webkit-mask-image: linear-gradient(to right, transparent, #000 2.5rem, #000 calc(100% - 2.5rem), transparent);
    mask-image: linear-gradient(to right, transparent, #000 2.5rem, #000 calc(100% - 2.5rem), transparent);
  }

  .announcement-bar__scroller.has-overflow-end:not(.has-overflow-start) {
    -webkit-mask-image: linear-gradient(to right, #000 calc(100% - 2.5rem), transparent);
    mask-image: linear-gradient(to right, #000 calc(100% - 2.5rem), transparent);
  }

  .announcement-bar__scroller.has-overflow-start:not(.has-overflow-end) {
    -webkit-mask-image: linear-gradient(to right, transparent, #000 2.5rem);
    mask-image: linear-gradient(to right, transparent, #000 2.5rem);
  }

  .announcement-bar__scroller .announcement-bar__text {
    display: block;
    inline-size: max-content;
    margin-inline: auto; /* centre (default); the auto margins place a message that fits */
    white-space: nowrap;
  }

  /* Follow the Text alignment setting when the message fits (ignored once it overflows and scrolls) */
  .announcement-bar--align-start .announcement-bar__scroller .announcement-bar__text {
    margin-inline: 0 auto;
  }

  .announcement-bar--align-end .announcement-bar__scroller .announcement-bar__text {
    margin-inline: auto 0;
  }

  /*
    Keyboard focus: the ring is drawn on the text span, not the full-width scroll box, so it hugs the
    message. outline-offset gives the gap ("padding") between the text and the ring; the pill radius rounds
    it. currentColor keeps it visible on any colour scheme (e.g. the red band).
  */
  .announcement-bar__text {
    border-radius: var(--radius-pill);
  }

  .announcement-bar__scroller:focus-visible {
    outline: none;
  }

  .announcement-bar__scroller:focus-visible .announcement-bar__text {
    outline: 2px solid currentColor;
    outline-offset: 4px;
  }

  @media (prefers-reduced-motion: no-preference) {
    .announcement-bar--marquee.is-moving .announcement-bar__track {
      animation: announcement-slide-x var(--announcement-duration, 40s) linear infinite;
    }

    .announcement-bar--marquee-right.is-moving .announcement-bar__track {
      animation-direction: reverse;
    }

    /*
      Paused while the mouse is over it or by the pause button. Not on keyboard focus: focus on the message
      already swaps in the still line, and pausing on focus kept it stopped after pressing play (the button
      keeps focus).
    */
    .announcement-bar--marquee.is-moving.is-paused .announcement-bar__track {
      animation-play-state: paused;
    }

    /* Hover only with a real mouse: on touch screens :hover sticks after a tap, which kept it stopped */
    @media (hover: hover) {
      .announcement-bar--marquee.is-moving:hover .announcement-bar__track {
        animation-play-state: paused;
      }
    }
  }

  @keyframes announcement-slide-x {
    to {
      transform: translateX(-50%);
    }
  }

  @keyframes announcement-slide-y {
    to {
      transform: translateY(-50%);
    }
  }

  /*
    Right side (large screens): the vertical band (Figma home hero, 36px). writing-mode turns the whole row
    sideways, so the same flex layout runs top to bottom; arrows turn to point up and down, and the marquee
    moves vertically ("Left" = up).
  */
  @media (min-width: 990px) {
    /*
      Fixed to the right edge of the screen, one screen tall, so it is always whole while the page scrolls.
      "Slide away while scrolling down": the script adds is-tucked once the page has scrolled down and removes it
      only back at the top; the band slides out to the right and back (instant with reduced motion).
    */
    .announcement-bar--right {
      position: fixed;
      inset-block-start: 0;
      inset-inline-end: 0;
      z-index: 15; /* under the sticky header (20) */
      inline-size: var(--announcement-size, 2.25rem);
      block-size: 100svh;
    }

    .announcement-bar--right.is-tucked {
      translate: 100% 0;
    }

    @media (prefers-reduced-motion: no-preference) {
      .announcement-bar--right {
        transition:
          translate var(--duration-slow, 0.5s) var(--ease-out),
          opacity var(--duration-base, 300ms) var(--ease-out);
      }
    }

    /*
      Arrows stay right next to the message (one compact group, like the bar above the header); Text alignment
      places the group at the top, middle or bottom of the band.
      The page keeps the band's width free on the right, so the band never covers content (full-width
      sections included): body padding narrows everything that is laid out inside it.
    */
    .announcement-bar--right .announcement-bar__messages {
      flex: 0 1 auto;
      min-inline-size: 0;
    }

    /*
      The page leaves the band's width free only while the band is showing: once it slides out
      (is-tucked), the gap closes with it, so no empty strip stays on the right.
    */
    body:has(.announcement-bar--right:not([hidden]):not(.is-tucked)) {
      padding-inline-end: var(--announcement-size, 2.25rem);
    }

    @media (prefers-reduced-motion: no-preference) {
      body:has(.announcement-bar--right) {
        transition: padding-inline-end var(--duration-slow, 0.5s) var(--ease-out);
      }
    }

    .announcement-bar--right .announcement-bar__inner {
      writing-mode: vertical-rl;
      /*
        Physical sizes on purpose: with vertical writing, "block" means across and "inline" means down, so
        block-size: 100% only set the width and the row stayed as short as its content (alignment had no room).
      */
      inline-size: auto;
      block-size: auto;
      width: 100%;
      height: 100%;
      min-block-size: 0;
      padding-inline: var(--space-sm);
    }

    .announcement-bar--right.announcement-bar--uppercase .announcement-bar__inner {
      letter-spacing: 0.35em;
    }

    /*
      The band reads top to bottom, so a long message scrolls up and down along the band (mouse wheel,
      trackpad, or the arrow keys once focused) instead of sideways, and the fades sit at the top / bottom.
      (Text alignment still places a message that fits: top, middle or bottom of the band.)
    */
    .announcement-bar--right .announcement-bar__scroller {
      overflow-x: hidden;
      overflow-y: auto;
    }

    .announcement-bar--right .announcement-bar__scroller.has-overflow-start.has-overflow-end {
      -webkit-mask-image: linear-gradient(to bottom, transparent, #000 2.5rem, #000 calc(100% - 2.5rem), transparent);
      mask-image: linear-gradient(to bottom, transparent, #000 2.5rem, #000 calc(100% - 2.5rem), transparent);
    }

    .announcement-bar--right .announcement-bar__scroller.has-overflow-end:not(.has-overflow-start) {
      -webkit-mask-image: linear-gradient(to bottom, #000 calc(100% - 2.5rem), transparent);
      mask-image: linear-gradient(to bottom, #000 calc(100% - 2.5rem), transparent);
    }

    .announcement-bar--right .announcement-bar__scroller.has-overflow-start:not(.has-overflow-end) {
      -webkit-mask-image: linear-gradient(to bottom, transparent, #000 2.5rem);
      mask-image: linear-gradient(to bottom, transparent, #000 2.5rem);
    }

    .announcement-bar--right .announcement-bar__arrow {
      rotate: 90deg;
    }

    .announcement-bar--right .announcement-bar__close {
      inset-inline-end: auto;
      inset-inline-start: var(--space-sm);
    }

    /* Pause / play: at the bottom end of the band, the close button's counterpart at the top */
    .announcement-bar--right .announcement-bar__pause {
      position: absolute;
      inset-inline-start: auto; /* undo the bar-above-header pin */
      inset-inline-end: var(--space-sm);
    }

    /*
      With a close or pause button, both ends keep the button's room plus a gap, like the bar above the
      header: the text never runs under a button and stays centred in the band.
    */
    .announcement-bar--right .announcement-bar__inner:is(:has(.announcement-bar__close), :has(.announcement-bar__pause)) {
      padding-inline: calc(var(--space-sm) + 1.5rem + var(--space-md));
    }

    @media (prefers-reduced-motion: no-preference) {
      .announcement-bar--right.announcement-bar--marquee.is-moving .announcement-bar__track {
        animation-name: announcement-slide-y;
      }
    }
  }

/* sections/article-comments.liquid */

  /*
    Figma 1920: heading 40px (heading font), count line 20px; form card 1116 x 123 (radius ~25, 1px
    pale border), avatar 58; each comment: avatar 58, name 20px medium, date on the right (grey),
    text 20px; "LOAD 35 MORE COMMENTS ⌄" accent label with an underline, centred.
    Sizes are Figma px x --px (screen-scale) with rem floors, or tokens.
  */
  /* --px: one Figma pixel, by the width only and never more than 1px (without it the 1920px sizes
     showed on phones). With "Scale with the screen" on, the rule after it also reads the height. */
  .article-comments {
    --px: min(calc(100vw / 1920), 0.0625rem);
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .article-comments.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .article-comments__inner {
    display: block;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    scroll-margin-block-start: calc(var(--header-space, 6.0625rem) + var(--space-lg));
  }

  /* From 1200px: the article section's columns (text 1114 / gap 171 / sidebar 354), content under the text */
  @media (min-width: 1200px) {
    .article-comments--aligned .article-comments__inner {
      display: grid;
      grid-template-columns: minmax(0, 1114fr) minmax(var(--space-2xl), 171fr) minmax(17rem, 354fr);
    }
  }

  .article-comments__content {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-xl), calc(40 * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  .article-comments__header > * {
    margin: 0;
  }

  .article-comments__heading {
    font-size: var(--font-size-h2);
    line-height: 1.25;
  }

  .article-comments__count {
    margin-block-start: var(--space-xs);
    font-size: var(--font-size-body);
  }

  /* ---------- Form card ---------- */
  .article-comments__form {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    margin: 0;
  }

  /*
    At rest (Figma 1116 x 123): avatar | text | Post comment on one line.
    Open (a text field has focus, text is typed, or after an error; not when only the button has focus,
    so clicking Post never moves it away from under the pointer): the text takes the whole line, then the name
    and email fields with Post comment beside them. The known customer's card stays at rest.
  */
  .article-comments__card {
    display: grid;
    grid-template-columns: max(3rem, calc(58 * var(--px, 0.0625rem))) minmax(0, 1fr) auto;
    grid-template-areas: 'avatar body submit';
    align-items: center;
    gap: var(--space-md) max(var(--space-md), calc(26 * var(--px, 0.0625rem)));
    padding: max(var(--space-md), calc(24 * var(--px, 0.0625rem))) max(var(--space-lg), calc(33 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: max(var(--radius-sm), calc(20 * var(--px, 0.0625rem)));
    background-color: var(--color-background);
    transition: border-color var(--duration-fast) var(--ease-out);
  }

  .article-comments__card:focus-within {
    border-color: color-mix(in srgb, var(--color-accent) 40%, var(--color-background));
  }

  /* The text field has no ring of its own: with the keyboard, the card edge is the focus ring */
  .article-comments__card:has(.article-comments__textarea:focus-visible) {
    border-color: var(--color-accent);
    box-shadow: 0 0 0 1px var(--color-accent);
  }

  /*
    Avatars are 58px circles (Figma) in the card and in the list. align-self: flex-start stops the
    comment row (a flex row) from stretching the avatar to the row's height, which would turn the
    circle into an oval; block-size: auto lets aspect-ratio: 1 set the height.
  */
  .article-comments .article-comments__avatar {
    flex: none;
    align-self: flex-start;
    inline-size: max(3rem, calc(58 * var(--px, 0.0625rem)));
    block-size: auto;
    aspect-ratio: 1;
    font-size: var(--font-size-caption);
  }

  /* In the card it fills its grid column (the same 58px) */
  .article-comments__card .article-comments__avatar {
    grid-area: avatar;
    align-self: start;
    inline-size: 100%;
  }

  .article-comments__avatar svg {
    inline-size: 45%;
    block-size: auto;
  }

  /* The text field has no box of its own: the card is the box (Figma) */
  .article-comments .article-comments__textarea {
    grid-area: body;
    align-self: start;
    min-inline-size: 0;
    min-block-size: max(3rem, calc(58 * var(--px, 0.0625rem)));
    padding: var(--space-sm) 0;
    border: 0;
    border-radius: 0;
    background: none;
    box-shadow: none;
    color: var(--color-text);
    font-size: var(--font-size-body);
    line-height: 1.5;
    resize: none;
    field-sizing: content;
  }

  .article-comments .article-comments__textarea:focus-visible {
    outline: none;
  }

  .article-comments__textarea::placeholder {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  .article-comments__submit {
    grid-area: submit;
  }

  .article-comments__submit svg {
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  .article-comments__extra {
    display: none;
    grid-area: extra;
    flex-direction: column;
    gap: var(--space-sm);
  }

  .article-comments__card:is(.is-open, :has(:is(textarea, input):focus), :has(.article-comments__textarea:not(:placeholder-shown))):not(.article-comments__card--known),
  .article-comments__card--known.is-open {
    grid-template-areas:
      'avatar body body'
      '. extra submit';
  }

  .article-comments__card:is(.is-open, :has(:is(textarea, input):focus), :has(.article-comments__textarea:not(:placeholder-shown))):not(.article-comments__card--known) .article-comments__extra,
  .article-comments__card--known.is-open .article-comments__extra {
    display: flex;
  }

  .article-comments__card:is(.is-open, :has(:is(textarea, input):focus), :has(.article-comments__textarea:not(:placeholder-shown))):not(.article-comments__card--known) .article-comments__submit,
  .article-comments__card--known.is-open .article-comments__submit {
    align-self: start;
    margin-block-start: 1.5rem; /* level with the fields, under their labels */
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-comments__extra {
      animation: article-comments-open var(--duration-normal) var(--ease-out);
    }
  }

  @keyframes article-comments-open {
    from {
      opacity: 0;
      translate: 0 -0.5rem;
    }
  }

  .article-comments__fields {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-md);
  }

  .article-comments__field {
    display: flex;
    flex: 1 1 12rem;
    flex-direction: column;
    gap: var(--space-2xs);
  }

  .article-comments__label {
    font-size: var(--font-size-small);
  }

  .article-comments .article-comments__input {
    min-block-size: 3.125rem; /* 50px, the button's height */
    padding-inline: var(--space-lg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-card);
    color: var(--color-text);
    font-size: var(--font-size-caption);
  }

  .article-comments .article-comments__input:focus-visible {
    border-color: var(--color-accent);
  }

  .article-comments .article-comments__input[aria-invalid='true'] {
    border-color: var(--color-error);
  }

  .article-comments__card:has(.article-comments__textarea[aria-invalid='true']) {
    border-color: var(--color-error);
  }

  .article-comments__note {
    margin: 0;
    font-size: var(--font-size-small);
    opacity: 0.8;
  }

  /* Narrow cards (no design: our choice): the button gets its own full line under the fields */
  @media (max-width: 749px) {
    .article-comments__card {
      grid-template-areas:
        'avatar body body'
        'submit submit submit';
    }

    .article-comments__card:is(.is-open, :has(:is(textarea, input):focus), :has(.article-comments__textarea:not(:placeholder-shown))):not(.article-comments__card--known),
    .article-comments__card--known.is-open {
      grid-template-areas:
        'avatar body body'
        'extra extra extra'
        'submit submit submit';
    }

    .article-comments__card .article-comments__submit {
      justify-self: end;
      margin-block-start: 0;
    }
  }

  /* ---------- Comments ---------- */
  .article-comments__list {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-xl), calc(48 * var(--px, 0.0625rem)));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .article-comments__comment {
    display: flex;
    gap: max(var(--space-md), calc(21 * var(--px, 0.0625rem)));
    scroll-margin-block-start: calc(var(--header-space, 6.0625rem) + var(--space-lg));
  }

  .article-comments__comment:focus {
    outline: none;
  }

  .article-comments__body {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--space-sm);
    min-inline-size: 0;
  }

  .article-comments__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-xs) var(--space-md);
    padding-block-start: var(--space-xs);
  }

  .article-comments__author {
    margin: 0;
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
  }

  .article-comments__date {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background)); /* 60% was under 4.5:1 */
    font-size: var(--font-size-body);
  }

  .article-comments__text {
    font-size: var(--font-size-body);
    line-height: 1.4;
  }

  .article-comments__text > * {
    margin: 0;
  }

  .article-comments__text > * + * {
    margin-block-start: var(--space-sm);
  }

  .article-comments__empty {
    margin: 0;
    font-size: var(--font-size-body);
    font-style: italic;
  }

  /* ---------- Load more ---------- */
  .article-comments__more {
    display: flex;
    justify-content: center;
  }

  .article-comments__more:empty {
    display: none;
  }

  .article-comments__more-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    padding-block-end: var(--space-xs);
    border-block-end: 1px solid currentcolor;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
  }

  .article-comments__more-link svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-comments__more-link:hover svg {
      translate: 0 0.125rem;
    }
  }

  .article-comments__more-link[aria-busy='true'] {
    opacity: 0.6;
    pointer-events: none;
  }

  /* Theme editor only: comments are turned off for this blog */
  .article-comments__off {
    margin: var(--space-xl) auto;
    padding: var(--space-md);
    max-inline-size: 40rem;
    border: 1px dashed var(--color-border);
    border-radius: var(--radius-sm);
    text-align: center;
  }

  /*
    Phones (design BLOG details 390px): heading 22px, count 11px, 38px avatars, name 13px, date 11px,
    comment text 12px; compact labels on "Post comment" and "Load more comments"
  */
  @media (max-width: 749px) {
    .article-comments .article-comments__heading {
      font-size: 1.375rem;
    }

    .article-comments .article-comments__count {
      font-size: 0.6875rem;
    }

    .article-comments .article-comments__avatar {
      inline-size: 2.375rem;
      font-size: 0.6875rem;
    }

    .article-comments .article-comments__card {
      grid-template-columns: 2.375rem minmax(0, 1fr) auto;
      padding: var(--space-md);
    }

    .article-comments .article-comments__textarea {
      min-block-size: 2.375rem;
      font-size: 0.8125rem;
    }

    .article-comments .article-comments__list {
      gap: var(--space-lg);
    }

    .article-comments .article-comments__comment {
      gap: var(--space-sm);
    }

    .article-comments .article-comments__body {
      gap: var(--space-xs);
    }

    .article-comments .article-comments__meta {
      padding-block-start: 0;
    }

    .article-comments .article-comments__author {
      font-size: 0.8125rem;
    }

    .article-comments .article-comments__date {
      font-size: 0.6875rem;
    }

    .article-comments .article-comments__text,
    .article-comments .article-comments__empty {
      font-size: 0.75rem;
      line-height: 1.5;
    }

    .article-comments__card .article-comments__submit {
      min-block-size: 2.5rem;
      padding-inline: var(--space-md);
      font-size: 0.75rem;
    }

    .article-comments__card .article-comments__submit svg {
      inline-size: 0.875rem;
      block-size: 0.875rem;
    }

    .article-comments__more .article-comments__more-link {
      font-size: 0.75rem;
    }
  }

/* sections/article-hero.liquid */

  /*
    Figma 1920: card 1841 x 816 from y 190, radius ~100px; pill 49px from the top, text ~62px from
    the left, meta row 77px tall, 46px from the bottom. Sizes are Figma px x --px (screen-scale) with
    rem floors, or tokens.
  */
  /* --px: one Figma pixel, by the width only and never more than 1px (without it the 1920px sizes
     showed on phones). With "Scale with the screen" on, the rule after it also reads the height. */
  .article-hero {
    --px: min(calc(100vw / 1920), 0.0625rem);
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .article-hero.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .article-hero__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .article-hero__breadcrumb {
    margin-block-end: var(--space-xl);
  }

  /* The article title in the breadcrumb: one line, cut with … (screen readers get the full text) */
  .breadcrumb.article-hero__breadcrumb ol {
    flex-wrap: nowrap;
  }

  .breadcrumb.article-hero__breadcrumb li {
    flex: none;
  }

  .breadcrumb.article-hero__breadcrumb li[aria-current] {
    flex: 0 1 auto;
    min-inline-size: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  /* The card: the photo fills it; the text sits on a dark fade from the bottom left */
  .article-hero__card {
    position: relative;
    display: flex;
    overflow: hidden;
    min-block-size: 32rem;
    border-radius: var(--hero-radius, 100px);
    background-color: #1a1a1a;
    color: #ffffff;
    isolation: isolate;
  }

  @media (min-width: 990px) {
    .article-hero__card {
      aspect-ratio: 1841 / 816;
    }
  }

  .article-hero__media,
  .article-hero__media img {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }

  .article-hero__media {
    z-index: -1;
  }

  .article-hero__media img {
    object-fit: cover;
  }

  .article-hero__media::after {
    content: "";
    position: absolute;
    inset: 0;
    background:
      linear-gradient(to top, #000000d9 0%, #00000080 30%, transparent 60%),
      linear-gradient(to right, #00000099 0%, transparent 55%);
  }

  /* No image: a pale panel with dark text (the topic pill too: its white text was not readable) */
  .article-hero__card--no-image {
    background-color: var(--color-tint-subtle);
    color: var(--color-text);
  }

  .article-hero__card--no-image .article-hero__topic {
    color: var(--color-accent);
  }

  .article-hero__content {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: var(--space-xl);
    padding:
      max(var(--space-xl), calc(49 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(62 * var(--px, 0.0625rem)))
      max(var(--space-xl), calc(46 * var(--px, 0.0625rem)));
  }

  /* Topic pill (top left): see-through glass over the photo, white text */
  .article-hero__topic {
    align-self: flex-start;
    padding: 0.3125rem 1.0625rem; /* 5px 17px */
    border: 1px solid color-mix(in srgb, var(--color-accent) 50%, transparent);
    border-radius: var(--radius-lg); /* 50px */
    background-color: color-mix(in srgb, var(--color-accent) 15%, transparent);
    color: #ffffff;
    font-size: var(--font-size-body-lg);
    line-height: 1.3;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  /* Title and summary sit low in the card, above the meta row */
  .article-hero__text {
    margin-block-start: auto;
  }

  /* Full card width below 990px; from 990px about 60% of the card (Figma: 640px of the text area) */
  .article-hero__title {
    max-inline-size: 100%;
    margin: 0;
    color: inherit;
    font-size: var(--font-size-h1); /* 60px */
    line-height: 1.15;
  }

  /*
    The title highlight (article field "Title highlight") in the accent colour, upright. The Figma's
    dark red on a dark photo is under 3:1: to check in the M9 contrast pass.
  */
  .article-hero__title em {
    color: var(--color-accent);
    font-style: normal;
  }

  @media (min-width: 990px) {
    .article-hero__title {
      max-inline-size: 60%;
    }
  }

  .article-hero__summary {
    max-inline-size: 100%;
    margin: var(--space-lg) 0 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.5;
    opacity: 0.9;
  }

  @media (min-width: 990px) {
    .article-hero__summary {
      max-inline-size: 70%;
    }
  }

  /* Author on the left, date and read time in the middle, Share on the far right */
  .article-hero__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-md) max(var(--space-xl), calc(72 * var(--px, 0.0625rem)));
  }

  .article-hero__author {
    display: inline-flex;
    align-items: center;
    gap: var(--space-md);
    font-size: var(--font-size-body);
  }

  /* The author-avatar snippet; two classes, because its own size and colors come later in the CSS file */
  .author-avatar.article-hero__avatar {
    inline-size: max(3.5rem, calc(77 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-accent) 15%, #ffffff);
    color: var(--color-accent);
    font-size: var(--font-size-body);
  }

  .article-hero__facts {
    display: inline-flex;
    flex-wrap: wrap;
    gap: var(--space-sm) max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  .article-hero__fact {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    font-size: var(--font-size-body);
  }

  .article-hero__fact svg {
    flex: none;
    inline-size: 1.25rem;
    block-size: auto;
  }

  /*
    Button and pill share one grid cell, right-aligned, so the pill appears exactly where the button
    was. Only on devices with a real hover (mouse): there the pill shows on hover or when the keyboard
    reaches the button; the button fades out but stays focusable underneath.
  */
  .article-hero__share {
    display: grid;
    align-items: center;
    justify-items: end;
    margin-inline-start: auto;
  }

  .article-hero__share > * {
    grid-area: 1 / 1;
  }

  .article-hero__share-button {
    min-block-size: 3.125rem; /* 50px, the same height as the pill */
  }

  .article-hero__share-button svg {
    flex: none;
    inline-size: 1.1em;
    block-size: auto;
  }

  /*
    The pill waits invisible on top of the button. pointer-events: none lets clicks reach the button
    under it; it stays in the keyboard order (no visibility: hidden), so Tab goes button → icons.
  */
  .article-hero__share .share-links {
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  .article-hero__share-main {
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  /*
    The pill's icons rise from below and fade in, one after another (60ms apart), when the pill opens.
    Only with motion allowed; otherwise they simply appear with the pill.
  */
  @media (prefers-reduced-motion: no-preference) {
    .article-hero__share .share-links__list > li {
      opacity: 0;
      translate: 0 0.75rem;
      transition:
        opacity var(--duration-base) var(--ease-out),
        translate var(--duration-base) var(--ease-out);
    }

    .article-hero__share .share-links__list > li:nth-child(2) {
      transition-delay: 60ms;
    }

    .article-hero__share .share-links__list > li:nth-child(3) {
      transition-delay: 120ms;
    }

    .article-hero__share .share-links__list > li:nth-child(4) {
      transition-delay: 180ms;
    }

    .article-hero__share .share-links__list > li:nth-child(5) {
      transition-delay: 240ms;
    }
  }

  /*
    Open: after a click / tap on the button (is-open, set by the script below), on mouse hover
    (devices that have one), or when the keyboard is on one of the icons. Not while the keyboard is
    on the button itself: then the button and its focus ring stay visible.
  */
  .article-hero__share.is-open .share-links,
  .article-hero__share .share-links:focus-within {
    opacity: 1;
    pointer-events: auto;
  }

  .article-hero__share.is-open .share-links__list > li,
  .article-hero__share .share-links:focus-within .share-links__list > li {
    opacity: 1;
    translate: 0 0;
  }

  .article-hero__share.is-open .article-hero__share-main,
  .article-hero__share:has(.share-links:focus-within) .article-hero__share-main {
    opacity: 0;
    pointer-events: none;
  }

  @media (hover: hover) {
    .article-hero__share:hover .share-links {
      opacity: 1;
      pointer-events: auto;
    }

    .article-hero__share:hover .share-links__list > li {
      opacity: 1;
      translate: 0 0;
    }

    .article-hero__share:hover .article-hero__share-main {
      opacity: 0;
      pointer-events: none;
    }
  }
  /*
    Phones (design BLOG details): a smaller card. Corners 16px or less (100px made the card a pill), a
    lower minimum height, smaller text; date and read time beside the author, Share on its own row at
    the end. Two classes, so these win over the screen-scale sizes.
  */
  @media (max-width: 749px) {
    .article-hero .article-hero__card {
      min-block-size: 24rem;
      border-radius: min(var(--hero-radius, 1rem), 1rem);
    }

    .article-hero .article-hero__content {
      gap: var(--space-md);
      padding: var(--space-md);
    }

    .article-hero .article-hero__topic {
      padding: 0.1875rem 0.75rem;
      font-size: 0.8125rem;
    }

    .article-hero .article-hero__title {
      font-size: 1.625rem;
    }

    .article-hero .article-hero__summary {
      margin-block-start: var(--space-sm);
      font-size: 0.8125rem;
    }

    .article-hero .article-hero__meta {
      gap: var(--space-sm) var(--space-md);
    }

    .article-hero .article-hero__author {
      gap: var(--space-sm);
      font-size: 0.875rem;
    }

    .article-hero .author-avatar.article-hero__avatar {
      inline-size: 2.5rem;
      font-size: 0.75rem;
    }

    .article-hero .article-hero__facts {
      gap: var(--space-xs) var(--space-md);
    }

    .article-hero .article-hero__fact {
      gap: 0.375rem;
      font-size: 0.8125rem;
    }

    .article-hero .article-hero__fact svg {
      inline-size: 1rem;
    }

    .article-hero .article-hero__share {
      flex-basis: 100%;
    }

    .article-hero .article-hero__share-button {
      min-block-size: 2.5rem;
      font-size: 0.75rem;
    }
  }

/* sections/article-related.liquid */

  /*
    Figma 1920: eyebrow, then the heading row ("More from the Journal" 40px; "VIEW ALL ARTICLES →"
    at the text column's right edge), cards 484 x 406, 34px apart, 68px under the heading.
    Sizes are Figma px x --px (screen-scale) with rem floors, or tokens.
  */
  /* --px: one Figma pixel, by the width only and never more than 1px (without it the 1920px sizes
     showed on phones). With "Scale with the screen" on, the rule after it also reads the height. */
  .article-related {
    --px: min(calc(100vw / 1920), 0.0625rem);
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .article-related.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .article-related__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* From 1200px: the article section's columns (text 1114 / gap 171 / sidebar 354), content under the text */
  @media (min-width: 1200px) {
    .article-related--aligned .article-related__inner {
      display: grid;
      grid-template-columns: minmax(0, 1114fr) minmax(var(--space-2xl), 171fr) minmax(17rem, 354fr);
    }
  }

  .article-related__content {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-xl), calc(68 * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  .article-related__header {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-lg), calc(42 * var(--px, 0.0625rem)));
  }

  .article-related__eyebrow {
    margin: 0;
  }

  .article-related__title-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md) var(--space-xl);
  }

  .article-related__heading {
    margin: 0;
    font-size: var(--font-size-h2);
    line-height: 1.25;
  }

  /* "More from the *Journal*": the italic word in the accent colour, upright */
  .article-related__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* "VIEW ALL ARTICLES →": accent label with an underline (Figma) */
  .article-related__view-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    padding-block-end: var(--space-xs);
    border-block-end: 1px solid currentcolor;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
  }

  .article-related__view-all-arrow svg {
    display: block;
    inline-size: 1.1em;
    block-size: auto;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  @media (prefers-reduced-motion: no-preference) {
    .article-related__view-all:hover .article-related__view-all-arrow svg {
      translate: 0.25em 0;
    }
  }

  .article-related__reveal {
    display: block;
  }

  /*
    Cards at most 484px wide (Figma) and at least 20rem; as many per row as fit, left-aligned, so
    2 cards sit side by side under the text as in the Figma and wrap on narrow screens.
  */
  .article-related__grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(100%, 20rem), max(20rem, calc(484 * var(--px, 0.0625rem)))));
    gap: max(var(--space-lg), calc(34 * var(--px, 0.0625rem)));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .article-related__item {
    display: flex;
  }

  .article-related__item > * {
    flex: 1;
  }

  /* Theme editor only: no other articles to show */
  .article-related__empty {
    margin: var(--space-xl) auto;
    padding: var(--space-md);
    max-inline-size: 40rem;
    border: 1px dashed var(--color-border);
    border-radius: var(--radius-sm);
    text-align: center;
  }

  /* Phones: a smaller heading and "View all articles" link */
  @media (max-width: 749px) {
    .article-related .article-related__heading {
      font-size: 1.375rem;
    }

    .article-related .article-related__view-all {
      font-size: 0.75rem;
    }
  }

  /*
    Phones from 375px (design BLOG details): 2 compact cards per row, the same card as the Article list
    (sections/blog.liquid): short photo box, 3-line title, small author + read time. Below 375px: one
    card per row in the normal sizes. Three classes, so these win over the card snippet's own rules.
  */
  @media (min-width: 375px) and (max-width: 749px) {
    .article-related .article-related__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: var(--space-sm);
    }

    .article-related .article-related__item .article-card {
      gap: 0.625rem;
      padding: var(--space-xs);
      border-radius: var(--space-sm);
    }

    .article-related .article-card .article-card__media {
      block-size: auto;
      aspect-ratio: 1.43 / 1;
      border-radius: var(--space-xs);
    }

    .article-related .article-card .article-card__media img,
    .article-related .article-card .article-card__placeholder {
      position: absolute;
      inset: 0;
    }

    .article-related .article-card .article-card__topic {
      inset: 0.375rem auto auto 0.375rem;
      font-size: 0.6875rem;
    }

    .article-related .article-card .article-card__body {
      gap: var(--space-xs);
    }

    .article-related .article-card .article-card__title {
      -webkit-line-clamp: 3;
      line-clamp: 3;
      font-size: 0.9375rem;
    }

    .article-related .article-card .article-card__meta {
      gap: 0.25rem var(--space-xs);
      font-size: 0.625rem;
    }

    .article-related .article-card .article-card__author {
      gap: 0.375rem;
    }

    .article-related .article-card .article-card__avatar {
      inline-size: 1.125rem;
      font-size: 0.4375rem;
    }

    .article-related .article-card .article-card__facts {
      gap: 0.25rem var(--space-xs);
    }

    .article-related .article-card .article-card__fact {
      gap: 0.25rem;
      font-size: 0.625rem;
    }

    .article-related .article-card .article-card__fact svg {
      inline-size: 0.75rem;
    }
  }

/* sections/article.liquid */

  /*
    Figma 1920: text column 1114 wide, sidebar 354 wide, 171px after the text (the Figma's extra 174px
    on the left is left out, so the text lines up with the other sections). Sizes are Figma px x --px
    (screen-scale) with rem floors, or tokens.
  */
  /* --px: one Figma pixel, by the width only and never more than 1px (without it the 1920px sizes
     showed on phones). With "Scale with the screen" on, the rule after it also reads the height. */
  .article {
    --px: min(calc(100vw / 1920), 0.0625rem);
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .article.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .article__layout {
    display: grid;
    gap: var(--space-2xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .article__main {
    min-inline-size: 0;
  }

  .article__side,
  .article__top {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-xl), calc(40 * var(--px, 0.0625rem)));
  }

  /*
    Below 1200px (phone design, also tablets): author, contents, tags and share sit after the lead
    (.article__top); the sidebar shows only its product cards, under the text, and only when the
    product rows are not in the text (.article__side--narrow).
  */
  .article__top {
    margin-block: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  .article__side:not(.article__side--narrow),
  .article__side > :not(.article__side-products) {
    display: none;
  }

  /*
    Beside each other from 1200px, filling the section's content box edge to edge like every other
    section (so the text lines up with the hero card and the breadcrumb). Every part is a share (fr)
    of that box, so the Figma proportions hold at any "Section width": text 1114, gap 171, sidebar 354
    (at least 17rem). The gap is its own empty column, so it shrinks with the box (never under 48px).
  */
  @media (min-width: 1200px) {
    .article__layout {
      grid-template-columns: minmax(0, 1114fr) minmax(var(--space-2xl), 171fr) minmax(17rem, 354fr);
      column-gap: 0;
    }

    .article__main {
      grid-column: 1;
    }

    .article__side,
    .article__side:not(.article__side--narrow) {
      display: flex;
      grid-column: 3;
    }

    .article__side > :not(.article__side-products) {
      display: block;
    }

    .article__top {
      display: none;
    }

    /*
      Sticky sidebar. It's often taller than the screen, so it doesn't stick at the top (its end
      would never be seen): it scrolls with the page until its bottom is in view, then stays there.
      The script below measures it into --side-height; when it's shorter than the screen it simply
      sticks under the header. Without the script it sticks under the header.
    */
    .article__layout--sticky .article__side {
      position: sticky;
      inset-block-start: min(
        calc(var(--header-space, 6.0625rem) + var(--space-lg)),
        calc(100svh - var(--side-height, 0px) - var(--space-lg))
      );
      align-self: start;
    }
  }

  /* Small uppercase accent labels ("IN THIS ARTICLE", "TAGS", "SHARE") */
  .article__label {
    margin: 0 0 var(--space-md);
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    line-height: var(--line-height-heading);
    text-transform: uppercase;
  }

  /* ---------- The article text ---------- */

  .article-body {
    font-size: var(--font-size-body-sm); /* 18px */
    line-height: 1.85;
  }

  /* Anchor jumps land below the sticky header */
  .article-body h2 {
    scroll-margin-block-start: calc(var(--header-space, 6.0625rem) + var(--space-xl));
  }

  @media (prefers-reduced-motion: no-preference) {
    html:has(.article__layout) {
      scroll-behavior: smooth;
    }
  }

  .article-body.rte > * + * {
    margin-block-start: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  .article-body strong {
    font-weight: 600;
  }

  /*
    The text after the lead is a second .article-body (the top block sits between them below 1200px).
    Its first part gets the space it had after the lead; headings keep their own bigger space.
  */
  .article-body.article-body--after-lead > :first-child:not(h1, h2, h3, h4, h5, h6, .article-body__eyebrow) {
    margin-block-start: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  /* Lead: the first paragraph, italic and bigger, with a 2px accent rule on its left */
  .article-body--lead > p {
    padding-inline-start: max(var(--space-lg), calc(36 * var(--px, 0.0625rem)));
    border-inline-start: 2px solid var(--color-accent);
    font-size: var(--font-size-body-lg); /* 22px */
    font-style: italic;
    line-height: 1.75;
  }

  /* Section heading: 40px heading font; an italic word turns upright and accent */
  .article-body.rte > h2 {
    margin-block-start: max(var(--space-3xl), calc(110 * var(--px, 0.0625rem)));
    font-size: var(--font-size-h2);
    line-height: 1.25;
  }

  .article-body h2 em {
    color: var(--color-accent);
    font-style: normal;
  }

  .article-body.rte > :is(h2, h3, h4) + * {
    margin-block-start: max(var(--space-md), calc(28 * var(--px, 0.0625rem)));
  }

  /* Eyebrow: a Heading 6 right above an H2 (a <p class="h6"> after the Liquid pass), with the theme's 66px accent rule before it */
  .article-body.rte > .article-body__eyebrow {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    margin-block-start: max(var(--space-3xl), calc(110 * var(--px, 0.0625rem)));
    color: var(--color-accent);
  }

  .article-body > .article-body__eyebrow::before {
    content: "";
    flex: none;
    inline-size: 4.125rem; /* 66px */
    block-size: 2px;
    background-color: currentcolor;
  }

  .article-body.rte > .article-body__eyebrow + h2 {
    margin-block-start: max(var(--space-sm), calc(18 * var(--px, 0.0625rem)));
  }

  /*
    Quote card (Figma: 1114 x 244, the accent at 3% on white, 1px border, radius 25, pale quote mark
    top left, italic 24px text, accent attribution). Two classes: the theme's .rte blockquote (left
    rule, heading font) must lose.
  */
  .article-body.rte blockquote {
    position: relative;
    margin-inline: 0;
    padding:
      max(var(--space-xl), calc(42 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(40 * var(--px, 0.0625rem)))
      max(var(--space-lg), calc(36 * var(--px, 0.0625rem)))
      max(var(--space-2xl), calc(74 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-accent) 3%, var(--color-background));
    box-shadow: var(--shadow-card);
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-lg);
    font-style: italic;
    line-height: 1.6;
  }

  .article-body blockquote > * {
    margin: 0;
  }

  .article-body blockquote > * + * {
    margin-block-start: var(--space-md);
  }

  /* The quote mark: the theme's quote icon as a mask, filled with a pale accent */
  .article-body blockquote::before {
    content: "";
    position: absolute;
    inset-block-start: max(var(--space-sm), calc(12 * var(--px, 0.0625rem)));
    inset-inline-start: max(var(--space-md), calc(26 * var(--px, 0.0625rem)));
    inline-size: max(2.5rem, calc(52 * var(--px, 0.0625rem)));
    aspect-ratio: 125 / 78;
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
    -webkit-mask: var(--icon-quote) center / contain no-repeat;
    mask: var(--icon-quote) center / contain no-repeat;
  }

  .article-body blockquote .article-body__cite {
    color: var(--color-accent);
    font-size: var(--font-size-body);
    font-style: normal;
  }

  /*
    Tips box: a quote with a bullet list inside (Figma 1116 x 415, the theme's card colours). The
    first line is its title, in the accent colour after a sparkle; the list is upright body text.
  */
  .article-body.rte blockquote:has(ul) {
    padding: max(var(--space-lg), calc(36 * var(--px, 0.0625rem)));
    background-color: var(--color-card);
    font-size: var(--font-size-body-sm);
    font-style: normal;
    line-height: 1.8;
  }

  .article-body blockquote:has(ul)::before {
    content: none;
  }

  .article-body blockquote:has(ul) > :first-child:not(ul) {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
  }

  .article-body blockquote:has(ul) > :first-child:not(ul)::before {
    content: "";
    flex: none;
    inline-size: 1.25rem;
    aspect-ratio: 1;
    background-color: currentcolor;
    -webkit-mask: var(--icon-tips) center / contain no-repeat;
    mask: var(--icon-tips) center / contain no-repeat;
  }

  .article-body blockquote ul {
    padding-inline-start: 1.25em;
  }

  .article-body blockquote li::marker {
    color: var(--color-text);
  }

  /* "The edit": the product rows at the [products] line, 20px apart (Figma) */
  .article-body.rte .article-edit {
    display: grid;
    gap: max(var(--space-md), calc(20 * var(--px, 0.0625rem)));
    padding: 0;
    list-style: none;
  }

  .article-body.rte .article-edit > li {
    margin: 0;
  }

  /* Images: full width, rounded (Figma 1114 x 548, radius ~40) */
  .article-body img {
    display: block;
    inline-size: 100%;
    max-inline-size: 100%;
    block-size: auto;
    border-radius: max(var(--radius-sm), calc(40 * var(--px, 0.0625rem)));
  }

  /*
    Caption: an all-italic paragraph right after an image is moved up onto the image's bottom edge,
    white on a dark fade (no wrapper needed, so it works whatever the editor wraps the image in).
    It moves up by its own height, which leaves that much room under the image before the next part.
  */
  .article-body :is(p:has(> img), img) + p:has(> em:only-child) {
    position: relative;
    z-index: 1;
    margin-block-start: 0;
    padding: var(--space-2xl) max(var(--space-md), calc(20 * var(--px, 0.0625rem))) var(--space-md);
    border-radius: 0 0 max(var(--radius-sm), calc(40 * var(--px, 0.0625rem))) max(var(--radius-sm), calc(40 * var(--px, 0.0625rem)));
    background: linear-gradient(to top, #000000b3, transparent);
    color: #ffffff;
    font-size: var(--font-size-small);
    line-height: 1.5;
    translate: 0 -100%;
  }

  .article-body :is(p:has(> img), img) + p:has(> em:only-child) + * {
    margin-block-start: 0;
  }

  /*
    Steps 01–05: a numbered list whose items start with a bold word (the pill), then the title (the
    Liquid pass wraps it) and the text. The number is a big pale counter on the left.
  */
  .article-body ol:has(> li > .article-body__step-title) {
    padding: 0;
    list-style: none;
    counter-reset: article-step;
  }

  .article-body ol:has(> li > .article-body__step-title) > li {
    position: relative;
    padding-inline-start: max(4rem, calc(76 * var(--px, 0.0625rem)));
    counter-increment: article-step;
  }

  .article-body ol:has(> li > .article-body__step-title) > li + li {
    margin-block-start: max(var(--space-xl), calc(48 * var(--px, 0.0625rem)));
  }

  .article-body ol:has(> li > .article-body__step-title) > li::before {
    content: counter(article-step, decimal-leading-zero);
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: 0;
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-family: var(--font-heading--family);
    font-size: max(2.5rem, calc(58 * var(--px, 0.0625rem)));
    line-height: 1;
  }

  .article-body ol:has(> li > .article-body__step-title) > li > strong:first-child {
    display: inline-block;
    padding: 0.15em 0.9em;
    border: 1px solid color-mix(in srgb, var(--color-accent) 45%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-tint);
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    line-height: 1.6;
  }

  .article-body__step-title {
    display: block;
    margin-block: var(--space-sm) var(--space-xs);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-h3); /* 26px */
    line-height: 1.3;
  }

  /* ---------- Under the text ---------- */

  .article__share-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-lg);
    margin-block-start: max(var(--space-2xl), calc(60 * var(--px, 0.0625rem)));
  }

  .article__share-row .article__label {
    margin: 0;
  }

  /* Author bio card (Figma 1116 x 319): avatar 77, name, bio */
  .article__bio-card {
    display: flex;
    align-items: flex-start;
    gap: max(var(--space-lg), calc(32 * var(--px, 0.0625rem)));
    margin-block-start: max(var(--space-xl), calc(48 * var(--px, 0.0625rem)));
    padding: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-background);
    box-shadow: var(--shadow-card);
  }

  /* Two classes: the author-avatar snippet's own size (4rem) comes later in the CSS file */
  .author-avatar.article__bio-avatar {
    inline-size: max(3.5rem, calc(77 * var(--px, 0.0625rem)));
  }

  .article__bio-name {
    margin: 0;
    font-size: var(--font-size-body-lg);
    font-weight: var(--font-weight-medium);
  }

  .article__bio {
    max-inline-size: 45rem;
    margin: var(--space-sm) 0 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.7;
  }

  /* ---------- Sidebar ---------- */

  /* Author card (Figma 354 x 338): avatar 64 + name, then the bio */
  .article__author-card {
    padding: max(var(--space-lg), calc(28 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-background);
    box-shadow: var(--shadow-card);
  }

  .article__author {
    display: flex;
    align-items: center;
    gap: var(--space-md);
  }

  .author-avatar.article__author-avatar {
    inline-size: max(3.25rem, calc(64 * var(--px, 0.0625rem)));
  }

  .article__author-name {
    margin: 0;
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
  }

  .article__author-bio {
    margin: var(--space-md) 0 0;
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  /* "In this article": 01–06 pale numbers + the heading links; the current one turns accent */
  .article__contents {
    display: grid;
    gap: var(--space-sm);
    margin: 0;
    padding: 0;
    list-style: none;
    counter-reset: article-contents;
  }

  .article__contents li {
    display: flex;
    gap: var(--space-md);
    align-items: baseline;
    counter-increment: article-contents;
  }

  .article__contents li::before {
    content: counter(article-contents, decimal-leading-zero);
    flex: none;
    min-inline-size: 1.5em;
    color: color-mix(in srgb, var(--color-accent) 45%, transparent);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-small);
  }

  .article__contents a {
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
    line-height: 1.4;
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .article__contents a:hover,
  .article__contents a[aria-current] {
    color: var(--color-accent);
  }

  .article__products {
    display: grid;
    gap: var(--space-lg);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Tablets: the two product cards side by side under the text */
  @media (min-width: 750px) and (max-width: 1199px) {
    .article__products {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  /* Tags: outlined chips that open the blog filtered to that tag */
  .article__tags {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .article__tag {
    display: inline-flex;
    align-items: center;
    min-block-size: 2.5rem; /* 41px, Figma */
    padding-inline: var(--space-md);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
    text-decoration: none;
    transition:
      color var(--duration-fast) var(--ease-out),
      border-color var(--duration-fast) var(--ease-out);
  }

  .article__tag:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  /*
    Phones (< 750px, design BLOG details 390px): 13px text, 22px headings, a compact quote card, tips
    box, steps (a small number beside the pill), author card and tag chips; 24px image corners.
    Two classes where the rules above have two.
  */
  @media (max-width: 749px) {
    .article-body {
      font-size: 0.8125rem;
      line-height: 1.7;
    }

    .article-body--lead > p {
      padding-inline-start: var(--space-md);
      font-size: 0.875rem;
      line-height: 1.65;
    }

    .article-body.rte > h2 {
      font-size: 1.375rem;
    }

    .article-body.rte > .article-body__eyebrow {
      gap: var(--space-sm);
      font-size: 0.75rem;
    }

    .article-body > .article-body__eyebrow::before {
      inline-size: 2rem;
    }

    .article-body.rte blockquote {
      margin-inline: var(--space-sm);
      padding: 2rem var(--space-md) var(--space-md);
      font-size: 0.75rem;
      line-height: 1.55;
    }

    .article-body blockquote::before {
      inset-block-start: var(--space-xs);
      inset-inline-start: var(--space-md);
      inline-size: 1.25rem;
    }

    .article-body blockquote .article-body__cite {
      font-size: 0.6875rem;
    }

    .article-body.rte blockquote:has(ul) {
      margin-inline: 0;
      padding: var(--space-md);
      font-size: 0.75rem;
      line-height: 1.6;
    }

    .article-body blockquote:has(ul) > :first-child:not(ul) {
      font-size: 0.875rem;
    }

    .article-body blockquote:has(ul) > :first-child:not(ul)::before {
      inline-size: 1rem;
    }

    .article-body img {
      border-radius: 1.5rem;
    }

    .article-body :is(p:has(> img), img) + p:has(> em:only-child) {
      padding: var(--space-xl) var(--space-sm) var(--space-sm);
      border-radius: 0 0 1.5rem 1.5rem;
      font-size: 0.6875rem;
    }

    .article-body ol:has(> li > .article-body__step-title) > li {
      padding-inline-start: 1.5rem;
      font-size: 0.75rem;
    }

    .article-body ol:has(> li > .article-body__step-title) > li + li {
      margin-block-start: var(--space-lg);
    }

    .article-body ol:has(> li > .article-body__step-title) > li::before {
      inset-block-start: 0.2em;
      font-size: 0.875rem;
    }

    .article-body ol:has(> li > .article-body__step-title) > li > strong:first-child {
      font-size: 0.6875rem;
    }

    .article-body__step-title {
      font-size: 0.875rem;
    }

    .article__top,
    .article__side {
      gap: var(--space-xl);
    }

    .article__author-card {
      padding: var(--space-md);
    }

    .author-avatar.article__author-avatar,
    .author-avatar.article__bio-avatar {
      inline-size: 2.5rem;
      font-size: var(--font-size-small);
    }

    .article__author-name,
    .article__bio-name {
      font-size: 0.8125rem;
    }

    .article__author-bio,
    .article__bio {
      font-size: 0.75rem;
    }

    .article__label {
      font-size: 0.75rem;
    }

    .article__contents a {
      font-size: 0.8125rem;
    }

    .article__contents li::before {
      font-size: 0.6875rem;
    }

    .article__tag {
      min-block-size: 1.75rem;
      padding-inline: 0.625rem;
      font-size: 0.6875rem;
    }

    .article__bio-card {
      gap: var(--space-md);
      padding: var(--space-md);
    }
  }

/* sections/blog-hero.liquid */

  /*
    Figma 1920 frame: text column x 49-590 (541px), collage x 745-1797 (1052 x 634, from y 257),
    155px apart. Phone frame (375px): centred intro, cards 2 per row. Sizes are tokens or Figma px x
    --px (screen-scale), with the Figma px in comments.
  */
  .blog-hero {
    position: relative;
    overflow: hidden;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /*
    Soft rose glows behind everything, at the Figma's seven spots (% of the 1920 x 1031 frame): five
    small ones under and between the cards, two big ones at the top-right and bottom-right corners.
  */
  .blog-hero::before {
    --glow: color-mix(in srgb, var(--color-accent) 6%, transparent);
    --glow-big: color-mix(in srgb, var(--color-accent) 7%, transparent);
    content: "";
    position: absolute;
    inset: 0;
    z-index: 0;
    background:
      radial-gradient(circle 9rem at 37.5% 19.7%, var(--glow), transparent),
      radial-gradient(circle 9rem at 56% 39%, var(--glow), transparent),
      radial-gradient(circle 9rem at 67% 25%, var(--glow), transparent),
      radial-gradient(circle 9rem at 70% 54.6%, var(--glow), transparent),
      radial-gradient(circle 9rem at 50% 71.5%, var(--glow), transparent),
      radial-gradient(circle 16rem at 92% 22%, var(--glow-big), transparent),
      radial-gradient(circle 16rem at 91.7% 89.5%, var(--glow-big), transparent);
    pointer-events: none;
  }

  .blog-hero__inner {
    position: relative;
    z-index: 1;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .blog-hero__breadcrumb {
    margin-block-end: var(--space-2xl); /* breadcrumb → eyebrow: ~65px (phones ~30px) */
  }

  /* Below 1440px (the phone design): the centred intro, then the cards */
  .blog-hero__grid {
    display: grid;
    gap: var(--space-2xl);
    align-items: center;
  }

  /* ---------- Intro ---------- */
  .blog-hero__intro {
    text-align: center;
  }

  /* A rule on both sides of the label (Figma "—— BEAUTY INTELLIGENCE ——"); the rules get shorter
     before the label goes onto two lines */
  .blog-hero__eyebrow {
    justify-content: center;
  }

  /* The rules start at 0 and take only the free space (66px at most), so the label keeps its line */
  .blog-hero__eyebrow::before,
  .blog-hero__eyebrow::after {
    content: "";
    flex: 1 1 0;
    min-inline-size: 1rem;
    max-inline-size: 66px;
    inline-size: auto;
    block-size: 2px;
    background-color: currentcolor;
  }

  .blog-hero__heading {
    margin-block-start: var(--space-xl); /* eyebrow → H1: ~41px */
  }

  /* The red second line: made italic in the editor, shown upright, on its own line */
  .blog-hero__heading em {
    display: block;
    font-style: normal;
    color: var(--color-accent);
  }

  .blog-hero__text {
    /* 550 Figma px, but never narrower than 34rem: on a small screen --px is tiny (500px wide = 0.26) */
    max-inline-size: max(34.375rem, calc(550 * var(--px, 0.0625rem)));
    margin: var(--space-2xl) auto 0; /* ~58px */
    font-size: var(--font-size-body-sm); /* 18px */
    line-height: 1.6; /* 29px lines */
  }

  .blog-hero__text p + p {
    margin-block-start: var(--space-xl); /* ~37px between the two paragraphs */
  }

  /* Counters: one row of equal columns, number on top, label under it (the <dt> label comes first
     in the HTML for screen readers) */
  .blog-hero__counters {
    display: grid;
    grid-template-columns: repeat(var(--counters, 3), minmax(0, 1fr));
    gap: var(--space-md);
    max-inline-size: 36rem;
    margin: var(--space-2xl) auto 0;
  }

  .blog-hero__counter {
    display: flex;
    flex-direction: column-reverse;
    align-items: center;
  }

  .blog-hero__counter dd {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: max(2.5rem, calc(56 * var(--px, 0.0625rem)));
    font-variant-numeric: oldstyle-nums;
    line-height: 1.1;
  }

  .blog-hero__counter dt {
    margin-block-start: var(--space-md);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* ---------- Cards ---------- */

  /*
    The zig-zag at all sizes: 2 columns, the 2nd card lower, the 2nd row moved to the inline end
    (Figma desktop: cards at (0, 0), (49.9%, 7.7%), (16.2%, 56%), (66.5%, 69.7%), 33.7% wide; phones
    the same shape, smaller). In normal flow, so a taller card (long text, Text size) pushes the next
    row down and never covers it. Sizes in cqi = % of the collage width.
  */
  .blog-hero__collage {
    position: relative;
    container: blog-hero-cards / inline-size;
    inline-size: 100%;
    max-inline-size: 48rem;
    margin-inline: auto;
  }

  .blog-hero__cards {
    --cards-gap: 4cqi; /* phones: 14px of 343 */
    --cards-shift: 4.5cqi; /* row 2 moves 16px to the end */
    --cards-drop: min(10cqi, 3.5rem); /* card 2: 35px lower */
    --cards-drop-2: 1.5cqi; /* card 4: 5px lower than card 3 */
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: start;
    column-gap: var(--cards-gap);
    row-gap: 4.5cqi;
    margin-block-end: 8cqi; /* room for the award outline under the cards */
    padding-inline-end: var(--cards-shift);
  }

  .blog-hero__cards > :nth-child(2) {
    margin-block-start: var(--cards-drop);
  }

  .blog-hero__cards > :nth-child(4) {
    margin-block-start: var(--cards-drop-2);
  }

  /* The card block is position: relative, so this only moves it */
  .blog-hero__cards > :nth-child(n + 3) {
    inset-inline-start: var(--cards-shift);
  }

  /* Faded outline icons behind the cards (phones: book at the left between the rows, award under
     the last card) */
  .blog-hero__deco {
    position: absolute;
    display: block;
    color: var(--color-accent);
    pointer-events: none;
  }

  .blog-hero__deco svg {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  .blog-hero__deco--book {
    inset-block-start: 45%;
    inset-inline-start: -2.5%;
    inline-size: 11cqi;
  }

  .blog-hero__deco--award {
    inset-block-start: calc(100% - 9cqi);
    inset-inline-start: 70%;
    inline-size: 8cqi;
  }

  .blog-hero__deco--heart {
    display: none;
  }

  @media (max-width: 749px) {
    .blog-hero__breadcrumb {
      margin-block-end: var(--space-xl);
    }

    .blog-hero__heading {
      margin-block-start: var(--space-lg);
    }

    .blog-hero__text {
      margin-block-start: var(--space-lg);
    }

    .blog-hero__counters {
      gap: var(--space-xs);
      margin-block-start: var(--space-xl);
    }

    .blog-hero__counter dd {
      font-size: 1.875rem; /* ~30px */
    }

    .blog-hero__counter dt {
      margin-block-start: var(--space-sm);
      font-size: 0.75rem;
    }
  }

  /* From 1440px with cards: the Figma desktop, intro left and cards right */
  @media (min-width: 1440px) {
    .blog-hero__grid--split {
      /* The text column keeps 28rem, so the H1 stays on two lines */
      grid-template-columns: minmax(min(28rem, 100%), 541fr) minmax(0, 1052fr);
      column-gap: calc(155 * var(--px, 0.0625rem));
    }

    .blog-hero__grid--split .blog-hero__intro {
      text-align: start;
    }

    .blog-hero__grid--split .blog-hero__eyebrow {
      justify-content: flex-start;
    }

    .blog-hero__grid--split .blog-hero__eyebrow::before,
    .blog-hero__grid--split .blog-hero__eyebrow::after {
      flex: none;
      inline-size: 66px;
      max-inline-size: none;
    }

    .blog-hero__grid--split .blog-hero__text {
      margin-inline: 0;
    }

    /* Counters: from the left edge, spread over the text column (Figma x 49 / 271 / 491 in 541px) */
    .blog-hero__grid--split .blog-hero__counters {
      grid-template-columns: repeat(var(--counters, 3), auto);
      justify-content: space-between;
      gap: var(--space-xl);
      margin: max(var(--space-2xl), calc(100 * var(--px, 0.0625rem))) 0 0;
    }

    .blog-hero__grid--split .blog-hero__counter {
      align-items: flex-start;
    }

    .blog-hero__grid--split .blog-hero__collage {
      max-inline-size: none;
    }

    .blog-hero__grid--split .blog-hero__cards {
      --cards-gap: 16.2cqi;
      --cards-shift: 16.2cqi;
      --cards-drop: 4.6cqi; /* 49px of 1052 */
      --cards-drop-2: 8.3cqi; /* 87px */
      row-gap: 10.5cqi; /* 111px */
      margin-block-end: 0;
    }

    /* Book 97 x 78 at (5, 240), award 63 x 83 at (623, 565) in the collage (Figma); the heart
       isn't in the final frame, so it fills the empty space beside the second card */
    .blog-hero__grid--split .blog-hero__deco--book {
      inset-block-start: 37.9%;
      inset-inline-start: 0.5%;
      inline-size: 9.2cqi;
    }

    .blog-hero__grid--split .blog-hero__deco--award {
      inset-block-start: 89.1%;
      inset-inline-start: 59.2%;
      inline-size: 6cqi;
    }

    .blog-hero__grid--split .blog-hero__deco--heart {
      display: block;
      inset-block-start: 24%;
      inset-inline-start: 89%;
      inline-size: 7.7cqi;
    }
  }

  /* Slow float and breathing: looping movements, so only with "Reveal sections on scroll" on
     (.motion-on) and when the visitor allows motion */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .blog-hero--float .blog-hero__cards > * {
      animation: blog-hero-float 7s ease-in-out infinite;
    }

    .motion-on .blog-hero--float .blog-hero__cards > :nth-child(2) {
      animation-duration: 8s;
      animation-delay: -2s;
    }

    .motion-on .blog-hero--float .blog-hero__cards > :nth-child(3) {
      animation-duration: 6.5s;
      animation-delay: -4s;
    }

    .motion-on .blog-hero--float .blog-hero__cards > :nth-child(4) {
      animation-duration: 7.5s;
      animation-delay: -1s;
    }

    .motion-on .blog-hero__deco {
      animation: blog-hero-breathe 5s ease-in-out infinite;
    }

    .motion-on .blog-hero__deco--award {
      animation-duration: 6s;
      animation-delay: -2s;
    }

    .motion-on .blog-hero__deco--heart {
      animation-duration: 5.5s;
      animation-delay: -3.5s;
    }
  }

  /* Breathing: grows a little and gets a touch stronger, then back */
  /* Pause button for the float and breathing (snippets/motion-pause.liquid): bottom corner of the collage */
  .blog-hero__pause {
    position: absolute;
    inset-block-end: -1rem; /* phones: clear of the last row of cards (card 3 ends ~11px above the collage's end) */
    inset-inline-start: 0;
    z-index: 2;
  }

  @keyframes blog-hero-breathe {
    0%,
    100% {
      scale: 1;
      opacity: 0.75;
    }

    50% {
      scale: 1.08;
      opacity: 1;
    }
  }

  @keyframes blog-hero-float {
    0%,
    100% {
      translate: 0 0;
    }

    50% {
      translate: 0 -0.625rem;
    }
  }

/* sections/blog-stories.liquid */

  .blog-stories {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .blog-stories__inner {
    display: flex;
    flex-direction: column;
    gap: clamp(2.5rem, 1.5rem + 3vw, 6rem);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .blog-stories__header {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-md);
  }

  .blog-stories__titles {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  .blog-stories__eyebrow {
    margin: 0;
  }

  .blog-stories__heading {
    margin: 0;
    font-size: var(--font-size-display);
  }

  /* "*Stories of* Transformation": italic words in the highlight color, not slanted */
  .blog-stories__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .blog-stories__view-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

  .blog-stories__arrow svg {
    inline-size: 1em;
    block-size: auto;
  }

  .blog-stories__grid {
    display: grid;
    gap: var(--space-lg);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .blog-stories__card {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: flex-end;
    min-block-size: 18rem;
    overflow: hidden;
    border-radius: var(--radius-lg);
    background-color: #1f1f1f;
    color: #ffffff;
  }

  /* "Fill empty places" off: a place with no article keeps its space in the layout */
  .blog-stories__card--empty {
    visibility: hidden;
  }

  /*
    Phones (Figma mobile): the featured card full width, then two stacked cards next to the tall card
    (Featured right: the tall card on the left). Columns about 5 : 4. Custom shapes: 2 columns.
  */
  @media (max-width: 749px) {
    /*
      Figma mobile: the eyebrow on its own line, then the heading with the link next to its last line.
      The titles box is skipped (display: contents) so the eyebrow can take the full width.
    */
    .blog-stories__header {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      align-items: end;
    }

    .blog-stories__titles {
      display: contents;
    }

    .blog-stories__eyebrow {
      grid-column: 1 / -1;
    }

    /* The 50px corners of large cards make the short phone cards look like pills */
    .blog-stories__card {
      border-radius: var(--radius-sm);
    }

    .blog-stories__heading {
      font-size: clamp(1.5rem, 1rem + 2.5vw, 2.5rem);
    }

    .blog-stories__view-all {
      flex: none;
    }

    .blog-stories__grid {
      gap: var(--space-sm);
    }

    .blog-stories__grid--featured-left {
      grid-template-columns: 5fr 4fr;
    }

    .blog-stories__grid--featured-right {
      grid-template-columns: 4fr 5fr;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right) {
      grid-template-rows: auto repeat(2, minmax(6.5rem, auto));
    }

    .blog-stories__grid--custom {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      grid-auto-rows: minmax(6.5rem, auto);
      grid-auto-flow: row dense;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right, .blog-stories__grid--custom) .blog-stories__card {
      min-block-size: 0;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right) .blog-stories__card:nth-child(1),
    .blog-stories__grid--custom .blog-stories__card--featured {
      grid-column: 1 / -1;
      min-block-size: 15rem;
    }

    .blog-stories__grid--featured-left .blog-stories__card:nth-child(2) { grid-area: 2 / 1; }
    .blog-stories__grid--featured-left .blog-stories__card:nth-child(3) { grid-area: 3 / 1; }
    .blog-stories__grid--featured-left .blog-stories__card:nth-child(4) { grid-area: 2 / 2 / 4 / 3; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(2) { grid-area: 2 / 2; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(3) { grid-area: 3 / 2; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(4) { grid-area: 2 / 1 / 4 / 2; }

    .blog-stories__grid--custom .blog-stories__card--landscape { grid-column: 1 / -1; }
    .blog-stories__grid--custom .blog-stories__card--portrait { grid-row: span 2; }

    /* The small and tall cards on phones: less padding, smaller text (not Featured, not Landscape) */
    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right, .blog-stories__grid--custom) .blog-stories__card:not(.blog-stories__card--featured, .blog-stories__card--landscape) .blog-stories__text {
      gap: 0.25rem;
      padding: 0.75rem 0.875rem;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right, .blog-stories__grid--custom) .blog-stories__card:not(.blog-stories__card--featured, .blog-stories__card--landscape) .blog-stories__category {
      font-size: 0.625rem;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right, .blog-stories__grid--custom) .blog-stories__card:not(.blog-stories__card--featured, .blog-stories__card--landscape) .blog-stories__title {
      font-size: 1rem;
    }

  }

  /* Tablets: the featured card full width, cards 2 and 3 side by side, card 4 full width */
  @media (min-width: 750px) and (max-width: 1199px) {
    .blog-stories__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right) .blog-stories__card:nth-child(1) {
      grid-column: 1 / -1;
      min-block-size: 24rem;
    }

    :is(.blog-stories__grid--featured-left, .blog-stories__grid--featured-right) .blog-stories__card:nth-child(4) {
      grid-column: 1 / -1;
    }

    /* Custom shapes on tablets: two columns, cards pack in order and fill gaps */
    .blog-stories__grid--custom {
      grid-auto-flow: row dense;
    }

    .blog-stories__grid--custom .blog-stories__card--landscape {
      grid-column: span 2;
    }

    .blog-stories__grid--custom :is(.blog-stories__card--featured, .blog-stories__card--portrait) {
      grid-row: span 2;
    }
  }

  /*
    Large screens: the mosaic (Figma, 1920px): columns about 10 : 5 : 4, two equal rows.
    Card 1 (featured) = the wide left column, both rows; cards 2 and 3 = middle column, one row each;
    card 4 = right column, both rows.
  */
  @media (min-width: 1200px) {
    .blog-stories__grid {
      /*
        Each row is at least 15-24rem (growing with the screen) and grows further if a card's text needs
        it (auto), so a card can never be taller than its row and run into the one below.
      */
      grid-template-rows: repeat(2, minmax(clamp(15rem, 17vw, 24rem), auto));
    }

    .blog-stories__card {
      min-block-size: 0;
    }

    /* Featured left (Figma): wide featured | 2 stacked | tall */
    .blog-stories__grid--featured-left {
      grid-template-columns: 10fr 5fr 4fr;
    }

    .blog-stories__grid--featured-left .blog-stories__card:nth-child(1) { grid-area: 1 / 1 / 3 / 2; }
    .blog-stories__grid--featured-left .blog-stories__card:nth-child(2) { grid-area: 1 / 2 / 2 / 3; }
    .blog-stories__grid--featured-left .blog-stories__card:nth-child(3) { grid-area: 2 / 2 / 3 / 3; }
    .blog-stories__grid--featured-left .blog-stories__card:nth-child(4) { grid-area: 1 / 3 / 3 / 4; }

    /* Featured right (mirrored): tall | 2 stacked | wide featured */
    .blog-stories__grid--featured-right {
      grid-template-columns: 4fr 5fr 10fr;
    }

    .blog-stories__grid--featured-right .blog-stories__card:nth-child(1) { grid-area: 1 / 3 / 3 / 4; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(2) { grid-area: 1 / 2 / 2 / 3; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(3) { grid-area: 2 / 2 / 3 / 3; }
    .blog-stories__grid--featured-right .blog-stories__card:nth-child(4) { grid-area: 1 / 1 / 3 / 2; }

    /*
      Custom (a Story block picked its own shape): 12 columns, rows as tall as the mosaic's rows, as many
      rows as needed. Featured = half the width x 2 rows, Landscape = half x 1, Small = a quarter x 1,
      Portrait = a quarter x 2. "dense" lets a later small card fill a hole left earlier, so e.g.
      Featured, Small, Portrait, Small rebuilds the Figma mosaic.
    */
    .blog-stories__grid--custom {
      grid-template-columns: repeat(12, minmax(0, 1fr));
      grid-template-rows: none;
      grid-auto-rows: minmax(clamp(15rem, 17vw, 24rem), auto);
      grid-auto-flow: row dense;
    }

    .blog-stories__grid--custom .blog-stories__card--featured { grid-column: span 6; grid-row: span 2; }
    .blog-stories__grid--custom .blog-stories__card--landscape { grid-column: span 6; }
    .blog-stories__grid--custom .blog-stories__card--small { grid-column: span 3; }
    .blog-stories__grid--custom .blog-stories__card--portrait { grid-column: span 3; grid-row: span 2; }
  }

  /* Equal columns ("Fill empty places" with fewer than 4 cards): one row from tablets up */
  @media (min-width: 750px) {
    .blog-stories__grid--equal {
      grid-template-columns: repeat(var(--cards, 1), minmax(0, 1fr));
      grid-template-rows: minmax(clamp(18rem, 26vw, 30rem), auto);
    }
  }

  /* Photo fills the card; a dark fade from the bottom keeps the white text readable */
  .blog-stories__media {
    position: absolute;
    inset: 0;
    z-index: -1;
  }

  .blog-stories__media .image,
  .blog-stories__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  /*
    Hover (Figma hover state): the photo slowly zooms in (Story block "Zoom amount", 112% by default;
    100% = none) towards its zoom point: the block's own position, else the image's focal point set in
    the image picker, else the centre. The text stays still. Only on screens with a real pointer (a tap
    must not leave the zoom on) and without reduced motion; keyboard focus zooms the same way.
  */
  .blog-stories__media img {
    transform-origin: var(--story-x, 50%) var(--story-y, 50%);
    transition: transform 0.9s var(--ease-out);
  }

  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .blog-stories__card:hover .blog-stories__media img {
      transform: scale(var(--story-zoom, 1.12));
    }
  }

  @media (prefers-reduced-motion: no-preference) {
    .blog-stories__card:has(.blog-stories__link:focus-visible) .blog-stories__media img {
      transform: scale(var(--story-zoom, 1.12));
    }
  }

  .blog-stories__media::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(0deg, #000000d9 0%, #00000066 45%, #00000000 75%);
  }

  .blog-stories__text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-xs);
    padding: clamp(1.25rem, 1rem + 1vw, 2.25rem);
  }

  .blog-stories__category {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Figma: "Featured Story" in a dark glass pill with a thin light edge */
  .blog-stories__pill {
    margin-block-end: var(--space-sm);
    padding: 0.35em 1.25em;
    border: 1px solid #ffffff4d;
    border-radius: var(--radius-pill);
    background-color: #ffffff1f;
    font-size: var(--font-size-body-sm);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    box-shadow: var(--glass-rim);
  }

  .blog-stories__title {
    margin: 0;
    color: #ffffff;
    font-size: var(--font-size-h3);
  }

  /*
    Featured shape (the first card unless a Story block chooses otherwise): bigger title, pill and
    excerpt. Other shapes don't show a pill or an excerpt; a featured card hides the category when it
    has a pill (Figma). Landscape gets a medium title.
  */
  .blog-stories__card--featured .blog-stories__title {
    font-size: var(--font-size-h1);
  }

  .blog-stories__card--landscape .blog-stories__title {
    font-size: var(--font-size-h2);
  }

  .blog-stories__card:not(.blog-stories__card--featured) :is(.blog-stories__pill, .blog-stories__excerpt),
  .blog-stories__card--featured:has(.blog-stories__pill) .blog-stories__category {
    display: none;
  }

  .blog-stories__excerpt {
    margin: var(--space-sm) 0 0;
    color: #ffffffd9;
    font-size: var(--font-size-body);
  }

  /*
    Featured title H2 in equal columns (the card is narrower) and on phones; smaller excerpt on phones.
    These rules come after the base rules above (same specificity: the later rule wins).
  */
  .blog-stories__grid--equal .blog-stories__card--featured .blog-stories__title {
    font-size: var(--font-size-h2);
  }

  @media (max-width: 749px) {
    .blog-stories__card--featured .blog-stories__title {
      font-size: var(--font-size-h2);
    }

    .blog-stories__excerpt {
      font-size: var(--font-size-body-sm);
    }
  }

  /* The title's link covers the whole card: one click target, one tab stop per story */
  .blog-stories__link {
    color: inherit;
    text-decoration: none;
  }

  .blog-stories__link::after {
    content: "";
    position: absolute;
    inset: 0;
  }

  /*
    Focus ring on the whole card, in the scheme accent (Highlight color if set). Only with :has();
    other browsers keep the link's own ring, so a keyboard user always sees where the focus is.
  */
  @supports selector(:has(*)) {
    .blog-stories__link:focus-visible {
      outline: none;
    }

    .blog-stories__card:has(.blog-stories__link:focus-visible) {
      outline: 2px solid var(--color-accent);
      outline-offset: 4px;
    }
  }

  /*
    Entrance ("Scroll animation" setting): the grid only triggers (it stays visible); its cards start
    moved and transparent, then glide in one after another (0.12s apart, capped so a long list doesn't
    keep the last cards waiting) when the grid scrolls into view. The selectors repeat [data-animate]
    and :not(.is-visible) to outrank the theme's generic "hide until visible" rule in critical.css,
    which would otherwise move the whole mosaic as one block.
  */
  .blog-stories__grid[data-animate='fade-up'] { --story-from: translateY(2rem); }
  .blog-stories__grid[data-animate='zoom-in'] { --story-from: scale(0.94); }
  .blog-stories__grid[data-animate='slide-top'] { --story-from: translateY(-3rem); }
  .blog-stories__grid[data-animate='slide-bottom'] { --story-from: translateY(3rem); }
  .blog-stories__grid[data-animate='slide-left'] { --story-from: translateX(-4rem); }
  .blog-stories__grid[data-animate='slide-right'] { --story-from: translateX(4rem); }

  .blog-stories__card:nth-child(2) { --card-index: 1; }
  .blog-stories__card:nth-child(3) { --card-index: 2; }
  .blog-stories__card:nth-child(4) { --card-index: 3; }
  .blog-stories__card:nth-child(5) { --card-index: 4; }
  .blog-stories__card:nth-child(n + 6) { --card-index: 5; }

  @media (prefers-reduced-motion: no-preference) {
    .js.animations-on .blog-stories__grid[data-animate],
    .js.animations-on .blog-stories__grid[data-animate]:not(.is-visible) {
      opacity: 1;
      transform: none;
      transition: none;
    }

    .js.animations-on .blog-stories__grid[data-animate] .blog-stories__card {
      transition:
        opacity 0.8s var(--ease-out),
        transform 0.8s var(--ease-out);
      transition-delay: calc(var(--card-index, 0) * 0.12s);
    }

    .js.animations-on .blog-stories__grid[data-animate]:not(.is-visible) .blog-stories__card {
      opacity: 0;
      transform: var(--story-from, none);
    }
  }

  /*
    Theme editor preview: while a Story block is selected (script below), its card stays zoomed in and
    a dot marks the zoom point, so the merchant sees the effect of Zoom amount / Zoom towards straight
    away instead of having to hover. Only in the editor; the live store never gets the class.
  */
  .blog-stories__card.is-zoom-preview .blog-stories__media img {
    transform: scale(var(--story-zoom, 1.12));
  }

  .blog-stories__card.is-zoom-preview .blog-stories__media::before {
    content: "";
    position: absolute;
    inset-block-start: var(--story-y, 50%);
    inset-inline-start: var(--story-x, 50%);
    z-index: 1;
    inline-size: 1.25rem;
    block-size: 1.25rem;
    border: 3px solid #ffffff;
    border-radius: 50%;
    background-color: var(--color-accent);
    box-shadow: 0 0 0 1px #00000059, 0 2px 8px #00000066;
    translate: -50% -50%;
  }

/* sections/blog-trending.liquid */

  /*
    Figma 1920 frame: video 489 x 859 at x 49, panel 1276 x 859 at x 594 (56px gap), from y 143.
    Sizes are tokens or Figma px x --px (screen-scale), with the Figma px in comments.
  */
  /*
    --px = one Figma pixel: from the screen width and height with Scale with the screen on, else from the
    width only and never more than 1px (without it the 1920px sizes showed at 1280px: an 859px video card).
  */
  .blog-trending {
    --px: min(calc(100vw / 1920), 0.0625rem);

    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .blog-trending.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  /* Phones and tablets: the panel, then the video (HTML order). Two columns from 1200px */
  .blog-trending__inner {
    display: grid;
    gap: var(--space-lg);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  @media (min-width: 750px) {
    .blog-trending__inner {
      gap: var(--space-2xl);
    }
  }

  /* The panel is first in the HTML; grid areas put the video on its side */
  @media (min-width: 1200px) {
    .blog-trending--has-video .blog-trending__inner {
      grid-template-columns: minmax(0, 489fr) minmax(0, 1276fr);
      grid-template-areas: "video panel";
      column-gap: max(var(--space-xl), calc(56 * var(--px, 0.0625rem)));
    }

    .blog-trending--has-video.blog-trending--video-right .blog-trending__inner {
      grid-template-columns: minmax(0, 1276fr) minmax(0, 489fr);
      grid-template-areas: "panel video";
    }

    .blog-trending--has-video .blog-trending__panel {
      grid-area: panel;
    }

    .blog-trending__video {
      grid-area: video;
    }
  }

  /* ---------- Video card ---------- */
  .blog-trending__video {
    display: grid;
  }

  /* Below 1200px a wide, short card (phone design: 335 x 152) */
  .blog-video {
    position: relative;
    display: block;
    overflow: hidden;
    aspect-ratio: 2.2 / 1;
    border-radius: var(--video-radius, var(--radius-lg));
    background-color: #1a1a1a;
    color: #ffffff;
    isolation: isolate;
  }

  /* Phones: a big radius would cut into the short card */
  @media (max-width: 749px) {
    .blog-video {
      border-radius: min(var(--video-radius, 1.5rem), 1.5rem);
    }
  }

  /* Wide screens: as tall as the panel next to it (859px in the Figma) */
  @media (min-width: 1200px) {
    .blog-video {
      aspect-ratio: auto;
      min-block-size: calc(859 * var(--px, 0.0625rem));
    }
  }

  .blog-video__poster,
  .blog-video__poster img,
  .blog-video__placeholder,
  .blog-video > video,
  .blog-video > iframe {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }

  .blog-video__poster img {
    object-fit: cover;
  }

  .blog-video__placeholder {
    fill: #ffffff40;
  }

  /* Dark fade at the bottom, so the white text reads on any photo (black 0 → 80%) */
  .blog-video__poster::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(to bottom, transparent 55%, #000000cc);
  }

  .blog-video__caption {
    position: absolute;
    inset: auto 0 0;
    z-index: 1;
    padding: 0 calc(37 * var(--px, 0.0625rem)) max(var(--space-xl), calc(42 * var(--px, 0.0625rem)));
    pointer-events: none;
  }

  /* "VIDEO · 12:40" */
  .blog-video__label {
    margin: 0;
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .blog-video__title {
    max-inline-size: 18em;
    margin: var(--space-lg) 0 0;
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: var(--font-size-h3); /* ~26px */
    line-height: 1.3;
  }

  /* Theme editor only: the empty card's note, in the middle */
  .blog-video__note {
    position: absolute;
    inset: 0;
    z-index: 1;
    display: grid;
    place-items: center;
    margin: 0;
    padding: var(--space-lg);
    font-size: var(--font-size-body-sm);
    font-style: italic;
    text-align: center;
  }

  /* Phones (design 335 x 152): small text near the edges, the play button above the caption */
  @media (max-width: 749px) {
    .blog-video__caption {
      padding: 0 var(--space-md) var(--space-md);
    }

    .blog-video__label {
      font-size: 0.75rem;
    }

    .blog-video__title {
      max-inline-size: none;
      margin-block-start: var(--space-xs);
      font-size: 0.875rem;
    }
  }

  /* 70px round glass button: white rim, frosted, white play icon */
  .blog-video__play {
    position: absolute;
    inset: 50% auto auto 50%;
    z-index: 2;
    display: grid;
    place-items: center;
    inline-size: max(3.5rem, calc(70 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    padding: 0;
    border: 1px solid #ffffff;
    border-radius: 50%;
    background-color: #ffffff1a;
    color: #ffffff;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    cursor: pointer;
    translate: -50% -50%;
    transition:
      scale var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
  }

  /* The triangle's middle is drawn at the middle of its 24px box (assets/icon-play.svg), no nudge */
  .blog-video__play svg {
    display: block;
    inline-size: 45%;
    block-size: auto;
  }

  @media (max-width: 749px) {
    .blog-video__play {
      inset-block-start: 30%;
      inline-size: 2.5rem;
    }
  }

  /* The button works only with the script: hidden without JavaScript and until the element is defined */
  blog-video:not(:defined) .blog-video__play {
    visibility: hidden;
  }

  @media (scripting: none) {
    .blog-video__play {
      display: none;
    }
  }

  .blog-video__play:hover,
  .blog-video__play:focus-visible {
    background-color: #ffffff33;
    scale: 1.08;
  }

  .blog-video__play:focus-visible {
    outline: 2px solid #ffffff;
    outline-offset: 4px;
  }

  /* Playing: the player covers the card; poster, text and button go */
  .blog-video.is-playing > :not(video, iframe) {
    display: none;
  }

  .blog-video > video {
    object-fit: contain;
    background-color: #000000;
  }

  .blog-video > iframe {
    border: 0;
  }

  /* ---------- Trending panel ---------- */
  .blog-trending__panel {
    padding: max(var(--space-xl), calc(45 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
  }

  .blog-trending__header {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-md);
    padding-inline-end: calc(12 * var(--px, 0.0625rem));
  }

  .blog-trending__heading {
    margin: 0;
    font-size: var(--font-size-h2); /* 44px with the Text size boost */
  }

  /* "*Trending* this week": the italic word in the accent colour, upright */
  .blog-trending__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* The Figma grey made darker in M9: 65% is the lowest mix with 4.5:1 on the light schemes */
  .blog-trending {
    --trending-muted: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  .blog-trending__view-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    margin-inline-start: auto; /* stays at the end with no heading */
    color: var(--trending-muted);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .blog-trending__view-all:hover {
    color: var(--color-accent);
  }

  .blog-trending__view-all-arrow svg {
    display: block;
    inline-size: 1.1em;
    block-size: auto;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  .blog-trending__view-all:hover .blog-trending__view-all-arrow svg {
    translate: 0.25em 0;
  }

  /* Rows 24px apart, ~50px under the header; the counter numbers them 01, 02… */
  .blog-trending__rows {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    margin: max(var(--space-xl), calc(50 * var(--px, 0.0625rem))) 0 0;
    padding: 0;
    list-style: none;
    counter-reset: trending-row;
  }

  /* The Figma zig-zag: every second row starts ~45px further in (12px on phones) */
  .blog-trending__rows > :nth-child(even) {
    margin-inline-start: max(var(--space-sm), calc(45 * var(--px, 0.0625rem)));
  }

  /* Phones (Variant14): the rows near the panel edges, close together */
  @media (max-width: 749px) {
    .blog-trending__panel {
      padding: var(--space-md) var(--space-xs) var(--space-xs);
    }

    .blog-trending__header {
      padding-inline: var(--space-xs);
    }

    .blog-trending__rows {
      gap: var(--space-xs);
      margin-block-start: var(--space-md);
    }
  }

  /* No row has a views text: no views column (else a gap between the pill and the arrow) */
  .blog-trending--no-views .trending-article {
    grid-template-columns: max(3rem, calc(72 * var(--px, 0.0625rem))) minmax(0, 1fr) auto auto;
    grid-template-areas: "number text tag arrow";
  }

  @media (max-width: 749px) {
    .blog-trending--no-views .trending-article {
      grid-template-columns: 1.75rem minmax(0, 1fr) auto auto;
      grid-template-areas: "number text tag arrow";
    }

    .blog-trending--no-views .trending-article__arrow {
      align-self: center;
    }
  }

  /* Rows fade up one after another, 100ms apart */
  .blog-trending__rows > :nth-child(2) {
    --animate-delay: 100ms;
  }

  .blog-trending__rows > :nth-child(3) {
    --animate-delay: 200ms;
  }

  .blog-trending__rows > :nth-child(4) {
    --animate-delay: 300ms;
  }

  .blog-trending__rows > :nth-child(5) {
    --animate-delay: 400ms;
  }

/* sections/blog.liquid */

  .blog-list {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .blog-list__inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    /* After a page change it scrolls here: room for the header pill and the sticky toolbar */
    scroll-margin-block-start: calc(var(--header-space, 6.0625rem) + 4rem);
  }

  /* ---------- Toolbar: search, then the topic pills (Figma y 121-161, 40px tall) ---------- */
  .blog-list__toolbar {
    display: flex;
    align-items: center;
    gap: var(--space-xl); /* search → pills: ~33px */
  }

  /* Sticks under the header pill; frosted, so cards scrolling underneath don't show through */
  .blog-list__toolbar--sticky {
    position: sticky;
    inset-block-start: calc(var(--header-space, 6.0625rem) + var(--space-xs));
    z-index: 10;
    padding-block: var(--space-sm);
    background-color: var(--color-background);
  }

  /*
    Stuck (the script below adds is-stuck): a block of the page colour fills the screen from the very
    top down to the bar's bottom, edge to edge, so no card shows between the header pill and the
    toolbar. z-index -1 puts it behind the search and pills (the bar is its own stacking layer); the
    header pill (z-index 20) stays on top of it.
  */
  .blog-list__toolbar--sticky.is-stuck::before {
    content: "";
    position: absolute;
    inset: auto auto 0 50%;
    z-index: -1;
    inline-size: 100vw;
    block-size: calc(100% + var(--toolbar-top, 7rem));
    background-color: var(--color-background);
    translate: -50% 0;
    pointer-events: none;
  }

  .blog-list__search {
    position: relative;
    flex: none;
    inline-size: min(16.375rem, 100%); /* 262px */
  }

  /* Two classes: critical.css input[type="search"] (element + attribute) sets 50px and a dark border */
  .blog-list__search .blog-list__search-input {
    inline-size: 100%;
    block-size: 2.5rem;
    min-block-size: 0;
    margin: 0;
    padding-inline: var(--space-lg) 2.75rem;
    border: 1px solid var(--color-tint-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    color: var(--color-text);
    font-size: var(--font-size-caption);
  }

  /*
    Two classes on purpose: critical.css styles every button[type="submit"] as the red button, and that
    selector (element + attribute) beats one class
  */
  .blog-list__search .blog-list__search-button,
  .blog-list__search .blog-list__search-button:hover {
    /* A 32px circle centred in the 40px box, so the keyboard focus ring is round, not an oval */
    position: absolute;
    inset: 50% 0.25rem auto auto;
    display: grid;
    place-items: center;
    inline-size: 2rem;
    block-size: 2rem;
    min-block-size: 0;
    border-radius: 50%;
    translate: 0 -50%;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: var(--color-text);
    cursor: pointer;
  }

  .blog-list__search-button svg {
    inline-size: 1.25rem;
    block-size: auto;
  }

  /* Pills go on more rows when they do not fit in one (phone design) */
  .blog-list__topics {
    min-inline-size: 0;
  }

  .blog-list__topic-list {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm) var(--space-md);
    margin: 0;
    padding: 0.25rem;
    list-style: none;
  }

  .blog-list__topic {
    display: inline-flex;
    align-items: center;
    block-size: 2.5rem;
    padding-inline: var(--space-lg);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
    white-space: nowrap;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .blog-list__topic:hover {
    border-color: var(--color-accent);
  }

  /* The current topic: red fill, white text (the Figma's dark text on red was ~1.5:1) */
  .blog-list__topic[aria-current="page"] {
    border-color: var(--color-button);
    background-color: var(--color-button);
    color: var(--color-button-text);
  }

  /* ---------- Results ---------- */
  .blog-list__results {
    outline: none;
  }

  .blog-list__results[aria-busy="true"] {
    opacity: 0.5;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  .blog-list__reveal {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl); /* featured → rows ~30px */
  }

  /*
    Cards: 1 column below 375px. From 375px to 1199px (phone design, also tablets): 2 columns, the first
    of every three cards uses both (one wide card, then two small). From 1200px the Figma's rows of three, as 48 thin
    columns so each row can have its own widths (Figma px → 48ths):
    row 1  400 / 962 / 400  → 11 / 26 / 11
    row 2  792 / 482 / 482  → 22 / 13 / 13
    row 3  400 / 400 / 962  → 11 / 11 / 26
    row 4  482 / 792 / 482  → 13 / 22 / 13
    The 48 tracks have no gap (it would repeat 47 times): each card has half the gap on each side.
  */
  .blog-list__grid {
    display: grid;
    gap: var(--space-xl);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  @media (min-width: 375px) and (max-width: 1199px) {
    .blog-list__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .blog-list__item:nth-child(3n + 1) {
      grid-column: 1 / -1;
    }

    /* Photo boxes by shape, not a fixed height: a short, wide strip on the wide card */
    .blog-list .blog-list__item .article-card__media {
      block-size: auto;
      aspect-ratio: 1.43 / 1;
    }

    .blog-list .blog-list__item:nth-child(3n + 1) .article-card__media {
      aspect-ratio: 4 / 1;
    }
  }

  /* The photo fills its box at every size (fixed height or shape) */
  .blog-list .article-card__media img,
  .blog-list .article-card__placeholder {
    position: absolute;
    inset: 0;
  }

  @media (min-width: 1200px) {
    .blog-list__grid {
      grid-template-columns: repeat(48, minmax(0, 1fr));
      column-gap: 0;
      margin-inline: calc(var(--space-xl) / -2);
    }

    .blog-list__item {
      grid-column: span 16;
      padding-inline: calc(var(--space-xl) / 2);
    }

    .blog-list__item .article-card {
      min-block-size: 25.1875rem; /* 403px rows */
    }

    .blog-list__grid--mixed > :nth-child(12n + 1),
    .blog-list__grid--mixed > :nth-child(12n + 3),
    .blog-list__grid--mixed > :nth-child(12n + 7),
    .blog-list__grid--mixed > :nth-child(12n + 8) {
      grid-column: span 11;
    }

    .blog-list__grid--mixed > :nth-child(12n + 2),
    .blog-list__grid--mixed > :nth-child(12n + 9) {
      grid-column: span 26;
    }

    .blog-list__grid--mixed > :nth-child(12n + 4),
    .blog-list__grid--mixed > :nth-child(12n + 11) {
      grid-column: span 22;
    }

    .blog-list__grid--mixed > :nth-child(12n + 5),
    .blog-list__grid--mixed > :nth-child(12n + 6),
    .blog-list__grid--mixed > :nth-child(12n + 10),
    .blog-list__grid--mixed > :nth-child(12n + 12) {
      grid-column: span 13;
    }

    /* The Figma's rows after the first start 15px further left (developer's choice, kept on purpose) */
    .blog-list__grid--mixed > :nth-child(n + 4) {
      translate: calc(-15 / 16 * 1rem) 0;
    }
  }

  /* Cards in a row fade up one after another */
  .blog-list__item:nth-child(3n + 2) {
    --animate-delay: 100ms;
  }

  .blog-list__item:nth-child(3n) {
    --animate-delay: 200ms;
  }

  .blog-list__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-lg);
    padding-block: var(--space-3xl);
    text-align: center;
  }

  .blog-list__empty p {
    margin: 0;
    font-size: var(--font-size-body-lg);
  }

  .blog-list .pagination {
    margin-block-start: var(--space-lg);
  }

  /* Below 1200px the search has its own row above the pills, so the pills use the full width */
  @media (max-width: 1199px) {
    .blog-list__toolbar {
      flex-wrap: wrap;
      gap: var(--space-sm);
    }

    .blog-list__search,
    .blog-list__topics {
      inline-size: 100%;
    }
  }

  /* Phones: small pills (Variant15) */
  @media (max-width: 749px) {

    .blog-list__topic {
      block-size: 1.5rem;
      padding-inline: 0.5rem;
      font-size: 0.6875rem;
      letter-spacing: 0.08em;
    }

    .blog-list__topic-list {
      gap: 0.375rem;
    }

    .blog-list__grid {
      gap: var(--space-sm);
    }
  }

  /*
    Phones from 375px (Variant15–18): compact cards. Below 375px the cards keep the normal sizes, one
    per row. Three classes, so these win over the card snippet's own rules.
  */
  @media (min-width: 375px) and (max-width: 749px) {
    .blog-list .blog-list__item .article-card,
    .blog-list .blog-list__featured .article-card {
      gap: 0.625rem;
      padding: var(--space-xs);
      border-radius: var(--space-sm);
    }

    .blog-list .article-card .article-card__media {
      border-radius: var(--space-xs);
    }

    .blog-list .article-card .article-card__topic {
      inset: 0.375rem auto auto 0.375rem;
      font-size: 0.6875rem;
    }

    .blog-list .article-card .article-card__body {
      gap: var(--space-xs);
    }

    .blog-list .article-card .article-card__title {
      font-size: 0.9375rem;
    }

    .blog-list .blog-list__item:not(:nth-child(3n + 1)) .article-card__title {
      -webkit-line-clamp: 3;
      line-clamp: 3;
    }

    .blog-list .article-card .article-card__meta {
      gap: 0.25rem var(--space-xs);
      font-size: 0.625rem;
    }

    .blog-list .article-card .article-card__author {
      gap: 0.375rem;
    }

    .blog-list .article-card .article-card__avatar {
      inline-size: 1.125rem;
      font-size: 0.4375rem;
    }

    .blog-list .article-card .article-card__fact {
      gap: 0.25rem;
      font-size: 0.625rem;
    }

    .blog-list .article-card .article-card__fact svg {
      inline-size: 0.75rem;
    }

    .blog-list .article-card .article-card__facts {
      gap: 0.25rem var(--space-xs);
    }

    /* Featured story: a short photo, small pill, title, 3-line excerpt, one meta row */
    .blog-list .blog-list__featured .article-card__media {
      block-size: auto;
      aspect-ratio: 2.6 / 1;
    }

    .blog-list .blog-list__featured .article-card__pill {
      padding: 0.2em 0.8em;
      font-size: 0.75rem;
    }

    .blog-list .blog-list__featured .article-card__title {
      font-size: 1.0625rem;
    }

    .blog-list .blog-list__featured .article-card__excerpt {
      font-size: 0.6875rem;
    }

    .blog-list .blog-list__featured .article-card__arrow {
      inline-size: 1.5rem;
    }

    /* One meta row with the arrow at the end (design): a long author name gets cut, not wrapped */
    .blog-list .blog-list__featured .article-card__meta {
      flex-wrap: nowrap;
    }

    .blog-list .blog-list__featured .article-card__author {
      min-inline-size: 0;
      overflow: hidden;
      white-space: nowrap;
    }

    .blog-list .blog-list__featured .article-card__facts {
      flex-wrap: nowrap;
      white-space: nowrap;
    }
  }

/* sections/cart.liquid */

  /* At least one screen tall (Figma: the cart fills the first screen, the footer comes after a scroll) */
  .cart-page {
    display: block;
    min-block-size: 100svh;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /*
    Empty bag with more sections after it (Product list, Collection tiles...): no full-screen height and
    a small bottom gap, so the next section sits right under the "Your bag is empty" strip. With nothing
    after it, the empty cart still fills the screen.
  */
  .shopify-section:has(.cart-empty):not(:last-child) .cart-page {
    min-block-size: 0;
    padding-block-end: var(--space-xl);
  }

  .cart-page__inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* "HOME > CART": small capitals, the current page in the accent colour (Figma) */
  .cart-page__breadcrumb ol {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* The sign is decoration: the empty alternative text after "/" keeps screen readers quiet */
  .cart-page__breadcrumb li + li::before {
    content: "›";
    content: "›" / "";
    margin-inline-end: var(--space-xs);
    color: var(--color-text);
  }

  .cart-page__breadcrumb a {
    color: var(--color-text);
    text-decoration: none;
  }

  .cart-page__breadcrumb a:hover {
    text-decoration: underline;
  }

  .cart-page__breadcrumb [aria-current] {
    color: var(--color-accent);
  }

  .cart-page__header {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
  }

  /* The Figma eyebrow here has no rule in front of the label */
  .cart-page__eyebrow {
    margin: 0;
  }

  .cart-page__eyebrow::before {
    display: none;
  }

  .cart-page__title {
    margin: 0;
    font-size: var(--font-size-h2);
  }

  /* "Shopping bag²": the count sits raised and small, without pushing the line height */
  .cart-page__count {
    margin-inline-start: 0.15em;
    font-size: 0.55em;
    line-height: 0;
    vertical-align: super;
  }

  /*
    Items left, cards right. Figma at 1920px: items ~1126px, cards ~556px, ~140px apart, so the cards
    column is fixed-ish and the items column takes the rest.
  */
  .cart-page__layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) clamp(20rem, 29vw, 34.75rem);
    gap: clamp(var(--space-xl), 7vw, 8.75rem);
    align-items: start;
  }

  .cart-page__aside {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  /*
    Right-hand cards (Coupons, Gift wrap, Order summary): a soft gold tint of the page background,
    ~25px corners, ~40px padding at 1920px (Figma).
  */
  .cart-card {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    padding: clamp(var(--space-lg), 2.1vw, 2.5rem);
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
  }

  .cart-card__title {
    margin: 0;
    font-size: var(--font-size-h3);
  }

  /*
    Coupons (Figma): one white pill holding the code field and, at its right end, the gold "Apply"
    pill with the paper plane, flush with the pill's edge (the pill is as tall as the button, 50px).
    overflow: hidden keeps the button's ends inside the pill's round edge. The field resets the global
    input rule with two classes (input[type="text"] beats a single class). White on light schemes,
    a lighter tone on dark ones (--color-surface-raised).
  */
  .cart-coupon__form {
    display: flex;
    align-items: stretch;
    min-block-size: 3.125rem;
    overflow: hidden;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-surface-raised) 70%, transparent);
    box-shadow:
      0 4px 10px 0 #b9b9b91a,
      inset 1px 1px 0 #ffffffcc;
  }

  .cart-coupon__form:has(.cart-coupon__input:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .cart-coupon__form .cart-coupon__input {
    flex: 1;
    min-inline-size: 0;
    min-block-size: 0;
    margin: 0;
    padding-block: 0; /* the field fills the pill's height, so the text sits in the middle */
    padding-inline: 1.75rem var(--space-sm);
    border: 0;
    border-radius: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
  }

  .cart-coupon__form .cart-coupon__input:focus-visible {
    outline: none;
  }

  .cart-coupon .cart-coupon__apply {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    flex: none;
    margin: 0;
    gap: var(--space-xs);
    min-block-size: 0; /* takes the pill's height (stretch) instead of its own 50px */
  }

  .cart-coupon__apply svg {
    inline-size: 1.1em;
    block-size: auto;
  }

  /* Result under the field: gold when applied, red when not */
  .cart-coupon__message {
    margin: 0;
    font-size: var(--font-size-small);
  }

  .cart-coupon__message[data-tone='success'] {
    color: var(--color-accent);
  }

  .cart-coupon__message[data-tone='error'] {
    color: var(--color-error, #b3261e);
  }

  .cart-coupon__codes:empty {
    display: none;
  }

  /* Working codes: small pills "SAVE10  -$5.00  x" */
  .cart-coupon__codes {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .cart-coupon__code {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    padding: 0.25rem 0.25rem 0.25rem 0.85rem;
    border: 1px solid color-mix(in srgb, var(--color-accent) 50%, transparent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
    font-size: var(--font-size-small);
  }

  .cart-coupon__name {
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.04em;
    text-transform: uppercase;
  }

  .cart-coupon__saving {
    color: var(--color-accent);
  }

  .cart-coupon__remove {
    display: grid;
    place-items: center;
    inline-size: 1.75rem;
    block-size: 1.75rem;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    color: var(--color-text);
    font-size: 1.1rem;
    line-height: 1;
    cursor: pointer;
  }

  .cart-coupon__remove:hover {
    background-color: color-mix(in srgb, var(--color-text) 8%, transparent);
  }

  /*
    Gift wrap card (Figma): Glass (Light -7deg 80% = the theme's --glass-rim) over a soft gold tint with
    a light patch, a gold ribbon band near the right edge with the bow at its top. The text keeps clear
    of the ribbon. No backdrop blur: only the plain page is behind the card, so it showed nothing.
    Needs JavaScript, so it's hidden without it.
  */
  .no-js .cart-gift {
    display: none;
  }

  .cart-gift {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    padding-inline-end: 34%;
    /*
      Figma fill: a diagonal gold > light gold > white > light gold > gold sweep, every stop at 15%,
      over the page colour. Gold = the scheme accent (#C8A24B); light gold = accent mixed half with white (#E3D0A4).
    */
    --gift-gold: color-mix(in srgb, var(--color-accent) 15%, transparent);
    --gift-light: color-mix(in srgb, color-mix(in srgb, var(--color-accent) 50%, #ffffff) 15%, transparent);
    background:
      linear-gradient(
        115.33deg,
        var(--gift-gold) 2.78%,
        var(--gift-light) 25.41%,
        #ffffff26 48.72%,
        var(--gift-light) 73.66%,
        var(--gift-gold) 97.89%
      ),
      var(--color-background);
    box-shadow: var(--glass-rim);
  }

  /* Figma ribbon: linear-gradient(180deg, #D9BB72 0%, #F7EED9 20.95%, #D9BB72 100%) */
  .cart-gift__ribbon {
    position: absolute;
    inset-block: 0;
    inset-inline-end: 16%;
    z-index: -1;
    inline-size: 0.5rem;
    background: linear-gradient(180deg, #d9bb72 0%, #f7eed9 20.95%, #d9bb72 100%);
  }

  /* The bow fills ~37% of its (wide, transparent) image, so the image is ~2.7x the bow's width */
  .cart-gift__bow {
    position: absolute;
    inset-block-start: 0.5rem;
    inset-inline-start: 50%;
    inline-size: 15rem;
    max-inline-size: none;
    block-size: auto;
    translate: -50% 0;
    pointer-events: none;
  }

  .cart-gift__body {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-md);
  }

  .cart-gift__title {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-body); /* Figma: 20px at 1920 */
    font-weight: var(--font-weight-medium);
  }

  .cart-gift__text {
    margin: 0;
    font-size: var(--font-size-body-sm);
  }

  /* Saved state: content stops before the bow (Figma: the price ends ~50px left of the ribbon) */
  .cart-gift--saved {
    padding-inline-end: 27%;
  }

  .cart-gift--saved .cart-gift__body {
    align-items: stretch;
  }

  /* Photo | name | price, then the message under the name */
  .cart-gift__item {
    display: grid;
    grid-template-columns: auto 1fr auto;
    align-items: center;
    column-gap: var(--space-md);
    row-gap: var(--space-xs);
  }

  /* Figma at 1920: name, message and Remove 16px, price 20px */
  .cart-gift__item-name,
  .cart-gift__item-price {
    margin: 0;
    font-size: var(--font-size-caption);
  }

  .cart-gift__item-price {
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
    white-space: nowrap;
  }

  /* One line; the Liquid also shortens long messages so the closing quote usually stays visible */
  .cart-gift__message {
    grid-column: 2 / -1;
    margin: 0;
    overflow: hidden;
    font-size: var(--font-size-caption);
    white-space: nowrap;
    text-overflow: ellipsis;
  }

  .cart-gift__message-label {
    color: var(--color-accent);
  }

  .cart-gift__links {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-lg);
  }

  /* "Remove": plain dark text (Figma), EDIT ↗ is the gold link on the right */
  .cart-gift__remove {
    margin-block-start: var(--space-sm);
    padding: 0;
    border: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-caption);
    cursor: pointer;
  }

  .cart-gift__remove:hover {
    text-decoration: underline;
  }

  /* "ADD GIFT WRAP ↗": gold capitals with a small arrow (the theme arrow turned up-right) */
  .cart-gift__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    margin-block-start: var(--space-sm);
    padding: 0;
    border: 0;
    background: none;
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
    cursor: pointer;
  }

  .cart-gift__link:hover {
    text-decoration: underline;
  }

  .cart-gift__arrow svg {
    inline-size: 1em;
    block-size: auto;
    rotate: -45deg;
  }

  /*
    Open state (Figma): the same card shows the form instead of the summary. The ribbon band goes, the
    text gets the full width, and the bow moves to the top-right corner, tilted, half off the card
    (the card's overflow: hidden cuts it, as in the design).
  */
  .cart-gift.is-open {
    padding-inline-end: clamp(var(--space-lg), 2.1vw, 2.5rem);
  }

  .cart-gift__summary {
    display: contents;
  }

  .cart-gift__summary[hidden] {
    display: none;
  }

  .cart-gift__form {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  /* Figma: the bow's knot sits ~50px in from the card's top and right edges; only the loops run off the edge */
  .cart-gift__corner-bow {
    position: absolute;
    inset-block-start: -0.75rem;
    inset-inline-end: -5.5rem;
    z-index: -1;
    inline-size: 18rem;
    max-inline-size: none;
    block-size: auto;
    rotate: 25deg;
    pointer-events: none;
  }

  .cart-gift__styles {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    margin: 0;
    padding: 0;
    border: 0;
  }

  .cart-gift__label {
    margin-block-end: var(--space-xs);
    padding: 0;
    color: var(--color-accent);
    font-size: var(--font-size-body-lg);
    font-weight: var(--font-weight-medium);
  }

  /* One style: round radio, photo, "Signature Blush Box (+$5.00)" */
  .cart-gift__style {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    cursor: pointer;
  }

  .cart-gift__style .cart-gift__radio {
    flex: none;
    display: grid;
    place-content: center;
    inline-size: 1.75rem;
    block-size: 1.75rem;
    margin: 0;
    border: 1px solid #ffffffcc;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-surface-raised) 85%, transparent);
    box-shadow: 0 2px 6px #b9b9b94d;
    appearance: none;
    cursor: pointer;
  }

  .cart-gift__style .cart-gift__radio::after {
    content: "";
    inline-size: 0.75rem;
    block-size: 0.75rem;
    border-radius: 50%;
    background-color: var(--color-accent);
    scale: 0;
    transition: scale var(--duration-fast) var(--ease-out);
  }

  .cart-gift__style .cart-gift__radio:checked::after {
    scale: 1;
  }

  .cart-gift__style-image {
    flex: none;
    inline-size: 3.25rem;
    aspect-ratio: 3 / 2;
    overflow: hidden;
    border-radius: 0.25rem;
    background-color: var(--color-tint, #f3ede2);
  }

  /* Bigger in the style list, where the photo helps choose */
  .cart-gift__style .cart-gift__style-image {
    inline-size: 5rem;
    border-radius: 0.375rem;
  }

  .cart-gift__style-image img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* Two classes: the global textarea rule would otherwise win (see the coupon field) */
  .cart-gift__form .cart-gift__textarea {
    min-block-size: 6.5rem;
    padding: var(--space-md) var(--space-lg);
    border: 1px solid #ffffffcc;
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-surface-raised) 60%, transparent);
    box-shadow: inset 0 1px 3px #b9b9b933;
    resize: vertical;
  }

  .cart-gift__error {
    margin: 0;
    color: var(--color-error, #b3261e);
    font-size: var(--font-size-small);
  }

  .cart-gift__actions {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md);
    margin-block-start: var(--space-sm);
  }

  .cart-gift__cancel {
    padding: var(--space-sm) var(--space-md);
    border: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-body);
    cursor: pointer;
  }

  .cart-gift__cancel:hover {
    text-decoration: underline;
  }

  .cart-gift .cart-gift__save {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    margin: 0;
  }

  /* Rows: label left, amount right */
  .cart-summary__rows {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    margin: 0;
    font-size: var(--font-size-body-sm);
  }

  .cart-summary__row {
    display: flex;
    justify-content: space-between;
    gap: var(--space-md);
  }

  .cart-summary__row dt,
  .cart-summary__row dd {
    margin: 0;
  }

  .cart-summary__row dd {
    text-align: end;
  }

  .cart-summary__row--discount,
  .cart-summary__free {
    color: var(--color-accent);
  }

  .cart-summary__later {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  /* Total: bigger, with more space above (Figma) */
  .cart-summary__row--total {
    margin-block-start: var(--space-sm);
    font-size: var(--font-size-body-lg);
    font-weight: var(--font-weight-medium);
  }

  /* "Add a note to your order": a quiet line that opens a text box */
  .cart-summary__note summary {
    color: var(--color-accent);
    font-size: var(--font-size-body-sm);
    cursor: pointer;
  }

  .cart-summary__note textarea {
    margin-block-start: var(--space-sm);
  }

  /* Proceed to checkout: the gold pill with the paper plane (Figma); the button reads its colours from these */
  .cart-summary .cart-summary__checkout {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    inline-size: 100%;
    gap: var(--space-sm);
  }

  .cart-summary__checkout svg {
    inline-size: 1.1em;
    block-size: auto;
  }

  /* Shopify's express buttons fill the card's width */
  .cart-summary__express :is(.additional-checkout-buttons, shopify-accelerated-checkout-cart) {
    --shopify-accelerated-checkout-button-border-radius: var(--radius-pill);
    inline-size: 100%;
  }

  /* "<- Continue shopping": the theme arrow turned to point left */
  .cart-summary__continue {
    display: inline-flex;
    align-items: center;
    align-self: center;
    gap: var(--space-xs);
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
    text-decoration: none;
  }

  .cart-summary__continue:hover {
    text-decoration: underline;
  }

  .cart-summary__continue svg {
    inline-size: 1em;
    block-size: auto;
    rotate: 180deg;
  }

  .cart-summary__continue--under-card {
    display: none;
  }

  @media (max-width: 749px) {
    .cart-summary__continue--in-card {
      display: none;
    }

    .cart-summary__continue--under-card {
      display: inline-flex;
      margin-block-start: var(--space-xs);
    }
  }

  .cart-page__title:focus {
    outline: none;
  }

  /*
    Free-shipping bar (Figma): truck + gold sentence on the left, "$285 / $200" on the right, a
    rounded bar below that fills with the accent colour.
  */
  .cart-shipping {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
    gap: var(--space-sm) var(--space-md);
    margin-block-end: var(--space-xl);
  }

  .cart-shipping__message,
  .cart-shipping__amounts {
    margin: 0;
    font-size: var(--font-size-body-lg);
  }

  .cart-shipping__message {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    color: var(--color-accent);
  }

  .cart-shipping__message svg {
    flex: none;
    inline-size: 1.5rem;
    block-size: auto;
  }

  .cart-shipping__amounts {
    font-weight: var(--font-weight-medium);
  }

  .cart-shipping__bar {
    grid-column: 1 / -1;
    block-size: 0.5rem;
    overflow: hidden;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 18%, var(--color-background));
  }

  /*
    The fill grows from 0 on page load. After a change the same fill gets the new --progress and the
    transition grows it; when the whole cart is swapped (layout change), the script copies the old
    --progress into --from on the new fill, so the load animation starts from there.
  */
  .cart-shipping__fill {
    display: block;
    inline-size: var(--progress);
    block-size: 100%;
    border-radius: inherit;
    background-color: var(--color-accent);
  }

  /* Page load: grows from 0 (animation); after a change: from its width to the new one (transition) */
  @media (prefers-reduced-motion: no-preference) {
    .cart-shipping__fill {
      animation: cart-shipping-fill 0.8s var(--ease-out);
      transition: inline-size 0.8s var(--ease-out);
    }
  }

  @keyframes cart-shipping-fill {
    from {
      inline-size: var(--from, 0%);
    }
  }

  .cart-page__items {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    margin: 0 0 var(--space-lg);
    padding: 0;
    list-style: none;
  }

  /* "2 selected   Remove selected" above the list */
  .cart-page__toolbar:not([hidden]) {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
    margin-block-end: var(--space-md);
  }

  .cart-page__error {
    margin: 0 0 var(--space-md);
    color: var(--color-error, #b3261e);
  }

  /*
    The script saves quantities on its own; the Update button is only for visitors without JavaScript.
    .js (set in <head> before the first paint), not cart-page:defined: the button would show until the
    deferred script runs, then go, and below 1200px the cards under it would jump up (layout shift).
  */
  .js .cart-page__update {
    display: none;
  }

  /*
    Empty bag (design C): a slim glass strip (icon, message, buttons on one line). .cart-empty is the
    size container: the strip changes its layout by its own width (see the rules after the phone rules).
  */
  .cart-empty {
    container-type: inline-size;
  }

  .cart-empty__strip {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
    padding-block: var(--space-lg);
    padding-inline: var(--space-xl);
    border-radius: var(--radius-lg);
    background-color: var(--color-glass-strong);
    box-shadow: var(--glass-shadow), var(--glass-rim);
  }

  /* The bag icon in a soft highlight circle */
  .cart-empty__icon {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 3.5rem;
    block-size: 3.5rem;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
    color: var(--color-text);
  }

  .cart-empty__icon svg {
    inline-size: 1.5rem;
    block-size: 1.5rem;
  }

  .cart-empty__message {
    display: grid;
    flex: 1;
    gap: var(--space-2xs);
    min-inline-size: 0;
  }

  .cart-empty__title,
  .cart-empty__text,
  .cart-empty__text > * {
    margin: 0;
  }

  .cart-empty__title {
    font-size: var(--font-size-h3);
  }

  .cart-empty__text {
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
  }

  /*
    Buttons: always a row or always a column (setting), never "whatever fits": flex-wrap would put them
    side by side for short labels and stacked for long ones.
  */
  .cart-empty__actions {
    display: flex;
    flex: none;
    gap: var(--space-sm) var(--space-lg);
  }

  .cart-empty__actions--row {
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: center;
  }

  .cart-empty__actions--row > * {
    white-space: nowrap;
  }

  .cart-empty__actions--column {
    flex-direction: column-reverse; /* the main button on top, the text link under it */
    align-items: flex-end;
  }

  .cart-empty__link svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

  /*
    Bottom bar (below 1200px, Figma mobile): "Total $306" on the left, the gold checkout pill on the
    right, on the page colour with round top corners and a soft shadow above. It spans the screen: the
    negative margins undo the page margins of .cart-page__inner (full width below 1200px).
  */
  /*
    The amount and the button label never break; when both don't fit (a long total such as
    "Rs. 107,700.00 INR" on a small phone), the button goes on its own full-width line.
  */
  .cart-bar {
    position: sticky;
    inset-block-end: 0;
    z-index: 2;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md);
    margin-inline: calc(var(--page-margin) * -1);
    padding: var(--space-md) var(--page-margin);
    padding-block-end: max(var(--space-md), env(safe-area-inset-bottom));
    border-start-start-radius: var(--radius-md);
    border-start-end-radius: var(--radius-md);
    background-color: var(--color-background);
    box-shadow: 0 -6px 20px 0 #b9b9b933;
  }

  .cart-bar__total {
    display: grid;
    margin: 0;
    line-height: 1.2;
  }

  .cart-bar__label {
    font-size: var(--font-size-body-sm);
  }

  .cart-bar__amount {
    font-size: var(--font-size-h3);
    font-weight: var(--font-weight-medium);
    white-space: nowrap;
  }

  .cart-bar .cart-bar__checkout {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    flex: 1 0 auto;
    max-inline-size: 100%;
    gap: var(--space-sm);
    white-space: nowrap;
  }

  /* A button alone on its line is as wide as the bar; next to the total it keeps its own width */
  @media (min-width: 750px) {
    .cart-bar .cart-bar__checkout {
      flex-grow: 0;
    }
  }

  .cart-bar__checkout svg {
    inline-size: 1.1em;
    block-size: auto;
  }

  /* Large screens: two columns, the order summary card has the checkout button */
  @media (min-width: 1200px) {
    .cart-bar {
      display: none;
    }
  }

  /* Tablets and phones (below 1200px): one column, the cards under the items */
  @media (max-width: 1199px) {
    .cart-page__layout {
      grid-template-columns: minmax(0, 1fr);
    }

    /* Two classes: the global .button rule (display: inline-flex) loads later and beats one class */
    .cart-summary .cart-summary__checkout {
      display: none;
    }
  }

  /* Phones (Figma mobile): smaller text and cards, half the bottom padding, the empty-bag strip stacks */
  @media (max-width: 749px) {
    .cart-page {
      padding-block-end: calc(var(--section-padding-bottom) / 2);
    }

    .cart-page__inner {
      gap: var(--space-lg);
    }

    .cart-page__breadcrumb ol {
      font-size: 0.75rem;
    }

    .cart-shipping {
      gap: var(--space-xs) var(--space-sm);
      margin-block-end: var(--space-lg);
    }

    .cart-shipping__message,
    .cart-shipping__amounts {
      font-size: 0.8125rem;
    }

    .cart-shipping__message svg {
      inline-size: 1rem;
    }

    .cart-shipping__bar {
      block-size: 0.25rem;
    }

    .cart-page__items {
      gap: var(--space-sm);
    }

    .cart-page__aside {
      gap: var(--space-sm);
    }

    /*
      Not the end padding of the gift card: there it keeps the text clear of the ribbon and the bow
      (34%, 27% with a wrap; the open form sets its own)
    */
    .cart-card {
      gap: var(--space-md);
      padding-block: var(--space-lg);
      padding-inline-start: var(--space-lg);
      border-radius: 1rem;
    }

    .cart-card:not(.cart-gift),
    .cart-gift.is-open {
      padding-inline-end: var(--space-lg);
    }

    .cart-card__title {
      font-size: 1rem;
    }

    .cart-coupon__form {
      min-block-size: 2.5rem;
    }

    .cart-coupon__form .cart-coupon__input {
      padding-inline-start: 1.25rem;
      font-size: 0.8125rem;
    }

    /* Two classes here and on the bar button: the global .button rule loads later and beats one class */
    .cart-coupon .cart-coupon__apply {
      padding-inline: var(--space-lg);
      font-size: 0.75rem;
    }

    .cart-gift__title {
      font-size: 0.9375rem;
    }

    .cart-gift__text,
    .cart-gift__link,
    .cart-gift__remove,
    .cart-gift__item-name,
    .cart-gift__message {
      font-size: 0.8125rem;
    }

    .cart-gift__bow {
      inline-size: 10rem;
    }

    .cart-gift__corner-bow {
      inline-size: 12rem;
      inset-inline-end: -3.5rem;
    }

    .cart-summary__rows {
      gap: var(--space-sm);
      font-size: 0.8125rem;
    }

    .cart-summary__row--total {
      font-size: 0.9375rem;
    }

    .cart-summary__continue {
      font-size: 0.8125rem;
    }

    .cart-bar__label {
      font-size: 0.875rem;
    }

    .cart-bar__amount {
      font-size: 1.25rem;
    }

    .cart-bar .cart-bar__checkout {
      min-block-size: 2.75rem;
      padding-inline: var(--space-lg);
      font-size: 0.75rem;
    }

    .cart-empty__strip {
      flex-direction: column;
      align-items: flex-start;
      padding: var(--space-lg);
    }

    /* Two buttons don't fit next to each other in the strip: they wrap (each label stays on one line) */
    .cart-empty__actions--row {
      flex-wrap: wrap;
    }

    .cart-empty__actions--column {
      align-items: flex-start;
    }
  }

  /*
    Tablets and small laptops (from 750px; phones stack, above): a strip narrower than 56rem has no room
    for the message AND both buttons on one line (at ~770px the text got ~90px and the link ran over
    it). Then: icon | message on the first row, the buttons on a second row under the message.
  */
  @media (min-width: 750px) {
    @container (max-width: 56rem) {
      .cart-empty__strip {
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        align-items: center;
        row-gap: var(--space-md);
      }

      .cart-empty__actions {
        grid-column: 2;
        flex-wrap: wrap;
      }

      .cart-empty__actions--column {
        align-items: flex-start;
      }
    }
  }

/* sections/collection-banner.liquid */

  /*
    The large image sits in the top-right corner of the section (Figma: 521px wide at 1920px, so about
    27%), behind the text. The text column stays centred and narrow enough not to run into it.
  */
  .collection-banner {
    position: relative;
    isolation: isolate;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /*
    "Start at the top of the page" (Figma: the jar starts at the page's top edge, behind the header pill).
    The banner moves up under the sticky header by the header's height (20px gap + 77px pill, the same
    value header.liquid uses for the transparent header) and adds it back as padding, so its colour fills
    the strip behind the pill and the large image starts at the very top. The breadcrumb stays where it was.
  */
  .collection-banner--under-header {
    --header-space: 6.0625rem;

    margin-block-start: calc(var(--header-space) * -1);
    padding-block-start: calc(var(--header-space) + var(--section-padding-top));
  }

  /* Below 1200px the header is the smaller pill (12px gap + 60px), see header.liquid */
  @media (max-width: 1199px) {
    .collection-banner--under-header {
      --header-space: calc(3.75rem + var(--space-sm));
    }
  }

  /* A transparent header already pulls the first section up under it: don't move it twice */
  body:has(.header--transparent) .collection-banner--under-header {
    margin-block-start: 0;
  }

  /* A solid header ("Solid background" header setting) has nothing to show through: the banner starts below it */
  body:has(.header--solid) .collection-banner--under-header {
    margin-block-start: 0;
    padding-block-start: var(--section-padding-top);
  }

  .collection-banner__inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* "HOME › SKINCARE": small capitals, the current page in the highlight colour (as on the cart page) */
  .collection-banner__breadcrumb ol {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .collection-banner__breadcrumb li + li::before {
    content: "›";
    margin-inline-end: var(--space-xs);
    color: var(--color-text);
  }

  .collection-banner__breadcrumb a {
    color: var(--color-text);
    text-decoration: none;
  }

  .collection-banner__breadcrumb a:hover {
    text-decoration: underline;
  }

  .collection-banner__breadcrumb [aria-current] {
    color: var(--banner-highlight);
  }

  .collection-banner__content {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-md);
    /*
      Centred, so it keeps half an image width clear on each side. The large image is pinned to the top
      right and drawn behind the text, so the text may run a little over the left of its (mostly empty) box.
      (Two full image widths left the sentence ~600px wide at 1280px, and the staggered lines wrapped.)
    */
    max-inline-size: min(80rem, calc(100% - var(--banner-image-width)));
    margin-inline: auto;
    text-align: center;
  }

  .collection-banner__title {
    margin: 0;
    color: var(--banner-highlight);
  }

  /* No sentence: the title itself is the big heading */
  .collection-banner__title--large {
    color: var(--color-text);
    font-size: var(--font-size-h1);
  }

  /*
    The sentence: 28px -> 40px (h2 size; the Figma's lines are ~48px at 1920px). Heading font, tall
    line height so the photos fit between the lines.
  */
  .collection-banner__sentence {
    margin: 0;
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: var(--font-size-h2);
    line-height: 1.5;
    text-wrap: balance;
  }

  .collection-banner__sentence em {
    font-style: normal;
    color: var(--banner-highlight);
  }

  /*
    Lines (split at [break]): on phones and tablets they run on and wrap freely. From 990px each line
    is its own row: "Centred" centres every row; "Staggered" lines the rows up on the left of a block
    that is itself centred, and pushes each row in by its Line indent (Figma: the second line starts a
    little in, the third under "with").
  */
  @media (min-width: 990px) {
    .collection-banner__line {
      display: block;
    }

    .collection-banner__sentence--staggered {
      inline-size: fit-content;
      max-inline-size: 100%;
      text-align: start;
    }

    .collection-banner__sentence--staggered .collection-banner__line {
      margin-inline-start: var(--line-indent, 0);
    }
  }

  /*
    A small photo inside the sentence: --photo-size is a % of the text size (100 = as tall as the
    letters). The negative margins cancel the extra height, so a big photo overlaps the lines above and
    below instead of pushing them apart (as in the Figma, where the brush is taller than the text).
  */
  .collection-banner__photo {
    --photo-height: calc(1em * var(--photo-size, 100) / 100);

    display: inline-block;
    block-size: var(--photo-height);
    margin-block: calc((1em - var(--photo-height)) / 2);
    margin-inline: 0.15em;
    vertical-align: middle;
    /* Tilt and nudge (% of the photo's own height). transform doesn't move the text around it. */
    transform: translateY(var(--photo-shift, 0%)) rotate(var(--photo-rotate, 0deg));
  }

  .collection-banner__photo > :is(img, svg) {
    display: block;
    inline-size: auto;
    block-size: 100%;
  }

  .collection-banner__photo--placeholder > svg {
    aspect-ratio: 1;
    border-radius: 4px;
    background-color: var(--color-tint);
  }

  .collection-banner__description {
    max-inline-size: 40rem;
  }

  /*
    Large image: top-right corner, behind the text, never stretched. Two classes: the image snippet's
    own `.image` rule (position: relative; width: 100%) loads later and would win against one class.
  */
  .collection-banner .collection-banner__image {
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
    z-index: -1;
    inline-size: var(--banner-image-width);
    block-size: 100%;
  }

  .collection-banner .collection-banner__image img,
  .collection-banner .collection-banner__image svg {
    inline-size: 100%;
    block-size: 100%;
    object-fit: contain;
    object-position: top right;
  }

  .collection-banner__image--placeholder svg {
    background-color: var(--color-tint);
  }

  /*
    Below 990px (phone design, design/collection): the large image sits on the right, behind the text, at
    1.5 times the Image width, its bottom at the end of the text; the sentence starts on the left under the breadcrumb, one line
    per row, and "Staggered" keeps its steps at about a third of the desktop indent (11em on a 375px
    phone would push the line off the screen).
  */
  @media (max-width: 989px) {
    .collection-banner__content {
      align-items: flex-start;
      max-inline-size: 100%;
      margin-inline: 0;
      text-align: start;
    }

    .collection-banner__line {
      display: block;
    }

    .collection-banner__sentence--staggered .collection-banner__line {
      margin-inline-start: calc(var(--line-indent, 0em) * 0.35);
    }

    /*
      Its bottom lines up with the end of the text (Figma). Its box is at most as tall as the text area
      (the section minus its top and bottom padding), so a tall photo gets narrower instead of reaching
      up under the header pill or the section above; the photo sits in the box's bottom-right corner.
    */
    .collection-banner .collection-banner__image {
      inset-block: var(--section-padding-top) var(--section-padding-bottom);
      inline-size: calc(var(--banner-image-width) * 1.5);
      block-size: auto;
    }

    .collection-banner--under-header .collection-banner__image {
      inset-block-start: calc(var(--header-space) + var(--section-padding-top));
    }

    .collection-banner .collection-banner__image img,
    .collection-banner .collection-banner__image svg {
      object-position: bottom right;
    }
  }

/* sections/collection-tiles.liquid */

  .collection-tiles {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .collection-tiles-empty {
    padding: var(--space-2xl) var(--page-margin);
    text-align: center;
  }

  /* The "Section width" setting (critical.css: --section-width), minus the page margins */
  .collection-tiles__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* Pause button for the Photo animation (snippets/motion-pause.liquid): under the cards, at the end */
  .collection-tiles__pause {
    margin-inline-start: auto;
  }

  /* The space on the button, so a hidden button (no motion, no JS) leaves no gap */
  .collection-tiles__pause .motion-pause__button {
    margin-block-start: var(--space-sm);
  }

  .collection-tiles__heading {
    margin-block: 0 var(--space-lg);
    font-size: var(--font-size-h3);
  }

  /* Tiles share the width: 3 tiles = 3 columns; at least 16rem each, so they wrap on smaller screens */
  .collection-tiles__list {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr));
    gap: 1.25rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* A photo tile (shape from the "Tile shape" setting) with a frosted glass bar along the bottom */
  .collection-tiles__link {
    position: relative;
    display: block;
    aspect-ratio: var(--tile-ratio, 4 / 3);
    overflow: hidden;
    border-radius: var(--radius-lg);
    color: var(--color-text);
    text-decoration: none;
  }

  .collection-tiles__image {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    transition: scale var(--duration-slow) var(--ease-out);
  }

  .collection-tiles__link:hover .collection-tiles__image {
    scale: 1.04;
  }

  @media (prefers-reduced-motion: reduce) {
    .collection-tiles__link:hover .collection-tiles__image {
      scale: none;
    }
  }

  .collection-tiles__bar {
    position: absolute;
    inset-inline: var(--space-md);
    inset-block-end: var(--space-md);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
    padding-block: var(--space-md);
    padding-inline: 1.25rem;
    border-radius: 1rem;
    /* Frosted glass in the scheme's own background, so its text (the scheme's text colour) stays readable */
    background-color: color-mix(in srgb, var(--color-background) 75%, transparent);
    box-shadow: var(--glass-rim);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .collection-tiles__name {
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body-lg);
  }

  .collection-tiles__cta {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
  }

  .collection-tiles__cta svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

  /* Dark price on the white bar (the price snippet uses the accent colour on product cards) */
  .collection-tiles__price .price__current {
    color: var(--color-text);
    font-weight: 700;
  }
  /*
    ---------- Promo card (Figma) ----------
    Phones 1 per row, tablets 2, desktop 3. A white card (the scheme's raised surface), text on the left,
    the cut-out on the right reaching over the top and bottom edges (overflow stays visible).
    Small heading, offer pill and link in the highlight colour (empty = the scheme's accent).
  */
  .collection-tiles--promo .collection-tiles__list {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-lg);
  }

  @media (min-width: 750px) {
    .collection-tiles--promo .collection-tiles__list {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (min-width: 1200px) {
    .collection-tiles--promo .collection-tiles__list {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: var(--space-xl);
    }
  }

  .collection-tiles__card {
    position: relative;
    display: flex;
    min-block-size: 12rem;
    padding: var(--space-xl) var(--space-xl) var(--space-lg);
    border-radius: var(--radius-md);
    background-color: var(--color-surface-raised, #ffffff);
    box-shadow: 0 0.75rem 2.5rem #0000000d;
  }

  .collection-tiles__card-text {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-sm);
    max-inline-size: 64%;
  }

  .collection-tiles__eyebrow {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .collection-tiles__card-name {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--space-xs) var(--space-sm);
  }

  .collection-tiles__card-title {
    margin: 0;
    font-size: var(--font-size-h3);
  }

  .collection-tiles__badge {
    padding: 0.25em 0.8em;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 14%, var(--color-surface-raised, #ffffff));
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-caption);
  }

  .collection-tiles__card-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    margin-block-start: auto;
    padding-block: var(--space-sm) 0.35em;
    border-block-end: 1px solid currentColor;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
  }

  /* The link covers the whole card: one click target, one Tab stop */
  .collection-tiles__card-link::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 2;
    border-radius: inherit;
  }

  .collection-tiles__card-link svg {
    inline-size: 1em;
    block-size: 1em;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  .collection-tiles__card:hover .collection-tiles__card-link svg {
    translate: 0.25em 0;
  }

  /* Focus ring on the whole card; without :has() the link keeps its own ring */
  @supports selector(:has(*)) {
    .collection-tiles__card:has(.collection-tiles__card-link:focus-visible) {
      outline: 2px solid var(--color-accent);
      outline-offset: 3px;
    }

    .collection-tiles__card-link:focus-visible {
      outline: none;
    }
  }

  /*
    The cut-out: right side, reaching a little over the top and bottom edges (Figma). The block's Photo
    settings turn, size and move it (rotate / scale / translate, % of its own box), so the text never moves.
    Hover: 4% bigger. "Photo animation" (below) moves it in a slow loop.
  */
  .collection-tiles__cutout {
    position: absolute;
    inset-block: -8%;
    inset-inline-end: 4%;
    inline-size: 36%;
    block-size: 116%;
    object-fit: contain;
    filter: drop-shadow(0 0.75rem 1rem #00000026);
    translate: var(--photo-x, 0%) var(--photo-y, 0%);
    rotate: var(--photo-rotate, 0deg);
    scale: var(--photo-scale, 1);
    transition: scale var(--duration-slow) var(--ease-out);
  }

  .collection-tiles__card:hover .collection-tiles__cutout {
    scale: calc(var(--photo-scale, 1) * 1.04);
  }

  /*
    "Photo animation": the hero decoration's movements (blocks/_hero-decoration.liquid), sized for a
    product photo. Set on the section, so all cards move together. transform only: it adds to the
    x
  */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .collection-tiles:not(.collection-tiles--anim-none) .collection-tiles__cutout {
      animation-duration: var(--photo-speed, 6s);
      animation-iteration-count: infinite;
      animation-timing-function: ease-in-out;
    }

    .motion-on .collection-tiles--anim-breathe .collection-tiles__cutout { animation-name: tiles-breathe; }
    .motion-on .collection-tiles--anim-float .collection-tiles__cutout { animation-name: tiles-float; }
    .motion-on .collection-tiles--anim-sway .collection-tiles__cutout { animation-name: tiles-sway; }
    .motion-on .collection-tiles--anim-twinkle .collection-tiles__cutout { animation-name: tiles-twinkle; }
    .motion-on .collection-tiles--anim-rock .collection-tiles__cutout { animation-name: tiles-rock; }
    .motion-on .collection-tiles--anim-flash .collection-tiles__cutout { animation-name: tiles-flash; }

    .motion-on .collection-tiles--anim-spin .collection-tiles__cutout {
      animation-name: tiles-spin;
      animation-timing-function: linear;
    }
  }

  @keyframes tiles-breathe {
    50% { transform: scale(1.06); }
  }

  @keyframes tiles-float {
    50% { transform: translateY(-6%); }
  }

  @keyframes tiles-sway {
    0%, 100% { transform: rotate(-4deg); }
    50% { transform: rotate(4deg); }
  }

  @keyframes tiles-twinkle {
    50% { transform: scale(0.94); opacity: 0.35; }
  }

  @keyframes tiles-spin {
    to { transform: rotate(360deg); }
  }

  @keyframes tiles-rock {
    50% { transform: rotate(12deg); }
  }

  /* Appear, turn and disappear: hidden at the start and end, so the loop restarts without a jump */
  @keyframes tiles-flash {
    0% { transform: scale(0.3) rotate(0deg); opacity: 0; }
    15% { transform: scale(1) rotate(30deg); opacity: 1; }
    65% { transform: scale(1) rotate(180deg); opacity: 1; }
    80%, 100% { transform: scale(0.3) rotate(240deg); opacity: 0; }
  }

  @media (prefers-reduced-motion: reduce) {
    .collection-tiles__card-link svg,
    .collection-tiles__cutout {
      transition: none;
    }
  }

/* sections/collection.liquid */

  .collection-section {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .collection-section__inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    scroll-margin-block-start: 7.5rem; /* after a page change it scrolls here: leave room for the sticky header pill */
  }

  .collection-section__title {
    margin: 0;
  }

  /*
    Toolbar (Figma, ~50px tall): category pills on the left, "30 products" | SORT on the right.
    Phones: the pills scroll sideways in their own row, count and sort below.
  */
  .collection-toolbar {
    position: relative;
    z-index: 2; /* a pill's hover image may reach over the banner above and the grid below */
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md) var(--space-xl);
  }

  /* Left side: Filters, then the pills (Figma gap 44px) */
  .collection-toolbar__start {
    display: flex;
    align-items: center;
    gap: var(--space-2xl);
    min-inline-size: 0;
    max-inline-size: 100%;
  }

  /* Results and active-filter pills, stacked; the focus target after a pill is removed shows no ring */
  .collection-results {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
  }

  .collection-results:focus {
    outline: none;
  }

  .collection-toolbar__end {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
    margin-inline-start: auto;
  }

  /* Figma "30 Products": small and grey (75% mix keeps it above 4.5:1) */
  .collection-toolbar__count {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-small);
    white-space: nowrap;
  }

  /* SORT: a real <select> dressed as the Figma outlined pill. The label sits inside the pill. */
  .collection-sort form {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    padding-inline: var(--space-lg) var(--space-md);
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .collection-sort__label {
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.08em;
    text-transform: uppercase;
  }

  .collection-sort__field {
    position: relative;
    display: inline-flex;
    align-items: center;
  }

  /* margin 0: critical.css spaces a control that follows a label (the magnifier lesson from M7.7) */
  .collection-sort .collection-sort__select {
    inline-size: auto;
    min-block-size: 2.75rem;
    margin: 0;
    padding-block: 0;
    padding-inline: 0 1.75rem;
    border: 0;
    background: transparent;
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
    cursor: pointer;
    -webkit-appearance: none;
    appearance: none;
  }

  .collection-sort .collection-sort__select:focus-visible {
    outline: none;
  }

  /* The ring goes round the whole pill when the select has keyboard focus */
  .collection-sort form:has(.collection-sort__select:focus-visible) {
    outline: 2px solid var(--color-accent); /* the theme's focus ring (critical.css) */
    outline-offset: 2px;
  }

  .collection-sort__field svg {
    position: absolute;
    inset-inline-end: 0.5rem;
    inline-size: 0.625rem;
    block-size: 0.625rem;
    pointer-events: none;
  }

  /*
    The open list. Browsers that support the customisable <select> (appearance: base-select, Chrome/Edge
    135+) draw it in the theme's style: a white rounded panel with a soft shadow under the SORT pill, roomy
    options, the chosen one in red with a light red background (no blue system highlight). Other browsers
    keep their own list; the select still works the same everywhere.
  */
  @supports (appearance: base-select) {
    .collection-sort .collection-sort__select,
    .collection-sort .collection-sort__select::picker(select) {
      appearance: base-select;
    }

    /* In this mode the select is a flex box that puts its text at the top: centre it beside SORT */
    .collection-sort .collection-sort__select {
      align-items: center;
    }

    /* We draw our own chevron (the svg above), so hide the built-in one */
    .collection-sort .collection-sort__select::picker-icon {
      display: none;
    }

    .collection-sort .collection-sort__select::picker(select) {
      min-inline-size: 14rem;
      margin-block-start: var(--space-sm);
      padding: var(--space-xs);
      border: 1px solid color-mix(in srgb, var(--color-accent) 15%, transparent);
      border-radius: var(--radius-sm);
      background-color: var(--color-background);
      box-shadow: var(--shadow-panel);
      opacity: 0;
      translate: 0 -0.25rem;
      transition:
        opacity var(--duration-fast) var(--ease-out),
        translate var(--duration-fast) var(--ease-out),
        display var(--duration-fast) allow-discrete,
        overlay var(--duration-fast) allow-discrete;
    }

    .collection-sort .collection-sort__select:open::picker(select) {
      opacity: 1;
      translate: 0 0;
    }

    @starting-style {
      .collection-sort .collection-sort__select:open::picker(select) {
        opacity: 0;
        translate: 0 -0.25rem;
      }
    }

    .collection-sort .collection-sort__select option {
      padding: var(--space-xs) var(--space-md);
      border-radius: var(--radius-xs);
      color: var(--color-text);
      font-size: var(--font-size-caption);
      cursor: pointer;
    }

    /* The chosen option's tick: hidden, the red text and background say it instead */
    .collection-sort .collection-sort__select option::checkmark {
      display: none;
    }

    /* Hover / keyboard focus: red, medium weight, light tint (like the chosen option, a shade lighter) */
    .collection-sort .collection-sort__select option:hover,
    .collection-sort .collection-sort__select option:focus-visible {
      outline: none;
      background-color: color-mix(in srgb, var(--color-accent) 6%, var(--color-background));
      color: var(--color-accent);
      font-weight: var(--font-weight-medium);
    }

    .collection-sort .collection-sort__select option:checked {
      background-color: color-mix(in srgb, var(--color-accent) 10%, var(--color-background));
      color: var(--color-accent);
      font-weight: var(--font-weight-medium);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .collection-sort .collection-sort__select::picker(select) {
      transition: none;
    }
  }

  .collection-sort__apply {
    min-block-size: 2.25rem;
    margin: 0;
    padding-inline: var(--space-md);
  }

  /* While a new sort loads, the old results fade a little */
  .collection-results[aria-busy='true'] {
    opacity: 0.5;
    transition: opacity var(--duration-fast) var(--ease-out);
  }

  @media (max-width: 749px) {
    /* Phones: Filters + the scrolling pills share the first row, count and sort the second */
    .collection-toolbar__start {
      flex: 1 1 100%;
      gap: var(--space-md);
    }

    .collection-pills {
      flex: 1 1 auto;
    }

    /* Count + switch on the left, SORT on the right; on a very narrow screen SORT moves to the next line */
    .collection-toolbar__end {
      flex: 1 1 100%;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: var(--space-xs);
      margin-inline-start: 0;
    }

    /* Smaller controls, so Filters + pills and count + switch + SORT fit a 375px screen */
    .collection-toolbar .filter-drawer__toggle {
      min-block-size: 2.5rem;
      padding-inline: var(--space-md);
      font-size: var(--font-size-small);
    }

    .collection-toolbar .collection-pill {
      padding: 0.6rem var(--space-sm);
      font-size: var(--font-size-small);
    }

    .collection-toolbar__count {
      font-size: var(--font-size-caption);
    }

    .collection-sort {
      margin-inline-start: auto;
    }

    .collection-sort form {
      gap: var(--space-xs);
      padding-inline: var(--space-md) var(--space-sm);
    }

    .collection-sort .collection-sort__select {
      min-block-size: 2.5rem;
      font-size: var(--font-size-small);
    }
  }

  /* The wrapper is the size container: the bento rows below are measured against its width (cqi) */
  .collection-grid-wrap {
    container-type: inline-size;
  }

  /* Phones: one tile per row; tablets (750px+): 2 per row. Every tile 4:5 */
  .collection-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-md);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .collection-grid__item {
    aspect-ratio: 4 / 5;
    min-inline-size: 0;
  }

  @media (min-width: 750px) {
    .collection-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (min-width: 990px) {
    /* Even grid: the chosen number of columns and tile shape */
    .collection-grid--grid {
      grid-template-columns: repeat(var(--grid-columns, 4), minmax(0, 1fr));
      gap: var(--space-xl);
    }

    .collection-grid--grid.collection-grid--square .collection-grid__item {
      aspect-ratio: 1;
    }

    .collection-grid--grid.collection-grid--landscape .collection-grid__item {
      aspect-ratio: 4 / 3;
    }
  }

  /*
    Small laptops (990-1199px): the bento's rows scale with the width, so its short tiles got too low for
    the info strip. Here it's an even 3-column grid instead; the bento starts at 1200px.
  */
  @media (min-width: 990px) and (max-width: 1199px) {
    .collection-grid--bento {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: var(--space-xl);
    }
  }

  @media (min-width: 1200px) {
    /*
      Bento. --u = one Figma pixel at the current width (Figma grid: 1831px wide, 4 columns, 35px gaps).
      --bento-rows (built in the Liquid above) lists the height of every row on this page: the Figma
      bands that are full, then the tail rows. Every tile is placed by its own --col / --row, so the
      tiles get their height from the rows they span, not from a shape.
    */
    .collection-grid--bento {
      --u: calc(100cqi / 1831);

      grid-template-columns: repeat(4, minmax(0, 1fr));
      grid-template-rows: var(--bento-rows);
      gap: calc(var(--u) * 35);
    }

    .collection-grid--bento .collection-grid__item {
      grid-column: var(--col);
      grid-row: var(--row);
      aspect-ratio: auto;
    }
  }

  /*
    Card style (style 'full'): the card grows with its content (no tile shape). Columns by view:
    phones 2 (fewer: 1), tablets 2 (more: 3), desktop "Columns on desktop" (more: 6). Three classes,
    so they beat the even grid's 990px rule above.
  */
  .collection-grid.collection-grid--full {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-sm);
  }

  .collection-grid--full .collection-grid__item {
    aspect-ratio: auto;
  }

  @media (max-width: 749px) {
    [data-view='fewer'] .collection-grid.collection-grid--full {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-md);
    }
  }

  @media (min-width: 750px) and (max-width: 1199px) {
    .collection-grid.collection-grid--full {
      gap: var(--space-lg);
    }

    [data-view='more'] .collection-grid.collection-grid--full {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }

  /* Laptops (1200-1599px): 3, or 4 with "more" */
  @media (min-width: 1200px) {
    .collection-grid.collection-grid--full {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: var(--space-xl);
    }

    [data-view='more'] .collection-grid.collection-grid--full {
      grid-template-columns: repeat(4, minmax(0, 1fr));
    }
  }

  /* Large screens (1600px+): "Columns on desktop", or 6 with "more" */
  @media (min-width: 1600px) {
    .collection-grid.collection-grid--full {
      grid-template-columns: repeat(var(--grid-columns, 4), minmax(0, 1fr));
    }

    [data-view='more'] .collection-grid.collection-grid--full {
      grid-template-columns: repeat(6, minmax(0, 1fr));
      gap: var(--space-lg);
    }
  }

  /* The column switch: two small icons, the chosen one red (design); hidden without JS */
  grid-view-switch:not(:defined) {
    display: none;
  }

  .grid-view__group {
    display: flex;
    gap: var(--space-2xs);
    margin: 0;
    padding: 0;
    border: 0;
  }

  /* A tap area at least 24px wide and 32px tall around each icon; the icon is 10px tall (2 rows), as wide as its columns */
  .grid-view__option {
    display: grid;
    place-items: center;
    min-inline-size: 1.5rem; /* 24px: the smallest tap target (WCAG 2.5.8) */
    block-size: 2rem;
    padding-inline: var(--space-2xs);
    border-radius: var(--radius-xs);
    /* 60%: an icon of a control needs 3:1 (WCAG 1.4.11); 35% gave about 2:1 */
    color: color-mix(in srgb, var(--color-text) 60%, transparent);
    cursor: pointer;
  }

  .grid-view__icon {
    display: none;
    inline-size: auto;
    block-size: 0.625rem;
    fill: currentColor;
  }

  @media (max-width: 749px) {
    .grid-view__icon--phone {
      display: block;
    }
  }

  @media (min-width: 750px) and (max-width: 1199px) {
    .grid-view__icon--tablet {
      display: block;
    }
  }

  @media (min-width: 1200px) and (max-width: 1599px) {
    .grid-view__icon--laptop {
      display: block;
    }
  }

  @media (min-width: 1600px) {
    .grid-view__icon--desktop {
      display: block;
    }
  }

  :checked + .grid-view__option {
    color: var(--color-accent);
  }

  :focus-visible + .grid-view__option {
    outline: 2px solid var(--color-accent);
    outline-offset: 1px;
  }

  /*
    Empty states (empty collection, filters that match nothing, and the search page's "No results"):
    a plain centred message, the usual "nothing found" page. A soft round icon, the heading in the heading
    font, one line of help, then the buttons. The empty collection's suggestions follow underneath.
    (The cart keeps its own glass strip.)
  */
  .collection-empty {
    display: grid;
    gap: var(--space-3xl);
    padding-block: var(--space-2xl) var(--space-xl);
  }

  .collection-empty__strip {
    display: grid;
    justify-items: center;
    gap: var(--space-lg);
    max-inline-size: 36rem;
    margin-inline: auto;
    text-align: center;
  }

  .collection-empty__icon {
    display: grid;
    place-items: center;
    inline-size: 5.5rem;
    block-size: 5.5rem;
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 8%, var(--color-background));
    color: var(--color-accent);
  }

  .collection-empty__icon svg {
    inline-size: 2rem;
    block-size: 2rem;
  }

  .collection-empty__message {
    display: grid;
    gap: var(--space-sm);
  }

  .collection-empty__title,
  .collection-empty__text,
  .collection-empty__picks-title {
    margin: 0;
  }

  .collection-empty__title {
    font-size: var(--font-size-h2);
    line-height: var(--line-height-heading);
  }

  .collection-empty__text {
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
    font-size: var(--font-size-body);
  }

  .collection-empty__actions {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    align-items: center;
    gap: var(--space-sm) var(--space-lg);
  }

  .collection-empty__actions > * {
    white-space: nowrap;
  }

  .collection-empty__picks {
    display: grid;
    gap: var(--space-xl);
  }

  .collection-empty__picks-title {
    font-size: var(--font-size-h2);
  }

  .collection-empty__picks-title em {
    color: var(--color-accent);
  }

/* sections/collections.liquid */

  .collections-page {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .collections-page__inner {
    display: grid;
    gap: var(--space-2xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* Header "Centred title": a short red rule + uppercase eyebrow, then the serif title (like search) */
  .collections-page__header {
    display: grid;
    justify-items: center;
    gap: var(--space-md);
    text-align: center;
  }

  .collections-page__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .collections-page__eyebrow::before {
    content: '';
    inline-size: 4.125rem; /* 66px, the theme's eyebrow rule */
    block-size: 2px;
    background-color: currentColor;
  }

  .collections-page__title {
    margin: 0;
    font-size: var(--font-size-h1);
    line-height: var(--line-height-heading);
  }

  .collections-page__text {
    max-inline-size: 40rem;
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
    font-size: var(--font-size-body);
  }

  /*
    Header "Banner with image": a rounded panel with the photo filling it and the words on the left. The
    background colour fades in from the left over the photo, so the text stays readable on any picture.
  */
  .collections-hero {
    position: relative;
    display: flex;
    align-items: center;
    min-block-size: clamp(16rem, 28vw, 27rem);
    overflow: hidden;
    border-radius: var(--card-radius, var(--radius-lg));
    isolation: isolate;
  }

  .collections-hero__image {
    position: absolute;
    inset: 0;
    z-index: -2;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .collections-hero::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background: linear-gradient(
      to right,
      color-mix(in srgb, var(--color-background) 85%, transparent) 0%,
      color-mix(in srgb, var(--color-background) 55%, transparent) 45%,
      transparent 75%
    );
  }

  .collections-hero--plain {
    background-color: color-mix(in srgb, var(--color-accent) 6%, var(--color-background));
  }

  .collections-hero__content {
    display: grid;
    gap: var(--space-md);
    max-inline-size: 34rem;
    padding: var(--space-2xl) clamp(var(--space-lg), 5vw, 6rem);
  }

  .collections-hero__title {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-display);
    line-height: var(--line-height-heading);
  }

  .collections-hero__text {
    margin: 0;
    font-size: var(--font-size-body-lg);
  }

  /* Breadcrumb under the banner: Home | Collections */
  .collections-page__breadcrumb {
    margin-block-start: calc(var(--space-lg) * -1); /* closer to the banner than the grid gap */
    font-size: var(--font-size-small);
  }

  .collections-page__breadcrumb ol {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .collections-page__breadcrumb li + li::before {
    content: '|';
    margin-inline-end: var(--space-sm);
    color: color-mix(in srgb, var(--color-text) 40%, var(--color-background));
  }

  .collections-page__breadcrumb a {
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    text-decoration: none;
  }

  .collections-page__breadcrumb a:hover {
    color: var(--color-accent);
  }

  .collections-page__breadcrumb [aria-current] {
    font-weight: var(--font-weight-medium);
  }

  /*
    The grid: phones 1 column, tablets 2, small laptops (990-1199px) --columns-laptop (at most 3),
    from 1200px "Columns on desktop". These rules come before the bento rules, which replace them.
  */
  .collections-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 1.25rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  @media (min-width: 750px) {
    .collections-grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .collections-grid > :nth-child(2n) {
      --col: 1;
    }
  }

  @media (min-width: 990px) {
    .collections-grid {
      grid-template-columns: repeat(var(--columns-laptop, 3), minmax(0, 1fr));
    }

    .collections-grid[data-columns-laptop='3'] > :nth-child(3n + 1) {
      --col: 0;
    }

    .collections-grid[data-columns-laptop='3'] > :nth-child(3n + 2) {
      --col: 1;
    }

    .collections-grid[data-columns-laptop='3'] > :nth-child(3n) {
      --col: 2;
    }
  }

  @media (min-width: 1200px) {
    .collections-grid {
      grid-template-columns: repeat(var(--columns, 3), minmax(0, 1fr));
    }

    .collections-grid[data-columns-desktop='4'] > :nth-child(4n + 1) {
      --col: 0;
    }

    .collections-grid[data-columns-desktop='4'] > :nth-child(4n + 2) {
      --col: 1;
    }

    .collections-grid[data-columns-desktop='4'] > :nth-child(4n + 3) {
      --col: 2;
    }

    .collections-grid[data-columns-desktop='4'] > :nth-child(4n) {
      --col: 3;
    }
  }

  /* Animation: the cards of one row come in one after the other (--col = the card's column, 0 = first) */
  .collections-grid__item {
    --animate-delay: calc(var(--col, 0) * 100ms);
  }

  /* One card: the photo, then the bar (where the bar sits depends on the layout) */
  .collections-card {
    position: relative;
    display: flex;
    flex-direction: column;
    block-size: 100%;
    color: var(--color-text);
    text-decoration: none;
  }

  /* "Corner radius" setting (default 50px = --radius-lg); the banner uses it too */
  .collections-card__media {
    position: relative;
    overflow: hidden;
    border-radius: var(--card-radius, var(--radius-lg));
    background-color: color-mix(in srgb, var(--color-accent) 6%, var(--color-background));
  }

  .collections-card__image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
    transition: scale var(--duration-slow) var(--ease-out);
  }

  /* Hover zoom only with a real hover (a tap on a touch screen can leave it zoomed) */
  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .collections-card:hover .collections-card__image {
      scale: 1.04;
    }
  }

  /* The focus ring follows the card's corners */
  .collections-card:focus-visible {
    border-radius: var(--card-radius, var(--radius-lg));
  }

  .collections-card__bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  .collections-card__name {
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body-lg);
  }

  .collections-card__count {
    display: inline-flex;
    flex: none;
    align-items: center;
    gap: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
  }

  .collections-card__count svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

  /* --- Tiles and bento: the bar is frosted glass on the photo --- */
  .collections-grid--tiles .collections-card__media,
  .collections-grid--bento .collections-card__media {
    position: absolute;
    inset: 0;
  }

  .collections-grid--tiles .collections-card {
    aspect-ratio: var(--tile-ratio, 4 / 5);
  }

  .collections-grid--tiles .collections-card__bar,
  .collections-grid--bento .collections-card__bar {
    position: absolute;
    inset-inline: var(--space-md);
    inset-block-end: var(--space-md);
    padding-block: var(--space-md);
    padding-inline: 1.25rem;
    border-radius: 1rem;
    /*
      Glass in the scheme's own background (white glass on light schemes, red glass on red). No backdrop
      blur: these cards scroll under the header, and a blur there makes a dark band on phones.
    */
    background-color: color-mix(in srgb, var(--color-background) 85%, transparent);
    box-shadow: var(--glass-rim);
  }

  /* --- Cards: the photo, then a separate light bar under it (name left, number right) --- */
  .collections-grid--cards .collections-card {
    gap: var(--space-sm);
  }

  .collections-grid--cards .collections-card__media {
    aspect-ratio: var(--tile-ratio, 1);
  }

  .collections-grid--cards .collections-card__bar {
    padding: var(--space-md) 1.25rem;
    border-radius: var(--radius-sm);
    background-color: color-mix(in srgb, var(--color-text) 4%, var(--color-background));
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .collections-grid--cards .collections-card:hover .collections-card__bar {
    background-color: color-mix(in srgb, var(--color-accent) 8%, var(--color-background));
  }

  .collections-grid--cards .collections-card__name {
    font-family: var(--font-body--family);
    font-size: var(--font-size-body);
    font-weight: var(--font-weight-medium);
  }

  .collections-grid--cards .collections-card__count {
    color: color-mix(in srgb, var(--color-text) 75%, var(--color-background));
    font-size: var(--font-size-body-sm);
    letter-spacing: 0;
  }

  /* --- Overlay: the photo darkened, the name centred in white on it --- */
  .collections-grid--overlay .collections-card {
    aspect-ratio: var(--tile-ratio, 4 / 3);
  }

  .collections-grid--overlay .collections-card__media {
    position: absolute;
    inset: 0;
  }

  /*
    Readable on any photo: 55% black makes even a pure white photo #737373, and white text on that is
    4.7:1 (WCAG AA for the small count too). A soft shadow under the text separates it a little more.
  */
  .collections-grid--overlay .collections-card__media::after {
    content: '';
    position: absolute;
    inset: 0;
    background-color: #0000008c;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .collections-grid--overlay .collections-card:hover .collections-card__media::after {
    background-color: #000000a6;
  }

  .collections-grid--overlay .collections-card__bar {
    position: absolute;
    inset: 0;
    flex-direction: column;
    justify-content: center;
    padding: var(--space-lg);
    color: #ffffff;
    text-align: center;
    text-shadow: 0 1px 2px #00000066, 0 0 12px #00000066;
  }

  .collections-grid--overlay .collections-card__name {
    font-size: var(--font-size-h2);
    line-height: var(--line-height-heading);
  }

  .collections-grid--overlay .collections-card__count {
    color: #ffffff;
    font-weight: var(--font-weight-medium);
  }

  /*
    --- Bento: 3 columns, a repeating group of 12 cards over 6 rows: a big 2x2 card on the left with 2 small
    ones beside it and 3 under, then the same with the big card on the right. "dense" lets the small cards
    fill the gaps. 750-989px: 2 columns, big cards 2 wide. Phones: one column like the other layouts.
  */
  .collections-grid--bento .collections-card {
    aspect-ratio: 4 / 3;
  }

  @media (min-width: 750px) {
    .collections-grid--bento {
      grid-template-columns: repeat(2, minmax(0, 1fr));
      grid-auto-rows: clamp(12rem, 24vw, 18rem);
      grid-auto-flow: dense;
    }

    .collections-grid--bento .collections-card {
      aspect-ratio: auto;
    }

    .collections-grid--bento .collections-grid__item:nth-child(12n + 1),
    .collections-grid--bento .collections-grid__item:nth-child(12n + 7) {
      grid-column: span 2;
    }
  }

  @media (min-width: 990px) {
    .collections-grid--bento {
      grid-template-columns: repeat(3, minmax(0, 1fr));
      grid-auto-rows: clamp(12rem, 18vw, 21rem);
    }

    .collections-grid--bento .collections-grid__item:nth-child(12n + 1) {
      grid-column: 1 / span 2;
      grid-row: span 2;
    }

    .collections-grid--bento .collections-grid__item:nth-child(12n + 7) {
      grid-column: 2 / span 2;
      grid-row: span 2;
    }

    .collections-grid--bento .collections-grid__item:is(:nth-child(12n + 1), :nth-child(12n + 7)) .collections-card__name {
      font-size: var(--font-size-h3);
    }
  }

  .collections-page__empty {
    margin: 0;
    text-align: center;
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
  }

/* sections/contact-channels.liquid */

  .contact-channels {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .contact-channels__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .contact-channels__heading {
    margin-block-start: var(--space-2xl); /* eyebrow → heading: 42px */
  }

  /* Red words: made italic in the editor, shown upright in the accent colour (Figma "Channel") */
  .contact-channels__heading em {
    font-style: normal;
    color: var(--color-accent);
  }

  .contact-channels__grid {
    display: grid;
    gap: var(--space-sm);
    margin-block-start: var(--space-3xl); /* heading → cards: 72px */
  }

  /* 2 per row from 375px (phone design) and on tablets / small laptops */
  @media (min-width: 375px) {
    .contact-channels__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (min-width: 750px) {
    .contact-channels__grid {
      gap: var(--space-lg);
    }
  }

  /* Figma: four 408px cards with 63px between them. From 1440px: below, 4 cards had ~140px for text */
  @media (min-width: 1440px) {
    .contact-channels__grid {
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: var(--space-xl);
    }
  }

  @media (min-width: 1600px) {
    .contact-channels__grid {
      gap: var(--space-3xl);
    }
  }

  /* Phones: the heading on one line (phone design) */
  @media (max-width: 749px) {
    .contact-channels__heading {
      margin-block-start: var(--space-sm);
      font-size: var(--font-size-h2);
    }

    .contact-channels__grid {
      margin-block-start: var(--space-xl);
    }
  }

  .contact-channels__editor-note {
    margin: var(--space-lg) var(--page-margin);
    padding: var(--space-md);
    border: 1px dashed var(--color-border);
    text-align: center;
  }

  /* Stagger (Figma: card 1, then cards 2 + 3 together, then card 4) */
  .contact-channels__grid > :nth-child(4n + 2),
  .contact-channels__grid > :nth-child(4n + 3) {
    --animate-delay: 100ms;
  }

  .contact-channels__grid > :nth-child(4n) {
    --animate-delay: 200ms;
  }

/* sections/contact-form.liquid */

  /*
    Figma 1920 frame: content from x 49 to 1870, the intro column 886px and the form panel 899px with
    a 36px gap, both starting at the eyebrow (y 212). Sizes below are tokens with the Figma px next to them.
  */
  /*
    --px = one Figma pixel. With "Scale with the screen" the screen-scale class sets it from the screen
    width and height; without it, from the width only and never more than 1px, so the Figma sizes
    shrink on phones (with no value they fell back to 1px = the 1920px sizes).
  */
  .contact {
    --px: min(calc(100vw / 1920), 0.0625rem);
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .contact.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .contact__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .contact__breadcrumb {
    margin-block-end: var(--space-2xl); /* breadcrumb → eyebrow: 45px */
  }

  /* Phones and tablets: intro, then the form. Two columns from 1200px */
  .contact__grid {
    display: grid;
    gap: var(--space-2xl);
    align-items: start;
  }

  @media (min-width: 1200px) {
    .contact__grid {
      grid-template-columns: minmax(0, 886fr) minmax(0, 899fr);
      gap: var(--space-xl); /* 36px */
    }
  }

  /* ---------- Intro ---------- */
  .contact__heading {
    margin-block-start: var(--space-2xl); /* eyebrow → H1: 42px */
  }

  /* Red words: made italic in the editor, shown upright in the accent colour (Figma "Always.") */
  .contact__heading em {
    font-style: normal;
    color: var(--color-accent);
  }

  .contact__text {
    margin-block-start: var(--space-xl); /* 33px */
    font-size: var(--font-size-body-lg); /* 22px, 35px lines */
    line-height: var(--line-height-body);
  }

  /* The Figma line length (857px) only on desktop: --px is small on phones (it made the text 174px wide) */
  @media (min-width: 1200px) {
    .contact__text {
      max-inline-size: max(36rem, calc(857 * var(--px, 0.0625rem)));
    }
  }

  /*
    Photo, stat circle and support box (desktop, from 1200px): two columns, the photo and the rest,
    30px apart. The stat circle starts back inside the photo column, so it covers the photo's right
    edge by 15.7% of the photo (Figma: photo 44-362, circle 312-518 = 50px of 318), and sits a little
    higher than the photo. The support box is under the circle and fills the rest of the column; its
    bottom lines up with the photo's bottom.
    The photo is 42cqi = 42% of the intro column (.contact__intro is a container).
  */
  .contact__intro {
    container-type: inline-size;
  }

  .contact__media {
    display: grid;
    margin-block-start: var(--space-2xl); /* 41px */
  }

  /* Two classes: the image snippet's .image / .image--cover set a height and load after this file */
  .contact__media .contact__photo {
    /* A fixed square, not aspect-ratio: the image inside would otherwise stretch it taller */
    inline-size: var(--contact-photo);
    block-size: var(--contact-photo);
    border-radius: 50%;
    overflow: hidden;
  }

  .contact__photo img,
  .contact__photo svg {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* Frosted circle: the photo shows through it, blurred. Text sizes follow the circle (cqi). */
  .contact__stat {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    inline-size: var(--contact-stat);
    aspect-ratio: 1;
    margin: 0;
    border: 1px solid color-mix(in srgb, var(--color-border) 80%, #ffffff);
    border-radius: 50%;
    background-color: var(--color-glass-strong);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    color: var(--color-accent);
    text-align: center;
    container-type: inline-size;
  }

  .contact__stat-value {
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    /*
      36% of the circle (74px in a 206px one). The Figma's 96px is Canela's narrow old-style digits;
      Newsreader's are wider, so at 96px "97%" ran past the circle's edges.
    */
    font-size: 36cqi;
    font-variant-numeric: oldstyle-nums;
    line-height: 1;
    /*
      Full width of the circle, centred. With line-height 1, Canela Text draws "97%" low in its
      1em line box: the glyphs run from 0.30em to 1.26em (old-style "7" descends 0.28em), so the 7
      ran into the label below. Moving the glyphs up 0.27em puts them inside the box
      (0.03em to 0.99em); translate leaves the layout, and so the label, where it is.
    */
    display: block;
    inline-size: 100%;
    text-align: center;
    translate: 0 -0.27em;
  }

  /* Whole words only: "SATISFACTION" is long, so the label may use most of the circle's width */
  .contact__stat-label {
    max-inline-size: 88%;
    overflow-wrap: normal;
    text-wrap: balance;
    margin-block-start: 4cqi;
    font-size: max(0.5rem, 8.7cqi); /* 18px in the 206px circle */
    font-weight: var(--font-weight-medium);
    line-height: 1.5;
    letter-spacing: var(--contact-stat-spacing, var(--letter-spacing-nav));
    text-transform: uppercase;
    /* Letter spacing also adds space after the last letter; the same space on the left re-centres it */
    padding-inline-start: var(--contact-stat-spacing, var(--letter-spacing-nav));
  }

  .contact__support {
    display: flex;
    align-items: center;
    gap: var(--space-lg);
    padding: var(--space-lg) var(--space-2xl) var(--space-lg) var(--space-lg);
    border: 1px solid var(--color-tint-border);
    border-radius: var(--radius-md);
    background-color: var(--color-tint-subtle);
  }

  .contact__support-text {
    display: grid;
    gap: var(--space-2xs);
    margin: 0;
    font-size: var(--font-size-body-lg); /* 22px, 35px lines */
    line-height: var(--line-height-body);
  }

  .contact__support-title {
    font-weight: var(--font-weight-medium);
  }

  /* Below 375px: the photo and the circle on one row, the support box full width under them */
  @media (max-width: 374px) {
    .contact__media {
      --contact-photo: 9rem;
      --contact-stat: 6rem;
      grid-template-columns: var(--contact-photo) minmax(0, 1fr);
      row-gap: var(--space-md);
      margin-block-start: var(--space-lg);
    }

    .contact__media .contact__photo {
      grid-column: 1;
      grid-row: 1;
    }

    .contact__stat {
      grid-column: 2;
      grid-row: 1;
      margin-inline-start: calc(var(--contact-photo) * -0.2);
    }

    .contact__support {
      grid-column: 1 / -1;
    }
  }

  /*
    375–1199px (phone design, also tablets): the support box on the left, the circle and the photo on
    the right; the circle covers the photo's left edge and sits a little higher.
  */
  @media (min-width: 375px) and (max-width: 1199px) {
    .contact__media {
      --contact-photo: 6rem;
      --contact-stat: 4.75rem;
      --contact-stat-overlap: 0.3;
      --contact-stat-spacing: 0.04em;
      grid-template-columns: minmax(0, 1fr) auto auto;
      align-items: center;
      column-gap: var(--space-sm);
      margin-block-start: var(--space-lg);
    }

    .contact__media .contact__photo {
      grid-column: 3;
      grid-row: 1;
      margin-block-start: calc(var(--contact-stat) * 0.25);
    }

    .contact__stat {
      grid-column: 2;
      grid-row: 1;
      align-self: start;
      margin-inline-end: calc(var(--contact-photo) * var(--contact-stat-overlap) * -1 - var(--space-sm));
    }

    .contact__support {
      grid-column: 1;
      grid-row: 1;
      gap: var(--space-xs);
      padding: var(--space-sm);
      border-radius: var(--radius-sm);
    }

    .contact__support-text {
      gap: 0;
      font-size: var(--font-size-small);
      line-height: 1.5;
    }
  }

  @media (min-width: 750px) and (max-width: 1199px) {
    .contact__media {
      --contact-photo: 12rem;
      --contact-stat: 9rem;
      --contact-stat-overlap: 0.22;
      --contact-stat-spacing: var(--letter-spacing-nav);
      column-gap: var(--space-lg);
      margin-block-start: var(--space-xl);
    }

    .contact__support {
      gap: var(--space-md);
      padding: var(--space-md) var(--space-lg);
    }

    .contact__support-text {
      font-size: var(--font-size-body);
    }
  }

  @media (min-width: 1200px) {
    .contact__media {
      --contact-photo: clamp(11rem, 42cqi, max(36rem, calc(560 * var(--px, 0.0625rem))));
      --contact-stat: calc(var(--contact-photo) * 0.648); /* 206px */
      grid-template-columns: var(--contact-photo) minmax(0, 1fr);
      column-gap: var(--space-xl); /* 30px */
    }

    .contact__media .contact__photo {
      grid-column: 1;
      grid-row: 1 / span 2;
      align-self: start;
      margin-block-start: calc(var(--contact-stat) * 0.136); /* 28px below the circle's top */
    }

    .contact__stat {
      grid-column: 2;
      grid-row: 1;
      margin-inline-start: calc(var(--contact-photo) * -0.157 - var(--space-xl)); /* over the photo's last 15.7% */
    }

    /* The margin keeps at least 32px under the circle */
    .contact__support {
      grid-column: 2;
      grid-row: 2;
      align-self: end;
      margin-block-start: var(--space-xl);
    }

    /* No photo: the circle and the box stack in one column, starting at the left */
    .contact__media--no-photo {
      grid-template-columns: minmax(0, 1fr);
    }

    .contact__media--no-photo .contact__stat {
      grid-column: 1;
      margin-inline-start: 0;
    }

    .contact__media--no-photo .contact__support {
      grid-column: 1;
    }
  }

  /* Phones: less space between the parts (phone design) */
  @media (max-width: 749px) {
    .contact__breadcrumb {
      margin-block-end: var(--space-lg);
    }

    .contact__heading {
      margin-block-start: var(--space-sm);
    }

    .contact__text {
      margin-block-start: var(--space-md);
    }

    .contact__grid {
      gap: var(--space-lg);
    }
  }

  /* ---------- Form panel ---------- */
  .contact-form {
    display: block;
    padding: var(--space-md);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-card);
    box-shadow: var(--shadow-card);
    container-type: inline-size;
  }

  @media (min-width: 750px) {
    .contact-form {
      padding: var(--space-xl);
    }
  }

  /* 34px top, 66px sides (Figma) from 1440px; less on small laptops, so the fields stay 2 per row */
  @media (min-width: 1440px) {
    .contact-form {
      padding: var(--space-xl) var(--space-3xl);
    }
  }

  /*
    Spacing with margins on our own elements, not gap on the form: Shopify's bot protection can inject
    an empty <div class="h-captcha"> into the form, and gap would add space around it too.
  */
  .contact-form__form > * {
    margin-block: 0;
  }

  .contact-form__message,
  .contact-form__topics {
    margin-block-end: var(--space-xl); /* 37px */
  }

  /* Shopify's answer after sending: a tinted box (red for an error, green for sent) */
  .contact-form__message {
    padding: var(--space-sm) var(--space-md);
    border: 1px solid color-mix(in srgb, currentcolor 35%, transparent);
    border-radius: var(--radius-sm);
    background-color: color-mix(in srgb, currentcolor 8%, transparent);
    font-weight: var(--font-weight-medium);
  }

  .contact-form__message .errors {
    margin: 0;
  }

  .contact-form__title {
    margin-block-end: var(--space-xl);
  }

  /* Small uppercase field captions (Figma "FIRST NAME", "TOPIC") */
  .contact-form__label {
    padding: 0;
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
  }

  .contact-form__topics {
    margin-inline: 0;
    padding: 0;
    border: 0;
  }

  .contact-form__pills {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-md); /* 17px */
    margin-block-start: var(--space-sm); /* 13px */
  }

  /* margin 0: the global form rule (label + input) would push each topic pill down */
  .contact-form__pills > * {
    margin: 0;
  }

  .contact-form__pill {
    display: inline-flex;
    align-items: center;
    min-block-size: max(2.5625rem, calc(41 * var(--px, 0.0625rem))); /* 41px */
    padding-inline: var(--space-sm);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-xs);
    font-size: var(--font-size-body-sm);
    font-weight: inherit;
    cursor: pointer;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .contact-form__pill:hover,
  .contact-form__pill-input:checked + .contact-form__pill {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  /* The radio itself is hidden, so its keyboard focus ring is drawn on the pill */
  .contact-form__pill-input:focus-visible + .contact-form__pill {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  /*
    One column in a very narrow panel (320px phones), two from 18rem of panel width (phone design:
    First / Last name and Email / Order number side by side). Figma 340 + 64 + 340 at 1920.
  */
  .contact-form__fields {
    display: grid;
    gap: var(--space-lg) var(--space-lg);
  }

  @container (min-width: 18rem) {
    .contact-form__fields {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .contact-form__field--full {
      grid-column: 1 / -1;
    }
  }

  @media (min-width: 1440px) {
    .contact-form__fields {
      column-gap: var(--space-3xl);
    }
  }

  .contact-form__field {
    display: grid;
    align-content: start;
    gap: var(--space-2xs); /* label → field: 5px */
  }

  .contact-form__field > * {
    margin: 0;
  }

  /*
    Side by side fields share their rows (subgrid): when one label takes two lines ("ORDER NUMBER
    (OPTIONAL)" on a phone), the two inputs still start on the same line. Rows: label, input, error.
  */
  @supports (grid-template-rows: subgrid) {
    .contact-form__fields {
      row-gap: 0;
    }

    .contact-form__field {
      grid-row: span 3;
      grid-template-rows: subgrid;
      row-gap: var(--space-2xs);
      margin-block-end: var(--space-lg);
    }

    .contact-form__field > .contact-form__label {
      align-self: end;
    }

    .contact-form__field:last-child {
      margin-block-end: 0;
    }
  }

  /*
    Two classes on purpose: critical.css styles input[type='text'] (0,1,1), which beats one class.
    The pale Figma border is kept in one place (--contact-field-border) for the M9 contrast decision.
  */
  .contact-form .contact-form__input {
    --contact-field-border: var(--color-border);
    min-block-size: max(3.125rem, calc(50 * var(--px, 0.0625rem))); /* 50px */
    padding-inline: var(--space-lg);
    border-color: var(--contact-field-border);
    border-radius: var(--radius-sm);
    background-color: var(--color-card);
    font-size: var(--font-size-caption);
  }

  .contact-form .contact-form__input:hover {
    border-color: color-mix(in srgb, var(--color-text) 40%, var(--color-background));
  }

  .contact-form .contact-form__input:focus-visible {
    border-color: var(--color-accent);
  }

  .contact-form .contact-form__input[aria-invalid='true'] {
    border-color: var(--color-error);
    background-color: color-mix(in srgb, var(--color-error) 4%, var(--color-card));
  }

  .contact-form .contact-form__textarea {
    min-block-size: max(6.625rem, calc(106 * var(--px, 0.0625rem))); /* 106px */
    padding-block: var(--space-md);
  }

  /* The theme's own error line (in place of the browser's bubble): a round "!" and the text */
  .contact-form__error {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2xs);
    color: var(--color-error);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    line-height: 1.4;
  }

  .contact-form__error[hidden] {
    display: none;
  }

  .contact-form__error::before {
    content: "!" / "";
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 1.1em;
    block-size: 1.1em;
    margin-block-start: 0.15em;
    border-radius: 50%;
    background-color: var(--color-error);
    color: #ffffff;
    font-size: 0.85em;
    line-height: 1;
  }

  /*
    Full width, so the paper plane must fly further than on a small pill to leave the button: the
    button is its own size container and the plane flies half its width (it starts near the middle).
  */
  .contact-form .contact-form__submit {
    --explore-fly: 55cqi;
    container-type: inline-size;
    inline-size: 100%;
    min-block-size: max(3.125rem, calc(56 * var(--px, 0.0625rem)));
    margin-block-start: var(--space-xl); /* 38px */
  }

  /* Phones (phone design): a compact panel, small captions, pills and fields */
  @media (max-width: 749px) {
    .contact-form__title {
      margin-block-end: var(--space-md);
      font-size: var(--font-size-body);
    }

    .contact-form__message,
    .contact-form__topics {
      margin-block-end: var(--space-lg);
    }

    .contact-form__label {
      font-size: 0.6875rem;
    }

    .contact-form__pills {
      gap: var(--space-xs);
      margin-block-start: var(--space-xs);
    }

    .contact-form__pill {
      min-block-size: 2rem;
      padding-inline: var(--space-xs);
      font-size: var(--font-size-small);
    }

    .contact-form__fields {
      column-gap: var(--space-sm);
    }

    @supports (grid-template-rows: subgrid) {
      .contact-form__field {
        margin-block-end: var(--space-md);
      }

      .contact-form__field:last-child {
        margin-block-end: 0;
      }
    }

    .contact-form .contact-form__input {
      min-block-size: 2.5rem;
      padding-inline: var(--space-sm);
      font-size: var(--font-size-small);
    }

    .contact-form .contact-form__textarea {
      min-block-size: 5rem;
      padding-block: var(--space-sm);
    }

    .contact-form .contact-form__submit {
      min-block-size: 2.75rem;
      margin-block-start: var(--space-lg);
    }
  }

/* sections/contact-locations.liquid */

  .contact-locations {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /* Below 1440px: social, then offices. Two columns from 1440px (Figma 546 + 64 + 1212) */
  .contact-locations__inner {
    display: grid;
    gap: var(--space-3xl);
    align-items: start;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  @media (min-width: 1440px) {
    .contact-locations__inner {
      grid-template-columns: minmax(0, 546fr) minmax(0, 1212fr);
    }

    .contact-locations__offices {
      grid-column: 1;
      grid-row: 1;
    }

    /* The social column starts 68px lower than the offices (Figma eyebrows at y 162 and 230) */
    .contact-locations__social {
      grid-column: 2;
      grid-row: 1;
      padding-block-start: var(--space-3xl);
    }

    /*
      Figma: the social heading is centred at x 1209, ~56px left of the cards' middle (1265). The
      right padding shifts the centre left by half of it: 9.25% of 1212px ≈ 112px → 56px.
    */
    .contact-locations__titles--social {
      padding-inline-end: 9.25%;
    }
  }

  /* Red words (optional): made italic in the editor, shown upright in the accent colour */
  .contact-locations__heading {
    margin-block-start: var(--space-2xl); /* eyebrow → heading: ~42px (Figma 37 / 37) */
    font-size: var(--font-size-h2); /* 40px */
  }

  .contact-locations__heading em {
    font-style: normal;
    color: var(--color-accent);
  }

  .contact-locations__titles {
    margin-block-end: var(--space-lg); /* heading → offices panel: 22px */
  }

  .contact-locations__titles--social {
    margin-block-end: var(--space-2xl); /* heading → social cards: 55px */
    text-align: center;
  }

  /* The rules start at 0 and take only the free space (66px at most), so the label keeps its line */
  .contact-locations__titles--social .eyebrow::before,
  .contact-locations__titles--social .eyebrow::after {
    flex: 1 1 0;
    min-inline-size: 1rem;
    max-inline-size: 66px;
    inline-size: auto;
  }

  @media (max-width: 749px) {
    .contact-locations__inner {
      gap: var(--space-2xl);
    }

    .contact-locations__heading {
      margin-block-start: var(--space-sm);
    }

    .contact-locations__titles--social {
      margin-block-end: var(--space-lg);
    }
  }

/* sections/cta-card.liquid */

  /* Figma 1920: the card 1649 x 136 at x 136, the page column's full width */
  /* --px = one Figma pixel (from the width only and never more than 1px with Scale with the screen off) */
  .cta-card {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .cta-card.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .cta-card__empty {
    margin: 0;
  }

  .cta-card__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /*
    As wide as the column, with no top margin (the FAQ card is 1418 wide and sits 90px under the
    questions). Two classes, so this wins over the snippet's .faq-contact whatever order Shopify
    puts the section and snippet stylesheets in.
  */
  .cta-card .cta-card__card {
    margin-block-start: 0;
  }

  .cta-card__card .faq-contact__card {
    inline-size: 100%;
  }

/* sections/custom-liquid.liquid */

  .custom-liquid-section {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /*
    The box itself has no overflow (overflow-x: auto would also make overflow-y auto: it cut focus
    rings, shadows and dropdowns, and broke position: sticky inside). Only wide content is held:
    - a table or <pre> scrolls sideways in its own box (display: block keeps the table's rows and cells);
    - a long URL or word breaks (overflow-wrap: break-word, not anywhere: anywhere would let a table
      shrink and break its words instead of scrolling, and squeeze flex / grid widgets);
    - a box with a fixed width at the top level (style="width: 1200px") is made no wider than the box;
    - iframes, videos and images are no wider than the box.
    <main> has overflow-x: clip, so the page never scrolls sideways.
  */
  .custom-liquid-section__content {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    overflow-wrap: break-word;
  }

  .custom-liquid-section__content > *,
  .custom-liquid-section__content :is(iframe, video, img) {
    max-inline-size: 100%;
  }

  .custom-liquid-section__content :is(table, pre) {
    display: block;
    max-inline-size: 100%;
    overflow-x: auto;
  }

  .custom-liquid-section__empty {
    margin: 0;
    padding: var(--space-xl);
    border: 1px dashed var(--color-border);
    border-radius: var(--radius-md);
    text-align: center;
  }

  /* Phones: half the section padding, as the other sections */
  @media (max-width: 749px) {
    .custom-liquid-section {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }
  }

/* sections/faq.liquid */

  /*
    Figma 1920 ("Default"): breadcrumb x 50 y 150; eyebrow y 175; H1 ~72px y 230–290 ("Ask us
    *anything.*", accent upright); intro ~22px / 35px, max ~840, y 350–385; search 767 x 48, ~80px
    under the intro; 5 cards 322 wide, gap 52, ~82px under the search.
    Topic view ("Default-1"): pills y 193–241 (48 tall, radius ~8, gap ~36), the panel from y 315.
  */
  /* --px: one Figma pixel, also with Scale with the screen off (else the 1920px sizes show on every screen) */
  .faq {
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /*
    Fill the screen height: at least one screen tall (the page background never stops above the fold),
    but the content keeps starting at the top, as in the Figma (the shared rule centres it). Two classes,
    so it beats both .faq (display: block) and the shared .section--fill-screen
  */
  .faq.section--fill-screen {
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
  }

  .faq__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .faq__intro {
    text-align: center;
  }

  .faq.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .faq__eyebrow {
    margin-block-start: var(--space-sm);
  }

  /* The rules start at 0 and take only the free space (66px at most), so the label keeps its line */
  .faq__eyebrow::before,
  .faq__eyebrow::after {
    flex: 1 1 0;
    min-inline-size: 1rem;
    max-inline-size: 66px;
    inline-size: auto;
  }

  .faq__heading {
    margin: max(var(--space-lg), calc(40 * var(--px, 0.0625rem))) 0 0;
    font-size: max(2.25rem, calc(72 * var(--px, 0.0625rem)));
    font-weight: 400;
    line-height: 1.1;
  }

  .faq__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .faq__text {
    max-inline-size: max(30rem, calc(860 * var(--px, 0.0625rem)));
    margin: max(var(--space-lg), calc(50 * var(--px, 0.0625rem))) auto 0;
    font-size: max(1rem, calc(22 * var(--px, 0.0625rem)));
    line-height: 1.6;
  }

  .faq__text > * {
    margin: 0;
  }

  /* ---------- Search (767 x 48, magnifier at the right) ---------- */
  .faq__search {
    position: relative;
    max-inline-size: max(36rem, calc(767 * var(--px, 0.0625rem)));
    margin: max(var(--space-xl), calc(70 * var(--px, 0.0625rem))) auto 0;
  }

  .faq:not([data-ready]) .faq__search {
    display: none;
  }

  /* display: block: an inline input leaves a gap under it, so the form (and the centred icon) was taller.
     Two classes: critical.css styles input[type=search] (0,1,1), which beats one class */
  .faq .faq__search-input {
    display: block;
    inline-size: 100%;
    min-block-size: max(2.5rem, calc(48 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    padding: 0 3.25rem 0 var(--space-lg);
    border: 1px solid var(--color-card-border);
    border-radius: max(0.75rem, calc(14 * var(--px, 0.0625rem)));
    background-color: var(--color-card);
    color: var(--color-text);
    font-size: var(--font-size-caption);
  }

  /* The browser's own clear ✕ is hidden: it sat on top of the magnifier. Ours replaces the magnifier */
  .faq .faq__search-input::-webkit-search-cancel-button {
    display: none;
    -webkit-appearance: none;
  }

  .faq__search-clear {
    position: absolute;
    inset-block: 0;
    inset-inline-end: calc(var(--space-lg) - 0.5rem);
    display: grid;
    place-items: center;
    inline-size: 2.25rem;
    margin-block: auto;
    block-size: 2.25rem;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    color: var(--color-text);
    cursor: pointer;
  }

  .faq__search-clear:hover {
    background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
    color: var(--color-accent);
  }

  .faq__search-clear[hidden] {
    display: none;
  }

  .faq__search-clear svg {
    inline-size: 0.9rem;
    block-size: 0.9rem;
  }

  .faq__search.has-text .faq__search-icon {
    display: none;
  }

  .faq__search-icon {
    position: absolute;
    inset-block: 0;
    inset-inline-end: var(--space-lg);
    display: grid;
    place-items: center;
    color: var(--color-text);
    pointer-events: none;
  }

  .faq__search-icon svg {
    display: block;
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  /* ---------- Topic cards (5 columns; the topic blocks' cards and panels are the grid items) ---------- */
  .faq__topics {
    counter-reset: faq-topic;
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: max(var(--space-xl), calc(52 * var(--px, 0.0625rem)));
    margin-block-start: max(var(--space-2xl), calc(82 * var(--px, 0.0625rem)));
  }

  /*
    The topic blocks have no Shopify wrapper ("tag": null): each .faq-topic steps out of the layout
    (display: contents), so each topic's card and panel are the grid items.
  */
  .faq__topics > * {
    display: contents;
  }

  /* Without the script, a panel has no answer card: the questions take the full width */
  .faq:not([data-ready]) .faq-topic__panel {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "head"
      "list";
  }

  /* ---------- Pills (topic view) ---------- */
  .faq__pills-list {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm) max(var(--space-md), calc(36 * var(--px, 0.0625rem)));
    margin: max(var(--space-lg), calc(35 * var(--px, 0.0625rem))) 0 0;
    padding: 0;
    list-style: none;
  }

  .faq__pill {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    min-block-size: max(2.5rem, calc(48 * var(--px, 0.0625rem)));
    box-sizing: border-box;
    padding: 0 var(--space-md);
    border: 1px solid var(--color-card-border);
    border-radius: max(0.5rem, calc(8 * var(--px, 0.0625rem)));
    background-color: var(--color-background);
    color: var(--color-text);
    font-family: var(--font-body--family);
    font-size: max(1rem, calc(18 * var(--px, 0.0625rem)));
    font-weight: var(--font-weight-medium);
    text-decoration: none;
    cursor: pointer;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .faq__pill:hover,
  .faq__pill[aria-current="true"] {
    border-color: color-mix(in srgb, var(--color-accent) 35%, transparent);
    color: var(--color-accent);
  }

  .faq__pill svg {
    inline-size: 1.1rem;
    block-size: auto;
    transform: scaleX(-1);
  }

  /*
    ---------- Results (no Figma frame: built from the answer card's look) ----------
    "Results for “…”" with the count at the right, then a grid of cards, one per match, as wide as
    the topic cards (3 or more per row on a laptop, 2 on tablets, 1 on phones). Each card: the
    topic's icon, the topic name (accent label), the question and the start of its answer (the
    searched word marked in both), and an arrow. Hover / focus: a pale fill, the arrow slides right.
  */
  .faq__results {
    margin-block-start: max(var(--space-2xl), calc(70 * var(--px, 0.0625rem)));
  }

  .faq__results[hidden] {
    display: none;
  }

  .faq__results-head {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-xs) var(--space-md);
    padding-block-end: var(--space-md);
    border-block-end: 1px solid var(--color-card-border);
  }

  .faq__results-title {
    margin: 0;
    font-size: max(1.375rem, calc(32 * var(--px, 0.0625rem)));
    font-weight: 400;
    line-height: 1.2;
  }

  .faq__results-title:focus {
    outline: none;
  }

  .faq__results-count {
    margin: 0;
    color: var(--color-accent);
    font-size: max(0.75rem, calc(15 * var(--px, 0.0625rem)));
    letter-spacing: 0.15em;
    text-transform: uppercase;
  }

  /*
    At least ~22rem per card and never more than 5 in a row (the topic cards' 5): 3 on a laptop,
    4 or 5 on a wide screen, then 2, then 1. The column minimum is the larger of 22rem and one fifth
    of the row (less the 4 gaps), so a sixth column never fits.
  */
  .faq__results-list {
    --results-gap: max(var(--space-md), calc(32 * var(--px, 0.0625rem)));
    display: grid;
    grid-template-columns: repeat(
      auto-fill,
      minmax(min(100%, max(22rem, calc((100% - 4 * var(--results-gap)) / 5))), 1fr)
    );
    gap: var(--results-gap);
    margin: max(var(--space-lg), calc(32 * var(--px, 0.0625rem))) 0 0;
    padding: 0;
    list-style: none;
  }

  .faq__result {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    align-items: start;
    gap: var(--space-md);
    inline-size: 100%;
    block-size: 100%;
    box-sizing: border-box;
    padding: max(var(--space-lg), calc(28 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: color-mix(in srgb, var(--color-accent) 1%, var(--color-background));
    box-shadow: var(--shadow-card);
    color: var(--color-text);
    font-family: var(--font-body--family);
    text-align: start;
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .faq__result:hover,
  .faq__result:focus-visible {
    background-color: color-mix(in srgb, var(--color-accent) 5%, transparent);
  }

  .faq__result .faq-topic__icon {
    margin: 0;
  }

  .faq__result-body {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    min-inline-size: 0;
  }

  /* Text on the same scale as the topic cards and the question rows (Figma px x --px) */
  .faq__result-topic {
    color: var(--color-accent);
    font-size: max(0.75rem, calc(14 * var(--px, 0.0625rem)));
    letter-spacing: 0.15em;
    text-transform: uppercase;
  }

  .faq__result-question {
    font-size: max(1rem, calc(22 * var(--px, 0.0625rem)));
    line-height: 1.35;
  }

  /* The start of the answer: two lines at most */
  .faq__result-excerpt {
    display: -webkit-box;
    overflow: hidden;
    color: color-mix(in srgb, var(--color-text) 70%, transparent);
    font-size: max(0.875rem, calc(17 * var(--px, 0.0625rem)));
    line-height: 1.5;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
  }

  /* The searched word */
  .faq__result mark {
    padding-inline: 0.1em;
    border-radius: 0.2em;
    background-color: color-mix(in srgb, var(--color-accent) 12%, transparent);
    color: var(--color-accent);
  }

  .faq__result-arrow {
    display: grid;
    place-items: center;
    inline-size: 2.25rem;
    block-size: 2.25rem;
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: 50%;
    color: var(--color-accent);
    transition:
      background-color var(--duration-base) var(--ease-out),
      transform var(--duration-base) var(--ease-out);
  }

  .faq__result-arrow svg {
    inline-size: 0.9rem;
    block-size: auto;
  }

  .faq__result:hover .faq__result-arrow,
  .faq__result:focus-visible .faq__result-arrow {
    background-color: var(--color-background);
  }

  @media (prefers-reduced-motion: no-preference) {
    .faq__result:hover .faq__result-arrow,
    .faq__result:focus-visible .faq__result-arrow {
      transform: translateX(4px);
    }
  }

  .faq__results-empty {
    margin: var(--space-lg) 0 0;
    font-size: var(--font-size-body);
  }

  /* Phones: compact result cards, the same scale as the question rows and the answer card (faq-mobile) */
  @media (max-width: 749px) {
    .faq__results {
      margin-block-start: var(--space-xl);
    }

    .faq__results-head {
      padding-block-end: var(--space-sm);
    }

    .faq__results-title {
      font-size: 1.125rem;
    }

    .faq__results-count {
      font-size: 0.6875rem;
    }

    .faq__results-list {
      gap: var(--space-sm);
      margin-block-start: var(--space-md);
    }

    .faq__result {
      grid-template-columns: minmax(0, 1fr) auto;
      gap: var(--space-sm);
      padding: var(--space-sm) var(--space-md);
      border-radius: 0.75rem;
    }

    .faq__result .faq-topic__icon {
      display: none;
    }

    .faq__result-body {
      gap: 0.125rem;
    }

    .faq__result-topic {
      font-size: 0.625rem;
    }

    .faq__result-question {
      font-size: 0.875rem;
    }

    .faq__result-excerpt {
      font-size: 0.75rem;
    }

    .faq__result-arrow {
      inline-size: 1.75rem;
      block-size: 1.75rem;
    }

    .faq__result-arrow svg {
      inline-size: 0.75rem;
    }

    .faq__results-empty {
      font-size: 0.8125rem;
    }
  }

  .faq__empty {
    margin: var(--space-xl) 0 0;
    text-align: center;
  }

  /* ---------- Views (with the script) ---------- */
  .faq[data-ready][data-view="overview"] .faq-topic__panel,
  .faq[data-ready][data-view="results"] .faq-topic__panel,
  .faq[data-ready][data-view="results"] .faq-topic__card,
  .faq[data-ready][data-view="topic"] .faq-topic__card,
  .faq[data-ready][data-view="topic"] .faq-topic__panel:not(.is-current),
  .faq[data-ready][data-view="topic"] .faq__eyebrow,
  .faq[data-ready][data-view="topic"] .faq__text,
  .faq[data-ready][data-view="topic"] .faq__search,
  .faq[data-ready][data-view="overview"]:not(.faq--editor) .faq-contact {
    display: none;
  }

  /* The topic view keeps the page's h1 for screen readers only (the topic title is the h2) */
  .faq[data-ready][data-view="topic"] .faq__heading {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .faq[data-ready][data-view="topic"] .faq__pills {
    display: block;
  }

  .faq[data-ready][data-view="topic"] .faq-topic__panel.is-current {
    margin-block-start: 0;
  }

  .faq[data-ready][data-view="topic"] .faq__topics {
    margin-block-start: max(var(--space-xl), calc(70 * var(--px, 0.0625rem)));
  }

  /* The view switch: the new view fades in (never on page load: this is the page's first section) */
  @media (prefers-reduced-motion: no-preference) {
    .faq.is-entering .faq__topics,
    .faq.is-entering .faq__results {
      animation: faq-view-in var(--duration-slow) var(--ease-out);
    }
  }

  @keyframes faq-view-in {
    from {
      opacity: 0;
      transform: translateY(0.75rem);
    }
  }

  /* Tablets and small laptops: 3 + 2 cards (5 in a row made 200px cards at 1280px) */
  @media (max-width: 1439px) {
    .faq__topics {
      grid-template-columns: repeat(6, minmax(0, 1fr));
      gap: var(--space-lg);
    }

    .faq-topic__card {
      grid-column: span 2;
    }
  }

  /* 3 + 2 from 750px: a last row of 2 (or 1) is centred. The wrappers are counted (one per topic) */
  @media (min-width: 750px) and (max-width: 1439px) {
    .faq__topics > :nth-child(3n + 1):nth-last-child(2) .faq-topic__card {
      grid-column: 2 / span 2;
    }

    .faq__topics > :nth-child(3n + 1):last-child .faq-topic__card {
      grid-column: 3 / span 2;
    }
  }

  /* Phones ("faq"): 2 + 2 + 1 cards, the odd last one centred */
  @media (max-width: 749px) {
    .faq__heading {
      font-size: 1.75rem;
    }

    .faq__text {
      font-size: 0.8125rem;
    }

    .faq__eyebrow {
      margin-block-start: var(--space-lg);
    }

    /* faq-mobile: a slim search box, full width */
    .faq__search {
      max-inline-size: none;
      margin-block-start: var(--space-lg);
    }

    .faq .faq__search-input {
      min-block-size: 2.25rem;
      padding-inline-start: var(--space-sm);
      border-radius: 0.5rem;
      font-size: 0.75rem;
    }

    .faq__search-icon {
      inset-inline-end: var(--space-sm);
    }

    .faq__search-icon svg {
      inline-size: 0.875rem;
      block-size: 0.875rem;
    }

    .faq__search-clear {
      inset-inline-end: 0;
    }

    .faq__topics {
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: var(--space-sm);
      margin-block-start: var(--space-md);
    }

    .faq-topic__card {
      grid-column: span 2;
    }

    /* The wrappers are counted (they're the topics, one each) */
    .faq__topics > :last-child:nth-child(odd) .faq-topic__card {
      grid-column: 2 / span 2;
    }

    .faq__pills-list {
      gap: var(--space-xs);
    }

    .faq__pill {
      min-block-size: 1.75rem;
      padding: 0 var(--space-xs);
      font-size: 0.6875rem;
    }
  }

/* sections/featured-product.liquid */

  featured-product {
    display: block;
  }

  .featured-product {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .featured-product__inner {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* One column on all screens: no media (store only) = the info card alone, centred, at a readable width; no
     blocks = the media alone, not wider than a two-column media */
  .featured-product__inner--no-media .featured-product__info {
    inline-size: 100%;
    max-inline-size: 60rem;
    margin-inline: auto;
  }

  .featured-product__inner--no-info .featured-product__media {
    inline-size: 100%;
    max-inline-size: 40rem;
    margin-inline: auto;
  }

  .featured-product__media {
    min-inline-size: 0;
  }

  /*
    Tablets (750-1199px), one column: a full-width square was taller than the screen. The media (gallery
    and thumbnails together) is at most 40rem wide, centred. Phones keep the full width
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .featured-product__media {
      inline-size: 100%;
      max-inline-size: 40rem;
      margin-inline: auto;
    }
  }

  /*
    From 1200px: two columns, media 45% and info card 55% (Figma PDP proportions). The media stays in view
    under the header while the info card scrolls (as the product page gallery)
  */
  @media (min-width: 1200px) {
    .featured-product__inner:not(.featured-product__inner--single) {
      grid-template-columns: minmax(0, 9fr) minmax(0, 11fr);
      align-items: start;
      gap: clamp(2rem, 3vw, 4rem);
    }

    .featured-product__media {
      position: sticky;
      inset-block-start: calc(var(--header-space, 6.0625rem) + var(--space-sm));
    }

    /* Media at the right: the columns swap too, so the media keeps its 9 parts */
    .featured-product--media-right .featured-product__inner:not(.featured-product__inner--single) {
      grid-template-columns: minmax(0, 11fr) minmax(0, 9fr);
    }

    .featured-product--media-right .featured-product__media {
      order: 2;
    }
  }

  /* Phones: half the top and bottom padding, less space between the media and the card */
  @media (max-width: 749px) {
    .featured-product {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }

    .featured-product__inner {
      gap: var(--space-lg);
    }
  }

  /*
    Gallery: a sideways scroller that snaps to one medium at a time (swipe on phones, trackpad or
    Shift + wheel on desktop, arrow keys once focused). Square slides, like the PDP photos.
  */
  .featured-product__gallery {
    display: grid;
    grid-auto-columns: 100%;
    grid-auto-flow: column;
    gap: var(--space-sm);
    overflow-x: auto;
    overscroll-behavior-x: contain;
    scroll-snap-type: x mandatory;
    scrollbar-width: none; /* the thumbnails show where you are */
    border-radius: var(--radius-lg);
  }

  .featured-product__gallery::-webkit-scrollbar {
    display: none;
  }

  .featured-product__gallery:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 4px;
  }

  .featured-product__slide {
    aspect-ratio: 1;
    scroll-snap-align: start;
  }

  .featured-product__slide--placeholder {
    overflow: hidden;
    border-radius: var(--radius-lg);
    background-color: var(--color-tint);
  }

  .featured-product__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  /*
    Thumbnails: small rounded squares; the one on show gets an accent outline. A thin scrollbar shows when
    they don't fit, so a mouse can reach the last ones
  */
  .featured-product__thumbs {
    display: flex;
    gap: var(--space-sm);
    margin-block-start: var(--space-sm);
    padding-block-end: var(--space-xs);
    overflow-x: auto;
    scrollbar-width: thin;
    scrollbar-color: color-mix(in srgb, var(--color-accent) 60%, transparent) transparent;
  }

  .featured-product__thumb {
    position: relative;
    flex: none;
    inline-size: 4.5rem;
    aspect-ratio: 1;
    margin: 0;
    padding: 0;
    overflow: hidden;
    border: 2px solid transparent;
    border-radius: var(--radius-md);
    background-color: var(--color-tint);
    opacity: 0.6;
    cursor: pointer;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      border-color var(--duration-fast) var(--ease-out);
  }

  .featured-product__thumb img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .featured-product__thumb:hover,
  .featured-product__thumb[aria-current='true'] {
    opacity: 1;
  }

  .featured-product__thumb[aria-current='true'] {
    border-color: var(--color-accent);
  }

  /* Video / 3D marker on a thumbnail */
  .featured-product__thumb-badge {
    position: absolute;
    inset-block-end: 0.25rem;
    inset-inline-end: 0.25rem;
    padding: 0.1rem 0.35rem;
    border-radius: var(--radius-pill);
    background-color: #000000b3;
    color: #ffffff;
    font-size: 0.625rem;
    line-height: 1.4;
  }

  /*
    Without JavaScript the thumbnails can't move the gallery: no buttons that do nothing. The gallery shows
    its own thin scrollbar in their place
  */
  @media (scripting: none) {
    .featured-product__thumbs {
      display: none;
    }

    .featured-product__gallery {
      scrollbar-width: thin;
    }
  }

  /*
    Figma PDP: the info sits in a large, light, rounded card with a hairline border. The raised surface is
    white on light schemes and a light veil on dark ones (never a white card on a dark section)
  */
  .featured-product__info {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    min-inline-size: 0;
    padding: clamp(1.5rem, 3.3vw, 4rem);
    border: 1px solid color-mix(in srgb, var(--color-text) 8%, transparent);
    border-radius: var(--radius-lg);
    background-color: var(--color-surface-raised);
  }

  /* Phones: the product page's card padding (Info card block) */
  @media (max-width: 749px) {
    .featured-product__info {
      gap: var(--space-md);
      padding: var(--space-lg) var(--space-md);
    }
  }

/* sections/footer.liquid */

  /*
    Only .footer__* classes here, no element selectors like "footer a": those beat BEM classes on
    specificity (the header had that bug in M2.2).

    Sizes measured from the design screenshot at 1920 wide (design/figma/components/footer/screenshot.png):
    panel 1822 x 806, 50px from each side, radius 50px, 50px inner padding, ~45px below it.
    The section's colour scheme class paints the strip around the panel; the panel is a glass card.
  */
  .footer {
    /*
      Link grey: the Figma's #787878 is only 4.2:1 on cream (body text needs 4.5:1). Mixing the scheme's
      text into its background gives the same soft grey look at 6:1 on cream, and it follows every colour
      scheme. --footer-link-mix (70% or 85%) is set in the Liquid above from the background's brightness.
    */
    --footer-link-color: color-mix(in srgb, var(--color-text) var(--footer-link-mix, 70%), var(--color-background));

    padding-block: var(--space-section) var(--space-2xl);
  }

  /*
    Dark background (.footer--dark, set in the Liquid from the scheme's brightness). The theme's white glass
    (25% white) turns a dark background into a mid grey, where the accent headings, the social icons and
    the email text fall under 4.5:1. Here the glass is a light veil of the text colour instead, and the
    social buttons, the email field and the country / language pills use the scheme's raised surface
    (snippets/css-variables.liquid), so they show clearly on the panel. Light schemes keep the white glass.
  */
  .footer--dark {
    --color-glass: color-mix(in srgb, var(--color-text) 8%, transparent);
    --color-glass-strong: var(--color-surface-raised);
  }

  /* The pickers' pill uses --color-glass at rest (snippets/localization-form): on dark, the raised surface too */
  .footer--dark .localization__toggle {
    background-color: var(--color-surface-raised);
  }

  /*
    Full width: the "full-width" class on <footer> (critical.css) lets it span the whole viewport instead
    of Skeleton's page-width column. The panel is then centred with margin-inline: auto and is as wide as
    the viewport minus the Figma's edge gap (16px on phones -> 50px at 1920, so 1822px wide at 1920).

    No overflow: hidden on the panel: it would also cut off the country/language list, which opens
    upwards from the bottom row. The wordmark clips itself instead (below).
  */
  .footer__panel {
    --footer-edge: clamp(var(--space-md), 2.6vw, 3.125rem);

    position: relative;
    container-type: inline-size; /* the wordmark's size is a share of the panel's width (cqi) */
    inline-size: calc(100% - var(--footer-edge) * 2);
    margin-inline: auto;
    padding-block-start: clamp(var(--space-2xl), 3.4vw, var(--space-3xl)); /* -> 64px */
    padding-inline: clamp(var(--space-lg), 2.6vw, 3.125rem); /* -> 50px */
    border-radius: var(--radius-lg);
    background-color: var(--color-glass);
    box-shadow: var(--shadow-collection), var(--shadow-glass-edge);
    /*
      No backdrop-filter here: nothing scrolls behind the panel (it sits on the section's flat colour), so a
      blur changes nothing you can see. It also caused a dark band on phones: when the panel's top goes
      past the top of the screen, the blur has no pixels there and fills them with dark, and the header's
      own blur then shows that band. (Like the header pill, the panel is still a see-through glass colour.)
    */
  }

  /*
    Top row. Phones and tablets: one column (brand, then the menu, then the newsletter).
    Desktop (1200px+), measured at 1920: brand ~490px, each menu ~245px, newsletter ~370px, 32px gaps, so
    2fr | 1fr per menu column | 1.5fr; --footer-tracks is built in the Liquid (no empty track).
  */
  .footer__top {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-2xl) var(--space-xl);
  }

  /* The menu columns: 2 per row on phones, all in one row from 750px */
  .footer__nav {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: var(--space-2xl) var(--space-xl);
  }

  .footer__brand {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-2xl); /* logo -> tagline -> social icons, ~48px apart */
  }

  .footer__logo {
    display: inline-flex;
    max-inline-size: 100%; /* a long logo text stays in the brand column (cut with …) */
    align-items: center;
    gap: var(--space-xs);
    color: var(--color-text);
    text-decoration: none;
  }

  .footer__logo-image {
    flex-shrink: 0;
    inline-size: var(--logo-width);
    max-block-size: 4rem;
    block-size: auto;
    object-fit: contain;
  }

  .footer__logo-text {
    font-family: var(--font-logo--family);
    font-weight: var(--font-logo--weight);
    font-size: calc(var(--logo-text-size) * var(--logo-text-scale, 1));
    line-height: 1;
  }

  .footer__logo-text em {
    font-style: italic;
  }

  .footer__logo-text em {
    color: var(--color-accent);
  }

  /* Tagline: body font, full text colour, 22px (Figma), about 450px wide */
  .footer__tagline {
    max-inline-size: 28rem;
    color: var(--color-text);
    font-size: var(--font-size-body-lg);
    line-height: 1.45;
  }

  .footer__tagline > :first-child,
  .footer__newsletter-text > :first-child {
    margin-block-start: 0;
  }

  .footer__tagline > :last-child,
  .footer__newsletter-text > :last-child {
    margin-block-end: 0;
  }

  /* Column heading: the Figma's red uppercase label, ~40px above the first link */
  .footer__heading {
    margin-block: 0 2.5rem;
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    line-height: var(--line-height-heading);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .footer__links,
  .footer__legal-list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .footer__links {
    display: grid;
    gap: 1.25rem; /* 20px between links (53px from line to line in the Figma) */
  }

  /* Links: heading (serif) font in the softer grey, accent colour on hover and for the current page */
  .footer__link {
    color: var(--footer-link-color);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body);
    text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .footer__link:hover,
  .footer__link[aria-current='page'] {
    color: var(--color-accent);
  }

  /*
    Column links: the header's hand-drawn underline (assets/nav-underline.svg) appears on hover, keyboard
    focus and the current page. Same technique as the header: an empty ::after box painted in currentColor
    (so it's red with the text) and cut to the SVG's shape with a CSS mask. --nav-underline is set on
    <footer> in the Liquid above, because asset_url can't run inside this stylesheet.
    It draws in from the left (scaleX 0 -> 1); with reduced motion it simply appears.
  */
  .footer__links .footer__link {
    position: relative;
    display: inline-block;
  }

  /*
    One size for every link (it used to be 65% of each word, stretched: "About" and "Blog" got different
    swooshes): the SVG's own proportions (97:16, "contain"), starting at the word's left edge (Figma)
  */
  .footer__links .footer__link::after {
    content: '';
    position: absolute;
    inset-inline-start: -0.1em;
    inset-block-start: calc(100% + 0.2rem);
    inline-size: 3.5rem;
    aspect-ratio: 97 / 16;
    background-color: currentcolor;
    mask: var(--nav-underline) left center / contain no-repeat;
    pointer-events: none;
    transform: scaleX(0);
    transform-origin: left center;
    transition: transform var(--duration-base) var(--ease-out);
  }

  .footer__links .footer__link:hover::after,
  .footer__links .footer__link:focus-visible::after,
  .footer__links .footer__link[aria-current='page']::after {
    transform: scaleX(1);
  }

  @media (prefers-reduced-motion: reduce) {
    .footer__links .footer__link::after {
      transition: none;
    }
  }

  /* Figma: ~58px from the newsletter text down to the email field */
  .footer__newsletter .newsletter-form {
    margin-block-start: 3.5rem;
  }

  .footer__newsletter-text {
    max-inline-size: 24rem;
    color: var(--footer-link-color);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body);
    line-height: 1.35;
  }

  /* Bottom row: 1px divider, then copyright | pickers + payment icons | legal links */
  .footer__bottom {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md) var(--space-xl);
    margin-block-start: 3.5rem; /* ~55px under the last link */
    padding-block: var(--space-lg);
    border-block-start: 1px solid var(--color-border);
    font-size: var(--font-size-caption);
  }

  .footer__copyright {
    margin: 0;
    color: var(--color-text);
  }

  .footer__utilities {
    display: flex;
    flex-wrap: wrap;
    min-inline-size: 0;
    max-inline-size: 100%; /* phones: the stacked row is never wider than the panel (long country names) */
    align-items: center;
    gap: var(--space-md) var(--space-lg);
  }

  .footer__payment-list {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-xs);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .footer__payment-icon {
    display: block;
  }

  /* Only placed in the row: the button's own colours and look are Shopify's and must not change */
  .footer__follow-on-shop {
    display: flex;
    align-items: center;
  }

  /* "Powered by Shopify" sits after the copyright in the same colour */
  .footer__copyright a {
    color: inherit;
  }

  .footer__legal-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
  }

  .footer__legal-list .footer__link {
    color: var(--color-text);
    font-family: var(--font-body--family);
    font-size: var(--font-size-caption);
  }

  .footer__legal-list .footer__link:hover,
  .footer__legal-list .footer__link[aria-current='page'] {
    color: var(--color-accent);
  }

  /*
    The Figma's small light dot between legal links. Drawn by CSS (an empty box with a round
    background), so screen readers don't read anything out.
  */
  .footer__legal-list li + li::before {
    content: '';
    display: inline-block;
    inline-size: 5px;
    block-size: 5px;
    margin-inline: 1.25rem;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-text) 25%, transparent);
    vertical-align: middle;
  }

  /*
    Giant wordmark (Figma: ~500px at 1920 wide, spanning most of the panel). Its box is only 0.72em
    tall and clips what overflows, so the bottom of the letters is cut off flush with the panel's
    bottom edge (the panel has no bottom padding). The negative top margin tucks the empty space above
    the letters under the bottom row, like the Figma. The clip also stops a sideways scroll on phones.
    Faded (Figma, measured): ~20% grey for the first word, ~20% of the accent for the italic word.
    Decorative only (aria-hidden), so it has no contrast requirement.
  */
  .footer__wordmark {
    block-size: 0.72em;
    overflow: hidden;
    margin-block: -0.08em 0;
    color: color-mix(in srgb, var(--color-text) 20%, transparent);
    font-family: var(--font-logo--family);
    font-weight: var(--font-logo--weight);
    font-size: min(31.25rem, var(--wordmark-size, 26cqi)); /* fits the panel; 500px at most */
    line-height: 1;
    text-align: center;
    white-space: nowrap;
    pointer-events: none;
    user-select: none;
  }

  /* The letters (see the markup): the logo text, then the accent word in italic */
  .footer__wordmark-text::before {
    content: attr(data-word);
  }

  .footer__wordmark-text::after {
    content: attr(data-accent);
    color: color-mix(in srgb, var(--color-accent) 20%, transparent);
    font-style: italic;
  }

  /*
    The whole word floats: it sinks a little further into the bottom edge and rises back, in a slow
    loop (only down from its resting place: the box clips at the top too, so moving up would cut the
    tops of the letters). transform only, so it costs no layout. With the theme's "Enable animations"
    setting on (.motion-on: also in the theme editor) and motion allowed. It moves without end, so the
    pause button (snippets/motion-pause.liquid) stops it (WCAG 2.2.2).
  */
  .footer__wordmark-text {
    display: inline-block;
  }

  @media (prefers-reduced-motion: no-preference) {
    .motion-on .footer__wordmark-text {
      animation: footer-wordmark-float 7s ease-in-out infinite;
    }
  }

  @keyframes footer-wordmark-float {
    50% {
      transform: translateY(0.14em);
    }
  }

  /* The pause button sits on the word, at the end of the panel */
  .footer__wordmark-area {
    position: relative;
  }

  .footer__wordmark-pause {
    position: absolute;
    inset-block-end: var(--space-md);
    inset-inline-end: 0;
  }

  /*
    Phones (below 750px, no Figma design: the developer chose this reflow): less space between the parts,
    so the footer is not too long; the bottom row stacks.
  */
  @media (max-width: 749px) {
    .footer__brand {
      gap: var(--space-lg);
    }

    .footer__heading {
      margin-block-end: var(--space-lg);
    }

    .footer__links {
      gap: var(--space-md);
    }

    .footer__newsletter .newsletter-form {
      margin-block-start: var(--space-lg);
    }

    .footer__bottom {
      flex-direction: column;
      align-items: flex-start;
      margin-block-start: var(--space-2xl);
    }
  }

  /*
    Tablets: as many menu columns in a row as fit at 9rem (144px) each (3 at 750px), the others wrap, so
    a menu with many items never gets very narrow columns. Desktop: all in one row (--footer-columns).
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .footer__nav {
      grid-template-columns: repeat(auto-fit, minmax(min(9rem, 100%), 1fr));
    }
  }

  @media (min-width: 1200px) {
    .footer__nav {
      grid-template-columns: repeat(var(--footer-columns), minmax(0, 1fr));
    }
  }

  @media (min-width: 1200px) {
    .footer__top {
      grid-template-columns: var(--footer-tracks);
    }
  }

/* sections/header.liquid */

  /*
    Sticky header. Shopify wraps the header in a section element (class shopify-section-group-header-group);
    that wrapper is what has to stick. A sticky element only sticks inside its parent, and the <header> fills
    its wrapper exactly, so making <header> itself sticky would do nothing. Every section of the Header group
    gets that class (e.g. the announcement bar), so :has(sticky-header) picks the header's wrapper only.
  */
  .shopify-section-group-header-group:has(sticky-header) {
    position: sticky;
    inset-block-start: 0;
    z-index: 20;
    /*
      The wrapper is a see-through box across the top of the page (20px gap + 77px pill). Without this it
      would still catch the mouse, so content scrolling underneath (e.g. the footer's country list on a
      short page) couldn't be hovered or clicked. Only the pill takes clicks again (below).
    */
    pointer-events: none;
  }

  .header__bar {
    pointer-events: auto;
  }

  /* The space around the pill stays see-through: only the pill has a surface */
  .header {
    padding-block-start: 1.25rem; /* 20px from the top, Figma */
  }

  /*
    The floating pill (Figma: 1363 x 77 at 1920 wide, radius 50px, 25% white "glass", soft shadow).
    The colour scheme class gives it its text colours; its background is replaced by the glass,
    and backdrop-filter blurs whatever scrolls underneath so the menu stays readable.
  */
  .header__bar {
    position: relative; /* the mega menu panel is positioned against the pill */
    display: var(--bar-display, flex); /* grid in the menu-button layout (see "Menu button layout" below) */
    align-items: center;
    justify-content: space-between;
    gap: var(--space-xl);
    max-inline-size: 85.25rem; /* 1364px */
    block-size: 4.8125rem; /* 77px, Figma */
    margin-inline: auto;
    padding-block: 0;
    padding-inline: var(--space-2xl) var(--space-sm);
    border-radius: var(--radius-pill);
    box-shadow: var(--shadow-header);
  }

  .header .header__bar {
    background-color: var(--color-glass);
    -webkit-backdrop-filter: blur(var(--glass-frost)) saturate(1.4);
    backdrop-filter: blur(var(--glass-frost)) saturate(1.4);
    transition:
      background-color var(--duration-base) var(--ease-out),
      box-shadow var(--duration-base) var(--ease-out),
      max-inline-size var(--duration-base) var(--ease-out);
  }

  sticky-header {
    display: block;
  }

  /*
    Transparent header (Figma home hero). The header's wrapper pulls the next section up underneath it
    (negative margin = 20px gap + 77px pill), so the hero starts at the very top of the page.
  */
  .shopify-section-group-header-group:has(.header--transparent) {
    margin-block-end: calc(var(--header-space) * -1);
  }

  /*
    A Hero as the first section goes under the header the same way when the header is not transparent
    (logo and menu always show): the hero image fills the top of the page behind the glass pill, instead
    of a strip of the hero's background colour. hero.liquid moves the hero's text down by --header-space.
    The Video banner does the same (video-banner.liquid).
  */
  body:has(#MainContent > .shopify-section:first-child :is(.hero, .video-banner)) .shopify-section-group-header-group:has(.header:not(.header--transparent):not(.header--solid)) {
    margin-block-end: calc(var(--header-space) * -1);
  }

  /*
    "Solid background" setting: the header area (full width, with the gap around the pill) is painted in the
    header's colour scheme (the color-* class on .header) and the page starts below it, so no section slides
    under it (the rules below skip .header--solid). The pill keeps its glass on top of that colour.
  */
  .header--solid {
    padding-block-end: 1.25rem; /* the same 20px under the pill as above it */
    pointer-events: auto; /* the wrapper lets clicks through; a painted band must not */
  }

  /* The band spans the whole window (the section grid puts its child in the page column; the pill still centres itself) */
  .shopify-section-group-header-group:has(.header--solid) > sticky-header {
    grid-column: 1 / -1;
  }

  /* The solid header is 20px taller (gap under the pill too): anchors and screen heights use this value */
  :root:has(.header--solid) {
    --header-space: calc(6.0625rem + 1.25rem);
  }

  /*
    Every other page: the header is see-through too. Without this, the page's own background (cream) showed
    as a band behind the pill above a first section in another colour (e.g. white search results).
    The first section slides up under the header (negative margin = the header's height) and gets a
    transparent top border of the same height: a background paints under the border, so the section's
    colour reaches the top of the page, while its content still starts below the pill. Its own padding is
    left alone. Skipped where the first section already does this: the transparent header (home hero) and
    the collection banner's "Under the header" option, and on pages without the header (the password
    layout: this CSS is bundled into every page, so it has to check that the header is there).
  */
  :root {
    --header-space: 6.0625rem; /* 20px gap + 77px pill */
  }

  body:has(sticky-header):not(:has(.header--transparent, .header--solid)) #MainContent > .shopify-section:first-child:not(:has(.collection-banner--under-header, .hero, .video-banner)) {
    margin-block-start: calc(var(--header-space) * -1);
  }

  body:has(sticky-header):not(:has(.header--transparent, .header--solid)) #MainContent > .shopify-section:first-child:not(:has(.collection-banner--under-header, .hero, .video-banner)) > * {
    border-block-start: var(--header-space) solid transparent;
  }

  /*
    A first section set to "Fill the screen height" (404, About hero): it already slides up under the
    header (above), so it is exactly one screen tall. The older rule (critical.css / screen-scale,
    100svh minus the header) subtracted the header a second time, and the footer showed at the bottom.
  */
  body:has(sticky-header):not(:has(.header--transparent, .header--solid)) #MainContent > .shopify-section:first-child:not(:has(.collection-banner--under-header, .hero, .video-banner)) .section--fill-screen {
    min-block-size: 100svh;
  }

  /*
    While a side drawer (filters, phone menu) is open, the header sits under the dimmed backdrop and can't be
    used, so its glass blur is switched off. Chrome otherwise composites the blurred page behind the pill
    differently from the rest of the dimmed page: a lighter/darker block showed where the banner photo starts.
  */
  html:has(.filter-drawer__dialog[open], .header-drawer__dialog[open]) .header .header__bar,
  html:has(.filter-drawer__dialog[open], .header-drawer__dialog[open]) .header__icon-button:not(.header-drawer__close) {
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  /*
    "At rest" = transparent header, page at the top, nobody using the header with the keyboard and no menu open.
    Then: no pill surface, the bar spans the page, and the logo and menu fade out (still focusable,
    so a keyboard user who tabs into the header brings the full pill back; :focus-visible means keyboard
    focus only, so a mouse click on a button doesn't flash the pill).
  */
  .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open])) .header__bar {
    max-inline-size: 100%;
    background-color: transparent;
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
    pointer-events: none; /* the bar is invisible and page-wide here, so let clicks through to the hero */
  }

  /* ...except the buttons, which stay visible and clickable */
  .header--transparent .header__actions {
    pointer-events: auto;
  }

  .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open]))
    :is(.header__logo, .header__menu) {
    opacity: 0;
    pointer-events: none;
  }

  .header--transparent :is(.header__logo, .header__menu) {
    transition: opacity var(--duration-base) var(--ease-out);
  }

  /* The actions stay at the right edge in both states */
  .header__actions {
    margin-inline-start: var(--actions-start, auto);
  }

  @media (prefers-reduced-motion: reduce) {
    .header .header__bar,
    .header--transparent :is(.header__logo, .header__menu) {
      transition: none;
    }
  }

  /*
    flex: 0 1 auto + min-inline-size 0: when the bar is too narrow, only the logo gives up space (the menu and
    the buttons have flex-shrink: 0), so the menu stays on one line. A long logo text is cut with … (below).
  */
  .header__logo {
    display: flex;
    align-items: center;
    gap: 0.625rem;
    flex: 0 1 auto;
    min-block-size: 1.5rem;
    color: var(--color-text);
    text-decoration: none;
  }

  /* Wide, square and tall logos: fixed width, height follows, but never taller than 4rem */
  .header__logo-image {
    flex-shrink: 0;
    inline-size: var(--logo-width);
    block-size: auto;
    max-block-size: 3.25rem; /* fits inside the 77px pill */
    object-fit: contain;
  }

  /* Text logo (Figma: Cormorant Garamond SemiBold 46.78px, line-height 100%; accent word italic, primary).
     The size follows the "Logo text size" setting and scales down on small screens. */
  .header__logo-text {
    color: var(--color-text);
    font-family: var(--font-logo--family);
    font-size: calc(clamp(min(1.75rem, var(--logo-text-size)), 1.4rem + 1.4vw, var(--logo-text-size)) * var(--logo-text-scale, 1)); /* never above the setting */
    font-weight: var(--font-logo--weight);
    line-height: 1;
    letter-spacing: 0;
  }

  /* The accent word follows the header's colour scheme (--color-accent), so it stays readable on red / dark schemes */
  .header__logo-text em {
    color: var(--color-accent);
    font-style: italic;
  }

  /* They never shrink: only the logo gives up space (see .header__logo), so a menu word never wraps */
  .header__menu,
  .header__actions {
    display: flex;
    flex-shrink: 0;
    align-items: center;
    gap: var(--space-md);
  }

  /* Hidden in the menu-button layout (its items are in the drawer) */
  .header__menu {
    display: var(--menu-display, flex);
  }

  /* Header actions (Figma): round glass icon buttons, then the red LOGIN pill */
  .header {
    --icon-size: 1.25rem;
  }

  /* The cart link's wrapper adds no box of its own: the link stays a direct flex item of the icon row */
  cart-count {
    display: contents;
  }

  .header__icon-button {
    position: relative;
    display: inline-grid;
    place-items: center;
    inline-size: 3.125rem; /* 50px, Figma "Liquid Glass Button" */
    block-size: 3.125rem;
    padding: var(--space-xs);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass);
    box-shadow: var(--shadow-header);
    color: var(--color-text);
    text-decoration: none;
    transition:
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  /* After a background add, the flying product photo lands here: a short bump (Buy buttons adds the class) */
  @media (prefers-reduced-motion: no-preference) {
    .is-cart-bump {
      animation: cart-bump 0.45s var(--ease-out);
    }
  }

  @keyframes cart-bump {
    35% {
      scale: 1.2;
    }

    65% {
      scale: 0.94;
    }
  }

  /* Keyboard focus looks like hover (filled glass, accent icon), plus the focus ring */
  .header__icon-button:is(:hover, :focus-visible) {
    background-color: var(--color-glass-strong);
    color: var(--color-accent);
  }

  .header__icon-button svg {
    inline-size: var(--icon-size);
    block-size: var(--icon-size);
  }

  /* Item count bubble on the cart (Figma: small red circle, top right). The scheme's button colours, so it follows the scheme */
  .header__count {
    position: absolute;
    inset-block-start: -0.125rem;
    inset-inline-end: -0.125rem;
    display: inline-grid;
    place-items: center;
    min-inline-size: 1.25rem;
    block-size: 1.25rem;
    padding-inline: 0.3rem;
    border-radius: var(--radius-pill);
    background-color: var(--color-button);
    color: var(--color-button-text);
    font-size: 0.6875rem;
    font-weight: var(--font-weight-medium);
    line-height: 1;
    font-variant-numeric: tabular-nums;
  }

  /*
    Account: Shopify's <shopify-account> (see the markup). Its own button (part "signed-out-avatar") is
    reset to a bare click target, so our LOGIN pill in the slot shows as before. Signed in, the component
    draws the initial: its CSS variables give it the size and colours of our round glass buttons, and the
    host carries the glass shadow. The account sheet takes the header scheme's colours, the theme fonts and
    the theme corners. Shopify can update the component; only these variables and the part are styled.
  */
  .header__account {
    --shopify-account-color-background: var(--color-background);
    --shopify-account-color-text: var(--color-text);
    --shopify-account-color-accent: var(--color-button, var(--color-accent));
    --shopify-account-color-accent-text: var(--color-button-text, var(--color-background));
    --shopify-account-font-body: var(--font-body--family);
    --shopify-account-font-heading: var(--font-heading--family);
    --shopify-account-radius-base: var(--radius-md);
    --shopify-account-dialog-position-top: var(--header-space);
    --shopify-account-avatar-size: 3.125rem;
    --shopify-account-signed-in-avatar-size: 3.125rem;
    --shopify-account-signed-in-avatar-color-background: var(--color-glass-strong);
    --shopify-account-signed-in-avatar-color-text: var(--color-accent);

    display: inline-flex;
    flex-shrink: 0;
  }

  .header__account--signed-in {
    border-radius: var(--radius-pill);
    box-shadow: var(--shadow-header);
  }

  /* Shopify gives its button a ~50px minimum size: our pill in the slot sets the size instead */
  .header__account::part(signed-out-avatar) {
    display: inline-flex;
    min-inline-size: 0;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background: none;
    color: inherit;
    cursor: pointer;
  }

  .header__account::part(signed-out-avatar):focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .header__login {
    gap: var(--space-xs);
    padding-inline: var(--space-xl);
  }

  .header__login svg {
    inline-size: var(--icon-size);
    block-size: var(--icon-size);
  }

  /* The menu button stays clickable while a transparent header is "at rest" (like the actions) */
  .header--transparent .header-drawer__toggle {
    pointer-events: auto;
  }

  /*
    Menu button layout: logo | buttons | menu button; the menu items are in the drawer.
    Phones (below 768px) always use it. Header setting "Show the menu button below" uses it on tablets too:
    990 = below 990px, 1200 = below 1200px (the class header--menu-button-990 / -1200).
    A media query can't read a setting, so each width range sets four variables on the header for the
    classes that apply there, and the layout rules read them (one set of rules for every case):
    --bar-display (grid), --menu-display (none), --drawer-display (contents: the menu button shows),
    --actions-start (0: the buttons sit in their grid column, not pushed right).
    --logo-overflow (hidden: a long logo is cut in its column instead of pushing the buttons out).
    KEEP THE THREE BLOCKS BELOW THE SAME: they hold the same five values. (One copy would need CSS style
    queries, which Firefox doesn't support, or JavaScript.) A missing value breaks only that width range.
    On tablets the logo, search, cart and LOGIN keep their tablet sizes; the phone sizes are further below.
  */
  @media (max-width: 767px) {
    .header {
      --bar-display: grid;
      --menu-display: none;
      --drawer-display: contents;
      --actions-start: 0;
      --logo-overflow: hidden;
    }
  }

  @media (min-width: 768px) and (max-width: 989px) {
    .header--menu-button-990,
    .header--menu-button-1200 {
      --bar-display: grid;
      --menu-display: none;
      --drawer-display: contents;
      --actions-start: 0;
      --logo-overflow: hidden;
    }
  }

  @media (min-width: 990px) and (max-width: 1199px) {
    .header--menu-button-1200 {
      --bar-display: grid;
      --menu-display: none;
      --drawer-display: contents;
      --actions-start: 0;
      --logo-overflow: hidden;
    }
  }

  /*
    The grid of the menu-button layout: logo (takes what is left, may shrink to 0) | buttons | menu button.
    These only act while the bar is a grid; the full layout (flexbox) ignores grid placement.
  */
  .header__bar {
    grid-template-columns: minmax(0, 1fr) auto auto;
  }

  .header__logo {
    grid-column: 1;
    grid-row: 1;
    justify-self: start;
    min-inline-size: 0; /* a grid item won't shrink below its content without this */
    max-inline-size: 100%;
    overflow: var(--logo-overflow, visible); /* clips a long logo in the narrow grid column only */
  }

  /*
    With a logo image, the logo never gets narrower than the image (it does not shrink): only the text gives
    up its space, so the image can't spill over the menu. 100% keeps it inside a narrow grid column.
  */
  .header__logo:has(.header__logo-image) {
    min-inline-size: min(var(--logo-width), 100%);
  }

  .header__actions {
    grid-column: 2;
    grid-row: 1;
  }

  /* Menu button: a plain icon inside the pill (Figma), 44px tap area. Only shown in the menu-button layout. */
  .header .header-drawer__toggle {
    grid-column: 3;
    grid-row: 1;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    border: 0;
    background-color: transparent;
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .header .header-drawer__toggle:is(:hover, :focus-visible) {
    background-color: transparent;
    color: var(--color-accent);
  }

  /*
    At rest over the hero there is no pill behind it: the glass circle like search and cart (no border).
    40px; on phones the smaller at-rest size (--rest-button).
  */
  .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open]))
    .header-drawer__toggle {
    inline-size: var(--rest-button, 2.5rem);
    block-size: var(--rest-button, 2.5rem);
    background-color: var(--color-glass);
    box-shadow: var(--shadow-header);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .header-drawer__toggle svg {
    inline-size: 1.125rem;
    block-size: auto;
  }

  /*
    Below 1200px (tablets and phones) the pill is smaller: 60px tall, 12px from the top and the sides, so the
    first-section pull-ups use --header-space (72px). What goes inside the pill depends on the width:
    - 768-1199px (tablets, small laptops): the desktop layout, scaled down (logo, full menu, search, cart, LOGIN),
      or the menu-button layout when the "Show the menu button below" setting covers this width.
    - below 768px (phones, Figma mobile pill): logo | menu button; the drawer holds the rest.
  */
  @media (max-width: 1199px) {
    .header {
      --icon-size: 1.125rem;

      /* A 12px gap all round: the page margins would leave the content too little room */
      padding-block-start: var(--space-sm);
      padding-inline: var(--space-sm);
    }

    /*
      The section's content grid adds the page margins; the pill spans the whole width instead.
      (Section class + element: beats critical.css's ".shopify-section > *" column rule.)
    */
    .shopify-section-group-header-group > sticky-header {
      grid-column: 1 / -1;
    }

    .header__bar {
      block-size: 3.75rem; /* 60px */
    }

    /* The buttons in the bar: 40px glass circles (smaller than desktop's 50px), never squeezed */
    .header__actions .header__icon-button {
      flex-shrink: 0;
      inline-size: 2.5rem;
      block-size: 2.5rem;
    }

    .header__login svg {
      inline-size: 1rem;
      block-size: 1rem;
    }

    /* The signed-in initial: the same 40px as the other round buttons */
    .header__account {
      --shopify-account-avatar-size: 2.5rem;
      --shopify-account-signed-in-avatar-size: 2.5rem;
    }

    /* Solid background: the same 12px under the small pill as above it */
    .header--solid {
      padding-block-end: var(--space-sm);
    }

    :root:has(.header--solid) {
      --header-space: calc(3.75rem + var(--space-sm) * 2);
    }

    /* The small pill: 12px gap + 60px pill (every pull-up above uses it, so they follow on their own) */
    :root {
      --header-space: calc(3.75rem + var(--space-sm));
    }
  }

  /*
    Tablets and small laptops (768-1199px): the desktop layout with small adjustments so it fits at 768px:
    a smaller logo, menu text and gaps, 40px buttons and a compact LOGIN pill. The mega menu opens under the
    pill as on desktop, with less padding.
  */
  @media (min-width: 768px) and (max-width: 1199px) {
    .header__bar {
      gap: var(--space-md);
      padding-inline: var(--space-lg) var(--space-xs);
    }

    /*
      The desktop's fluid size (33px at 768px, 37px at 1024px, 39px at 1199px: no jump at 1200px), never
      above the "Logo text size" setting and never above 40px, so it fits the 60px pill.
    */
    .header__logo-text {
      font-size: calc(clamp(min(1.75rem, var(--logo-text-size)), 1.4rem + 1.4vw, min(var(--logo-text-size), 2.5rem)) * var(--logo-text-scale, 1));
    }

    /* The logo image grows the same way: 28px tall at 768px up to 36px, never wider than the Logo width setting */
    .header__logo-image {
      inline-size: auto;
      max-inline-size: var(--logo-width);
      block-size: clamp(1.75rem, 1rem + 1.6vw, 2.25rem);
    }

    .header .menu {
      gap: clamp(var(--space-sm), 2vw, var(--space-xl));
    }

    .header .menu__link {
      font-size: clamp(0.75rem, 1.15vw, 0.9375rem);
    }

    .header__actions {
      gap: var(--space-xs);
    }

    .header .header__login {
      gap: var(--space-2xs);
      block-size: 2.5rem;
      min-block-size: 2.5rem;
      padding-inline: var(--space-md);
      white-space: nowrap;
    }

    .header .menu__panel {
      inset-block-start: calc(100% + var(--space-sm));
      padding: var(--space-md) var(--space-lg) var(--space-lg);
    }
  }

  /*
    Phones (below 768px), Figma mobile pill: logo (left) | menu button (right). The menu, account, search and
    cart move into the drawer (snippets/header-drawer.liquid); search and cart can stay in the bar (settings
    "Small screens"). The logo column is the only one that gives way when space runs short (minmax(0, 1fr)).
    At rest on a transparent header the logo is hidden as on desktop: the hero shows its own logo there.
  */
  @media (max-width: 767px) {
      /*
        Columns: logo (takes what is left, may shrink to 0) | optional search + cart | menu button.
        Figma mobile pill: 58px tall, ~24px inside padding, the logo on the left and a plain menu icon on the right.
      */
      .header__bar {
        gap: var(--space-xs);
        padding-inline: var(--space-lg) var(--space-sm);
      }

      .header__logo {
        gap: var(--space-xs);
      }

      /* A small mark, a big word: 26px on a 320px phone, 30px at 375px, up to 32px on tablets */
      .header__logo-text {
        font-size: calc(clamp(1.625rem, 8vw, 2rem) * var(--logo-text-scale, 1));
      }

      /* Sized by height in the small pill (26px), never wider than the Logo width setting or the column */
      .header__logo-image {
        flex-shrink: 0;
        inline-size: auto;
        max-inline-size: min(var(--logo-width), 100%);
        block-size: 1.625rem;
      }

      .header__actions {
        gap: var(--space-2xs);
      }

      /*
        Search and cart live in the drawer here; they can stay in the bar (header settings "Small screens"
        add header--m-search / header--m-cart). Only the search BUTTON is hidden: its popup <dialog> sits in
        the same element and must still open from the drawer. The account button always stays in the bar
        (Theme Store: <shopify-account> visible in the mobile header), as a round icon (below).
      */
      .header:not(.header--m-search) .header__actions [data-search-open],
      .header:not(.header--m-cart) .header__actions cart-count > a {
        display: none;
      }

      /*
        Transparent header at rest (top of the homepage, Figma mobile hero): no pill and no logo (the hero has
        its own), so there is room for search and cart in the bar too. Once the page scrolls they go back
        into the drawer. (This selector outweighs the hiding rule above.)
        At rest the round buttons sit straight on the hero photo, so they are smaller than in the pill
        (36px circles, 16px icons) and cover less of the photo. --rest-button / --icon-size are read by
        search, cart, the account button and the menu button below. Once the page scrolls, the pill's sizes
        (40px, 18px) come back.
      */
      .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open])) {
        --rest-button: 2.25rem;
        --icon-size: 1rem;
      }

      .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open]))
        .header__actions
        :is([data-search-open], cart-count > a) {
        display: inline-grid; /* the round button's own display: centres the icon (place-items) */
        inline-size: var(--rest-button);
        block-size: var(--rest-button);
      }

      /* The account on phones: a round icon button like search and cart (LOGIN signed out, the initial signed in) */
      .header__account {
        --shopify-account-avatar-size: var(--rest-button, 2.5rem);
        --shopify-account-signed-in-avatar-size: var(--rest-button, 2.5rem);
      }

      /* Two classes: the global .button rule loads after this file and beats one class */
      .header .header__login {
        justify-content: center;
        inline-size: var(--rest-button, 2.5rem);
        min-inline-size: 0;
        min-block-size: var(--rest-button, 2.5rem);
        padding: 0;
      }

      /* The word LOGIN is only for screen readers on phones */
      .header__login-text {
        position: absolute;
        inline-size: 1px;
        block-size: 1px;
        overflow: hidden;
        clip-path: inset(50%);
        white-space: nowrap;
      }

      .header__login svg {
        inline-size: var(--icon-size);
        block-size: var(--icon-size);
      }

      /* The menu icon at rest: the same 16px as search and cart */
      .header--transparent:not(.is-scrolled):not(:has(:focus-visible)):not(:has(.menu__dropdown[open]))
        .header-drawer__toggle
        svg {
        inline-size: var(--icon-size);
      }
  }

/* sections/hero.liquid */

  /*
    Layers: the photo fills the section (z 0), an optional overlay tints it for readability, the content
    sits on top on the left. The section's colour scheme sets the text colours (Figma: dark text on the
    light plaster side).
  */
  hero-showcase {
    display: flex;
  }

  .hero {
    position: relative;
    isolation: isolate;
    display: flex;
    align-items: center;
    overflow: hidden;
    background-color: var(--color-background);
  }

  .hero--height-full {
    min-block-size: 100svh;
  }

  .hero--height-large {
    min-block-size: 80svh;
  }

  .hero--height-medium {
    min-block-size: 60svh;
  }

  /*
    A top announcement bar sits in normal flow ABOVE the hero (it's in the Header group and scrolls away),
    so it pushes the hero down and the bottom of a full-height hero falls below the screen. Take the bar's
    height off the full-height hero so it fits the first screen exactly. --announcement-size is set on :root
    by the announcement bar section (default 36px). The rule falls away on its own when the bar is closed
    ([hidden]) or set to the right-side band (only announcement-bar--top matches).
    Desktop only (min-width 1024px): below that the hero with a Mobile image is sized from the photo's
    ratio (see .hero--has-mobile), and this must not override that fixed height.
  */
  @media (min-width: 1024px) {
    body:has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .hero--height-full {
      min-block-size: calc(100svh - var(--announcement-size, 2.25rem));
    }

    /*
      The bar AND a solid header ("Solid header background") sit above the hero: take both off. (The rule
      above is stronger than the solid-header rule further down, so this case needs its own rule.)
    */
    body:has(.header--solid):has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .hero--height-full {
      min-block-size: calc(100svh - var(--header-space) - var(--announcement-size, 2.25rem));
    }

    /*
      When the bar is closed it collapses to nothing and stops matching the rule above, so the hero grows
      back to the full screen. Easing that change keeps it in step with the bar's own collapse.
    */
    @media (prefers-reduced-motion: no-preference) {
      #MainContent > .shopify-section:first-child .hero--height-full {
        transition: min-block-size var(--duration-base, 300ms) var(--ease-out);
      }
    }
  }

  /*
    The hero is the page's first section and the header is NOT transparent (logo and menu always show):
    header.liquid slides the hero up under the pill, so the image fills the top of the page behind the
    glass. The text moves down by the header's height (--header-space, set by header.liquid), so the pill
    never covers it. A transparent header needs no offset (its logo and menu are hidden at rest, the Figma
    hero's own logo sits level with the buttons), and a solid header keeps the hero below it.
  */
  body:has(sticky-header):not(:has(.header--transparent, .header--solid)) #MainContent > .shopify-section:first-child .hero {
    --hero-header-offset: var(--header-space);
  }

  /* A solid header keeps the hero below it: a full-height hero fills the rest of the first screen */
  body:has(.header--solid) #MainContent > .shopify-section:first-child .hero--height-full {
    min-block-size: calc(100svh - var(--header-space));
  }

  .hero__media {
    position: absolute;
    inset: 0;
    z-index: -2;
  }

  .hero__media .image {
    block-size: 100%;
  }

  .hero__placeholder {
    inline-size: 100%;
    block-size: 100%;
    background-color: var(--color-tint-subtle);
    fill: var(--color-tint-border);
  }

  /* Optional tint over the photo, in the scheme's background colour (0 = none, the Figma default) */
  .hero::before {
    content: '';
    position: absolute;
    inset: 0;
    z-index: -1;
    background-color: color-mix(in srgb, var(--color-background) var(--hero-overlay), transparent);
    pointer-events: none;
  }

  /*
    Content column, measured from the SCREEN edge, not the page width: the Figma hero is a full-screen
    composition (content ~90px from the left at 1920 = 4.7vw), so on a wide monitor the text stays on
    the plaster side of the photo instead of drifting towards the middle.
  */
  /*
    Sizes in the settings are the sizes at the 1920px Figma frame (plain numbers, so CSS can do maths
    with them). --hero-px turns one of those design pixels into a real length:
    - Fixed: 1px.
    - Scale with screen: the Figma frame fitted to the window (see below), so the whole composition grows
      on a 2560 monitor and shrinks on a laptop, keeping the Figma's proportions. max() keeps a minimum on
      small screens.
  */
  /*
    --hero-bottom-space: the room under the content, shared by the pause button so the two line up: the
    button is centred on the content's last row on every screen (see .hero__pause).
    At least 48px (64px on phones, below), more when "Bottom padding" asks for it.
  */
  .hero {
    --hero-px: 1px;
    --hero-bottom-space: max(var(--space-2xl), calc(var(--hero-pad-bottom) * var(--hero-px)));
  }

  /*
    The Figma frame is 1920 x 1031. Scaling by the smaller of the two ratios (width or height) fits the
    whole composition on screen: a wide-but-short laptop window scales by its height, so the content
    never makes the hero taller than the screen; a tall window scales by its width.
  */
  .hero--scale-screen {
    --hero-px: min(calc(100vw / 1920), calc(100svh / 1031));

    /* The theme's type sizes, redefined for this section as their Figma size x screen ratio */
    --font-size-display-xl: max(3.5rem, calc(108 * var(--hero-px)));
    --font-size-display: max(3rem, calc(96 * var(--hero-px)));
    --font-size-h1: max(2.25rem, calc(60 * var(--hero-px)));
    --font-size-h2: max(1.75rem, calc(40 * var(--hero-px)));
    --font-size-h3: max(1.375rem, calc(26 * var(--hero-px)));
    --font-size-body-lg: max(1.125rem, calc(22 * var(--hero-px)));
    --font-size-body: max(1rem, calc(20 * var(--hero-px)));
    --font-size-body-sm: max(0.9375rem, calc(18 * var(--hero-px)));
    --font-size-caption: max(0.875rem, calc(16 * var(--hero-px)));
    --font-size-label: max(0.875rem, calc(18 * var(--hero-px)));
    --font-size-small: max(0.8125rem, calc(14 * var(--hero-px)));
  }

  /*
    Phones (below 750px, Figma mobile hero at 375px): the 1920-frame maths gives sizes far too small there, and
    the max() floors above are desktop minimums (a 56px display line on a 320px screen). Each size here grows with
    the screen width (vw) between a phone minimum and a tablet maximum. The minimums keep small phones (320px)
    at the 375px Figma size: "Unveil your" (display) 34px, "It is time to" / "Ultimate glow" (h1) 24px, the
    subheading (h3) 17px, the paragraph 15px, buttons 15px. Applies with either Text scaling option.
  */
  @media (max-width: 749px) {
    .hero {
      --font-size-display-xl: clamp(2.375rem, 10vw, 3.25rem);
      --font-size-display: clamp(2.125rem, 9vw, 3rem);
      --font-size-h1: clamp(1.5rem, 6.4vw, 2.25rem);
      --font-size-h2: clamp(1.375rem, 5.4vw, 1.75rem);
      --font-size-h3: clamp(1.0625rem, 4.27vw, 1.375rem);
      --font-size-body-lg: clamp(0.9375rem, 4vw, 1.125rem);
      --font-size-body: clamp(0.9375rem, 3.8vw, 1rem);
      --font-size-body-sm: clamp(0.875rem, 3.6vw, 0.9375rem);
      /* Button text (caption): 15px on phones up to 375px, then up to 16px, so it fills the pill */
      --font-size-caption: clamp(0.9375rem, 4vw, 1rem);
      --font-size-label: clamp(0.9375rem, 4vw, 1rem);
      --font-size-small: clamp(0.75rem, 3.2vw, 0.8125rem);
    }

    /*
      Room at the bottom: 64px under the last row ("New arrivals") on phones, so it and the pause button next
      to it never hug the bottom of the screen (or the browser's toolbar). ".hero" in front of .hero__pause:
      this rule comes before the base one further down, so it needs the extra class to win.
    */
    .hero {
      --hero-bottom-space: max(var(--space-3xl), calc(var(--hero-pad-bottom) * var(--hero-px)));
    }

    .hero .hero__pause {
      inset-block-end: calc(var(--hero-bottom-space) - 0.625rem);
      inset-inline-end: var(--space-md);
    }

    /*
      Buttons: the global pill is 50px tall with 35px sides (desktop Figma). On a phone that left the text
      looking small inside a big pill, so the pill is sized to the text instead: 46px tall, 24px sides.
    */
    .hero .button:not(.button--text) {
      min-block-size: 2.875rem;
      padding-inline: var(--space-lg);
    }
  }

  /*
    The content layer spans the full width over the product area, so it lets the pointer through
    (pointer-events: none) and only the content column takes clicks again: otherwise hovering or
    clicking a product would never reach it.
  */
  .hero__inner {
    position: relative;
    z-index: 1;
    display: flex;
    inline-size: 100%;
    pointer-events: none;
    padding-block:
      calc(max(var(--space-2xl), calc(var(--hero-pad-top) * var(--hero-px))) + var(--hero-header-offset, 0px))
      var(--hero-bottom-space);
    padding-inline: max(var(--page-margin), calc(var(--hero-pad-side) * var(--hero-px)));
    /* Section width: Full (default, Figma) = from the screen edge; Wide / Narrow = a centred column */
    max-inline-size: var(--section-width, 100vw);
    margin-inline: auto;
  }

  /* Content position: horizontal (start / center / end) */
  .hero--x-start .hero__inner { justify-content: flex-start; }
  .hero--x-center .hero__inner { justify-content: center; }
  .hero--x-end .hero__inner { justify-content: flex-end; }

  .hero--x-center .hero-content { align-items: center; }
  .hero--x-end .hero-content { align-items: flex-end; }

  /*
    Content spacing. "Gap" = the Content block's fixed gap. The other three spread the blocks over the
    full height of the hero (minus its padding), so the space adapts to each screen's height:
    - between: first block at the top, last at the bottom, equal space in between
    - around: equal space around each block (half-size space at the very top and bottom)
    - evenly: exactly equal space everywhere, top and bottom included
    For that, the content column stretches to the hero's height (vertical position no longer applies).
  */
  .hero:not(.hero--spacing-gap) {
    align-items: stretch;
  }

  .hero:not(.hero--spacing-gap) .hero__content {
    display: flex;
    flex-direction: column;
  }

  .hero:not(.hero--spacing-gap) .hero-content {
    flex: 1;
  }

  .hero--spacing-between .hero-content { justify-content: space-between; }
  .hero--spacing-around .hero-content { justify-content: space-around; }
  .hero--spacing-evenly .hero-content { justify-content: space-evenly; }

  /* Content position: vertical (start / center / end), inside the section's height */
  .hero--y-start { align-items: flex-start; }
  .hero--y-center { align-items: center; }
  .hero--y-end { align-items: flex-end; }

  /*
    The content box: position for the decoration layer (inset 0 = exactly this box), isolation so
    decorations and text stack only against each other (Layer 1-9 behind, text 10, 11-20 in front).
  */
  .hero__content {
    position: relative;
    isolation: isolate;
    pointer-events: auto;
    max-inline-size: calc(var(--hero-content-width) * var(--hero-px));
  }

  /*
    Product area: from "Products area start" to the right edge, full height; products are % inside it.
    (A right-side Announcement bar band keeps its own room: the page leaves its width free.)
  */
  .hero__products {
    position: absolute;
    inset-block: 0;
    inset-inline-start: var(--hero-products-start);
    inset-inline-end: 0;
  }



  /*
    When the active product changes, only the brush WORD fades out and back in: the script wraps the
    word in .hero-brush-text, so the red brush (drawn by the em's ::before) stays still.
  */
  .hero-brush-text {
    display: inline-block;
    min-inline-size: var(--brush-word-width, auto); /* the widest brush word: the brush keeps one size */
    text-align: center;
    white-space: nowrap; /* one line: a word that wrapped inside the brush would run past it */
    transition: opacity var(--duration-base) var(--ease-out), scale var(--duration-base) var(--ease-out);
  }

  .hero-brush-text.is-swapping {
    opacity: 0;
    scale: 0.9;
  }

  @media (prefers-reduced-motion: reduce) {
    .hero-brush-text {
      transition: none;
    }
  }

  /* Pause / play: a small round glass button, bottom right (left of the brand band, when there is one) */
  /*
    Centred on the content's last row. Large screens: the 50px button row, so the 44px button sits 3px above
    the content's bottom. Phones (below): the "New arrivals" link alone on the last line (24px), so 10px below.
  */
  .hero__pause {
    position: absolute;
    inset-block-end: calc(var(--hero-bottom-space) + 0.1875rem);
    inset-inline-end: var(--space-lg);
    z-index: 3;
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    margin: 0;
    padding: 0;
    border: 1px solid #ffffff;
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong);
    box-shadow: var(--shadow-header);
    color: var(--color-text);
    cursor: pointer;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .hero__pause[hidden] {
    display: none;
  }

  .hero__pause-icon--play,
  .hero__pause[aria-pressed='true'] .hero__pause-icon--pause {
    display: none;
  }

  .hero__pause[aria-pressed='true'] .hero__pause-icon--play {
    display: block;
  }

  /* Paused: decorations freeze where they are (and the rotation stops, in the script) */
  .hero--paused .hero-decoration {
    animation-play-state: paused !important;
  }

  /*
    Smaller screens (no mobile design yet, decision 7): the content spans the width and a light tint
    keeps the text readable over the photo.
  */
  @media (max-width: 989px) {
    .hero::before {
      background-color: color-mix(in srgb, var(--color-background) 55%, transparent);
    }

    .hero__content {
      max-inline-size: none;
    }

    /* Products need the photo's shelves to sit on, so they are hidden where the layout stacks */
    .hero__products {
      display: none;
    }
  }

  /*
    Entrance on page load (pure CSS, starts at first paint: no script to wait for, so it can't leave the
    hero hidden). The background photo never animates, and the products show within 0.2s (one of them
    can be the LCP image, see hero-grow). Only with the theme's animations on (the
    .animations-on class, which is also off in the theme editor) and not with reduced motion.
    - Content rows slide in from the left, one after another.
    - The logo (an Image block in the content) drops in from the top instead.
    - Product images grow from their base like a flower opening: half size -> slightly too big -> settle.
      `transform` adds on top of their translate / rotate, so they keep their place and tilt.
  */
  @media (prefers-reduced-motion: no-preference) {
    .animations-on .hero-content > * {
      animation: hero-in-left 0.8s var(--ease-out) both;
    }

    .animations-on .hero-content > .image-block {
      animation-name: hero-in-top;
    }

    .animations-on .hero-content > :nth-child(2) { animation-delay: 0.12s; }
    .animations-on .hero-content > :nth-child(3) { animation-delay: 0.24s; }
    .animations-on .hero-content > :nth-child(4) { animation-delay: 0.36s; }
    .animations-on .hero-content > :nth-child(5) { animation-delay: 0.48s; }
    .animations-on .hero-content > :nth-child(n + 6) { animation-delay: 0.6s; }

    .animations-on .hero-product {
      transform-origin: 50% 100%;
      animation: hero-grow 1s var(--ease-out) both; /* all products bloom together, straight away */
    }
  }

  /*
    Starts half visible (0.5), not hidden (0): the headline is readable from the first paint (decision 3:
    never hide the hero content), and the browser can count it for LCP straight away on phones, where the
    <h1> can be the largest element.
  */
  @keyframes hero-in-left {
    from {
      opacity: 0.5;
      transform: translateX(-3rem);
    }
  }

  @keyframes hero-in-top {
    from {
      opacity: 0.5;
      transform: translateY(-2rem);
    }
  }

  /*
    Starts at half size and fades in over the first 0.2s, so a tiny product is never seen. No delay and a
    short fade: a product image can be the page's LCP element, and the browser only counts an image
    once it is visible, so it must show almost at once.
  */
  @keyframes hero-grow {
    0% {
      opacity: 0;
      transform: scale(0.5);
    }

    20% {
      opacity: 1;
    }

    60% {
      transform: scale(1.06);
    }

    100% {
      transform: none;
    }
  }


  /*
    Phones and tablets with a Mobile image (below 1024px, Figma mobile hero / "product scene showcase"): one
    tall photo, the text over its top, the products on its shelves.
    - The hero is exactly the photo's shape at the screen width (100vw / its width:height ratio): the photo is
      shown whole, never stretched or cropped, on every phone. The section's Height setting doesn't apply here.
    - "Text area height" (mobile_products_start, e.g. 46%) = how much of the top the text may use: the text's
      bottom padding is the rest of the photo + 16px. The products area is the whole photo, so a product at
      68% / 61% always sits on the same shelf.
    - "Text width" (e.g. 100%) = the text column's width.
    - The hero never grows: if the text is taller than its area, the merchant raises Text area height, shortens
      the text or hides the paragraph (Text block: Hide on phones).
    Placed after the 989px rules on purpose: same specificity, so the later rule wins (tint, hidden products).
    Note: a tall photo on a wide tablet makes a tall hero (about 2 screens at 1024px held upright).
  */
  @media (max-width: 1023px) {
    .hero.hero--has-mobile {
      --hero-m-height: calc(100vw / var(--hero-m-ratio));
      align-items: flex-start;
      min-block-size: 0;
      block-size: var(--hero-m-height);
    }

    .hero--has-mobile .hero__content {
      max-inline-size: var(--hero-m-text-width, 100%);
    }

    /* The gap between the content's rows: the 1920-frame maths makes it ~5px here, so a fixed 16px (Figma) */
    .hero--has-mobile .hero-content {
      gap: var(--space-md);
    }

    /* Figma: the logo sits at the top, level with the header's buttons (the header floats over the hero) */
    .hero--has-mobile .hero__inner {
      padding-block-start: calc(var(--space-sm) + var(--hero-header-offset, 0px));
    }

    /* A row of buttons that wraps (Explore collection / New arrivals): 16px between the lines, not the desktop 48px */
    .hero--has-mobile .group--horizontal {
      gap: var(--space-md) var(--space-lg);
    }


    /* The Figma mobile hero has no tint: back to the Overlay setting (0 by default) */
    .hero--has-mobile::before {
      background-color: color-mix(in srgb, var(--color-background) var(--hero-overlay), transparent);
    }

    /*
      The text area is a real box: the top "Text area height" (e.g. 46%) of the photo, minus 16px above the
      shelves. The text sits in it by the section's own options, so the setting visibly moves it:
      - Content spacing Between / Around / Evenly: the rows spread over the whole area (logo at the top,
        buttons at its bottom, as in the Figma);
      - Content spacing Gap: the rows stay together, placed by Vertical position (top / center / bottom).
      (box-sizing: border-box, so the height includes the 12px top and 16px bottom padding.)
    */
    .hero--has-mobile .hero__inner {
      box-sizing: border-box;
      block-size: calc(var(--hero-m-height) * var(--hero-m-start) / 100);
      padding-block-end: var(--space-md);
      align-items: flex-start;
    }

    .hero--has-mobile.hero--y-center .hero__inner {
      align-items: center;
    }

    .hero--has-mobile.hero--y-end .hero__inner {
      align-items: flex-end;
    }

    .hero--has-mobile:not(.hero--spacing-gap) .hero__inner {
      align-items: stretch;
    }

    /* The products area = the whole photo (the hero is exactly its shape) */
    .hero--has-mobile .hero__products {
      display: block;
      inset: auto 0 0;
      z-index: 2;
      block-size: var(--hero-m-height);
      pointer-events: none;
    }

    /* Each product's Phones settings (set as variables on the product, see blocks/_hero-product.liquid) */
    .hero--has-mobile .hero-product {
      inset-inline-start: var(--hero-product-mx);
      inset-block-start: var(--hero-product-my);
      inline-size: var(--hero-product-mw);
      pointer-events: auto;
    }

    .hero--has-mobile .hero-product__label {
      inset-inline-start: var(--hero-label-mx);
      inset-block-start: var(--hero-label-my);
      font-size: clamp(1.25rem, 6vw, 1.75rem); /* Figma ~22px at 375px */
    }

    /* Decorations: only those with "Show on phones", at their Phones position and size (real px) */
    .hero--has-mobile .hero-decorations {
      display: block;
    }

    .hero--has-mobile .hero-decoration {
      inset-inline-start: var(--deco-mx);
      inset-block-start: var(--deco-my);
      inline-size: calc(var(--deco-msize) * 1px);
    }

    .hero--has-mobile .hero-decoration:not(.hero-decoration--phone) {
      display: none;
    }

    /* The pause button sits over the shelves, bottom right (the text's bottom space is the shelf area here) */
    .hero--has-mobile .hero__pause {
      inset-block-end: var(--space-md);
    }
  }

/* sections/icon-features.liquid */

  .icon-features {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .icon-features-empty {
    padding: var(--space-2xl) var(--page-margin);
    text-align: center;
  }

  .icon-features__inner {
    container-type: inline-size;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .icon-features__heading {
    margin: 0 0 var(--space-2xl);
    text-align: center;
  }

  /*
    Each feature takes 1/--columns of the row (minus the gaps). justify-content: center puts a last
    row that is not full in the middle.
  */
  .icon-features__grid {
    --columns: var(--columns-mobile);
    --column-gap: var(--space-md);
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: var(--space-xl) var(--column-gap);
  }

  .icon-features__grid > * {
    flex: 0 0 calc((100% - (var(--columns) - 1) * var(--column-gap)) / var(--columns));
    min-inline-size: 0;
  }

  /*
    One by one, per row: --col = the feature's column (0 = first), set below for each column count.
    The first feature of each row starts at once, the next ones 100ms after each other.
  */
  .icon-features__grid > * {
    --animate-delay: calc(var(--col, 0) * 100ms);
  }

  /* Phones: half the section padding (Figma mobile) */
  @media (max-width: 749px) {
    .icon-features {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }

    .icon-features__grid[data-columns-phone='2'] > :nth-child(2n) {
      --col: 1;
    }
  }

  @media (min-width: 750px) {
    .icon-features__grid {
      --column-gap: var(--space-lg);
      row-gap: var(--space-2xl);
    }
  }

  /*
    Tablets: 3 columns, 4 when the row is 50rem (800px) or wider, so each column keeps about 180px.
    Never more than "Columns on desktop" (Liquid writes both counts as data attributes).
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .icon-features__grid {
      --columns: min(var(--columns-desktop), 3);
    }

    @container (width < 50rem) {
      .icon-features__grid[data-columns-tablet='2'] > :nth-child(2n),
      .icon-features__grid[data-columns-tablet='3'] > :nth-child(3n + 2) {
        --col: 1;
      }

      .icon-features__grid[data-columns-tablet='3'] > :nth-child(3n) {
        --col: 2;
      }
    }

    @container (width >= 50rem) {
      .icon-features__grid {
        --columns: min(var(--columns-desktop), 4);
      }

      .icon-features__grid[data-columns-tablet-wide='2'] > :nth-child(2n),
      .icon-features__grid[data-columns-tablet-wide='3'] > :nth-child(3n + 2),
      .icon-features__grid[data-columns-tablet-wide='4'] > :nth-child(4n + 2) {
        --col: 1;
      }

      .icon-features__grid[data-columns-tablet-wide='3'] > :nth-child(3n),
      .icon-features__grid[data-columns-tablet-wide='4'] > :nth-child(4n + 3) {
        --col: 2;
      }

      .icon-features__grid[data-columns-tablet-wide='4'] > :nth-child(4n) {
        --col: 3;
      }
    }
  }

  @media (min-width: 1200px) {
    .icon-features__grid {
      --columns: var(--columns-desktop);
      --column-gap: var(--space-xl);
    }

    .icon-features__grid[data-columns-desktop='2'] > :nth-child(2n),
    .icon-features__grid[data-columns-desktop='3'] > :nth-child(3n + 2),
    .icon-features__grid[data-columns-desktop='4'] > :nth-child(4n + 2),
    .icon-features__grid[data-columns-desktop='5'] > :nth-child(5n + 2),
    .icon-features__grid[data-columns-desktop='6'] > :nth-child(6n + 2) {
      --col: 1;
    }

    .icon-features__grid[data-columns-desktop='3'] > :nth-child(3n),
    .icon-features__grid[data-columns-desktop='4'] > :nth-child(4n + 3),
    .icon-features__grid[data-columns-desktop='5'] > :nth-child(5n + 3),
    .icon-features__grid[data-columns-desktop='6'] > :nth-child(6n + 3) {
      --col: 2;
    }

    .icon-features__grid[data-columns-desktop='4'] > :nth-child(4n),
    .icon-features__grid[data-columns-desktop='5'] > :nth-child(5n + 4),
    .icon-features__grid[data-columns-desktop='6'] > :nth-child(6n + 4) {
      --col: 3;
    }

    .icon-features__grid[data-columns-desktop='5'] > :nth-child(5n),
    .icon-features__grid[data-columns-desktop='6'] > :nth-child(6n + 5) {
      --col: 4;
    }

    .icon-features__grid[data-columns-desktop='6'] > :nth-child(6n) {
      --col: 5;
    }
  }
  /*
    "Feature style: Card" (collection page design): each feature in a soft rounded card, a light tint of
    the highlight colour on the scheme background with a faint edge. The cards in a row are the same height
    (flex stretch), and the gaps are the same both ways.
  */
  .icon-features--card .icon-features__grid {
    row-gap: var(--column-gap);
  }

  .icon-features--card .icon-feature {
    justify-content: flex-start;
    padding: var(--space-lg) var(--space-md);
    border: 1px solid color-mix(in srgb, var(--color-text) 6%, transparent);
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-accent) 4%, var(--color-background));
  }

  @media (min-width: 1200px) {
    .icon-features--card .icon-feature {
      padding: var(--space-2xl) var(--space-xl);
    }
  }

/* sections/image-banner.liquid */

  /*
    The photo and the overlay fill the section (absolute, behind); the content sits on top in the
    page-width column, centred vertically.
  */
  image-banner {
    display: block;
  }

  /* clip, not hidden: a focused link that is moved out of view must not scroll the stage itself */
  .image-banner__stage {
    position: relative;
    display: grid;
    overflow: hidden;
    overflow: clip;
    isolation: isolate;
  }

  .image-banner--full .image-banner__stage {
    min-block-size: 100svh;
  }

  .image-banner--large .image-banner__stage {
    min-block-size: 80svh;
  }

  .image-banner--medium .image-banner__stage {
    min-block-size: 64svh;
  }

  .image-banner--small .image-banner__stage {
    min-block-size: 48svh;
  }

  .image-banner__media,
  .image-banner__overlay {
    position: absolute;
    inset: 0;
    z-index: -1;
  }

  .image-banner__media .image,
  .image-banner__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  .image-banner__placeholder {
    background-color: var(--color-tint);
  }

  /*
    Overlay: black, faded by the Overlay strength setting (opacity), so white text stays readable.
    Gradient (Manifesto): dark on the left behind the text, clear on the right where the face is.
    Even (promo): the same tint everywhere.
  */
  .image-banner__overlay {
    opacity: var(--banner-overlay);
  }

  .image-banner--overlay-gradient .image-banner__overlay {
    background: linear-gradient(90deg, #000000 0%, #000000b3 30%, #00000000 65%);
  }

  .image-banner--overlay-gradient-right .image-banner__overlay {
    background: linear-gradient(270deg, #000000 0%, #000000b3 30%, #00000000 65%);
  }

  .image-banner--overlay-even .image-banner__overlay {
    background-color: #000000;
  }

  .image-banner__inner {
    display: grid;
    align-items: center;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /* Large screens: content left, cards right (the cards column only when it has cards) */
  @media (min-width: 1200px) {
    .image-banner__inner {
      grid-template-columns: 1fr auto;
    }
  }

  /*
    Phones and tablets (Figma mobile): the content, then the small cards under it at the right.
    The content group sits low on the photo (align-content: end), so the face stays clear.
  */
  @media (max-width: 1199px) {
    .image-banner__inner {
      align-content: safe end; /* safe: content taller than the box overflows at the bottom, never the top */
      gap: var(--space-lg);
    }

    .image-banner__cards {
      justify-self: end;
    }

    .image-banner .highlight-cards {
      gap: var(--space-sm);
    }

    .image-banner .highlight-card {
      gap: var(--space-sm);
      min-inline-size: clamp(8rem, 5rem + 8vw, 11rem);
      padding: var(--space-xs) var(--space-sm);
      border-radius: min(var(--highlight-card-radius, var(--radius-lg)), 0.875rem);
    }

    .image-banner .highlight-card__icon {
      inline-size: clamp(1.75rem, 1.25rem + 1.5vw, 2.25rem);
      block-size: clamp(1.75rem, 1.25rem + 1.5vw, 2.25rem);
    }

    .image-banner .highlight-card__icon :is(svg, img) {
      inline-size: 0.875rem;
      block-size: 0.875rem;
    }

    .image-banner .highlight-card__label {
      font-size: 0.625rem;
    }

    .image-banner .highlight-card__value {
      font-size: var(--font-size-small);
    }
  }

  .image-banner__cards:not(:has(.highlight-card, .countdown:not([hidden]))) {
    display: none;
  }

  /*
    Countdown in the card column (Figma promo banner): from 1200px at the bottom of the right column,
    lower than the text; below 1200px under the text (Figma mobile).
    The column gets room (2/5 of the width on large screens, the full width below 1200px), so the
    countdown's Alignment settings can move the tiles in it.
  */
  @media (min-width: 1200px) {
    .image-banner__inner:has(.countdown:not([hidden])) {
      grid-template-columns: minmax(0, 3fr) minmax(max-content, 2fr);
    }

    .image-banner__cards:has(.countdown) {
      align-self: end;
    }
  }

  @media (max-width: 1199px) {
    .image-banner__cards:has(.countdown) {
      justify-self: stretch;
    }
  }

  /*
    Scene (only with data-scene-active, added by the script when a Trending sheet is shown):
    the track is Scene length tall, the stage sticks to the screen, and --p (0 -> 1) drives:
    - out: 0 -> 1 while --p goes 0.12 -> 0.42 (content + cards slide left and fade)
    - in:  0 -> 1 while --p goes 0.30 -> 0.65 (the sheet slides in from the left)
    then the sheet holds until the pin lets go.
  */
  .image-banner[data-scene-active] .image-banner__track {
    block-size: calc(var(--scene-length, 250) * 1svh);
  }

  .image-banner[data-scene-active] .image-banner__stage {
    --out: clamp(0, calc((var(--p) - 0.12) / 0.3), 1);
    --in: clamp(0, calc((var(--p) - 0.3) / 0.35), 1);

    position: sticky;
    inset-block-start: 0;
    grid-template-rows: 100%; /* the row is the screen height, also when the content is taller */
    block-size: 100svh;
    min-block-size: 0;
  }

  .image-banner[data-scene-active] .image-banner__inner,
  .image-banner[data-scene-active] .banner-sheet {
    grid-area: 1 / 1;
  }

  .image-banner[data-scene-active] .image-banner__inner {
    opacity: calc(1 - var(--out));
    transform: translateX(calc(var(--out) * -6rem));
  }

  /* Once the sheet is over the photo, the faded content can't be clicked by accident */
  .image-banner[data-sheet-shown] .image-banner__inner {
    pointer-events: none;
  }

  .image-banner[data-scene-active] .banner-sheet {
    justify-self: start;
    inline-size: var(--sheet-width, 50%);
    block-size: 100%;
    overflow-y: auto;
    transform: translateX(calc((1 - var(--in)) * -100%));
    box-shadow: 1.5rem 0 3rem #00000040;
  }

  /*
    Transition "vertical" (Trending sheet setting): the banner's text and cards slide UP and away, and
    the sheet rises from the bottom of the photo instead of coming in from the left. Same --out / --in
    timing as above; the stage's overflow: hidden keeps the sheet out of sight until it rises.
  */
  .image-banner[data-scene-active][data-scene-style='vertical'] .image-banner__inner {
    transform: translateY(calc(var(--out) * -6rem));
  }

  .image-banner[data-scene-active][data-scene-style='vertical'] .banner-sheet {
    transform: translateY(calc((1 - var(--in)) * 100%));
    box-shadow: 0 -1.5rem 3rem #00000040;
  }

  /*
    "Slide in the heading and View all": once the sheet is in place (the script sets data-sheet-placed)
    both come in from OUTSIDE the sheet to their own side: the heading from beyond the left edge,
    "View all" from beyond the right edge, quickly. Time-based, not tied to the scroll, so it always
    finishes. Scrolling back up sends them out again with the sheet.
    Each travels its own width plus 4rem (more than the sheet's side padding), so it starts fully
    outside; the sheet hides anything past its edges (overflow-x below), so they appear from the edge.
  */
  .image-banner[data-scene-active][data-sheet-header] .banner-sheet {
    overflow-x: hidden; /* no sideways scrollbar while "View all" is still out to the right */
  }

  .image-banner[data-scene-active][data-sheet-header] :is(.trending-list__heading, .trending-list__view-all) {
    transition:
      transform 0.55s var(--ease-out),
      opacity 0.3s var(--ease-out),
      color var(--duration-fast) var(--ease-out),
      background-color var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  .image-banner[data-scene-active][data-sheet-header] .trending-list__view-all {
    transition-delay: 0.08s, 0.08s, 0s, 0s, 0s;
  }

  .image-banner[data-scene-active][data-sheet-header]:not([data-sheet-placed]) .trending-list__heading {
    opacity: 0;
    transform: translateX(calc(-100% - 4rem));
  }

  .image-banner[data-scene-active][data-sheet-header]:not([data-sheet-placed]) .trending-list__view-all {
    opacity: 0;
    transform: translateX(calc(100% + 4rem));
  }

  /* Sheet width: tablets and phones have their own setting (Trending sheet block) */
  @media (max-width: 1199px) {
    .image-banner[data-scene-active] .banner-sheet {
      inline-size: var(--sheet-width-tablet, 70%);
    }
  }

  @media (max-width: 749px) {
    .image-banner[data-scene-active] .banner-sheet {
      inline-size: var(--sheet-width-phone, 80%);
    }

    /* Figma mobile: the text needs the full width, so the tint from the left is darker and goes further */
    .image-banner--overlay-gradient .image-banner__overlay {
      background: linear-gradient(90deg, #000000 0%, #000000b3 45%, #00000059 100%);
    }

    .image-banner--overlay-gradient-right .image-banner__overlay {
      background: linear-gradient(270deg, #000000 0%, #000000b3 45%, #00000059 100%);
    }

    /* Half of the padding */
    .image-banner__inner {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }

    /* While the stage is pinned, the sticky header covers its top: the text starts below the header */
    .image-banner[data-scene-active] .image-banner__inner {
      padding-block-start: max(calc(var(--section-padding-top) / 2), var(--header-space, 6rem));
    }
  }

/* sections/locations-map.liquid */

  .locations-map {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .locations-map__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  location-map {
    display: block;
  }

  /* Heading on the left, filter buttons on the right, both sitting on the same bottom line (Figma) */
  .locations-map__header {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-lg) var(--space-xl);
  }

  .locations-map__heading {
    margin-block-start: var(--space-2xl); /* eyebrow → heading: 42px */
  }

  .locations-map__heading em {
    font-style: normal;
    color: var(--color-accent);
  }

  /* Figma: 50px buttons, 38px apart */
  .locations-map__filters {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-sm) var(--space-xl);
  }

  .locations-map__filters[hidden] {
    display: none;
  }

  /*
    critical.css gives a button that follows another button a 12px top margin (for stacked form
    buttons). In this row it pushed every button after the first down and made it shorter, so the
    heights looked uneven. The row sets its own gap instead.
  */
  .locations-map__filters > * {
    margin: 0;
  }

  .locations-map__filter {
    min-block-size: max(3.125rem, calc(50 * var(--px, 0.0625rem)));
    padding-inline: var(--space-md);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-xs);
    background-color: var(--color-background);
    color: var(--color-text);
    font-size: var(--font-size-body-sm);
    cursor: pointer;
    transition:
      border-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .locations-map__filter:hover,
  .locations-map__filter[aria-pressed='true'] {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  /*
    The box: the chosen shape (Figma 1787 x 663 = 2.7:1), cropping the map. container-type: size lets
    the stage below measure the box with cqw / cqh. The background is the map's own night blue, shown
    while the image loads.
  */
  .locations-map__map {
    position: relative;
    aspect-ratio: var(--map-ratio);
    margin-block-start: var(--space-xl); /* 34px */
    overflow: hidden;
    background-color: #091d29;
    container-type: size;
  }

  /* Phones (phone design): small pills in one row, the taller map shape */
  @media (max-width: 749px) {
    .locations-map__heading {
      margin-block-start: var(--space-sm);
      font-size: var(--font-size-h2);
    }

    .locations-map__filters {
      gap: 0.375rem;
    }

    .locations-map__filter {
      min-block-size: 2rem;
      padding-inline: 0.5rem;
      font-size: 0.6875rem;
    }

    .locations-map__map {
      aspect-ratio: var(--map-ratio-mobile);
      margin-block-start: var(--space-lg);
    }
  }

  /*
    The stage has the image's own shape and is just big enough to cover the box: the full box width
    (then the height is width / image ratio) or the full box height, whichever is larger. The spare
    part is pushed off-screen by the Map position (0 = keep the left/top edge, 1 = the right/bottom),
    exactly like object-position.
  */
  .locations-map__stage {
    --stage-w: max(100cqw, 100cqh * var(--image-ratio));
    --stage-h: max(100cqh, 100cqw / var(--image-ratio));
    position: absolute;
    left: calc((100cqw - var(--stage-w)) * var(--focus-x));
    top: calc((100cqh - var(--stage-h)) * var(--focus-y));
    inline-size: var(--stage-w);
    block-size: var(--stage-h);
  }

  .locations-map__image {
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }

  .locations-map__pins {
    position: absolute;
    inset: 0;
  }

  /* Order of appearance: titles, buttons, map, then the pins one by one */
  .locations-map__map {
    --animate-delay: 150ms;
  }

  .locations-map__pins > :nth-child(1) .map-pin__inner { --animate-delay: 450ms; }
  .locations-map__pins > :nth-child(2) .map-pin__inner { --animate-delay: 550ms; }
  .locations-map__pins > :nth-child(3) .map-pin__inner { --animate-delay: 650ms; }
  .locations-map__pins > :nth-child(4) .map-pin__inner { --animate-delay: 750ms; }
  .locations-map__pins > :nth-child(5) .map-pin__inner { --animate-delay: 850ms; }
  .locations-map__pins > :nth-child(n + 6) .map-pin__inner { --animate-delay: 950ms; }

/* sections/marquee.liquid */

  /*
    Figma 1920 (Default-10): full bleed, one line y 895–985; body font extra bold ~110px, uppercase,
    accent, no wrap. --marquee-size is the "Text size" setting in px at a 1920 screen; it scales
    with the screen (vw) down to a 2.5rem minimum.
  */
  .marquee {
    position: relative;
    display: block;
    overflow: hidden;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /* Left to right also on right-to-left stores: the loop slides by -50% (see the comment above) */
  .marquee__viewport {
    overflow: hidden;
    direction: ltr;
  }

  .marquee__track {
    display: flex;
    inline-size: max-content;
  }

  .marquee__half {
    display: flex;
    flex-shrink: 0;
    align-items: center;
  }

  .marquee__item,
  .marquee__separator {
    flex-shrink: 0;
    padding-inline-end: 0.35em;
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: max(2.5rem, calc(var(--marquee-size, 110) / 1920 * 100vw));
    font-weight: 800;
    line-height: 1.05;
    letter-spacing: -0.01em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  /*
    The outline repeat (Figma prototype): regular weight, transparent fill, a thin accent stroke on
    both sides of each stroke (the "double line" look), and wide letter-spacing (~0.08em: the
    letters stand apart, as in the Figma).
  */
  .marquee__item--outline {
    color: transparent;
    font-weight: 400;
    letter-spacing: 0.08em;
    -webkit-text-stroke: max(1px, 0.012em) var(--color-accent);
  }

  /*
    Moving: the track slides by one half (-50%), then starts over at 0; the two halves are the
    same, so the jump back can't be seen. Right = the same animation played in reverse.
    is-moving is set by the script, together with showing the pause button: no JS (or reduced
    motion, or animations off) = no movement and no button.
  */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .marquee.is-moving .marquee__track {
      animation: marquee-slide var(--marquee-duration, 40s) linear infinite;
    }

    .motion-on .marquee--right.is-moving .marquee__track {
      animation-direction: reverse;
    }

    .motion-on .marquee.is-paused .marquee__track {
      animation-play-state: paused;
    }
  }

  /* Pause on hover only with a mouse: after a tap on a phone, :hover stays on */
  @media (prefers-reduced-motion: no-preference) and (hover: hover) {
    .motion-on .marquee.is-moving:hover .marquee__track {
      animation-play-state: paused;
    }
  }

  @keyframes marquee-slide {
    to {
      transform: translateX(-50%);
    }
  }

  /* Pause / play: a small round button at the bottom right (shown by the script only when it moves) */
  .marquee__pause {
    position: absolute;
    inset-block-end: max(var(--space-xs), calc(var(--section-padding-bottom) - 2.75rem));
    inset-inline-end: var(--page-margin);
    display: grid;
    place-items: center;
    inline-size: 2.25rem;
    block-size: 2.25rem;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    box-shadow: var(--shadow-header);
    color: var(--color-accent);
    cursor: pointer;
  }

  .marquee__pause[hidden] {
    display: none;
  }

  .marquee__pause-icon--play,
  .marquee__pause[aria-pressed='true'] .marquee__pause-icon--pause {
    display: none;
  }

  .marquee__pause[aria-pressed='true'] .marquee__pause-icon--play {
    display: block;
  }

  .marquee__empty {
    margin: 0;
    padding: var(--space-xl);
    text-align: center;
  }

/* sections/newsletter.liquid */

  .newsletter {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /* The card's column. It is the size container: the card's layout follows the room it has. */
  .newsletter__inner {
    container: newsletter / inline-size;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /*
    The card: white on light schemes (--color-surface-raised), rounded, the soft collection shadow.
    overflow: clip keeps the image inside the round corners.
  */
  .newsletter__card {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    overflow: clip;
    border-radius: var(--radius-md);
    background-color: var(--color-surface-raised);
    box-shadow: var(--shadow-collection);
  }

  /* Narrow card (phones): the image on top in the "Image shape" ratio */
  .newsletter__media {
    position: relative;
    aspect-ratio: var(--newsletter-phone-ratio, 4 / 3);
    background-color: var(--color-tint-subtle);
  }

  .newsletter__media .newsletter__image {
    position: absolute;
    inset: 0;
  }

  .newsletter__content {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    min-inline-size: 0;
    padding: var(--space-lg);
    container: newsletter-content / inline-size;
  }

  .newsletter__content--center {
    align-items: center;
    text-align: center;
  }

  .newsletter__card--no-image .newsletter__content {
    inline-size: min(100%, 44rem);
    margin-inline: auto;
  }

  /* Full width of the column, so the label never wraps to make room for the rules */
  .newsletter__eyebrow {
    align-self: stretch;
    margin: 0 0 var(--space-md);
  }

  /* The eyebrow rules take only the free space (66px at most), so a short label stays on one line */
  .newsletter .newsletter__eyebrow::before,
  .newsletter .newsletter__eyebrow::after {
    flex: 0 1 66px;
    width: auto;
    min-width: 1.5rem;
  }

  /* The label never shrinks (a shrunk label wraps); it wraps only when it is wider than 75% of the column */
  .newsletter__eyebrow-label {
    flex: none;
    max-inline-size: 75%;
  }

  .newsletter__heading {
    margin: 0;
    font-size: var(--font-size-h2);
    line-height: var(--line-height-heading);
    text-wrap: balance;
  }

  .newsletter__heading em {
    color: var(--color-accent);
  }

  .newsletter__text {
    margin-block-start: var(--space-md);
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-surface-raised));
    font-size: var(--font-size-body-sm);
    line-height: var(--line-height-body);
  }

  .newsletter__text > :first-child {
    margin-block-start: 0;
  }

  .newsletter__text > :last-child {
    margin-block-end: 0;
  }

  .newsletter__form {
    inline-size: 100%;
    margin-block-start: var(--space-xl);
  }

  .newsletter__note {
    margin: var(--space-md) 0 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-surface-raised));
    font-size: var(--font-size-small);
  }

  /*
    The footer's form, restyled for the card. Three classes, so these win over the snippet's own two-class
    rules whatever order Shopify puts the stylesheets in. No gap anywhere: Shopify injects an empty
    h-captcha div into the form, and a gap would be added next to it (see the snippet).
    Narrow text column: the field and the button full width, one under the other.
  */
  .newsletter .newsletter-form.newsletter-form--card {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: stretch;
    max-inline-size: none;
    inline-size: 100%;
  }

  .newsletter .newsletter-form--card .newsletter-form__input {
    flex: 1 1 100%;
    min-inline-size: 0;
    border: 1px solid color-mix(in srgb, var(--color-text) 55%, var(--color-surface-raised));
    background-color: var(--color-surface-raised);
    box-shadow: none;
    -webkit-backdrop-filter: none;
    backdrop-filter: none;
  }

  .newsletter .newsletter-form--card .newsletter-form__input:hover {
    border-color: var(--color-text);
  }

  .newsletter .newsletter-form--card .newsletter-form__input:focus-visible {
    border-color: var(--color-accent);
  }

  .newsletter .newsletter-form--card .newsletter-form__input[aria-invalid='true'] {
    border-color: var(--color-error);
  }

  .newsletter .newsletter-form--card .newsletter-form__button {
    flex: 1 1 100%;
    margin-block-start: var(--space-sm);
  }

  .newsletter .newsletter-form--card > .newsletter-form__message,
  .newsletter .newsletter-form--card > auto-dismiss {
    flex: 1 1 100%;
  }

  /* Text column 24rem or wider: the field and the button on one row */
  @container newsletter-content (width >= 24rem) {
    .newsletter .newsletter-form--card .newsletter-form__input {
      flex: 1 1 12rem;
    }

    .newsletter .newsletter-form--card .newsletter-form__button {
      flex: 0 0 auto;
      margin-block-start: 0;
      margin-inline-start: var(--space-sm);
    }
  }

  /*
    Card 42rem or wider: the image beside the text (40% of the card) and as tall as the card.
    The text column then keeps at least ~22rem.
  */
  @container newsletter (width >= 42rem) {
    .newsletter__card:not(.newsletter__card--no-image) {
      grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
    }

    .newsletter__card.newsletter__card--image-right {
      grid-template-columns: minmax(0, 3fr) minmax(0, 2fr);
    }

    .newsletter__card--image-right .newsletter__media {
      order: 2;
    }

    .newsletter__media {
      aspect-ratio: auto;
      min-block-size: 22rem;
    }

    .newsletter__content {
      justify-content: center;
      padding: var(--space-2xl) var(--space-xl);
    }

    .newsletter__card--no-image .newsletter__content {
      padding-block: var(--space-3xl);
    }
  }

  @media (min-width: 1200px) {
    @container newsletter (width >= 42rem) {
      .newsletter__card:not(.newsletter__card--no-image) {
        grid-template-columns: minmax(0, 9fr) minmax(0, 11fr);
      }

      .newsletter__card.newsletter__card--image-right {
        grid-template-columns: minmax(0, 11fr) minmax(0, 9fr);
      }

      .newsletter__media {
        min-block-size: 28rem;
      }

      .newsletter__content {
        padding: var(--space-3xl);
      }
    }
  }

  /* Phones: half the section padding, smaller corners */
  @media (max-width: 749px) {
    .newsletter {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }

    .newsletter__card {
      border-radius: var(--radius-sm);
    }

    .newsletter__card--no-phone-image .newsletter__media {
      display: none;
    }
  }

/* sections/page.liquid */

  /*
    No Figma frame: the M5 pages' header (breadcrumb, eyebrow, heading-font h1 ~64px with an accent
    word, a 3px rule under it, as the policy pages) and a reading column for the text (~760px).
  */
  /*
    --px = one Figma pixel. With "Scale with the screen" the screen-scale class sets it from the screen
    width and height; without it, from the width only and never more than 1px, so the sizes below
    shrink on small screens and stop at the Figma size (a 64px title on a phone was the old bug).
  */
  .page-main {
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .page-main.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .page-main__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .page-main__header {
    margin-block-start: max(var(--space-xl), calc(45 * var(--px, 0.0625rem)));
    padding-block-end: max(var(--space-xl), calc(39 * var(--px, 0.0625rem)));
    border-block-end: 3px solid var(--color-card-border);
  }

  .page-main__header--center {
    text-align: center;
  }

  .page-main__title {
    margin: max(var(--space-lg), calc(42 * var(--px, 0.0625rem))) 0 0;
    /* --text-boost = the Text size setting (only with Scale with the screen), as the page text */
    font-size: calc(max(2.25rem, calc(64 * var(--px))) * var(--text-boost, 1));
    font-weight: 400;
    line-height: 1.1;
  }

  .page-main__header > .page-main__title:first-child {
    margin-block-start: 0;
  }

  .page-main__title em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* The page's text: a reading column, headings in the heading font, links and italic accent */
  .page-main__content {
    max-inline-size: var(--page-text-width, 760px);
    margin-block-start: max(var(--space-xl), calc(48 * var(--px, 0.0625rem)));
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .page-main__header--center + .page-main__content {
    margin-inline: auto;
  }

  .page-main__content :is(h2, h3) {
    font-weight: 400;
    line-height: 1.3;
  }

  .page-main__content h2 {
    font-size: max(1.5rem, calc(32 * var(--px, 0.0625rem)));
  }

  .page-main__content h3 {
    font-size: max(1.25rem, calc(24 * var(--px, 0.0625rem)));
  }

  .page-main__content a {
    color: var(--color-accent);
  }

  .page-main__content img {
    max-inline-size: 100%;
    block-size: auto;
    border-radius: var(--radius-sm);
  }

  /* Videos added in the text editor (YouTube / Vimeo iframes): full column width, 16:9 */
  .page-main__content iframe {
    inline-size: 100%;
    block-size: auto;
    aspect-ratio: 16 / 9;
    border: 0;
    border-radius: var(--radius-sm);
  }

  /* The scroll box around each table (added in Liquid): scrolls sideways when the table is too wide */
  .page-main__table {
    max-inline-size: 100%;
    overflow-x: auto;
    border-radius: var(--radius-sm);
  }

  .page-main__content table {
    inline-size: 100%;
    border-collapse: collapse;
  }

  .page-main__content table :is(th, td) {
    min-inline-size: 7rem;
  }

  .page-main__content :is(th, td) {
    padding: var(--space-sm) var(--space-md) var(--space-sm) 0;
    border-block-end: 1px solid var(--color-card-border);
    text-align: start;
    vertical-align: top;
  }

  .page-main__empty {
    margin: var(--space-xl) 0 0;
  }

  @media (max-width: 749px) {
    .page-main__content {
      font-size: var(--font-size-body-sm);
      line-height: 1.7;
    }
  }

/* sections/password.liquid */

  /*
    No Figma frame: the M5 look on a full screen: a soft accent background, a white card (radius,
    the card shadow) centred, the logo, a centred eyebrow, a heading-font h1 with an accent word,
    the message, one pill field with the button inside, a quiet owner link.
  */
  .password-page {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: var(--space-lg);
    min-block-size: 100svh;
    box-sizing: border-box;
    padding: var(--space-xl) var(--page-margin);
    background:
      radial-gradient(60% 50% at 20% 10%, color-mix(in srgb, var(--color-accent) 8%, transparent), transparent 70%),
      radial-gradient(50% 40% at 85% 90%, color-mix(in srgb, var(--color-accent) 6%, transparent), transparent 70%),
      var(--color-background);
    color: var(--color-text);
  }

  .password-page__card {
    inline-size: min(100%, 36rem);
    box-sizing: border-box;
    padding: clamp(2rem, 1rem + 4vw, 3.5rem);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-md);
    background-color: var(--color-background);
    box-shadow: 0 20px 60px 0 #0000000f;
    text-align: center;
  }

  .password-page__logo {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-sm);
    margin: 0;
  }

  /*
    Theme settings > Logo width, never wider than the card; a tall logo stops at 8rem. Width auto +
    max sizes keep the image's aspect ratio (no empty box beside a square logo). Only the logo text
    shrinks (and gets the …), as in the header.
  */
  .password-page__logo-image {
    display: block;
    flex-shrink: 0;
    inline-size: auto;
    max-inline-size: min(var(--logo-width), 100%);
    block-size: auto;
    max-block-size: 8rem;
  }

  /* As the header's text logo: the Logo font and the Logo text size (smaller on small screens) */
  .password-page__logo-text {
    font-family: var(--font-logo--family);
    font-size: calc(clamp(min(1.75rem, var(--logo-text-size)), 1.4rem + 1.4vw, var(--logo-text-size)) * var(--logo-text-scale, 1));
    font-weight: var(--font-logo--weight);
    line-height: 1;
  }

  .password-page__logo-text em {
    color: var(--color-accent);
  }

  .password-page__eyebrow {
    margin-block-start: var(--space-xl);
  }

  /* The rules start at 0 and take only the free space (66px at most), so the label keeps its line */
  .password-page__eyebrow::before,
  .password-page__eyebrow::after {
    flex: 1 1 0;
    min-inline-size: 1rem;
    max-inline-size: 66px;
    inline-size: auto;
  }

  .password-page__heading {
    margin: var(--space-md) 0 0;
    font-size: clamp(1.75rem, 1.4rem + 1.4vw, 2.5rem);
    font-weight: var(--font-heading--weight);
    line-height: 1.15;
  }

  .password-page__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .password-page__message {
    margin: var(--space-md) 0 0;
    font-size: var(--font-size-body);
    line-height: 1.7;
  }

  .password-page__form {
    margin-block-start: var(--space-xl);
  }

  .password-page__error {
    margin: 0 0 var(--space-sm);
    color: var(--color-accent);
    font-size: var(--font-size-caption);
  }

  /* One pill: the field with the button inside (as the search fields) */
  /*
    A fixed-height pill; the field and the button fill it with the same 6px all round, so the button
    is always centred (no shadow inside the pill: it made the button look lower).
  */
  .password-page__field {
    display: flex;
    align-items: stretch;
    gap: var(--space-xs);
    block-size: 3.5rem;
    box-sizing: border-box;
    padding: 0.375rem 0.375rem 0.375rem var(--space-lg);
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-card);
  }

  .password-page__field:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  .password-page .password-page__input {
    flex: 1;
    min-inline-size: 0;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    color: var(--color-text);
    font-size: var(--font-size-body);
  }

  .password-page .password-page__input:focus-visible {
    outline: none;
  }

  .password-page .password-page__submit {
    flex: none;
    min-block-size: 0;
    margin: 0;
    padding-block: 0;
    padding-inline: var(--space-lg);
    box-shadow: none;
  }

  .password-page__owner {
    margin: var(--space-lg) 0 0;
    font-size: var(--font-size-caption);
  }

  .password-page__owner a {
    color: var(--color-accent);
  }

  .password-page__powered {
    margin: 0;
    font-size: var(--font-size-small);
  }

  .password-page__powered a {
    color: inherit;
  }

  @media (max-width: 479px) {
    .password-page__field {
      flex-direction: column;
      block-size: auto;
      padding: var(--space-sm);
      border-radius: var(--radius-md);
    }

    .password-page .password-page__input {
      min-block-size: 2.75rem;
      padding-inline: var(--space-sm);
    }

    .password-page .password-page__submit {
      min-block-size: 2.75rem;
    }
  }

/* sections/pickup-availability.liquid */

  /* Shown in the side panel of blocks/product-pickup.liquid */
  .pickup-availability__product {
    margin: 0 0 var(--space-md);
    font-size: var(--font-size-body-sm);
  }

  .pickup-availability__product span {
    display: block;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  .pickup-availability__list {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .pickup-availability__store {
    padding-block: var(--space-md);
    border-block-start: 1px solid var(--color-border);
    font-size: var(--font-size-body-sm);
  }

  .pickup-availability__name {
    margin: 0 0 var(--space-2xs);
    font-family: var(--font-body--family);
    font-size: var(--font-size-body);
    font-weight: 600;
  }

  .pickup-availability__status {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
  }

  /* A dot before the status: accent = in stock, grey = not */
  .pickup-availability__status::before {
    content: "";
    flex: none;
    inline-size: 0.5rem;
    block-size: 0.5rem;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-text) 40%, var(--color-background));
  }

  .pickup-availability__status--in::before {
    background-color: var(--color-accent);
  }

  .pickup-availability__time,
  .pickup-availability__address,
  .pickup-availability__phone {
    margin: var(--space-2xs) 0 0;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
  }

  .pickup-availability__address p {
    margin: 0;
  }

/* sections/policy.liquid */

  /*
    Figma 1920 (privacy 1:18280, terms 1:18208): content x 135–1785 at 1920, the Widest width (as the other pages).
    Header: eyebrow y 212, heading ~64px y 278; privacy "In force" right-aligned (label y 288, date
    ~24px y 333, meta y 376); a 3px rule y 461; intro ~20px / 35, max 954 (y 501).
    Rows (privacy): title column 418 (number x 135, title x 191, heading font ~26px), text from
    x 553 (~20 / 35), 1px rules, ~136px per row. Register: columns 418 / 591 / 374 / 267, header
    labels accent caps, Basis accent.
    Contents (terms): a 466px contents column (rows 70 tall, 3px rail), clauses 1107 wide, gap 77.
    CTA: a 3px rule ~100px under the last row, heading ~40px, text, button 259 x 50 at the right.
  */
  /*
    --px = one Figma pixel: from the screen width and height with Scale with the screen on, else from the
    width only and never more than 1px (without it the 1920px sizes showed on phones: a 64px title).
  */
  .policy {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .policy.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .policy__inner {
    --policy-title-column: max(14rem, calc(418 * var(--px)));

    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* ---------- Header ---------- */
  .policy__header {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-lg) var(--space-2xl);
    margin-block-start: max(var(--space-xl), calc(45 * var(--px)));
    padding-block-end: max(var(--space-xl), calc(39 * var(--px)));
    border-block-end: 3px solid var(--color-card-border);
  }

  .policy__heading {
    max-inline-size: 16em;
    margin: max(var(--space-lg), calc(42 * var(--px))) 0 0;
    /* --text-boost = the Text size setting (only with Scale with the screen) */
    font-size: calc(max(2.25rem, calc(64 * var(--px))) * var(--text-boost, 1));
    font-weight: 400;
    line-height: 1.1;
  }

  .policy__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .policy__in-force {
    text-align: end;
  }

  .policy__in-force > * {
    margin: 0;
  }

  .policy__in-force-label,
  .policy__label {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .policy__in-force-date {
    margin-block-start: var(--space-sm);
    font-family: var(--font-heading--family);
    font-size: max(1.25rem, calc(24 * var(--px)));
  }

  .policy__in-force-meta {
    margin-block-start: var(--space-xs);
    font-size: var(--font-size-body-sm);
  }

  .policy__intro {
    max-inline-size: max(20rem, calc(954 * var(--px)));
    margin-block-start: max(var(--space-lg), calc(37 * var(--px)));
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .policy__intro > * {
    margin: 0;
  }

  /* ---------- The policy text (Settings > Policies) ---------- */
  .policy__layout {
    margin-block-start: max(var(--space-xl), calc(48 * var(--px)));
  }

  .policy__body {
    counter-reset: policy-item;
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  /* Shopify's generated policies wrap the text in one <div>: let its children join the layout */
  .policy__body > div:not([data-policy-group]) {
    display: contents;
  }

  .policy__body :is(p, ul, ol) {
    margin: 0;
  }

  /* An H4–H6 (a div in Liquid): the accent group label ("The register", "In detail"); the numbering restarts */
  .policy__body [data-policy-group] {
    counter-reset: policy-item;
    margin: max(var(--space-2xl), calc(72 * var(--px))) 0 0;
    color: var(--color-accent);
    font-family: var(--font-body--family);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .policy__body > :first-child,
  .policy__body > div > :first-child {
    margin-block-start: 0;
  }

  /* Each H2: a numbered item ("01 Who we are") */
  .policy__body h2 {
    counter-increment: policy-item;
    display: flex;
    gap: max(var(--space-sm), calc(30 * var(--px)));
    margin: 0;
    font-size: max(1.25rem, calc(26 * var(--px)));
    font-weight: 400;
    line-height: 1.35;
    scroll-margin-block-start: calc(var(--header-space, 6.0625rem) + var(--space-lg));
  }

  .policy__body h2::before {
    content: counter(policy-item, decimal-leading-zero);
    flex-shrink: 0;
    color: var(--color-accent);
    font-size: 0.85em;
    line-height: 1.6;
  }

  .policy__body h3 {
    margin: var(--space-md) 0 0;
    font-size: var(--font-size-body-lg);
    font-weight: 400;
  }

  .policy__body a {
    color: var(--color-accent);
  }

  /* Italic = the accent colour, upright (the terms' closing "Governed by the laws of France…" line) */
  .policy__body em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* "The register": a table with accent header labels, heading-font first column, accent last column */
  .policy__body table {
    inline-size: 100%;
    margin-block-start: var(--space-lg);
    border-collapse: collapse;
  }

  .policy__body th {
    padding: 0 var(--space-md) max(var(--space-md), calc(22 * var(--px))) 0;
    border-block-end: 1px solid var(--color-card-border);
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-align: start;
    text-transform: uppercase;
  }

  .policy__body td {
    padding: max(var(--space-lg), calc(33 * var(--px))) var(--space-md) max(var(--space-lg), calc(33 * var(--px))) 0;
    border-block-end: 1px solid var(--color-card-border);
    vertical-align: top;
  }

  .policy__body td:first-child {
    font-family: var(--font-heading--family);
    font-size: max(1.25rem, calc(26 * var(--px)));
    line-height: 1.35;
  }

  .policy__body td:last-child {
    color: var(--color-accent);
  }

  /*
    Rows (privacy): the policy text becomes a 2-column grid. Every H2 takes the title column and the
    text after it (until the next H2) takes the text column; a 1px rule above each H2 and its first
    paragraph draws the row line. Everything else (labels, tables, an intro) spans both columns.
  */
  .policy--rows .policy__body {
    display: grid;
    grid-template-columns: var(--policy-title-column) minmax(0, 1fr);
    align-items: start;
  }

  .policy--rows .policy__body > *,
  .policy--rows .policy__body > div > * {
    grid-column: 1 / -1;
  }

  .policy--rows .policy__body h2 {
    grid-column: 1;
    padding-block-start: max(var(--space-lg), calc(33 * var(--px)));
    padding-inline-end: var(--space-lg);
    border-block-start: 1px solid var(--color-card-border);
  }

  .policy--rows .policy__body h2 ~ :is(p, ul, ol, h3) {
    grid-column: 2;
    padding-block-end: var(--space-sm);
  }

  .policy--rows .policy__body h2 + :is(p, ul, ol, h3) {
    padding-block-start: max(var(--space-lg), calc(33 * var(--px)));
    border-block-start: 1px solid var(--color-card-border);
  }

  .policy--rows .policy__body h2 ~ :is(p, ul, ol) + :is(p, ul, ol) {
    margin-block-start: var(--space-sm);
  }

  /* The row ends with space before the next one */
  .policy--rows .policy__body h2 ~ :is(p, ul, ol):has(+ h2) {
    padding-block-end: max(var(--space-lg), calc(33 * var(--px)));
  }

  /* Contents (terms): the contents column (sticky) + the clauses, each with a rule under it */
  .policy--contents .policy__layout {
    display: grid;
    grid-template-columns: max(14rem, calc(466 * var(--px))) minmax(0, 1fr);
    align-items: start;
    gap: max(var(--space-xl), calc(77 * var(--px)));
  }

  .policy--contents .policy__layout:not(:has(.policy__contents:not([hidden]))) {
    grid-template-columns: minmax(0, 1fr);
  }

  .policy--contents .policy__body h2 {
    padding-block-start: max(var(--space-lg), calc(38 * var(--px)));
    border-block-start: 1px solid var(--color-card-border);
    font-size: max(1.375rem, calc(30 * var(--px)));
  }

  .policy--contents .policy__body > h2:first-child,
  .policy--contents .policy__body > div > h2:first-child {
    padding-block-start: 0;
    border-block-start: 0;
  }

  .policy--contents .policy__body h2 + * {
    margin-block-start: max(var(--space-md), calc(22 * var(--px)));
  }

  .policy--contents .policy__body :is(p, ul, ol) + :is(p, ul, ol) {
    margin-block-start: var(--space-sm);
  }

  .policy--contents .policy__body :is(p, ul, ol):has(+ h2) {
    padding-block-end: max(var(--space-lg), calc(38 * var(--px)));
  }

  .policy__contents {
    position: sticky;
    inset-block-start: calc(var(--header-space, 6.0625rem) + var(--space-md));
  }

  .policy__contents[hidden] {
    display: none;
  }

  .policy__contents-list {
    margin: max(var(--space-lg), calc(38 * var(--px))) 0 0;
    padding: 0;
    border-inline-start: 3px solid var(--color-card-border);
    list-style: none;
  }

  .policy__contents-link {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    min-block-size: max(2.75rem, calc(70 * var(--px)));
    box-sizing: border-box;
    margin-inline-start: -3px;
    padding: var(--space-xs) var(--space-md);
    border-inline-start: 3px solid transparent;
    color: var(--color-text);
    font-size: var(--font-size-body);
    line-height: 1.35;
    text-decoration: none;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  .policy__contents-number {
    color: var(--color-accent);
    font-variant-numeric: tabular-nums;
  }

  .policy__contents-link:hover,
  .policy__contents-link[aria-current="true"] {
    border-inline-start-color: var(--color-accent);
    background-color: color-mix(in srgb, var(--color-accent) 5%, transparent);
    color: var(--color-accent);
  }

  /* ---------- Call to action (privacy "Exercise any of these in one message.") ---------- */
  .policy__cta {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-lg) var(--space-2xl);
    margin-block-start: max(var(--space-2xl), calc(100 * var(--px)));
    padding-block-start: max(var(--space-xl), calc(76 * var(--px)));
    border-block-start: 3px solid var(--color-card-border);
  }

  .policy__cta-copy {
    flex: 1 1 24rem;
    max-inline-size: max(24rem, calc(855 * var(--px)));
  }

  .policy__cta-heading {
    margin: 0;
    font-size: max(1.75rem, calc(40 * var(--px)));
    font-weight: 400;
    line-height: 1.2;
  }

  .policy__cta-text {
    margin-block-start: var(--space-md);
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .policy__cta-text > * {
    margin: 0;
  }

  .policy__cta-button {
    min-block-size: max(2.75rem, calc(50 * var(--px)));
    padding-inline: max(1.25rem, calc(35 * var(--px)));
    font-size: max(var(--font-size-caption), calc(16.5 * var(--px)));
  }

  .policy__cta-icon {
    display: inline-flex;
  }

  .policy__cta-icon svg {
    inline-size: max(1.125rem, calc(19 * var(--px)));
    block-size: auto;
  }

  .policy__empty {
    margin: var(--space-xl) 0 0;
  }

  /* ---------- Below 990px: one column for the contents layout; the contents is a normal list above the clauses ---------- */
  @media (max-width: 989px) {
    .policy--contents .policy__layout {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-xl);
    }

    .policy__contents {
      position: static;
    }

    .policy__contents-list {
      margin-block-start: var(--space-md);
    }

    .policy__contents-link {
      min-block-size: 2.5rem;
    }
  }

  /*
    ---------- Phones (phone PNGs, 375px): heading and "In force" on one row, smaller type,
    the register as label / value rows, the button at its own width ----------
  */
  @media (max-width: 749px) {
    /* A grid: the eyebrow on its own row, then the heading and the "In force" block side by side */
    .policy__header {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      align-items: end;
      gap: 0 var(--space-md);
      margin-block-start: var(--space-lg);
      padding-block-end: var(--space-lg);
    }

    .policy__title-block {
      display: contents;
    }

    .policy__eyebrow {
      grid-column: 1 / -1;
    }

    .policy__in-force {
      max-inline-size: 11rem;
    }

    .policy__heading {
      margin-block-start: var(--space-md);
      font-size: calc(1.75rem * var(--text-boost, 1));
      line-height: 1.3;
    }

    .policy__in-force-label,
    .policy__in-force-meta {
      font-size: 0.75rem;
    }

    .policy__in-force-date {
      margin-block-start: var(--space-xs);
      font-size: 1rem;
    }

    .policy__intro {
      margin-block-start: var(--space-lg);
    }

    .policy__layout {
      margin-block-start: var(--space-xl);
    }

    .policy__body,
    .policy__intro,
    .policy__cta-text {
      font-size: 0.8125rem;
      line-height: 1.65;
    }

    .policy__body h2,
    .policy--contents .policy__body h2 {
      gap: var(--space-sm);
      font-size: 1.0625rem;
    }

    /* Not the first one: the first label sits under the intro with only the layout's space */
    .policy__body [data-policy-group]:not(:first-child) {
      margin-block-start: var(--space-xl);
    }

    .policy__body [data-policy-group] {
      font-size: 0.8125rem;
    }

    .policy__contents-link {
      font-size: 0.875rem;
    }

    .policy--rows .policy__body {
      grid-template-columns: minmax(0, 1fr);
    }

    .policy--rows .policy__body h2,
    .policy--rows .policy__body h2 ~ :is(p, ul, ol, h3) {
      grid-column: 1;
    }

    .policy--rows .policy__body h2 {
      padding-inline-end: 0;
    }

    .policy--rows .policy__body h2 + :is(p, ul, ol, h3) {
      padding-block-start: var(--space-sm);
      border-block-start: 0;
    }

    /* A table scrolls sideways (no JS: no column labels for the rows below) */
    .policy__body table {
      display: block;
      overflow-x: auto;
    }

    /* The register: each row a stack of label / value (the script copies the column labels to data-label) */
    .policy__body table:has(td[data-label]) :is(tbody, tr, td) {
      display: block;
    }

    .policy__body table:has(td[data-label]) :is(thead, tr:has(th)) {
      display: none;
    }

    .policy__body table:has(td[data-label]) {
      margin-block-start: 0;
    }

    .policy__body table:has(td[data-label]) tr {
      padding-block: var(--space-lg);
      border-block-end: 1px solid var(--color-card-border);
    }

    .policy__body table:has(td[data-label]) td {
      padding: 0;
      border: 0;
    }

    .policy__body table:has(td[data-label]) td + td {
      margin-block-start: var(--space-md);
    }

    .policy__body table:has(td[data-label]) td:first-child {
      font-size: 1.0625rem;
    }

    .policy__body td[data-label]::before {
      content: attr(data-label);
      display: block;
      margin-block-end: var(--space-xs);
      color: var(--color-accent);
      font-family: var(--font-body--family);
      font-size: 0.6875rem;
      letter-spacing: var(--letter-spacing-label);
      line-height: 1.5;
      text-transform: uppercase;
    }

    .policy__cta {
      align-items: flex-start;
      flex-direction: column;
      gap: var(--space-md);
      margin-block-start: var(--space-xl);
      padding-block-start: var(--space-lg);
    }

    .policy__cta-copy {
      flex: none;
    }

    .policy__cta-heading {
      font-size: 1.125rem;
    }
  }

  /* Very small phones: the "In force" block goes under the heading (else "Everything" has no room) */
  @media (max-width: 374px) {
    .policy__header {
      grid-template-columns: minmax(0, 1fr);
    }

    .policy__in-force {
      max-inline-size: none;
      margin-block-start: var(--space-md);
      text-align: start;
    }
  }

/* sections/product-clinical.liquid */

  /*
    Figma 1920 ("Product details 9"): eyebrow y 211; heading x 54–845, ~70px, 2 lines, accent words;
    before / after x 56–791 (735 x 455), square corners: a 1px white line with a 56px white circle (◂ ▸)
    at the middle; frosted pills "WEEK 0" (top left) and "WEEK 12" (top right). Rings x 907–1226 (~320):
    the outer ring accent ~3px, three pale ones inside; "94%" ~26px medium and "RADIANCE" caps in the
    middle. Results x 1303–1837: label ~18px (the first dark, the others grey), value caps ~15px right,
    a hairline under each row. --px = one Figma pixel: the 1920px sizes get smaller on smaller screens.
    Below 1200px: the slider, the rings centred, the list (agreed, not the Variant97-2 side by side).
  */
  .product-clinical {
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product-clinical-empty {
    padding: var(--space-2xl) var(--page-margin);
    background-color: var(--color-background);
    text-align: center;
  }

  .product-clinical__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-clinical__eyebrow {
    margin: 0 0 var(--space-lg);
  }

  .product-clinical__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-clinical__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* Below 1200px (agreed): the slider full width, then the rings centred, then the list full width */
  .product-clinical__layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: center;
    gap: var(--space-xl);
  }

  @media (max-width: 1199px) {
    .product-clinical__rings {
      justify-self: center;
      inline-size: min(100%, 16rem);
    }
  }

  .product-clinical__intro + .product-clinical__layout {
    margin-block-start: max(var(--space-xl), calc(44 * var(--px)));
  }

  .product-clinical__compare {
    grid-column: 1 / -1;
  }

  /* No results: the slider alone, not wider than 48rem */
  .product-clinical--no-results .product-clinical__layout {
    grid-template-columns: minmax(0, 48rem);
  }

  /*
    Before / after: both frames on top of each other; the "after" one is cut at --pos. Always left to
    right: the photos are not mirrored in RTL, so the cut, the line, the tags and the range must not be.
  */
  .product-clinical__compare {
    position: relative;
    display: grid;
    overflow: hidden;
    aspect-ratio: 735 / 455;
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
    direction: ltr;
    user-select: none;
    /* A sideways drag moves the line (the script); an up / down swipe still scrolls the page */
    touch-action: pan-y;
    cursor: ew-resize;
  }

  .product-clinical__frame {
    grid-area: 1 / 1;
  }

  .product-clinical__frame--after {
    clip-path: inset(0 0 0 var(--pos));
  }

  .product-clinical__image {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .product-clinical__placeholder {
    fill: color-mix(in srgb, var(--color-text) 30%, transparent);
  }

  .product-clinical__placeholder--after {
    background-color: color-mix(in srgb, var(--color-accent) 10%, var(--color-background));
  }

  .product-clinical__tag {
    position: absolute;
    z-index: 2;
    top: max(var(--space-sm), calc(20 * var(--px)));
    padding: 0.45em 1.25em;
    border-radius: var(--radius-pill);
    background-color: #00000040;
    color: #ffffff;
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
    pointer-events: none;
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
  }

  .product-clinical__tag--before {
    left: max(var(--space-sm), calc(25 * var(--px)));
  }

  .product-clinical__tag--after {
    right: max(var(--space-sm), calc(25 * var(--px)));
  }

  /* The divider at --pos, with the round handle in the middle */
  .product-clinical__line {
    position: absolute;
    z-index: 2;
    inset-block: 0;
    left: var(--pos);
    inline-size: 1px;
    background-color: #ffffffcc;
    pointer-events: none;
  }

  .product-clinical__handle {
    position: absolute;
    top: 50%;
    left: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.125rem;
    inline-size: max(2.75rem, calc(56 * var(--px)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: #ffffff;
    box-shadow: 0 2px 10px #00000026;
    color: var(--color-text);
    translate: -50% -50%;
  }

  .product-clinical__handle-icon {
    display: inline-flex;
    rotate: 180deg; /* icon-arrow.svg points right: the first one points left */
  }

  .product-clinical__handle-icon--right {
    rotate: 0deg;
  }

  .product-clinical__handle-icon svg {
    inline-size: 0.625rem;
    block-size: auto;
  }

  /* The real control for the keyboard and screen readers: an invisible range input over the image */
  .product-clinical .product-clinical__range {
    position: absolute;
    z-index: 3;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 0;
    background: none;
    opacity: 0;
    appearance: none;
    /* The keyboard uses it (Tab, ← / →); presses and drags go to the photo (the script) */
    pointer-events: none;
  }

  .product-clinical__compare:has(.product-clinical__range:focus-visible) .product-clinical__handle {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  /* The rings */
  .product-clinical__rings {
    position: relative;
    display: grid;
    place-items: center;
    aspect-ratio: 1;
  }

  .product-clinical__svg {
    grid-area: 1 / 1;
    inline-size: 100%;
    block-size: 100%;
    rotate: -90deg; /* the rings start at the top */
  }

  .product-clinical__track,
  .product-clinical__arc {
    fill: none;
    stroke-width: 1.6;
  }

  .product-clinical__track {
    stroke: color-mix(in srgb, var(--color-accent) 7%, var(--color-background));
  }

  .product-clinical__arc {
    stroke: color-mix(in srgb, var(--color-accent) 30%, var(--color-background));
    stroke-dasharray: var(--value) 100;
    stroke-linecap: round;
  }

  .product-clinical__arc--lead {
    stroke: var(--color-accent);
    stroke-width: 2;
  }

  /*
    Drawn when in view (the script adds is-drawn), one ring after the other from the outside. Without
    JS, before the element is defined, if its script fails, or with reduced motion: full at once.
  */
  @media (prefers-reduced-motion: no-preference) and (scripting: enabled) {
    product-clinical:defined:not(.is-drawn) .product-clinical__arc {
      stroke-dasharray: 0 100;
    }

    .product-clinical__arc {
      transition: stroke-dasharray 1.4s var(--ease-out);
      transition-delay: calc(var(--ring, 0) * 0.15s);
    }
  }

  .product-clinical__centre {
    grid-area: 1 / 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
    text-align: center;
  }

  .product-clinical__centre-value {
    font-size: var(--font-size-h3);
    font-weight: var(--font-weight-medium);
  }

  .product-clinical__centre-label {
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-clinical__results {
    margin: 0;
  }

  .product-clinical__result {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: var(--space-md);
    padding-block: var(--space-md);
    border-block-end: 1px solid var(--color-card-border);
    color: color-mix(in srgb, var(--color-text) 62%, var(--color-background));
  }

  .product-clinical__result--lead {
    color: var(--color-text);
  }

  .product-clinical__result--empty {
    font-style: italic;
  }

  .product-clinical__result dt {
    font-size: var(--font-size-body-sm);
  }

  .product-clinical__result dd {
    margin: 0;
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    white-space: nowrap;
  }

  /* Phones: smaller heading, slider tags and handle (Variant97-2); rings and list as on tablets */
  @media (max-width: 749px) {
    .product-clinical__layout {
      gap: var(--space-lg);
    }

    .product-clinical__intro + .product-clinical__layout {
      margin-block-start: var(--space-lg);
    }

    .product-clinical__eyebrow {
      margin-block-end: var(--space-sm);
    }

    .product-clinical__heading {
      font-size: 1.5rem;
      line-height: 1.2;
    }

    .product-clinical__tag {
      font-size: 0.625rem;
    }

    .product-clinical__handle {
      inline-size: 1.75rem;
    }

    .product-clinical__handle-icon svg {
      inline-size: 0.5rem;
    }
  }

  /* Desktop: slider | rings | list (Figma 735 : 320 : 534) */
  @media (min-width: 1200px) {
    .product-clinical__layout {
      grid-template-columns: minmax(0, 735fr) minmax(0, 320fr) minmax(0, 534fr);
      gap: max(var(--space-xl), calc(90 * var(--px)));
    }

    .product-clinical__compare {
      grid-column: auto;
    }

    .product-clinical--no-compare .product-clinical__layout {
      grid-template-columns: minmax(0, 320fr) minmax(0, 534fr);
    }

    .product-clinical__heading {
      max-inline-size: 26ch; /* Figma: 2 lines */
    }
  }

/* sections/product-deck.liquid */

  product-deck {
    display: block;
  }

  .product-deck {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .product-deck__inner {
    display: flex;
    flex-direction: column;
    gap: clamp(2rem, 1rem + 3vw, 4.5rem);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* Titles in the middle column, the pill in the right one (Figma), so the titles stay centred */
  .product-deck__header {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    gap: var(--space-md);
  }

  .product-deck__titles {
    grid-column: 2;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-sm);
    text-align: center;
  }

  .product-deck__eyebrow,
  .product-deck__heading,
  .product-deck__pill {
    margin: 0;
  }

  .product-deck__heading {
    font-size: var(--font-size-display);
  }

  /* "New *Arrivals*": italic words in the highlight colour, not slanted */
  .product-deck__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* "• Fresh this week": a pale gold pill with a dot */
  .product-deck__pill {
    grid-column: 3;
    justify-self: end;
    display: inline-flex;
    align-items: center;
    gap: 0.6em;
    padding: 0.45em 1.1em;
    border: 1px solid color-mix(in srgb, var(--color-accent) 35%, transparent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 18%, var(--color-background));
    color: color-mix(in srgb, var(--color-accent) 70%, var(--color-text));
    font-size: var(--font-size-caption);
  }

  .product-deck__pill::before {
    content: "";
    inline-size: 0.45em;
    block-size: 0.45em;
    border-radius: 50%;
    background-color: currentcolor;
  }

  /*
    The deck. Every card sits in the middle; its place comes from:
    --o    offset from the middle of the deck (7 cards: -3 ... 3), set by Liquid, never changes
    --d    the same without the sign (how far from the middle)
    --half the biggest offset (7 cards: 3)
    --fan  0 = stacked, 1 = fanned out (the script turns it from 0 to 1 while the section scrolls in)
    Fanned: each step moves the card --spread sideways and --turn round, and it drops along an arc (--arc). The
    spread shares ~38% of the width between the steps, so 3 or 8 cards both fill the row.
    Stacked: the cards are only nudged (0.6rem, 3deg), like a pile of photos.
  */
  .product-deck__stage {
    --fan: 1;
    /*
      Width and spread work together, because the outer cards lie on top (Figma): each step is 66% of
      a card, so every inner card keeps about a third of itself visible between its neighbours. The
      width shrinks with more cards so the outermost ones still end inside the row (half x step + half a
      card <= 50%): 6 cards = 22cqi (the Figma ~420px at 1920), 7 = 20cqi, 8 = ~18cqi.
      Card size setting (--card-scale, 1 = that width): bigger cards overlap more instead of pushing the
      outer ones out of the row, so the step is the smaller of 66% of a card and what still fits (the
      outer card is tilted, which makes it ~0.6 of its width wide on each side of its centre, not 0.5).
    */
    --card-w: clamp(12rem, min(22cqi, 50cqi / (var(--half, 3) * 0.66 + 0.55)) * var(--card-scale, 1), 40rem);
    --spread: min(var(--card-w) * 0.66, (50cqi - var(--card-w) * 0.62) / max(var(--half, 3), 0.5));
    /* How far the outermost cards sit below the middle one (Figma: ~100px at 1920) */
    --arc: clamp(2rem, 6cqi, 7.5rem);
    --turn: 5deg;
    position: relative;
    container-type: inline-size;
    /*
      Own stacking layer: the cards' z-index (10-20) only counts inside the deck, so the sticky
      header and its mega menu always stay on top of them
    */
    isolation: isolate;
  }

  .product-deck[data-fan-active] .product-deck__stage {
    --fan: var(--fan-progress, 0);
  }

  .product-deck__list {
    position: relative;
    /*
      Room under the cards for the details card, which hangs well below the front card (Figma), plus
      the arc, so it still fits when an outer (lowest) card is the active one. The details card is about
      the same height at every desktop width, so its room is fixed (phones: below).
    */
    --info-room: 17.5rem;
    block-size: calc(var(--card-w) * var(--card-ratio, 0.7) + var(--info-room) + var(--arc));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /*
    --y follows an arc, not a V (Figma): with t = distance / biggest distance (0 middle ... 1 outer),
    the drop is half straight and half squared, so the neighbours of the middle card drop a little and
    the outer ones a lot. 6 cards: 12%, 48%, 100% of --arc.
  */
  .product-deck__card {
    --t: calc(var(--d) / max(var(--half, 3), 0.5));
    --x: calc(var(--o) * (var(--spread) * var(--fan) + 0.6rem * (1 - var(--fan))));
    --y: calc((var(--t) + var(--t) * var(--t)) / 2 * var(--arc) * var(--fan));
    --r: calc(var(--o) * (var(--turn) * var(--fan) + 3deg * (1 - var(--fan))));
    position: absolute;
    inset-block-start: var(--space-md);
    inset-inline-start: 50%;
    /*
      One stack from left to right: each card lies on top of the next one, so the left cards cover
      their inner neighbour (Figma: the rose card over the serum card) and the right ones tuck in
      behind the middle card. Leftmost = 10 + count - 1, rightmost = 10 (the active card is 20).
      Liquid writes --z, so no CSS round() is needed (older browsers do not know it).
    */
    z-index: var(--z, 10);
    inline-size: var(--card-w);
    aspect-ratio: 1 / var(--card-ratio, 0.7); /* Card height setting: height / width, 0.7 = the Figma 10 : 7 */
    margin-inline-start: calc(var(--card-w) / -2);
    transform: translate(var(--x), var(--y)) rotate(var(--r));
  }

  /*
    A card growing or shrinking glides (not while scrolling: the script drives that, frame by frame).
    Reduced motion: the card changes size at once.
  */
  @media (prefers-reduced-motion: no-preference) {
    .product-deck[data-moving] .product-deck__card {
      transition: transform 0.45s var(--ease-out);
    }
  }

  /*
    The active card: in its own place and tilt, on top and clearly bigger (Figma: about +12%; rows
    below 1200px: +6%, so a tilted outer card stays inside the page margin)
  */
  .product-deck__card.is-active {
    z-index: 20;
    transform: translate(var(--x), var(--y)) rotate(var(--r)) scale(calc(1 + var(--grow, 0.12) * var(--fan)));
  }

  .product-deck__media {
    position: absolute;
    inset: 0;
    overflow: hidden;
    border-radius: clamp(1rem, 1.6cqi, 1.6rem);
    background-color: var(--color-tint);
    box-shadow: 0 0.75rem 2rem #00000033;
  }

  .product-deck__media .image,
  .product-deck__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  /* "New": a gold glass pill, top right */
  .product-deck__badge {
    position: absolute;
    inset-block-start: 7%;
    inset-inline-end: 6%;
    z-index: 2;
    padding: 0.2em 0.85em;
    /*
      Figma Glass (Light -45deg 80%, Frost 100): 1px rim top-left 80% + weaker bottom-right, 35px blur.
      Border = the highlight colour (default #c8a24b, the Figma value). Refraction / Depth / Dispersion /
      Splay are left out, as on every other glass element.
    */
    border: 1px solid var(--color-accent);
    border-radius: var(--radius-pill);
    background-color: color-mix(in srgb, var(--color-accent) 75%, transparent);
    box-shadow:
      0 4px 10px 0 #00000040,
      inset 1px 1px 0 #ffffffcc,
      inset -1px -1px 0 #ffffffbd;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    color: #ffffff;
    font-size: var(--font-size-caption);
  }

  /* Covers the card, under the active card's cart button and info card */
  .product-deck__pick {
    position: absolute;
    inset: 0;
    z-index: 3;
    padding: 0;
    border: 0;
    border-radius: inherit;
    background: none;
    box-shadow: none;
    cursor: pointer;
  }

  .product-deck__pick:focus-visible {
    outline-offset: 4px;
  }

  /* The overlay behind the button ("Overlay behind the button") is drawn by the quick-add snippet */
  .product-deck__cart {
    position: absolute;
    inset-block-start: 7%;
    inset-inline-start: 5%;
    z-index: 4;
  }

  /*
    The glass info card: hangs low off the bottom of the active card (Figma), centred and 6% narrower than
    the card on each side, so it never pokes out sideways. Hidden (and out of the tab order) on the
    other cards.
    Figma Glass: Frost 100 = the theme's 35px blur, so the product image shows through as a soft tint at
    the top; Light -45deg 80% = a 1px rim on the top-left edges (80%) and a weaker one bottom-right;
    drop shadow 0 4px 15px #00000040. Refraction / Depth / Splay bend the background along the rim
    (SVG filter, Chrome only) and are left out, as on every other glass element.
  */
  .product-deck__info {
    position: absolute;
    inset-block-start: 76%; /* Figma: starts about three quarters down the card and hangs below it */
    /*
      6% in from each side, so it never pokes out past a tilted outer card. On small laptops the card is
      narrow: the padding gets smaller, the price goes above "Buy now" (the footer wraps) and the button
      text stays on one line.
    */
    inset-inline: 6%;
    z-index: 4;
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    padding-block: clamp(1rem, 0.5rem + 1.2vw, 2.25rem);
    padding-inline: clamp(0.875rem, 0.25rem + 1vw, 1.75rem);
    border-radius: clamp(0.9rem, 1.4cqi, 1.4rem);
    background-color: color-mix(in srgb, var(--color-background) 40%, transparent);
    box-shadow:
      0 4px 15px 0 #00000040,
      inset 1px 1px 0 #ffffffcc,
      inset -1px -1px 0 #ffffffbd;
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
    color: var(--color-text);
  }

  /*
    Hidden: the cart button and details of every card that is not open, and (before the script runs)
    the open card's while the visitor points at or tabs into another card (see the no-JS rules below)
  */
  .product-deck__card:not(.is-active) :is(.product-deck__cart, .product-deck__info),
  product-deck:not(:defined) .product-deck__list:has(.product-deck__card:not(.is-active):is(:hover, :focus-within)) .is-active :is(.product-deck__cart, .product-deck__info) {
    opacity: 0;
    visibility: hidden;
  }

  /*
    Shown quickly (0.08s wait, 0.25s fade) so it keeps up with the card growing; the old 0.25s wait +
    0.4s fade felt like lag. The info card also rises 0.5rem as it fades in (not with reduced motion).
  */
  .product-deck__card.is-active .product-deck__cart,
  .product-deck__card.is-active .product-deck__info {
    transition:
      opacity 0.25s var(--ease-out) 0.08s,
      transform 0.3s var(--ease-out) 0.08s,
      visibility 0s linear 0.08s;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-deck__card:not(.is-active) .product-deck__info {
      transform: translateY(0.5rem);
    }
  }

  /*
    Before the script runs (or without JavaScript) no card can be picked. Then pointing at a card or
    tabbing into it shows its details, so a visitor can still reach every product, and the first card's
    details hide meanwhile, so only one details card shows.
  */
  product-deck:not(:defined) .product-deck__card:is(:hover, :focus-within) {
    z-index: 21;
  }

  product-deck:not(:defined) .product-deck__card:is(:hover, :focus-within) :is(.product-deck__cart, .product-deck__info) {
    opacity: 1;
    visibility: visible;
    transform: none;
  }

  .product-deck__title {
    margin: 0;
    font-size: clamp(1.125rem, 0.9rem + 0.6vw, 1.6rem);
  }

  .product-deck__link {
    color: inherit;
    text-decoration: none;
  }

  .product-deck__link:hover {
    text-decoration: underline;
  }

  .product-deck__text {
    display: -webkit-box;
    margin: 0;
    overflow: hidden;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
  }

  .product-deck__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  .product-deck__price {
    color: var(--color-accent);
    font-weight: 600;
  }

  /* "Buy now": a small gold pill (Figma) */
  .product-deck__buy {
    --color-button: var(--color-accent);
    --color-button-border: var(--color-accent);
    --color-button-text: #ffffff;
    min-block-size: 2.5rem;
    padding-block: 0.4rem;
    padding-inline: clamp(0.75rem, 0.25rem + 0.7vw, 1.1rem);
    white-space: nowrap;
  }

  /*
    Solid fill: the global .button fill is 85% (Figma), and here the photo shows through the glass card
    behind it, so white text fell under 4.5:1 (3.8:1 with #8a6a1f). Two classes: .button loads later.
  */
  .button.product-deck__buy {
    background-color: var(--color-button);
  }

  .product-deck__buy-icon svg {
    display: block;
    inline-size: 1.5em;
    block-size: auto;
  }

  /* "Explore all": snippets/explore-button.liquid (shared with the Button block) */

  .product-deck__controls {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-md);
  }

  /*
    Rows (below 1200px; Figma mobile): tilted cards in rows,
    3 per row on tablets, 2 on phones. The cards overlap a little at the sides, and each row lies over
    the bottom of the row above (later cards on top). Left cards turn left, right cards turn right, a
    middle card stays straight. A row that is not full is centred (7 cards on a phone: the 7th sits
    alone in the middle). The open card grows in its own place and its details card covers the row
    below, as in the Figma.
    The same --x / --y / --r as the fan, so the animation also works here: --fan 0 = a small stack at
    the top, 1 = the rows. Liquid writes the numbers, so no CSS mod() / round() is needed (older
    browsers, e.g. Samsung Internet before Chromium 125, do not know them):
    --row-2 / --row-3   the card's row with 2 / 3 per row (0, 1, ...)
    --gx-2 / --gx-3     its column's offset from the middle of its row (2 per row: -0.5 / 0.5; 3: -1 / 0 /
                        1; a card alone in its row: 0)
    --rows-2 / --rows-3 the number of rows (on the deck)
    Card = one column wide, the columns 0.9 of a column apart: the cards overlap a little, and the open
    outer card (tilted, +6%) still ends inside the page margin, also with Card height 130%.
    In the last row the details card opens upwards over its own photo (data-last-row), so the list
    only needs a little room below the cards, whatever the length of the text.
  */
  @media (max-width: 1199px) {
    .product-deck__stage {
      --cols: 3;
      --rows: var(--rows-3, 1);
      --col-w: calc(100cqi / var(--cols));
      --card-w: var(--col-w);
      --step-x: calc(var(--col-w) * 0.9);
      --step-y: calc(var(--card-w) * var(--card-ratio, 0.7) * 0.86);
      --turn: 6deg; /* per column step: 3 per row = -6 / 0 / 6deg */
      --grow: 0.06;
    }

    .product-deck__list {
      /* The last row's details card hangs 10% below its card (+6% grow, shadow) */
      --info-room: calc(var(--card-w) * var(--card-ratio, 0.7) * 0.16 + 1rem);
      block-size: calc(
        var(--space-md) + var(--card-w) * var(--card-ratio, 0.7) + (var(--rows) - 1) * var(--step-y) +
          var(--info-room)
      );
    }

    .product-deck__card {
      --row: var(--row-3, 0);
      --gx: var(--gx-3, 0);
      --x: calc(var(--gx) * (var(--step-x) * var(--fan) + 0.6rem * (1 - var(--fan))));
      --y: calc(var(--row) * var(--step-y) * var(--fan));
      --r: calc(var(--gx) * (var(--turn) * var(--fan) + 3deg * (1 - var(--fan))));
    }

    /* Later cards on top (the open card stays on top of all: 20) */
    .product-deck__card:not(.is-active) {
      z-index: calc(10 + var(--i));
    }

    .product-deck__card[data-last-row~="3"] .product-deck__info {
      inset-block: auto -10%;
    }
  }

  /* Phones: the pill under the heading */
  @media (max-width: 749px) {
    .product-deck__header {
      grid-template-columns: 1fr;
      justify-items: center;
    }

    .product-deck__titles,
    .product-deck__pill {
      grid-column: 1;
      justify-self: center;
    }

    /* Rows: 2 per row, -6 / 6deg (the column offset is half a step here) */
    .product-deck__stage {
      --cols: 2;
      --rows: var(--rows-2, 1);
      --turn: 12deg;
    }

    .product-deck__card {
      --row: var(--row-2, 0);
      --gx: var(--gx-2, 0);
    }

    /* The last row with 2 per row (first undo the tablet rule, then set this one) */
    .product-deck__card[data-last-row~="3"] .product-deck__info {
      inset-block: 76% auto;
    }

    .product-deck__card[data-last-row~="2"] .product-deck__info {
      inset-block: auto -10%;
    }

    /*
      The details card is centred under its own card, 3% in from each side, so it never goes off the
      screen. The phone card is narrow, so the padding is small. Only the title, price and "Buy now"
      show (Figma mobile).
    */
    .product-deck__info {
      inset-inline: 3%;
      gap: var(--space-xs);
      padding: 0.75rem;
    }

    /* Long prices (a unit price such as "Rs. 15,333.33/100ml") wrap inside the narrow card */
    .product-deck__price {
      min-inline-size: 0;
      font-size: 0.875rem;
      overflow-wrap: anywhere;
    }

    /* "Buy now": smaller lettering on one line, so it fits next to or under the price */
    .product-deck__buy {
      min-block-size: 2.25rem;
      padding-inline: 0.75rem;
      font-size: 0.75rem;
      letter-spacing: 0.06em;
      white-space: nowrap;
    }

    .product-deck__title {
      font-size: 1.05rem;
    }

    .product-deck__text {
      display: none;
    }
  }

/* sections/product-faq.liquid */

  /*
    Figma 1920 ("Product details 11"): pale pink fill; eyebrow y 211 centred, heading ~70px (y ~297),
    accent word. Form card x 50–470 (420), y 348–818, white glass, radius ~24; "ASK US ANYTHING" accent
    caps ~15px; "Didn't Find Your Answer?" heading font ~24px; pill fields 380 x 50 (message 88 tall),
    "SEND MESSAGE" full width. Chat x 523–1870: questions = dark bubbles (~#1f1f1f, white text ~18px,
    padding ~14 / 16, radius ~16 with a square bottom-right corner) on the right, ~45px apart; the
    answer = a white bubble (x 523–1698, square top-left corner) under its question.
    Doodles: a chat outline top left of the heading, a "?" speech bubble top right, a big outline "?"
    behind the chat (left), two pale filled "?" in the middle, a white "?" bottom right.
  */
  .product-faq {
    /* One Figma pixel: the 1920px sizes get smaller on smaller screens */
    --px: min(calc(100vw / 1920), 0.0625rem);
    position: relative;
    display: block;
    overflow: clip; /* the doodles never widen the page */
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product-faq-empty {
    padding: var(--space-2xl) var(--page-margin);
    background-color: var(--color-background);
    text-align: center;
  }

  /* Figma: a pale pink fill, mixed from the scheme's accent so it follows the scheme */
  .product-faq--tint {
    background-color: color-mix(in srgb, var(--color-accent) 3%, var(--color-background));
  }

  .product-faq__inner {
    position: relative;
    z-index: 1;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-faq__intro {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-lg);
    text-align: center;
  }

  .product-faq__intro .eyebrow {
    margin: 0;
  }

  /* The eyebrow as the section's h2 (no heading): the eyebrow look, not the heading font */
  .product-faq__eyebrow-heading {
    font-family: var(--font-body--family);
  }

  .product-faq__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-faq__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /*
    Phones and tablets (agreed, Figma phone Variant98): the chat, then the form card centred (at most
    40rem). Desktop: form left (420 of 1820), chat right
  */
  .product-faq__layout {
    display: grid;
    gap: var(--space-2xl);
    margin-block-start: max(var(--space-xl), calc(40 * var(--px, 0.0625rem)));
  }

  @media (max-width: 1199px) {
    .product-faq__card {
      justify-self: center;
      inline-size: min(100%, 40rem);
    }

    /* Name + Email side by side */
    .product-faq__pair {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: var(--space-sm);
    }
  }

  @media (min-width: 1200px) {
    .product-faq__pair {
      display: contents;
    }

    .product-faq__layout {
      /* The form at least 24rem: on small laptops (~1264px) the Figma share left a 288px card */
      grid-template-columns: minmax(24rem, 420fr) minmax(0, 1347fr);
      align-items: start;
      gap: calc(53 * var(--px, 0.0625rem));
    }

    .product-faq__card {
      grid-column: 1;
      grid-row: 1;
    }

    .product-faq__chat {
      grid-column: 2;
      grid-row: 1;
    }

    .product-faq__layout--chat-only {
      grid-template-columns: minmax(0, 1fr);
    }

    .product-faq__layout--chat-only .product-faq__chat {
      grid-column: 1;
    }

    /* No question shows: the card alone, centred */
    .product-faq__layout--form-only {
      grid-template-columns: minmax(0, 1fr);
    }

    .product-faq__layout--form-only .product-faq__card {
      justify-self: center;
      inline-size: min(100%, 40rem);
    }
  }

  /* The chat */
  .product-faq__chat {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-lg), calc(45 * var(--px, 0.0625rem)));
  }

  /* Plain block flow inside <details> (older browsers ignore display: flex on it): the bubbles shrink
     to their text (fit-content) and an auto margin pushes them right (question) or left (answer) */
  .product-faq__question {
    display: block;
    inline-size: fit-content;
    max-inline-size: min(100%, 34rem);
    margin-inline-start: auto;
    padding: max(0.75rem, calc(14 * var(--px, 0.0625rem))) max(1rem, calc(16 * var(--px, 0.0625rem)));
    border-radius: 1rem 1rem 0.25rem 1rem;
    background-color: var(--color-text);
    box-shadow: var(--shadow-card-soft);
    color: var(--color-background);
    font-size: var(--font-size-body);
    line-height: 1.35;
    list-style: none; /* no ▸ marker */
    cursor: pointer;
    transition: background-color var(--duration-fast) var(--ease-out);
  }

  .product-faq__question::-webkit-details-marker {
    display: none;
  }

  .product-faq__question:hover {
    background-color: color-mix(in srgb, var(--color-text) 85%, var(--color-accent));
  }

  .product-faq__question:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  /* The answer: a white bubble on the left under its question (Figma: up to 1175 of 1347) */
  .product-faq__answer {
    inline-size: fit-content;
    max-inline-size: 87%;
    margin-inline-end: auto;
    margin-block-start: max(var(--space-md), calc(18 * var(--px, 0.0625rem)));
    padding: max(0.75rem, calc(14 * var(--px, 0.0625rem))) max(1rem, calc(16 * var(--px, 0.0625rem)));
    /* Figma "Frame 1984077925": white, a soft grey shadow, square bottom-left corner (the bubble's tail) */
    border-radius: 20px 20px 20px 0;
    /* White on light schemes, a raised colour on dark ones (white with light text could not be read) */
    background-color: var(--color-surface-raised);
    box-shadow: 0 2px 10px #c2c2c240;
    font-size: var(--font-size-body);
    line-height: 1.5;
  }

  .product-faq__answer-text > * {
    margin: 0;
  }

  .product-faq__answer-text > * + * {
    margin-block-start: var(--space-sm);
  }

  /* A new answer pops in like a chat reply */
  @media (prefers-reduced-motion: no-preference) {
    .product-faq__item[open] .product-faq__answer {
      animation: product-faq-reply 0.45s var(--ease-out) 0.08s backwards;
    }
  }

  @keyframes product-faq-reply {
    from {
      opacity: 0;
      translate: 0 0.75rem;
      scale: 0.97;
    }
  }

  .product-faq__empty {
    margin: 0;
  }

  /* Editor only: a question with no question or no answer */
  .product-faq__answer.product-faq__answer--note {
    margin-block-start: 0;
    font-style: italic;
  }

  /* The form card */
  .product-faq__card {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
    padding: max(var(--space-lg), calc(30 * var(--px, 0.0625rem))) max(var(--space-md), calc(20 * var(--px, 0.0625rem)));
    /* Figma: a white glass edge. --color-surface-raised = white on light schemes, a soft light mix on dark ones */
    border: 1px solid var(--color-surface-raised);
    border-radius: 1.84625rem; /* Figma 29.54px */
    background-color: color-mix(in srgb, var(--color-card, #ffffff) 70%, transparent);
    box-shadow: var(--shadow-card-soft);
    -webkit-backdrop-filter: blur(12px);
    backdrop-filter: blur(12px);
  }

  .product-faq__label {
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-label);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-faq__card-heading {
    margin: 0;
    font-size: var(--font-size-h3);
    font-weight: var(--font-heading--weight); /* Figma 500: no heading 500 font file is loaded (performance) */
  }

  /* Fields spaced with gap (no margins: Shopify may add an hCaptcha element inside the form) */
  .product-faq__form {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-md), calc(25 * var(--px, 0.0625rem)));
    margin-block-start: var(--space-sm);
  }

  /* Two classes: the global input[type] / textarea rules outweigh one */
  .product-faq .product-faq__input {
    margin: 0; /* the global :where(label) + input gap: here the label floats over the field */
    border-color: var(--color-surface-raised); /* Figma: white edge (light schemes) */
    border-radius: 3.0625rem; /* Figma 49px */
    background-color: color-mix(in srgb, var(--color-surface-raised) 50%, transparent); /* Figma: 50% white */
    font-weight: 500;
    padding-inline: max(var(--space-lg), calc(30 * var(--px, 0.0625rem)));
  }

  .product-faq .product-faq__textarea {
    min-block-size: calc(88 * var(--px, 0.0625rem));
    border-radius: 1rem;
  }

  /* Floating labels: at rest in the field (as the Figma placeholder), on focus / when filled on the border */
  .product-faq__field {
    position: relative;
  }

  .product-faq .product-faq__field-label {
    position: absolute;
    z-index: 1;
    inset-block-start: 50%;
    inset-inline-start: max(var(--space-lg), calc(30 * var(--px, 0.0625rem)));
    padding-inline: 0.35rem;
    margin-inline-start: -0.35rem;
    border-radius: var(--radius-pill);
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background)); /* 4.5:1 or more, as placeholders */
    font-size: var(--font-size-body-sm);
    font-weight: 500;
    line-height: 1.2;
    pointer-events: none; /* a click goes to the field under it */
    translate: 0 -50%;
    transition:
      inset-block-start var(--duration-fast) var(--ease-out),
      font-size var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  /* The message box: the label on the first line, not the middle */
  .product-faq .product-faq__field--message .product-faq__field-label {
    inset-block-start: 1.6rem;
  }

  /*
    Up on the border while its field has focus or text. The selectors name the field: a bare
    :not(:placeholder-shown) matched the label itself (it never shows a placeholder), so every label sat
    on the border even in an empty field
  */
  .product-faq .product-faq__field:has(.product-faq__input:focus, .product-faq__input:not(:placeholder-shown)) .product-faq__field-label {
    inset-block-start: 0;
    background-color: var(--color-surface-raised); /* solid: the border line must not run through the label */
    color: var(--color-accent);
    font-size: var(--font-size-small);
  }

  @media (prefers-reduced-motion: reduce) {
    .product-faq .product-faq__field-label {
      transition: none;
    }
  }

  /*
    Full width: the leaving paper plane must fly further than on a normal pill, or it stops inside the
    button next to the one parking in (two icons). As on the contact page, the button is its own size
    container and the plane flies 55% of its width (it starts near the middle)
  */
  .product-faq .product-faq__submit {
    --explore-fly: 55cqi;
    container-type: inline-size;
    inline-size: 100%;
    margin-block-start: var(--space-sm);
  }

  /*
    The doodles (decoration only), placed from the Figma relative to the content box (x 50–1870, top =
    the eyebrow): left / width in % of 1820, top in Figma px from the eyebrow. Behind the content: the
    inner box is a stacking context (z-index 1), so z-index -1 keeps them under the text but above the
    section's fill.
  */
  .product-faq__decor {
    position: absolute;
    z-index: -1;
    inset: 0;
    pointer-events: none;
    user-select: none;
  }

  .product-faq__doodle {
    position: absolute;
    background-color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
    -webkit-mask: var(--doodle) center / contain no-repeat;
    mask: var(--doodle) center / contain no-repeat;
  }

  /* Two chat bubbles, top left of the heading (Figma x 380–495, y 178) */
  .product-faq__doodle--chat {
    --doodle: var(--doodle-chat);
    inset-block-start: calc(-33 * var(--px, 0.0625rem));
    inset-inline-start: 18.1%;
    inline-size: 6.3%;
    aspect-ratio: 320 / 202;
  }

  /* The "?" speech bubble, top right (x 1455–1580, y 110), very faint and tilted */
  .product-faq__doodle--bubble {
    --doodle: var(--doodle-bubble);
    /* Figma 100px above the eyebrow, but never above the section's top padding (it would be cut off) */
    inset-block-start: max(calc(-100 * var(--px, 0.0625rem)), calc(-1 * var(--section-padding-top, 64px)));
    inset-inline-start: 77.2%;
    inline-size: 6.9%;
    aspect-ratio: 320 / 322;
    background-color: color-mix(in srgb, var(--color-text) 7%, var(--color-background));
    rotate: 14deg;
  }

  /* Three outline "?" behind the chat, left (x 470–773, y 460–893) */
  .product-faq__doodle--questions {
    --doodle: var(--doodle-questions);
    inset-block-start: calc(249 * var(--px, 0.0625rem));
    inset-inline-start: 23.1%;
    inline-size: 16.6%;
    aspect-ratio: 640 / 835;
    background-color: color-mix(in srgb, var(--color-accent) 9%, var(--color-background));
  }

  /* Two pale filled "?" in the middle (x 1114–1286, y 525–715) */
  .product-faq__doodle--pale,
  .product-faq__doodle--pale-small {
    --doodle: var(--doodle-question);
    aspect-ratio: 152 / 250;
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
  }

  .product-faq__doodle--pale {
    inset-block-start: calc(314 * var(--px, 0.0625rem));
    inset-inline-start: 58.4%;
    inline-size: 5.6%;
    rotate: -8deg;
  }

  .product-faq__doodle--pale-small {
    inset-block-start: calc(394 * var(--px, 0.0625rem));
    inset-inline-start: 64%;
    inline-size: 3.9%;
    rotate: 10deg;
  }

  /* A white "?" bottom right (x 1733–1843, y 888) */
  .product-faq__doodle--white {
    --doodle: var(--doodle-question);
    inset-block-start: calc(677 * var(--px, 0.0625rem));
    inset-inline-start: 93.5%;
    inline-size: 5.4%;
    aspect-ratio: 152 / 250;
    background-color: var(--color-card, #ffffff);
    rotate: 14deg;
  }

  @media (max-width: 1199px) {
    .product-faq__doodle--questions,
    .product-faq__doodle--chat,
    .product-faq__doodle--pale-small {
      display: none;
    }
  }
  /* Phones (Figma Variant98): 24px heading, small bubbles, a compact form card */
  @media (max-width: 749px) {
    .product-faq__intro {
      gap: var(--space-sm);
    }

    .product-faq__heading {
      font-size: 1.5rem;
      line-height: 1.2;
    }

    .product-faq__layout {
      gap: var(--space-lg);
      margin-block-start: var(--space-lg);
    }

    .product-faq__chat {
      gap: var(--space-sm);
    }

    .product-faq__question,
    .product-faq__answer {
      padding: 0.4rem 0.6rem;
      font-size: 0.75rem;
      line-height: 1.45;
    }

    .product-faq__question {
      max-inline-size: 85%;
      border-radius: 0.5rem 0.5rem 0.125rem 0.5rem;
    }

    .product-faq__answer {
      max-inline-size: 85%;
      margin-block-start: var(--space-sm);
      border-radius: 0.625rem 0.625rem 0.625rem 0;
    }

    .product-faq__card {
      gap: var(--space-xs);
      padding: var(--space-md) var(--space-sm);
      border-radius: 1rem;
    }

    .product-faq__label {
      font-size: 0.625rem;
    }

    .product-faq__card-heading {
      font-size: 0.875rem;
    }

    .product-faq__form {
      gap: var(--space-sm);
      margin-block-start: var(--space-xs);
    }

    .product-faq .product-faq__input {
      min-block-size: 2.25rem;
      padding-block: 0.4rem;
      padding-inline: var(--space-md);
      font-size: 0.75rem;
    }

    .product-faq .product-faq__textarea {
      min-block-size: 3.5rem;
    }

    .product-faq .product-faq__field-label {
      inset-inline-start: var(--space-md);
      font-size: 0.75rem;
    }

    .product-faq .product-faq__field--message .product-faq__field-label {
      inset-block-start: 1.1rem;
    }

    .product-faq .product-faq__field:has(.product-faq__input:focus, .product-faq__input:not(:placeholder-shown)) .product-faq__field-label {
      font-size: 0.625rem;
    }

    .product-faq .product-faq__submit {
      margin-block-start: 0;
    }
  }

/* sections/product-highlights.liquid */

  /*
    Figma 1920 ("Product details 7"): intro x 50–500 (eyebrow y 212, heading ~70px 2 lines, the first
    words accent, text ~22px); grid x 640–1870 in 3 columns (~410 each), 1px pale lines between the
    columns and between the rows, cells padded ~32; icon ~28px accent; title ~22px; text ~17px grey.
    Spec table x 645–1750, 2 columns of label caps ~15px + value ~18px, a hairline (faded at both ends)
    under each row. --px = one Figma pixel: the 1920px sizes get smaller on smaller screens.
  */
  .product-highlights {
    --px: min(calc(100vw / 1920), 0.0625rem);
    --highlights-line: var(--color-card-border);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product-highlights-empty {
    padding: var(--space-2xl) var(--page-margin);
    background-color: var(--color-background);
    text-align: center;
  }

  .product-highlights__inner {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-highlights__eyebrow {
    margin: 0 0 var(--space-lg);
  }

  .product-highlights__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-highlights__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .product-highlights__text {
    margin-block-start: max(var(--space-lg), calc(70 * var(--px)));
    font-size: var(--font-size-body-lg);
    line-height: 1.65;
  }

  /* The grid: lines between the columns and between the rows, none on the outside edges */
  .product-highlights__grid {
    --columns: 3;
    display: grid;
    grid-template-columns: repeat(var(--columns), minmax(0, 1fr));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .product-highlights__item {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    padding: max(var(--space-lg), calc(32 * var(--px)));
    border-block-end: 1px solid var(--highlights-line);
    /* One by one across a row: --col = the cell's column (0 = first) */
    --animate-delay: calc(var(--col, 0) * 100ms);
  }

  .product-highlights__icon {
    display: inline-flex;
    margin-block-end: var(--space-xs);
    color: var(--color-accent);
  }

  .product-highlights__icon svg,
  .product-highlights__icon-image {
    inline-size: max(1.5rem, calc(28 * var(--px)));
    block-size: max(1.5rem, calc(28 * var(--px)));
    object-fit: contain;
  }

  .product-highlights__title {
    margin: 0;
    font-family: var(--font-body--family);
    font-size: var(--font-size-body-lg);
    font-weight: var(--font-weight-medium);
    line-height: 1.3;
  }

  .product-highlights__item-text {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 72%, var(--color-background));
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  /* The spec table fills column by column (--spec-rows from Liquid) */
  .product-highlights__specs {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-template-rows: repeat(var(--spec-rows, 1), auto);
    grid-auto-flow: column;
    gap: 0 max(var(--space-lg), calc(70 * var(--px)));
    margin: max(var(--space-xl), calc(60 * var(--px))) 0 0;
    padding-inline-start: max(var(--space-sm), calc(5 * var(--px)));
  }

  .product-highlights__main > .product-highlights__specs:first-child {
    margin-block-start: 0;
  }

  /* The row hairline fades at both ends (border-image: only the bottom border has a width) */
  .product-highlights__spec {
    display: grid;
    grid-template-columns: minmax(7rem, 200fr) minmax(0, 330fr);
    align-items: baseline;
    gap: var(--space-md);
    padding-block: var(--space-md);
    border-block-end: 1px solid var(--highlights-line);
    border-image: linear-gradient(
        90deg,
        #00000000,
        var(--highlights-line) 12%,
        var(--highlights-line) 88%,
        #00000000
      )
      1;
  }

  .product-highlights__spec dt {
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-highlights__spec dd {
    margin: 0;
    font-size: var(--font-size-body-sm);
  }

  /* Tablets and up: 3 columns; a line before each cell that does not start a row; no line under the last row */
  @media (min-width: 750px) {
    .product-highlights__item:not(:nth-child(3n + 1)) {
      border-inline-start: 1px solid var(--highlights-line);
    }

    .product-highlights__item:nth-child(3n + 1):nth-last-child(-n + 3),
    .product-highlights__item:nth-child(3n + 1):nth-last-child(-n + 3) ~ .product-highlights__item {
      border-block-end: 0;
    }

    .product-highlights__item:nth-child(3n + 2) {
      --col: 1;
    }

    .product-highlights__item:nth-child(3n + 3) {
      --col: 2;
    }
  }

  /* Desktop: the intro beside the benefits (Figma 450 : 1230) */
  @media (min-width: 1200px) {
    .product-highlights__inner--split {
      grid-template-columns: minmax(0, 450fr) minmax(0, 1230fr);
      column-gap: max(var(--space-xl), calc(140 * var(--px)));
    }
  }

  /* Phones (Variant96-3 / 96-4): 2 columns of benefits, a 1-column spec table, smaller text, half the padding */
  @media (max-width: 749px) {
    .product-highlights {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }

    .product-highlights__inner {
      gap: var(--space-lg);
    }

    .product-highlights__eyebrow {
      margin-block-end: var(--space-md);
    }

    .product-highlights__heading {
      font-size: 1.625rem;
      line-height: 1.2;
    }

    .product-highlights__text {
      margin-block-start: var(--space-md);
      font-size: 0.8125rem;
    }

    .product-highlights__grid {
      --columns: 2;
    }

    .product-highlights__item {
      gap: var(--space-xs);
      padding: var(--space-md) var(--space-sm);
    }

    .product-highlights__item:nth-child(2n) {
      border-inline-start: 1px solid var(--highlights-line);
      --col: 1;
    }

    .product-highlights__item:nth-child(2n + 1):nth-last-child(-n + 2),
    .product-highlights__item:nth-child(2n + 1):nth-last-child(-n + 2) ~ .product-highlights__item {
      border-block-end: 0;
    }

    .product-highlights__icon {
      margin-block-end: var(--space-2xs, 0.25rem);
    }

    .product-highlights__icon svg,
    .product-highlights__icon-image {
      inline-size: 1.125rem;
      block-size: 1.125rem;
    }

    .product-highlights__title {
      font-size: 0.9375rem;
    }

    .product-highlights__item-text {
      font-size: 0.75rem;
      line-height: 1.5;
    }

    .product-highlights__specs {
      grid-template-columns: minmax(0, 1fr);
      grid-template-rows: none;
      grid-auto-flow: row;
      margin-block-start: var(--space-lg);
      padding-inline-start: var(--space-sm);
    }

    .product-highlights__spec dt {
      font-size: 0.6875rem;
    }

    .product-highlights__spec dd {
      font-size: 0.75rem;
    }
  }

/* sections/product-how-to.liquid */

  /*
    Figma 1920 ("Product details 13"): eyebrow y 211; heading x 50–870, ~70px, 2 lines, the last words
    accent; timeline x 50–665: a 1px pale line with dots (active: accent ~22px with a pale ring; others
    pale ~18px), number accent caps ~16px, title heading font ~28px, the open step's text ~18px; media
    x 1158–1825 (667 x 546), square corners, caption white ~18px bottom left on a dark fade, "01/04"
    caps bottom right, a 2px line under them (accent fill over pale). --px = one Figma pixel: the 1920px
    sizes get smaller on smaller screens.
    Phones (Variant97-1): heading on top, then a portrait media panel (~157 x 187 at 390) on the left
    beside the timeline.
  */
  .product-how-to {
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product-how-to-empty {
    padding: var(--space-2xl) var(--page-margin);
    background-color: var(--color-background);
    text-align: center;
  }

  /* Phones and tablets: the heading on top, the media panel on the left beside the timeline */
  .product-how-to__inner {
    display: grid;
    grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
    grid-template-areas:
      "intro intro"
      "media timeline";
    align-items: center;
    gap: var(--space-xl) var(--space-lg);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* No heading: no intro row (its row gap would leave empty space); no media: one column */
  .product-how-to--no-intro .product-how-to__inner {
    grid-template-areas: "media timeline";
  }

  .product-how-to--no-media .product-how-to__inner {
    grid-template-columns: minmax(0, 1fr);
    grid-template-areas:
      "intro"
      "timeline";
  }

  .product-how-to--no-media.product-how-to--no-intro .product-how-to__inner {
    grid-template-areas: "timeline";
  }

  .product-how-to__intro {
    grid-area: intro;
  }

  .product-how-to__timeline {
    grid-area: timeline;
  }

  .product-how-to__media {
    grid-area: media;
  }

  .product-how-to__eyebrow {
    margin: 0 0 var(--space-lg);
  }

  .product-how-to__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-how-to__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* The timeline: a pale line down the dots */
  .product-how-to__steps {
    --dot-column: 1.625rem;
    --step-gap: max(var(--space-md), calc(24 * var(--px)));
    position: relative;
    display: flex;
    flex-direction: column;
    gap: max(var(--space-md), calc(26 * var(--px)));
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .product-how-to__steps::before {
    content: "";
    position: absolute;
    inset-block: 0.75rem 0;
    inset-inline-start: calc(var(--dot-column) / 2);
    inline-size: 1px;
    background-color: var(--color-card-border);
  }

  .product-how-to__step-button {
    position: relative;
    display: grid;
    grid-template-columns: var(--dot-column) minmax(0, 1fr);
    column-gap: var(--step-gap);
    align-items: start;
    inline-size: 100%;
    min-block-size: 0;
    padding: 0;
    border: 0;
    background: none;
    box-shadow: none;
    color: inherit;
    text-align: start;
    text-transform: none;
    letter-spacing: normal;
    cursor: pointer;
  }

  .product-how-to__step-button:hover {
    background: none;
  }

  .product-how-to__step-button:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 4px;
  }

  /* The dot; the "ping" on the current step: a ring grows out of the dot and fades */
  .product-how-to__dot {
    position: relative;
    grid-column: 1;
    grid-row: 1 / span 2;
    justify-self: center;
    margin-block-start: 0.3rem;
    inline-size: 1.125rem;
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 14%, var(--color-background));
    transition:
      background-color var(--duration-fast) var(--ease-out),
      box-shadow var(--duration-fast) var(--ease-out);
  }

  .product-how-to__step.is-active .product-how-to__dot {
    background-color: var(--color-accent);
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--color-accent) 16%, var(--color-background));
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-how-to__step.is-active .product-how-to__dot::after {
      content: "";
      position: absolute;
      inset: 0;
      border-radius: 50%;
      background-color: var(--color-accent);
      /* 3 pings (4.8s) when a step opens (WCAG 2.2.2: nothing moves by itself for more than 5s
         without a pause). The ::after has the dot's size and colour, so it can't be seen when it ends. */
      animation: product-how-to-ping 1.6s cubic-bezier(0, 0, 0.2, 1) 3;
    }

    /* While the steps play by themselves, the ping goes on: the pause button stops both */
    .product-how-to.is-playing .product-how-to__step.is-active .product-how-to__dot::after {
      animation-iteration-count: infinite;
    }

    .product-how-to.is-paused .product-how-to__step.is-active .product-how-to__dot::after {
      animation: none;
    }

    .product-how-to__step.is-active .product-how-to__text {
      animation: product-how-to-text var(--duration-normal) var(--ease-out);
    }

    .product-how-to__slide {
      transition: opacity 0.6s var(--ease-out);
    }
  }

  @keyframes product-how-to-ping {
    75%,
    100% {
      opacity: 0;
      scale: 2.4;
    }
  }

  .product-how-to__number {
    grid-column: 2;
    color: var(--color-accent);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
  }

  .product-how-to__title {
    grid-column: 2;
    font-family: var(--font-heading--family);
    font-size: var(--font-size-h3);
    line-height: 1.25;
  }

  /* Only the open step shows its text (it opens with a short fade); without JS every text shows */
  .product-how-to__text {
    display: none;
    margin: var(--space-sm) 0 0 calc(var(--dot-column) + var(--step-gap));
    font-size: var(--font-size-body-sm);
    line-height: 1.6;
  }

  .product-how-to__step.is-active .product-how-to__text {
    display: block;
  }

  @media (scripting: none) {
    .product-how-to__text {
      display: block;
    }
  }

  @keyframes product-how-to-text {
    from {
      opacity: 0;
      translate: 0 0.5rem;
    }
  }

  /* The media panel: the slides stacked, the open one shown; a step with no image = the tint */
  .product-how-to__media {
    position: relative;
    display: grid;
    overflow: hidden;
    aspect-ratio: 157 / 187;
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
    color: #ffffff;
  }

  .product-how-to__slide {
    grid-area: 1 / 1;
    margin: 0;
    opacity: 0;
  }

  .product-how-to__slide.is-active {
    opacity: 1;
  }

  .product-how-to__image {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .product-how-to__placeholder {
    fill: color-mix(in srgb, var(--color-text) 30%, transparent);
  }

  /* A dark fade at the bottom, so the white caption and counter stay readable on any photo */
  .product-how-to__media::after {
    content: "";
    position: absolute;
    inset: auto 0 0;
    block-size: 35%;
    background: linear-gradient(to top, #00000080, #00000000);
    pointer-events: none;
  }

  .product-how-to__caption {
    position: absolute;
    z-index: 1;
    inset-block-end: max(var(--space-lg), calc(28 * var(--px)));
    inset-inline: max(var(--space-sm), calc(20 * var(--px))) 5.5rem; /* clear of the counter */
    margin: 0;
    font-size: var(--font-size-body);
    line-height: 1.3;
  }

  .product-how-to__counter {
    position: absolute;
    z-index: 1;
    inset-block-end: max(var(--space-lg), calc(24 * var(--px)));
    inset-inline-end: max(var(--space-sm), calc(20 * var(--px)));
    margin: 0;
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    font-variant-numeric: tabular-nums;
  }

  /*
    The controls: on the media panel the pause button sits in the top corner and the line along the
    bottom; with no media panel, both go under the timeline (the line in the text colours).
  */
  .product-how-to__media > .product-how-to__controls {
    display: contents; /* its children sit on the panel; the wrapper must not add a grid row */
  }

  .product-how-to__media .product-how-to__pause {
    position: absolute;
    z-index: 1;
    inset-block-start: max(var(--space-sm), calc(16 * var(--px)));
    inset-inline-end: max(var(--space-sm), calc(16 * var(--px)));
    border-color: #ffffff80;
    background-color: #00000040;
    color: #ffffff;
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
  }

  .product-how-to__media .product-how-to__progress {
    position: absolute;
    z-index: 1;
    inset-block-end: max(var(--space-sm), calc(12 * var(--px)));
    inset-inline: max(var(--space-sm), calc(20 * var(--px)));
  }

  .product-how-to__timeline > .product-how-to__controls {
    display: flex;
    align-items: center;
    gap: var(--space-md);
    margin-block-start: var(--space-lg);
    padding-inline-start: calc(var(--dot-column) + var(--step-gap));
  }

  .product-how-to__timeline .product-how-to__progress {
    flex: 1;
    max-inline-size: 20rem;
    background-color: var(--color-card-border);
  }

  .product-how-to__pause {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 2rem;
    block-size: 2rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 1px solid color-mix(in srgb, var(--color-accent) 50%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    color: var(--color-accent);
    cursor: pointer;
  }

  .product-how-to__pause svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .product-how-to__pause-icon--play,
  .product-how-to__pause[aria-pressed="true"] .product-how-to__pause-icon--pause {
    display: none;
  }

  .product-how-to__pause[aria-pressed="true"] .product-how-to__pause-icon--play {
    display: block;
  }

  .product-how-to__pause[hidden] {
    display: none;
  }

  /* Without JS nothing plays, so the button would do nothing */
  @media (scripting: none) {
    .product-how-to .product-how-to__pause {
      display: none;
    }
  }

  /* The progress line: its fill is the step timer (the script moves on when the animation ends) */
  .product-how-to__progress {
    display: block;
    block-size: 2px;
    background-color: #ffffff59;
  }

  .product-how-to__progress > span {
    display: block;
    inline-size: 0;
    block-size: 100%;
    background-color: var(--color-accent);
  }

  .product-how-to.is-playing .product-how-to__progress > span {
    animation: product-how-to-progress var(--step-duration) linear forwards;
  }

  .product-how-to.is-paused .product-how-to__progress > span {
    animation-play-state: paused;
  }

  /*
    Without autoplay (click only / reduced motion / no JS): the line shows which step of how many is
    open (--step-fill: step 1 from Liquid, then from the script)
  */
  .product-how-to:not(.is-playing) .product-how-to__progress > span {
    inline-size: var(--step-fill);
    transition: inline-size var(--duration-normal) var(--ease-out);
  }

  @keyframes product-how-to-progress {
    from {
      inline-size: 0;
    }

    to {
      inline-size: 100%;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .product-how-to__dot {
      transition: none;
    }
  }

  /* Phones (Variant97-1): media ~42% wide, smaller text and dots */
  @media (max-width: 749px) {
    .product-how-to__inner {
      grid-template-columns: minmax(0, 21fr) minmax(0, 29fr);
      gap: var(--space-xl) var(--space-md);
    }

    .product-how-to__eyebrow {
      margin-block-end: var(--space-sm);
    }

    .product-how-to__heading {
      font-size: 1.5rem;
      line-height: 1.2;
    }

    .product-how-to__steps {
      --dot-column: 0.625rem;
      --step-gap: var(--space-sm);
      gap: var(--space-lg);
    }

    .product-how-to__steps::before {
      inset-block-start: 0.5rem;
    }

    .product-how-to__dot {
      margin-block-start: 0.2rem;
      inline-size: 0.4375rem;
    }

    .product-how-to__step.is-active .product-how-to__dot {
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--color-accent) 16%, var(--color-background));
    }

    .product-how-to__number {
      font-size: 0.625rem;
    }

    .product-how-to__title {
      font-size: 0.9375rem;
    }

    .product-how-to__text {
      margin-block-start: var(--space-xs);
      font-size: 0.75rem;
      line-height: 1.5;
    }

    .product-how-to__caption {
      inset-block-end: var(--space-md);
      inset-inline-end: 3.25rem;
      font-size: 0.75rem;
    }

    .product-how-to__counter {
      inset-block-end: var(--space-md);
      font-size: 0.625rem;
      letter-spacing: 0.05em;
    }

    .product-how-to__media .product-how-to__progress {
      inset-block-end: 0.5rem;
    }

    .product-how-to__pause {
      inline-size: 1.75rem;
      block-size: 1.75rem;
    }
  }

  /* Desktop: the heading and the timeline on the left, the media panel (667 x 546) centred on the right */
  @media (min-width: 1200px) {
    .product-how-to__inner {
      grid-template-columns: minmax(0, 1000fr) minmax(0, 667fr);
      grid-template-areas:
        "intro media"
        "timeline media";
      /* A tall media panel gives its extra height to the timeline row, not to the heading row */
      grid-template-rows: auto 1fr;
      align-items: start;
      gap: max(var(--space-xl), calc(44 * var(--px))) max(var(--space-xl), calc(110 * var(--px)));
    }

    .product-how-to--no-intro .product-how-to__inner {
      grid-template-areas: "timeline media";
      grid-template-rows: auto;
    }

    .product-how-to__heading {
      max-inline-size: 20ch; /* Figma: 2 lines */
    }

    .product-how-to__media {
      align-self: center;
      aspect-ratio: 667 / 546;
    }
  }

/* sections/product-list.liquid */

  .product-list {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  /* The "Section width" setting (critical.css: --section-width), minus the page margins */
  .product-list__inner {
    display: block;
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  /* Top bar: the heading area on the left, the tabs or the strip's arrows on the right */
  .product-list__top {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--space-md) var(--space-lg);
    margin-block-end: var(--space-2xl);
  }

  /* Heading area: blocks stack with space between */
  .product-list__header {
    display: flex;
    flex: 1 1 20rem;
    flex-direction: column;
    gap: var(--space-md);
  }

  .product-list__items {
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /* Grid and tabs: the big cards in columns */
  .product-list__items--grid {
    display: grid;
    grid-template-columns: repeat(var(--columns-mobile), minmax(0, 1fr));
    gap: var(--space-lg) var(--space-md);
  }

  @media (min-width: 750px) {
    .product-list__items--grid {
      grid-template-columns: repeat(var(--columns-desktop), minmax(0, 1fr));
      gap: var(--space-xl);
    }
  }

  /* Each card fills its grid cell, so cards in a row are equal height */
  .product-list__items--grid .product-list__item,
  .product-list__items--grid .product-list__item > .product-card {
    block-size: 100%;
  }

  /* Compact rows: one per row on phones, two per row from 750px (empty-bag mockup "Main") */
  .product-list__items--rows {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--space-md);
  }

  @media (min-width: 750px) {
    .product-list__items--rows {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  /* Both cards in a row the same height (a unit price line makes one taller) */
  .product-list__items--rows .product-list__item,
  .product-list__items--rows .product-row-card {
    block-size: 100%;
  }

  /*
    Scrolling strip: one row that scrolls sideways; each card snaps to the left edge. The scrollbar is
    hidden (the arrows and touch swipes move it), padding keeps the cards' shadows from being cut off.
  */
  .product-list__items--strip {
    display: flex;
    gap: var(--space-md);
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    padding-block: var(--space-xs) var(--space-md);
    scroll-snap-type: inline mandatory;
    scrollbar-width: none;
  }

  .product-list__items--strip::-webkit-scrollbar {
    display: none;
  }

  .product-list__items--strip .product-list__item {
    flex: none;
    inline-size: clamp(14rem, 22vw, 20rem);
    scroll-snap-align: start;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-list__items--strip {
      scroll-behavior: smooth;
    }
  }

  /* Round outline arrows; the left one is the right arrow turned around */
  .product-list__arrows {
    display: flex;
    gap: var(--space-sm);
  }

  .product-list .product-list__arrow {
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    min-block-size: 0;
    block-size: 2.75rem;
    padding: 0;
    border: 1px solid var(--color-text);
    border-radius: var(--radius-pill);
    background: none;
    box-shadow: none;
    color: var(--color-text);
    cursor: pointer;
  }

  .product-list .product-list__arrow:hover:not(:disabled) {
    background-color: var(--color-text);
    color: var(--color-background);
  }

  .product-list .product-list__arrow:disabled {
    opacity: 0.35;
    cursor: default;
  }

  .product-list__arrow svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

  .product-list__arrow[data-strip-prev] svg {
    rotate: 180deg;
  }

  /* Right-to-left pages: "next" goes to the left, so both arrows point the other way */
  .product-list__arrows:dir(rtl) svg {
    scale: -1 1;
  }

  /*
    Tabs layout: one grid for the heading blocks, the tab row and the Tab blocks' panels (all drawn in one
    flow, see the markup). Phones: one column (heading, tab row, panels). From 750px: the heading blocks on
    the left, the tab row on the right of the first row (empty-bag mockup "Tabs"), the panels under both.
    <product-tab> (one per Tab block) has no box of its own: its button and panel are grid items.
    No Tab shows (all off, or no products on the store): the section shows nothing.
  */
  .product-list--tabs.product-list--live:not(:has(product-tab)) {
    display: none;
  }

  /* Theme editor: the note "Add a Tab block..." shows only while no Tab shows */
  .product-list__flow:has(product-tab) .product-list__editor-note {
    display: none;
  }

  /* The hidden h2 goes when the heading area has its own h1 / h2 (display: none = not read either) */
  .product-list:has(:is(.product-list__header, .product-list__flow) :is(h1, h2)) .product-list__fallback-heading {
    display: none;
  }

  /* Top bar with nothing in it (only Tab blocks left over from the Tabs layout): no empty gap */
  .product-list__top:not(:has(.product-list__arrows, .product-list__header > :not(.shopify-block), .product-list__header > .shopify-block > *)) {
    display: none;
  }

  .product-list__flow {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: end;
    gap: var(--space-md) var(--space-lg);
  }

  /*
    Shopify puts each theme block in a wrapper (<div class="shopify-block">); without a box of its own,
    the block's content (heading, text, tab button, panel) takes part in this grid. The rules below also
    work when there is no wrapper.
  */
  .product-list__flow > .shopify-block,
  .product-list__tab-item {
    display: contents;
  }

  .product-list__flow > *,
  .product-list__flow > .shopify-block > *,
  .product-list__tab-item > .product-list__panel {
    grid-column: 1 / -1;
  }

  .product-list__tablist {
    order: 1;
    justify-self: start;
  }

  .product-list__tab-item > .product-list__panel {
    order: 2;
    margin-block-start: var(--space-lg);
  }

  .product-list__tab-off {
    order: 2;
    margin: 0;
    font-style: italic;
    opacity: 0.7;
  }

  @media (min-width: 750px) {
    .product-list__flow {
      grid-template-columns: minmax(0, 1fr) auto;
    }

    /* The heading blocks in the first column (not the tab row, Tab blocks or the editor note) */
    .product-list__flow > :not(.product-list__tablist, .product-list__tab-item, .product-list__tab-off, .shopify-block),
    .product-list__flow > .shopify-block > :not(.product-list__tab-item, .product-list__tab-off) {
      grid-column: 1;
    }

    .product-list__flow > .product-list__tablist {
      grid-column: 2;
      grid-row: 1;
      justify-self: end;
    }
  }

  /* Tabs: a glass pill holding the tab buttons; the chosen tab is the solid button colour */
  .product-list__tablist {
    display: flex;
    flex-wrap: wrap;
    gap: 0.375rem;
    padding: 0.25rem;
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong);
    box-shadow: var(--glass-shadow), var(--glass-rim);
  }

  /* With JavaScript, before the script moves the buttons in: the row keeps its height (no jump) */
  .js .product-list__tablist:empty {
    min-block-size: 3rem;
    min-inline-size: 12rem;
  }

  .product-list .product-list__tab {
    min-block-size: 2.5rem;
    padding-block: 0;
    padding-inline: 1.25rem;
    border: 0;
    border-radius: var(--radius-pill);
    background: none;
    box-shadow: none;
    color: var(--color-text);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
    cursor: pointer;
  }

  .product-list .product-list__tab[aria-selected='true'] {
    background-color: var(--color-button);
    color: var(--color-button-text);
  }

  /* A button still in its Tab block (no script yet, or none) is hidden; the tab row shows the moved ones */
  .product-list__tab-item > .product-list__tab {
    display: none;
  }

  /*
    With JavaScript only the chosen tab's panel shows. Before the script runs, only the first Tab's panel
    shows: a Tab block that comes after another Tab block hides its panel (with the Shopify block wrapper,
    and without it). Without JavaScript every panel shows with its tab name, and there is no tab row.
  */
  .js product-list-ui:defined .product-list__panel:not(.is-active),
  .js product-list-ui:not(:defined) .shopify-block:has(product-tab) ~ .shopify-block .product-list__panel,
  .js product-list-ui:not(:defined) .product-list__tab-item ~ .product-list__tab-item > .product-list__panel,
  .no-js .product-list__tablist {
    display: none;
  }

  /*
    With JavaScript the tab row shows the tab names, so the panel's h3 title is visually hidden; screen
    readers still get it, so the outline stays h2 section, h3 tab, h4 products (as without JavaScript).
  */
  .js .product-list__panel-title {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .product-list__panel-title {
    margin: 0 0 var(--space-md);
    font-size: var(--font-size-h3);
  }

/* sections/product-overview.liquid */

  /*
    Figma 1920 ("Product details 6"): eyebrow y 213; heading x 50–475, ~70px, 3 lines, accent words;
    text x 730–1185 ~22px; spec rows under it: label caps ~15px wide spacing (x 730), value ~18px
    (x 870), ~38px apart; image x 1259–1870 (611 x 437, square corners), 3 red dots ~12px with a white
    ring. Quote x 285–1080, the accent font ~56px, the accent phrase red; figures 2 x 2 x 1297–1830:
    value ~24px medium, label caps ~15px, a hairline under the first row.
  */
  .product-overview {
    /* One Figma pixel: the screen width / 1920, never more than 1px (the Figma sizes are the largest) */
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product-overview__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-overview__top {
    display: grid;
    /* Built in Liquid from the parts that are there (Figma 680 : 528 : 611) */
    grid-template-columns: var(--top-columns);
    align-items: start;
    gap: max(var(--space-lg), calc(50 * var(--px, 0.0625rem)));
  }

  .product-overview__eyebrow {
    margin: 0 0 var(--space-lg);
  }

  .product-overview__heading {
    margin: 0;
    max-inline-size: 11ch;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-overview__heading em,
  .product-overview__quote em {
    color: var(--color-accent);
    font-style: normal;
  }

  .product-overview__body {
    padding-block-start: max(var(--space-lg), calc(80 * var(--px, 0.0625rem)));
  }

  .product-overview__text {
    font-size: var(--font-size-body-lg);
    line-height: 1.65;
  }

  .product-overview__specs {
    display: grid;
    gap: var(--space-md);
    margin: max(var(--space-lg), calc(40 * var(--px, 0.0625rem))) 0 0;
  }

  .product-overview__spec {
    display: grid;
    grid-template-columns: minmax(6rem, 140fr) minmax(0, 315fr);
    align-items: baseline;
    gap: var(--space-md);
  }

  .product-overview__spec dt {
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-overview__spec dd {
    margin: 0;
    font-size: var(--font-size-body-sm);
  }

  .product-overview__media {
    position: relative;
    aspect-ratio: 611 / 437;
    background-color: var(--color-tint, color-mix(in srgb, var(--color-text) 5%, var(--color-background)));
  }

  .product-overview__image {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .product-overview__placeholder {
    fill: color-mix(in srgb, var(--color-text) 30%, transparent);
  }

  /* Hotspots: a red dot with a white ring; a pulse ring draws the eye (not with reduced motion) */
  /* Physical left / top: the image is not mirrored in RTL, so x = 0% is always its left edge */
  .product-overview__hotspot {
    position: absolute;
    top: var(--spot-y);
    left: var(--spot-x);
    translate: -50% -50%;
  }

  .product-overview__dot {
    position: relative;
    display: block;
    inline-size: 2.75rem; /* the touch target; the visible dot is drawn smaller */
    block-size: 2.75rem;
    min-block-size: 0;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
    box-shadow: none;
    cursor: pointer;
  }

  .product-overview__dot::before {
    content: "";
    position: absolute;
    inset: 50% auto auto 50%;
    inline-size: 0.875rem;
    block-size: 0.875rem;
    border: 2px solid #ffffff;
    border-radius: 50%;
    background-color: var(--color-accent);
    box-shadow: 0 2px 6px #00000040;
    translate: -50% -50%;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-overview__dot::after {
      content: "";
      position: absolute;
      inset: 50% auto auto 50%;
      inline-size: 0.875rem;
      block-size: 0.875rem;
      border-radius: 50%;
      background-color: color-mix(in srgb, var(--color-accent) 45%, transparent);
      translate: -50% -50%;
      animation: product-hotspot-pulse 2.4s var(--ease-out) infinite;
    }
  }

  @keyframes product-hotspot-pulse {
    to {
      opacity: 0;
      scale: 3;
    }
  }

  .product-overview__dot:hover,
  .product-overview__dot:focus-visible {
    background: none;
  }

  .product-overview__dot:focus-visible {
    outline: 2px solid #ffffff;
    outline-offset: -6px;
  }

  /* The card: a frosted glass box beside the dot (left of it when the dot is near the right edge) */
  .product-overview__card {
    position: absolute;
    z-index: 2;
    inset-block-start: 50%;
    inline-size: max(13rem, calc(240 * var(--px, 0.0625rem)));
    padding: var(--space-sm) var(--space-md);
    border: 1px solid #ffffff59;
    border-radius: max(0.625rem, calc(12 * var(--px, 0.0625rem)));
    background-color: #ffffff33;
    box-shadow: 0 8px 30px #0000002e;
    color: #ffffff;
    opacity: 0;
    pointer-events: none;
    translate: 0 -50%;
    visibility: hidden;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      visibility 0s linear var(--duration-fast);
    -webkit-backdrop-filter: blur(14px);
    backdrop-filter: blur(14px);
  }

  .product-overview__hotspot--right .product-overview__card {
    left: calc(100% + 0.25rem);
  }

  .product-overview__hotspot--left .product-overview__card {
    right: calc(100% + 0.25rem);
  }

  /* Each hotspot is its own layer (translate): the one with an open card comes to the front, so the
     other dots don't show over its card */
  .product-overview__hotspot:hover,
  .product-overview__hotspot:focus-within {
    z-index: 3;
  }

  .product-overview__hotspot:has([aria-expanded="true"]) {
    z-index: 3;
  }

  /*
    Placed by the script (data-placed): left / top from the hotspot's box, so the card stays inside the
    image. Physical left / top: the script measures the screen, which is the same in RTL.
  */
  .product-overview__hotspot[data-placed] .product-overview__card {
    inset: auto;
    left: var(--card-left);
    top: var(--card-top);
    max-inline-size: var(--card-max, none);
    translate: none;
  }

  .product-overview__hotspot:hover .product-overview__card,
  .product-overview__dot:focus-visible + .product-overview__card,
  .product-overview__dot[aria-expanded="true"] + .product-overview__card {
    opacity: 1;
    visibility: visible;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      visibility 0s;
  }

  /* Escape closes a card shown by hover or focus too (WCAG 1.4.13), until the pointer or focus leaves */
  .product-overview__hotspot[data-dismissed] .product-overview__card {
    opacity: 0;
    visibility: hidden;
  }

  .product-overview__card p {
    margin: 0;
  }

  .product-overview__card-title {
    margin-block-end: 0.2em;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-body-lg);
    line-height: 1.2;
    text-shadow: 0 0 12px #ffffffb3;
  }

  .product-overview__card-text {
    font-size: var(--font-size-small);
    line-height: 1.5;
    text-shadow: 0 1px 4px #00000059;
  }

  /* Bottom row: the quote (centre-left) and the figures (right) */
  .product-overview__bottom {
    display: grid;
    grid-template-columns: minmax(0, 1210fr) minmax(0, 611fr);
    align-items: start;
    gap: max(var(--space-lg), calc(50 * var(--px, 0.0625rem)));
    margin-block-start: max(var(--space-2xl, 4rem), calc(70 * var(--px, 0.0625rem)));
  }

  .product-overview__quote {
    margin: 0;
    padding-inline-start: calc(235 * var(--px, 0.0625rem));
  }

  .product-overview__quote p {
    margin: 0;
    font-family: var(--font-accent--family);
    font-style: var(--font-accent--style);
    font-weight: var(--font-accent--weight);
    font-size: max(2rem, calc(56 * var(--px, 0.0625rem)));
    line-height: 1.2;
  }

  /* The quote marks, drawn by CSS so the merchant types only the words */
  .product-overview__quote p::before {
    content: "“ ";
  }

  .product-overview__quote p::after {
    content: " ”";
  }

  .product-overview__figures {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0 max(var(--space-lg), calc(80 * var(--px, 0.0625rem)));
    margin: 0;
  }

  /*
    In a <dl> the label (<dt>) must come before its value (<dd>), so the HTML reads "Felt skin softer:
    98%"; column-reverse shows the value on top, as in the Figma
  */
  .product-overview__figure {
    display: flex;
    flex-direction: column-reverse;
    justify-content: flex-end;
    gap: var(--space-xs);
    padding-block: var(--space-md);
  }

  /* A hairline under the first row, only when there is a second row (3+ figures) */
  .product-overview__figures:has(> :nth-child(3)) > .product-overview__figure:nth-child(-n + 2) {
    border-block-end: 1px solid var(--color-card-border);
  }

  .product-overview__figure-value {
    margin: 0;
    font-size: var(--font-size-h3);
    font-weight: var(--font-weight-medium);
  }

  .product-overview__figure-label {
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Tablets: heading + text side by side, the image full width under them, then quote and figures */
  @media (max-width: 1199px) {
    .product-overview__top {
      grid-template-columns: var(--top-columns-tablet);
    }

    .product-overview__media {
      grid-column: 1 / -1;
    }

    .product-overview__bottom {
      grid-template-columns: minmax(0, 1fr);
    }

    .product-overview__quote {
      padding-inline-start: 0;
    }
  }

  /* Phones (brief: the Overview drops the spec rows and the quote): one column */
  @media (max-width: 749px) {
    .product-overview__top {
      grid-template-columns: minmax(0, 1fr);
    }

    .product-overview__body {
      padding-block-start: 0;
    }
  }

/* sections/product-pairs.liquid */

  /*
    Figma 1920 ("Product details 5"): eyebrow y 143 (66px rule + accent caps); heading ~64px, "well with"
    in the accent colour; 4 cards x 63 / 357 / 649 / 943 (~254 wide, ~40px apart; the 2nd and 4th 40px
    lower); the summary card x 1305–1857 (552 wide), white, pale border, radius ~16, padding ~32:
    "YOUR PRODUCTS" grey caps, one line per product (name left, price right), a hairline, "Bundle Total",
    the total ~28px, ADD ALL TO CART full-width red pill.
    Phone 375 ("Variant97"): 3 cards a row (~98 wide, ~20px apart, the middle one ~20px lower); the 4th
    card with the summary next to it over 2 columns; summary padding ~12, small text (label 9px, lines
    12px, total 13px), a small button.
  */
  .product-pairs {
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /* No products to pair with (no complementary ones and no fallback): nothing to show on the store */
  .product-pairs[data-empty]:not([data-editor]) {
    display: none;
  }

  /* Theme editor: the note shows only while there is nothing to pair; the empty form stays hidden */
  .product-pairs:not([data-empty]) .product-pairs__editor-note,
  .product-pairs[data-empty] .product-pairs__layout {
    display: none;
  }

  .product-pairs__editor-note {
    margin: 0;
    padding: var(--space-lg);
    border: 1px dashed var(--color-card-border);
    border-radius: 0.75rem;
  }

  .product-pairs__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-pairs__header {
    margin-block-end: max(var(--space-xl), calc(40 * var(--px, 0.0625rem)));
  }

  .product-pairs__eyebrow {
    margin: 0 0 var(--space-md);
  }

  .product-pairs__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-pairs__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .product-pairs__layout {
    --pairs-gap: max(var(--space-md), calc(40 * var(--px, 0.0625rem)));
    display: grid;
    grid-template-columns: minmax(0, 1180fr) minmax(18rem, 552fr);
    align-items: start;
    gap: max(var(--space-xl), calc(110 * var(--px, 0.0625rem)));
  }

  /* The cards: up to 4 in a row; the 2nd and 4th sit 40px lower (Figma) */
  .product-pairs__list {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--pairs-gap);
  }

  .product-pairs__list > :nth-child(even) {
    margin-block-start: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  .product-pairs__summary {
    display: flex;
    flex-direction: column;
    min-inline-size: 0;
    padding: max(var(--space-lg), calc(32 * var(--px, 0.0625rem)));
    border: 1px solid var(--color-card-border);
    border-radius: max(0.75rem, calc(16 * var(--px, 0.0625rem)));
    background-color: var(--color-background);
    box-shadow: 0 4px 30px #0000000d;
  }

  .product-pairs__label,
  .product-pairs__none {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background)); /* 60% gave 4.35:1 on white */
    font-size: var(--font-size-small);
  }

  .product-pairs__label {
    margin: 0 0 var(--space-md);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .product-pairs__lines,
  .product-pairs__none {
    margin: 0;
    padding: 0 0 var(--space-lg);
    border-block-end: 1px solid var(--color-card-border);
  }

  .product-pairs__lines {
    display: flex;
    flex-direction: column;
    gap: var(--space-sm);
    list-style: none;
  }

  .product-pairs__lines:empty,
  .product-pairs__none[hidden] {
    display: none;
  }

  .product-pairs__line {
    display: flex;
    justify-content: space-between;
    gap: var(--space-md);
    font-size: var(--font-size-body-sm);
  }

  /* The price never breaks onto two lines; a long name wraps instead */
  .product-pairs__line > :last-child {
    flex: none;
    white-space: nowrap;
  }

  .product-pairs__total {
    margin-block: var(--space-lg);
  }

  .product-pairs__total p {
    margin: 0;
  }

  .product-pairs__total-label {
    font-size: var(--font-size-body-sm);
    font-weight: var(--font-weight-medium);
  }

  .product-pairs__total-price {
    margin-block-start: var(--space-xs);
    font-size: var(--font-size-h3);
    font-weight: var(--font-weight-medium);
  }

  .product-pairs .product-pairs__add {
    inline-size: 100%;
    margin: 0;
  }

  .product-pairs__add-icon {
    display: inline-flex;
  }

  .product-pairs__add-icon svg {
    inline-size: 1.125rem;
    block-size: 1.125rem;
  }

  /* While it adds: a small spinning ring in place of the cart icon (as the Product section's Add to cart) */
  .product-pairs__add.is-adding {
    cursor: progress;
  }

  .product-pairs__add.is-adding .product-pairs__add-icon {
    display: none;
  }

  .product-pairs__add.is-adding [data-pairs-add-label] {
    opacity: 0.7;
  }

  .product-pairs__add.is-adding::before {
    content: "";
    flex: none;
    inline-size: 1em;
    block-size: 1em;
    border: 2px solid color-mix(in srgb, currentcolor 25%, transparent);
    border-block-start-color: currentcolor;
    border-radius: 50%;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-pairs__add.is-adding::before {
      animation: product-pairs-spin 0.7s linear infinite;
    }
  }

  @keyframes product-pairs-spin {
    to {
      rotate: 1turn;
    }
  }

  .product-pairs__add:disabled {
    cursor: not-allowed;
    opacity: 0.6;
  }

  .product-pairs__message {
    margin: var(--space-sm) 0 0;
    color: var(--color-error);
    font-size: var(--font-size-small);
  }

  /*
    Phones and tablets (Variant97): one grid of 3 columns for the cards AND the summary (the list's box
    goes away with display: contents; it has no list role, which older WebKit drops with display: contents). The middle card of each row is lower.
    The summary takes its own row, or the 2 free places next to a last card that is alone in its row.
  */
  @media (max-width: 1199px) {
    .product-pairs__layout {
      --pairs-gap: clamp(1rem, 0.6rem + 1.8vw, 2rem);
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: var(--pairs-gap);
    }

    .product-pairs__list {
      display: contents;
    }

    .product-pairs__list > :nth-child(even) {
      margin-block-start: 0;
    }

    .product-pairs__list > :nth-child(3n + 2) {
      margin-block-start: var(--pairs-gap);
    }

    .product-pairs__summary {
      grid-column: 1 / -1;
    }

    .product-pairs__layout:has(.pair-card:last-child:nth-child(3n + 1)) .product-pairs__summary {
      grid-column: span 2;
    }
  }

  /* Phones: the small summary card of Variant97 */
  @media (max-width: 749px) {
    .product-pairs__header {
      margin-block-end: var(--space-lg);
    }

    .product-pairs__heading {
      font-size: var(--font-size-h2);
    }

    .product-pairs__summary {
      padding: 0.75rem;
      border-radius: 0.625rem;
    }

    .product-pairs__label {
      margin-block-end: var(--space-sm);
      font-size: 0.5625rem;
    }

    .product-pairs__lines,
    .product-pairs__none {
      gap: var(--space-xs);
      padding-block-end: var(--space-md);
      font-size: 0.75rem;
    }

    .product-pairs__line {
      gap: var(--space-sm);
      font-size: 0.75rem;
    }

    .product-pairs__total {
      margin-block: var(--space-md);
    }

    .product-pairs__total-label {
      font-size: 0.6875rem;
    }

    .product-pairs__total-price {
      font-size: 0.8125rem;
      font-weight: 700;
    }

    .product-pairs .product-pairs__add {
      min-block-size: 2.25rem;
      padding-inline: var(--space-sm);
      font-size: 0.625rem;
    }

    .product-pairs__add-icon svg {
      inline-size: 0.75rem;
      block-size: 0.75rem;
    }
  }

/* sections/product-panels.liquid */

  product-panels {
    display: block;
  }

  .product-panels {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .product-panels__inner {
    display: flex;
    flex-direction: column;
    gap: clamp(2.5rem, 1.5rem + 3vw, 6rem);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-panels__header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md);
  }

  .product-panels__titles {
    display: flex;
    flex-direction: column;
    gap: var(--space-md);
  }

  .product-panels__eyebrow,
  .product-panels__heading {
    margin: 0;
  }

  .product-panels__heading {
    font-size: var(--font-size-display);
  }

  /* "Editor's *Picks*": italic words in the highlight colour, not slanted */
  .product-panels__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .product-panels__view-all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    color: color-mix(in srgb, var(--color-text) 70%, var(--color-background));
  }

  .product-panels__arrow svg {
    inline-size: 1em;
    block-size: auto;
  }

  /*
    The strips (from 750px): rows of strips, all the same height. Every strip grows (flex) by 1; the
    open one by 1.85, so it is about twice as wide (Figma: ~425px vs ~230px). The width change glides.
  */
  .product-panels__list {
    --panels-strip-height: calc(var(--panels-height, 30) * 1rem);
    display: flex;
    flex-wrap: wrap;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /*
    Row breaks: an invisible full-width item, shown after every 3rd / 4th / 5th / 7th product. Each
    product is followed by a break, so product k is child 2k - 1 and its break is child 2k: a break
    after every 4th product = :nth-child(8n).
  */
  .product-panels__break {
    display: none;
    flex-basis: 100%;
    block-size: 0;
  }

  /*
    For each width (n per row):
    - the break after every n-th product (child 2n) is shown
    - several rows (product n + 1 = child 2n + 1 exists): every strip is 60% of the Strip height, so
      2 or 3 rows don't make the section several screens tall
    - a strip alone in the last row (the last child, right after a shown break) doesn't stretch across
      the whole width: it keeps the width of an open strip in a full row, 1.85 / (n + 0.85)
  */

  /* Tablet: 3 per row */
  @media (min-width: 750px) and (max-width: 989px) {
    .product-panels__break:nth-child(6n) {
      display: block;
    }

    .product-panels__list:has(> .product-panels__item:nth-child(7)) {
      --panels-strip-height: calc(var(--panels-height, 30) * 0.6rem);
    }

    .product-panels__break:nth-child(6n) + .product-panels__item:last-child {
      flex: 0 0 calc(100% * 1.85 / 3.85);
    }
  }

  /* Laptop: 4 per row */
  @media (min-width: 990px) and (max-width: 1199px) {
    .product-panels__break:nth-child(8n) {
      display: block;
    }

    .product-panels__list:has(> .product-panels__item:nth-child(9)) {
      --panels-strip-height: calc(var(--panels-height, 30) * 0.6rem);
    }

    .product-panels__break:nth-child(8n) + .product-panels__item:last-child {
      flex: 0 0 calc(100% * 1.85 / 4.85);
    }
  }

  /* Larger laptop: 5 per row */
  @media (min-width: 1200px) and (max-width: 1599px) {
    .product-panels__break:nth-child(10n) {
      display: block;
    }

    .product-panels__list:has(> .product-panels__item:nth-child(11)) {
      --panels-strip-height: calc(var(--panels-height, 30) * 0.6rem);
    }

    .product-panels__break:nth-child(10n) + .product-panels__item:last-child {
      flex: 0 0 calc(100% * 1.85 / 5.85);
    }
  }

  /* Monitor: 7 per row (8 products = a second row with one strip) */
  @media (min-width: 1600px) {
    .product-panels__break:nth-child(14n) {
      display: block;
    }

    .product-panels__list:has(> .product-panels__item:nth-child(15)) {
      --panels-strip-height: calc(var(--panels-height, 30) * 0.6rem);
    }

    .product-panels__break:nth-child(14n) + .product-panels__item:last-child {
      flex: 0 0 calc(100% * 1.85 / 7.85);
    }
  }

  /*
    "Fill the screen height" (Figma: the section is one screen, content in the middle, strips about 45%
    of the screen height). The section is at least one screen tall from 750px. On monitors (one row of
    7) the strips also use the bigger of the Strip height setting and 45% of the screen, so they grow on
    tall screens. Smaller screens have several rows, so they keep the set height.
  */
  @media (min-width: 750px) {
    .product-panels--fill {
      display: flex;
      flex-direction: column;
      justify-content: center;
      min-block-size: 100svh;
    }
  }

  @media (min-width: 1600px) {
    .product-panels--fill .product-panels__list {
      --panels-strip-height: max(calc(var(--panels-height, 30) * 1rem), 45svh);
    }
  }

  /*
    Each strip is a flex column that pushes its glass card to the bottom. The card stays in the normal
    flow (not absolute), so the strip, not the card, anchors the title's stretched link: the whole
    strip is clickable.
  */
  .product-panels__item {
    position: relative;
    isolation: isolate;
    display: flex;
    flex: 1 1 0;
    flex-direction: column;
    justify-content: flex-end;
    block-size: var(--panels-strip-height);
    padding: var(--space-md);
    min-inline-size: 0;
    overflow: hidden;
    background-color: var(--color-tint);
    color: #ffffff;
    transition: flex-grow 0.6s var(--ease-out);
  }

  .product-panels__item.is-active {
    flex-grow: 1.85;
  }

  .product-panels__media {
    position: absolute;
    inset: 0;
    z-index: -1;
  }

  .product-panels__media .image,
  .product-panels__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  /*
    Figma overlay on every strip: only the lower part (from 45% down, behind the card), fading from
    clear to 50% black at the bottom: linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,0.5) 100%).
    The top of the photo stays untouched.
  */
  .product-panels__media::after {
    content: "";
    position: absolute;
    inset: 45% 0 0;
    background: linear-gradient(180deg, #00000000 0%, #00000080 100%);
  }


  /* Big faded number, top left (Figma: gold, semi-transparent) */
  .product-panels__number {
    position: absolute;
    inset-block-start: var(--space-md);
    inset-inline-start: var(--space-md);
    color: color-mix(in srgb, var(--color-accent) 70%, transparent);
    font-size: var(--font-size-h2);
    font-weight: 600;
    line-height: 1;
  }

  /* Round glass cart button (snippets/quick-add.liquid): 9px from the open strip's top-right corner */
  .product-panels__cart {
    position: absolute;
    inset-block-start: 0.5625rem;
    inset-inline-end: 0.5625rem;
    z-index: 2;
  }

  /* The overlay behind the button ("Overlay behind the button") is drawn by the quick-add snippet */

  /*
    Glass card, bottom left of the open strip: title, short text, price. On closed strips it is
    transparent (but still focusable: tabbing to its link opens that strip).
  */
  .product-panels__card {
    display: flex;
    flex-direction: column;
    gap: var(--space-xs);
    /* Full width of the open strip, minus the strip's own padding on both sides (Figma) */
    inline-size: 100%;
    padding: var(--space-md) var(--space-lg);
    border: 1px solid #ffffff59;
    border-radius: var(--panels-card-radius, 12px); /* "Card corner size" setting */
    /*
      Figma: light "liquid" glass that takes on the photo's colours (blur), over the overlay below it,
      which keeps the white text readable.
    */
    background-color: #ffffff33;
    -webkit-backdrop-filter: blur(var(--glass-frost)) saturate(1.2);
    backdrop-filter: blur(var(--glass-frost)) saturate(1.2);
    box-shadow: var(--glass-rim);
    text-shadow: 0 1px 2px #00000033;
    /* The card must not take the stretched link's place: clicks fall through to it (its own links: below) */
    pointer-events: none;
  }

  .product-panels__card,
  .product-panels__cart {
    opacity: 0;
    transition: opacity var(--duration-base) var(--ease-out);
  }

  /*
    From 750px: the cart button is invisible on closed strips, so it mustn't catch clicks there
    (keyboard focus still opens the strip). The phone grid has its own rule for this (in the phone
    styles below); the phone slider and "one per row" layouts show every button, so all stay clickable.
  */
  @media (min-width: 750px) {
    .product-panels__item:not(.is-active) .product-panels__cart {
      pointer-events: none;
    }
  }

  .product-panels__item.is-active :is(.product-panels__card, .product-panels__cart) {
    opacity: 1;
    transition-delay: 0.25s;
  }

  /*
    Without JavaScript (or before the script runs): every strip shows its card and cart button, so the
    content of every row is visible and usable. The first strip stays wider (is-active from Liquid).
    :not(:defined) = the <product-panels> element has no script yet. Once the script runs, the cards
    of the closed strips fade out. The extra classes beat the "closed strip" rules.
  */
  product-panels:not(:defined) :is(.product-panels__card, .product-panels__cart) {
    opacity: 1;
  }

  product-panels.product-panels:not(:defined) .product-panels__item .product-panels__cart {
    pointer-events: auto;
  }

  /*
    Desktop: the details card slides up from below the strip while the strip widens, instead of
    fading in 0.25s later (that made the card look like a separate piece). It moves with a negative
    bottom margin, NOT transform: a transform would make the card the containing block of the title
    link's stretched ::after, and the whole strip would stop being clickable. The strip's
    overflow: hidden hides the card until it rises into view. Closing is quicker than opening.
  */
  @media (min-width: 750px) and (prefers-reduced-motion: no-preference) {
    .product-panels__card {
      margin-block-end: -14rem;
      transition:
        margin-block-end 0.3s var(--ease-out),
        opacity 0.2s var(--ease-out);
    }

    .product-panels__item.is-active .product-panels__card {
      margin-block-end: 0;
      transition:
        margin-block-end 0.6s var(--ease-out) 0.05s,
        opacity 0.3s var(--ease-out) 0.05s;
    }

    product-panels:not(:defined) .product-panels__card {
      margin-block-end: 0;
    }
  }

  .product-panels__title {
    margin: 0;
    color: #ffffff;
    font-size: var(--font-size-h3);
  }

  .product-panels__text {
    margin: 0;
    color: #ffffffe6;
    font-size: var(--font-size-body-sm);
  }

  .product-panels__price .price__compare {
    color: #ffffffb3;
  }

  .product-panels__price .price__current {
    color: #ffffff;
    font-size: var(--font-size-body-lg);
    font-weight: 600;
  }

  /* The title's link covers the whole strip: one click target per product */
  .product-panels__link {
    color: inherit;
    text-decoration: none;
  }

  .product-panels__link::after {
    content: "";
    position: absolute;
    inset: 0;
  }

  /* Ring on the whole strip only where :has() works; other browsers keep the link's own ring */
  @supports selector(:has(*)) {
    .product-panels__link:focus-visible {
      outline: none;
    }

    .product-panels__item:has(.product-panels__link:focus-visible) {
      outline: 2px solid var(--color-accent);
      outline-offset: -2px;
    }
  }

  .product-panels__card a {
    pointer-events: auto;
  }

  /* Phones and small tablets: three layouts, from the Phones > Layout setting */
  @media (max-width: 749px) {
    /*
      The shape comes from aspect-ratio, not the Strip height. Phones > Strip height scales the
      layout's own height: 100% = its shape below, 150% = half as tall again (--panels-mobile-scale).
    */
    .product-panels__item {
      block-size: auto;
    }

    /* Slider: a sideways-scrolling row of cards */
    .product-panels--mobile-slider .product-panels__list {
      flex-wrap: nowrap;
      gap: var(--space-sm);
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
    }

    .product-panels--mobile-slider .product-panels__item {
      flex: 0 0 75%;
      aspect-ratio: 3 / calc(4 * var(--panels-mobile-scale, 1));
      scroll-snap-align: start;
    }

    /* One product per row */
    .product-panels--mobile-single .product-panels__list {
      flex-direction: column;
      gap: var(--space-sm);
    }

    .product-panels--mobile-single .product-panels__item {
      flex: none;
      aspect-ratio: 4 / calc(5 * var(--panels-mobile-scale, 1));
    }

    /* Slider and one per row: every card shows its details and its cart button */
    :is(.product-panels--mobile-slider, .product-panels--mobile-single)
      :is(.product-panels__card, .product-panels__cart) {
      opacity: 1;
    }

    /*
      Grid (mobile design): 2 tiles per row, 2px apart, a little taller than wide. As on desktop, only
      the open tile shows its card and cart button; the others show the photo and the number.
    */
    .product-panels--mobile-grid .product-panels__list {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 2px;
    }

    .product-panels--mobile-grid .product-panels__item {
      aspect-ratio: 10 / calc(11 * var(--panels-mobile-scale, 1));
      padding: var(--space-xs);
    }

    .product-panels--mobile-grid .product-panels__item:not(.is-active) .product-panels__cart {
      pointer-events: none;
    }

    .product-panels--mobile-grid .product-panels__number {
      inset-block-start: var(--space-xs);
      inset-inline-start: var(--space-xs);
      font-size: var(--font-size-body);
    }

    /* Smaller cart button on the small tiles (36px; the icon scales with it) */
    .product-panels--mobile-grid .quick-add__button {
      --quick-add-size: 2.25rem;
    }

    .product-panels--mobile-grid .product-panels__cart {
      inset-block-start: 0.375rem;
      inset-inline-end: 0.375rem;
    }

    .product-panels--mobile-grid .product-panels__card {
      gap: 0.125rem;
      padding: var(--space-xs) var(--space-sm);
    }

    /* The tile is small: title (2 lines at most) and price only */
    .product-panels--mobile-grid .product-panels__title {
      display: -webkit-box;
      overflow: hidden;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: 2;
      line-clamp: 2;
      font-size: var(--font-size-caption);
    }

    .product-panels--mobile-grid .product-panels__text {
      display: none;
    }

    .product-panels--mobile-grid .product-panels__price .price__current {
      font-size: var(--font-size-body-sm);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .product-panels__item {
      transition: none;
    }
  }

/* sections/product-related.liquid */

  /*
    Figma 1920 ("Variant31"): eyebrow x 50 (rule 66 + "YOU MAY ALSO LOVE" accent caps ~18px) at y 226;
    "VIEW ALL →" grey caps, wide spacing, right (x ~1730–1870); cards from y 292: 2 tiles 890 x 398
    (x 50–940 / 980–1868, gap ~40), the photo filling the tile, a glass strip ~103 tall at the bottom
    (title ~22px, "Eau de Parfum · 50ml" ~18px, price accent ~28px bold right), "Trending" badge top
    left. The heart is the parked wishlist (hidden).
  */
  .product-related {
    /* One Figma pixel: the 1920px sizes get smaller on smaller screens */
    --px: min(calc(100vw / 1920), 0.0625rem);
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  /* The hidden attribute (no products yet): the class's display: block would otherwise win */
  product-related[hidden] {
    display: none;
  }

  .product-related__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-related__header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-md) var(--space-lg);
    margin-block-end: max(var(--space-xl), calc(56 * var(--px, 0.0625rem)));
  }

  .product-related__eyebrow {
    margin: 0;
  }

  /* The eyebrow as the title: centred with a line on each side on phones (the shared eyebrow--center);
     from 750px at the left, as the Figma desktop */
  @media (min-width: 750px) {
    .product-related__eyebrow.eyebrow--center {
      justify-content: flex-start;
      text-align: start;
    }

    .product-related__eyebrow.eyebrow--center::after {
      content: none;
    }
  }

  .product-related__heading {
    flex-basis: 100%;
    order: 1;
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-related__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .product-related__all {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    color: color-mix(in srgb, var(--color-text) 62%, var(--color-background));
    font-size: var(--font-size-label);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
    transition: color var(--duration-fast) var(--ease-out);
  }

  .product-related__all:hover {
    color: var(--color-accent);
  }

  .product-related__arrow {
    display: inline-flex;
    transition: translate var(--duration-fast) var(--ease-out);
  }

  .product-related__arrow svg {
    inline-size: 1rem;
    block-size: auto;
  }

  @media (prefers-reduced-motion: no-preference) {
    .product-related__all:hover .product-related__arrow {
      translate: 0.25rem 0;
    }
  }

  /* Desktop: --columns tiles in a row (Figma 2, ~40px apart); each tile is as tall as its shape setting */
  .product-related__grid {
    display: grid;
    grid-template-columns: repeat(var(--columns, 2), minmax(0, 1fr));
    gap: max(var(--space-lg), calc(40 * var(--px, 0.0625rem)));
  }

  /* Tile: the tile has the Card shape. Card: as tall as the tallest card in its row */
  .product-related--tile .product-related__item {
    aspect-ratio: var(--tile-ratio, 890 / 398);
  }

  .product-related--full .product-related__item > .product-card {
    block-size: 100%;
  }

  /*
    Tile on touch screens (no hover): the details panel is always open, so the cart button can be
    reached. The rating and the description stay hidden, so the photo still shows.
  */
  @media (hover: none) {
    .product-related .product-card--tile .product-card__details {
      grid-template-rows: 1fr;
    }

    .product-related .product-card--tile .product-card__details-inner {
      visibility: visible;
      transition-delay: 0s;
    }

    .product-related .product-card--tile :is(.product-card__rating, .product-card__description) {
      display: none;
    }
  }

  .product-related__empty {
    margin: 0;
  }

  /* Tablets: two in a row (Products per row is at least 2) */
  @media (max-width: 989px) {
    .product-related__grid {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    /* A taller tile (Wide and 4:3 become 4:5, from Liquid): the always open panel leaves the photo */
    .product-related--tile .product-related__item {
      aspect-ratio: var(--tile-ratio-small, 4 / 5);
    }
  }

  /*
    Phones (Figma Variant97-3): the eyebrow centred with a line on each side, "View all" under it at the
    right, then the cards one under the other (agreed: one per row; the Figma shows 2)
  */
  @media (max-width: 749px) {
    .product-related__header {
      flex-direction: column;
      align-items: stretch;
      gap: var(--space-md);
      margin-block-end: var(--space-lg);
    }

    .product-related__heading {
      order: 0; /* eyebrow, heading, then "View all" (the desktop row puts the heading last) */
    }

    .product-related__all {
      align-self: flex-end;
    }

    .product-related__grid {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-md);
    }
  }

/* sections/product-reviews.liquid */

  /*
    Figma 1920 ("Component 1642"): eyebrow y 211 centred; heading ~70px centred (y ~297), accent word;
    "WRITE A REVIEW" white glass pill x 1670–1878, y 200–248 (top right, level with the eyebrow).
    Cards 660 x ~145, radius ~24, white, soft shadow; right ones x 858–1518, left ones x 393–1054, ~35px
    apart; text ~18px centred; a 72px round avatar half over the outer edge; a pale accent quote mark
    (~50px) at the inner top corner; stars ~16px gold + score; "~PRINCE, CANADA" caps, wide spacing.
    Moving cards tilt ~1.5deg (right ones clockwise, left ones anticlockwise). Product cut-out x 110–270
    (~160 wide) at three poses; "REVIEWS" ~130px bold, pale grey, x 1290–1850, y 850–950.
  */
  .product-reviews {
    /* One Figma pixel: the 1920px sizes get smaller on smaller screens */
    --px: min(calc(100vw / 1920), 0.0625rem);
    --float-width: calc(var(--float-size, 160) * var(--px));
    position: relative; /* the floating image measures its place from here (offsetTop) */
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
    overflow: hidden; /* the big word and the floating image never widen the page */
  }

  .product-reviews__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-reviews__intro {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-lg);
    text-align: center;
  }

  .product-reviews__intro .eyebrow {
    margin: 0;
  }

  .product-reviews__heading {
    margin: 0;
    font-size: var(--font-size-h1);
    font-weight: 400;
    line-height: 1.1;
  }

  .product-reviews__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /* Top right, level with the eyebrow, from 1200px (smaller screens: under the heading) */
  .product-reviews__write {
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  @media (min-width: 1200px) {
    .product-reviews__write {
      position: absolute;
      inset-block-start: 0;
      inset-inline-end: 0;
    }
  }

  .product-reviews__stage {
    position: relative;
    margin-block-start: max(var(--space-xl), calc(60 * var(--px, 0.0625rem)));
  }

  /* The cards' column: 1190 of 1820 in the Figma (avatars included), centred */
  .product-reviews__viewport {
    position: relative;
    z-index: 1;
    max-inline-size: calc(1190 * var(--px, 0.0625rem));
    margin-inline: auto;
    padding-inline: calc(36 * var(--px, 0.0625rem)); /* room for the avatars over the card edges */
  }

  .product-reviews__track {
    display: grid;
    grid-auto-rows: 1fr; /* every card as tall as the tallest: each step of the carousel is the same */
    gap: max(var(--space-lg), calc(35 * var(--px, 0.0625rem)));
  }

  /* With the script: only --visible cards show. The clip-path cuts above and below only, so the
     avatars over the side edges still show (overflow: hidden would cut those too) */
  product-reviews.is-ready .product-reviews__viewport {
    block-size: var(--viewport-height, auto);
    clip-path: inset(0 -100vw);
  }

  product-reviews.is-ready .product-reviews__track {
    transform: translateY(calc(var(--index, 0) * var(--step, 0px) * -1));
  }

  @media (prefers-reduced-motion: no-preference) {
    product-reviews.is-ready.is-sliding .product-reviews__track {
      transition: transform 0.9s var(--ease-out);
    }
  }

  /* One card */
  .review-card {
    --tilt: 1.5deg;
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: var(--space-md);
    inline-size: 55.5%; /* 660 of 1190 */
    min-inline-size: min(100%, 22rem);
    margin: 0;
    padding-block: max(var(--space-md), calc(22 * var(--px, 0.0625rem)));
    padding-inline: max(var(--space-xl), calc(80 * var(--px, 0.0625rem)));
    border-radius: max(1rem, calc(24 * var(--px, 0.0625rem)));
    background-color: var(--color-card, #ffffff);
    box-shadow: var(--shadow-card-soft);
    transition: opacity 0.6s var(--ease-out);
  }

  .review-card--right {
    justify-self: end;
  }

  .review-card--left {
    --tilt: -1.5deg;
    justify-self: start;
  }

  /* Cards outside the window fade (the clip alone would cut them with a hard edge) */
  .review-card.is-out {
    opacity: 0;
  }

  product-reviews.is-jumping .review-card {
    transition: none;
  }

  /* Each step: the cards tilt while they move and settle flat (the class restarts the animation) */
  @media (prefers-reduced-motion: no-preference) {
    product-reviews.is-tilting .review-card {
      animation: review-card-tilt 0.9s var(--ease-out);
    }
  }

  @keyframes review-card-tilt {
    40% {
      rotate: var(--tilt);
    }
  }

  .review-card__mark {
    position: absolute;
    inset-block-start: max(var(--space-sm), calc(18 * var(--px, 0.0625rem)));
    inset-inline-start: max(var(--space-sm), calc(18 * var(--px, 0.0625rem)));
    color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
  }

  .review-card--left .review-card__mark {
    inset-inline: auto max(var(--space-sm), calc(18 * var(--px, 0.0625rem)));
  }

  .review-card__mark svg {
    display: block;
    inline-size: max(2.25rem, calc(50 * var(--px, 0.0625rem)));
    block-size: auto;
  }

  /* The round avatar, half over the outer edge (right cards: right edge; left cards: left edge) */
  .review-card__avatar {
    position: absolute;
    inset-block-start: 50%;
    inset-inline-end: 0;
    display: grid;
    place-items: center;
    inline-size: max(3.5rem, calc(72 * var(--px, 0.0625rem)));
    aspect-ratio: 1;
    overflow: hidden;
    border: 3px solid var(--color-card, #ffffff);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
    box-shadow: var(--shadow-card-soft);
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: var(--font-size-h3);
    translate: 50% -50%;
  }

  .review-card--left .review-card__avatar {
    inset-inline: 0 auto;
    translate: -50% -50%;
  }

  .review-card__avatar-image {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .review-card__quote {
    margin: 0;
    font-size: var(--font-size-body);
    line-height: 1.45;
    text-align: center;
  }

  /* The quote marks of the page's language (“…” in English, « … » in French): quotes: auto */
  .review-card__quote p {
    margin: 0;
    quotes: auto;
  }

  .review-card__quote p::before {
    content: open-quote;
  }

  .review-card__quote p::after {
    content: close-quote;
  }

  /* Right cards: stars left, name right. Left cards: name left, stars right */
  .review-card__footer {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-xs) var(--space-md);
  }

  .review-card--left .review-card__footer {
    flex-direction: row-reverse;
  }

  .review-card__rating {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    margin: 0;
    font-size: var(--font-size-caption);
  }

  /* Five stars filled up to the rating (4.8 of 5 = 96%), the rest pale */
  .review-card__stars {
    background: linear-gradient(
      90deg,
      var(--color-rating) var(--rating-percent, 100%),
      color-mix(in srgb, var(--color-text) 15%, transparent) var(--rating-percent, 100%)
    );
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 1.15em;
    letter-spacing: 0.1em;
  }

  .review-card__author {
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Decoration: the empty alt text after the slash keeps screen readers from reading "tilde"
     (browsers that do not know it keep the first declaration) */
  .review-card__author::before {
    content: "~";
    content: "~" / "";
  }

  /* Editor only: a review with no text */
  .review-card__note {
    margin: 0;
    font-style: italic;
    text-align: center;
  }

  /* Prev / pause / next under the cards */
  .product-reviews__controls {
    position: relative;
    z-index: 1;
    display: flex;
    justify-content: center;
    gap: var(--space-sm);
    margin-block-start: var(--space-xl);
  }

  product-reviews:not(.is-ready) .product-reviews__controls,
  .product-reviews .product-reviews__control[hidden] {
    display: none;
  }

  .product-reviews .product-reviews__control {
    display: inline-grid;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-border);
    border-radius: 50%;
    background-color: var(--color-card, #ffffff);
    box-shadow: var(--shadow-glass-edge);
    color: var(--color-text);
    cursor: pointer;
    transition: color var(--duration-fast) var(--ease-out), border-color var(--duration-fast) var(--ease-out);
  }

  .product-reviews .product-reviews__control:hover {
    border-color: var(--color-accent);
    color: var(--color-accent);
  }

  .product-reviews__arrow {
    display: inline-flex;
  }

  .product-reviews__arrow svg {
    inline-size: 0.875rem;
    block-size: auto;
  }

  /* icon-arrow.svg points right */
  .product-reviews__arrow--up {
    rotate: -90deg;
  }

  .product-reviews__arrow--down {
    rotate: 90deg;
  }

  .product-reviews__pause-icon {
    inline-size: 0.875rem;
    block-size: 0.875rem;
  }

  .product-reviews__pause-icon--play,
  product-reviews.is-stopped .product-reviews__pause-icon--pause {
    display: none;
  }

  product-reviews.is-stopped .product-reviews__pause-icon--play {
    display: block;
  }

  /*
    The floating product (Figma, image strip): it rises up the left side, one place per card row, tilting
    one way then the other (+12°, −15°, +20°, −3°, −25°) until it meets the bottom of the tabs bar, then
    slips under it and fades. The script sets translate / rotate / opacity from the progress (the scroll,
    or the carousel's steps). Size: the "Floating image size" setting (Figma 160px at 1920). Desktop only.
  */
  .product-reviews__float {
    position: absolute;
    z-index: 0;
    inset-block-end: 0;
    /*
      The gutter left of the cards is (stage width − the cards' 1190) / 2, about 315px at 1920. A wider
      image moves left by the difference (into the page margin) so it never sits under the cards; only a
      very large one is cut at the screen edge
    */
    inset-inline-start: min(0px, calc((100% - 1190 * var(--px, 0.0625rem)) / 2 - var(--float-width)));
    inline-size: var(--float-width);
    rotate: 12deg;
    filter: drop-shadow(0 1.5rem 1.5rem #00000026);
    will-change: translate, rotate, opacity;
  }

  /* Each card step: it eases to its next place (scroll, timer or arrows alike) */
  @media (prefers-reduced-motion: no-preference) {
    product-reviews.is-float-easing .product-reviews__float {
      transition: translate 1.2s var(--ease-out), rotate 1.2s var(--ease-out), opacity 0.9s var(--ease-out);
    }
  }

  .product-reviews__float-image {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  /* Below 1200px the cards use the full width: no room for the image (tried at 1024px: rejected) */
  @media (max-width: 1199px) {
    .product-reviews__float {
      display: none;
    }
  }

  /* The big word: an outline that fills in once the section is on screen */
  .product-reviews__word {
    position: absolute;
    z-index: 0;
    inset-block-end: 0;
    inset-inline-end: 0;
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 9%, var(--color-background));
    font-family: var(--font-body--family);
    font-size: clamp(4rem, 9vw, calc(170 * var(--px, 0.0625rem)));
    font-weight: 700;
    line-height: 0.8;
    text-transform: uppercase;
    pointer-events: none;
    user-select: none;
  }

  @media (prefers-reduced-motion: no-preference) {
    product-reviews:not(.is-seen) .product-reviews__word {
      color: transparent;
      -webkit-text-stroke: 1px color-mix(in srgb, var(--color-text) 15%, var(--color-background));
    }

    .product-reviews__word {
      transition: color 1.4s var(--ease-out);
    }
  }

  .product-reviews__apps {
    margin-block-start: var(--space-2xl);
  }

  .product-reviews__empty {
    margin: 0;
    text-align: center;
  }

  /*
    Tablets (750–1199px): the desktop column (1190 of 1920, scaled down) left ~260px cards at 768px.
    The column takes the full content width and each card 80% of it (at most 40rem), still left / right.
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .product-reviews__viewport {
      max-inline-size: none;
      padding-inline: 2.75rem; /* half an avatar over each side */
    }

    /* 4.5rem each side: the text clears the quote marks in the top corners */
    .review-card {
      inline-size: min(80%, 40rem);
      padding-inline: 4.5rem;
    }
  }

  /* Phones (agreed, no design): cards full width, no stagger, 48px avatars, 14px text */
  @media (max-width: 749px) {
    .review-card {
      gap: var(--space-sm);
      inline-size: 100%;
      min-inline-size: 0;
      padding-block: var(--space-md);
      /* 2.5rem each side: the quote mark (0.5rem from the corner, 1.75rem wide) on one side, half the
         avatar on the other */
      padding-inline: 2.5rem;
    }

    .product-reviews__viewport {
      max-inline-size: none; /* the desktop column (1190 Figma px) would be 242px at 390 */
      padding-inline: 1.5rem; /* half an avatar over each side */
    }

    .review-card__avatar {
      inline-size: 3rem;
      border-width: 2px;
      font-size: var(--font-size-body-lg);
    }

    .review-card__mark svg {
      inline-size: 1.75rem;
    }

    .review-card__quote {
      font-size: 0.875rem;
    }
  }

/* sections/product-tabs.liquid */

  /*
    Figma 1920: x 48–930, 50 tall, white pill with a soft shadow; links caps ~15px wide spacing, 20px
    apart; the active one a red pill (accent fill, white text); ↑ at the end. Stuck at y 112 (under the
    header pill).
  */
  /*
    Stuck 15px under the header pill. --header-space (header.liquid) is the header's height for each
    width and for "Solid header background", so the bar never goes under the header or leaves a gap.
  */
  .shopify-section:has(> product-tabs) {
    position: sticky;
    inset-block-start: calc(var(--header-space, 6.0625rem) + 0.9375rem);
    z-index: 19; /* under the header (20) */
    pointer-events: none; /* the wrapper spans the page width: only the bar takes clicks */
  }

  /* No tab finds its section (the script checks): no bar on the store */
  .shopify-section.is-tabs-empty {
    display: none;
  }

  /*
    Only the script knows which tabs find their section: until it runs, the bar is not shown (no tabs
    that link to nothing). Without JS the bar shows all tabs as plain page links.
  */
  @media (scripting: enabled) {
    product-tabs:not(:defined) .product-tabs__bar {
      visibility: hidden;
    }
  }

  /*
    Only the pill is painted: the colour scheme class would fill the whole width (a white band over the
    pink FAQ). Element + class to outweigh .color-scheme-*
  */
  product-tabs.product-tabs {
    background-color: transparent;
  }

  /* Tabbed layout: the sections that aren't the chosen tab (their Shopify wrapper) */
  .shopify-section.is-tab-hidden {
    display: none;
  }

  /*
    Tabbed + scroll (pinned): the script puts the panel sections in a track, one screen of scroll per
    panel. The stage sticks under the tabs and holds every panel in the same grid cell; only the active
    one shows, the others fade out (and are inert: no clicks, no Tab stops).
  */
  .product-tabs-track__stage {
    position: sticky;
    inset-block-start: 0;
    display: grid;
    block-size: var(--stage-height);
    overflow: hidden;
  }

  /*
    Transition (setting): where the new panel's text and image slide in from (the panel itself only
    fades). --enter = their starting offset.
  */
  /* --enter-back: the opposite side, for a panel that comes back (an earlier tab, or scrolling up) */
  .product-tabs-track {
    position: relative;
    --enter: 0 3rem;
    --enter-back: 0 -3rem;
  }

  .product-tabs-track[data-transition="fade"] {
    --enter: 0 0;
    --enter-back: 0 0;
  }

  .product-tabs-track[data-transition="down"] {
    --enter: 0 -3rem;
    --enter-back: 0 3rem;
  }

  .product-tabs-track[data-transition="left"] {
    --enter: 4rem 0;
    --enter-back: -4rem 0;
  }

  .product-tabs-track[data-transition="right"] {
    --enter: -4rem 0;
    --enter-back: 4rem 0;
  }

  /*
    The panel wrapper has no background of its own: it sits outside the section's colour scheme, so a
    background here would take the page's default scheme (the cream bands). The section inside fills
    the stage instead, with its own scheme colour, and centres its content.
  */
  .product-tabs-track__stage > .shopify-section {
    display: flex;
    flex-direction: column;
    grid-area: 1 / 1;
    align-self: start;
    min-block-size: var(--stage-height);
    transition:
      opacity 0.5s var(--ease-out),
      visibility 0s;
    will-change: transform;
  }

  .product-tabs-track__stage > .shopify-section > * {
    display: flex;
    flex: 1 0 auto;
    flex-direction: column;
    /* Centred under the tabs when it fits; a taller panel starts at the top ("safe": never pushed out) */
    justify-content: safe center;
    /* The stage starts at the top of the screen (so the panel's own colour fills behind the header and
       tabs): the content starts below the tabs */
    padding-block-start: calc(var(--stage-offset) + var(--section-padding-top, 0px));
  }

  .product-tabs-track__stage > .shopify-section.is-tab-faded {
    opacity: 0;
    visibility: hidden;
    transition:
      opacity 0.4s var(--ease-out),
      visibility 0s linear 0.4s;
  }

  /*
    The parts of a panel (heading, text, image, quote, figures… marked data-tab-item in the sections)
    slide in from --enter one after another (--tab-item = their order, set by the script, 90ms apart).
    translate, not transform: the scroll animations (data-animate) use transform, so they don't clash.
  */
  .product-tabs-track__stage [data-tab-item] {
    translate: 0 0;
    transition:
      opacity 0.7s var(--ease-out) calc(var(--tab-item, 0) * 90ms + 0.1s),
      translate 0.7s var(--ease-out) calc(var(--tab-item, 0) * 90ms + 0.1s);
  }

  /* The incoming panel's parts start at --enter, see-through: a class set for one frame by the script */
  .product-tabs-track__stage > .is-tab-entering [data-tab-item] {
    opacity: 0;
    translate: var(--enter);
    transition: none;
  }

  .product-tabs-track__stage > .is-tab-entering.is-tab-back [data-tab-item] {
    translate: var(--enter-back);
  }

  /* The sections the tabs link to stop under the header + tabs, not behind them */
  /* Header + 15px + the bar (~54px) + 16px. Not when the bar is hidden (no tab finds its section) */
  html:has(.shopify-section:not(.is-tabs-empty) > product-tabs) {
    scroll-padding-block-start: calc(var(--header-space, 6.0625rem) + 5.25rem);
  }

  /*
    The stuck bar sits inside that padding area. When the Tab key focuses a tab, the browser took it as
    covered and scrolled the page up to the bar's place in the page (an earlier panel then showed). A
    negative scroll margin of the same size makes the tab count as visible where it is stuck. Only while
    it is stuck (is-tabs-stuck, set on scroll): off the screen, the margin put a focused tab under the
    header
  */
  .is-tabs-stuck .product-tabs__bar :is(a, button) {
    scroll-margin-block-start: calc(-1 * (var(--header-space, 6.0625rem) + 5.25rem));
  }

  @media (prefers-reduced-motion: no-preference) {
    html:has(.shopify-section:not(.is-tabs-empty) > product-tabs) {
      scroll-behavior: smooth;
    }
  }

  .product-tabs {
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .product-tabs__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product-tabs__bar {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    max-inline-size: 100%;
    padding: 0.375rem;
    border: 1px solid var(--color-card-border);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    box-shadow: 0 4px 24px #0000000f;
    pointer-events: auto;
  }

  .product-tabs__row {
    position: relative;
    display: flex;
    min-inline-size: 0;
  }

  /*
    The row scrolls sideways when the tabs don't fit (Figma phone), without a scroll bar. overflow-x also
    clips up and down: 5px of padding (taken back with a negative margin) keep the focus ring inside.
    The mask fades a cut edge (data-more-start / -end); var() in the gradient's direction works for RTL.
  */
  .product-tabs__list {
    position: relative; /* the script measures each tab from the row (offsetLeft) */
    display: flex;
    flex: 1 1 auto;
    gap: var(--space-xs);
    min-inline-size: 0;
    overflow-x: auto;
    margin: -0.3125rem;
    padding: 0.3125rem;
    list-style: none;
    scrollbar-width: none;
    --fade-direction: to right;
    mask-image: linear-gradient(
      var(--fade-direction),
      var(--fade-start, #000) 0,
      #000 2.5rem,
      #000 calc(100% - 2.5rem),
      var(--fade-end, #000) 100%
    );
  }

  .product-tabs__list:dir(rtl) {
    --fade-direction: to left;
  }

  .product-tabs__row[data-more-start] .product-tabs__list {
    --fade-start: #00000000;
  }

  .product-tabs__row[data-more-end] .product-tabs__list {
    --fade-end: #00000000;
  }

  .product-tabs__list::-webkit-scrollbar {
    display: none;
  }

  .product-tabs__list li[hidden] {
    display: none;
  }

  /* Figma phone: a thin pale accent line under the tabs shows how far the row is scrolled */
  .product-tabs__scroll-line {
    display: none;
    position: absolute;
    inset-block-end: -0.3125rem;
    inset-inline-start: var(--line-start, 0);
    inline-size: var(--line-size, 0);
    block-size: 2px;
    border-radius: 1px;
    background-color: color-mix(in srgb, var(--color-accent) 40%, transparent);
    pointer-events: none;
  }

  .product-tabs__row[data-overflow] .product-tabs__scroll-line {
    display: block;
  }

  .product-tabs__note {
    margin: var(--space-xs) 0 0;
    padding: var(--space-xs) var(--space-sm);
    border-radius: var(--radius-sm, 0.5rem);
    background-color: var(--color-background);
    font-size: var(--font-size-small);
    pointer-events: auto;
  }

  .product-tabs__link,
  .product-tabs__top {
    display: inline-flex;
    align-items: center;
    min-block-size: 2.5rem;
    padding-inline: max(var(--space-md), calc(14 * var(--px, 0.0625rem)));
    border-radius: var(--radius-pill);
    color: var(--color-text);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-decoration: none;
    text-transform: uppercase;
    white-space: nowrap;
    transition:
      background-color var(--duration-fast) var(--ease-out),
      color var(--duration-fast) var(--ease-out);
  }

  /* The ring follows the pill shape, 2px out (the row's padding has room for it) */
  .product-tabs__link:focus-visible,
  .product-tabs__top:focus-visible {
    border-radius: var(--radius-pill);
    outline-offset: 2px;
  }

  .product-tabs__link:hover {
    background-color: color-mix(in srgb, var(--color-accent) 8%, transparent);
  }

  .product-tabs__link[aria-current="true"] {
    background-color: var(--color-accent);
    color: var(--color-button-text);
  }

  .product-tabs__top {
    flex: none;
    justify-content: center;
    padding-inline: var(--space-sm);
    font-size: var(--font-size-body);
  }

  .product-tabs__top:hover {
    color: var(--color-accent);
  }

  /* icon-arrow.svg points right: a quarter turn makes it point up */
  .product-tabs__top-icon {
    display: inline-flex;
    rotate: -90deg;
  }

  .product-tabs__top-icon svg {
    inline-size: 1.125rem;
    block-size: auto;
  }

  /* Phones (Figma Variant96-2): the bar is full width and ↑ comes first */
  @media (max-width: 749px) {
    .product-tabs__bar {
      display: flex;
    }

    .product-tabs__top {
      order: -1;
    }
  }

/* sections/product.liquid */

  /*
    Figma 1920 ("Product details 1"): breadcrumb y 150; gallery x 50–816 (766), 3 columns
    220 / 297 / 188 with ~30px gaps, column tops at y 241 / 190 / 298, images radius ~16; the info card
    x 898–1870 (972, gap 82), cream (the card colour on white), 1px pale border, radius ~24, padding ~55.
  */
  .product {
    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .product__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .product__layout {
    display: grid;
    grid-template-columns: minmax(0, 766fr) minmax(0, 972fr);
    align-items: start;
    gap: max(var(--space-xl), calc(82 * var(--px, 0.0625rem)));
    margin-block-start: max(var(--space-lg), calc(30 * var(--px, 0.0625rem)));
  }

  /* The gallery stays in view under the header while the info column scrolls (when it fits the screen) */
  .product__gallery {
    position: sticky;
    inset-block-start: calc(var(--header-space, 6.0625rem) + var(--space-sm));
    display: grid;
    grid-template-columns: 220fr 297fr 188fr;
    align-items: start;
    gap: max(var(--space-sm), calc(30 * var(--px, 0.0625rem)));
  }

  .product__gallery--few {
    grid-template-columns: minmax(0, 1fr);
  }

  .product__column {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-sm), calc(30 * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  /* Offset tops (Figma): the left column 51px lower than the middle one, the right 108px */
  .product__column--1 {
    margin-block-start: calc(51 * var(--px, 0.0625rem));
  }

  .product__column--3 {
    margin-block-start: calc(108 * var(--px, 0.0625rem));
  }

  .product__gallery--few .product__column--1 {
    margin-block-start: 0;
  }

  .product__media {
    position: relative;
    overflow: hidden;
    aspect-ratio: var(--media-ratio, 1);
    border-radius: max(0.75rem, calc(16 * var(--px, 0.0625rem)));
  }

  /*
    Videos, YouTube / Vimeo and 3D models have controls: in a narrow column a 16:9 video was ~66px tall
    and the controls and buttons covered it. They are at least 10rem tall (a video fills the taller box)
  */
  .product__media:is(.product__media--video, .product__media--external_video, .product__media--model) {
    min-block-size: 10rem;
  }

  /* Shopify's 3D play button is 62px: too big for a gallery tile (the image viewer keeps the full size) */
  .product__media .shopify-model-viewer-ui__button--poster {
    scale: 0.65;
  }

  /*
    The product-media snippet has its own (larger) radius and tint: it takes this frame's radius, so the
    corners match and nothing shows behind the image (its tint still shows while the image loads)
  */
  .product__media > * {
    inline-size: 100%;
    block-size: 100%;
  }

  /* Two classes: the snippet's own .product-media radius has the same weight as one class */
  .product__media .product-media {
    border-radius: inherit;
  }

  /* The variant's image, just moved to the top: a short highlight */
  @media (prefers-reduced-motion: no-preference) {
    .product__media.is-variant {
      animation: product-media-in var(--duration-normal) var(--ease-out);
    }
  }

  @keyframes product-media-in {
    from {
      opacity: 0.4;
      transform: scale(0.98);
    }
  }

  /* The viewer opener: invisible over the whole image (a zoom-in cursor), or a small glass corner button */
  .product__open {
    position: absolute;
    z-index: 1;
    inset: 0;
    min-block-size: 0;
    padding: 0;
    border: 0;
    border-radius: inherit;
    background: none;
    box-shadow: none;
    cursor: zoom-in;
  }

  .product__open:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: -4px;
  }

  .product__open--corner {
    inset: var(--space-sm) var(--space-sm) auto auto;
    display: grid;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-background) 70%, transparent);
    color: var(--color-text);
    font-size: 1.25rem;
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
  }

  .product__open--corner:hover {
    background-color: var(--color-background);
  }

  /* Without JavaScript the viewer can't open: no buttons that do nothing */
  @media (scripting: none) {
    .product__open {
      display: none;
    }
  }

  .product__placeholder {
    inline-size: 100%;
    block-size: 100%;
  }

  /* The info column: the cards (product-panel blocks) one under the other, Figma gap ~15 */
  .product__info {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-sm), calc(15 * var(--px, 0.0625rem)));
    min-inline-size: 0;
  }

  /* Tablets and phones (Variant96…): one column, the gallery not sticky, the masonry kept */
  @media (max-width: 989px) {
    .product__layout {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-lg);
    }

    .product__gallery {
      position: static;
      gap: var(--space-xs);
    }

    .product__column {
      gap: var(--space-xs);
    }

    .product__column--1 {
      margin-block-start: 1.25rem;
    }

    .product__column--3 {
      margin-block-start: 2.5rem;
    }
  }


/* sections/returns-hero.liquid */

  /*
    Figma 1920 (1:18125): breadcrumb y 134; badge circle 223 x 223 at x 276 y 231 (fill accent ~7%,
    1px pale ring, soft shadow), "60" heading font ~115px accent, "DAYS" label accent; text column
    from x 593 (eyebrow y 212, heading ~64px y 278, 629 wide; intro ~20 / 35 under it); the badge
    column is 135–593 (458 wide), the badge centred in it at the right.
  */
  /* --px = one Figma pixel (from the width only and never more than 1px with Scale with the screen off) */
  .returns-hero {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .returns-hero.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .returns-hero__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .returns-hero__grid {
    display: grid;
    grid-template-columns: max(12rem, calc(458 * var(--px))) minmax(0, 1fr);
    align-items: start;
    margin-block-start: max(var(--space-xl), calc(45 * var(--px)));
  }

  .returns-hero__grid--no-badge {
    grid-template-columns: minmax(0, 1fr);
  }

  .returns-hero__badge {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    justify-self: center;
    inline-size: max(9rem, calc(223 * var(--px)));
    aspect-ratio: 1;
    box-sizing: border-box;
    margin-block-start: max(0rem, calc(19 * var(--px)));
    border: 1px solid color-mix(in srgb, var(--color-accent) 15%, transparent);
    border-radius: 50%;
    background-color: color-mix(in srgb, var(--color-accent) 7%, var(--color-background));
    box-shadow: 0 12px 34px 0 color-mix(in srgb, var(--color-accent) 12%, transparent);
    color: var(--color-accent);
  }

  .returns-hero__badge-number {
    font-family: var(--font-heading--family);
    font-size: max(4rem, calc(115 * var(--px)));
    line-height: 0.95;
  }

  .returns-hero__badge-label {
    margin-block-start: var(--space-sm);
    font-size: var(--font-size-small);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .returns-hero__heading {
    margin: max(var(--space-lg), calc(42 * var(--px))) 0 0;
    /* --text-boost = the Text size setting (only with Scale with the screen) */
    font-size: calc(max(2.25rem, calc(64 * var(--px))) * var(--text-boost, 1));
    font-weight: 400;
    line-height: 1.1;
  }

  .returns-hero__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .returns-hero__text {
    max-inline-size: max(20rem, calc(640 * var(--px)));
    margin-block-start: max(var(--space-lg), calc(40 * var(--px)));
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .returns-hero__text > * {
    margin: 0;
  }

  /* Phones and small tablets: the badge above the text, a little smaller */
  @media (max-width: 989px) {
    .returns-hero__grid {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-xl);
    }

    .returns-hero__badge {
      justify-self: start;
      inline-size: 8.5rem;
      margin: 0;
    }

    .returns-hero__badge-number {
      font-size: 3.5rem;
    }

    .returns-hero__badge-label {
      margin-block-start: var(--space-xs);
    }
  }

  @media (max-width: 749px) {
    .returns-hero__text {
      font-size: var(--font-size-body-sm);
      line-height: 1.7;
    }
  }

/* sections/returns-lists.liquid */

  /*
    Figma 1920: two cards 795 x 345 at x 135 / 990 (gap 60) from y 1018; radius ~16, 1px pale border
    (the second dashed), white; icon 40 + title heading font ~30px; items ~20 / 35, one every ~45px,
    a 24px tick / cross.
  */
  .returns-lists {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .returns-lists.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .returns-lists__inner {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: max(var(--space-lg), calc(60 * var(--px)));
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .returns-lists__empty {
    display: block;
    margin-block: 0;
  }

  .returns-lists__card {
    box-sizing: border-box;
    padding: max(var(--space-lg), calc(44 * var(--px))) max(var(--space-lg), calc(33 * var(--px)));
    border: 1px solid var(--color-card-border);
    border-radius: max(0.75rem, calc(16 * var(--px)));
    background-color: color-mix(in srgb, var(--color-accent) 1%, var(--color-background));
  }

  .returns-lists__card--no {
    border-style: dashed;
    border-color: color-mix(in srgb, var(--color-accent) 22%, transparent);
  }

  .returns-lists__card:nth-child(2) {
    --animate-delay: 100ms;
  }

  .returns-lists__title {
    display: flex;
    align-items: center;
    gap: max(var(--space-sm), calc(18 * var(--px)));
    margin: 0;
    font-size: max(1.375rem, calc(30 * var(--px)));
    font-weight: 400;
    line-height: 1.25;
  }

  /* The title's circle: solid accent with a white ✓, or pale accent with an accent "!" */
  .returns-lists__icon {
    display: grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: max(2.25rem, calc(40 * var(--px)));
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-accent);
    color: var(--color-background);
  }

  .returns-lists__card--no .returns-lists__icon {
    background-color: color-mix(in srgb, var(--color-accent) 12%, var(--color-background));
    color: var(--color-accent);
  }

  .returns-lists__icon svg {
    inline-size: 45%;
    block-size: auto;
  }

  .returns-lists__items {
    display: flex;
    flex-direction: column;
    gap: max(var(--space-xs), calc(10 * var(--px)));
    margin: max(var(--space-lg), calc(34 * var(--px))) 0 0;
    padding: 0;
    list-style: none;
  }

  .returns-lists__item {
    display: flex;
    align-items: baseline;
    gap: max(var(--space-md), calc(26 * var(--px)));
    font-size: var(--font-size-body);
    line-height: 1.75;
  }

  .returns-lists__mark {
    display: inline-grid;
    flex-shrink: 0;
    place-items: center;
    inline-size: 1.25rem;
    color: var(--color-accent);
    transform: translateY(0.15em);
  }

  .returns-lists__mark svg {
    inline-size: 0.875rem;
    block-size: auto;
  }

  /* Phones and small tablets: the cards stack, full width */
  @media (max-width: 989px) {
    .returns-lists__inner {
      grid-template-columns: minmax(0, 1fr);
      gap: var(--space-md);
    }

    .returns-lists__card:nth-child(2) {
      --animate-delay: 0ms;
    }
  }

  @media (max-width: 749px) {
    .returns-lists__card {
      padding: var(--space-lg) var(--space-md);
    }

    .returns-lists__title {
      font-size: 1.25rem;
    }

    .returns-lists__item {
      gap: var(--space-sm);
      font-size: var(--font-size-body-sm);
      line-height: 1.6;
    }
  }

/* sections/returns-steps.liquid */

  /* Figma 1920: 4 steps from x 135, one every 410px (text 318 wide), from y 617 */
  .returns-steps {
    --px: min(calc(100vw / 1920), 0.0625rem);

    display: block;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    background-color: var(--color-background);
  }

  .returns-steps.section--screen-scale {
    --px: min(calc(100vw / 1920), calc(100svh / 1031));
  }

  .returns-steps__inner {
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .returns-steps__heading {
    margin: 0 0 var(--space-xl);
    font-size: var(--font-size-h3);
    font-weight: 400;
  }

  .returns-steps__list {
    --step-marker: max(3.25rem, calc(73 * var(--px)));
    --steps-gap: max(var(--space-lg), calc(92 * var(--px)));

    counter-reset: return-step;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: var(--space-2xl) var(--steps-gap);
  }

  /*
    The line from each circle to the next one (Figma: 8px after the circle, 8px before the next),
    measured from the step, so it fits at any width. Drawn here, where the list knows the last step.
  */
  .returns-steps__list > .return-step:not(:last-child)::before {
    content: "";
    position: absolute;
    inset-block-start: calc(var(--step-marker) / 2);
    inset-inline: calc(var(--step-marker) + 8px) calc(var(--steps-gap) * -1 + 8px);
    block-size: 1px;
    background-color: color-mix(in srgb, var(--color-accent) 18%, transparent);
  }

  /* 4 per row: no line at the end of a row (with 5 or 6 steps, the 4th starts no line into nothing) */
  .returns-steps__list > .return-step:nth-child(4n)::before {
    content: none;
  }

  /* The steps in a row fade up one after another (also in the second row) */
  .returns-steps__list > .return-step:nth-child(4n + 2) {
    --animate-delay: 100ms;
  }

  .returns-steps__list > .return-step:nth-child(4n + 3) {
    --animate-delay: 200ms;
  }

  .returns-steps__list > .return-step:nth-child(4n) {
    --animate-delay: 300ms;
  }

  .returns-steps__empty {
    margin: 0;
  }

  /* Tablets: 2 x 2, no lines between the rows */
  @media (max-width: 1199px) {
    .returns-steps__list {
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }

    .returns-steps__list > .return-step:nth-child(even)::before {
      content: none;
    }

    .returns-steps__list > .return-step:nth-child(n) {
      --animate-delay: 0ms;
    }

    .returns-steps__list > .return-step:nth-child(even) {
      --animate-delay: 100ms;
    }
  }

  /* Phones: a vertical timeline; the line runs from under each circle down to the next one */
  @media (max-width: 749px) {
    .returns-steps__list {
      grid-template-columns: minmax(0, 1fr);
      gap: 0;
    }

    .returns-steps__list > .return-step:not(:last-child)::before {
      content: none;
    }

    .returns-steps__list > .return-step:not(:last-child)::after {
      content: "";
      position: absolute;
      inset-block: calc(3rem + var(--space-xs)) var(--space-xs);
      inset-inline-start: 1.5rem;
      inline-size: 1px;
      background-color: color-mix(in srgb, var(--color-accent) 25%, transparent);
    }

    .returns-steps__list > .return-step:nth-child(n) {
      --animate-delay: 0ms;
    }
  }

/* sections/scrolling-showcase.liquid */

  .scrolling-showcase {
    /* Separate colours for each highlighted part (the M4.4 scroll scene changes them one by one) */
    --showcase-eyebrow-color: var(--showcase-highlight);
    --showcase-em-color: var(--showcase-highlight);
    --showcase-arrow-color: var(--showcase-highlight);

    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .scrolling-showcase__inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: clamp(2.5rem, 1.5rem + 4vw, 7.5rem); /* 40px on phones -> 120px at 1920px (Figma) */
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    text-align: center;
  }

  .scrolling-showcase__eyebrow {
    margin: 0;
    color: var(--showcase-eyebrow-color);
  }

  /*
    The sentence: 56px on phones -> 108px at 1920px (the display-xl token). The tall line height leaves
    room for the photo stack, which is taller than the letters. Everything inside is sized in em, so the
    photos and the arrow grow and shrink with the text.
  */
  /*
    The font is set here, not left to the h2 rules in critical.css: the band's white copy is a <div>
    (one heading per page area), so it would otherwise fall back to the body font and break its lines
    differently from the real heading.
  */
  .scrolling-showcase__title {
    max-inline-size: 15em;
    margin: 0;
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: var(--font-size-display-xl);
    line-height: 1.6;
    letter-spacing: 0;
    text-wrap: balance;
  }

  .scrolling-showcase__title em {
    font-style: normal;
    color: var(--showcase-em-color);
  }

  /* [break]: only on wide screens, where the Figma's three lines fit; smaller screens wrap freely */
  .scrolling-showcase__break {
    display: none;
  }

  @media (min-width: 990px) {
    .scrolling-showcase__break {
      display: inline;
    }
  }

  /* [images]: up to three rounded photos overlapping like a fanned hand of cards */
  .scrolling-showcase__images {
    display: inline-flex;
    margin-inline: 0.1em;
    vertical-align: middle;
  }

  .scrolling-showcase__image {
    display: block;
    flex: none;
    inline-size: 0.85em;
    block-size: 1.27em;
    overflow: hidden;
    border: 0.03em solid #ffffff;
    border-radius: 0.16em;
    background-color: var(--color-tint);
    box-shadow: 0 0.04em 0.12em #00000026;
  }

  .scrolling-showcase__image + .scrolling-showcase__image {
    margin-inline-start: -0.13em;
  }

  /* Linked photo: the global focus ring, kept on the photo's own rounded corners */
  .scrolling-showcase__image--link:focus-visible {
    border-radius: 0.16em;
  }

  /*
    The real heading (with the real links) sits under the gold band, so its focus ring hides there.
    The white copy on top has the same photos in the same spots: draw the ring on the copy's matching
    photo too. (The copy is clipped to the band, so above the band only the real ring shows.)
  */
  .scrolling-showcase:has(.scrolling-showcase__image--link:nth-child(1):focus-visible)
    .scrolling-showcase__band-text
    .scrolling-showcase__image--link:nth-child(1),
  .scrolling-showcase:has(.scrolling-showcase__image--link:nth-child(2):focus-visible)
    .scrolling-showcase__band-text
    .scrolling-showcase__image--link:nth-child(2),
  .scrolling-showcase:has(.scrolling-showcase__image--link:nth-child(3):focus-visible)
    .scrolling-showcase__band-text
    .scrolling-showcase__image--link:nth-child(3) {
    outline: 2px solid var(--scene-text);
    outline-offset: 3px;
  }

  /* The small photos in the sentence and the big scroll photos: the image fills its frame */
  :is(.scrolling-showcase__image, .scrolling-showcase__photo) > :is(img, svg) {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /* [arrow]: the Figma's double arrow (→>), drawn with currentColor so one variable colours it */
  .scrolling-showcase__arrow {
    display: inline-block;
    margin-inline: 0.12em;
    color: var(--showcase-arrow-color);
    vertical-align: middle;
  }

  .scrolling-showcase__arrow svg {
    display: block;
    inline-size: 1.5em;
    block-size: auto;
  }

  scrolling-showcase {
    display: block;
  }

  /*
    Intro (set by the script, see watchIntro): hidden until the sentence is in view, then each small photo
    slides in from the left, 0.15s after the one before, and the arrow follows last.
  */
  scrolling-showcase[data-intro]:not([data-intro-played]) :is(.scrolling-showcase__image, .scrolling-showcase__arrow) {
    opacity: 0;
  }

  scrolling-showcase[data-intro-played] :is(.scrolling-showcase__image, .scrolling-showcase__arrow) {
    animation: showcase-slide-in 0.6s var(--ease-out) both;
  }

  scrolling-showcase[data-intro-played] .scrolling-showcase__image:nth-child(2) {
    animation-delay: 0.15s;
  }

  scrolling-showcase[data-intro-played] .scrolling-showcase__image:nth-child(3) {
    animation-delay: 0.3s;
  }

  scrolling-showcase[data-intro-played] .scrolling-showcase__arrow {
    animation-delay: 0.5s;
  }

  @keyframes showcase-slide-in {
    from {
      opacity: 0;
      transform: translateX(-0.6em);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    scrolling-showcase :is(.scrolling-showcase__image, .scrolling-showcase__arrow) {
      opacity: 1 !important;
      animation: none !important;
    }
  }

  /* Static (scene off, or not switched on by the script): the band is never shown */
  .scrolling-showcase__band {
    display: none;
  }

  /*
    Scroll scene. Everything below applies only once the script has added data-scene-active.

    The track is several screens tall (Scene length, e.g. 300 = 3 screen heights); the stage inside it
    is sticky, so it stays on screen while the visitor scrolls through the track. The script turns the
    scroll position inside the track into --p: 0 when the stage pins, 1 when it lets go.
  */
  .scrolling-showcase[data-scene-active] {
    padding-block: 0;
  }

  .scrolling-showcase[data-scene-active] .scrolling-showcase__track {
    block-size: calc(var(--scene-length) * 1svh);
  }

  .scrolling-showcase[data-scene-active] .scrolling-showcase__stage {
    /*
      Timeline, from --p (0 = the stage pins, 1 = it lets go):
      - 0    -> 0.20  rise: the band comes up from the bottom and fills the screen
      - 0.05 -> 0.40  the photos come up into place, one shortly after the other
      - 0.40 -> 0.45  hold: all three sit in their spots
      - 0.45 -> 0.89  the photos leave upwards one by one (each starts when the one before is halfway)
      - 0.89 -> 1     only the white text on gold; then the pin lets go and the gold screen scrolls up
                      like any section, straight into the next one
      clamp() keeps each value between 0 and 1 before and after its part of the scroll.
    */
    --rise: clamp(0, calc(var(--p) / 0.2), 1);

    position: sticky;
    inset-block-start: 0;
    display: grid;
    block-size: 100svh;
    /*
      clip, not hidden: hidden is still a scroll container. If something inside got focus (a link typed
      in the sentence) or a script called scrollIntoView, the browser could scroll the stage and push
      the layers out of line. clip never scrolls. (hidden first: the fallback for browsers without clip)
    */
    overflow: hidden;
    overflow: clip;
  }

  /*
    All layers share one grid cell (so the two texts line up exactly); z-index sets the order:
    real text 0, gold band 1, photos 2, white text 3.
  */
  .scrolling-showcase[data-scene-active] .scrolling-showcase__stage > * {
    grid-area: 1 / 1;
  }

  /* Top/Bottom padding move the text down/up inside the pinned screen (e.g. clear of the header) */
  .scrolling-showcase[data-scene-active] .scrolling-showcase__layer {
    align-self: center;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .scrolling-showcase[data-scene-active] .scrolling-showcase__band {
    z-index: 1;
    display: block;
    background-color: var(--showcase-highlight);
    pointer-events: none; /* links in the real sentence underneath stay clickable */
  }

  /* Top edge = the rising band. Only that part of the band and of the white text shows. */
  .scrolling-showcase[data-scene-active] :is(.scrolling-showcase__band, .scrolling-showcase__band-text) {
    clip-path: inset(calc((1 - var(--rise)) * 100%) 0 0 0);
  }

  /*
    The white copy fills the whole stage, exactly like the band: clip-path % is measured against each
    element's own box, so a copy only as tall as the text was cut lower than the band, leaving a strip
    where the gold had covered the dark text and photos but the white copy wasn't drawn yet.
    justify-content: center + the same padding puts the text exactly where the real (centred) text is.
  */
  .scrolling-showcase[data-scene-active] .scrolling-showcase__band-text {
    z-index: 3;
    align-self: stretch;
    justify-content: center;
    color: var(--scene-text);

    /* The M4.3 colour variables, recoloured for the band: white text and "!!!", dark arrow */
    --showcase-eyebrow-color: var(--scene-text);
    --showcase-em-color: var(--scene-text);
    --showcase-arrow-color: var(--scene-arrow);
  }

  /* Photos: placed by their centre (x / y = % of the screen), between the band and the white text */
  /* Hidden until the scroll effect runs */
  .scrolling-showcase__photos {
    display: none;
  }

  .scrolling-showcase[data-scene-active] .scrolling-showcase__photos {
    position: relative;
    z-index: 2;
    display: block;
    pointer-events: none; /* the layer covers the whole stage: links in the sentence underneath stay clickable */
  }

  .scrolling-showcase__photo {
    /*
      Each photo has its own two moments (start times set per photo below):
      --in:  0 -> 1 over 0.25 of the scroll from --in-start (coming up into place)
      --out: 0 -> 1 over 0.22 of the scroll from --out-start (leaving upwards)
      Before --out-start a photo stays perfectly still, so while one leaves the others wait.
    */
    --in: clamp(0, calc((var(--p) - var(--in-start)) / 0.25), 1);
    --out: clamp(0, calc((var(--p) - var(--out-start)) / 0.22), 1);

    position: absolute;
    inset-inline-start: var(--x);
    inset-block-start: var(--y);
    inline-size: var(--w);
    aspect-ratio: 3 / 2;
    overflow: hidden;
    border-radius: clamp(0.75rem, 1.25vw, 1.5rem);
    background-color: var(--color-tint);
    box-shadow: 0 1.25rem 2.5rem #00000033;
    /*
      Coming in: starts one screen height lower and extra tilted, slows down as it lands
      ((1 - in) squared = ease-out). Leaving: speeds up as it goes (out squared = ease-in), moving
      1.2 screen heights up so it is fully off the stage, and turns a little the other way.
      Between the two (in = 1, out = 0) both terms are 0: the photo sits exactly at its spot.
    */
    transform: translate(-50%, -50%)
      translateY(calc((1 - var(--in)) * (1 - var(--in)) * 100svh - var(--out) * var(--out) * 120svh))
      rotate(calc((var(--tilt) + (1 - var(--in)) * var(--spin) - var(--out) * var(--spin)) * 1deg));
    will-change: transform;
  }

  /*
    Timing per photo. Leaving: photo 1 at 0.45, photo 2 at 0.56 (photo 1 halfway out),
    photo 3 at 0.67 (photo 2 halfway out); each takes 0.22, so the last one is gone at 0.89.
  */
  .scrolling-showcase__photo--1 { --spin: 12; --in-start: 0.05; --out-start: 0.45; }
  .scrolling-showcase__photo--2 { --spin: -10; --in-start: 0.1; --out-start: 0.56; }
  .scrolling-showcase__photo--3 { --spin: 14; --in-start: 0.15; --out-start: 0.67; }

  /*
    Phones: one shared width for all three cards (Card width on phones, default 50%). The old rule
    (desktop width x 1.6) gave 43% = 138px at 320px, too small next to the 56px sentence.
  */
  @media (max-width: 749px) {
    .scrolling-showcase__photo {
      inline-size: var(--phone-card-width, 50%);
    }
  }

  /*
    Tablets and small laptops: the large-screen widths (about 27%, set for 1920px) gave 276px cards at
    1024px, small on a screen that is as tall as it is wide. One shared width (Card width on tablets,
    default 40% = 410px at 1024px).
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .scrolling-showcase__photo {
      inline-size: var(--tablet-card-width, 40%);
    }
  }

/* sections/search.liquid */

  .search-section {
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
  }

  .search-section__inner {
    display: flex;
    flex-direction: column;
    gap: var(--space-xl);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
    scroll-margin-block-start: 7.5rem; /* after a page change it scrolls here: leave room for the sticky header pill */
  }

  /* Heading + search box, centred like the collection banner's sentence */
  .search-hero {
    display: grid;
    justify-items: center;
    gap: var(--space-md);
    padding-block: var(--space-xl) var(--space-lg);
    text-align: center;
  }

  /* The section eyebrow pattern: a short red rule, then the uppercase label */
  .search-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-sm);
    margin: 0;
    color: var(--color-accent);
    font-size: var(--font-size-label);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  .search-hero__eyebrow::before {
    content: '';
    inline-size: 4.125rem; /* 66px */
    block-size: 2px;
    background-color: currentColor;
  }

  .search-hero__title {
    max-inline-size: 48rem;
    margin: 0;
    font-size: var(--font-size-h1);
    line-height: var(--line-height-heading);
  }

  /* The searched words in red italic, like the highlighted words in the banners */
  .search-hero__title em {
    color: var(--color-accent);
  }

  .search-hero__form {
    display: flex;
    align-items: center;
    gap: var(--space-xs);
    inline-size: min(40rem, 100%);
    margin-block-start: var(--space-sm);
    padding: var(--space-2xs) var(--space-2xs) var(--space-2xs) var(--space-lg);
    border: 1px solid color-mix(in srgb, var(--color-accent) 25%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong);
    box-shadow: var(--shadow-header);
    -webkit-backdrop-filter: blur(var(--glass-frost));
    backdrop-filter: blur(var(--glass-frost));
  }

  .search-hero__form:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
  }

  /*
    .search-hero in front: critical.css styles input[type="search"] and button[type="submit"] (a class +
    an element, which beats a class alone), so these rules need two classes to win.
    margin 0: critical.css spaces a control that follows a label (the M7.7 magnifier lesson).
  */
  .search-hero .search-hero__input {
    flex: 1;
    min-inline-size: 0;
    min-block-size: 3rem;
    margin: 0;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--color-text);
    font: inherit;
    font-size: var(--font-size-body);
  }

  .search-hero .search-hero__input:focus-visible {
    outline: none;
  }

  /* The browser's own × in search boxes: hidden (it doesn't match the design; clearing the words is easy) */
  .search-hero__input::-webkit-search-cancel-button,
  .search-hero__input::-webkit-search-decoration {
    -webkit-appearance: none;
    appearance: none;
  }

  /* margin 0: critical.css adds space above a control that follows another (here: the input) */
  .search-hero .search-hero__submit {
    display: inline-grid;
    flex: none;
    place-items: center;
    inline-size: 3rem;
    min-block-size: 0;
    block-size: 3rem;
    margin: 0;
    padding: 0;
    border: 0;
    border-radius: var(--radius-pill);
    background-color: var(--color-accent);
    box-shadow: none;
    color: var(--color-background);
    cursor: pointer;
  }

  .search-hero__submit svg {
    inline-size: 1.25rem;
    block-size: 1.25rem;
  }

  /* SORT: here a hidden q input comes before the label, which gave it critical.css's spacing */
  .search-section .collection-sort__label {
    margin: 0;
  }

  /*
    Product columns (the grid and card styles come from sections/collection.liquid): phones 2 cards or
    1 tile, tablets 3, "Columns on desktop" from 1200px. Three classes, so these beat the collection
    page's own column rules (its tablets have 2, its laptops 3).
  */
  @media (min-width: 750px) and (max-width: 1199px) {
    .search-section .collection-grid.collection-grid--grid {
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
  }

  @media (min-width: 1200px) {
    .search-section .collection-grid.collection-grid--grid {
      grid-template-columns: repeat(var(--grid-columns, 4), minmax(0, 1fr));
    }
  }

  /* Results groups: Products, Collections, Articles, Pages, each with a section-size heading */
  .search-group {
    display: grid;
    gap: var(--space-lg);
  }

  .search-group + .search-group {
    margin-block-start: var(--space-2xl);
  }

  .search-group__title {
    margin: 0;
    font-size: var(--font-size-h2);
    line-height: var(--line-height-heading);
  }

  .search-group__title em {
    color: var(--color-accent);
  }

  .search-group--centred {
    justify-items: center;
    text-align: center;
  }

  /* Collection, article and page cards: 3 per row on desktop, the whole card is one link */
  .result-cards {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(min(20rem, 100%), 1fr));
    gap: var(--space-xl);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .result-card__link {
    display: flex;
    flex-direction: column;
    block-size: 100%;
    overflow: hidden;
    border-radius: var(--radius-md);
    background-color: color-mix(in srgb, var(--color-text) 3%, var(--color-background));
    box-shadow: var(--shadow-card);
    color: var(--color-text);
    text-decoration: none;
    transition:
      box-shadow var(--duration-fast) var(--ease-out),
      translate var(--duration-fast) var(--ease-out);
  }

  .result-card__link:hover {
    box-shadow: var(--shadow-card-rose);
    translate: 0 -2px;
  }

  @media (prefers-reduced-motion: reduce) {
    .result-card__link:hover {
      translate: none;
    }
  }

  .result-card__media {
    aspect-ratio: 16 / 10;
    overflow: hidden;
    background-color: color-mix(in srgb, var(--color-accent) 6%, var(--color-background));
  }

  .result-card__media img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .result-card__body {
    display: grid;
    flex: 1;
    align-content: start;
    gap: var(--space-xs);
    padding: var(--space-lg);
  }

  .result-card__meta,
  .result-card__title,
  .result-card__excerpt {
    margin: 0;
  }

  .result-card__meta {
    color: var(--color-accent);
    font-size: var(--font-size-small);
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-nav);
    text-transform: uppercase;
  }

  .result-card__title {
    font-size: var(--font-size-h3);
    line-height: var(--line-height-heading);
  }

  .result-card__excerpt {
    color: color-mix(in srgb, var(--color-text) 80%, var(--color-background));
    font-size: var(--font-size-caption);
  }

  .result-card__more {
    display: inline-flex;
    align-items: center;
    gap: var(--space-xs);
    margin-block-start: var(--space-xs);
    color: var(--color-accent);
    font-size: var(--font-size-caption);
    font-weight: var(--font-weight-medium);
  }

  .result-card__more svg {
    inline-size: 1rem;
    block-size: 1rem;
  }

/* sections/slideshow.liquid */

  slideshow-section {
    display: block;
  }

  /* Theme editor only: no Slide block */
  .slideshow-empty {
    padding: var(--space-2xl) var(--page-margin);
    text-align: center;
  }

  /*
    No overflow rule on the section: an ancestor with overflow (hidden / clip) stops the sticky stage in
    Page scroll mode. The stage itself clips what goes past the sides (decorations, the card).
    --slideshow-screen = the screen height this section may fill (less the header / announcement bar, below).
  */
  .slideshow {
    --slideshow-offset: 0px;
    --slideshow-screen: calc(100svh - var(--slideshow-offset) - var(--slideshow-bar, 0px));
    --slideshow-outline: var(--color-background);
    position: relative;
    padding-block: var(--slideshow-pad-top, 0px) var(--slideshow-pad-bottom, 0px);
    background-color: var(--color-background);
    color: var(--color-text);
  }

  /*
    The first section slides up under a floating header, and the header CSS adds a top border as tall as the
    header (sections/header.liquid): the stage is then one screen less the header. A solid header covers the
    top of the page: the same height comes off. A top announcement bar above the first section pushes it down:
    its height comes off too (as on the hero).
  */
  body:has(sticky-header):not(:has(.header--transparent, .header--solid)) #MainContent > .shopify-section:first-child .slideshow,
  body:has(.header--solid) .slideshow {
    --slideshow-offset: var(--header-space);
  }

  body:has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .slideshow {
    --slideshow-bar: var(--announcement-size, 2.25rem);
  }

  /*
    Two values carried to the script (these properties have no other use here, the stage does not scroll):
    scroll-margin-block-start = the screen height this section may fill; scroll-padding-block-start = the room a
    floating header takes at the top (0 when --slideshow-offset already takes the header off).
  */
  .slideshow__stage {
    position: relative;
    overflow-x: clip;
    scroll-margin-block-start: var(--slideshow-screen);
    scroll-padding-block-start: max(0px, calc(var(--header-space, 0px) - var(--slideshow-offset)));
  }

  .slideshow__frame {
    position: relative;
  }

  /* All slides in one grid cell: the shown one on top, the others invisible (their images still load) */
  .slideshow__slides {
    display: grid;
  }

  .slideshow-slide {
    position: relative;
    grid-area: 1 / 1;
    min-inline-size: 0;
  }

  .slideshow-slide.is-active {
    z-index: 1;
  }

  .slideshow-slide:not(.is-active):not(.is-leaving) {
    visibility: hidden;
    opacity: 0;
    pointer-events: none;
  }

  /*
    Images load only for slides that are ready (slide 1, and the slides next to the shown slide: the script
    adds .is-ready). The hidden slides are on the screen, so "lazy" alone does not stop their images: a hidden
    <img> does. The boxes keep their size (aspect-ratio), so the slide height does not change.
  */
  slideshow-section:defined .slideshow-slide:not(.is-ready) img {
    display: none;
  }

  /* No JavaScript, or before the script runs: slide 1 only, no buttons */
  slideshow-section:not(:defined) .slideshow-slide:not(.is-active) {
    display: none;
  }

  slideshow-section:not(:defined) :is(.slideshow__controls, .slideshow__dots) {
    visibility: hidden;
  }

  /* Two parts: the .slideshow__controls / __dots rules later in this file would win over one class */
  @media (scripting: none) {
    .slideshow :is(.slideshow__controls, .slideshow__dots) {
      display: none;
    }
  }

  /* ---------- Phone layout (phones, tablets, and 1024-1199px screens taller than wide): the Figma 375px frame ---------- */

  /*
    The slide is the size container: --mpx = one pixel of the 375px Figma frame at this slide's width.
    Tablets (750px and up): the slide width = "Slide width on tablets" (a %) of the screen, counted on at most
    56rem (896px), so the setting changes the width on every tablet and the slide never gets huge.
    --cpx: text sizes grow with the slide too, but at most to 1.2x (big text in a narrow column looks heavy).
  */
  .slideshow {
    --slideshow-slide-width: min(100%, calc(min(100vw, 56rem) * var(--slideshow-tablet-width, 75) / 100));
  }

  @media (max-width: 749px) {
    .slideshow {
      --slideshow-slide-width: 100%;
    }
  }

  .slideshow-slide {
    --mpx: calc(100cqi / 375);
    --cpx: min(100cqi / 375, 0.075rem);
    container-type: inline-size;
    display: grid;
    align-content: start;
    inline-size: var(--slideshow-slide-width);
    margin-inline: auto;
  }

  .slideshow-slide__content {
    position: relative;
    z-index: 5;
    order: -1; /* below 1200px: the text first, above the photo (Figma 375px frame) */
    display: grid;
    justify-items: start;
    gap: calc(12 * var(--cpx));
    padding: calc(40 * var(--cpx)) calc(28 * var(--cpx)) calc(26 * var(--cpx));
  }

  .slideshow-slide__subheading {
    margin: 0;
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: max(1.375rem, calc(24 * var(--cpx)));
    font-style: var(--font-heading--style);
    font-weight: 700;
    line-height: 1.15;
  }

  .slideshow-slide__text {
    max-inline-size: 34em;
    color: color-mix(in srgb, var(--color-text) 85%, var(--color-background));
    font-size: max(0.8125rem, calc(13 * var(--cpx)));
    line-height: 1.5;
  }

  .slideshow-slide__text p {
    margin: 0;
  }

  .slideshow-slide__text p + p {
    margin-block-start: 0.6em;
  }

  .slideshow-slide__actions {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: calc(12 * var(--cpx)) calc(20 * var(--cpx));
    margin-block-start: calc(16 * var(--cpx));
  }

  /* Two classes: the global .button rule loads after this file and would win over one class */
  .slideshow-slide__button.button {
    gap: 0.75em;
    min-block-size: max(2.75rem, calc(42 * var(--cpx)));
    padding-inline: max(1rem, calc(18 * var(--cpx)));
    font-size: max(0.75rem, calc(11 * var(--cpx)));
    letter-spacing: 0.08em;
  }

  .slideshow-slide__link.button {
    gap: 0.5em;
    font-size: max(0.75rem, calc(11 * var(--cpx)));
    letter-spacing: 0.08em;
  }

  .slideshow-slide__actions svg {
    flex: none;
    inline-size: 1.3em;
    block-size: auto;
  }

  .slideshow-slide__actions [aria-disabled='true'] {
    opacity: 0.5;
    cursor: not-allowed;
  }

  /* The scene: eyebrow, word, photo, outline. Figma phone frame from the eyebrow down = 375 x 450. */
  .slideshow-slide__scene {
    position: relative;
    aspect-ratio: 375 / 450;
  }

  .slideshow-slide__title,
  .slideshow-slide__twin {
    position: absolute;
    inset: 0;
    display: flex;
    justify-content: center;
    padding-block-start: calc(10 * var(--mpx));
    pointer-events: none;
  }

  .slideshow-slide__title {
    z-index: 1;
  }

  .slideshow-slide__model {
    position: absolute;
    z-index: 2;
    inset-block-end: 0;
    left: calc(197 * var(--mpx));
    block-size: calc(470 * var(--mpx) * var(--photo-size, 1));
    aspect-ratio: var(--model-ratio-phone);
    translate: -50% 0;
  }

  .slideshow-slide__model picture,
  .slideshow-slide__model img,
  .slideshow-slide__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
  }

  .slideshow-slide__model img {
    object-fit: contain;
    object-position: 50% 100%;
  }

  .slideshow-slide__placeholder {
    background-color: var(--color-tint-subtle);
    fill: var(--color-tint-border);
  }

  /*
    The outline copy: the same box and layout as the title, masked by the photo's own pixels (the script sets
    --model-mask from the loaded photo). The mask has the photo's box: the same size, at the bottom, centred
    on the same point. No mask yet (no JS, photo not loaded, or the browser can't read it) = no outline.
  */
  .slideshow-slide__twin {
    --mask-h: calc(470 * var(--mpx) * var(--photo-size, 1));
    --mask-w: calc(var(--mask-h) * var(--model-ratio-phone));
    --mask-x: calc(197 * var(--mpx) - var(--mask-w) / 2);
    z-index: 3;
    -webkit-mask-image: var(--model-mask);
    mask-image: var(--model-mask);
    -webkit-mask-repeat: no-repeat;
    mask-repeat: no-repeat;
    -webkit-mask-size: var(--mask-w) var(--mask-h);
    mask-size: var(--mask-w) var(--mask-h);
    -webkit-mask-position: var(--mask-x) 100%;
    mask-position: var(--mask-x) 100%;
  }

  .slideshow-slide__twin:not(.has-mask) {
    display: none;
  }

  .slideshow-slide__twin .slideshow-slide__eyebrow {
    visibility: hidden;
  }

  .slideshow-slide__title-inner {
    display: grid;
    align-content: start;
    justify-items: start;
    gap: calc(10 * var(--mpx));
  }

  .slideshow-slide__eyebrow {
    margin: 0;
    gap: calc(12 * var(--mpx));
    font-size: max(0.6875rem, calc(11 * var(--cpx)));
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.16em;
  }

  .slideshow-slide__eyebrow::before {
    inline-size: calc(20 * var(--mpx));
    block-size: 1px;
  }

  /* h1 / h2 reset: the size comes from the word length (Liquid) and "Big word size" */
  .slideshow-slide__word {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 92%, var(--color-background));
    font-family: var(--font-heading--family);
    font-size: calc(min(var(--word-size-phone) * var(--word-scale, 1), var(--word-fit-phone)) * var(--mpx));
    font-style: var(--font-heading--style);
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: -0.01em;
    white-space: nowrap;
    text-wrap: nowrap;
  }

  .slideshow-slide__word--outline {
    color: transparent;
    -webkit-text-stroke: 1px var(--slideshow-outline);
  }

  /* Handwriting: desktop only (the phone design has none) */
  .slideshow-slide__script {
    display: none;
  }

  /* Product card. Its sizes are in em of the card: font-size = card width / 21 (10px on a 210px card). */
  .slideshow-card {
    /* At most 20rem on tablets: a bigger card hides the photo */
    --card-w: min(calc(215 * var(--mpx)), 20rem);
    position: absolute;
    z-index: 4;
    right: calc(25 * var(--mpx));
    /* + 1.25rem: our arrows are 40px (tap size), the design's about 28px; the card corner must stay above them */
    bottom: calc(58 * var(--mpx) + 1.25rem);
    inline-size: var(--card-w);
    overflow: hidden;
    border-radius: 1.4em;
    background-color: var(--color-surface-raised);
    box-shadow: 0 1.2em 3em #0000002e;
    color: var(--color-text);
    font-size: calc(var(--card-w) / 21);
    rotate: 8deg;
  }

  /*
    The design has no pause button. The card goes up more when the controls are longer (relative to the slide),
    so they do not touch:
    - phones, when the pause button shows (autoplay, not pinned);
    - phones narrower than the 375px design: the card gets smaller, the buttons do not.
  */
  @media (max-width: 374px) {
    .slideshow-card {
      bottom: calc(58 * var(--mpx) + 3rem);
    }
  }

  @media (max-width: 749px) {
    .slideshow:has(.slideshow__pause:not([hidden])) .slideshow-card {
      bottom: calc(58 * var(--mpx) + 3rem);
    }
  }

  .slideshow-card__media {
    aspect-ratio: 420 / 250;
    overflow: hidden;
  }

  .slideshow-card__media img,
  .slideshow-card__placeholder {
    display: block;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .slideshow-card__placeholder {
    background-color: var(--color-tint-subtle);
    fill: var(--color-tint-border);
  }

  .slideshow-card__body {
    display: grid;
    gap: 0.3em;
    padding: 0.9em 1.1em 1.1em;
  }

  .slideshow-card__title {
    margin: 0;
    font-family: var(--font-heading--family);
    font-size: max(0.9375rem, 1.5em);
    font-style: var(--font-heading--style);
    font-weight: 700;
    line-height: 1.15;
  }

  .slideshow-card__link {
    color: inherit;
    text-decoration: none;
  }

  /* The title link covers the whole card (the card is positioned) */
  .slideshow-card__link::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
  }

  .slideshow-card__link:focus-visible {
    outline: none;
  }

  .slideshow-card:has(.slideshow-card__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .slideshow-card__type {
    margin: 0;
    color: var(--color-accent);
    font-size: max(0.625rem, 0.7em);
    letter-spacing: 0.2em;
    text-transform: uppercase;
  }

  .slideshow-card__price {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: 0 0.6em;
    margin: 0.4em 0 0;
    padding-inline-end: 3em;
  }

  .slideshow-card__current {
    font-size: max(1rem, 1.55em);
    line-height: 1.2;
  }

  .slideshow-card__compare {
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: max(0.75rem, 0.95em);
  }

  .slideshow-card__arrow {
    position: absolute;
    right: 1em;
    bottom: 1em;
    display: grid;
    place-items: center;
    inline-size: max(1.75rem, 2.1em);
    aspect-ratio: 1;
    border-radius: 50%;
    background-color: var(--color-surface-raised);
    box-shadow: 0 2px 10px #0000001f;
    color: var(--color-accent);
  }

  .slideshow-card__arrow svg {
    inline-size: 45%;
    block-size: auto;
  }

  /*
    Decorations: behind the text and the photo, past the sides (the stage clips them). Per decoration (Slide
    block): --deco-size, --deco-rotate, --deco-x / --deco-y (% of the slide: + = to the right / down) and
    --deco-blur ("Soft focus"; a little less below 1200px, where the images are smaller).
  */
  .slideshow-slide__deco {
    position: absolute;
    z-index: 0;
    filter: blur(calc(var(--deco-blur, 0px) * 0.6));
    rotate: var(--deco-rotate, 0deg);
    pointer-events: none;
  }

  .slideshow-slide__deco img {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  .slideshow-slide__deco--start {
    left: calc(-25 * var(--mpx) + var(--deco-x, 0) * 1%);
    bottom: calc(190 * var(--mpx) - var(--deco-y, 0) * 1%);
    inline-size: calc(95 * var(--mpx) * var(--deco-size, 1));
  }

  .slideshow-slide__deco--end {
    right: calc(-20 * var(--mpx) - var(--deco-x, 0) * 1%);
    top: calc(70 * var(--mpx) + var(--deco-y, 0) * 1%);
    inline-size: calc(80 * var(--mpx) * var(--deco-size, 1));
  }

  /* The phone layout (the opposite of the desktop media query below) */
  @media (max-width: 1023px), (max-width: 1199px) and (orientation: portrait) {
    .slideshow-slide__deco--no-phone {
      display: none;
    }
  }

  /* Theme editor: a slide with no content */
  .slideshow-slide__note {
    position: absolute;
    z-index: 6;
    inset-block-start: 50%;
    inset-inline: var(--space-md);
    margin: 0;
    padding: var(--space-md);
    border: 1px dashed currentColor;
    border-radius: var(--radius-xs);
    background-color: var(--color-background);
    font-style: italic;
    text-align: center;
  }

  /* Counter, line, arrows, pause: bottom left, over the photo */
  .slideshow__controls {
    position: absolute;
    z-index: 6;
    bottom: var(--space-md);
    left: calc((100% - var(--slideshow-slide-width)) / 2 + 1.25rem);
    display: flex;
    align-items: center;
    gap: 0.625rem;
  }

  .slideshow__counter {
    margin: 0;
    color: color-mix(in srgb, var(--color-text) 85%, var(--color-background));
    font-size: 0.75rem;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
  }

  .slideshow__line {
    inline-size: 2.5rem;
    block-size: 1px;
    background-color: var(--color-accent);
  }

  /*
    Figma "Liquid Glass Button", on all screens: 40 x 40, white 13% fill (#ffffff21), a 6% red edge (#7d00000f)
    and a soft shadow (#00000012); the arrow in the highlight color. On white the fill does not show: the
    shadow draws the circle (as in the design). Never smaller than 40px (tap size).
  */
  .slideshow__button {
    display: grid;
    place-items: center;
    inline-size: 2.5rem;
    aspect-ratio: 1;
    margin: 0;
    padding: 0;
    border: 1px solid #7d00000f;
    border-radius: 2.5rem;
    background-color: #ffffff21;
    box-shadow: 0 5px 10px #00000012;
    color: var(--color-accent);
    cursor: pointer;
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }

  .slideshow__button:hover {
    box-shadow: 0 5px 14px #00000024;
  }

  /*
    Phone layout: the buttons sit on the photo, where the 13% white fill does not show. They get the color
    scheme's background and a stronger shadow, so they stand out from the photo.
  */
  @media (max-width: 1023px), (max-width: 1199px) and (orientation: portrait) {
    .slideshow__button {
      background-color: var(--color-background);
      box-shadow: 0 4px 12px #00000029;
    }

    .slideshow__button:hover {
      box-shadow: 0 5px 16px #00000038;
    }
  }

  /* Page scroll: no previous slide before slide 1, no next slide after the last one */
  .slideshow__arrow[aria-disabled='true'] {
    opacity: 0.4;
    cursor: default;
  }

  .slideshow__button svg {
    inline-size: 45%;
    block-size: auto;
  }

  /* The left arrow = the right arrow mirrored (Figma scaleX(-1)) */
  .slideshow__arrow--prev svg {
    transform: scaleX(-1);
  }

  .slideshow__pause[hidden] {
    display: none;
  }

  .slideshow__pause svg {
    inline-size: 40%;
  }

  .slideshow__pause-icon--play,
  .slideshow__pause[aria-pressed='true'] .slideshow__pause-icon--pause {
    display: none;
  }

  .slideshow__pause[aria-pressed='true'] .slideshow__pause-icon--play {
    display: block;
  }

  /* Side dots and the scroll hint: desktop only */
  .slideshow__dots,
  .slideshow__hint {
    display: none;
  }

  /* ---------- Page scroll, pinned (all screen sizes; the script adds .is-pinned) ---------- */

  /*
    The track is one screen plus one "Scroll distance for each slide" per extra slide; the stage stays on the
    screen while the track passes.
  */
  .slideshow.is-pinned .slideshow__track {
    block-size: calc(var(--slideshow-screen) + (var(--slide-count) - 1) * var(--scroll-length) * 1svh);
  }

  .slideshow.is-pinned .slideshow__stage {
    position: sticky;
    top: var(--slideshow-offset);
    block-size: var(--slideshow-screen);
  }

  /*
    Phone layout, pinned: the stage keeps its own height (full width, the tallest slide; it does not stretch or
    shrink to the screen). The track = the stage + one "Scroll distance for each slide" per extra slide.
    Sticky top: under the room a floating header takes when the stage fits the screen; else the stage stops with
    its bottom on the screen bottom (the text above scrolls away, the photo, card and buttons stay).
    --slideshow-stage-h = the stage height, set by the script.
  */
  @media (max-width: 1023px), (max-width: 1199px) and (orientation: portrait) {
    /* A height, not padding: a sticky box can't move into its parent's padding */
    .slideshow.is-pinned .slideshow__track {
      block-size: calc(var(--slideshow-stage-h, 0px) + (var(--slide-count) - 1) * var(--scroll-length) * 1svh);
    }

    .slideshow.is-pinned .slideshow__stage {
      top: calc(
        var(--slideshow-offset) +
          min(
            max(0px, calc(var(--header-space, 0px) - var(--slideshow-offset))),
            calc(var(--slideshow-screen) - var(--slideshow-stage-h, 0px))
          )
      );
      block-size: auto;
    }
  }

  /* ---------- Desktop layout: the Figma 1920 x 1031 frame ---------- */

  /* 1200px and up, and 1024px and up on a screen wider than it is tall (the phone layout is too tall there) */
  @media (min-width: 1200px), (min-width: 1024px) and (orientation: landscape) {
    /*
      The stage is exactly the screen height this section may fill (--slideshow-screen: 100svh less the header
      and announcement bar when first), at least 36rem: below that the section grows and the page scrolls.
      It is the size container, so the parts use both its width and its height:
      - --px = stage width / 1920: horizontal places and widths (a short window never makes the design narrower);
      - --pv = stage height / 1031, at most 1.3 x --px: vertical places (the frame below is 1031 --pv tall and
        stands on the stage's bottom edge, so the photo, arrows and hint are always on the first screen);
      - --pm = the smaller of the two: sizes that must fit both ways (big word, photo width, card, text).
    */
    .slideshow__stage {
      --px: calc(100cqw / 1920);
      --py: calc(100cqh / 1031);
      --pv: min(var(--py), var(--px) * 1.3);
      --pm: min(var(--px), var(--pv));
      container-type: size;
      block-size: max(var(--slideshow-screen), 36rem);
    }

    /* "Make the section one screen tall" off: the design's shape */
    .slideshow--fit .slideshow__stage {
      block-size: auto;
      aspect-ratio: 1920 / 1031;
    }

    .slideshow__frame {
      position: absolute;
      inset-inline: 0;
      bottom: 0;
      block-size: calc(1031 * var(--pv));
    }

    .slideshow__slides {
      block-size: 100%;
    }

    .slideshow-slide {
      container-type: normal;
      display: block;
      inline-size: auto;
      block-size: 100%;
      margin-inline: 0;
    }

    .slideshow-slide__scene {
      position: absolute;
      inset: 0;
      aspect-ratio: auto;
    }

    /* Eyebrow and big word: their top at y 222 of the frame, centred across */
    .slideshow-slide__title,
    .slideshow-slide__twin {
      padding-block-start: calc(222 * var(--pv));
    }

    .slideshow-slide__title-inner {
      gap: calc(4 * var(--pv));
    }

    .slideshow-slide__eyebrow {
      gap: calc(20 * var(--px));
      font-size: max(0.6875rem, calc(15 * var(--pm)));
      letter-spacing: 0.2em;
    }

    .slideshow-slide__eyebrow::before {
      inline-size: calc(62 * var(--px));
    }

    .slideshow-slide__word {
      font-size: calc(min(var(--word-size) * var(--word-scale, 1), var(--word-fit)) * var(--pm));
    }

    .slideshow-slide__word--outline {
      -webkit-text-stroke-width: max(1px, calc(1.5 * var(--pm)));
    }

    /* The photo stands on the bottom edge; its height from the stage height (never below the screen) */
    .slideshow-slide__model {
      left: calc(935 * var(--px));
      block-size: calc(840 * var(--pv) * var(--photo-size, 1));
      aspect-ratio: var(--model-ratio);
    }

    .slideshow-slide__twin {
      --mask-h: calc(840 * var(--pv) * var(--photo-size, 1));
      --mask-w: calc(var(--mask-h) * var(--model-ratio));
      --mask-x: calc(935 * var(--px) - var(--mask-w) / 2);
    }

    /* Handwriting: top right, accent font, one word per line, slightly turned, with a curly arrow */
    .slideshow-slide__script {
      position: absolute;
      z-index: 3;
      top: calc(128 * var(--pv));
      left: calc(1640 * var(--px));
      display: block;
      inline-size: min-content;
      margin: 0;
      color: var(--color-accent);
      font-family: var(--font-accent--family);
      font-size: max(1.5rem, calc(50 * var(--pm)));
      font-style: italic;
      font-weight: var(--font-accent--weight);
      line-height: 1.15;
      text-align: center;
      rotate: -8deg;
    }

    .slideshow-slide__script-arrow {
      position: absolute;
      top: 100%;
      right: 90%;
      inline-size: calc(64 * var(--pm));
      block-size: auto;
      margin-block-start: calc(18 * var(--pm));
      rotate: 8deg;
    }

    /* Left column: 50 design px from the left, its top at y 580 of the frame, under the big word */
    .slideshow-slide__content {
      position: absolute;
      top: calc(580 * var(--pv));
      left: max(1.25rem, calc(50 * var(--px)));
      inline-size: max(23rem, calc(520 * var(--pm)));
      gap: calc(30 * var(--pv));
      padding: 0;
    }

    .slideshow-slide__subheading {
      font-size: max(1.25rem, calc(34 * var(--pm)));
    }

    .slideshow-slide__text {
      max-inline-size: 20em;
      font-size: max(0.9375rem, calc(22 * var(--pm)));
      line-height: 1.45;
    }

    .slideshow-slide__actions {
      gap: calc(16 * var(--pv)) calc(45 * var(--px));
      margin-block-start: calc(28 * var(--pv));
    }

    .slideshow-slide__button.button {
      min-block-size: max(2.75rem, calc(60 * var(--pm)));
      padding-inline: max(1.25rem, calc(32 * var(--pm)));
      font-size: max(0.8125rem, calc(17 * var(--pm)));
    }

    .slideshow-slide__link.button {
      font-size: max(0.8125rem, calc(17 * var(--pm)));
    }

    /* Card: bottom right, its size fits both the width and the height */
    .slideshow-card {
      --card-w: max(15rem, calc(420 * var(--pm)));
      right: auto;
      bottom: calc(62 * var(--pv));
      left: calc(1262 * var(--px));
    }

    .slideshow-slide__deco {
      filter: blur(var(--deco-blur, 0px));
    }

    .slideshow-slide__deco--start {
      top: auto;
      bottom: calc(486 * var(--pv) - var(--deco-y, 0) * 1%);
      left: calc(-20 * var(--px) + var(--deco-x, 0) * 1%);
      inline-size: calc(210 * var(--pm) * var(--deco-size, 1));
    }

    .slideshow-slide__deco--end {
      top: auto;
      right: calc(-30 * var(--px) - var(--deco-x, 0) * 1%);
      bottom: calc(-40 * var(--pv) - var(--deco-y, 0) * 1%);
      inline-size: calc(180 * var(--pm) * var(--deco-size, 1));
    }

    .slideshow-slide__note {
      inset-inline: 30%;
    }

    /* Counter, line, arrows, pause: on the bottom edge, left */
    .slideshow__controls {
      bottom: max(var(--space-md), calc(20 * var(--pv)));
      left: max(1.25rem, calc(50 * var(--px)));
      gap: max(0.625rem, calc(14 * var(--px)));
    }

    .slideshow__counter {
      font-size: max(0.8125rem, calc(17 * var(--pm)));
    }

    .slideshow__line {
      inline-size: calc(62 * var(--px));
    }

    /*
      Side dots (Figma rail), centred on the frame's y 515 at the right edge: separate pieces with gaps. Dot =
      a 24px button (tap size) with a 12px dot; the shown slide's dot is solid red, the others pale with a faint
      ring. Lines 2px wide: the two that touch the shown dot are red, the others pale.
    */
    .slideshow__dots {
      position: absolute;
      z-index: 6;
      top: calc(515 * var(--pv));
      right: max(1.25rem, calc(44 * var(--px)));
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0.25rem;
      translate: 0 -50%;
    }

    .slideshow__rail {
      inline-size: 2px;
      block-size: max(1.5rem, calc(36 * var(--pm)));
      border-radius: 1px;
      background-color: color-mix(in srgb, var(--color-accent) 14%, var(--color-background));
      transition: background-color var(--duration-base) var(--ease-out);
    }

    .slideshow__rail--end {
      block-size: max(0.75rem, calc(16 * var(--pm)));
    }

    .slideshow__rail.is-active {
      background-color: var(--color-accent);
    }

    .slideshow__dot {
      display: grid;
      place-items: center;
      inline-size: 1.5rem;
      block-size: 1.5rem;
      margin: 0;
      padding: 0;
      border: 0;
      background: none;
      cursor: pointer;
    }

    .slideshow__dot::before {
      content: '';
      inline-size: 0.75rem;
      aspect-ratio: 1;
      border-radius: 50%;
      background-color: color-mix(in srgb, var(--color-accent) 22%, var(--color-background));
      box-shadow: 0 0 0 1px color-mix(in srgb, var(--color-accent) 25%, transparent);
      transition: background-color var(--duration-fast) var(--ease-out);
    }

    .slideshow__dot:hover::before,
    .slideshow__dot[aria-current='true']::before {
      background-color: var(--color-accent);
    }

    /* "Scroll to explore": on the bottom edge, centred. The mouse = a 20 x 36 pill with a red dot. */
    .slideshow__hint {
      position: absolute;
      z-index: 6;
      bottom: calc(14 * var(--pv));
      left: 50%;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: calc(10 * var(--pv));
      margin: 0;
      color: var(--color-accent);
      font-size: max(0.6875rem, calc(13 * var(--pm)));
      font-weight: var(--font-weight-medium);
      letter-spacing: 0.25em;
      text-transform: uppercase;
      white-space: nowrap;
      translate: -50% 0;
      pointer-events: none;
    }

    .slideshow__mouse {
      position: relative;
      inline-size: 1.25rem;
      block-size: 2.25rem;
      border: 2px solid #dcdce4;
      border-radius: var(--radius-pill);
    }

    .slideshow__mouse::after {
      content: '';
      position: absolute;
      top: 0.3125rem;
      left: 50%;
      inline-size: 0.375rem;
      aspect-ratio: 1;
      margin-left: -0.1875rem;
      border-radius: 50%;
      background-color: var(--color-accent);
    }

    /* Pinned (only when the screen is at least 36rem tall): exactly one screen, also with the design shape */
    .slideshow.is-pinned .slideshow__stage {
      display: block;
      aspect-ratio: auto;
    }
  }

  /* ---------- Motion ---------- */

  /*
    Slide entrance (Figma Default frames): plays when a slide becomes the shown slide (.is-entering, set by the
    script): the photo rises and fades in, then the big word, then the outline, text, card and decorations. Only
    with "Enable animations" (.motion-on) and no reduced motion. Slide 1 never moves on page load when the
    section is on screen (decision 3: never hide the hero): .is-waiting holds the first frame for a section
    further down until it comes on screen.
    The scroll hint's dot moves down and fades, then starts again (reduced motion: it stays at the top).
  */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__model {
      animation: slideshow-rise 1s var(--ease-out) both;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__title .slideshow-slide__word {
      animation: slideshow-word 0.9s var(--ease-out) 0.3s both;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__twin {
      animation: slideshow-fade 0.6s ease 0.9s both;
    }

    .motion-on .slideshow--anim-rise .is-entering :is(.slideshow-slide__title .slideshow-slide__eyebrow, .slideshow-slide__content > *, .slideshow-card, .slideshow-slide__script, .slideshow-slide__deco) {
      animation: slideshow-up 0.8s var(--ease-out) 0.5s both;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__content > :nth-child(2) {
      animation-delay: 0.6s;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__content > :nth-child(3) {
      animation-delay: 0.7s;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-card {
      animation-delay: 0.65s;
    }

    .motion-on .slideshow--anim-rise .is-entering .slideshow-slide__script {
      animation-delay: 0.85s;
    }

    .motion-on .slideshow--anim-fade .slideshow-slide.is-entering {
      animation: slideshow-fade 0.7s ease both;
    }

    .motion-on :is(.slideshow--anim-rise, .slideshow--anim-fade) .slideshow-slide.is-leaving {
      animation: slideshow-fade-out 0.5s ease both;
    }

    /* Waiting to come on screen: hold the first frame of the entrance */
    .slideshow-slide.is-waiting,
    .slideshow-slide.is-waiting * {
      animation-play-state: paused !important;
    }

    .motion-on .slideshow__mouse::after {
      animation: slideshow-wheel 1.8s var(--ease-out) infinite;
    }
  }

  @keyframes slideshow-rise {
    from {
      opacity: 0;
      transform: translateY(16%);
    }
  }

  @keyframes slideshow-word {
    from {
      opacity: 0;
      transform: scale(1.08);
    }
  }

  @keyframes slideshow-up {
    from {
      opacity: 0;
      transform: translateY(1.5rem);
    }
  }

  @keyframes slideshow-fade {
    from {
      opacity: 0;
    }
  }

  @keyframes slideshow-fade-out {
    to {
      opacity: 0;
    }
  }

  @keyframes slideshow-wheel {
    0% {
      opacity: 1;
      transform: translateY(0);
    }

    70% {
      opacity: 0;
      transform: translateY(0.875rem);
    }

    100% {
      opacity: 0;
      transform: translateY(0.875rem);
    }
  }

/* sections/testimonials.liquid */

  testimonial-showcase {
    display: block;
  }

  /* Theme editor only: the section has no Review block */
  .testimonials-empty {
    padding: var(--space-2xl) var(--page-margin);
    text-align: center;
  }

  /*
    Section height: at least the chosen share of the screen, the content centred vertically inside.
    Fit content = as tall as the content needs. svh = the small viewport height, so the address bar on
    phones never pushes the bottom out of view.
  */
  .testimonials {
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding-block: var(--section-padding-top) var(--section-padding-bottom);
    overflow: hidden;
  }

  .testimonials--height-full {
    min-block-size: 100svh;
  }

  .testimonials--height-large {
    min-block-size: 80svh;
  }

  .testimonials--height-medium {
    min-block-size: 64svh;
  }

  .testimonials--height-small {
    min-block-size: 48svh;
  }

  .testimonials__inner {
    display: flex;
    flex-direction: column;
    gap: clamp(2.5rem, 1.5rem + 3vw, 5rem);
    inline-size: min(
      calc(var(--section-width, var(--page-width)) - var(--page-margin) * 2),
      calc(100% - var(--page-margin) * 2)
    );
    margin-inline: auto;
  }

  .testimonials__header {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-md);
    text-align: center;
  }

  .testimonials__eyebrow,
  .testimonials__heading {
    margin: 0;
  }

  .testimonials__heading {
    font-size: var(--font-size-display);
  }

  /* "What our *Clients* Say": italic words in the highlight colour, not slanted */
  .testimonials__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  /*
    Phones and tablets (below 1200px, Figma mobile): one column. The avatar group, a row of dots, then
    the cards. Desktop (1200px+) changes this to three columns, see the media query below.
  */
  .testimonials__body {
    position: relative;
    /* Own layer: the closing quote (z-index -1) stays above the section's background, behind the cards */
    isolation: isolate;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    row-gap: var(--space-lg);
    align-items: start;
    /* Closing ” size: behind the card on phones and tablets, in its own gutter on desktop */
    --quote-end-size: clamp(6rem, 12vw, 9rem);
  }

  /*
    Desktop (Figma 1920px): avatars ~420px | timeline | cards ~870px. ~90px from the avatars to the
    dots, ~110px from the dots to the card (the opening quote sits in that gap, over the card's corner).
    The closing ” gets its own space on the right (Figma: the card stops ~290px before the edge and the
    quote sits in that gutter, bottom right), instead of lying under the card.
  */
  @media (min-width: 1200px) {
    .testimonials__body {
      --quote-end-size: clamp(6rem, 10.5vw, 11rem);

      /* Laptops and normal desktops: avatar column up to 30rem, the cards take the rest */
      grid-template-columns: clamp(16rem, 24vw, 30rem) auto minmax(0, 1fr);
      column-gap: clamp(2rem, 4.6vw, 5.5rem);
      row-gap: 0;
      padding-inline-end: calc(var(--quote-end-size) + 1rem);
    }
  }

  /*
    Large desktops (24" and up, 1700px+): the Figma quote size (292px at 1920px) and the Layout split
    setting, 40/60, 45/55 or 50/50
  */
  @media (min-width: 1700px) {
    .testimonials__body {
      --quote-end-size: clamp(8rem, 15.2vw, 18.25rem);

      grid-template-columns: minmax(0, var(--split-left, 40fr)) auto minmax(0, var(--split-right, 60fr));
    }
  }

  /* ---------- Avatars: fixed slots, the active reviewer in slot 0 (large, top right) ---------- */
  /*
    The avatar group is a size container: the avatars are sized in cqi (1cqi = 1% of the group's
    width), so a wider group (bigger screen, or a 50/50 split) gives bigger faces.
    The Figma avatar area is ~420 x 480 (7 : 8). Keeping that shape (height follows the width) puts
    every slot exactly where the Figma has it at any size.
    Phones and tablets: the group is centred, 42% of the width (Figma mobile: ~158px of 375px), at
    least 9.5rem and at most 24rem. Desktop: it fills its column.
  */
  .testimonials__avatars {
    position: relative;
    justify-self: center;
    inline-size: clamp(9.5rem, 42%, 24rem);
    aspect-ratio: 7 / 8;
    container-type: inline-size;
  }

  @media (min-width: 1200px) {
    .testimonials__avatars {
      justify-self: stretch;
      inline-size: auto;
    }
  }

  /* Phones and tablets (Figma mobile): small faces 25%, the large one 36% of the group */
  .testimonials__avatar {
    --avatar-size: 25cqi;
    --avatar-border: 2px;

    position: absolute;
    inset-inline-start: var(--x);
    inset-block-start: var(--y);
    display: grid;
    place-items: center;
    inline-size: var(--avatar-size);
    block-size: var(--avatar-size);
    min-block-size: 0;
    margin: 0;
    padding: 0;
    overflow: hidden;
    border: var(--avatar-border) solid #ffffff;
    border-radius: var(--radius-pill);
    background-color: var(--color-tint);
    box-shadow: 0 0.5rem 1.25rem #00000026;
    cursor: pointer;
    translate: -50% -50%;
    transition:
      inset-inline-start 0.7s var(--ease-out),
      inset-block-start 0.7s var(--ease-out),
      inline-size 0.7s var(--ease-out),
      block-size 0.7s var(--ease-out),
      border-color 0.7s var(--ease-out);
  }

  .testimonials__avatar[data-slot='0'] {
    --avatar-size: 36cqi;

    border-color: var(--color-accent);
  }

  @media (min-width: 1200px) {
    .testimonials__avatar {
      --avatar-size: clamp(4.25rem, 19cqi, 8rem);
      --avatar-border: 3px;
    }

    .testimonials__avatar[data-slot='0'] {
      --avatar-size: clamp(6rem, 27cqi, 11.5rem);
    }
  }

  .testimonials__avatar img {
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  .testimonials__initial {
    color: var(--color-accent);
    font-family: var(--font-heading--family);
    font-size: clamp(1rem, 12cqi, 1.5rem);
  }

  /* Slot positions (centre of each avatar, % of the avatar area), measured on the Figma */
  .testimonials__avatar[data-slot='0'] { --x: 79%; --y: 15%; }
  .testimonials__avatar[data-slot='1'] { --x: 19%; --y: 31%; }
  .testimonials__avatar[data-slot='2'] { --x: 54%; --y: 53%; }
  .testimonials__avatar[data-slot='3'] { --x: 13%; --y: 76%; }
  .testimonials__avatar[data-slot='4'] { --x: 71%; --y: 89%; }
  .testimonials__avatar[data-slot='5'] { --x: 40%; --y: 12%; }
  .testimonials__avatar[data-slot='6'] { --x: 92%; --y: 55%; }
  .testimonials__avatar[data-slot='7'] { --x: 33%; --y: 95%; }

  /*
    More than 5 reviews: a balanced layout per count, spread round the centre slot (2), so the extra
    faces don't crowd the Figma group. Ring order (0 -> 1 -> 3 -> 4 -> ...) goes round the group, so
    the rotation flows. 5 or fewer reviews use the Figma positions above.
  */
  /*
    One review: the face in the centre. Phones and tablets: a low group (5 : 2), so no empty area
    under it; desktop keeps the 7 : 8 column next to the card.
  */
  .testimonials__avatars[data-count='1'] {
    aspect-ratio: 5 / 2;
  }

  .testimonials__avatars[data-count='1'] .testimonials__avatar[data-slot='0'] { --x: 50%; --y: 50%; }

  @media (min-width: 1200px) {
    .testimonials__avatars[data-count='1'] {
      aspect-ratio: 7 / 8;
    }
  }

  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='0'] { --x: 78%; --y: 13%; }
  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='1'] { --x: 22%; --y: 18%; }
  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='2'] { --x: 50%; --y: 48%; }
  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='3'] { --x: 12%; --y: 62%; }
  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='4'] { --x: 40%; --y: 92%; }
  .testimonials__avatars[data-count='6'] .testimonials__avatar[data-slot='5'] { --x: 86%; --y: 70%; }

  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='0'] { --x: 78%; --y: 13%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='1'] { --x: 22%; --y: 14%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='2'] { --x: 51%; --y: 50%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='3'] { --x: 11%; --y: 52%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='4'] { --x: 26%; --y: 89%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='5'] { --x: 74%; --y: 90%; }
  .testimonials__avatars[data-count='7'] .testimonials__avatar[data-slot='6'] { --x: 91%; --y: 52%; }

  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='0'] { --x: 78%; --y: 12%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='1'] { --x: 34%; --y: 8%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='2'] { --x: 51%; --y: 50%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='3'] { --x: 10%; --y: 38%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='4'] { --x: 14%; --y: 76%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='5'] { --x: 46%; --y: 94%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='6'] { --x: 82%; --y: 82%; }
  .testimonials__avatars[data-count='8'] .testimonials__avatar[data-slot='7'] { --x: 92%; --y: 46%; }

  /* ---------- Timeline: line + dots ---------- */
  /*
    Phones and tablets (Figma mobile): a centred row, the line a little longer than the dots and faded
    at both ends. Desktop: a vertical line with the dots in a column.
  */
  .testimonials__timeline {
    position: relative;
    justify-self: center;
    display: flex;
    align-items: center;
    gap: var(--space-md);
    padding-inline: 2.5rem;
  }

  /* No script yet (or none at all): the dots can't switch reviews, so they keep their place hidden */
  testimonial-showcase:not(:defined) .testimonials__timeline {
    visibility: hidden;
  }

  .testimonials__timeline::before {
    content: "";
    position: absolute;
    inset-block-start: 50%;
    inset-inline: 0;
    block-size: 1px;
    background-image: linear-gradient(
      to right,
      transparent,
      color-mix(in srgb, var(--color-accent) 40%, transparent) 20% 80%,
      transparent
    );
  }

  .testimonials__dots {
    --dot-size: 0.75rem;

    position: relative;
    display: flex;
    /* Dot centres 30px apart (Figma mobile), more than the 24px target size (WCAG 2.5.8) */
    gap: 1.125rem;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  @media (min-width: 1200px) {
    .testimonials__timeline {
      justify-self: stretch;
      flex-direction: column;
      gap: var(--space-lg);
      padding: var(--space-xl) 0;
    }

    .testimonials__timeline::before {
      inset-block: 0;
      inset-inline-start: 50%;
      inset-inline-end: auto;
      inline-size: 1px;
      block-size: auto;
      background-image: none;
      background-color: color-mix(in srgb, var(--color-accent) 40%, transparent);
    }

    .testimonials__dots {
      --dot-size: 1rem;

      flex-direction: column;
      gap: clamp(1.75rem, 2.8vw, 2.5rem);
    }
  }

  .testimonials__dot {
    display: block;
    inline-size: var(--dot-size);
    block-size: var(--dot-size);
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 1px solid var(--color-accent);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    cursor: pointer;
    transition:
      background-color var(--duration-base) var(--ease-out),
      scale var(--duration-base) var(--ease-out);
  }

  .testimonials__dot[aria-current='true'] {
    background-color: var(--color-accent);
    scale: 1.3;
  }

  .testimonials__dot:focus-visible {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .testimonials__pause {
    position: relative;
    display: grid;
    place-items: center;
    inline-size: 2rem;
    block-size: 2rem;
    min-block-size: 0;
    margin: 0;
    padding: 0;
    border: 1px solid color-mix(in srgb, var(--color-accent) 50%, transparent);
    border-radius: var(--radius-pill);
    background-color: var(--color-background);
    color: var(--color-accent);
    cursor: pointer;
  }

  .testimonials__pause svg {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .testimonials__pause-icon--play,
  .testimonials__pause[aria-pressed='true'] .testimonials__pause-icon--pause {
    display: none;
  }

  .testimonials__pause[aria-pressed='true'] .testimonials__pause-icon--play {
    display: block;
  }

  /* ---------- Cards: the active one in full, the next one faded below ---------- */
  /*
    The quote marks sit in this wrapper, outside the viewport: the viewport clips (overflow: hidden)
    and would cut off the marks that overlap the card's top-left corner. The space above the card (for
    the quote) is on this wrapper too: inside the clipped viewport, the previous card would show
    through above the active one.
  */
  .testimonials__cards-area {
    position: relative;
    padding-block-start: clamp(1.5rem, 2.4vw, 2.8rem);
  }

  @media (min-width: 1200px) {
    .testimonials__cards-area {
      margin-inline-start: clamp(0.75rem, 1.4vw, 1.75rem);
    }
  }

  .testimonials__viewport {
    position: relative;
  }

  /*
    Figma quote marks (icon-quote-open / -close.svg, currentColor). Opening: 125px wide at 1920px, gold
    at 42%, overlapping the card's top-left corner (~55px left of it, ~45px above).
  */
  .testimonials__quote {
    position: absolute;
    inset-block-start: 0;
    inset-inline-start: calc(clamp(3.5rem, 6.5vw, 7.8rem) * -0.45);
    z-index: 2;
    display: block;
    inline-size: clamp(3.5rem, 6.5vw, 7.8rem);
    color: color-mix(in srgb, var(--color-accent) 42%, transparent);
    pointer-events: none;
  }

  .testimonials__quote svg {
    display: block;
    inline-size: 100%;
    block-size: auto;
  }

  /*
    Closing: gold at 10%, behind everything. Desktop: 292px wide at 1920px, bottom right of the
    section. Phones and tablets (Figma mobile): on the next card's bottom right corner, partly past the
    screen edge (the section clips it).
  */
  .testimonials__quote--end {
    inset: auto calc(var(--page-margin) * -1) calc(var(--quote-end-size) * -0.3) auto;
    z-index: -1;
    inline-size: var(--quote-end-size);
    color: color-mix(in srgb, var(--color-accent) 10%, transparent);
  }

  @media (min-width: 1200px) {
    .testimonials__quote--end {
      inset-inline-end: 0;
    }
  }

  .testimonials__cards {
    display: flex;
    flex-direction: column;
    gap: var(--space-lg);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  /*
    Light glass card (Figma "Rectangle 2213": 29px corners, cream at 20%). All cards get the height of
    the tallest review (--card-height, set by the script), so the section keeps one height while the
    reviews change.
    Glass edge, the same as the search popup cards: a thin white light on the top and right edges, and
    a soft dark inner shadow, even on all sides (no offset), at 6% so it stays light. It shows the card
    on the cream page, where a 20% cream fill alone is invisible. No outer shadow and no backdrop blur
    (a blur on a flat cream background changes nothing and costs paint time).
  */
  .testimonials__card {
    min-block-size: var(--card-height, auto);
    display: flex;
    flex-direction: column;
    /* Figma: ~55px between the name / date and the review text */
    gap: clamp(1.75rem, 1rem + 2vw, 3.4rem);
    /* Figma: ~50px top, ~72px at the sides */
    padding: clamp(1.5rem, 1rem + 2vw, 3.1rem) clamp(1.5rem, 1rem + 3vw, 4.5rem);
    border: 0;
    border-radius: 1.8125rem;
    background-color: #fcf6e833;
    box-shadow:
      inset -1px 1px 0 #ffffffcc,
      inset 1px -1px 0 #ffffff80,
      inset 0 0 1rem #0000000f;
    opacity: 0.45;
    transition: opacity 0.6s var(--ease-out);
  }

  .testimonials__card.is-active,
  testimonial-showcase:not(.is-enhanced) .testimonials__card {
    opacity: 1;
  }

  /*
    Desktop: cards are at least the Figma card height (343px), even for a short review; longer reviews
    still grow (the tallest one sets --card-height). While the script measures, --card-height is 'auto',
    which makes this max() invalid for a moment, so the cards fall back to their natural height and are
    measured correctly. After the base .testimonials__card rule on purpose: same specificity, so the
    later rule wins.
  */
  @media (min-width: 1200px) {
    .testimonials__card {
      min-block-size: max(var(--card-height, 0px), 21.4375rem);
    }
  }

  /* Without the script all reviews show in a list: the copy of the first one is not needed */
  testimonial-showcase:not(.is-enhanced) .testimonials__card--clone {
    display: none;
  }

  .testimonials__meta {
    display: flex;
    flex-wrap: wrap;
    align-items: flex-start;
    justify-content: space-between;
    gap: var(--space-sm);
  }

  .testimonials__name,
  .testimonials__date {
    margin: 0;
    letter-spacing: var(--letter-spacing-label);
    text-transform: uppercase;
  }

  /* Figma: semi-bold, letter-spaced name; the date in body size, muted grey, a little below */
  .testimonials__name {
    font-size: var(--font-size-body-sm);
    font-weight: 600;
  }

  .testimonials__date {
    margin-block-start: 0.25rem;
    color: color-mix(in srgb, var(--color-text) 65%, var(--color-background));
    font-size: var(--font-size-body-sm);
  }

  /* Stars: five outlines, with the filled row on top cut to the rating (4.5 -> 90%) */
  .testimonials__stars {
    --star-size: 1.4rem;

    position: relative;
    display: inline-grid;
    color: #e3a83a;
  }

  .testimonials__stars-row {
    grid-area: 1 / 1;
    display: flex;
    gap: calc(var(--star-size) * 0.18);
  }

  .testimonials__stars-row svg {
    inline-size: var(--star-size);
    block-size: var(--star-size);
  }

  .testimonials__stars-row--empty svg path {
    fill: none;
    stroke: currentcolor;
    stroke-width: 1.5;
  }

  .testimonials__stars-row--full {
    clip-path: inset(0 calc(100% - var(--rating-fill, 100%)) 0 0);
  }

  .testimonials__stars-row--full svg path {
    fill: currentcolor;
  }

  .testimonials__text {
    font-size: var(--font-size-body-lg);
  }

  /*
    Normal wrapping: the theme's text-wrap: pretty shortens the last lines of a paragraph, which makes a
    ragged block in this narrow card (Figma: full lines)
  */
  .testimonials__text > * {
    margin: 0;
    text-wrap: wrap;
  }

  /*
    Phones (Figma mobile, 375px): a smaller heading and a smaller card. Name 12px, date 11px, stars
    13px, review text 14px, ~20px side padding, 16px corners, 12px between the cards.
  */
  @media (max-width: 749px) {
    .testimonials__inner {
      gap: var(--space-lg);
    }

    .testimonials__heading {
      font-size: var(--font-size-h2);
    }

    .testimonials__cards {
      gap: var(--space-sm);
    }

    .testimonials__card {
      gap: var(--space-sm);
      padding: 1.125rem 1.25rem 1.25rem;
      border-radius: 1rem;
    }

    .testimonials__name {
      font-size: 0.75rem;
    }

    .testimonials__date {
      margin-block-start: 0.125rem;
      font-size: 0.6875rem;
    }

    .testimonials__stars {
      --star-size: 0.8125rem;
    }

    .testimonials__text {
      font-size: 0.875rem;
      line-height: 1.5;
    }
  }

  /*
    With the script: the cards list moves up so the active card sits at the top of the viewport, which
    shows the active card plus the top of the next one, fading out.
  */
  /*
    overflow: clip, not hidden: a clipped box can't scroll, so keyboard focus on a link in a review
    never scrolls the list on top of its translate (hidden = fallback for older browsers)
  */
  testimonial-showcase.is-enhanced .testimonials__viewport {
    overflow: hidden;
    overflow: clip;
    block-size: var(--viewport-height, auto);
    /* Only the last ~12% fades, so the next review stays readable (faded), as in the Figma */
    mask-image: linear-gradient(to bottom, #000000 88%, #00000000 100%);
    transition: block-size 0.6s var(--ease-out);
  }

  testimonial-showcase.is-enhanced .testimonials__cards {
    translate: 0 var(--cards-offset, 0);
    transition: translate 0.7s var(--ease-out);
  }

  @media (prefers-reduced-motion: reduce) {
    .testimonials__avatar,
    .testimonials__card,
    .testimonials__dot,
    testimonial-showcase.is-enhanced .testimonials__cards,
    testimonial-showcase.is-enhanced .testimonials__viewport {
      transition: none;
    }
  }

/* sections/trending-products.liquid */

  /*
    Figma: two halves, the dark list panel (snippets/trending-list.liquid) and a full-height photo.
    Below 1200px: one column, the list first, then the photo.
  */
  .trending {
    display: grid;
  }

  @media (min-width: 1200px) {
    .trending {
      grid-template-columns: 1fr 1fr;
      min-block-size: 100svh;
    }

    .trending--image-left .trending__media {
      order: -1;
    }
  }

  .trending__panel {
    position: relative;
    isolation: isolate;
    display: flex;
    flex-direction: column;
    justify-content: center;
    padding: var(--section-padding-top) clamp(var(--page-margin), 3vw, 4rem) var(--section-padding-bottom);
  }

  /* Phones: half the top and bottom padding */
  @media (max-width: 749px) {
    .trending__panel {
      padding-block: calc(var(--section-padding-top) / 2) calc(var(--section-padding-bottom) / 2);
    }
  }

  .trending__media {
    position: relative;
    min-block-size: 60svh;
  }

  /* No image: the half stays as the raised surface of the scheme (white on light schemes, a 12% text mix on dark ones;
     the placeholder drawing only in the editor) */
  .trending__media--empty {
    background-color: var(--color-surface-raised);
  }

  .trending__media .image,
  .trending__placeholder {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
  }

  /* Image overlay: black at the chosen strength, over the photo */
  .trending__overlay {
    position: absolute;
    inset: 0;
    background-color: #000000;
  }

/* sections/video-banner.liquid */

  /*
    Figma frame 1920 x 1031. --px = one Figma pixel on this screen width, at most 1px; sizes are
    Figma px x --px with rem minimums, so tablets keep readable sizes.
    The section is a one-cell grid: the media and the content layer share the cell (desktop).
    Phones: two rows, the video with the text on it, then the card.
  */
  .video-banner {
    --px: min(calc(100vw / 1920), 0.0625rem);
    --video-banner-height: auto;
    --video-banner-offset: 0px;
    position: relative;
    isolation: isolate;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    grid-template-rows: minmax(var(--video-banner-height), auto);
    overflow: clip;
    background-color: var(--color-background);
  }

  .video-banner--fill {
    --video-banner-height: 100svh;
  }

  .video-banner:not(.video-banner--fill) {
    --video-banner-height: 37.5rem;
  }

  /*
    First section: it slides up under the header pill (header.liquid), so the content moves down by the
    header's height. Also with a transparent header: its buttons still show at the top right, over the
    card. A solid header keeps the section below it: no offset, one screen minus the header.
  */
  body:has(sticky-header):not(:has(.header--solid)) #MainContent > .shopify-section:first-child .video-banner {
    --video-banner-offset: var(--header-space);
  }

  body:has(.header--solid) #MainContent > .shopify-section:first-child .video-banner--fill {
    --video-banner-height: calc(100svh - var(--header-space));
  }

  /* A top announcement bar sits above the section and pushes it down: take its height off (as the hero) */
  body:has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .video-banner--fill {
    --video-banner-height: calc(100svh - var(--announcement-size, 2.25rem));
  }

  body:has(.header--solid):has(.announcement-bar--top:not([hidden]):not(.is-closing)) #MainContent > .shopify-section:first-child .video-banner--fill {
    --video-banner-height: calc(100svh - var(--header-space) - var(--announcement-size, 2.25rem));
  }

  /* ---------- Background ---------- */

  /* Dark under the poster: with no video and no poster the white text still reads */
  .video-banner__media {
    position: relative;
    z-index: -1;
    grid-area: 1 / 1;
    overflow: hidden;
    background-color: #1f1f1f;
  }

  .video-banner__poster,
  .video-banner__video,
  .video-banner__placeholder {
    position: absolute;
    inset: 0;
    inline-size: 100%;
    block-size: 100%;
    object-fit: cover;
  }

  /*
    No video and no poster: a light placeholder in the scheme's colours, no dark overlay or fade, and the
    text in the scheme's text colour (Liquid writes it into --video-banner-text), so the accent word, the
    button and the scroll hint stay readable.
  */
  .video-banner--placeholder .video-banner__media {
    background-color: color-mix(in srgb, var(--color-text) 6%, var(--color-background));
  }

  .video-banner__placeholder {
    fill: color-mix(in srgb, var(--color-text) 16%, transparent);
  }

  .video-banner--placeholder .video-banner__media::after {
    display: none;
  }

  /* The video shows only once it plays (until then, and without JS, the sharp poster shows) */
  .video-banner__video {
    opacity: 0;
  }

  .video-banner.is-video-ready .video-banner__video {
    opacity: 1;
  }

  @media (prefers-reduced-motion: no-preference) {
    .video-banner__video {
      transition: opacity var(--duration-slow, 700ms) var(--ease-out);
    }
  }

  /* Overlay: the whole video darker by "Overlay opacity", plus a fade behind the text (left) */
  .video-banner__media::after {
    content: '';
    position: absolute;
    inset: 0;
    background:
      linear-gradient(90deg, #00000073 0%, #00000000 55%),
      color-mix(in srgb, #000000 var(--video-banner-overlay), transparent);
    pointer-events: none;
  }

  /* ---------- Content layer ---------- */

  .video-banner__inner {
    display: grid;
    grid-area: 1 / 1;
    grid-template-columns: minmax(0, 1fr) auto;
    grid-template-rows: auto 1fr auto;
    grid-template-areas:
      'content card'
      'content .'
      'scroll corner';
    column-gap: var(--space-xl);
    row-gap: var(--space-lg);
    inline-size: 100%;
    max-inline-size: var(--section-width, 100vw);
    margin-inline: auto;
    padding-block:
      calc(max(var(--space-lg), calc(var(--video-banner-pad-top) * var(--px))) + var(--video-banner-offset))
      max(var(--space-md), calc(var(--video-banner-pad-bottom) * var(--px)));
    padding-inline: max(var(--page-margin), calc(52 * var(--px)));
    color: var(--video-banner-text);
  }

  .video-banner__content {
    grid-area: content;
    align-self: center;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: max(var(--space-md), calc(28 * var(--px)));
    max-inline-size: max(22rem, calc(560 * var(--px)));
    padding-block: var(--space-xl);
  }

  /* Eyebrow: uppercase label, then a short line (design: after the text, in the text colour) */
  .video-banner__eyebrow {
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    margin: 0;
    font-size: max(0.75rem, calc(15 * var(--px)));
    font-weight: var(--font-weight-medium);
    letter-spacing: var(--letter-spacing-label);
    line-height: 1.3;
    text-transform: uppercase;
  }

  .video-banner__eyebrow::after {
    content: '';
    flex: none;
    inline-size: max(2.5rem, calc(60 * var(--px)));
    block-size: 1px;
    background-color: currentcolor;
  }

  .video-banner__heading {
    margin: 0;
    color: inherit;
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: max(2.5rem, calc(76 * var(--px)));
    line-height: 1.04;
    text-wrap: balance;
  }

  /* The italic word(s) in the editor: the highlight colour, upright (design "You") */
  .video-banner__heading em {
    color: var(--color-accent);
    font-style: normal;
  }

  .video-banner__text {
    margin: 0;
    max-inline-size: 20em;
    font-size: max(1rem, calc(20 * var(--px)));
    line-height: 1.5;
  }

  .video-banner__button.button {
    gap: var(--space-sm);
    min-block-size: max(3.125rem, calc(60 * var(--px)));
    margin-block-start: max(var(--space-xs), calc(20 * var(--px)));
    padding-inline: max(var(--space-lg), calc(33 * var(--px)));
    font-size: max(0.875rem, calc(17 * var(--px)));
    letter-spacing: 0.12em;
  }

  .video-banner__button svg {
    flex: none;
    inline-size: 1.1em;
    block-size: auto;
  }

  .video-banner__note {
    margin: 0;
    padding: var(--space-xs) var(--space-sm);
    border: 1px dashed currentcolor;
    border-radius: var(--radius-xs);
    font-size: var(--font-size-small);
  }

  /*
    Scroll hint, the Slideshow's look: a 20 x 36 pill with an accent dot, the label under it. The label is in
    the text colour (the accent on a dark video was hard to read); the dot carries the accent.
  */
  .video-banner__scroll {
    grid-area: scroll;
    align-self: end;
    justify-self: start;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: max(0.5rem, calc(10 * var(--px)));
  }

  .video-banner__mouse {
    position: relative;
    flex: none;
    inline-size: 1.25rem;
    block-size: 2.25rem;
    border: 2px solid color-mix(in srgb, currentcolor 75%, transparent);
    border-radius: var(--radius-pill);
  }

  .video-banner__mouse::after {
    content: '';
    position: absolute;
    top: 0.3125rem;
    left: 50%;
    inline-size: 0.375rem;
    aspect-ratio: 1;
    margin-left: -0.1875rem;
    border-radius: 50%;
    background-color: var(--color-accent);
  }

  .video-banner__scroll-text {
    font-size: max(0.6875rem, calc(13 * var(--px)));
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.25em;
    text-transform: uppercase;
    white-space: nowrap;
  }

  /* The dot moves down and fades, then starts again (looping motion: "Enable animations", no reduced motion) */
  @media (prefers-reduced-motion: no-preference) {
    .motion-on .video-banner__mouse::after {
      animation: video-banner-wheel 1.8s var(--ease-out) infinite;
    }
  }

  @keyframes video-banner-wheel {
    0% {
      opacity: 1;
      transform: translateY(0);
    }

    70% {
      opacity: 0;
      transform: translateY(0.875rem);
    }

    100% {
      opacity: 0;
      transform: translateY(0);
    }
  }

  /* Bottom right: line, lotus, italic tagline (two lines), then the video's pause button */
  .video-banner__corner {
    grid-area: corner;
    align-self: end;
    justify-self: end;
    display: flex;
    align-items: center;
    gap: var(--space-md);
  }

  .video-banner__tagline {
    display: flex;
    align-items: center;
    gap: max(0.625rem, calc(14 * var(--px)));
    margin: 0;
    font-size: max(0.9375rem, calc(18 * var(--px)));
    font-style: italic;
    line-height: 1.4;
  }

  .video-banner__tagline::before {
    content: '';
    flex: none;
    inline-size: max(3rem, calc(80 * var(--px)));
    block-size: 1px;
    margin-inline-end: max(0.5rem, calc(12 * var(--px)));
    background-color: currentcolor;
  }

  .video-banner__tagline-icon {
    display: flex;
    flex: none;
  }

  .video-banner__tagline-icon svg {
    inline-size: max(1.25rem, calc(26 * var(--px)));
    block-size: auto;
  }

  .video-banner__tagline-text {
    max-inline-size: 9em;
  }

  /* Pause buttons: round glass (as the hero's), 44px; the card's own is 32px */
  .video-banner__pause {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: 2.75rem;
    block-size: 2.75rem;
    margin: 0;
    padding: 0;
    border: 1px solid #ffffffb3;
    border-radius: var(--radius-pill);
    background-color: var(--color-glass-strong, #ffffff80);
    box-shadow: var(--shadow-header);
    color: #1f1f1f;
    cursor: pointer;
  }

  .video-banner__pause[hidden] {
    display: none;
  }

  .video-banner__pause--small {
    inline-size: 2rem;
    block-size: 2rem;
    border-color: color-mix(in srgb, var(--color-text) 20%, transparent);
    background-color: transparent;
    box-shadow: none;
    color: var(--color-text);
  }

  .video-banner__pause-icon {
    inline-size: 1rem;
    block-size: 1rem;
  }

  .video-banner__pause--small .video-banner__pause-icon {
    inline-size: 0.75rem;
    block-size: 0.75rem;
  }

  .video-banner__pause[aria-pressed='true'] .video-banner__pause-icon--pause,
  .video-banner__pause:not([aria-pressed='true']) .video-banner__pause-icon--play {
    display: none;
  }

  /* ---------- Product card (Figma 389 x 261 at x 1481, y 180) ---------- */

  .video-banner__card-area {
    grid-area: card;
    align-self: start;
    /* Room above the card for the product photo that sticks out */
    padding-block-start: max(1.5rem, calc(28 * var(--px)));
  }

  .video-banner-card {
    --card-image-width: max(4.5rem, calc(96 * var(--px)));
    position: relative;
    display: flex;
    flex-direction: column;
    gap: max(0.375rem, calc(10 * var(--px)));
    inline-size: max(18rem, calc(389 * var(--px)));
    padding: max(1.125rem, calc(29 * var(--px)));
    border: 1px solid #ffffff99;
    border-radius: max(1rem, calc(24 * var(--px)));
    background-color: color-mix(in srgb, var(--color-background) 86%, transparent);
    box-shadow: var(--glass-shadow, 0 4px 15px 0 #b9b9b940), var(--glass-rim, inset 0 1px 0 #ffffffcc);
    color: var(--color-text);
  }

  /* Hover and focus: a touch more solid */
  .video-banner-card:has(.video-banner-card__link:hover) {
    background-color: color-mix(in srgb, var(--color-background) 94%, transparent);
  }

  .video-banner-card__top {
    position: relative;
    z-index: 2;
    display: flex;
    align-items: center;
    gap: var(--space-sm);
    padding-inline-end: calc(var(--card-image-width) + var(--space-sm));
  }

  .video-banner-card__counter {
    margin: 0;
    font-size: max(0.8125rem, calc(16 * var(--px)));
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.04em;
  }

  /* The products share one grid cell: the card is as tall as the tallest one */
  .video-banner-card__list {
    display: grid;
    margin: 0;
    padding: 0;
    list-style: none;
  }

  .video-banner-card__item {
    display: flex;
    flex-direction: column;
    gap: max(0.375rem, calc(10 * var(--px)));
    grid-area: 1 / 1;
  }

  .video-banner-card__item:not(.is-active) {
    visibility: hidden;
    opacity: 0;
  }

  @media (prefers-reduced-motion: no-preference) {
    .video-banner-card__item {
      transition:
        opacity 0.6s var(--ease-out),
        visibility 0s linear 0s;
    }

    .video-banner-card__item:not(.is-active) {
      transition:
        opacity 0.6s var(--ease-out),
        visibility 0s linear 0.6s;
    }
  }

  /*
    Product photo: top right, out over the card's top edge (containing block = the card). Each card block sets
    "Image size" (--card-image-scale), "Image rotation" (--card-image-rotate) and the two moves (--card-image-x /
    -y, translate in % of the photo's own box, so a move keeps its look at every size); the title and label
    keep clear of the photo's width (not of a move).
  */
  .video-banner-card__item {
    --card-image-size: calc(var(--card-image-width) * var(--card-image-scale, 1));
  }

  .video-banner-card__media {
    position: absolute;
    inset-block-start: calc(max(1.5rem, calc(28 * var(--px))) * -1);
    inset-inline-end: max(0.875rem, calc(25 * var(--px)));
    inline-size: var(--card-image-size);
    aspect-ratio: 2 / 3;
    translate: var(--card-image-x, 0%) var(--card-image-y, 0%);
    rotate: var(--card-image-rotate, 0deg);
    pointer-events: none;
  }

  .video-banner-card__media img,
  .video-banner-card__placeholder {
    inline-size: 100%;
    block-size: 100%;
    object-fit: contain;
    filter: drop-shadow(0 6px 10px #00000026);
  }

  .video-banner-card__title,
  .video-banner-card__type {
    padding-inline-end: calc(var(--card-image-size) + var(--space-sm));
  }

  .video-banner-card__title {
    margin: 0;
    font-family: var(--font-heading--family);
    font-style: var(--font-heading--style);
    font-weight: var(--font-heading--weight);
    font-size: max(1.25rem, calc(26 * var(--px)));
    line-height: 1.2;
  }

  .video-banner-card__link {
    color: inherit;
    text-decoration: none;
  }

  /* The title link covers the whole card (one link per product, no nested links) */
  .video-banner-card__link::after {
    content: '';
    position: absolute;
    inset: 0;
    z-index: 1;
    border-radius: inherit;
  }

  .video-banner-card__link:focus-visible {
    outline: none;
  }

  .video-banner-card:has(.video-banner-card__link:focus-visible) {
    outline: 2px solid var(--color-accent);
    outline-offset: 3px;
  }

  .video-banner-card__type {
    margin: 0;
    color: var(--color-accent);
    font-size: max(0.6875rem, calc(14 * var(--px)));
    font-weight: var(--font-weight-medium);
    letter-spacing: 0.2em;
    text-transform: uppercase;
  }

  .video-banner-card__text {
    margin: 0;
    margin-block-start: max(0.25rem, calc(14 * var(--px)));
    font-size: max(0.9375rem, calc(19 * var(--px)));
    line-height: 1.4;
  }

  /* Theme editor only: an empty Product card block (or none) */
  .video-banner-card__item--empty .video-banner-card__text {
    font-size: var(--font-size-small);
    font-style: italic;
    opacity: 0.8;
  }

  .video-banner-card__item--empty .video-banner-card__placeholder {
    fill: color-mix(in srgb, var(--color-text) 25%, transparent);
  }

  .video-banner-card__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-sm);
    margin-block-start: max(0.375rem, calc(14 * var(--px)));
  }

  .video-banner-card__footer .price {
    font-size: max(1.25rem, calc(30 * var(--px)));
    gap: 0 var(--space-sm);
  }

  .video-banner-card__footer .price__current {
    color: var(--color-text);
    font-weight: 400;
  }

  .video-banner-card__footer .price__compare {
    font-size: 0.67em;
  }

  .video-banner-card__arrow {
    display: grid;
    flex: none;
    place-items: center;
    inline-size: max(2rem, calc(36 * var(--px)));
    block-size: max(2rem, calc(36 * var(--px)));
    border-radius: var(--radius-pill);
    background-color: #ffffff99;
    box-shadow: var(--glass-rim, inset 0 1px 0 #ffffffcc);
    color: var(--color-accent);
  }

  .video-banner-card__arrow svg {
    inline-size: 45%;
    block-size: auto;
  }

  @media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .video-banner-card__arrow {
      transition: transform var(--duration-fast, 150ms) var(--ease-out);
    }

    .video-banner-card:has(.video-banner-card__link:hover) .video-banner-card__arrow {
      transform: translateX(3px);
    }
  }

  /* ---------- Tablets (750–1199px): the desktop layout; optional card under the text ---------- */
  @media (min-width: 750px) and (max-width: 1199px) {
    .video-banner--tablet-card-below .video-banner__inner {
      grid-template-columns: minmax(0, 1fr) auto;
      grid-template-rows: 1fr auto auto;
      grid-template-areas:
        'content content'
        'card .'
        'scroll corner';
    }

    .video-banner--tablet-card-below .video-banner__card-area {
      padding-block-end: var(--space-md);
    }
  }

  /* ---------- Phones (below 750px) ---------- */
  @media (max-width: 749px) {
    .video-banner {
      grid-template-rows: minmax(var(--video-banner-height), auto) auto;
    }

    .video-banner:not(.video-banner--fill) {
      --video-banner-height: 32rem;
    }

    /* Stronger fade from the bottom, behind the text */
    .video-banner__media::after {
      background:
        linear-gradient(0deg, #000000bf 0%, #00000066 45%, #00000000 75%),
        color-mix(in srgb, #000000 var(--video-banner-overlay), transparent);
    }

    /* The layer's parts become the section's grid items: text on the video, the card under it */
    .video-banner__inner {
      display: contents;
    }

    .video-banner__content {
      grid-area: 1 / 1;
      align-self: end;
      gap: var(--space-md);
      max-inline-size: none;
      padding-block:
        calc(var(--space-2xl) + var(--video-banner-offset))
        max(var(--space-xl), calc(var(--video-banner-pad-bottom) * var(--px)));
      padding-inline: var(--page-margin) calc(var(--page-margin) + 3.25rem);
      color: var(--video-banner-text);
    }

    .video-banner__heading {
      font-size: clamp(2.125rem, 10vw, 2.75rem);
    }

    .video-banner__text {
      font-size: 0.9375rem;
    }

    .video-banner__eyebrow {
      font-size: 0.6875rem;
    }

    .video-banner__button.button {
      min-block-size: 2.875rem;
      margin-block-start: var(--space-xs);
      padding-inline: var(--space-lg);
      font-size: 0.875rem;
    }

    .video-banner__scroll,
    .video-banner__tagline {
      display: none;
    }

    /* The video's pause button: bottom right of the video, beside the text's last row */
    .video-banner__corner {
      grid-area: 1 / 1;
      align-self: end;
      justify-self: end;
      padding-block-end: max(var(--space-xl), calc(var(--video-banner-pad-bottom) * var(--px)));
      padding-inline-end: var(--page-margin);
    }

    .video-banner__card-area {
      grid-area: 2 / 1;
      justify-self: stretch;
      padding: var(--space-2xl) var(--page-margin) var(--space-xl);
    }

    .video-banner--no-phone-card .video-banner__card-area {
      display: none;
    }

    .video-banner-card {
      --card-image-width: 4.25rem;
      inline-size: 100%;
      max-inline-size: 26rem;
      margin-inline: auto;
      padding: var(--space-md) var(--space-md) var(--space-md) 1.125rem;
      border-color: color-mix(in srgb, var(--color-text) 8%, transparent);
      background-color: var(--color-surface-raised, #ffffff);
    }

    .video-banner-card:has(.video-banner-card__link:hover) {
      background-color: var(--color-surface-raised, #ffffff);
    }

    .video-banner-card__media {
      inset-block-start: -1.25rem;
    }

    .video-banner-card__title {
      font-size: 1.125rem;
    }

    .video-banner-card__text {
      margin-block-start: 0;
      font-size: 0.8125rem;
    }

    .video-banner-card__footer .price {
      font-size: 1.125rem;
    }
  }
